# ===== 3. FIX CONSOLE ENCODING (Windows) =====
def fix_console_encoding():
    """Fix console encoding for Windows to handle Unicode characters."""
    if sys.platform != 'win32':
        return
    
    try:
        # Python 3.7+ - use reconfigure (doesn't close the stream)
        sys.stdout.reconfigure(encoding='utf-8', errors='replace')
        sys.stderr.reconfigure(encoding='utf-8', errors='replace')
        print("✅ Console reconfigured to UTF-8")
        return
    except AttributeError:
        pass
    
    # Fallback for older Python versions
    try:
        sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')
        sys.stderr = io.TextIOWrapper(sys.stderr.buffer, encoding='utf-8', errors='replace')
        sys.stdin = io.TextIOWrapper(sys.stdin.buffer, encoding='utf-8', errors='replace')
        print("✅ Console wrapped with UTF-8")
    except Exception as e:
        print(f"⚠️ Could not reconfigure console: {e}")

fix_console_encoding()

