# ===== 5. CONFIGURE LOGGING ONCE =====
class SafeStreamHandler(logging.StreamHandler):
    """Stream handler that handles Unicode and I/O errors gracefully."""
    
    def __init__(self, stream=None):
        if stream is None:
            stream = sys.stdout
        super().__init__(stream)
    
    def emit(self, record):
        try:
            msg = self.format(record)
            stream = self.stream
            stream.write(msg + self.terminator)
            self.flush()
        except (UnicodeEncodeError, UnicodeError):
            # Fallback: encode with replacement
            try:
                msg = self.format(record).encode('ascii', 'replace').decode('ascii')
                self.stream.write(msg + self.terminator)
                self.flush()
            except Exception:
                self.handleError(record)
        except (ValueError, OSError, AttributeError):
            # Suppress I/O errors during shutdown
            pass
        except Exception:
            self.handleError(record)

def setup_logging():
    """Setup logging once with proper handlers."""
    root_logger = logging.getLogger()
    
    # Remove all existing handlers
    for handler in root_logger.handlers[:]:
        root_logger.removeHandler(handler)
    
    # Create formatter
    formatter = logging.Formatter(
        '%(asctime)s - %(name)s - %(levelname)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )
    
    # Console handler (using safe handler)
    console_handler = SafeStreamHandler(sys.stdout)
    console_handler.setFormatter(formatter)
    root_logger.addHandler(console_handler)
    
    # File handler (optional)
    try:
        file_handler = logging.FileHandler('safetytrack.log', encoding='utf-8')
        file_handler.setFormatter(formatter)
        root_logger.addHandler(file_handler)
    except Exception:
        pass
    
    root_logger.setLevel(logging.INFO)
    
    return root_logger

# Setup logging ONCE
logger = setup_logging()

