# ==================== HELPER FUNCTIONS ====================

def allowed_file(filename, allowed_extensions=None):
    """
    Check if file extension is allowed
    
    Args:
        filename: The filename to check
        allowed_extensions: Custom allowed extensions (defaults to INCIDENT_ALLOWED_EXTENSIONS)
    
    Returns:
        bool: True if allowed, False otherwise
    """
    if allowed_extensions is None:
        allowed_extensions = INCIDENT_ALLOWED_EXTENSIONS
    
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in allowed_extensions

def allowed_profile_file(filename):
    """Check if profile image extension is allowed"""
    return allowed_file(filename, PROFILE_ALLOWED_EXTENSIONS)

def allowed_signature_file(filename):
    """Check if signature image extension is allowed"""
    return allowed_file(filename, SIGNATURE_ALLOWED_EXTENSIONS)

def get_file_size_limit(file_type='incident'):
    """
    Get max file size for different file types
    
    Args:
        file_type: 'incident', 'profile', 'signature'
    
    Returns:
        int: Max file size in bytes
    """
    limits = {
        'incident': INCIDENT_MAX_FILE_SIZE,
        'profile': PROFILE_MAX_FILE_SIZE,
        'signature': SIGNATURE_MAX_FILE_SIZE
    }
    return limits.get(file_type, INCIDENT_MAX_FILE_SIZE)

def get_upload_folder(file_type='incident'):
    """
    Get upload folder for different file types
    
    Args:
        file_type: 'incident', 'profile', 'signature', 'template', etc.
    
    Returns:
        str: Upload folder path
    """
    folders = {
        'incident': UPLOAD_FOLDER,
        'profile': PROFILE_UPLOAD_FOLDER,
        'signature': SIGNATURE_UPLOAD_FOLDER,
        'template': TEMPLATE_FOLDER,
        'models': MODELS_DIR
    }
    return folders.get(file_type, UPLOAD_FOLDER)

def ensure_upload_directories():
    """Create all upload directories if they don't exist"""
    all_dirs = list(UPLOAD_DIRS.values()) + [
        MODELS_DIR,
        PROFILE_UPLOAD_FOLDER,
        SIGNATURE_UPLOAD_FOLDER,
        TEMPLATE_FOLDER
    ]
    
    for folder in all_dirs:
        os.makedirs(folder, exist_ok=True)
        print(f"✅ Ensured directory exists: {folder}")

# ==================== CREATE DIRECTORIES ON STARTUP ====================

