# ===== ADVANCED COMPUTER VISION SYSTEM CLASS =====

class AdvancedComputerVisionSystem:
    def __init__(self, yolov5_path: str = None):
        """
        Initialize Computer Vision System with a SINGLE YOLO model.
        
        The model must be manually uploaded to the Railway volume at:
            /app/data/yolov8n.pt
        
        No model downloads, no YOLOv5 cloning, no other models loaded.
        """
        self.models = {}
        self.active_monitors = {}
        self.yolov5_available = False
        self.opencv_available = True

        # Keep path for compatibility only
        self.yolov5_path = yolov5_path

        self.violation_thresholds = {
            'no_mask': 0.7,
            'no_gloves': 0.6,
            'no_helmet': 0.8,
            'no_safety_vest': 0.7,
            'unsafe_posture': 0.5
        }

        # Upload directories
        self.UPLOAD_DIRS = {
            'temp': 'temp_uploads',
            'violations': 'violation_uploads'
        }
        self._ensure_directories()

        # ✅ Load ONLY the single YOLO model
        self._load_single_model()

    def _ensure_directories(self):
        """Ensure required directories exist"""
        for directory in self.UPLOAD_DIRS.values():
            os.makedirs(directory, exist_ok=True)

    def _load_single_model(self):
        """
        Load the single YOLO model from the Railway volume.
        Skips silently if the model isn't present (uses OpenCV fallback).
        """
        volume_path = os.environ.get("RAILWAY_VOLUME_MOUNT_PATH", "/app/data")
        model_path = os.path.join(volume_path, "yolov8n.pt")

        if not os.path.exists(model_path):
            logger.warning(f"YOLO model not found at {model_path}, using OpenCV fallback")
            self.yolov5_available = False
            return

        try:
            from ultralytics import YOLO
            logger.info(f"Loading YOLO model from: {model_path}")
            model = YOLO(model_path)
            self.models['general'] = {
                'model': model,
                'classes': list(model.names.values()) if hasattr(model, 'names') else ['person'],
                'confidence': 0.5
            }
            self.yolov5_available = True
            logger.info("✅ YOLO model loaded successfully")
        except Exception as e:
            logger.error(f"Failed to load YOLO model: {e}")
            self.yolov5_available = False

    # ============================================================
    # Detection
    # ============================================================

    def detect_safety_violations(self, image_path: str, industry: str = 'healthcare', context: Dict = None) -> Dict:
        """Detect violations using the single YOLO model, or fallback to OpenCV."""
        if not self.yolov5_available:
            return self._fallback_violation_detection(image_path, industry)

        try:
            config = self.models.get('general')
            if not config or config['model'] is None:
                return self._fallback_violation_detection(image_path, industry)

            model = config['model']
            model.conf = config['confidence']

            results = model(image_path)
            predictions = results[0].boxes if hasattr(results[0], 'boxes') else None

            violations = []
            detections = []
            compliance_score = 100

            if predictions is not None:
                for box in predictions:
                    cls_id = int(box.cls[0])
                    confidence = float(box.conf[0])
                    xyxy = box.xyxy[0].tolist()
                    class_name = model.names.get(cls_id, f'class_{cls_id}')

                    if class_name.startswith('no_') and confidence > self.violation_thresholds.get(class_name, 0.5):
                        violations.append({
                            'type': class_name,
                            'confidence': confidence,
                            'bbox': xyxy,
                            'industry': industry
                        })
                        compliance_score -= 20

                    detections.append({
                        'class': class_name,
                        'confidence': confidence,
                        'bbox': xyxy
                    })

            compliance_score = max(0, compliance_score)

            return {
                'violations': violations,
                'detections': detections,
                'violation_count': len(violations),
                'compliance_score': compliance_score,
                'risk_level': self._calculate_risk_level(violations, industry, context),
                'model_used': 'yolov8n',
                'timestamp': datetime.utcnow().isoformat()
            }

        except Exception as e:
            logger.error(f"YOLO detection failed: {e}")
            return self._fallback_violation_detection(image_path, industry)

    # ============================================================
    # OpenCV Fallback Detection (unchanged — keeps working)
    # ============================================================

    def _fallback_violation_detection(self, image_path: str, industry: str) -> Dict:
        """Advanced fallback using OpenCV when YOLO is unavailable"""
        try:
            image = cv2.imread(image_path)
            if image is None:
                return {'error': 'Could not load image'}

            height, width = image.shape[:2]
            if height == 0 or width == 0:
                return {'error': 'Invalid image dimensions'}

            violations = []
            detections = []
            confidence_scores = []

            hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
            gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
            gray = cv2.medianBlur(gray, 5)
            clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
            gray = clahe.apply(gray)

            analysis_results = self._perform_comprehensive_analysis(image, gray, hsv, industry)
            violations.extend(analysis_results['violations'])
            detections.extend(analysis_results['detections'])
            confidence_scores.extend(analysis_results['confidence_scores'])

            person_detections = self._detect_persons(image, gray)
            detections.extend(person_detections)

            if person_detections:
                person_violations = self._analyze_persons_for_violations(
                    image, hsv, gray, person_detections, industry
                )
                violations.extend(person_violations)

            compliance_score = self._calculate_compliance_score(violations, detections)
            risk_level = self._calculate_risk_level(violations, industry)

            return {
                'violations': violations,
                'detections': detections,
                'violation_count': len(violations),
                'compliance_score': compliance_score,
                'risk_level': risk_level,
                'model_used': 'opencv_fallback',
                'analysis_metrics': {
                    'person_count': len(person_detections),
                    'image_quality_score': self._assess_image_quality(gray),
                    'lighting_condition': self._assess_lighting_condition(gray),
                    'detection_confidence_avg': np.mean(confidence_scores) if confidence_scores else 0.5
                },
                'timestamp': datetime.utcnow().isoformat(),
                'notes': 'Using OpenCV fallback detection'
            }

        except Exception as e:
            logger.error(f"Fallback detection error: {e}")
            return self._minimal_fallback_detection(image_path, e)

    # ============================================================
    # Stub methods (kept for compatibility — all disabled)
    # ============================================================

    def _download_yolov5_repository(self):
        logger.info("YOLOv5 repository download is disabled.")
        return False

    def _download_model_weights(self, model_name, url):
        logger.info(f"Model download disabled for {model_name}.")
        return None

    def _download_all_models(self):
        logger.info("Model downloads are disabled.")
        return {}

    def load_models(self):
        """No-op — model is loaded in __init__"""
        logger.info("load_models() is a no-op in this build.")

    def activate_yolov5(self) -> bool:
        return self.yolov5_available

    def _load_yolov5_models(self):
        logger.info("YOLOv5 multi-model loading is disabled.")
        return

    def _fallback_to_torch_hub(self):
        logger.info("torch.hub fallback is disabled.")
        self.yolov5_available = False

    def verify_model_downloads(self):
        logger.info("Model verification is disabled.")
        return self.yolov5_available


    def _perform_comprehensive_analysis(self, image, gray, hsv, industry):
        """Perform comprehensive image analysis for safety violations"""
        violations = []
        detections = []
        confidence_scores = []
        
        # 1. Edge and contour analysis
        edge_analysis = self._analyze_edges_and_contours(gray, image.shape)
        violations.extend(edge_analysis['violations'])
        detections.extend(edge_analysis['detections'])
        confidence_scores.extend(edge_analysis['confidences'])
        
        # 2. Color-based safety equipment detection
        color_analysis = self._color_based_safety_detection(hsv, image, industry)
        violations.extend(color_analysis['violations'])
        detections.extend(color_analysis['detections'])
        confidence_scores.extend(color_analysis['confidences'])
        
        # 3. Texture and pattern analysis
        texture_analysis = self._texture_pattern_analysis(gray, industry)
        violations.extend(texture_analysis['violations'])
        detections.extend(texture_analysis['detections'])
        confidence_scores.extend(texture_analysis['confidences'])
        
        # 4. Motion blur detection (for video frames)
        blur_analysis = self._detect_motion_blur(gray)
        if blur_analysis.get('is_blurry', False):
            violations.append({
                'type': 'image_quality_issue',
                'confidence': 0.7,
                'reason': 'High motion blur may affect detection accuracy',
                'severity': 'low'
            })
        
        return {
            'violations': violations,
            'detections': detections,
            'confidence_scores': confidence_scores
        }

    def _analyze_edges_and_contours(self, gray, image_shape):
        """Analyze edges and contours for potential safety equipment"""
        violations = []
        detections = []
        confidences = []
        
        height, width = image_shape[:2]
        area = height * width
        
        # Multi-scale edge detection
        edges_fine = cv2.Canny(gray, 50, 150)
        edges_coarse = cv2.Canny(gray, 100, 200)
        
        edge_density_fine = np.sum(edges_fine > 0) / area
        edge_density_coarse = np.sum(edges_coarse > 0) / area
        
        # Detect contours for shape analysis
        contours, _ = cv2.findContours(edges_coarse, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        
        # Analyze contours for potential safety equipment
        for contour in contours:
            if len(contour) >= 5:
                area_contour = cv2.contourArea(contour)
                
                # Filter by size (avoid noise)
                if area_contour < 100 or area_contour > area * 0.1:
                    continue
                    
                # Shape analysis
                hull = cv2.convexHull(contour)
                hull_area = cv2.contourArea(hull)
                solidity = area_contour / hull_area if hull_area > 0 else 0
                
                # Aspect ratio
                x, y, w, h = cv2.boundingRect(contour)
                aspect_ratio = w / h if h > 0 else 0
                
                # Detect potential helmets (circular/oval shapes)
                if 0.8 <= solidity <= 1.2 and 0.7 <= aspect_ratio <= 1.3:
                    detections.append({
                        'class': 'potential_helmet',
                        'confidence': 0.4,
                        'bbox': [x, y, x+w, y+h],
                        'reason': 'Circular contour detected'
                    })
                    confidences.append(0.4)
        
        # Edge density analysis for PPE detection
        if edge_density_fine < 0.005:
            violations.append({
                'type': 'possible_ppe_missing',
                'confidence': 0.6,
                'reason': 'Very low image detail may indicate missing safety equipment',
                'severity': 'medium'
            })
            confidences.append(0.6)
        
        return {
            'violations': violations,
            'detections': detections,
            'confidences': confidences
        }

    def _color_based_safety_detection(self, hsv, image, industry):
        """Detect safety equipment based on color analysis"""
        violations = []
        detections = []
        confidences = []
        
        # Define color ranges for different safety equipment
        color_ranges = {
            'safety_vest': {
                'orange': [(10, 100, 100), (25, 255, 255)],
                'yellow': [(25, 100, 100), (35, 255, 255)],
                'red': [(0, 100, 100), (10, 255, 255), (170, 100, 100), (180, 255, 255)]
            },
            'helmet': {
                'white': [(0, 0, 200), (180, 30, 255)],
                'yellow': [(25, 100, 100), (35, 255, 255)],
                'blue': [(100, 100, 100), (130, 255, 255)]
            }
        }
        
        total_pixels = hsv.shape[0] * hsv.shape[1]
        
        for equipment, colors in color_ranges.items():
            equipment_pixels = 0
            
            for color_name, ranges in colors.items():
                if len(ranges) == 2:
                    lower, upper = ranges
                    mask = cv2.inRange(hsv, np.array(lower), np.array(upper))
                else:
                    lower1, upper1, lower2, upper2 = ranges
                    mask1 = cv2.inRange(hsv, np.array(lower1), np.array(upper1))
                    mask2 = cv2.inRange(hsv, np.array(lower2), np.array(upper2))
                    mask = mask1 + mask2
                
                equipment_pixels += np.sum(mask > 0)
                
                # Detect significant color blobs
                contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
                for contour in contours:
                    if cv2.contourArea(contour) > 1000:
                        x, y, w, h = cv2.boundingRect(contour)
                        confidence = min(0.7, cv2.contourArea(contour) / 5000)
                        
                        detections.append({
                            'class': f'potential_{equipment}',
                            'confidence': confidence,
                            'bbox': [x, y, x+w, y+h],
                            'color': color_name,
                            'reason': f'Large {color_name} area detected'
                        })
                        confidences.append(confidence)
            
            # Check if safety equipment colors are insufficient
            color_ratio = equipment_pixels / total_pixels
            threshold = 0.01 if equipment == 'safety_vest' else 0.005
            
            if color_ratio < threshold and industry in ['construction', 'manufacturing']:
                violations.append({
                    'type': f'possible_{equipment}_missing',
                    'confidence': 0.5,
                    'reason': f'Insufficient {equipment} color detected',
                    'severity': 'medium'
                })
                confidences.append(0.5)
        
        return {
            'violations': violations,
            'detections': detections,
            'confidences': confidences
        }

    def _detect_persons(self, image, gray):
        """Detect persons using multiple methods"""
        detections = []
        
        try:
            # Method 1: Haar Cascade for person detection
            cascade_path = cv2.data.haarcascades + 'haarcascade_fullbody.xml'
            if os.path.exists(cascade_path):
                person_cascade = cv2.CascadeClassifier(cascade_path)
                persons = person_cascade.detectMultiScale(
                    gray, 
                    scaleFactor=1.1, 
                    minNeighbors=5, 
                    minSize=(30, 30)
                )
                
                for (x, y, w, h) in persons:
                    detections.append({
                        'class': 'person',
                        'confidence': 0.6,
                        'bbox': [x, y, x+w, y+h],
                        'method': 'haar_cascade'
                    })
            
            # Method 2: HOG Descriptor with SVM (more accurate)
            try:
                hog = cv2.HOGDescriptor()
                hog.setSVMDetector(cv2.HOGDescriptor_getDefaultPeopleDetector())
                
                persons, weights = hog.detectMultiScale(
                    gray,
                    winStride=(8, 8),
                    padding=(32, 32),
                    scale=1.05,
                    hitThreshold=0.5
                )
                
                for i, (x, y, w, h) in enumerate(persons):
                    confidence = min(0.9, weights[i][0] if len(weights) > i else 0.7)
                    detections.append({
                        'class': 'person',
                        'confidence': float(confidence),
                        'bbox': [x, y, x+w, y+h],
                        'method': 'hog_svm'
                    })
                    
            except Exception as e:
                logger.warning(f"HOG person detection failed: {e}")
        
        except Exception as e:
            logger.warning(f"Person detection failed: {e}")
        
        return detections

    def _analyze_persons_for_violations(self, image, hsv, gray, person_detections, industry):
        """Analyze detected persons for safety violations"""
        violations = []
        
        for person in person_detections:
            if person['class'] == 'person':
                bbox = person['bbox']
                x1, y1, x2, y2 = bbox
                
                # Extract person region
                person_region = image[y1:y2, x1:x2]
                person_hsv = hsv[y1:y2, x1:x2]
                
                if person_region.size == 0:
                    continue
                
                # Analyze head region for helmet
                head_analysis = self._analyze_head_region(person_region, person_hsv, industry)
                if head_analysis:
                    violations.extend(head_analysis)
                
                # Analyze torso region for safety vest
                vest_analysis = self._analyze_torso_region(person_region, person_hsv, industry)
                if vest_analysis:
                    violations.extend(vest_analysis)
        
        return violations

    def _analyze_head_region(self, person_region, person_hsv, industry):
        """Analyze head region for helmet detection"""
        violations = []
        
        height, width = person_region.shape[:2]
        head_height = int(height * 0.2)
        
        if head_height > 0:
            head_region = person_region[0:head_height, :]
            head_hsv = person_hsv[0:head_height, :]
            
            if head_region.size > 0:
                # Look for helmet colors
                helmet_colors = [
                    ((0, 0, 200), (180, 30, 255)),
                    ((25, 100, 100), (35, 255, 255)),
                    ((100, 100, 100), (130, 255, 255))
                ]
                
                helmet_pixels = 0
                total_head_pixels = head_region.shape[0] * head_region.shape[1]
                
                for lower, upper in helmet_colors:
                    mask = cv2.inRange(head_hsv, np.array(lower), np.array(upper))
                    helmet_pixels += np.sum(mask > 0)
                
                helmet_ratio = helmet_pixels / total_head_pixels if total_head_pixels > 0 else 0
                
                if helmet_ratio < 0.1 and industry in ['construction', 'manufacturing']:
                    violations.append({
                        'type': 'no_helmet',
                        'confidence': 0.6,
                        'reason': 'Insufficient helmet color in head region',
                        'severity': 'high',
                        'location': 'head_region'
                    })
        
        return violations

    def _analyze_torso_region(self, person_region, person_hsv, industry):
        """Analyze torso region for safety vest detection"""
        violations = []
        
        height, width = person_region.shape[:2]
        torso_start = int(height * 0.2)
        torso_end = int(height * 0.7)
        torso_height = torso_end - torso_start
        
        if torso_height > 0:
            torso_region = person_region[torso_start:torso_end, :]
            torso_hsv = person_hsv[torso_start:torso_end, :]
            
            if torso_region.size > 0:
                # Look for safety vest colors
                vest_colors = [
                    ((10, 100, 100), (25, 255, 255)),
                    ((25, 100, 100), (35, 255, 255)),
                    ((0, 100, 100), (10, 255, 255)),
                    ((170, 100, 100), (180, 255, 255))
                ]
                
                vest_pixels = 0
                total_torso_pixels = torso_region.shape[0] * torso_region.shape[1]
                
                for lower, upper in vest_colors:
                    mask = cv2.inRange(torso_hsv, np.array(lower), np.array(upper))
                    vest_pixels += np.sum(mask > 0)
                
                vest_ratio = vest_pixels / total_torso_pixels if total_torso_pixels > 0 else 0
                
                if vest_ratio < 0.15 and industry in ['construction', 'oil_gas']:
                    violations.append({
                        'type': 'no_safety_vest',
                        'confidence': 0.55,
                        'reason': 'Insufficient safety vest color in torso region',
                        'severity': 'high',
                        'location': 'torso_region'
                    })
        
        return violations

    def _texture_pattern_analysis(self, gray, industry):
        """Analyze texture patterns for specific safety equipment"""
        violations = []
        detections = []
        confidences = []
        
        try:
            laplacian_var = cv2.Laplacian(gray, cv2.CV_64F).var()
            
            if laplacian_var < 100:
                violations.append({
                    'type': 'image_quality_issue',
                    'confidence': 0.4,
                    'reason': 'Low texture variance may affect equipment detection',
                    'severity': 'low'
                })
                confidences.append(0.4)
                
        except Exception as e:
            logger.warning(f"Texture analysis failed: {e}")
        
        return {
            'violations': violations,
            'detections': detections,
            'confidences': confidences
        }

    def _detect_motion_blur(self, gray):
        """Detect motion blur in the image"""
        try:
            laplacian_var = cv2.Laplacian(gray, cv2.CV_64F).var()
            
            return {
                'is_blurry': laplacian_var < 50,
                'blur_score': laplacian_var,
                'confidence': 0.7
            }
        except:
            return {'is_blurry': False, 'blur_score': 0, 'confidence': 0}

    def _assess_image_quality(self, gray):
        """Assess overall image quality"""
        try:
            laplacian_var = cv2.Laplacian(gray, cv2.CV_64F).var()
            brightness = np.mean(gray)
            contrast = np.std(gray)
            
            quality_score = min(100, (laplacian_var / 10 + brightness / 2.55 + contrast) / 3)
            return max(0, quality_score)
        except:
            return 50

    def _assess_lighting_condition(self, gray):
        """Assess lighting conditions"""
        try:
            brightness = np.mean(gray)
            if brightness < 50:
                return 'dark'
            elif brightness > 200:
                return 'bright'
            else:
                return 'normal'
        except:
            return 'unknown'

    def _calculate_compliance_score(self, violations, detections):
        """Calculate comprehensive compliance score"""
        base_score = 100
        
        for violation in violations:
            severity_weights = {
                'low': 5,
                'medium': 15,
                'high': 25,
                'critical': 40
            }
            
            severity = violation.get('severity', 'medium')
            confidence = violation.get('confidence', 0.5)
            
            deduction = severity_weights.get(severity, 15) * confidence
            base_score -= deduction
        
        safety_equipment_count = sum(1 for d in detections if 'potential_' in d.get('class', ''))
        base_score += min(10, safety_equipment_count * 2)
        
        return max(0, min(100, base_score))

    def _calculate_risk_level(self, violations: List[Dict], industry: str = 'healthcare', context: Dict = None) -> str:
        """Advanced risk level calculation considering multiple factors"""
        try:
            if not violations:
                return "Low"
            
            risk_score = 0
            
            severity_weights = {
                'no_helmet': {'construction': 8, 'manufacturing': 7, 'oil_gas': 9, 'default': 6},
                'no_safety_vest': {'construction': 7, 'oil_gas': 8, 'default': 5},
                'no_gloves': {'healthcare': 6, 'manufacturing': 5, 'default': 4},
                'no_mask': {'healthcare': 8, 'default': 5},
                'no_gown': {'healthcare': 7, 'default': 4},
                'no_face_shield': {'healthcare': 6, 'manufacturing': 5, 'default': 4},
                'unsafe_posture': {'construction': 5, 'manufacturing': 4, 'default': 3},
                'unauthorized_access': {'default': 6},
                'equipment_misuse': {'manufacturing': 7, 'construction': 6, 'default': 5},
                'possible_ppe_missing': {'default': 3}
            }
            
            confidence_multiplier = {
                'high': 1.0,
                'medium': 0.7,
                'low': 0.4
            }
            
            temporal_penalty = 1.0
            if context and context.get('recent_violations_count', 0) > 0:
                temporal_penalty += min(0.5, context['recent_violations_count'] * 0.1)
            
            environmental_penalty = 1.0
            if context and context.get('lighting_condition') == 'dark':
                environmental_penalty += 0.3
            if context and context.get('weather_condition') in ['rain', 'snow', 'fog']:
                environmental_penalty += 0.2
            
            for violation in violations:
                violation_type = violation.get('type', 'unknown')
                confidence = violation.get('confidence', 0.5)
                
                type_weights = severity_weights.get(violation_type, {'default': 4})
                base_weight = type_weights.get(industry, type_weights['default'])
                
                if confidence >= 0.8:
                    conf_level = 'high'
                elif confidence >= 0.5:
                    conf_level = 'medium'
                else:
                    conf_level = 'low'
                
                conf_multiplier = confidence_multiplier.get(conf_level, 0.7)
                
                violation_score = base_weight * conf_multiplier
                risk_score += violation_score
            
            risk_score = risk_score * temporal_penalty * environmental_penalty
            
            if len(violations) > 1:
                multiple_penalty = 1.0 + (min(1.0, (len(violations) - 1) * 0.2))
                risk_score *= multiple_penalty
            
            industry_thresholds = {
                'healthcare': {'low': 5, 'medium': 12, 'high': 20, 'critical': 30},
                'construction': {'low': 8, 'medium': 18, 'high': 30, 'critical': 45},
                'manufacturing': {'low': 6, 'medium': 15, 'high': 25, 'critical': 40},
                'oil_gas': {'low': 10, 'medium': 22, 'high': 35, 'critical': 50},
                'default': {'low': 5, 'medium': 12, 'high': 20, 'critical': 30}
            }
            
            thresholds = industry_thresholds.get(industry, industry_thresholds['default'])
            
            if risk_score >= thresholds['critical']:
                return "Critical"
            elif risk_score >= thresholds['high']:
                return "High"
            elif risk_score >= thresholds['medium']:
                return "Medium"
            else:
                return "Low"
                
        except Exception as e:
            logger.error(f"Risk calculation error: {e}")
            violation_count = len(violations)
            if violation_count == 0:
                return "Low"
            elif violation_count <= 2:
                return "Medium"
            elif violation_count <= 5:
                return "High"
            else:
                return "Critical"

    def _minimal_fallback_detection(self, image_path, error):
        """Absolute minimal fallback when everything else fails"""
        return {
            'error': f'Advanced detection failed: {str(error)}',
            'violations': [],
            'detections': [{'class': 'minimal_fallback', 'confidence': 0.1}],
            'violation_count': 0,
            'compliance_score': 50,
            'risk_level': 'Unknown',
            'model_used': 'minimal_fallback',
            'timestamp': datetime.utcnow().isoformat(),
            'notes': 'Using minimal fallback due to critical error'
        }

    def start_camera_monitoring(self, camera_url: str, user_id: int, department: str, industry: str = 'healthcare') -> str:
        """Enhanced real-time camera monitoring with adaptive processing and health checks"""
        try:
            if not self.yolov5_available:
                logger.warning("YOLOv5 not available, using fallback computer vision")
                return self._start_fallback_monitoring(camera_url, user_id, department, industry)
            
            monitor_id = f"mon_{user_id}_{department}_{int(time.time())}"
            
            # Validate camera URL and connection
            if not self._validate_camera_connection(camera_url):
                logger.error(f"Camera validation failed: {camera_url}")
                return None
            
            def monitor_feed():
                """Main monitoring loop with adaptive processing"""
                cap = None
                consecutive_errors = 0
                max_errors = 5
                frame_count = 0
                processing_times = []
                health_check_interval = 30
                last_health_check = time.time()
                
                try:
                    cap = cv2.VideoCapture(camera_url)
                    if not cap.isOpened():
                        logger.error(f"Could not open camera feed: {camera_url}")
                        return
                    
                    cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
                    cap.set(cv2.CAP_PROP_FPS, 15)
                    
                    logger.info(f"Started monitoring feed: {monitor_id}")
                    
                    while monitor_id in self.active_monitors:
                        try:
                            current_time = time.time()
                            
                            if current_time - last_health_check > health_check_interval:
                                self._update_monitor_health(monitor_id, processing_times)
                                last_health_check = current_time
                                processing_times = []
                            
                            ret, frame = cap.read()
                            if not ret:
                                consecutive_errors += 1
                                logger.warning(f"Frame read error {consecutive_errors} for {monitor_id}")
                                
                                if consecutive_errors >= max_errors:
                                    logger.error(f"Too many consecutive errors for monitor {monitor_id}")
                                    self._handle_monitor_failure(monitor_id, "Frame read errors")
                                    break
                                
                                if consecutive_errors == 3:
                                    cap.release()
                                    time.sleep(2)
                                    cap = cv2.VideoCapture(camera_url)
                                    if not cap.isOpened():
                                        logger.error(f"Failed to reinitialize camera: {camera_url}")
                                        break
                                
                                time.sleep(1)
                                continue
                            
                            consecutive_errors = 0
                            frame_count += 1
                            
                            process_frame = self._should_process_frame(frame_count, processing_times)
                            
                            if process_frame:
                                start_time = time.time()
                                
                                results = self._process_monitoring_frame(frame, industry, monitor_id)
                                
                                processing_time = time.time() - start_time
                                processing_times.append(processing_time)
                                
                                if results and results.get('violation_count', 0) > 0:
                                    self._handle_violation_detection(
                                        results, monitor_id, user_id, department, industry, frame
                                    )
                                
                                sleep_time = self._calculate_adaptive_sleep(processing_times)
                                time.sleep(sleep_time)
                            else:
                                time.sleep(0.05)
                                
                        except Exception as e:
                            consecutive_errors += 1
                            logger.error(f"Frame processing error for {monitor_id}: {e}")
                            
                            if consecutive_errors >= max_errors:
                                logger.error(f"Too many processing errors for monitor {monitor_id}")
                                self._handle_monitor_failure(monitor_id, f"Processing errors: {str(e)}")
                                break
                            
                            time.sleep(1)
                
                except Exception as e:
                    logger.error(f"Monitoring loop error for {monitor_id}: {e}")
                    self._handle_monitor_failure(monitor_id, f"Loop error: {str(e)}")
                
                finally:
                    if cap and cap.isOpened():
                        cap.release()
                    logger.info(f"Camera monitoring stopped for {monitor_id}")
                    self._cleanup_monitor(monitor_id)
            
            # Initialize monitor entry
            self.active_monitors[monitor_id] = {
                'thread': threading.Thread(target=monitor_feed, daemon=True),
                'camera_url': camera_url,
                'user_id': user_id,
                'department': department,
                'industry': industry,
                'start_time': datetime.utcnow(),
                'status': 'starting',
                'last_frame_time': None,
                'total_frames_processed': 0,
                'average_processing_time': 0,
                'violations_detected': 0,
                'last_health_check': datetime.utcnow()
            }
            
            # Start monitoring thread
            self.active_monitors[monitor_id]['thread'].start()
            self.active_monitors[monitor_id]['status'] = 'active'
            
            logger.info(f"Successfully started camera monitoring: {monitor_id}")
            return monitor_id
            
        except Exception as e:
            logger.error(f"Failed to start camera monitoring: {e}")
            return None

    def _start_fallback_monitoring(self, camera_url: str, user_id: int, department: str, industry: str = 'healthcare') -> str:
        """Fallback monitoring using OpenCV when YOLOv5 is not available"""
        try:
            monitor_id = f"fallback_mon_{user_id}_{department}_{int(time.time())}"
            
            if not self._validate_camera_connection(camera_url):
                logger.error(f"Camera validation failed for fallback: {camera_url}")
                return None
            
            def fallback_monitor_feed():
                """Fallback monitoring loop using OpenCV"""
                cap = None
                try:
                    cap = cv2.VideoCapture(camera_url)
                    if not cap.isOpened():
                        logger.error(f"Could not open camera feed for fallback: {camera_url}")
                        return
                    
                    logger.info(f"Started fallback monitoring feed: {monitor_id}")
                    
                    frame_count = 0
                    while monitor_id in self.active_monitors:
                        ret, frame = cap.read()
                        if not ret:
                            time.sleep(1)
                            continue
                        
                        frame_count += 1
                        
                        if frame_count % 10 == 0:
                            try:
                                temp_path = os.path.join(self.UPLOAD_DIRS['temp'], f"fallback_{monitor_id}_{int(time.time())}.jpg")
                                cv2.imwrite(temp_path, frame)
                                
                                results = self._fallback_violation_detection(temp_path, industry)
                                
                                if results and results.get('violation_count', 0) > 0:
                                    self._handle_violation_detection(
                                        results, monitor_id, user_id, department, industry, frame
                                    )
                                
                                if os.path.exists(temp_path):
                                    os.remove(temp_path)
                                    
                            except Exception as e:
                                logger.error(f"Fallback frame processing error: {e}")
                        
                        time.sleep(0.1)
                
                except Exception as e:
                    logger.error(f"Fallback monitoring error: {e}")
                finally:
                    if cap and cap.isOpened():
                        cap.release()
                    self._cleanup_monitor(monitor_id)
            
            self.active_monitors[monitor_id] = {
                'thread': threading.Thread(target=fallback_monitor_feed, daemon=True),
                'camera_url': camera_url,
                'user_id': user_id,
                'department': department,
                'industry': industry,
                'start_time': datetime.utcnow(),
                'status': 'starting',
                'is_fallback': True,
                'violations_detected': 0
            }
            
            self.active_monitors[monitor_id]['thread'].start()
            self.active_monitors[monitor_id]['status'] = 'active'
            
            logger.info(f"Started fallback camera monitoring: {monitor_id}")
            return monitor_id
            
        except Exception as e:
            logger.error(f"Failed to start fallback monitoring: {e}")
            return None

    def _validate_camera_connection(self, camera_url: str) -> bool:
        """Validate camera connection before starting monitoring"""
        try:
            cap = cv2.VideoCapture(camera_url)
            if not cap.isOpened():
                return False
            
            ret, frame = cap.read()
            cap.release()
            
            return ret and frame is not None
            
        except Exception as e:
            logger.error(f"Camera validation error: {e}")
            return False

    def _should_process_frame(self, frame_count: int, processing_times: List[float]) -> bool:
        """Determine whether to process current frame based on adaptive logic"""
        if frame_count <= 10:
            return True
        
        base_rate = 5
        
        if processing_times:
            avg_processing_time = sum(processing_times) / len(processing_times)
            if avg_processing_time > 0.5:
                base_rate = 10
            elif avg_processing_time < 0.1:
                base_rate = 3
        
        return frame_count % base_rate == 0

    def _process_monitoring_frame(self, frame, industry: str, monitor_id: str) -> Dict:
        """Process a single frame for safety violations"""
        try:
            temp_path = os.path.join(self.UPLOAD_DIRS['temp'], f"process_{monitor_id}_{int(time.time())}.jpg")
            cv2.imwrite(temp_path, frame)
            
            if self.yolov5_available:
                results = self.detect_safety_violations(temp_path, industry)
            else:
                results = self._fallback_violation_detection(temp_path, industry)
            
            if os.path.exists(temp_path):
                os.remove(temp_path)
            
            return results
            
        except Exception as e:
            logger.error(f"Frame processing error: {e}")
            return None

    def _calculate_adaptive_sleep(self, processing_times: List[float]) -> float:
        """Calculate adaptive sleep time based on processing performance"""
        if not processing_times:
            return 0.1
        
        avg_processing_time = sum(processing_times) / len(processing_times)
        
        sleep_time = max(0.05, avg_processing_time * 0.5)
        
        return min(0.5, sleep_time)

    def _update_monitor_health(self, monitor_id: str, processing_times: List[float]):
        """Update monitor health status and metrics"""
        if monitor_id not in self.active_monitors:
            return
        
        monitor = self.active_monitors[monitor_id]
        monitor['last_health_check'] = datetime.utcnow()
        
        if processing_times:
            monitor['average_processing_time'] = sum(processing_times) / len(processing_times)
        
        logger.debug(f"Monitor health updated: {monitor_id}")

    def _handle_monitor_failure(self, monitor_id: str, reason: str):
        """Handle monitor failure gracefully"""
        logger.error(f"Monitor {monitor_id} failed: {reason}")
        
        if monitor_id in self.active_monitors:
            self.active_monitors[monitor_id]['status'] = 'failed'
            self.active_monitors[monitor_id]['failure_reason'] = reason

    def _cleanup_monitor(self, monitor_id: str):
        """Clean up monitor resources"""
        if monitor_id in self.active_monitors:
            self.active_monitors[monitor_id]['status'] = 'stopped'
            self.active_monitors[monitor_id]['end_time'] = datetime.utcnow()

    def _handle_violation_detection(self, results: Dict, monitor_id: str, user_id: int, department: str, industry: str, frame):
        """Enhanced violation detection handling with advanced features"""
        try:
            if not results or results.get('violation_count', 0) == 0:
                return
            
            violation_types = [v['type'] for v in results['violations']]
            max_confidence = max([v.get('confidence', 0) for v in results['violations']])
            
            context = {
                'recent_violations_count': self._get_recent_violations_count(monitor_id),
                'lighting_condition': results.get('analysis_metrics', {}).get('lighting_condition', 'unknown'),
                'monitor_id': monitor_id
            }
            
            risk_level = self._calculate_risk_level(results['violations'], industry, context)
            
            violation_filename = f"violation_{monitor_id}_{int(time.time())}.jpg"
            violation_path = os.path.join(self.UPLOAD_DIRS['violations'], violation_filename)
            
            encode_param = [int(cv2.IMWRITE_JPEG_QUALITY), 85]
            cv2.imwrite(violation_path, frame, encode_param)
            
            if monitor_id in self.active_monitors:
                self.active_monitors[monitor_id]['violations_detected'] += 1
            
            logger.info(
                f"Safety violation detected: {violation_types} in {department} "
                f"(Risk: {risk_level}, Confidence: {max_confidence:.2f})"
            )
            
        except Exception as e:
            logger.error(f"Error handling violation detection: {e}")

    def _get_recent_violations_count(self, monitor_id: str, time_window_minutes: int = 10) -> int:
        """Get count of recent violations for temporal analysis"""
        try:
            return 0
        except Exception as e:
            logger.error(f"Error getting recent violations count: {e}")
            return 0

    def stop_camera_monitoring(self, monitor_id: str) -> bool:
        """Enhanced camera monitoring stop with graceful shutdown"""
        try:
            if monitor_id in self.active_monitors:
                monitor = self.active_monitors[monitor_id]
                
                monitor['status'] = 'stopping'
                
                if monitor['thread'].is_alive():
                    monitor['thread'].join(timeout=5.0)
                
                del self.active_monitors[monitor_id]
                
                logger.info(f"Successfully stopped camera monitoring: {monitor_id}")
                return True
            
            logger.warning(f"Monitor {monitor_id} not found for stopping")
            return False
            
        except Exception as e:
            logger.error(f"Error stopping camera monitoring {monitor_id}: {e}")
            return False

    def get_monitoring_status(self) -> Dict:
        """Get comprehensive monitoring status with health metrics"""
        status = {}
        
        for monitor_id, info in self.active_monitors.items():
            duration = datetime.utcnow() - info['start_time']
            
            status[monitor_id] = {
                'status': info['status'],
                'user_id': info['user_id'],
                'department': info['department'],
                'industry': info['industry'],
                'start_time': info['start_time'].isoformat(),
                'duration_seconds': int(duration.total_seconds()),
                'duration_human': str(duration),
                'is_fallback': info.get('is_fallback', False),
                'violations_detected': info.get('violations_detected', 0),
                'average_processing_time': info.get('average_processing_time', 0),
                'last_health_check': info.get('last_health_check', info['start_time']).isoformat(),
                'camera_url': info['camera_url'][:50] + '...' if len(info['camera_url']) > 50 else info['camera_url']
            }
            
            last_health_check = info.get('last_health_check', info['start_time'])
            time_since_health_check = (datetime.utcnow() - last_health_check).total_seconds()
            
            if time_since_health_check > 60:
                status[monitor_id]['health'] = 'degraded'
            elif info['status'] == 'failed':
                status[monitor_id]['health'] = 'failed'
            else:
                status[monitor_id]['health'] = 'healthy'
        
        return status

