def normalize_plan_for_user(user, token_data=None):
    """
    Normalize plan for a user with country-specific pricing
    """
    print(f"\n🔄 PLAN NORMALIZATION FOR USER {user.id}:")
    
    effective_plan = 'free'
    is_trial_active = False
    trial_ends_at = None
    
    if user.trial_ends_at and datetime.utcnow() < user.trial_ends_at:
        effective_plan = user.trial_plan or 'pro'
        is_trial_active = True
        trial_ends_at = user.trial_ends_at
        print(f"  Trial active: {user.trial_plan} until {user.trial_ends_at}")
    elif user.subscription_status == 'active':
        effective_plan = user.subscription_plan or 'free'
        print(f"  Subscription active: {user.subscription_status}")
    else:
        print(f"  Free plan (no active subscription)")
    
    print(f"  Effective plan from DB: {effective_plan}")
    
    user_country = getattr(user, 'country', None) or 'default'
    if token_data and 'country' in token_data:
        user_country = token_data['country']
    
    country_mapping = {
        'GH': 'Ghana', 'GHA': 'Ghana',
        'QA': 'Qatar', 'QAT': 'Qatar',
        'US': 'United States', 'USA': 'United States',
        'default': 'default'
    }
    
    country_name = country_mapping.get(user_country, user_country)
    if country_name not in COUNTRY_PRICING:
        country_name = 'default'
    
    print(f"  User country: {user_country} -> {country_name}")
    
    original_plan = effective_plan.lower() if isinstance(effective_plan, str) else 'free'
    normalized_plan = PLAN_NAME_MAPPING.get(original_plan, 'free')
    
    print(f"  Normalized plan name: {original_plan} -> {normalized_plan}")
    
    country_pricing = COUNTRY_PRICING.get(country_name, COUNTRY_PRICING['default'])
    plan_pricing = country_pricing.get(normalized_plan, country_pricing['free'])
    
    plan_config = PLANS.get(normalized_plan, PLANS['free'])
    
    billing_cycle = getattr(user, 'billing_cycle', '1_month')
    
    cycle_pricing = {
        'monthly': plan_pricing.get('1_month', 0),
        'annual': plan_pricing.get('1_year', 0),
        'semi_annual': plan_pricing.get('6_month', 0)
    }
    
    current_price = 0
    if normalized_plan != 'free':
        if billing_cycle == '1_month':
            current_price = plan_pricing.get('1_month', 0)
        elif billing_cycle == '6_month':
            current_price = plan_pricing.get('6_month', 0)
        elif billing_cycle == '1_year':
            current_price = plan_pricing.get('1_year', 0)
    
    normalized_data = {
        'plan': normalized_plan,
        'original_plan': effective_plan,
        'label': plan_config['label'],
        'country': country_name,
        'currency': plan_pricing.get('currency', 'USD'),
        'pricing': plan_pricing,
        'cycle_pricing': cycle_pricing,
        'current_price': current_price,
        'billing_cycle': billing_cycle,
        'payment_method': plan_pricing.get('payment_method', 'Not specified'),
        'features': plan_config['features'],
        'limits': plan_config['limits'],
        'plan_level': PLAN_HIERARCHY.get(normalized_plan, 0),
        'is_trial_active': is_trial_active,
        'trial_ends_at': trial_ends_at.isoformat() if trial_ends_at else None,
        'trial_days_remaining': (trial_ends_at - datetime.utcnow()).days if is_trial_active and trial_ends_at else None,
        'is_standardized': True,
        'is_custom': normalized_plan == 'enterprise' and plan_pricing.get('1_month') == 'Custom'
    }
    
    print(f"  ✅ Normalized to: {normalized_plan} ({country_name})")
    print(f"  Currency: {normalized_data['currency']}")
    print(f"  Plan level: {normalized_data['plan_level']}")
    print(f"  Trial active: {is_trial_active}")
    print(f"  Custom plan: {normalized_data['is_custom']}")
    
    return normalized_data

def get_user_country(user):
    """Get user's country with fallback"""
    country = getattr(user, 'country', None)
    if not country:
        email_domain = user.email.split('@')[-1].lower()
        country_domains = {
            '.gh': 'Ghana',
            '.com.gh': 'Ghana',
            '.qa': 'Qatar',
            '.com.qa': 'Qatar',
            '.us': 'United States',
            '.com': 'United States',
            '.org': 'United States',
            '.net': 'United States'
        }
        
        for domain, country_name in country_domains.items():
            if email_domain.endswith(domain):
                return country_name
    
    return country or 'default'

def setup_application():
    """Setup application with AI model configuration"""
    try:
        if os.path.exists('.env'):
            load_dotenv()
            logger.info("Loaded environment variables from .env file")
        
        validate_environment()
        
        if not validate_ai_configuration():
            logger.warning("AI configuration validation failed - some features may be limited")
        
        create_directories()
        
        with app.app_context():
            db.create_all()
            logger.info("Database tables created successfully")
        
        if app.config['AI_MODELS_ENABLED']:
            global ai_manager
            ai_manager = AIModelManager()
            logger.info("AI models initialized")
        else:
            logger.info("AI models disabled - skipping initialization")
        
        setup_extensions()
        start_background_services()
        
        logger.info(f"Application setup completed in {app.config['ENVIRONMENT']} environment")
        
    except Exception as e:
        logger.error(f"Application setup failed: {e}")
        raise

