def validate_healthcare_headers(f):
    """
    Decorator to validate healthcare-specific headers for HIPAA compliance.
    Only validates for hospital/medical endpoints. Skips validation for all other endpoints.
    
    Required Headers (for hospital endpoints only):
    - X-Healthcare-Facility or x-healthcare-facility
    - X-User-Role or x-user-role
    - X-HIPAA-Compliant or x-hipaa-compliant
    - X-Data-Sensitivity or x-data-sensitivity
    """
    @wraps(f)
    def decorated_function(*args, **kwargs):
        
        # ✅ Check if this is a hospital/medical endpoint
        hospital_endpoints = [
            '/api/hospital',
            '/api/hospital/',
            '/api/hospitals',
            '/api/hospitals/',
            '/api/hospital/departments',
            '/api/hospital/departments/',
            '/api/hospital/beds',
            '/api/hospital/beds/',
            '/api/hospital/patients',
            '/api/hospital/patients/',
            '/api/hospital/staff',
            '/api/hospital/staff/',
            '/api/hospital/ai-services',
            '/api/hospital/ai-analytics',
            '/api/hospital/analytics',
            '/api/hospital/accreditations',
            '/api/hospital/quality-indicators',
            '/api/hospital/safety-goals',
            '/api/hospital/adverse-events',
            '/api/hospital/risk-assessments',
            '/api/hospital/compliance',
            '/api/hospital/clinical-protocols',
            '/api/hospital/clinical-trials',
            '/api/hospital/medical-records',
            '/api/hospital/equipment',
            '/api/hospital/feedback',
            '/api/hospital/waste-reports',
            '/api/hospital/safety/',
            '/api/ai/medical/',
            '/api/medical/',
            '/api/hospitals/ai-services',
            '/api/hospitals/ai-analytics',
            '/api/hospitals/analytics',
            '/api/hospitals/departments',
            '/api/hospitals/beds',
            '/api/hospitals/patients',
            '/api/hospitals/staff',
            '/api/hospitals/accreditations',
            '/api/hospitals/quality-indicators',
            '/api/hospitals/safety-goals',
            '/api/hospitals/adverse-events',
            '/api/hospitals/risk-assessments',
            '/api/hospitals/compliance',
            '/api/hospitals/clinical-protocols',
            '/api/hospitals/clinical-trials',
            '/api/hospitals/medical-records',
            '/api/hospitals/equipment',
            '/api/hospitals/feedback',
            '/api/hospitals/waste-reports',
            '/api/hospitals/safety/',
            '/api/hse/healthcare/',
        ]
        
        is_hospital = any(request.path.startswith(endpoint) for endpoint in hospital_endpoints)
        
        # ✅ If not a hospital endpoint, skip validation and continue
        if not is_hospital:
            # Set default context for non-hospital endpoints
            request.healthcare_context = {
                'facility': 'N/A',
                'user_role': 'N/A',
                'hipaa_compliant': False,
                'data_sensitivity': 'low',
                'is_hospital_endpoint': False
            }
            # Log for debugging
            logger.debug(f"Non-hospital endpoint {request.path} - skipping healthcare headers validation")
            return f(*args, **kwargs)
        
        # ✅ HOSPITAL ENDPOINT - Validate healthcare headers
        try:
            # Get healthcare headers (case-insensitive)
            healthcare_facility = (
                request.headers.get('X-Healthcare-Facility') or 
                request.headers.get('x-healthcare-facility', '').strip()
            )
            
            user_role = (
                request.headers.get('X-User-Role') or 
                request.headers.get('x-user-role', '').strip()
            )
            
            hipaa_compliant = (
                request.headers.get('X-HIPAA-Compliant') or 
                request.headers.get('x-hipaa-compliant', 'false').strip().lower()
            )
            
            data_sensitivity = (
                request.headers.get('X-Data-Sensitivity') or 
                request.headers.get('x-data-sensitivity', 'medium').strip().lower()
            )
            
            # Validate required headers
            missing_headers = []
            
            if not healthcare_facility:
                missing_headers.append('X-Healthcare-Facility')
            
            if not user_role:
                missing_headers.append('X-User-Role')
            
            if hipaa_compliant not in ['true', 'false', '1', '0', 'yes', 'no']:
                missing_headers.append('X-HIPAA-Compliant (must be true/false)')
            
            if data_sensitivity not in ['low', 'medium', 'high', 'critical']:
                missing_headers.append('X-Data-Sensitivity (must be low/medium/high/critical)')
            
            if missing_headers:
                return jsonify({
                    'success': False,
                    'error': 'Missing or invalid healthcare headers',
                    'code': 'MISSING_HEALTHCARE_HEADERS',
                    'missing_headers': missing_headers,
                    'required_headers': [
                        'X-Healthcare-Facility',
                        'X-User-Role',
                        'X-HIPAA-Compliant',
                        'X-Data-Sensitivity'
                    ],
                    'suggestion': 'Please include all required healthcare headers in your request'
                }), 400
            
            # Store healthcare context in request
            request.healthcare_context = {
                'facility': healthcare_facility,
                'user_role': user_role,
                'hipaa_compliant': hipaa_compliant.lower() in ['true', '1', 'yes'],
                'data_sensitivity': data_sensitivity,
                'is_hospital_endpoint': True,
                'timestamp': datetime.utcnow().isoformat()
            }
            
            # Log healthcare context for auditing
            logger.info(f"🏥 Hospital request - Facility: {healthcare_facility}, "
                       f"User Role: {user_role}, "
                       f"HIPAA Compliant: {hipaa_compliant}, "
                       f"Data Sensitivity: {data_sensitivity}")
            
            # HIPAA compliance check for sensitive data
            if data_sensitivity in ['high', 'critical'] and not hipaa_compliant.lower() in ['true', '1', 'yes']:
                logger.warning(f"⚠️ HIPAA non-compliant request for sensitive data - Facility: {healthcare_facility}")
                return jsonify({
                    'success': False,
                    'error': 'HIPAA compliance required for sensitive data',
                    'code': 'HIPAA_REQUIRED',
                    'data_sensitivity': data_sensitivity,
                    'required_compliance': 'HIPAA',
                    'suggestion': 'Set X-HIPAA-Compliant header to true for sensitive data access'
                }), 403
            
            return f(*args, **kwargs)
            
        except Exception as e:
            logger.error(f"Error in healthcare headers validation: {str(e)}")
            return jsonify({
                'success': False,
                'error': 'Healthcare headers validation error',
                'code': 'VALIDATION_ERROR',
                'message': str(e)
            }), 500
    
    return decorated_function


def get_healthcare_context():
    """
    Get the healthcare context from the request.
    Should be called after validate_healthcare_headers decorator.
    
    Returns:
        dict: Healthcare context dictionary
    """
    try:
        if hasattr(request, 'healthcare_context'):
            return request.healthcare_context
        
        # Fallback: Try to extract from headers directly
        return {
            'facility': request.headers.get('X-Healthcare-Facility') or request.headers.get('x-healthcare-facility', 'Unknown'),
            'user_role': request.headers.get('X-User-Role') or request.headers.get('x-user-role', 'unknown'),
            'hipaa_compliant': (request.headers.get('X-HIPAA-Compliant') or request.headers.get('x-hipaa-compliant', 'false')).lower() in ['true', '1', 'yes'],
            'data_sensitivity': request.headers.get('X-Data-Sensitivity') or request.headers.get('x-data-sensitivity', 'medium'),
            'is_hospital_endpoint': hasattr(request, 'healthcare_context') and request.healthcare_context.get('is_hospital_endpoint', False),
            'timestamp': datetime.utcnow().isoformat()
        }
    except Exception as e:
        logger.error(f"Error getting healthcare context: {e}")
        return {
            'facility': 'Unknown',
            'user_role': 'unknown',
            'hipaa_compliant': False,
            'data_sensitivity': 'medium',
            'is_hospital_endpoint': False
        }

