class BackblazeB2Manager:
    def __init__(self):
        self.application_key_id = app.config['BACKBLAZE_APPLICATION_KEY_ID']
        self.application_key = app.config['BACKBLAZE_APPLICATION_KEY']
        self.bucket_name = app.config['BACKBLAZE_BUCKET_NAME']
        self.endpoint_url = app.config['BACKBLAZE_ENDPOINT_URL']
        
        # Initialize S3 client for Backblaze B2
        self.s3_client = self._initialize_b2_client()
        self.is_configured = all([self.application_key_id, self.application_key, self.bucket_name])
        
    def _initialize_b2_client(self):
        """Initialize S3 client for Backblaze B2"""
        try:
            if not all([self.application_key_id, self.application_key, self.bucket_name]):
                logger.warning("Backblaze B2 credentials not fully configured")
                return None
                
            return boto3.client(
                's3',
                endpoint_url=self.endpoint_url,
                aws_access_key_id=self.application_key_id,
                aws_secret_access_key=self.application_key,
                config=Config(
                    signature_version='s3v4',
                    s3={'addressing_style': 'virtual'}
                )
            )
        except Exception as e:
            logger.error(f"Failed to initialize Backblaze B2 client: {e}")
            return None
    
    def upload_file(self, file, filename, folder=''):
        """Upload file to Backblaze B2"""
        try:
            if not self.s3_client or not self.is_configured:
                return self._fallback_to_local(file, filename, folder)
            
            # Generate unique filename
            file_extension = os.path.splitext(filename)[1]
            unique_filename = f"{uuid.uuid4()}{file_extension}"
            
            # Construct object key
            if folder:
                object_key = f"{folder}/{unique_filename}"
            else:
                object_key = unique_filename
            
            # Upload to B2
            self.s3_client.upload_fileobj(
                file,
                self.bucket_name,
                object_key,
                ExtraArgs={
                    'ContentType': file.content_type if hasattr(file, 'content_type') else 'application/octet-stream',
                    'ACL': 'public-read'  # Make files publicly accessible
                }
            )
            
            # Return public URL - Backblaze B2 uses different URL format
            file_url = self._get_public_url(object_key)
            
            logger.info(f"File uploaded to Backblaze B2: {object_key}")
            return {
                'success': True,
                'file_url': file_url,
                'object_key': object_key,
                'filename': unique_filename,
                'storage_type': 'backblaze_b2'
            }
            
        except Exception as e:
            logger.error(f"Backblaze B2 upload failed: {e}")
            return self._fallback_to_local(file, filename, folder)
    
    def _get_public_url(self, object_key):
        """Generate public URL for Backblaze B2 file"""
        # Backblaze B2 public URL format: https://f002.backblazeb2.com/file/bucket-name/object-key
        # Or custom domain if configured
        if hasattr(app.config, 'BACKBLAZE_PUBLIC_URL') and app.config.get('BACKBLAZE_PUBLIC_URL'):
            return urljoin(app.config['BACKBLAZE_PUBLIC_URL'], object_key)
        else:
            # Extract bucket ID from endpoint URL for public URL construction
            endpoint_base = self.endpoint_url.replace('https://s3.', 'https://f002.')
            return f"{endpoint_base}/file/{self.bucket_name}/{object_key}"
    
    def _fallback_to_local(self, file, filename, folder):
        """Fallback to local storage when B2 is unavailable"""
        try:
            # Create local directory
            if folder:
                local_folder = os.path.join(app.config['UPLOAD_FOLDER'], folder)
            else:
                local_folder = app.config['UPLOAD_FOLDER']
            
            os.makedirs(local_folder, exist_ok=True)
            
            # Generate unique filename
            file_extension = os.path.splitext(filename)[1]
            unique_filename = f"{uuid.uuid4()}{file_extension}"
            local_path = os.path.join(local_folder, unique_filename)
            
            # Save locally
            file.save(local_path)
            
            # Return local URL
            file_url = f"/api/files/{folder}/{unique_filename}" if folder else f"/api/files/{unique_filename}"
            
            logger.info(f"File saved locally (B2 fallback): {local_path}")
            return {
                'success': True,
                'file_url': file_url,
                'local_path': local_path,
                'filename': unique_filename,
                'storage_type': 'local'
            }
            
        except Exception as e:
            logger.error(f"Local fallback also failed: {e}")
            return {
                'success': False,
                'error': str(e)
            }
    
    def delete_file(self, object_key):
        """Delete file from Backblaze B2"""
        try:
            if not self.s3_client or not self.is_configured:
                return self._delete_local_file(object_key)
            
            self.s3_client.delete_object(
                Bucket=self.bucket_name,
                Key=object_key
            )
            
            logger.info(f"File deleted from Backblaze B2: {object_key}")
            return {'success': True}
            
        except Exception as e:
            logger.error(f"Backblaze B2 delete failed: {e}")
            return self._delete_local_file(object_key)
    
    def _delete_local_file(self, file_path):
        """Delete local file"""
        try:
            if os.path.exists(file_path):
                os.remove(file_path)
                logger.info(f"Local file deleted: {file_path}")
                return {'success': True}
            else:
                return {'success': False, 'error': 'File not found'}
        except Exception as e:
            logger.error(f"Local file delete failed: {e}")
            return {'success': False, 'error': str(e)}
    
    def get_file_url(self, object_key):
        """Get public URL for file"""
        if object_key.startswith('/'):
            # Local file
            return object_key
        else:
            # Backblaze B2 file
            return self._get_public_url(object_key)
    
    def check_connection(self):
        """Check Backblaze B2 connection"""
        try:
            if not self.s3_client:
                return {'connected': False, 'error': 'B2 not configured'}
            
            self.s3_client.head_bucket(Bucket=self.bucket_name)
            return {'connected': True}
        except Exception as e:
            logger.error(f"Backblaze B2 connection check failed: {e}")
            return {'connected': False, 'error': str(e)}

# Initialize Backblaze B2 manager
b2_manager = BackblazeB2Manager()

