@app.after_request
def add_security_headers(response):
    """Add comprehensive security headers to all responses"""
    
    # ✅ Prevent clickjacking
    response.headers['X-Frame-Options'] = 'DENY'
    
    # ✅ Prevent MIME-type sniffing
    response.headers['X-Content-Type-Options'] = 'nosniff'
    
    # ✅ XSS Protection (modern browsers use CSP instead)
    response.headers['X-XSS-Protection'] = '1; mode=block'
    
    # ✅ Referrer Policy
    response.headers['Referrer-Policy'] = 'strict-origin-when-cross-origin'
    
    # ✅ Strict Transport Security (HTTPS only)
    if not request.host.startswith('localhost'):
        response.headers['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains; preload'
    
    # ✅ Content Security Policy (adjust as needed)
    response.headers['Content-Security-Policy'] = (
        "default-src 'self'; "
        "script-src 'self' 'unsafe-inline' 'unsafe-eval'; "
        "style-src 'self' 'unsafe-inline'; "
        "img-src 'self' data: https:; "
        "font-src 'self' data:; "
        "connect-src 'self' wss: https://api.safetrackproglobal.com; "
        "frame-ancestors 'none'; "
        "base-uri 'self'; "
        "form-action 'self'"
    )
    
    # ✅ Remove Server header (don't reveal technology)
    response.headers.pop('Server', None)
    response.headers.pop('X-Powered-By', None)
    
    # ✅ Add response time for monitoring
    if hasattr(g, 'start_time'):
        elapsed = (datetime.utcnow() - g.start_time).total_seconds() * 1000
        response.headers['X-Response-Time'] = f'{elapsed:.2f}ms'
    
    return response

@app.before_request
def start_timer():
    """Start timer for response time tracking"""
    g.start_time = datetime.utcnow()

@app.after_request
def add_cache_control(response):
    """Add appropriate cache headers"""
    if request.method == 'GET' and not response.status_code >= 400:
        if not request.path.startswith('/api/'):
            response.headers['Cache-Control'] = 'public, max-age=300'
        else:
            response.headers['Cache-Control'] = 'private, no-cache, no-store, must-revalidate'
            response.headers['Pragma'] = 'no-cache'
            response.headers['Expires'] = '0'
    return response


class UserCache:
    """Redis cache for user data to reduce database queries"""
    
    CACHE_TTL = 3600  # 1 hour
    
    @staticmethod
    def get_redis():
        """Get Redis connection with error handling"""
        try:
            redis_url = current_app.config.get('REDIS_URL', 'redis://localhost:6379/0')
            return redis.Redis.from_url(redis_url, decode_responses=True)
        except Exception as e:
            logger.error(f"Redis connection error: {str(e)}")
            return None
    
    @staticmethod
    def get(user_id):
        """Get cached user data"""
        try:
            redis_client = UserCache.get_redis()
            if not redis_client:
                return None
            
            cache_key = f"user:{user_id}"
            cached = redis_client.get(cache_key)
            
            if cached:
                return json.loads(cached)
            return None
            
        except Exception as e:
            logger.error(f"Redis get error for user {user_id}: {str(e)}")
            return None
    
    @staticmethod
    def set(user_id, user_data):
        """Store user data in cache"""
        try:
            redis_client = UserCache.get_redis()
            if not redis_client:
                return False
            
            cache_key = f"user:{user_id}"
            redis_client.setex(cache_key, UserCache.CACHE_TTL, json.dumps(user_data))
            logger.info(f"Cached user {user_id}")
            return True
            
        except Exception as e:
            logger.error(f"Redis set error for user {user_id}: {str(e)}")
            return False
    
    @staticmethod
    def clear(user_id):
        """Remove user from cache (when status changes)"""
        try:
            redis_client = UserCache.get_redis()
            if not redis_client:
                return False
            
            cache_key = f"user:{user_id}"
            redis_client.delete(cache_key)
            logger.info(f"Cleared cache for user {user_id}")
            return True
            
        except Exception as e:
            logger.error(f"Redis clear error for user {user_id}: {str(e)}")
            return False
    
    @staticmethod
    def to_user_object(cached_data):
        """Convert cached dict to a user-like object with lazy loading"""
        class CachedUser:
            def __init__(self, data):
                # Set all attributes from cached data
                for key, value in data.items():
                    setattr(self, key, value)
                
                # Ensure required attributes exist with fallbacks
                self.id = data.get('id')
                self.email = data.get('email')
                self.name = data.get('name')
                self.user_type = data.get('user_type')
                self.role = data.get('role')
                
                # Admin attributes
                self.admin_role = data.get('admin_role', '')
                self.admin_level = data.get('admin_level', '')
                self.admin_tier = data.get('admin_tier', '')
                self.is_super_admin = data.get('is_super_admin', False)
                self.is_platform_owner = data.get('is_platform_owner', False)
                self.is_system_team = data.get('is_system_team', False)
                self.is_active = data.get('is_active', True)
                self.verified = data.get('verified', True)
                
                # Hospital
                self.hospital_id = data.get('hospital_id')
                
                # Subscription
                self.subscription_plan = data.get('subscription_plan', 'free')
                self.subscription_status = data.get('subscription_status', 'inactive')
                self.company_id = data.get('company_id')
                self.company_name = data.get('company_name')
                self.token_version = data.get('token_version', 1)
                self.approval_status = data.get('approval_status', 'approved')
                self.login_count = data.get('login_count', 0)
                self.last_login = data.get('last_login')
                self.created_at = data.get('created_at')
                
                # Country and other fields
                self.country = data.get('country', '')
                self.industry = data.get('industry', '')
                self.preferred_language = data.get('preferred_language', 'en')
                self.stage = data.get('stage', '')
                
                # ✅ LAZY LOADING: Company property
                self._company = None
                self._company_loaded = False
            
            @property
            def company(self):
                """Lazy load company from database when accessed"""
                if not self._company_loaded:
                    if self.company_id:
                        try:
                            from models import Company
                            self._company = Company.query.get(self.company_id)
                        except Exception as e:
                            logger.error(f"Error loading company for user {self.id}: {str(e)}")
                            self._company = None
                    self._company_loaded = True
                return self._company
            
            @company.setter
            def company(self, value):
                """Allow setting company directly"""
                self._company = value
                self._company_loaded = True
                if value:
                    self.company_id = value.id
                    self.company_name = getattr(value, 'name', None)
            
            def get_company(self):
                """Explicit method to get company"""
                return self.company
            
            # ✅ LAZY LOADING: Hospital property
            @property
            def hospital(self):
                """Lazy load hospital from database when accessed"""
                if not hasattr(self, '_hospital') or self._hospital is None:
                    if self.hospital_id:
                        try:
                            from models import Hospital
                            self._hospital = Hospital.query.get(self.hospital_id)
                        except Exception as e:
                            logger.error(f"Error loading hospital for user {self.id}: {str(e)}")
                            self._hospital = None
                    else:
                        self._hospital = None
                return self._hospital
            
            @hospital.setter
            def hospital(self, value):
                """Allow setting hospital directly"""
                self._hospital = value
                if value:
                    self.hospital_id = value.id
            
            def get_hospital(self):
                """Explicit method to get hospital"""
                return self.hospital
            
            # ✅ Add to_dict method for debugging
            def to_dict(self):
                """Convert to dictionary for debugging"""
                return {
                    'id': self.id,
                    'email': self.email,
                    'name': self.name,
                    'user_type': self.user_type,
                    'role': self.role,
                    'is_super_admin': self.is_super_admin,
                    'company_id': self.company_id,
                    'company_name': self.company_name,
                    'hospital_id': self.hospital_id,
                    'subscription_plan': self.subscription_plan
                }
        
        return CachedUser(cached_data)


