    def get_entity_type(self, label):
        """Map model-specific labels to standardized entity types"""
        return self.entity_mapping.get(label, label)

    def analyze_text(self, text):
        """Analyze text with all available models"""
        results = {}

        if self.model_status.get('bio_clinical_bert') == 'loaded':
            try:
                results['bio_entities'] = self.models['bio_clinical_bert'](text)
            except Exception as e:
                logger.error(f"BioClinicalBERT analysis failed: {e}")

        if self.model_status.get('hunflair_v2') == 'loaded':
            try:
                from flair.data import Sentence
                sentence = Sentence(text)
                self.models['hunflair_v2'].predict(sentence)
                results['hunflair_entities'] = [
                    {
                        'text': entity.text,
                        'label': entity.tag,
                        'score': entity.score,
                        'start': entity.start_position,
                        'end': entity.end_position
                    }
                    for entity in sentence.get_spans()
                ]
            except Exception as e:
                logger.error(f"HunFlair analysis failed: {e}")

        if self.model_status.get('flair_sentiment') == 'loaded':
            try:
                from flair.data import Sentence
                sentence = Sentence(text)
                self.models['flair_sentiment'].predict(sentence)
                results['sentiment'] = str(sentence.labels[0]) if sentence.labels else None
            except Exception as e:
                logger.error(f"Sentiment analysis failed: {e}")

        return results

    # ==================== COMMON UTILITY METHODS ====================

    def is_model_available(self, model_name):
        """Check if a specific model is available"""
        model = self.models.get(model_name)
        return model is not None and self.model_status.get(model_name) == 'loaded'

    def comprehensive_entity_extraction(self, text: str) -> Dict:
        """Extract entities using multiple models for better accuracy"""
        entities = []
        models_used = []

        if self.is_model_available('bio_clinical_bert'):
            try:
                bio_results = self.models['bio_clinical_bert'](text)
                for entity in bio_results:
                    entities.append({
                        'text': entity['word'],
                        'type': self.entity_mapping.get(entity['entity_group'], entity['entity_group']),
                        'confidence': float(entity['score']),
                        'start': entity.get('start', 0),
                        'end': entity.get('end', 0),
                        'model': 'BioClinicalBERT'
                    })
                models_used.append('BioClinicalBERT')
            except Exception as e:
                logger.warning(f"BioClinicalBERT extraction failed: {e}")

        if self.is_model_available('hunflair_v2'):
            try:
                sentence = Sentence(text)
                self.models['hunflair_v2'].predict(sentence)
                for entity in sentence.get_spans('ner'):
                    entities.append({
                        'text': entity.text,
                        'type': entity.tag,
                        'confidence': float(entity.score),
                        'start': entity.start_position,
                        'end': entity.end_position,
                        'model': 'HunFlair2'
                    })
                models_used.append('HunFlair2')
            except Exception as e:
                logger.warning(f"HunFlair2 extraction failed: {e}")

        entity_dict = {}
        for entity in entities:
            key = f"{entity['text']}_{entity['type']}"
            if key not in entity_dict or entity['confidence'] > entity_dict[key]['confidence']:
                entity_dict[key] = entity

        by_type = defaultdict(list)
        for entity in entity_dict.values():
            by_type[entity['type']].append(entity)

        return {
            'entities': list(entity_dict.values()),
            'by_type': dict(by_type),
            'total_count': len(entity_dict),
            'unique_types': list(by_type.keys()),
            'models_used': models_used
        }

    def analyze_sentiment_flair(self, text: str) -> Dict:
        """Analyze sentiment using Flair"""
        if not self.is_model_available('flair_sentiment'):
            return {'sentiment': 'NEUTRAL', 'confidence': 0.5, 'model': None}

        try:
            sentence = Sentence(text)
            self.models['flair_sentiment'].predict(sentence)
            label = sentence.labels[0]
            return {
                'sentiment': label.value,
                'confidence': float(label.score),
                'model': 'Flair Sentiment'
            }
        except Exception as e:
            logger.warning(f"Sentiment analysis failed: {e}")
            return {'sentiment': 'NEUTRAL', 'confidence': 0.5, 'model': None}

    def get_pubmed_embeddings(self, text: str) -> np.ndarray:
        """Get PubMedBERT embeddings for text"""
        if not self.is_model_available('pubmed_bert'):
            return np.zeros(768)

        try:
            inputs = self.tokenizers['pubmed'](
                text,
                return_tensors="pt",
                padding=True,
                truncation=True,
                max_length=self.model_config['max_length']
            ).to(self.model_config['device'])

            with torch.no_grad():
                outputs = self.models['pubmed_bert'](**inputs)

            embeddings = outputs.last_hidden_state[:, 0, :].cpu().numpy()
            return embeddings[0]
        except Exception as e:
            logger.warning(f"Embedding extraction failed: {e}")
            return np.zeros(768)
    
    # ==================== MODULE 1: MEDICAL CHAT ====================
    
    def medical_chat(self, message: str, context: Dict = None) -> Dict:
        """
        Handle general medical queries conversationally
        Uses: BioClinicalBERT, HunFlair2 (entity extraction), Flair (sentiment), PubMedBERT (understanding)
        """
        start_time = time.time()
        
        try:
            # 1. Understand the query
            entities_result = self.comprehensive_entity_extraction(message)
            entities = entities_result['entities']
            sentiment = self.analyze_sentiment_flair(message)
            
            # 2. Get embedding for semantic understanding
            embedding = self.get_pubmed_embeddings(message)
            
            # 3. Categorize query type
            query_type = self._categorize_query(message, entities)
            
            # 4. Generate response based on query type
            response_data = self._generate_chat_response(
                message, entities, sentiment, query_type, context
            )
            
            # 5. Generate follow-up suggestions
            suggestions = self._generate_chat_suggestions(
                message, entities, query_type, sentiment
            )
            
            result = {
                'response': response_data['text'],
                'query_type': query_type,
                'entities_detected': {
                    'count': len(entities),
                    'diseases': len([e for e in entities if e['type'] == 'DISEASE']),
                    'symptoms': len([e for e in entities if e['type'] == 'SYMPTOM']),
                    'medications': len([e for e in entities if e['type'] == 'MEDICATION'])
                },
                'sentiment': sentiment,
                'suggestions': suggestions,
                'confidence': response_data['confidence'],
                'requires_professional': response_data.get('requires_professional', False),
                'emergency_detected': response_data.get('emergency', False),
                'processing_time': time.time() - start_time,
                'models_used': entities_result['models_used'] + ['Flair Sentiment', 'PubMedBERT'],
                'module': 'medical_chat'
            }
            
            return result
            
        except Exception as e:
            logger.error(f"Medical chat failed: {e}")
            return {
                'response': "I'm here to help with medical questions. Could you please provide more details?",
                'query_type': 'general',
                'entities_detected': {'count': 0},
                'sentiment': {'sentiment': 'NEUTRAL', 'confidence': 0.5},
                'suggestions': ['Tell me more about your symptoms', 'When did this start?', 'Have you seen a doctor?'],
                'confidence': 0.5,
                'requires_professional': True,
                'emergency_detected': False,
                'processing_time': time.time() - start_time,
                'module': 'medical_chat',
                'error': True
            }
    
    def _categorize_query(self, message: str, entities: List) -> str:
        """Categorize the type of medical query"""
        message_lower = message.lower()
        
        # Check for emergency keywords
        emergency_keywords = ['emergency', 'severe', 'chest pain', 'difficulty breathing', 'unconscious', 'bleeding']
        if any(kw in message_lower for kw in emergency_keywords):
            return 'emergency'
        
        # Check for symptom-related
        symptom_entities = [e for e in entities if e['type'] == 'SYMPTOM']
        if symptom_entities:
            return 'symptom_inquiry'
        
        # Check for disease-related
        disease_entities = [e for e in entities if e['type'] == 'DISEASE']
        if disease_entities:
            return 'disease_inquiry'
        
        # Check for medication-related
        medication_entities = [e for e in entities if e['type'] == 'MEDICATION']
        if medication_entities:
            return 'medication_inquiry'
        
        # Check for general medical questions
        medical_keywords = ['doctor', 'hospital', 'treatment', 'cure', 'medicine', 'health', 'medical']
        if any(kw in message_lower for kw in medical_keywords):
            return 'general_medical'
        
        return 'general'
    
    def _generate_chat_response(self, message: str, entities: List, sentiment: Dict, 
                                 query_type: str, context: Dict = None) -> Dict:
        """Generate appropriate chat response based on query type"""
        
        # Emergency detection
        if query_type == 'emergency':
            return {
                'text': "🚨 **POTENTIAL MEDICAL EMERGENCY DETECTED** 🚨\n\nBased on your description, this could be a medical emergency. Please call emergency services (911) immediately or go to the nearest emergency room. Do not wait for an online response.",
                'confidence': 0.95,
                'requires_professional': True,
                'emergency': True
            }
        
        # Symptom inquiry
        if query_type == 'symptom_inquiry':
            symptoms = [e['text'] for e in entities if e['type'] == 'SYMPTOM']
            symptom_text = ", ".join(symptoms[:3])
            
            return {
                'text': f"I understand you're experiencing {symptom_text}. While I can provide general information, it's important to consult with a healthcare provider for proper evaluation. They can consider your full medical history and perform necessary examinations.\n\nCould you tell me more about when these symptoms started and their severity?",
                'confidence': 0.85,
                'requires_professional': True,
                'emergency': False
            }
        
        # Disease inquiry
        if query_type == 'disease_inquiry':
            diseases = [e['text'] for e in entities if e['type'] == 'DISEASE']
            disease_text = ", ".join(diseases[:2])
            
            return {
                'text': f"You're asking about {disease_text}. I can provide general educational information, but please remember that treatment plans should always be discussed with your healthcare provider who knows your specific situation.\n\nWould you like to know about common symptoms, treatments, or general management strategies?",
                'confidence': 0.85,
                'requires_professional': True,
                'emergency': False
            }
        
        # Medication inquiry
        if query_type == 'medication_inquiry':
            meds = [e['text'] for e in entities if e['type'] == 'MEDICATION']
            med_text = ", ".join(meds[:2])
            
            return {
                'text': f"You're asking about {med_text}. For specific medication advice, including dosage and potential interactions, please consult your pharmacist or prescribing physician. They can provide personalized guidance based on your health profile.\n\nAre you asking about side effects, dosage, or general information?",
                'confidence': 0.80,
                'requires_professional': True,
                'emergency': False
            }
        
        # General medical
        if query_type == 'general_medical':
            # Check sentiment for empathetic response
            if sentiment.get('sentiment') == 'NEGATIVE' and sentiment.get('confidence', 0) > 0.7:
                empathy = "I sense you might be concerned. "
            else:
                empathy = ""
            
            return {
                'text': f"{empathy}I'm here to help with medical questions. Could you provide more specific details about what you'd like to know? For example, are you asking about symptoms, conditions, treatments, or general health information?",
                'confidence': 0.80,
                'requires_professional': False,
                'emergency': False
            }
        
        # Default
        return {
            'text': "I'm here to assist with medical questions. Please provide more details about your health concern so I can offer more specific information.",
            'confidence': 0.75,
            'requires_professional': False,
            'emergency': False
        }
    
    def _generate_chat_suggestions(self, message: str, entities: List, query_type: str, sentiment: Dict) -> List:
        """Generate follow-up suggestions based on query"""
        
        suggestions = []
        
        if query_type == 'symptom_inquiry':
            suggestions = [
                "When did these symptoms start?",
                "How severe are they on a scale of 1-10?",
                "What makes them better or worse?",
                "Have you seen a doctor about this?"
            ]
        elif query_type == 'disease_inquiry':
            suggestions = [
                "Are you asking about symptoms, causes, or treatments?",
                "Do you have a family history of this condition?",
                "Would you like to know about management strategies?",
                "Have you been diagnosed with this?"
            ]
        elif query_type == 'medication_inquiry':
            suggestions = [
                "Are you asking about dosage, side effects, or interactions?",
                "How long have you been taking this medication?",
                "Have you discussed this with your pharmacist?",
                "Are you experiencing any side effects?"
            ]
        elif query_type == 'general_medical':
            suggestions = [
                "What specific symptoms are you experiencing?",
                "When did your symptoms begin?",
                "Have you consulted a healthcare provider?",
                "Would you like information about a specific condition?"
            ]
        elif query_type == 'emergency':
            suggestions = [
                "Please call emergency services immediately",
                "Go to the nearest emergency room",
                "Do not wait for online advice"
            ]
        else:
            suggestions = [
                "Can you provide more details about your concern?",
                "What specific symptoms are you experiencing?",
                "When did this start?",
                "Have you seen a doctor about this?"
            ]
        
        return suggestions[:4]  # Return top 4 suggestions
    
    # ==================== MODULE 2: DISEASE PREDICTION ====================
    
    def disease_prediction(self, symptoms: str, patient_data: Dict = None) -> Dict:
        """
        Predict potential diseases based on symptoms
        Uses: BioClinicalBERT, HunFlair2 (symptom extraction), PubMedBERT (matching)
        """
        start_time = time.time()
        
        try:
            # 1. Extract symptoms from description
            entities_result = self.comprehensive_entity_extraction(symptoms)
            symptom_entities = [e for e in entities_result['entities'] if e['type'] == 'SYMPTOM']
            
            # If no symptoms found, try to extract from text directly
            if not symptom_entities:
                # Simple keyword matching
                common_symptoms = ['fever', 'cough', 'headache', 'pain', 'nausea', 'fatigue', 
                                  'dizziness', 'rash', 'swelling', 'shortness of breath']
                for word in common_symptoms:
                    if word in symptoms.lower():
                        symptom_entities.append({
                            'text': word,
                            'type': 'SYMPTOM',
                            'confidence': 0.6,
                            'model': 'keyword'
                        })
            
            symptom_text = " ".join([s['text'] for s in symptom_entities])
            
            # 2. Get embedding of symptoms
            symptom_embedding = self.get_pubmed_embeddings(symptom_text)
            
            # 3. Match against disease database (simplified rules)
            potential_diseases = self._match_diseases(symptom_entities, patient_data)
            
            # 4. Calculate risk factors
            risk_factors = self._calculate_risk_factors(patient_data, symptom_entities)
            
            # 5. Determine urgency
            urgency = self._determine_urgency(symptom_entities, potential_diseases)
            
            result = {
                'predictions': potential_diseases,
                'symptoms_detected': [s['text'] for s in symptom_entities],
                'risk_factors': risk_factors,
                'urgency': urgency,
                'recommendations': self._generate_disease_recommendations(urgency, potential_diseases),
                'confidence': self._calculate_prediction_confidence(symptom_entities, potential_diseases),
                'processing_time': time.time() - start_time,
                'models_used': entities_result['models_used'] + ['PubMedBERT'],
                'module': 'disease_prediction'
            }
            
            return result
            
        except Exception as e:
            logger.error(f"Disease prediction failed: {e}")
            return {
                'predictions': [],
                'symptoms_detected': [],
                'risk_factors': ['Unable to analyze'],
                'urgency': 'UNKNOWN',
                'recommendations': ['Please consult a healthcare provider for proper evaluation'],
                'confidence': 0.3,
                'processing_time': time.time() - start_time,
                'module': 'disease_prediction',
                'error': True
            }
    
    def _match_diseases(self, symptoms: List, patient_data: Dict = None) -> List:
        """Match symptoms to potential diseases (simplified rules)"""
        
        # Simplified disease-symptom mapping
        disease_map = {
            'Common Cold': ['cough', 'sneeze', 'runny nose', 'sore throat', 'congestion'],
            'Influenza': ['fever', 'cough', 'fatigue', 'body ache', 'headache'],
            'COVID-19': ['fever', 'cough', 'fatigue', 'loss of taste', 'loss of smell', 'shortness of breath'],
            'Strep Throat': ['sore throat', 'fever', 'swollen lymph nodes'],
            'Pneumonia': ['cough', 'fever', 'shortness of breath', 'chest pain'],
            'Bronchitis': ['cough', 'fatigue', 'shortness of breath', 'chest discomfort'],
            'Migraine': ['headache', 'nausea', 'sensitivity to light', 'sensitivity to sound'],
            'Tension Headache': ['headache', 'neck pain', 'scalp tenderness'],
            'Sinusitis': ['facial pain', 'headache', 'congestion', 'fever'],
            'Gastroenteritis': ['nausea', 'vomiting', 'diarrhea', 'abdominal pain'],
            'UTI': ['burning urination', 'frequent urination', 'cloudy urine'],
            'Allergies': ['sneeze', 'itchy eyes', 'runny nose', 'congestion']
        }
        
        symptom_texts = [s['text'].lower() if isinstance(s, dict) else s.lower() for s in symptoms]
        
        predictions = []
        for disease, disease_symptoms in disease_map.items():
            matches = 0
            for ds in disease_symptoms:
                if any(ds in st for st in symptom_texts):
                    matches += 1
            
            if matches > 0:
                probability = matches / len(disease_symptoms)
                if probability > 0.3:  # Only include if at least 30% match
                    predictions.append({
                        'disease': disease,
                        'probability': round(probability * 100, 1),
                        'matching_symptoms': matches,
                        'total_symptoms': len(disease_symptoms),
                        'severity': 'Medium' if 'fever' in str(symptom_texts) else 'Low'
                    })
        
        # Sort by probability
        predictions.sort(key=lambda x: x['probability'], reverse=True)
        
        return predictions[:5]  # Return top 5
    
    def _calculate_risk_factors(self, patient_data: Dict = None, symptoms: List = None) -> List:
        """Calculate risk factors based on patient data"""
        risk_factors = []
        
        if patient_data:
            if patient_data.get('age', 0) > 60:
                risk_factors.append('Age over 60')
            if patient_data.get('age', 0) < 2:
                risk_factors.append('Age under 2')
            if patient_data.get('smoking'):
                risk_factors.append('Smoking')
            if patient_data.get('pregnancy'):
                risk_factors.append('Pregnancy')
            if patient_data.get('chronic_conditions'):
                risk_factors.extend(patient_data.get('chronic_conditions', []))
        
        if symptoms:
            severe_symptoms = ['chest pain', 'difficulty breathing', 'severe pain', 'unconscious']
            for s in symptoms:
                if s['text'].lower() in severe_symptoms:
                    risk_factors.append(f"Severe symptom: {s['text']}")
        
        return risk_factors or ['No significant risk factors identified']
    
    def _determine_urgency(self, symptoms: List, predictions: List) -> str:
        """Determine urgency based on symptoms and predictions"""
        
        # Check for emergency symptoms
        emergency_symptoms = ['chest pain', 'difficulty breathing', 'unconscious', 'severe bleeding', 'seizure']
        for s in symptoms:
            if s['text'].lower() in emergency_symptoms:
                return 'EMERGENCY'
        
        # Check predictions for serious conditions
        serious_conditions = ['pneumonia', 'heart attack', 'stroke', 'meningitis']
        for p in predictions[:3]:
            if p['disease'].lower() in serious_conditions and p['probability'] > 50:
                return 'URGENT'
        
        # Check for high probability predictions
        if predictions and predictions[0]['probability'] > 70:
            return 'SOON'
        
        return 'ROUTINE'
    
    def _generate_disease_recommendations(self, urgency: str, predictions: List) -> List:
        """Generate recommendations based on urgency and predictions"""
        
        if urgency == 'EMERGENCY':
            return [
                "🚨 SEEK EMERGENCY CARE IMMEDIATELY",
                "Call emergency services (911) or go to nearest ER",
                "Do not wait for online consultation"
            ]
        
        if urgency == 'URGENT':
            return [
                "Seek medical attention within 24 hours",
                "Contact your healthcare provider today",
                "Monitor symptoms closely and go to ER if they worsen"
            ]
        
        recommendations = [
            "Schedule appointment with healthcare provider",
            "Monitor symptoms and track any changes",
            "Rest and maintain hydration"
        ]
        
        if predictions and predictions[0]['probability'] > 50:
            recommendations.append(f"Discuss {predictions[0]['disease']} with your doctor")
        
        return recommendations
    
    def _calculate_prediction_confidence(self, symptoms: List, predictions: List) -> float:
        """Calculate overall confidence in predictions"""
        if not symptoms or not predictions:
            return 0.3
        
        # Base confidence on number of symptoms and top prediction probability
        symptom_confidence = min(len(symptoms) * 0.1, 0.5)  # Up to 0.5 from symptoms
        prediction_confidence = predictions[0]['probability'] / 100 * 0.5 if predictions else 0
        
        return min(symptom_confidence + prediction_confidence, 0.95)
    
    # ==================== MODULE 3: LAB ANALYZER ====================
    
    def lab_analyzer(self, lab_results: Dict) -> Dict:
        """
        Analyze laboratory results and flag abnormalities
        Uses: PubMedBERT (understanding lab names), Rule-based (reference ranges)
        """
        start_time = time.time()
        
        try:
            abnormalities = []
            normal_results = []
            
            for test_name, value in lab_results.items():
                # Find matching reference range
                ref_range = self._find_reference_range(test_name)
                
                if ref_range:
                    # Check if abnormal
                    is_abnormal, severity, interpretation = self._check_lab_value(
                        value, ref_range
                    )
                    
                    result = {
                        'test': test_name,
                        'value': value,
                        'unit': ref_range.get('unit', ''),
                        'reference_range': f"{ref_range.get('min', '?')} - {ref_range.get('max', '?')}",
                        'flag': 'ABNORMAL' if is_abnormal else 'NORMAL',
                        'severity': severity if is_abnormal else 'normal',
                        'interpretation': interpretation
                    }
                    
                    if is_abnormal:
                        abnormalities.append(result)
                    else:
                        normal_results.append(result)
                else:
                    # Unknown test
                    abnormalities.append({
                        'test': test_name,
                        'value': value,
                        'unit': '',
                        'reference_range': 'Unknown',
                        'flag': 'UNKNOWN',
                        'severity': 'unknown',
                        'interpretation': 'Reference range not available'
                    })
            
            # Determine overall urgency
            urgency = self._determine_lab_urgency(abnormalities)
            
            # Get embedding for understanding (optional)
            test_names = ", ".join(lab_results.keys())
            embedding = self.get_pubmed_embeddings(test_names)
            
            result = {
                'summary': {
                    'total_tests': len(lab_results),
                    'abnormal_count': len(abnormalities),
                    'normal_count': len(normal_results),
                    'unknown_count': len([a for a in abnormalities if a['flag'] == 'UNKNOWN'])
                },
                'abnormal_results': abnormalities,
                'normal_results': normal_results[:10],  # Limit normal results
                'urgency': urgency,
                'critical_findings': [a for a in abnormalities if a['severity'] == 'critical'],
                'recommendations': self._generate_lab_recommendations(abnormalities, urgency),
                'processing_time': time.time() - start_time,
                'models_used': ['Rule-based', 'PubMedBERT'],
                'module': 'lab_analyzer'
            }
            
            return result
            
        except Exception as e:
            logger.error(f"Lab analysis failed: {e}")
            return {
                'summary': {'total_tests': 0, 'abnormal_count': 0},
                'abnormal_results': [],
                'normal_results': [],
                'urgency': 'UNKNOWN',
                'critical_findings': [],
                'recommendations': ['Unable to analyze lab results'],
                'processing_time': time.time() - start_time,
                'module': 'lab_analyzer',
                'error': True
            }
    
    def _find_reference_range(self, test_name: str) -> Dict:
        """Find reference range for a lab test"""
        test_lower = test_name.lower().strip()
        
        # Direct match
        if test_lower in self.lab_reference_ranges:
            return self.lab_reference_ranges[test_lower]
        
        # Partial match
        for key, value in self.lab_reference_ranges.items():
            if key in test_lower or test_lower in key:
                return value
        
        return None
    
    def _check_lab_value(self, value: float, ref_range: Dict) -> Tuple[bool, str, str]:
        """Check if lab value is abnormal"""
        min_val = ref_range.get('min', float('-inf'))
        max_val = ref_range.get('max', float('inf'))
        critical_low = ref_range.get('critical_low')
        critical_high = ref_range.get('critical_high')
        
        is_abnormal = False
        severity = 'normal'
        interpretation = "Within normal range"
        
        if value < min_val:
            is_abnormal = True
            if critical_low and value < critical_low:
                severity = 'critical'
                interpretation = f"CRITICALLY LOW - Below {critical_low}"
            else:
                severity = 'low'
                interpretation = f"Below normal range (min: {min_val})"
        
        elif value > max_val:
            is_abnormal = True
            if critical_high and value > critical_high:
                severity = 'critical'
                interpretation = f"CRITICALLY HIGH - Above {critical_high}"
            else:
                severity = 'high'
                interpretation = f"Above normal range (max: {max_val})"
        
        return is_abnormal, severity, interpretation
    
    def _determine_lab_urgency(self, abnormalities: List) -> str:
        """Determine urgency based on lab abnormalities"""
        
        # Check for critical abnormalities
        critical_count = sum(1 for a in abnormalities if a['severity'] == 'critical')
        if critical_count > 0:
            return 'CRITICAL'
        
        # Check for multiple abnormalities
        if len(abnormalities) > 3:
            return 'URGENT'
        elif len(abnormalities) > 0:
            return 'FOLLOW_UP'
        
        return 'NORMAL'
    
    def _generate_lab_recommendations(self, abnormalities: List, urgency: str) -> List:
        """Generate recommendations based on lab results"""
        
        if urgency == 'CRITICAL':
            return [
                "🚨 CRITICAL RESULTS - Immediate medical attention required",
                "Contact healthcare provider or go to ER immediately",
                "Bring these results with you"
            ]
        
        if urgency == 'URGENT':
            return [
                "Discuss these results with your healthcare provider within 24-48 hours",
                "Multiple abnormal results require review",
                "Do not ignore these findings"
            ]
        
        recommendations = [
            "Review results with your healthcare provider",
            "Discuss any concerns during your next appointment",
            "Keep these results for your medical records"
        ]
        
        if abnormalities:
            tests = ", ".join([a['test'] for a in abnormalities[:3]])
            recommendations.append(f"Pay special attention to: {tests}")
        
        return recommendations
    
    # ==================== MODULE 4: SYMPTOMS ANALYZER ====================
    
    def symptoms_analyzer(self, symptoms_text: str, patient_info: Dict = None) -> Dict:
        """
        Analyze symptoms and provide insights
        Uses: BioClinicalBERT, HunFlair2 (extraction), PubMedBERT (matching)
        """
        start_time = time.time()
        
        try:
            # 1. Extract symptoms
            entities_result = self.comprehensive_entity_extraction(symptoms_text)
            symptom_entities = [e for e in entities_result['entities'] if e['type'] == 'SYMPTOM']
            
            # If no symptoms found, use keyword matching
            if not symptom_entities:
                common_symptoms = ['fever', 'cough', 'headache', 'pain', 'nausea', 'fatigue', 
                                  'dizziness', 'rash', 'swelling', 'shortness of breath']
                for word in common_symptoms:
                    if word in symptoms_text.lower():
                        symptom_entities.append({
                            'text': word,
                            'type': 'SYMPTOM',
                            'confidence': 0.6,
                            'model': 'keyword'
                        })
            
            # 2. Analyze severity and urgency
            severity = self._analyze_symptom_severity(symptom_entities, symptoms_text)
            urgency = self._determine_symptom_urgency(symptom_entities, symptoms_text)
            
            # 3. Get symptom embedding for matching
            symptom_text_combined = " ".join([s['text'] for s in symptom_entities])
            symptom_embedding = self.get_pubmed_embeddings(symptom_text_combined)
            
            # 4. Find possible conditions
            possible_conditions = self._match_symptoms_to_conditions(symptom_entities)
            
            # 5. Generate recommendations
            recommendations = self._generate_symptom_recommendations(
                severity, urgency, possible_conditions
            )
            
            # 6. Check for emergency indicators
            emergency_indicators = self._check_emergency_indicators(symptoms_text)
            
            result = {
                'symptoms_detected': [{
                    'text': s['text'],
                    'confidence': s.get('confidence', 0.8),
                    'model': s.get('model', 'NER')
                } for s in symptom_entities],
                'count': len(symptom_entities),
                'severity': severity,
                'urgency': urgency,
                'possible_conditions': possible_conditions,
                'emergency_indicators': emergency_indicators,
                'recommendations': recommendations,
                'disclaimer': "This is an AI-assisted analysis. Always consult a healthcare professional.",
                'processing_time': time.time() - start_time,
                'models_used': entities_result['models_used'] + ['PubMedBERT'],
                'module': 'symptoms_analyzer'
            }
            
            return result
            
        except Exception as e:
            logger.error(f"Symptoms analysis failed: {e}")
            return {
                'symptoms_detected': [],
                'count': 0,
                'severity': 'UNKNOWN',
                'urgency': 'UNKNOWN',
                'possible_conditions': [],
                'emergency_indicators': [],
                'recommendations': ['Unable to analyze symptoms'],
                'processing_time': time.time() - start_time,
                'module': 'symptoms_analyzer',
                'error': True
            }
    
    def _analyze_symptom_severity(self, symptoms: List, text: str) -> str:
        """Analyze severity of symptoms"""
        
        severe_indicators = ['severe', 'excruciating', 'worst', 'unbearable', 'extreme']
        moderate_indicators = ['moderate', 'significant', 'bothersome']
        
        text_lower = text.lower()
        
        # Check for severe indicators
        if any(ind in text_lower for ind in severe_indicators):
            return 'SEVERE'
        
        # Check for moderate indicators
        if any(ind in text_lower for ind in moderate_indicators):
            return 'MODERATE'
        
        # Check for specific symptoms that are typically severe
        severe_symptoms = ['chest pain', 'difficulty breathing', 'unconscious', 'seizure']
        for s in symptoms:
            if s['text'].lower() in severe_symptoms:
                return 'SEVERE'
        
        return 'MILD'
    
    def _determine_symptom_urgency(self, symptoms: List, text: str) -> str:
        """Determine urgency based on symptoms"""
        
        # Emergency symptoms
        emergency_symptoms = ['chest pain', 'difficulty breathing', 'unconscious', 
                             'severe bleeding', 'seizure', 'stroke']
        
        for s in symptoms:
            if s['text'].lower() in emergency_symptoms:
                return 'EMERGENCY'
        
        # Check for severe indicators
        if 'severe' in text.lower() or 'excruciating' in text.lower():
            return 'URGENT'
        
        # Multiple symptoms
        if len(symptoms) >= 3:
            return 'SOON'
        
        return 'ROUTINE'
    
    def _match_symptoms_to_conditions(self, symptoms: List) -> List:
        """Match symptoms to possible conditions"""
        
        # Simplified condition-symptom mapping
        condition_map = {
            'Common Cold': ['cough', 'sneeze', 'runny nose', 'sore throat', 'congestion'],
            'Flu': ['fever', 'cough', 'fatigue', 'body ache', 'headache'],
            'COVID-19': ['fever', 'cough', 'fatigue', 'loss of taste', 'loss of smell'],
            'Strep Throat': ['sore throat', 'fever', 'difficulty swallowing'],
            'Allergies': ['sneeze', 'itchy eyes', 'runny nose', 'congestion'],
            'Migraine': ['headache', 'nausea', 'sensitivity to light'],
            'Sinusitis': ['facial pain', 'headache', 'congestion'],
            'Bronchitis': ['cough', 'fatigue', 'shortness of breath'],
            'Pneumonia': ['cough', 'fever', 'shortness of breath', 'chest pain'],
            'Gastroenteritis': ['nausea', 'vomiting', 'diarrhea', 'stomach pain']
        }
        
        symptom_texts = [s['text'].lower() for s in symptoms]
        
        conditions = []
        for condition, cond_symptoms in condition_map.items():
            matches = []
            for cs in cond_symptoms:
                for st in symptom_texts:
                    if cs in st or st in cs:
                        matches.append(cs)
            
            if matches:
                match_count = len(matches)
                total = len(cond_symptoms)
                match_percentage = (match_count / total) * 100
                
                if match_percentage > 30:  # Only include if >30% match
                    conditions.append({
                        'condition': condition,
                        'match_percentage': round(match_percentage, 1),
                        'matched_symptoms': matches,
                        'confidence': min(match_percentage / 100, 0.9)
                    })
        
        # Sort by match percentage
        conditions.sort(key=lambda x: x['match_percentage'], reverse=True)
        
        return conditions[:5]  # Return top 5
    
    def _generate_symptom_recommendations(self, severity: str, urgency: str, conditions: List) -> List:
        """Generate recommendations based on symptom analysis"""
        
        if urgency == 'EMERGENCY':
            return [
                "🚨 SEEK EMERGENCY CARE IMMEDIATELY",
                "Call emergency services (911) or go to nearest ER",
                "Do not wait for online consultation"
            ]
        
        if severity == 'SEVERE' or urgency == 'URGENT':
            return [
                "Seek medical attention within 24 hours",
                "Contact your healthcare provider today",
                "Monitor symptoms closely and go to ER if they worsen"
            ]
        
        recommendations = [
            "Monitor symptoms and track any changes",
            "Rest and maintain hydration",
            "Consider telemedicine consultation"
        ]
        
        if conditions and conditions[0]['match_percentage'] > 60:
            recommendations.append(f"Discuss {conditions[0]['condition']} with your healthcare provider")
        
        if len(conditions) > 2:
            recommendations.append("Multiple conditions possible - professional evaluation recommended")
        
        return recommendations
    
    def _check_emergency_indicators(self, text: str) -> List:
        """Check for emergency indicators in text"""
        emergency_indicators = []
        
        emergency_patterns = [
            ('chest pain', 'Possible heart attack - seek emergency care'),
            ('difficulty breathing', 'Respiratory distress - seek emergency care'),
            ('shortness of breath', 'Respiratory distress - seek emergency care'),
            ('unconscious', 'Loss of consciousness - seek emergency care'),
            ('seizure', 'Seizure activity - seek emergency care'),
            ('severe bleeding', 'Active bleeding - seek emergency care'),
            ('stroke', 'Stroke symptoms - seek emergency care'),
            ('cannot breathe', 'Airway emergency - seek emergency care'),
            ('choking', 'Airway obstruction - seek emergency care')
        ]
        
        text_lower = text.lower()
        
        for pattern, message in emergency_patterns:
            if pattern in text_lower:
                emergency_indicators.append(message)
        
        return emergency_indicators
    
    # ==================== MODULE 5: TEXT ANALYSIS ====================
    
    def text_analysis(self, medical_text: str, analysis_type: str = 'comprehensive') -> Dict:
        """
        Analyze medical notes, discharge summaries, clinical texts
        Uses: BioClinicalBERT, HunFlair2 (NER), PubMedBERT (embeddings), Flair (sentiment)
        """
        start_time = time.time()
        
        try:
            # 1. Extract all entities
            entities_result = self.comprehensive_entity_extraction(medical_text)
            entities = entities_result['entities']
            
            # 2. Get document embedding for categorization
            embedding = self.get_pubmed_embeddings(medical_text)
            
            # 3. Analyze sentiment
            sentiment = self.analyze_sentiment_flair(medical_text)
            
            # 4. Categorize by entity types
            entities_by_type = defaultdict(list)
            for e in entities:
                entities_by_type[e['type']].append(e)
            
            # 5. Generate summary based on entities
            summary = self._generate_text_summary(entities_by_type, medical_text)
            
            # 6. Determine document type
            doc_type = self._determine_document_type(medical_text, entities)
            
            # 7. Extract key medical concepts
            key_concepts = self._extract_key_concepts(entities)
            
            result = {
                'document_type': doc_type,
                'summary': summary,
                'entities': {
                    'total': len(entities),
                    'by_type': {
                        'diseases': len(entities_by_type.get('DISEASE', [])),
                        'symptoms': len(entities_by_type.get('SYMPTOM', [])),
                        'medications': len(entities_by_type.get('MEDICATION', [])),
                        'procedures': len(entities_by_type.get('PROCEDURE', [])),
                        'lab_tests': len(entities_by_type.get('LAB_TEST', [])),
                        'anatomy': len(entities_by_type.get('ANATOMY', [])),
                        'chemicals': len(entities_by_type.get('CHEMICAL', [])),
                        'genes': len(entities_by_type.get('GENE', []))
                    },
                    'detailed': entities[:20]  # Limit detailed entities
                },
                'key_concepts': key_concepts,
                'sentiment': sentiment,
                'text_stats': {
                    'length': len(medical_text),
                    'word_count': len(medical_text.split()),
                    'sentence_count': len(medical_text.split('.'))
                },
                'processing_time': time.time() - start_time,
                'models_used': entities_result['models_used'] + ['PubMedBERT', 'Flair Sentiment'],
                'module': 'text_analysis'
            }
            
            return result
            
        except Exception as e:
            logger.error(f"Text analysis failed: {e}")
            return {
                'document_type': 'UNKNOWN',
                'summary': 'Unable to analyze text',
                'entities': {'total': 0},
                'key_concepts': [],
                'sentiment': {'sentiment': 'NEUTRAL'},
                'text_stats': {'length': 0},
                'processing_time': time.time() - start_time,
                'module': 'text_analysis',
                'error': True
            }
    
    def _determine_document_type(self, text: str, entities: List) -> str:
        """Determine the type of medical document"""
        text_lower = text.lower()
        
        # Check for specific keywords
        if 'discharge' in text_lower or 'discharged' in text_lower:
            return 'DISCHARGE_SUMMARY'
        elif 'admission' in text_lower or 'admitted' in text_lower:
            return 'ADMISSION_NOTE'
        elif 'progress' in text_lower and 'note' in text_lower:
            return 'PROGRESS_NOTE'
        elif 'consult' in text_lower:
            return 'CONSULTATION'
        elif 'lab' in text_lower and ('result' in text_lower or 'report' in text_lower):
            return 'LAB_REPORT'
        elif 'radiology' in text_lower or 'x-ray' in text_lower or 'mri' in text_lower:
            return 'RADIOLOGY_REPORT'
        elif 'prescription' in text_lower:
            return 'PRESCRIPTION'
        elif 'surgery' in text_lower or 'operative' in text_lower:
            return 'SURGICAL_REPORT'
        
        # Check entity composition
        entity_types = [e['type'] for e in entities]
        if 'DISEASE' in entity_types and 'MEDICATION' in entity_types:
            return 'CLINICAL_NOTE'
        elif 'PROCEDURE' in entity_types:
            return 'PROCEDURE_NOTE'
        
        return 'MEDICAL_DOCUMENT'
    
    def _generate_text_summary(self, entities_by_type: Dict, text: str) -> Dict:
        """Generate structured summary from entities"""
        
        summary = {}
        
        # Diseases
        if 'DISEASE' in entities_by_type:
            diseases = list(set([e['text'] for e in entities_by_type['DISEASE']]))
            summary['conditions'] = diseases[:5]
        
        # Symptoms
        if 'SYMPTOM' in entities_by_type:
            symptoms = list(set([e['text'] for e in entities_by_type['SYMPTOM']]))
            summary['symptoms'] = symptoms[:5]
        
        # Medications
        if 'MEDICATION' in entities_by_type:
            meds = list(set([e['text'] for e in entities_by_type['MEDICATION']]))
            summary['medications'] = meds[:5]
        
        # Procedures
        if 'PROCEDURE' in entities_by_type:
            procedures = list(set([e['text'] for e in entities_by_type['PROCEDURE']]))
            summary['procedures'] = procedures[:3]
        
        # Lab tests
        if 'LAB_TEST' in entities_by_type:
            labs = list(set([e['text'] for e in entities_by_type['LAB_TEST']]))
            summary['lab_tests'] = labs[:3]
        
        # Generate narrative summary
        narrative_parts = []
        if summary.get('conditions'):
            narrative_parts.append(f"Discusses {', '.join(summary['conditions'][:2])}")
        if summary.get('symptoms'):
            narrative_parts.append(f"mentions {', '.join(summary['symptoms'][:2])}")
        if summary.get('medications'):
            narrative_parts.append(f"involves {', '.join(summary['medications'][:2])}")
        
        summary['narrative'] = "This document " + " and ".join(narrative_parts) if narrative_parts else "General medical document"
        
        return summary
    
    def _extract_key_concepts(self, entities: List) -> List:
        """Extract key medical concepts from entities"""
        concepts = []
        seen = set()
        
        for entity in entities:
            key = f"{entity['text']}_{entity['type']}"
            if key not in seen and entity['confidence'] > 0.7:
                seen.add(key)
                concepts.append({
                    'concept': entity['text'],
                    'type': entity['type'],
                    'confidence': entity['confidence']
                })
        
        return concepts[:10]  # Return top 10 concepts
    
    # ==================== MODULE 6: SAFETY ANALYSIS ====================
    
    def safety_analysis(self, document: str, document_type: str = 'general') -> Dict:
        """
        Analyze safety protocols, compliance documents, incident reports
        Uses: PubMedBERT (understanding), Flair (sentiment), Entity extraction
        """
        start_time = time.time()
        
        try:
            # 1. Extract safety-related entities
            entities_result = self.comprehensive_entity_extraction(document)
            entities = entities_result['entities']
            
            # Filter safety-relevant entities
            safety_entities = [e for e in entities if e['type'] in ['PROCEDURE', 'CHEMICAL', 'EQUIPMENT']]
            
            # 2. Analyze sentiment for concerning tone
            sentiment = self.analyze_sentiment_flair(document)
            
            # 3. Get document embedding
            embedding = self.get_pubmed_embeddings(document)
            
            # 4. Check compliance issues (simplified rules)
            compliance_issues = self._check_compliance(document, document_type)
            
            # 5. Identify safety risks
            safety_risks = self._identify_safety_risks(document, entities)
            
            # 6. Calculate compliance score
            compliance_score = self._calculate_compliance_score(document, compliance_issues)
            
            # 7. Determine risk level
            risk_level = self._determine_safety_risk_level(compliance_issues, safety_risks)
            
            result = {
                'document_type': document_type,
                'compliance_score': compliance_score,
                'risk_level': risk_level,
                'compliance_issues': compliance_issues,
                'safety_risks': safety_risks,
                'sentiment': sentiment,
                'safety_entities': safety_entities[:10],
                'recommendations': self._generate_safety_recommendations(compliance_issues, risk_level),
                'processing_time': time.time() - start_time,
                'models_used': entities_result['models_used'] + ['PubMedBERT', 'Flair Sentiment'],
                'module': 'safety_analysis'
            }
            
            return result
            
        except Exception as e:
            logger.error(f"Safety analysis failed: {e}")
            return {
                'compliance_score': 0,
                'risk_level': 'UNKNOWN',
                'compliance_issues': ['Unable to analyze'],
                'safety_risks': [],
                'recommendations': ['Manual safety review required'],
                'processing_time': time.time() - start_time,
                'module': 'safety_analysis',
                'error': True
            }
    
    def _check_compliance(self, document: str, doc_type: str) -> List:
        """Check for compliance issues in document"""
        issues = []
        doc_lower = document.lower()
        
        # General compliance keywords to check
        compliance_checks = {
            'consent': ['consent', 'agreement', 'authorization', 'signature'],
            'documentation': ['date', 'time', 'signature', 'provider', 'identifier'],
            'safety': ['protocol', 'procedure', 'guideline', 'standard', 'policy'],
            'privacy': ['hipaa', 'confidential', 'private', 'protected'],
            'medication': ['dosage', 'route', 'frequency', 'allergy']
        }
        
        for category, keywords in compliance_checks.items():
            missing = []
            for kw in keywords:
                if kw not in doc_lower:
                    missing.append(kw)
            
            if missing:
                issues.append({
                    'category': category,
                    'issue': f"Missing {category} documentation: {', '.join(missing)}",
                    'severity': 'HIGH' if category in ['consent', 'safety'] else 'MEDIUM'
                })
        
        return issues
    
    def _identify_safety_risks(self, document: str, entities: List) -> List:
        """Identify safety risks in document"""
        risks = []
        doc_lower = document.lower()
        
        # Risk keywords
        risk_patterns = [
            ('fall', 'Fall risk'),
            ('bleeding', 'Bleeding risk'),
            ('infection', 'Infection risk'),
            ('allergy', 'Allergy risk'),
            ('reaction', 'Adverse reaction risk'),
            ('error', 'Potential error'),
            ('miscommunication', 'Communication risk'),
            ('delay', 'Delay in care risk')
        ]
        
        for pattern, risk_desc in risk_patterns:
            if pattern in doc_lower:
                risks.append({
                    'risk': risk_desc,
                    'severity': 'HIGH',
                    'evidence': f"Mentions '{pattern}'"
                })
        
        # Check for medication-related risks
        medication_entities = [e for e in entities if e['type'] == 'MEDICATION']
        if medication_entities:
            risks.append({
                'risk': 'Medication-related risk',
                'severity': 'MEDIUM',
                'evidence': f"Discusses {len(medication_entities)} medications"
            })
        
        return risks
    
    def _calculate_compliance_score(self, document: str, issues: List) -> int:
        """Calculate compliance score (0-100)"""
        base_score = 100
        
        # Deduct for issues
        for issue in issues:
            if issue.get('severity') == 'HIGH':
                base_score -= 15
            else:
                base_score -= 5
        
        # Check document length/completeness
        word_count = len(document.split())
        if word_count < 50:
            base_score -= 20
        elif word_count < 100:
            base_score -= 10
        
        return max(base_score, 0)
    
    def _determine_safety_risk_level(self, compliance_issues: List, safety_risks: List) -> str:
        """Determine overall safety risk level"""
        
        # Check for high severity issues
        high_severity = any(i.get('severity') == 'HIGH' for i in compliance_issues)
        if high_severity:
            return 'HIGH'
        
        # Check number of issues
        total_issues = len(compliance_issues) + len(safety_risks)
        if total_issues > 5:
            return 'HIGH'
        elif total_issues > 2:
            return 'MEDIUM'
        elif total_issues > 0:
            return 'LOW'
        
        return 'MINIMAL'
    
    def _generate_safety_recommendations(self, compliance_issues: List, risk_level: str) -> List:
        """Generate safety recommendations"""
        
        if risk_level == 'HIGH':
            recommendations = [
                "🚨 IMMEDIATE SAFETY REVIEW REQUIRED",
                "Conduct comprehensive safety audit within 24 hours",
                "Review all compliance documentation",
                "Implement corrective actions immediately"
            ]
        elif risk_level == 'MEDIUM':
            recommendations = [
                "Schedule safety review within 1 week",
                "Address identified compliance gaps",
                "Update safety protocols as needed",
                "Conduct staff training on identified issues"
            ]
        elif risk_level == 'LOW':
            recommendations = [
                "Review safety documentation during next routine audit",
                "Monitor for recurring issues",
                "Consider preventive measures"
            ]
        else:
            recommendations = [
                "Continue current safety practices",
                "Maintain regular documentation",
                "Schedule periodic safety reviews"
            ]
        
        # Add specific recommendations from issues
        for issue in compliance_issues[:2]:
            recommendations.append(f"Address: {issue['issue']}")
        
        return recommendations[:5]  # Return top 5 recommendations
    
    # ==================== STATUS AND UTILITY METHODS ====================
    
    def get_status(self) -> Dict:
        """Get system status"""
        return {
            'models': {
                name: self.model_status.get(name, 'unknown')
                for name in ['bio_clinical_bert', 'pubmed_bert', 'flair_sentiment', 
                            'hunflair_v1', 'hunflair_v2']
            },
            'device': self.model_config['device'],
            'modules': ['medical_chat', 'disease_prediction', 'lab_analyzer', 
                       'symptoms_analyzer', 'text_analysis', 'safety_analysis'],
            'gpu_available': torch.cuda.is_available(),
            'timestamp': datetime.utcnow().isoformat()
        }
    
    def is_model_available(self, model_name):
        """Check if a specific model is available"""
        model = self.models.get(model_name)
        return model is not None and self.model_status.get(model_name) == 'loaded'


