# ==================== KEEP YOUR EXACT SAFETYPRO DECORATOR ====================

def safetypro_required(f):
    """
    JWT authentication for SafetyPro system administrators only
    WITH DEBUG - KEEPING YOUR EXACT IMPLEMENTATION
    """
    print(f"\n🎯 DEBUG: Creating safetypro_required decorator for {f.__name__}")
    
    @wraps(f)
    def inner_wrapper(*args, **kwargs):
        print(f"\n🎯 DEBUG: safetypro_required wrapper called for {f.__name__}")
        print(f"🎯 Path: {request.path}")
        print(f"🎯 Method: {request.method}")
        
        # Apply jwt_required to this specific call
        @wraps(f)
        def jwt_wrapped_function(*inner_args, **inner_kwargs):
            print(f"\n🎯 DEBUG: Inside jwt_wrapped_function for {f.__name__}")
            
            # First authenticate with jwt_required
            print(f"🎯 Applying jwt_required authentication...")
            
            # Call jwt_required on our function
            jwt_decorated = jwt_required(f)
            result = jwt_decorated(*inner_args, **inner_kwargs)
            
            # If authentication failed, return the error
            if isinstance(result, tuple) and len(result) > 1 and result[1] == 401:
                print(f"🎯 ❌ JWT authentication failed")
                return result
            
            print(f"🎯 ✅ JWT authentication successful")
            
            # Now check if user is SafetyPro team
            print(f"\n🎯 CHECKING SAFETYPRO ACCESS:")
            print(f"  request.is_system_team = {getattr(request, 'is_system_team', 'NOT SET')}")
            print(f"  request.user_type = {getattr(request.user, 'user_type', 'NOT SET') if hasattr(request, 'user') else 'NO USER'}")
            
            if not getattr(request, 'is_system_team', False):
                print(f"🎯 ❌ ACCESS DENIED: Not SafetyPro team")
                return jsonify({
                    'success': False,
                    'error': 'Access restricted to SafetyPro system administrators',
                    'code': 'ACCESS_DENIED',
                    'debug_info': {
                        'user_type': getattr(request.user, 'user_type', 'unknown'),
                        'admin_role': getattr(request.user, 'admin_role', None),
                        'admin_level': getattr(request.user, 'admin_level', None),
                        'is_system_team': getattr(request, 'is_system_team', False),
                        'endpoint': request.path
                    }
                }), 403
            
            print(f"🎯 ✅ ACCESS GRANTED: User is SafetyPro team member")
            return result
        
        # Call the jwt-wrapped function
        print(f"🎯 Executing jwt_wrapped_function...")
        return jwt_wrapped_function(*args, **kwargs)
    
    print(f"🎯 DEBUG: Returning wrapper for {f.__name__}")
    return inner_wrapper

# ==================== ENHANCED CHECK FEATURE ACCESS ====================

def check_feature_access(feature_name, required_plan='basic'):
    """
    ENHANCED decorator - now uses normalized plans
    """
    def decorator(f):
        @wraps(f)
        @jwt_required
        def decorated_function(*args, **kwargs):
            user = request.user
            
            # System team has unlimited access
            if request.is_system_team:
                return f(*args, **kwargs)
            
            # Check using NORMALIZED plan levels
            user_plan_level = PLAN_HIERARCHY.get(request.effective_plan, 0)
            required_plan_level = PLAN_HIERARCHY.get(required_plan, 0)
            
            if user_plan_level < required_plan_level:
                # Get pricing for user's country
                user_country = request.user_country
                country_pricing = COUNTRY_PRICING.get(user_country, COUNTRY_PRICING['default'])
                required_plan_pricing = country_pricing.get(required_plan, {})
                
                return jsonify({
                    'success': False,
                    'error': f'This feature requires {required_plan} plan or higher',
                    'code': 'UPGRADE_REQUIRED',
                    'current_plan': request.effective_plan,
                    'required_plan': required_plan,
                    'feature': feature_name,
                    'pricing': {
                        'currency': required_plan_pricing.get('currency', 'USD'),
                        'monthly': required_plan_pricing.get('1_month', 'N/A'),
                        'yearly': required_plan_pricing.get('1_year', 'N/A')
                    },
                    'upgrade_url': f'/pricing?country={user_country}&plan={required_plan}'
                }), 403
            
            return f(*args, **kwargs)
        
        return decorated_function
    return decorator

# ==================== ENHANCED CHECK USAGE LIMIT ====================

def check_usage_limit(limit_type, amount=1):
    """
    ENHANCED decorator - now uses normalized plan limits
    """
    def decorator(f):
        @wraps(f)
        @jwt_required
        def decorated_function(*args, **kwargs):
            from app import db
            
            user = request.user
            
            # System team has no limits
            if request.is_system_team:
                return f(*args, **kwargs)
            
            # Map limit types to standardized fields
            limit_field_map = {
                'uploads': 'uploads_per_month',
                'api_calls': 'api_calls_per_month',
                'ai_requests': 'ai_requests_per_month',
                'video_minutes': 'video_analysis_minutes',
                'team_members': 'team_members',
                'monitoring_stations': 'monitoring_stations',
                'camera_feeds': 'camera_feeds'
            }
            
            limit_field = limit_field_map.get(limit_type)
            
            if not limit_field:
                return f(*args, **kwargs)
            
            # Get limit from NORMALIZED plan data
            limit = request.plan_limits.get(limit_field)
            
            # Unlimited plan check
            if limit == "Unlimited" or limit == -1:
                return f(*args, **kwargs)
            
            # Get current usage
            usage_field_map = {
                'uploads_per_month': 'monthly_uploads_used',
                'api_calls_per_month': 'monthly_api_calls_used',
                'ai_requests_per_month': 'monthly_ai_requests_used',
                'video_analysis_minutes': 'monthly_video_minutes_used'
            }
            
            usage_field = usage_field_map.get(limit_field)
            current_usage = getattr(user, usage_field, 0) if usage_field else 0
            
            # Check if limit will be exceeded
            if current_usage + amount > limit:
                return jsonify({
                    'success': False,
                    'error': f'Monthly {limit_type.replace("_", " ")} limit exceeded',
                    'code': f'{limit_type.upper()}_LIMIT_EXCEEDED',
                    'current_used': current_usage,
                    'monthly_limit': limit,
                    'attempted_amount': amount,
                    'current_plan': request.effective_plan,
                    'upgrade_url': f'/pricing?country={request.user_country}'
                }), 403
            
            # Process the request
            response = f(*args, **kwargs)
            
            # If successful, track usage
            if response and hasattr(response, 'status_code') and response.status_code == 200:
                if usage_field:
                    setattr(user, usage_field, getattr(user, usage_field, 0) + amount)
                    db.session.commit()
            
            return response
        
        return decorated_function
    return decorator

