def get_user_company_id(user):
    """Get user's company_id with fallback"""
    if not user:
        return None
    
    # Check if user has company_id
    company_id = getattr(user, 'company_id', None)
    
    # If user has no company, check if they're a super admin or system team
    if not company_id:
        if hasattr(user, 'is_super_admin') and user.is_super_admin:
            # Super admin can access all companies, return None to bypass filter
            return None
        if hasattr(user, 'is_system_team') and user.is_system_team:
            return None
    
    return company_id

def has_environmental_access(user, data_company_id=None):
    """
    Check if user has access to environmental data
    Returns: (has_access, company_id_to_filter)
    """
    if not user:
        return False, None
    
    # Super admin bypass
    if hasattr(user, 'is_super_admin') and user.is_super_admin:
        return True, None
    
    # System team bypass
    if hasattr(user, 'is_system_team') and user.is_system_team:
        return True, None
    
    # Platform owner bypass
    if hasattr(user, 'is_platform_owner') and user.is_platform_owner:
        return True, None
    
    # Check if user has a company
    company_id = getattr(user, 'company_id', None)
    
    if not company_id:
        return False, None
    
    # If data_company_id is provided, check if user has access to that specific company
    if data_company_id and data_company_id != company_id:
        return False, None
    
    # Check user's plan for environmental access
    effective_plan = get_effective_plan_for_user(user)
    
    # Enterprise, business, and custom plans have full environmental access
    if effective_plan in ['enterprise', 'business', 'custom']:
        return True, company_id
    
    # Pro users have limited environmental access
    if effective_plan == 'pro':
        # Check if user has environmental feature access
        if has_feature_access('environmental_intelligence'):
            return True, company_id
        return False, None
    
    # Free and basic users have limited access
    if effective_plan in ['free', 'basic']:
        # Free users can only view basic environmental data
        return True, company_id
    
    return False, None

def get_effective_plan_for_user(user):
    """Get user's effective plan"""
    if not user:
        return 'free'
    
    # Check for company plan first
    if hasattr(user, 'company_id') and user.company_id:
        from models import Company
        company = Company.query.get(user.company_id)
        if company and company.plan:
            return company.plan.lower()
    
    # Check user's subscription plan
    if hasattr(user, 'subscription_plan') and user.subscription_plan:
        return user.subscription_plan.lower()
    
    if hasattr(user, 'plan') and user.plan:
        return user.plan.lower()
    
    return 'free'

def can_user_access_environmental_data(user, data_company_id=None, data_user_id=None):
    """
    Comprehensive check if user can access environmental data
    Returns: (has_access, company_id_to_filter)
    """
    if not user:
        return False, None
    
    # Super admin - full access
    if hasattr(user, 'is_super_admin') and user.is_super_admin:
        return True, None
    
    # System team - full access
    if hasattr(user, 'is_system_team') and user.is_system_team:
        return True, None
    
    # Platform owner - full access
    if hasattr(user, 'is_platform_owner') and user.is_platform_owner:
        return True, None
    
    user_company_id = getattr(user, 'company_id', None)
    
    # If user has no company, they can't access anything
    if not user_company_id:
        return False, None
    
    # If data belongs to a specific company, check if user belongs to it
    if data_company_id and data_company_id != user_company_id:
        return False, None
    
    # If data belongs to a specific user, check if it's the current user
    if data_user_id and data_user_id != user.id:
        # Unless user has admin permissions
        user_type = getattr(user, 'user_type', '')
        if user_type not in ['admin', 'safetypro']:
            return False, None
    
    # Check plan access
    effective_plan = get_effective_plan_for_user(user)
    
    # Enterprise, business, custom - full access
    if effective_plan in ['enterprise', 'business', 'custom']:
        return True, user_company_id
    
    # Pro - limited access
    if effective_plan == 'pro':
        return True, user_company_id
    
    # Free, basic - view only
    if effective_plan in ['free', 'basic']:
        return True, user_company_id
    
    return False, None

def filter_by_company(query, model, user):
    """Apply company filter to query"""
    if not user or not query:
        return query
    
    # Super admin sees all
    if hasattr(user, 'is_super_admin') and user.is_super_admin:
        return query
    
    # System team sees all
    if hasattr(user, 'is_system_team') and user.is_system_team:
        return query
    
    company_id = getattr(user, 'company_id', None)
    if company_id:
        return query.filter_by(company_id=company_id)
    
    # If user has no company, return empty query
    return query.filter(False)


# Update your EnvironmentalModelManager class in app.py
class EnvironmentalModelManager:
    def __init__(self):
        self.models = {}
        self.load_models()
    
    def load_models(self):
        """Load all pre-trained environmental models with correct file names"""
        try:
            print("🔄 Loading environmental AI models...")
            
            # Load scikit-learn models with correct file names
            model_files = {
                'air_quality': 'ml_models/air_quality_rf.pkl',
                'water_quality': 'ml_models/water_quality_rf.pkl', 
                'risk_assessment': 'ml_models/risk_assessment_rf.pkl'  # This matches your file
            }
            
            for model_name, file_path in model_files.items():
                try:
                    self.models[model_name] = joblib.load(file_path)
                    print(f"✅ Loaded {model_name} from {file_path}")
                except FileNotFoundError:
                    print(f"⚠️  {file_path} not found, will create fallback")
            
            # Load scalers if they exist
            scaler_files = {
                'scaler_air': 'ml_models/scaler_air.pkl',
                'scaler_water': 'ml_models/scaler_water.pkl'
            }
            
            for scaler_name, file_path in scaler_files.items():
                try:
                    self.models[scaler_name] = joblib.load(file_path)
                    print(f"✅ Loaded {scaler_name}")
                except FileNotFoundError:
                    print(f"⚠️  {scaler_name} not found, will create dynamically")
            
            # Load transformer models if they exist
            transformer_models = {
                'environmental_ner': 'ml_models/environmental_ner',
                'climate_bert': 'ml_models/climate_bert'
            }
            
            for model_name, model_path in transformer_models.items():
                try:
                    if os.path.exists(model_path):
                        self.models[model_name] = AutoModel.from_pretrained(model_path)
                        self.models[f'{model_name}_tokenizer'] = AutoTokenizer.from_pretrained(model_path)
                        print(f"✅ Loaded {model_name} from {model_path}")
                    else:
                        print(f"⚠️  {model_path} directory not found")
                except Exception as e:
                    print(f"⚠️  Error loading {model_name}: {e}")
            
            # Create missing models
            self.create_missing_models()
            
            print("✅ All environmental models loaded successfully!")
            
        except Exception as e:
            print(f"❌ Error loading models: {e}")
            self.create_fallback_models()
    
    def create_missing_models(self):
        """Create any missing models that weren't found"""
        from sklearn.ensemble import RandomForestRegressor
        from sklearn.preprocessing import StandardScaler
        import numpy as np
        
        # Create air quality model if missing
        if 'air_quality' not in self.models:
            print("🔄 Creating air quality model...")
            self.models['air_quality'] = RandomForestRegressor(n_estimators=100, random_state=42)
            # Train with realistic environmental data ranges
            X_air = np.random.rand(1000, 5) * np.array([100, 200, 1000, 50, 100])  # PM2.5, PM10, CO2, temp, humidity
            y_air = 20 + np.random.rand(1000) * 80  # AQI range 20-100
            self.models['air_quality'].fit(X_air, y_air)
            
            # Save for future use
            try:
                joblib.dump(self.models['air_quality'], 'ml_models/air_quality_rf.pkl')
                print("💾 Saved air quality model")
            except:
                print("⚠️  Could not save air quality model")
        
        # Create water quality model if missing
        if 'water_quality' not in self.models:
            print("🔄 Creating water quality model...")
            self.models['water_quality'] = RandomForestRegressor(n_estimators=100, random_state=42)
            X_water = np.random.rand(1000, 4) * np.array([4, 10, 2000, 40])  # pH, turbidity, conductivity, temp
            y_water = 50 + np.random.rand(1000) * 50  # Water quality score 50-100
            self.models['water_quality'].fit(X_water, y_water)
            
            try:
                joblib.dump(self.models['water_quality'], 'ml_models/water_quality_rf.pkl')
                print("💾 Saved water quality model")
            except:
                print("⚠️  Could not save water quality model")
        
        # Create risk assessment model if missing
        if 'risk_assessment' not in self.models:
            print("🔄 Creating risk assessment model...")
            self.models['risk_assessment'] = RandomForestRegressor(n_estimators=100, random_state=42)
            X_risk = np.random.rand(1000, 6) * 100  # Multiple risk factors
            y_risk = np.random.rand(1000) * 100  # Risk score 0-100
            self.models['risk_assessment'].fit(X_risk, y_risk)
            
            try:
                joblib.dump(self.models['risk_assessment'], 'ml_models/risk_assessment_rf.pkl')
                print("💾 Saved risk assessment model")
            except:
                print("⚠️  Could not save risk assessment model")
        
        # Create scalers if missing
        if 'scaler_air' not in self.models:
            print("🔄 Creating air quality scaler...")
            self.models['scaler_air'] = StandardScaler()
            # Fit with realistic ranges
            sample_air_data = np.random.rand(100, 5) * np.array([100, 200, 1000, 50, 100])
            self.models['scaler_air'].fit(sample_air_data)
        
        if 'scaler_water' not in self.models:
            print("🔄 Creating water quality scaler...")
            self.models['scaler_water'] = StandardScaler()
            sample_water_data = np.random.rand(100, 4) * np.array([4, 10, 2000, 40])
            self.models['scaler_water'].fit(sample_water_data)
    
    def create_fallback_models(self):
        """Create simple fallback models if loading fails completely"""
        from sklearn.ensemble import RandomForestRegressor
        from sklearn.preprocessing import StandardScaler
        import numpy as np
        
        print("🔄 Creating comprehensive fallback models...")
        
        # Create all models from scratch
        self.create_missing_models()
        
        print("✅ All fallback models created successfully!")

def extract_text_from_file(file_path, file_type):
    """Enhanced text extraction from various file types with error handling"""
    try:
        if file_type == 'pdf':
            with pdfplumber.open(file_path) as pdf:
                text = '\n'.join([page.extract_text() or '' for page in pdf.pages])
            return text.strip()
        
        elif file_type in ['doc', 'docx']:
            try:
                doc = DocxDocument(file_path)
                return '\n'.join([para.text for para in doc.paragraphs])
            except Exception as e:
                logger.warning(f"Error reading Word document: {e}")
                return ""
        
        elif file_type in ['xls', 'xlsx']:
            try:
                df = pd.read_excel(file_path)
                return df.to_string()
            except Exception as e:
                logger.warning(f"Error reading Excel file: {e}")
                return ""
        
        elif file_type == 'csv':
            try:
                df = pd.read_csv(file_path)
                return df.to_string()
            except Exception as e:
                logger.warning(f"Error reading CSV file: {e}")
                return ""
        
        elif file_type in ['jpg', 'jpeg', 'png', 'bmp', 'tiff']:
            return extract_text_from_image(file_path)
        
        else:  # txt and other text files
            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    return f.read()
            except UnicodeDecodeError:
                with open(file_path, 'r', encoding='latin-1', errors='ignore') as f:
                    return f.read()
                
    except Exception as e:
        logger.error(f"Error extracting text from {file_path}: {e}")
        return ""

def extract_text_from_image(image_path):
    """Extract text from image using OCR"""
    try:
        # Try Google Cloud Vision first
        if app.config['CLOUD_VISION_CREDENTIALS'] and os.path.exists(app.config['CLOUD_VISION_CREDENTIALS']):
            try:
                client = vision.ImageAnnotatorClient()
                with io.open(image_path, 'rb') as image_file:
                    content = image_file.read()
                image = vision.Image(content=content)
                response = client.text_detection(image=image)
                texts = response.text_annotations
                if texts:
                    return texts[0].description
            except Exception as e:
                logger.warning(f"Google Cloud Vision OCR failed: {e}")
        
        # Fallback to Tesseract (if available)
        try:
            import pytesseract
            from PIL import Image
            image = Image.open(image_path)
            text = pytesseract.image_to_string(image)
            return text.strip()
        except ImportError:
            logger.warning("Tesseract not available for OCR")
        
        return ""
        
    except Exception as e:
        logger.error(f"OCR failed for {image_path}: {e}")
        return ""

def analyze_text_with_ai(text, doc_type, iso_standard, language):
    """Enhanced AI text analysis with multiple models and comprehensive results"""
    results = {
        "summary": "",
        "compliance_issues": [],
        "recommendations": [],
        "entities": [],
        "symptoms": [],
        "sentiment": "",
        "risk_score": 0,
        "compliance_score": 0,
        "key_findings": [],
        "analysis_timestamp": datetime.utcnow().isoformat()
    }

    try:
        # Text preprocessing
        clean_text = text.strip()
        if not clean_text:
            return results

        # Summarization
        if summarizer and len(clean_text) > 100:
            try:
                max_chunk_size = 1024
                text_chunks = [clean_text[i:i+max_chunk_size] for i in range(0, len(clean_text), max_chunk_size)]
                summaries = []
                
                for chunk in text_chunks[:3]:  # Limit to first 3 chunks
                    summary = summarizer(chunk, max_length=150, min_length=30, do_sample=False)
                    summaries.append(summary[0]['summary_text'])
                
                results["summary"] = " ".join(summaries)
            except Exception as e:
                logger.error(f"Summarization error: {e}")
                results["summary"] = clean_text[:500] + "..." if len(clean_text) > 500 else clean_text

        # Medical NER for healthcare documents
        if medical_ner and len(clean_text) > 10 and doc_type.lower() in ['clinical', 'medical', 'patient']:
            try:
                entities = medical_ner(clean_text[:512])
                results["entities"] = [
                    {
                        "text": ent['word'], 
                        "type": ent['entity_group'], 
                        "score": float(ent['score']),
                        "start": ent.get('start', 0),
                        "end": ent.get('end', 0)
                    }
                    for ent in entities if ent['score'] > 0.7
                ]
            except Exception as e:
                logger.error(f"Medical NER error: {e}")

        # Symptom analysis for clinical documents
        if symptom_analyzer and doc_type.lower() in ['clinical', 'patient', 'medical']:
            try:
                symptoms = symptom_analyzer(clean_text[:512])
                results["symptoms"] = [
                    {"label": s['label'], "score": float(s['score'])} 
                    for s in symptoms[0] if s['score'] > 0.3
                ]
            except Exception as e:
                logger.error(f"Symptom analysis error: {e}")

        # Sentiment analysis
        if sentiment_analyzer and len(clean_text) > 10:
            try:
                sentiment = sentiment_analyzer(clean_text[:512])
                results["sentiment"] = sentiment[0]['label']
            except Exception as e:
                logger.error(f"Sentiment analysis error: {e}")

        # Enhanced compliance analysis
        if iso_standard:
            compliance_analysis = analyze_compliance(clean_text, iso_standard, doc_type)
            results["compliance_score"] = compliance_analysis["score"]
            results["compliance_issues"] = compliance_analysis["issues"]
            results["recommendations"] = compliance_analysis["recommendations"]

        # Risk assessment
        risk_analysis = assess_risk(clean_text, doc_type)
        results["risk_score"] = risk_analysis["score"]
        results["key_findings"] = risk_analysis["findings"]

        # Add industry-specific analysis
        industry_analysis = analyze_industry_specific(clean_text, doc_type)
        results.update(industry_analysis)

    except Exception as e:
        logger.error(f"AI analysis error: {e}")
        # Provide basic analysis as fallback
        results["summary"] = clean_text[:300] + "..." if len(clean_text) > 300 else clean_text
        results["risk_score"] = 50
        results["compliance_score"] = 50

    return results

def analyze_compliance(text, standard, doc_type):
    """Enhanced compliance analysis with standard-specific rules"""
    issues = []
    recommendations = []
    base_score = 75  # Start with assumption of partial compliance
    
    # Standard-specific keyword analysis
    standard_keywords = {
        "ISO 45001": ["risk assessment", "hazard identification", "safety policy", "emergency preparedness", 
                      "management review", "worker participation", "incident investigation"],
        "ISO 9001": ["quality policy", "quality objectives", "process approach", "continuous improvement",
                    "customer focus", "evidence-based decision making", "relationship management"],
        "ISO 14001": ["environmental policy", "environmental aspects", "compliance obligations", 
                     "environmental objectives", "life cycle perspective", "environmental management"]
    }
    
    keywords = standard_keywords.get(standard, [])
    found_keywords = []
    
    text_lower = text.lower()
    for keyword in keywords:
        if keyword in text_lower:
            found_keywords.append(keyword)
            base_score += 3  # Bonus for each required element found
        else:
            issues.append(f"Missing reference to: {keyword}")
            recommendations.append(f"Include documentation for: {keyword}")
    
    # Document type specific checks
    if doc_type.lower() in ['risk_assessment', 'safety']:
        risk_indicators = ['hazard', 'risk', 'danger', 'incident', 'accident', 'injury']
        risk_count = sum(1 for indicator in risk_indicators if indicator in text_lower)
        if risk_count == 0:
            issues.append("No risk-related terminology found")
            recommendations.append("Include hazard identification and risk assessment sections")
    
    # Calculate final score
    compliance_score = min(100, base_score)
    
    if compliance_score < 60:
        issues.append(f"Low compliance with {standard} requirements")
        recommendations.append(f"Conduct comprehensive {standard} gap analysis")
    elif compliance_score > 85:
        recommendations.append(f"Good compliance with {standard}. Maintain documentation and conduct regular reviews")
    
    return {
        "score": compliance_score,
        "issues": issues,
        "recommendations": recommendations,
        "found_requirements": found_keywords
    }

def assess_risk(text, doc_type):
    """Enhanced risk assessment with multiple factors"""
    text_lower = text.lower()
    risk_factors = {
        'high_risk_terms': ['emergency', 'critical', 'urgent', 'immediate', 'danger', 'hazard', 'unsafe'],
        'medium_risk_terms': ['caution', 'warning', 'attention', 'review', 'investigate', 'incident'],
        'low_risk_terms': ['routine', 'normal', 'standard', 'procedure', 'guideline']
    }
    
    risk_score = 50  # Base score
    
    # Count risk terms
    high_count = sum(1 for term in risk_factors['high_risk_terms'] if term in text_lower)
    medium_count = sum(1 for term in risk_factors['medium_risk_terms'] if term in text_lower)
    low_count = sum(1 for term in risk_factors['low_risk_terms'] if term in text_lower)
    
    # Adjust score based on term frequency
    risk_score += high_count * 10
    risk_score += medium_count * 5
    risk_score -= low_count * 3
    
    # Document type modifiers
    doc_type_modifiers = {
        'incident_report': 20,
        'risk_assessment': 15,
        'safety_audit': 10,
        'procedure': -10,
        'policy': -5
    }
    
    risk_score += doc_type_modifiers.get(doc_type.lower(), 0)
    
    # Ensure score is within bounds
    risk_score = max(0, min(100, risk_score))
    
    findings = []
    if high_count > 0:
        findings.append(f"Found {high_count} high-risk terms indicating urgent attention needed")
    if risk_score > 70:
        findings.append("High risk level detected - immediate review recommended")
    elif risk_score > 40:
        findings.append("Moderate risk level - scheduled review recommended")
    else:
        findings.append("Low risk level - maintain current controls")
    
    return {
        "score": risk_score,
        "findings": findings,
        "term_counts": {
            "high_risk": high_count,
            "medium_risk": medium_count,
            "low_risk": low_count
        }
    }

def analyze_industry_specific(text, doc_type):
    """Industry-specific analysis"""
    analysis = {}
    text_lower = text.lower()
    
    # Healthcare specific analysis
    healthcare_terms = ['patient', 'medical', 'clinical', 'treatment', 'diagnosis', 'prescription']
    if any(term in text_lower for term in healthcare_terms):
        analysis["industry"] = "Healthcare"
        # Add healthcare specific insights
    
    # Construction specific analysis
    construction_terms = ['construction', 'site', 'scaffold', 'excavation', 'crane', 'hardhat']
    if any(term in text_lower for term in construction_terms):
        analysis["industry"] = "Construction"
    
    return analysis

def generate_pdf_report(data, filename, company_name=None, company_logo_path=None):
    """Enhanced PDF report generation with professional formatting"""
    pdf = FPDF()
    pdf.add_page()
    
    # Set up fonts
    pdf.set_font("Arial", size=10)
    
    # Add company logo if available
    if company_logo_path and os.path.exists(company_logo_path):
        try:
            pdf.image(company_logo_path, x=10, y=8, w=30)
            pdf.set_y(40)  # Move down after logo
        except Exception as e:
            logger.warning(f"Could not add company logo: {e}")
    
    # Title
    pdf.set_font("Arial", 'B', 16)
    title = f"{company_name} - Safety Analysis Report" if company_name else "SafetyTrack Pro Analysis Report"
    pdf.cell(200, 10, txt=title, ln=1, align='C')
    pdf.ln(10)
    
    # Report metadata
    pdf.set_font("Arial", size=10)
    pdf.cell(0, 8, txt=f"Generated: {datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S UTC')}", ln=1)
    if data.get('analysis_timestamp'):
        pdf.cell(0, 8, txt=f"Analysis Date: {data['analysis_timestamp']}", ln=1)
    pdf.ln(5)
    
    # Executive Summary
    pdf.set_font("Arial", 'B', 14)
    pdf.cell(0, 10, txt="Executive Summary", ln=1)
    pdf.set_font("Arial", size=10)
    if data.get('summary'):
        pdf.multi_cell(0, 8, txt=data['summary'])
    else:
        pdf.multi_cell(0, 8, txt="No summary available for this analysis.")
    pdf.ln(5)
    
    # Risk Assessment
    pdf.set_font("Arial", 'B', 14)
    pdf.cell(0, 10, txt="Risk Assessment", ln=1)
    pdf.set_font("Arial", size=10)
    
    risk_score = data.get('risk_score', 0)
    risk_level = "Low" if risk_score < 40 else "Medium" if risk_score < 70 else "High"
    risk_color = (0, 128, 0) if risk_score < 40 else (255, 165, 0) if risk_score < 70 else (255, 0, 0)
    
    pdf.set_text_color(*risk_color)
    pdf.cell(0, 8, txt=f"Risk Score: {risk_score}/100 ({risk_level} Risk)", ln=1)
    pdf.set_text_color(0, 0, 0)  # Reset to black
    
    if data.get('key_findings'):
        pdf.multi_cell(0, 8, txt="Key Findings:")
        for finding in data['key_findings'][:5]:  # Limit to 5 findings
            pdf.multi_cell(0, 8, txt=f"• {finding}")
    pdf.ln(5)
    
    # Compliance Assessment
    if data.get('compliance_score') is not None:
        pdf.set_font("Arial", 'B', 14)
        pdf.cell(0, 10, txt="Compliance Assessment", ln=1)
        pdf.set_font("Arial", size=10)
        pdf.cell(0, 8, txt=f"Compliance Score: {data['compliance_score']}/100", ln=1)
        
        if data.get('compliance_issues'):
            pdf.multi_cell(0, 8, txt="Compliance Issues:")
            for issue in data['compliance_issues'][:5]:  # Limit to 5 issues
                pdf.multi_cell(0, 8, txt=f"• {issue}")
        pdf.ln(5)
    
    # Recommendations
    if data.get('recommendations'):
        pdf.set_font("Arial", 'B', 14)
        pdf.cell(0, 10, txt="Recommendations", ln=1)
        pdf.set_font("Arial", size=10)
        for i, recommendation in enumerate(data['recommendations'][:10], 1):  # Limit to 10 recommendations
            pdf.multi_cell(0, 8, txt=f"{i}. {recommendation}")
        pdf.ln(5)
    
    # Entities (if available)
    if data.get('entities'):
        pdf.set_font("Arial", 'B', 14)
        pdf.cell(0, 10, txt="Identified Entities", ln=1)
        pdf.set_font("Arial", size=10)
        for entity in data['entities'][:15]:  # Limit to 15 entities
            pdf.cell(0, 8, txt=f"{entity['text']} ({entity['type']}, {entity['score']:.2f})", ln=1)
        pdf.ln(5)
    
    # Footer
    pdf.set_y(-30)
    pdf.set_font("Arial", 'I', 8)
    pdf.cell(0, 10, txt="Confidential - For authorized use only", ln=1, align='C')
    pdf.cell(0, 10, txt="Generated by SafetyTrack Pro - AI-Powered Safety Management System", ln=1, align='C')
    
    # Save to file
    try:
        pdf.output(filename)
        return filename
    except Exception as e:
        logger.error(f"Error generating PDF: {e}")
        raise



