def get_effective_plan(user):
    """Returns the plan the user should have access to RIGHT NOW, considering trials."""
    if user.trial_ends_at and datetime.utcnow() < user.trial_ends_at:
        return user.trial_plan
    else:
        return user.plan

def check_usage_limits(user_id, feature):
    """Enhanced usage limits checking with detailed tracking and caching"""
    try:
        user = User.query.get(user_id)
        if not user:
            logger.warning(f"Usage check failed: User {user_id} not found")
            return False

        effective_plan = get_effective_plan(user)
        plan_limits = PLANS.get(effective_plan, {}).get('limits', {})
        
        now = datetime.utcnow()
        month_start = datetime(now.year, now.month, 1)
        
        # Check if user is on unlimited plan
        if effective_plan == 'enterprise':
            return True
        
        current_usage = 0
        max_allowed = 0
        
        if feature == 'uploads':
            current_usage = get_monthly_usage(user_id, 'uploads', now.year, now.month)
            max_allowed = plan_limits.get('uploads_per_month', 0)
            
        elif feature == 'api_calls':
            current_usage = get_monthly_usage(user_id, 'api_calls', now.year, now.month)
            max_allowed = plan_limits.get('api_calls_per_month', 0)
            
        elif feature == 'ai_requests':
            current_usage = get_monthly_usage(user_id, 'ai_requests', now.year, now.month)
            max_allowed = plan_limits.get('ai_requests_per_month', 0)
            
        elif feature == 'camera_feeds':
            current_usage = CameraFeed.query.filter_by(user_id=user_id, status='active').count()
            max_allowed = plan_limits.get('camera_feeds', 0)
            
        elif feature == 'video_analysis_minutes':
            current_usage = get_monthly_usage(user_id, 'video_analysis_minutes', now.year, now.month)
            max_allowed = plan_limits.get('video_analysis_minutes', 0)
            
        elif feature == 'team_members':
            current_usage = TeamMember.query.join(Team).filter(Team.created_by == user_id).count()
            max_allowed = plan_limits.get('team_members', 0)
            
        elif feature == 'monitoring_stations':
            current_usage = MonitoringStation.query.filter_by(user_id=user_id).count()
            max_allowed = plan_limits.get('monitoring_stations', 0)
        
        else:
            logger.warning(f"Unknown feature for usage limits: {feature}")
            return True  # Allow unknown features by default
        
        # Check if limit is exceeded
        if max_allowed != "Unlimited" and current_usage >= max_allowed:
            logger.info(f"Usage limit exceeded for user {user_id}: {feature} ({current_usage}/{max_allowed})")
            
            # Create notification for user about limit exceeded
            create_notification(
                user_id,
                f"Usage Limit Exceeded - {feature.replace('_', ' ').title()}",
                f"You have reached your monthly limit for {feature.replace('_', ' ')}. Upgrade your plan for higher limits.",
                "warning",
                "medium",
                "/billing/upgrade"
            )
            return False
        
        # Log near-limit warning at 80% usage
        if (max_allowed != "Unlimited" and 
            current_usage >= max_allowed * 0.8 and 
            current_usage < max_allowed):
            
            # Only notify once per month per feature
            warning_key = f"usage_warning_{feature}_{now.year}_{now.month}"
            if not hasattr(user, warning_key):
                create_notification(
                    user_id,
                    f"Usage Limit Approaching - {feature.replace('_', ' ').title()}",
                    f"You have used {current_usage} of {max_allowed} {feature.replace('_', ' ')} this month.",
                    "info",
                    "low",
                    "/billing/upgrade"
                )
                setattr(user, warning_key, True)
        
        return True
        
    except Exception as e:
        logger.error(f"Error checking usage limits for user {user_id}, feature {feature}: {e}")
        # Fail open - allow usage on error to not block users
        return True

def get_monthly_usage(user_id, feature, year, month):
    """Get monthly usage with caching for performance"""
    try:
        # Try to get from monthly summary first (faster)
        summary = MonthlyUsageSummary.query.filter_by(
            user_id=user_id,
            year=year,
            month=month,
            feature=feature
        ).first()
        
        if summary:
            return summary.usage_count
        
        # If no summary exists, calculate from raw data
        month_start = datetime(year, month, 1)
        if month == 12:
            month_end = datetime(year + 1, 1, 1)
        else:
            month_end = datetime(year, month + 1, 1)
        
        usage_count = 0
        
        if feature == 'uploads':
            usage_count = Document.query.filter(
                Document.user_id == user_id,
                Document.uploaded_at >= month_start,
                Document.uploaded_at < month_end
            ).count()
            
        elif feature == 'ai_requests':
            usage_count = AIRequest.query.filter(
                AIRequest.user_id == user_id,
                AIRequest.created_at >= month_start,
                AIRequest.created_at < month_end
            ).count()
            
        elif feature == 'api_calls':
            usage_count = APIUsage.query.filter(
                APIUsage.user_id == user_id,
                APIUsage.timestamp >= month_start,
                APIUsage.timestamp < month_end
            ).count()
            
        elif feature == 'video_analysis_minutes':
            # Sum video analysis minutes
            total_minutes = db.session.query(
                func.sum(VideoAnalysis.processing_time / 60.0)
            ).filter(
                VideoAnalysis.user_id == user_id,
                VideoAnalysis.analyzed_at >= month_start,
                VideoAnalysis.analyzed_at < month_end
            ).scalar() or 0
            usage_count = int(total_minutes)
        
        # Create or update monthly summary
        update_monthly_usage_summary(user_id, year, month, feature, usage_count)
        
        return usage_count
        
    except Exception as e:
        logger.error(f"Error getting monthly usage for user {user_id}, feature {feature}: {e}")
        return 0

def update_monthly_usage_summary(user_id, year, month, feature, usage_count):
    """Update monthly usage summary for performance"""
    try:
        summary = MonthlyUsageSummary.query.filter_by(
            user_id=user_id,
            year=year,
            month=month,
            feature=feature
        ).first()
        
        if summary:
            summary.usage_count = usage_count
            summary.last_updated = datetime.utcnow()
        else:
            summary = MonthlyUsageSummary(
                user_id=user_id,
                year=year,
                month=month,
                feature=feature,
                usage_count=usage_count
            )
            db.session.add(summary)
        
        db.session.commit()
        
    except Exception as e:
        logger.error(f"Error updating monthly usage summary: {e}")
        db.session.rollback()

def track_api_usage(user_id, endpoint, method, ip_address=None, user_agent=None, 
                   response_status=200, processing_time=0, feature=None, resource_id=None, metadata=None):
    """Track API usage for rate limiting and analytics"""
    try:
        api_usage = APIUsage(
            user_id=user_id,
            endpoint=endpoint,
            method=method,
            ip_address=ip_address,
            user_agent=user_agent,
            response_status=response_status,
            processing_time=processing_time,
            feature=feature,
            resource_id=resource_id,
            metadata=json.dumps(metadata) if metadata else None
        )
        
        db.session.add(api_usage)
        db.session.commit()
        
        # Update monthly summary for performance
        now = datetime.utcnow()
        current_usage = get_monthly_usage(user_id, 'api_calls', now.year, now.month)
        update_monthly_usage_summary(user_id, now.year, now.month, 'api_calls', current_usage + 1)
        
    except Exception as e:
        logger.error(f"Error tracking API usage: {e}")
        db.session.rollback()

def track_usage(feature=None):
    """Decorator to track API usage for specific endpoints"""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            start_time = time.time()
            response = None
            
            try:
                # Call the original function
                response = f(*args, **kwargs)
                processing_time = time.time() - start_time
                
                # Track usage if user is authenticated
                if hasattr(request, 'user_id'):  # Set by JWT required decorator
                    user_id = request.user_id
                    
                    # Get response status
                    if response and hasattr(response, '__iter__'):
                        response_status = response[1] if len(response) > 1 else 200
                    else:
                        response_status = 200
                    
                    # Determine feature from endpoint if not specified
                    track_feature = feature or determine_feature_from_endpoint(request.endpoint)
                    
                    track_api_usage(
                        user_id=user_id,
                        endpoint=request.endpoint or request.path,
                        method=request.method,
                        ip_address=request.remote_addr,
                        user_agent=request.headers.get('User-Agent'),
                        response_status=response_status,
                        processing_time=processing_time,
                        feature=track_feature,
                        metadata={
                            'path': request.path,
                            'query_params': dict(request.args),
                            'content_length': request.content_length or 0
                        }
                    )
                
                return response
                
            except Exception as e:
                # Track failed requests too
                if hasattr(request, 'user_id'):
                    processing_time = time.time() - start_time
                    track_api_usage(
                        user_id=request.user_id,
                        endpoint=request.endpoint or request.path,
                        method=request.method,
                        ip_address=request.remote_addr,
                        user_agent=request.headers.get('User-Agent'),
                        response_status=500,
                        processing_time=processing_time,
                        feature=feature or 'error',
                        metadata={'error': str(e)}
                    )
                raise e
                
        return decorated_function
    return decorator

def determine_feature_from_endpoint(endpoint):
    """Determine feature category from endpoint"""
    if not endpoint:
        return 'unknown'
    
    endpoint_lower = endpoint.lower()
    
    if any(term in endpoint_lower for term in ['document', 'upload', 'file']):
        return 'uploads'
    elif any(term in endpoint_lower for term in ['ai', 'analysis', 'process']):
        return 'ai_requests'
    elif any(term in endpoint_lower for term in ['camera', 'monitor', 'violation']):
        return 'camera_feeds'
    elif any(term in endpoint_lower for term in ['video', 'analysis']):
        return 'video_analysis_minutes'
    elif any(term in endpoint_lower for term in ['team', 'member', 'user']):
        return 'team_members'
    else:
        return 'api_calls'

