@app.route('/api/user/usage', methods=['GET'])
@jwt_required
def get_user_usage_stats():
    """Get user usage statistics for profile display"""
    try:
        user = request.user
        app.logger.info(f"📊 Getting usage stats for user: {user.email} (ID: {user.id})")
        
        # Get user's plan from request (already normalized by decorator)
        plan = request.effective_plan or 'free'
        
        # Get allowed file types for this plan (using your existing function)
        allowed_types = get_allowed_file_types(plan)
        
        # Default limits based on plan (same as before)
        limits = {
            'free': {'uploads': 3, 'api_calls': 20, 'team_members': 1, 'storage': 100, 'video_minutes': 0},
            'basic': {'uploads': 100, 'api_calls': 500, 'team_members': 5, 'storage': 10 * 1024, 'video_minutes': 0},
            'pro': {'uploads': 500, 'api_calls': 2000, 'team_members': 20, 'storage': 50 * 1024, 'video_minutes': 100},
            'enterprise': {'uploads': 'Unlimited', 'api_calls': 'Custom', 'team_members': 'Unlimited', 'storage': 'Custom', 'video_minutes': 'Custom'}
        }
        
        plan_limits = limits.get(plan, limits['free'])
        
        # Calculate usage (same as before)
        uploads_used = getattr(user, 'monthly_uploads_used', 0)
        api_calls_used = getattr(user, 'monthly_api_calls_used', 0)
        
        # Team members count
        team_members_used = 1
        if user and user.company_id:
            try:
                team_members_used = User.query.filter_by(company_id=user.company_id).count()
            except:
                pass
        
        # Storage used
        storage_used_mb = 0
        try:
            if hasattr(user, 'storage_used_mb'):
                storage_used_mb = user.storage_used_mb
        except:
            pass
        
        video_minutes_used = getattr(user, 'monthly_video_minutes_used', 0)
        
        usage_data = {
            'uploads': {'used': uploads_used, 'total': plan_limits['uploads']},
            'apiCalls': {'used': api_calls_used, 'total': plan_limits['api_calls']},
            'teamMembers': {'used': team_members_used, 'total': plan_limits['team_members']},
            'storage': {'used': storage_used_mb, 'total': plan_limits['storage']},
            'videoMinutes': {'used': video_minutes_used, 'total': plan_limits['video_minutes']},
            'allowedFileTypes': allowed_types  # Add this to the response
        }
        
        return jsonify({
            'success': True,
            **usage_data
        }), 200
        
    except Exception as e:
        app.logger.error(f"❌ Error getting user usage stats: {e}")
        return jsonify({
            'success': False,
            'error': str(e),
            'uploads': {'used': 0, 'total': 3},
            'apiCalls': {'used': 0, 'total': 20},
            'teamMembers': {'used': 1, 'total': 1},
            'storage': {'used': 0, 'total': 100},
            'videoMinutes': {'used': 0, 'total': 0},
            'allowedFileTypes': get_allowed_file_types('free')
        }), 500



