@app.route('/api/user/quick-stats', methods=['GET'])
@jwt_required
def get_user_quick_stats():
    """Get quick statistics for profile dashboard"""
    try:
        # Check if user exists in request
        if not hasattr(request, 'user') or not request.user:
            app.logger.error("No user found in request context")
            return jsonify({
                'success': False,
                'error': 'User not authenticated',
                'incidents': 0,
                'documents': 0,
                'tasks': 0,
                'alerts': 0,
                'team': 1,
                'completion': 0
            }), 401
            
        user = request.user
        app.logger.info(f"Getting quick stats for user: {user.email} (ID: {user.id})")
        
        # Initialize counters with defaults
        incidents = 0
        documents = 0
        tasks = 0
        alerts = 0
        team = 1
        completion = 0
        
        # Try to get counts from various models with individual try-except blocks
        # Use the correct field names based on your models
        
        # Incidents - check which field name is correct
        try:
            from models import Incident
            # Try different possible field names
            if hasattr(Incident, 'reported_by'):
                incidents = Incident.query.filter_by(reported_by=user.id).count()
            elif hasattr(Incident, 'user_id'):
                incidents = Incident.query.filter_by(user_id=user.id).count()
            elif hasattr(Incident, 'created_by'):
                incidents = Incident.query.filter_by(created_by=user.id).count()
            app.logger.info(f"Incidents count: {incidents}")
        except Exception as e:
            app.logger.warning(f"Error counting incidents: {e}")
        
        # Documents - fix the field name (not 'uploaded_by')
        try:
            from models import Document
            # Try common field names for documents
            if hasattr(Document, 'user_id'):
                documents = Document.query.filter_by(user_id=user.id).count()
            elif hasattr(Document, 'uploaded_by'):
                documents = Document.query.filter_by(uploaded_by=user.id).count()
            elif hasattr(Document, 'created_by'):
                documents = Document.query.filter_by(created_by=user.id).count()
            elif hasattr(Document, 'owner_id'):
                documents = Document.query.filter_by(owner_id=user.id).count()
            app.logger.info(f"Documents count: {documents}")
        except Exception as e:
            app.logger.warning(f"Error counting documents: {e}")
        
        # Tasks
        try:
            from models import Task
            if hasattr(Task, 'assigned_to_id'):
                tasks = Task.query.filter_by(assigned_to_id=user.id, status='pending').count()
            elif hasattr(Task, 'assigned_to'):
                tasks = Task.query.filter_by(assigned_to=user.id, status='pending').count()
            elif hasattr(Task, 'user_id'):
                tasks = Task.query.filter_by(user_id=user.id, status='pending').count()
            app.logger.info(f"Tasks count: {tasks}")
            
            # Task completion rate
            if hasattr(Task, 'assigned_to_id'):
                total_tasks = Task.query.filter_by(assigned_to_id=user.id).count()
                completed_tasks = Task.query.filter_by(assigned_to_id=user.id, status='completed').count()
            elif hasattr(Task, 'assigned_to'):
                total_tasks = Task.query.filter_by(assigned_to=user.id).count()
                completed_tasks = Task.query.filter_by(assigned_to=user.id, status='completed').count()
            else:
                total_tasks = 0
                completed_tasks = 0
                
            completion = round((completed_tasks / total_tasks) * 100) if total_tasks > 0 else 0
            app.logger.info(f"Task completion: {completion}%")
        except Exception as e:
            app.logger.warning(f"Error counting tasks: {e}")
        
        # Notifications / Alerts
        try:
            from models import Notification
            if hasattr(Notification, 'user_id'):
                alerts = Notification.query.filter_by(user_id=user.id, read=False).count()
            elif hasattr(Notification, 'recipient_id'):
                alerts = Notification.query.filter_by(recipient_id=user.id, read=False).count()
            app.logger.info(f"Alerts count: {alerts}")
        except Exception as e:
            app.logger.warning(f"Error counting notifications: {e}")
        
        # Team count
        try:
            if user and user.company_id:
                from models import User
                team = User.query.filter_by(company_id=user.company_id).count()
                app.logger.info(f"Team count: {team}")
        except Exception as e:
            app.logger.warning(f"Error counting team members: {e}")
        
        return jsonify({
            'success': True,
            'incidents': incidents,
            'documents': documents,
            'tasks': tasks,
            'alerts': alerts,
            'team': team,
            'completion': completion
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error in get_user_quick_stats: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e),
            'incidents': 0,
            'documents': 0,
            'tasks': 0,
            'alerts': 0,
            'team': 1,
            'completion': 0
        }), 500


