# ============================================================================
@app.route('/api/user/preferences', methods=['PUT'])
@jwt_required
def update_user_preferences():
    """Update user preferences"""
    try:
        user = request.user
        app.logger.info(f"⚙️ Updating preferences for user: {user.email} (ID: {user.id})")
        
        data = request.get_json()
        
        prefs = UserPreferences.query.filter_by(user_id=user.id).first()
        if not prefs:
            prefs = UserPreferences(user_id=user.id)
            db.session.add(prefs)
        
        # Update fields (same as before)
        if 'emailNotifications' in data:
            prefs.email_notifications = data['emailNotifications']
        
        if 'pushNotifications' in data:
            prefs.push_notifications = data['pushNotifications']
        
        if 'browserNotifications' in data:
            prefs.browser_notifications = data['browserNotifications']
        
        if 'notificationFrequency' in data:
            prefs.notification_frequency = data['notificationFrequency']
        
        if 'categories' in data:
            prefs.categories = json.dumps(data['categories'])
        
        if 'quietHours' in data:
            prefs.quiet_hours = json.dumps(data['quietHours'])
        
        if 'language' in data:
            user.preferred_language = data['language']
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Preferences updated successfully'
        }), 200
        
    except Exception as e:
        app.logger.error(f"❌ Error updating user preferences: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


