@app.route('/api/user/sessions', methods=['GET'])
@jwt_required
def get_user_sessions_profile():
    """Get active user sessions for profile page"""
    try:
        # Use request.user set by your custom decorator
        user = request.user
        app.logger.info(f"Getting sessions for user: {user.email} (ID: {user.id})")
        
        # Get current session ID from header if provided
        current_session_id = request.headers.get('X-Session-ID')
        
        sessions = UserSession.query.filter_by(
            user_id=user.id,
            is_active=True
        ).order_by(UserSession.last_activity.desc()).all()
        
        sessions_data = []
        for session in sessions:
            session_dict = {
                'id': session.id,
                'device_info': session.device_info or session.user_agent or 'Unknown Device',
                'ip_address': session.ip_address,
                'location': session.location or 'Unknown',
                'is_active': session.is_active,
                'created_at': session.login_time.isoformat() if session.login_time else None,
                'last_activity': session.last_activity.isoformat() if session.last_activity else None,
                'is_current': (session.session_id == current_session_id)
            }
            sessions_data.append(session_dict)
        
        return jsonify({
            'success': True,
            'sessions': sessions_data
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error getting user sessions: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


# ============================================================================
# 9. TERMINATE SPECIFIC SESSION (FIXED - USING request.user)
# ============================================================================
@app.route('/api/user/sessions/<int:session_id>', methods=['DELETE'])
@jwt_required
def terminate_user_session(session_id):
    """Terminate a specific user session"""
    try:
        # Use request.user set by your custom decorator
        user = request.user
        app.logger.info(f"Terminating session {session_id} for user: {user.email} (ID: {user.id})")
        
        session = UserSession.query.filter_by(
            id=session_id,
            user_id=user.id
        ).first()
        
        if not session:
            return jsonify({'success': False, 'error': 'Session not found'}), 404
        
        # Don't allow terminating current session through this endpoint
        current_session_id = request.headers.get('X-Session-ID')
        if session.session_id == current_session_id:
            return jsonify({'success': False, 'error': 'Cannot terminate current session'}), 400
        
        session.is_active = False
        session.logout_time = datetime.utcnow()
        db.session.commit()
        
        # Log activity
        try:
            log_user_activity(user.id, 'session_terminated', f'Terminated session from {session.ip_address}')
        except:
            pass
        
        return jsonify({
            'success': True,
            'message': 'Session terminated successfully'
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error terminating session: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


# ============================================================================
# 10. TERMINATE OTHER SESSIONS (FIXED - USING request.user)
# ============================================================================
@app.route('/api/user/sessions/others', methods=['DELETE'])
@jwt_required
def terminate_other_user_sessions():
    """Terminate all other sessions except current"""
    try:
        # Use request.user set by your custom decorator
        user = request.user
        app.logger.info(f"Terminating other sessions for user: {user.email} (ID: {user.id})")
        
        current_session_id = request.headers.get('X-Session-ID')
        
        if not current_session_id:
            return jsonify({'success': False, 'error': 'Current session ID required'}), 400
        
        # Count sessions to be terminated
        sessions_to_terminate = UserSession.query.filter(
            UserSession.user_id == user.id,
            UserSession.session_id != current_session_id,
            UserSession.is_active == True
        ).all()
        
        count = len(sessions_to_terminate)
        
        # Update all other sessions
        UserSession.query.filter(
            UserSession.user_id == user.id,
            UserSession.session_id != current_session_id,
            UserSession.is_active == True
        ).update({
            'is_active': False,
            'logout_time': datetime.utcnow()
        }, synchronize_session=False)
        
        db.session.commit()
        
        # Log activity
        try:
            log_user_activity(user.id, 'sessions_terminated', f'Terminated {count} other sessions')
        except:
            pass
        
        return jsonify({
            'success': True,
            'message': f'Successfully terminated {count} other sessions',
            'terminated_count': count
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error terminating other sessions: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


