@app.route('/api/user/activity', methods=['GET'])
@jwt_required
def get_user_activity_log():
    """Get user activity log for profile page"""
    try:
        # Use request.user set by your custom decorator
        user = request.user
        app.logger.info(f"Getting activity log for user: {user.email} (ID: {user.id})")
        
        page = request.args.get('page', 1, type=int)
        limit = request.args.get('limit', 20, type=int)
        
        activities = ActivityLog.query.filter_by(user_id=user.id)\
            .order_by(ActivityLog.timestamp.desc())\
            .paginate(page=page, per_page=limit, error_out=False)
        
        activities_data = []
        for act in activities.items:
            activities_data.append({
                'id': act.id,
                'action': act.activity_type or act.action,
                'description': act.description,
                'details': act.activity_data or act.details,
                'ip_address': act.ip_address,
                'created_at': act.timestamp.isoformat() if act.timestamp else None
            })
        
        return jsonify({
            'success': True,
            'activities': activities_data,
            'total': activities.total,
            'page': page,
            'pages': activities.pages,
            'has_next': activities.has_next,
            'has_prev': activities.has_prev
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error getting user activity log: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


