# Update profile endpoint
@app.route('/api/auth/profile/update', methods=['PUT', 'OPTIONS'])
@jwt_required
def update_profile():
    """Update user profile with cache invalidation"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        user = request.user
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No data provided'
            }), 400
        
        # Check API usage
        usage_stats = getattr(request, 'usage_stats', {})
        api_remaining = usage_stats.get('api_calls', {}).get('remaining', 100)
        
        if api_remaining is not None and api_remaining <= 0:
            return jsonify({
                'success': False,
                'error': 'Monthly API call limit reached',
                'code': 'API_LIMIT_REACHED',
                'usage': usage_stats.get('api_calls', {})
            }), 429
        
        # Define allowed fields for update
        allowed_fields = [
            'name', 'phone', 'department', 'position', 'avatar_url',
            'company_name', 'industry', 'company_size', 'country',
            'city', 'address', 'website', 'employee_id'
        ]
        
        # Update only allowed fields
        updated_fields = []
        for field in allowed_fields:
            if field in data:
                if hasattr(user, field):
                    old_value = getattr(user, field)
                    new_value = data[field]
                    
                    # Skip if value hasn't changed
                    if old_value != new_value:
                        setattr(user, field, new_value)
                        updated_fields.append(field)
        
        # Handle preferences separately
        if 'preferences' in data and isinstance(data['preferences'], dict):
            current_prefs = json.loads(user.preferences) if hasattr(user, 'preferences') and user.preferences else {}
            updated_prefs = {**current_prefs, **data['preferences']}
            user.preferences = json.dumps(updated_prefs)
            updated_fields.append('preferences')
        
        # If no fields were updated
        if not updated_fields:
            return jsonify({
                'success': False,
                'error': 'No valid fields to update',
                'allowed_fields': allowed_fields
            }), 400
        
        # Update timestamp
        user.updated_at = datetime.utcnow()
        
        # Increment token version to force cache refresh
        user.token_version = getattr(user, 'token_version', 0) + 1
        
        # Update API usage
        user.monthly_api_calls_used = getattr(user, 'monthly_api_calls_used', 0) + 1
        db.session.commit()
        
        # ==================== 🆕 CLEAR CACHE ====================
        UserCache.clear(user.id)
        print(f"✅ Cache cleared for user {user.id} after profile update")
        
        # Log the update
        try:
            audit_log = AuditLog(
                user_id=user.id,
                action='profile_update',
                resource_type='user',
                resource_id=user.id,
                details=json.dumps({
                    'updated_fields': updated_fields,
                    'ip_address': request.remote_addr,
                    'user_agent': request.headers.get('User-Agent', '')[:255]
                }),
                ip_address=request.remote_addr,
                user_agent=request.headers.get('User-Agent', '')
            )
            db.session.add(audit_log)
            db.session.commit()
        except Exception as e:
            print(f"⚠️ Could not create audit log: {str(e)}")
        
        # ==================== 🆕 RETURN UPDATED PROFILE ====================
        return jsonify({
            'success': True,
            'message': 'Profile updated successfully',
            'updated_fields': updated_fields,
            'profile': {
                'id': user.id,
                'name': user.name,
                'email': user.email,
                'company_name': user.company_name,
                'industry': user.industry,
                'updated_at': user.updated_at.isoformat() if user.updated_at else None
            },
            'token_version': user.token_version,  # Let frontend know to refresh token
            'cache_cleared': True,
            'usage_stats': usage_stats
        }), 200
        
    except Exception as e:
        logger.error(f"Profile update error: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Failed to update profile',
            'message': 'Please try again or contact support'
        }), 500

# Change password endpoint
@app.route('/api/auth/change-password', methods=['POST', 'OPTIONS'])
@jwt_required
def change_password():
    """Change user password with cache invalidation"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        user = request.user
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No data provided'
            }), 400
        
        required_fields = ['current_password', 'new_password', 'confirm_password']
        for field in required_fields:
            if field not in data:
                return jsonify({
                    'success': False,
                    'error': f'Missing required field: {field}'
                }), 400
        
        # Validate passwords
        if data['new_password'] != data['confirm_password']:
            return jsonify({
                'success': False,
                'error': 'New passwords do not match'
            }), 400
        
        # Check password strength
        if len(data['new_password']) < 8:
            return jsonify({
                'success': False,
                'error': 'Password must be at least 8 characters long'
            }), 400
        
        # Verify current password
        if not user.check_password(data['current_password']):
            return jsonify({
                'success': False,
                'error': 'Current password is incorrect'
            }), 401
        
        # Check if new password is same as old
        if user.check_password(data['new_password']):
            return jsonify({
                'success': False,
                'error': 'New password cannot be the same as current password'
            }), 400
        
        # Update password
        user.set_password(data['new_password'])
        user.updated_at = datetime.utcnow()
        
        # Increment token version to force cache refresh
        user.token_version = getattr(user, 'token_version', 0) + 1
        
        # Update API usage
        user.monthly_api_calls_used = getattr(user, 'monthly_api_calls_used', 0) + 1
        db.session.commit()
        
        # ==================== 🆕 CLEAR CACHE ====================
        UserCache.clear(user.id)
        print(f"✅ Cache cleared for user {user.id} after password change")
        
        # Create notification
        try:
            notification = Notification(
                user_id=user.id,
                title='Password Changed',
                message='Your password has been successfully changed.',
                type='success',
                category='security',
                priority='high'
            )
            db.session.add(notification)
        except Exception as e:
            print(f"⚠️ Could not create notification: {str(e)}")
        
        # Log password change
        try:
            audit_log = AuditLog(
                user_id=user.id,
                action='password_change',
                resource_type='user',
                resource_id=user.id,
                details=json.dumps({
                    'changed_at': datetime.utcnow().isoformat(),
                    'ip_address': request.remote_addr
                }),
                ip_address=request.remote_addr,
                user_agent=request.headers.get('User-Agent', '')
            )
            db.session.add(audit_log)
            db.session.commit()
        except Exception as e:
            print(f"⚠️ Could not create audit log: {str(e)}")
        
        # ==================== 🆕 RETURN WITH TOKEN VERSION ====================
        return jsonify({
            'success': True,
            'message': 'Password changed successfully',
            'notification_sent': True,
            'token_version': user.token_version,  # Let frontend know to refresh token
            'cache_cleared': True,
            'usage_stats': getattr(request, 'usage_stats', {})
        }), 200
        
    except Exception as e:
        logger.error(f"Password change error: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Failed to change password',
            'message': 'Please try again or contact support'
        }), 500


# Upload profile avatar
@app.route('/api/auth/profile/avatar', methods=['POST', 'OPTIONS'])
@jwt_required
def upload_avatar():
    """Upload user profile avatar with cache invalidation"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        user = request.user
        
        # ==================== CHECK FEATURE ACCESS ====================
        plan_features = getattr(request, 'plan_features', {})
        is_system_team = getattr(request, 'is_system_team', False)
        
        if not plan_features.get('custom_avatar', True) and not is_system_team:
            return jsonify({
                'success': False,
                'error': 'Custom avatar upload not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'upgrade_required': True
            }), 403
        
        # ==================== CHECK UPLOAD LIMITS ====================
        usage_stats = getattr(request, 'usage_stats', {})
        uploads_remaining = usage_stats.get('uploads', {}).get('remaining', 100)
        
        if uploads_remaining is not None and uploads_remaining <= 0:
            return jsonify({
                'success': False,
                'error': 'Monthly upload limit reached',
                'code': 'UPLOAD_LIMIT_REACHED',
                'usage': usage_stats.get('uploads', {})
            }), 429
        
        # ==================== VALIDATE FILE ====================
        if 'avatar' not in request.files:
            return jsonify({
                'success': False,
                'error': 'No avatar file provided'
            }), 400
        
        avatar_file = request.files['avatar']
        if avatar_file.filename == '':
            return jsonify({
                'success': False,
                'error': 'No file selected'
            }), 400
        
        # Validate file type
        allowed_extensions = {'png', 'jpg', 'jpeg', 'gif', 'webp'}
        if not ('.' in avatar_file.filename and 
                avatar_file.filename.rsplit('.', 1)[1].lower() in allowed_extensions):
            return jsonify({
                'success': False,
                'error': 'Invalid file type. Allowed: PNG, JPG, JPEG, GIF, WEBP'
            }), 400
        
        # Check file size (max 5MB)
        max_size = 5 * 1024 * 1024  # 5MB
        avatar_file.seek(0, 2)  # Seek to end
        file_size = avatar_file.tell()
        avatar_file.seek(0)  # Reset
        
        if file_size > max_size:
            return jsonify({
                'success': False,
                'error': 'File too large. Maximum size is 5MB'
            }), 400
        
        # ==================== SAVE FILE ====================
        # Generate unique filename
        file_extension = avatar_file.filename.rsplit('.', 1)[1].lower()
        timestamp = datetime.utcnow().strftime('%Y%m%d_%H%M%S')
        unique_filename = f"avatar_{user.id}_{timestamp}.{file_extension}"
        
        # Create avatars directory if it doesn't exist
        avatars_dir = os.path.join(current_app.config.get('UPLOAD_FOLDER', 'uploads'), 'avatars')
        if not os.path.exists(avatars_dir):
            os.makedirs(avatars_dir)
        
        # Save file
        file_path = os.path.join(avatars_dir, unique_filename)
        avatar_file.save(file_path)
        
        # Delete old avatar if it exists and is not default
        if user.avatar_url and not user.avatar_url.startswith('http'):
            try:
                old_avatar_path = os.path.join(current_app.root_path, user.avatar_url.lstrip('/'))
                if os.path.exists(old_avatar_path):
                    os.remove(old_avatar_path)
                    print(f"🗑️ Deleted old avatar: {old_avatar_path}")
            except Exception as e:
                logger.warning(f"Could not delete old avatar: {e}")
        
        # ==================== UPDATE USER ====================
        avatar_url = f"/uploads/avatars/{unique_filename}"
        user.avatar_url = avatar_url
        user.updated_at = datetime.utcnow()
        
        # Increment token version to force cache refresh
        user.token_version = getattr(user, 'token_version', 0) + 1
        
        # Update usage
        user.monthly_api_calls_used = getattr(user, 'monthly_api_calls_used', 0) + 1
        user.monthly_uploads_used = getattr(user, 'monthly_uploads_used', 0) + 1
        db.session.commit()
        
        # ==================== 🆕 CLEAR CACHE ====================
        UserCache.clear(user.id)
        print(f"✅ Cache cleared for user {user.id} after avatar upload")
        
        # Log avatar upload
        try:
            audit_log = AuditLog(
                user_id=user.id,
                action='avatar_upload',
                resource_type='user',
                resource_id=user.id,
                details=json.dumps({
                    'file_size': file_size,
                    'file_type': file_extension,
                    'avatar_url': avatar_url
                }),
                ip_address=request.remote_addr,
                user_agent=request.headers.get('User-Agent', '')
            )
            db.session.add(audit_log)
            db.session.commit()
        except Exception as e:
            print(f"⚠️ Could not create audit log: {str(e)}")
        
        # ==================== RETURN RESPONSE ====================
        return jsonify({
            'success': True,
            'message': 'Avatar uploaded successfully',
            'avatar_url': avatar_url,
            'full_url': request.host_url.rstrip('/') + avatar_url,
            'token_version': user.token_version,  # Let frontend know to refresh token
            'cache_cleared': True,
            'usage_stats': usage_stats
        }), 200
        
    except Exception as e:
        logger.error(f"Avatar upload error: {e}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to upload avatar',
            'message': 'Please try again or contact support'
        }), 500

@app.route('/api/auth/resend-verification', methods=['POST', 'OPTIONS'])
@app.route('/api/resend-verification', methods=['POST'])
def resend_verification():
    """Resend verification code to user's email"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        data = request.get_json()
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided'
            }), 400
            
        email = data.get('email')
        
        if not email:
            return jsonify({
                'success': False,
                'error': 'Email is required'
            }), 400
        
        # Normalize email
        email = email.lower().strip()
        
        # Find user
        user = User.query.filter_by(email=email).first()
        if not user:
            logger.warning(f"Resend verification attempt for non-existent email: {email}")
            return jsonify({
                'success': False,
                'error': 'User not found'
            }), 404
        
        # Check if already verified
        if user.verified:
            logger.info(f"Resend verification attempt for already verified email: {email}")
            return jsonify({
                'success': False,
                'error': 'Email already verified',
                'message': 'Your email is already verified. You can proceed to login.'
            }), 400
        
        # Check rate limiting
        recent_attempts = Verification.query.filter(
            Verification.email == email,
            Verification.created_at > datetime.utcnow() - timedelta(minutes=5)
        ).count()
        
        if recent_attempts >= 3:
            logger.warning(f"Too many resend attempts for email: {email}")
            return jsonify({
                'success': False,
                'error': 'Too many attempts',
                'message': 'Please wait 5 minutes before requesting another verification code.'
            }), 429
        
        # Generate new verification code
        code = str(random.randint(100000, 999999))
        
        # Remove any existing verification codes for this email
        deleted = Verification.query.filter_by(email=email).delete()
        logger.info(f"🗑️ Deleted {deleted} old verification codes for {email}")
        
        # ✅ Create new verification record
        verification = Verification(
            email=email,
            code=code,
            purpose='email_verification',
            expires_at=datetime.utcnow() + timedelta(minutes=10)  # ✅ 10 minutes expiry
        )
        db.session.add(verification)
        
        # Update user's verification attempts
        if not hasattr(user, 'verification_attempts'):
            user.verification_attempts = 0
        user.verification_attempts += 1
        user.last_verification_sent = datetime.utcnow()
        
        db.session.commit()
        logger.info(f"✅ Created new verification code for {email}: {code}")
        
        # ========== SEND VERIFICATION EMAIL ==========
        email_subject = "Verify Your Email - SafetyTrack Pro"
        
        # Build email HTML content
        is_admin = user.user_type == 'admin'
        
        if is_admin:
            html_content = f"""
            <!DOCTYPE html>
            <html>
            <head>
                <style>
                    body {{ font-family: Arial, sans-serif; line-height: 1.6; color: #333; }}
                    .container {{ max-width: 600px; margin: 0 auto; padding: 20px; }}
                    .header {{ background: linear-gradient(135deg, #ff6b6b 0%, #ee5a24 100%); color: white; padding: 30px; text-align: center; border-radius: 10px 10px 0 0; }}
                    .content {{ background: #f9f9f9; padding: 30px; border-radius: 0 0 10px 10px; }}
                    .verification-code {{ background: #ff6b6b; color: white; padding: 15px 30px; font-size: 24px; font-weight: bold; text-align: center; border-radius: 5px; margin: 20px 0; }}
                    .footer {{ text-align: center; margin-top: 20px; font-size: 12px; color: #666; }}
                    .admin-note {{ background: #fff3cd; border: 1px solid #ffeaa7; padding: 15px; border-radius: 5px; margin: 15px 0; }}
                </style>
            </head>
            <body>
                <div class="container">
                    <div class="header">
                        <h1>SafetyTrack Pro</h1>
                        <p>Admin Account Verification</p>
                    </div>
                    <div class="content">
                        <h2>Hello {user.name or 'Administrator'},</h2>
                        <p>Thank you for registering as an Administrator with SafetyTrack Pro.</p>
                        
                        <div class="admin-note">
                            <strong>Important:</strong> Your admin account requires approval. After verification, our team will review your application and activate your account.
                        </div>
                        
                        <p>To verify your email address, please use the verification code below:</p>
                        
                        <div class="verification-code">
                            {code}
                        </div>
                        
                        <p>This code will expire in 10 minutes.</p>
                        
                        <p>If you didn't request an admin account with SafetyTrack Pro, please ignore this email.</p>
                        
                        <p>Best regards,<br>The SafetyTrack Pro Team</p>
                    </div>
                    <div class="footer">
                        <p>&copy; 2024 SafetyTrack Pro. All rights reserved.</p>
                    </div>
                </div>
            </body>
            </html>
            """
        else:
            html_content = f"""
            <!DOCTYPE html>
            <html>
            <head>
                <style>
                    body {{ font-family: Arial, sans-serif; line-height: 1.6; color: #333; }}
                    .container {{ max-width: 600px; margin: 0 auto; padding: 20px; }}
                    .header {{ background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; text-align: center; border-radius: 10px 10px 0 0; }}
                    .content {{ background: #f9f9f9; padding: 30px; border-radius: 0 0 10px 10px; }}
                    .verification-code {{ background: #667eea; color: white; padding: 15px 30px; font-size: 24px; font-weight: bold; text-align: center; border-radius: 5px; margin: 20px 0; }}
                    .footer {{ text-align: center; margin-top: 20px; font-size: 12px; color: #666; }}
                </style>
            </head>
            <body>
                <div class="container">
                    <div class="header">
                        <h1>SafetyTrack Pro</h1>
                        <p>Account Verification</p>
                    </div>
                    <div class="content">
                        <h2>Hello {user.name or 'there'},</h2>
                        <p>Thank you for registering with SafetyTrack Pro. To complete your registration, please use the verification code below:</p>
                        
                        <div class="verification-code">
                            {code}
                        </div>
                        
                        <p>This code will expire in 10 minutes.</p>
                        
                        <p>If you didn't create an account with SafetyTrack Pro, please ignore this email.</p>
                        
                        <p>Best regards,<br>The SafetyTrack Pro Team</p>
                    </div>
                    <div class="footer">
                        <p>&copy; 2024 SafetyTrack Pro. All rights reserved.</p>
                    </div>
                </div>
            </body>
            </html>
            """
        
        # ✅ FIX: Use correct parameter name 'recipient' (not 'to_email')
        # Your send_email function signature: send_email(recipient, subject, html_content)
        email_sent = send_email(
            recipient=email,      # ✅ Correct parameter name
            subject=email_subject,
            html_content=html_content
        )
        
        if email_sent:
            logger.info(f"✅ Verification email sent to {email}")
            
            return jsonify({
                'success': True,
                'message': 'Verification email sent successfully',
                'timestamp': datetime.utcnow().isoformat(),
                'code_sent': True,
                'user': {
                    'email': user.email,
                    'name': user.name
                }
            }), 200
        else:
            logger.error(f"❌ Failed to send verification email to {email}")
            return jsonify({
                'success': False,
                'error': 'Failed to send verification email',
                'message': 'Please try again in a few minutes or contact support.',
                'code_sent': False
            }), 500
        
    except Exception as e:
        logger.error(f"❌ Resend verification error: {e}")
        import traceback
        logger.error(traceback.format_exc())
        db.session.rollback()
        
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'message': 'An unexpected error occurred. Please try again.'
        }), 500


# Dashboard statistics endpoint
@app.route('/api/dashboard/stats', methods=['GET', 'OPTIONS'])
@jwt_required
def dashboard_stats():
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        user = request.user
        
        # Check API usage limits
        if (request.usage_stats['api_calls']['remaining'] is not None and 
            request.usage_stats['api_calls']['remaining'] <= 0):
            return jsonify({
                'success': False,
                'error': 'Monthly API call limit reached',
                'code': 'API_LIMIT_REACHED',
                'usage': request.usage_stats['api_calls']
            }), 429
        
        # Calculate time periods
        today = datetime.utcnow().date()
        week_ago = datetime.utcnow() - timedelta(days=7)
        month_ago = datetime.utcnow() - timedelta(days=30)
        
        # Document statistics
        document_count = Document.query.filter_by(user_id=user.id).count()
        recent_documents = Document.query.filter(
            Document.user_id == user.id,
            Document.uploaded_at >= week_ago
        ).count()
        
        # Notification statistics
        unread_notifications = Notification.query.filter_by(
            user_id=user.id, 
            is_read=False
        ).count()
        total_notifications = Notification.query.filter_by(
            user_id=user.id
        ).count()
        
        # Incident statistics
        incident_count = Incident.query.filter_by(reported_by=user.id).count()
        recent_incidents = Incident.query.filter(
            Incident.reported_by == user.id,
            Incident.created_at >= week_ago
        ).count()
        critical_incidents = Incident.query.filter(
            Incident.reported_by == user.id,
            Incident.severity == 'critical'
        ).count()
        
        # Task statistics
        pending_tasks = Task.query.filter_by(
            assigned_to_id=user.id,
            status='todo'
        ).count()
        overdue_tasks = Task.query.filter(
            Task.assigned_to_id == user.id,
            Task.status.in_(['todo', 'in_progress']),
            Task.due_date < datetime.utcnow()
        ).count()
        completed_tasks = Task.query.filter(
            Task.assigned_to_id == user.id,
            Task.status == 'completed',
            Task.completed_at >= month_ago
        ).count()
        
        # AI Document statistics
        ai_document_count = AIDocument.query.filter_by(user_id=user.id).count()
        
        # Monitoring statistics (if feature available)
        monitoring_alerts_count = 0
        camera_count = 0
        if request.plan_features.get('monitoring', False) or request.is_system_team:
            monitoring_alerts_count = MonitoringAlert.query.filter_by(
                user_id=user.id,
                status='active'
            ).count()
            camera_count = CameraFeed.query.filter_by(
                user_id=user.id,
                status='active'
            ).count()
        
        
        
        # Module-specific statistics
        module_stats = {}
        
        # HSE Module stats
        if request.plan_features.get('hse_module', False) or request.is_system_team:
            near_misses_count = NearMiss.query.filter_by(reported_by=user.id).count()
            risk_assessments_count = RiskAssessment.query.filter_by(assessed_by=user.id).count()
            
            module_stats['hse'] = {
                'nearMisses': near_misses_count,
                'riskAssessments': risk_assessments_count
            }
        
        # Hospital Module stats
        if request.plan_features.get('hospital_module', False) or request.is_system_team:
            patient_incidents_count = PatientSafetyIncident.query.filter_by(reported_by=user.id).count()
            training_completed_count = TrainingRecord.query.filter_by(user_id=user.id, status='completed').count()
            
            module_stats['hospital'] = {
                'patientIncidents': patient_incidents_count,
                'trainingCompleted': training_completed_count
            }
        
        # Update API usage
        user.monthly_api_calls_used += 1
        db.session.commit()
        
        return jsonify({
            'success': True,
            'stats': {
                'documents': {
                    'total': document_count,
                    'recent': recent_documents,
                    'aiGenerated': ai_document_count
                },
                'notifications': {
                    'unread': unread_notifications,
                    'total': total_notifications,
                    'unreadPercentage': round((unread_notifications / total_notifications * 100), 1) if total_notifications > 0 else 0
                },
                'incidents': {
                    'total': incident_count,
                    'recent': recent_incidents,
                    'critical': critical_incidents,
                    'criticalPercentage': round((critical_incidents / incident_count * 100), 1) if incident_count > 0 else 0
                },
                'tasks': {
                    'pending': pending_tasks,
                    'overdue': overdue_tasks,
                    'completedMonthly': completed_tasks,
                    'completionRate': round((completed_tasks / (pending_tasks + completed_tasks) * 100), 1) if (pending_tasks + completed_tasks) > 0 else 0
                },
                'monitoring': {
                    'activeAlerts': monitoring_alerts_count,
                    'activeCameras': camera_count
                },
                
                'modules': module_stats,
                'productivity': {
                    'documentsPerDay': round(document_count / 30, 1) if document_count > 0 else 0,
                    'incidentsPerWeek': round(incident_count / 4, 1) if incident_count > 0 else 0,
                    'taskCompletionRate': round((completed_tasks / (pending_tasks + completed_tasks) * 100), 1) if (pending_tasks + completed_tasks) > 0 else 0
                }
            },
            'time_periods': {
                'today': today.isoformat(),
                'week_ago': week_ago.isoformat(),
                'month_ago': month_ago.isoformat()
            },
            'plan_info': {
                'current_plan': request.effective_plan,
                'is_trial': request.is_trial_active,
                'is_system_team': request.is_system_team,
                'features': {
                    'monitoring': request.plan_features.get('monitoring', False),
                    'hse_module': request.plan_features.get('hse_module', False),
                    'hospital_module': request.plan_features.get('hospital_module', False),
                    'supply_chain': request.plan_features.get('supply_chain_module', False)
                }
            },
            'usage_stats': request.usage_stats,
            'generated_at': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        logger.error(f"Dashboard stats error: {e}", exc_info=True)
        return jsonify({'error': 'Internal server error'}), 500

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

# Documents - Analyze
@app.route('/api/documents/analyze', methods=['POST', 'OPTIONS'])
@jwt_required
def analyze_document():
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        user = request.user
        
        # Check if document analysis feature is available
        if not request.plan_features.get('document_analysis', False) and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Document analysis not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'upgrade_required': True
            }), 403
        
        # Check upload limits
        if (request.usage_stats['uploads']['remaining'] is not None and 
            request.usage_stats['uploads']['remaining'] <= 0):
            return jsonify({
                'success': False,
                'error': 'Monthly upload limit reached',
                'code': 'UPLOAD_LIMIT_REACHED',
                'usage': request.usage_stats['uploads']
            }), 429
        
        if 'file' not in request.files:
            return jsonify({
                'success': False,
                'error': 'No file provided'
            }), 400
        
        file = request.files['file']
        if file.filename == '':
            return jsonify({
                'success': False,
                'error': 'No file selected'
            }), 400
        
        if not allowed_file(file.filename):
            return jsonify({
                'success': False,
                'error': f'File type not allowed. Allowed types: {", ".join(ALLOWED_EXTENSIONS)}'
            }), 400
        
        # Check file size limit (10MB default)
        max_file_size = request.plan_limits.get('max_file_size_mb', 10) * 1024 * 1024
        file.seek(0, 2)  # Seek to end
        file_size = file.tell()
        file.seek(0)  # Reset pointer
        
        if file_size > max_file_size:
            return jsonify({
                'success': False,
                'error': f'File size exceeds limit of {request.plan_limits.get("max_file_size_mb", 10)}MB',
                'code': 'FILE_TOO_LARGE',
                'max_size_mb': request.plan_limits.get('max_file_size_mb', 10),
                'file_size_mb': round(file_size / (1024 * 1024), 2)
            }), 400
        
        # Generate unique filename
        original_filename = secure_filename(file.filename)
        file_extension = original_filename.rsplit('.', 1)[1].lower() if '.' in original_filename else ''
        timestamp = datetime.utcnow().strftime('%Y%m%d_%H%M%S')
        unique_filename = f"{user.id}_{timestamp}_{original_filename}"
        
        # Ensure upload folder exists
        upload_folder = current_app.config.get('UPLOAD_FOLDER', 'uploads')
        if not os.path.exists(upload_folder):
            os.makedirs(upload_folder)
        
        file_path = os.path.join(upload_folder, unique_filename)
        file.save(file_path)
        
        # Create upload file record
        upload_file = UploadFile(
            user_id=user.id,
            filename=unique_filename,
            original_filename=original_filename,
            file_path=file_path,
            file_size=file_size,
            mime_type=file.content_type,
            upload_type='document',
            uploaded_at=datetime.utcnow(),
            category=request.form.get('category', 'general'),
            is_public=request.form.get('is_public', 'false').lower() == 'true',
            tags=request.form.get('tags', ''),
            metadata=json.dumps({
                'upload_source': 'document_analysis',
                'original_filename': original_filename,
                'content_type': file.content_type,
                'uploaded_at': datetime.utcnow().isoformat()
            })
        )
        db.session.add(upload_file)
        db.session.flush()  # Get the ID
        
        try:
            # Analyze document content
            analysis_start_time = datetime.utcnow()
            risk_score, compliance_score, analysis_details = analyze_document_content(
                file_path, 
                file.content_type,
                user_context={
                    'user_id': user.id,
                    'user_email': user.email,
                    'company_name': user.company_name if hasattr(user, 'company_name') else None,
                    'industry': user.industry if hasattr(user, 'industry') else None
                }
            )
            analysis_time = (datetime.utcnow() - analysis_start_time).total_seconds()
            
            # Determine risk level based on score
            risk_level = "low"
            if risk_score > 70:
                risk_level = "high"
            elif risk_score > 30:
                risk_level = "medium"
            
            # Determine compliance status
            compliance_status = "compliant"
            if compliance_score < 60:
                compliance_status = "non_compliant"
            elif compliance_score < 80:
                compliance_status = "partially_compliant"
            
            # Create document record
            document = Document(
                user_id=user.id,
                upload_file_id=upload_file.id,
                filename=unique_filename,
                originalname=original_filename,
                uploaded_at=datetime.utcnow(),
                doc_type=file_extension.upper(),
                file_size=file_size,
                mime_type=file.content_type,
                analysis_result=json.dumps(analysis_details),
                risk_score=risk_score,
                compliance_score=compliance_score,
                risk_level=risk_level,
                compliance_status=compliance_status,
                analysis_time=analysis_time,
                status='processed',
                category=request.form.get('category', 'general'),
                tags=request.form.get('tags', ''),
                metadata=json.dumps({
                    'analysis_details': analysis_details,
                    'analyzed_at': datetime.utcnow().isoformat(),
                    'analysis_time_seconds': analysis_time,
                    'plan_used': request.effective_plan
                })
            )
            db.session.add(document)
            
            # Create notification for user
            notification = Notification(
                user_id=user.id,
                title='Document Analysis Complete',
                message=f'Analysis complete for "{original_filename}". Risk level: {risk_level.title()}',
                type='info' if risk_level == 'low' else 'warning' if risk_level == 'medium' else 'critical',
                category='document',
                reference_id=document.id,
                reference_type='document',
                priority='medium' if risk_level == 'low' else 'high' if risk_level == 'medium' else 'critical'
            )
            db.session.add(notification)
            
            # If high risk, create an incident automatically
            if risk_level == 'high' and request.plan_features.get('auto_incident_creation', False):
                incident_number = f"DOC-{datetime.utcnow().strftime('%Y%m%d')}-{random.randint(1000, 9999)}"
                
                incident = Incident(
                    incident_number=incident_number,
                    title=f"High Risk Document Detected: {original_filename}",
                    description=f"Document analysis detected high risk content in {original_filename}. Risk score: {risk_score}",
                    incident_type='document_risk',
                    severity='high',
                    location='Document Management System',
                    department='Compliance',
                    reported_by=user.id,
                    date_occurred=datetime.utcnow(),
                    status='reported',
                    source='auto_document_analysis',
                    source_reference=f"document:{document.id}",
                    metadata=json.dumps({
                        'document_id': document.id,
                        'original_filename': original_filename,
                        'risk_score': risk_score,
                        'compliance_score': compliance_score,
                        'analysis_details': analysis_details
                    })
                )
                db.session.add(incident)
            
            # Update usage
            user.monthly_api_calls_used += 1
            user.monthly_uploads_used += 1
            db.session.commit()
            
            # Log document analysis
            audit_log = AuditLog(
                user_id=user.id,
                action='document_analysis',
                resource_type='document',
                resource_id=document.id,
                details=json.dumps({
                    'filename': original_filename,
                    'file_size': file_size,
                    'risk_score': risk_score,
                    'compliance_score': compliance_score,
                    'risk_level': risk_level,
                    'analysis_time': analysis_time
                }),
                ip_address=request.remote_addr,
                user_agent=request.user_agent.string if request.user_agent else None
            )
            db.session.add(audit_log)
            db.session.commit()
            
            return jsonify({
                'success': True,
                'analysis': {
                    'status': 'analyzed',
                    'risk_level': risk_level,
                    'risk_score': risk_score,
                    'compliance_score': compliance_score,
                    'compliance_status': compliance_status,
                    'document_id': document.id,
                    'upload_file_id': upload_file.id,
                    'original_filename': original_filename,
                    'analysis_details': analysis_details,
                    'analysis_time_seconds': round(analysis_time, 2),
                    'download_url': f"/api/documents/download/{document.id}",
                    'preview_url': f"/api/documents/preview/{document.id}" if hasattr(document, 'has_preview') and document.has_preview else None
                },
                'notifications': {
                    'created': True,
                    'incident_created': risk_level == 'high' and request.plan_features.get('auto_incident_creation', False)
                },
                'usage_stats': request.usage_stats,
                'plan_info': {
                    'current_plan': request.effective_plan,
                    'upload_limit': request.plan_limits.get('uploads_per_month', 'Unlimited'),
                    'uploads_used': user.monthly_uploads_used
                }
            }), 200
            
        except Exception as analysis_error:
            # Mark document as failed
            document = Document(
                user_id=user.id,
                upload_file_id=upload_file.id,
                filename=unique_filename,
                originalname=original_filename,
                uploaded_at=datetime.utcnow(),
                doc_type=file_extension.upper(),
                file_size=file_size,
                mime_type=file.content_type,
                status='failed',
                error_message=str(analysis_error),
                batch_metadata=json.dumps({
                    'error': str(analysis_error),
                    'failed_at': datetime.utcnow().isoformat()
                })
            )
            db.session.add(document)
            
            # Still update usage even if failed
            user.monthly_api_calls_used += 1
            user.monthly_uploads_used += 1
            db.session.commit()
            
            logger.error(f"Document analysis failed: {analysis_error}", exc_info=True)
            
            return jsonify({
                'success': False,
                'error': 'Document analysis failed',
                'details': str(analysis_error) if current_app.debug else 'Analysis failed. Please try again.',
                'document_id': document.id,
                'status': 'failed',
                'usage_stats': request.usage_stats
            }), 500
        
    except Exception as e:
        logger.error(f"Document analysis endpoint error: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Document analysis failed',
            'details': str(e) if current_app.debug else 'An unexpected error occurred.'
        }), 500

@app.route('/api/documents/analyze-multi', methods=['POST', 'OPTIONS'])
@jwt_required
def analyze_documents_multi():
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        user = request.user
        
        # Check if document analysis feature is available
        if not request.plan_features.get('document_analysis', False) and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Document analysis not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'upgrade_required': True
            }), 403
        
        # Check upload limits for multiple files
        files = request.files.getlist('files')
        if not files or all(file.filename == '' for file in files):
            return jsonify({
                'success': False,
                'error': 'No files selected'
            }), 400
        
        # Check if number of files exceeds batch limit
        batch_limit = request.plan_limits.get('batch_upload_limit', 10)
        if len(files) > batch_limit:
            return jsonify({
                'success': False,
                'error': f'Number of files exceeds batch limit of {batch_limit}',
                'code': 'BATCH_LIMIT_EXCEEDED',
                'batch_limit': batch_limit,
                'files_submitted': len(files)
            }), 400
        
        # Check upload limits
        remaining_uploads = request.usage_stats['uploads']['remaining']
        if remaining_uploads is not None and len(files) > remaining_uploads:
            return jsonify({
                'success': False,
                'error': f'Not enough upload credits. You have {remaining_uploads} remaining, but trying to upload {len(files)} files',
                'code': 'UPLOAD_LIMIT_EXCEEDED',
                'usage': request.usage_stats['uploads'],
                'files_submitted': len(files)
            }), 429
        
        # Get batch ID for tracking
        batch_id = f"BATCH-{datetime.utcnow().strftime('%Y%m%d%H%M%S')}-{random.randint(1000, 9999)}"
        batch_start_time = datetime.utcnow()
        
        results = []
        failed_files = []
        total_file_size = 0
        max_file_size = request.plan_limits.get('max_file_size_mb', 10) * 1024 * 1024
        
        # Ensure upload folder exists
        upload_folder = current_app.config.get('UPLOAD_FOLDER', 'uploads')
        if not os.path.exists(upload_folder):
            os.makedirs(upload_folder)
        
        for file_index, file in enumerate(files):
            file_result = {
                'filename': file.filename,
                'status': 'pending',
                'error': None
            }
            
            try:
                if not file or file.filename == '':
                    file_result['status'] = 'skipped'
                    file_result['error'] = 'Empty filename'
                    failed_files.append(file_result)
                    continue
                
                if not allowed_file(file.filename):
                    file_result['status'] = 'skipped'
                    file_result['error'] = 'File type not allowed'
                    failed_files.append(file_result)
                    continue
                
                # Check individual file size
                file.seek(0, 2)
                file_size = file.tell()
                file.seek(0)
                total_file_size += file_size
                
                if file_size > max_file_size:
                    file_result['status'] = 'skipped'
                    file_result['error'] = f'File size exceeds {request.plan_limits.get("max_file_size_mb", 10)}MB limit'
                    failed_files.append(file_result)
                    continue
                
                # Generate unique filename
                original_filename = secure_filename(file.filename)
                file_extension = original_filename.rsplit('.', 1)[1].lower() if '.' in original_filename else ''
                timestamp = datetime.utcnow().strftime('%Y%m%d_%H%M%S_%f')[:-3]
                unique_filename = f"{user.id}_{timestamp}_{file_index}_{original_filename}"
                
                file_path = os.path.join(upload_folder, unique_filename)
                file.save(file_path)
                
                # Create upload file record
                upload_file = UploadFile(
                    user_id=user.id,
                    filename=unique_filename,
                    original_filename=original_filename,
                    file_path=file_path,
                    file_size=file_size,
                    mime_type=file.content_type,
                    upload_type='document',
                    uploaded_at=datetime.utcnow(),
                    category=request.form.get('category', 'general'),
                    batch_id=batch_id,
                    is_public=request.form.get('is_public', 'false').lower() == 'true',
                    tags=request.form.get('tags', ''),
                    metadata=json.dumps({
                        'upload_source': 'batch_document_analysis',
                        'original_filename': original_filename,
                        'content_type': file.content_type,
                        'batch_id': batch_id,
                        'file_index': file_index,
                        'uploaded_at': datetime.utcnow().isoformat()
                    })
                )
                db.session.add(upload_file)
                db.session.flush()
                
                # Analyze document content
                analysis_start_time = datetime.utcnow()
                try:
                    risk_score, compliance_score, analysis_details = analyze_document_content(
                        file_path, 
                        file.content_type,
                        user_context={
                            'user_id': user.id,
                            'user_email': user.email,
                            'company_name': user.company_name if hasattr(user, 'company_name') else None,
                            'industry': user.industry if hasattr(user, 'industry') else None,
                            'batch_analysis': True,
                            'batch_id': batch_id
                        }
                    )
                    analysis_time = (datetime.utcnow() - analysis_start_time).total_seconds()
                    
                    # Determine risk level
                    risk_level = "low"
                    if risk_score > 70:
                        risk_level = "high"
                    elif risk_score > 30:
                        risk_level = "medium"
                    
                    # Determine compliance status
                    compliance_status = "compliant"
                    if compliance_score < 60:
                        compliance_status = "non_compliant"
                    elif compliance_score < 80:
                        compliance_status = "partially_compliant"
                    
                    # Create document record
                    document = Document(
                        user_id=user.id,
                        upload_file_id=upload_file.id,
                        filename=unique_filename,
                        originalname=original_filename,
                        uploaded_at=datetime.utcnow(),
                        doc_type=file_extension.upper(),
                        file_size=file_size,
                        mime_type=file.content_type,
                        analysis_result=json.dumps(analysis_details),
                        risk_score=risk_score,
                        compliance_score=compliance_score,
                        risk_level=risk_level,
                        compliance_status=compliance_status,
                        analysis_time=analysis_time,
                        status='processed',
                        category=request.form.get('category', 'general'),
                        batch_id=batch_id,
                        tags=request.form.get('tags', ''),
                        metadata=json.dumps({
                            'analysis_details': analysis_details,
                            'analyzed_at': datetime.utcnow().isoformat(),
                            'analysis_time_seconds': analysis_time,
                            'plan_used': request.effective_plan,
                            'batch_id': batch_id,
                            'file_index': file_index
                        })
                    )
                    db.session.add(document)
                    
                    file_result.update({
                        'status': 'processed',
                        'risk_level': risk_level,
                        'risk_score': risk_score,
                        'compliance_score': compliance_score,
                        'compliance_status': compliance_status,
                        'document_id': document.id,
                        'upload_file_id': upload_file.id,
                        'analysis_time_seconds': round(analysis_time, 2),
                        'download_url': f"/api/documents/download/{document.id}"
                    })
                    
                    results.append(file_result)
                    
                except Exception as analysis_error:
                    # Mark document as failed
                    document = Document(
                        user_id=user.id,
                        upload_file_id=upload_file.id,
                        filename=unique_filename,
                        originalname=original_filename,
                        uploaded_at=datetime.utcnow(),
                        doc_type=file_extension.upper(),
                        file_size=file_size,
                        mime_type=file.content_type,
                        status='failed',
                        error_message=str(analysis_error),
                        batch_id=batch_id,
                        metadata=json.dumps({
                            'error': str(analysis_error),
                            'failed_at': datetime.utcnow().isoformat(),
                            'batch_id': batch_id
                        })
                    )
                    db.session.add(document)
                    
                    file_result['status'] = 'failed'
                    file_result['error'] = str(analysis_error)
                    failed_files.append(file_result)
                    
            except Exception as file_error:
                logger.error(f"Error processing file {file.filename}: {file_error}")
                file_result['status'] = 'failed'
                file_result['error'] = str(file_error)
                failed_files.append(file_result)
        
        # Calculate batch statistics
        processed_count = len([r for r in results if r['status'] == 'processed'])
        failed_count = len(failed_files)
        skipped_count = len([f for f in failed_files if f['status'] == 'skipped'])
        
        # Create batch record
        batch = BatchProcess(
            user_id=user.id,
            batch_id=batch_id,
            process_type='document_analysis',
            total_files=len(files),
            processed_files=processed_count,
            failed_files=failed_count,
            skipped_files=skipped_count,
            start_time=batch_start_time,
            end_time=datetime.utcnow(),
            status='completed' if failed_count == 0 else 'partial',
            total_size=total_file_size,
            metadata=json.dumps({
                'results': results,
                'failed_files': failed_files,
                'total_file_size': total_file_size,
                'average_file_size': total_file_size / len(files) if files else 0,
                'plan_used': request.effective_plan
            })
        )
        db.session.add(batch)
        
        # Create notification for batch completion
        if processed_count > 0:
            notification = Notification(
                user_id=user.id,
                title='Batch Document Analysis Complete',
                message=f'Batch analysis complete. Processed: {processed_count}, Failed: {failed_count}',
                type='success' if failed_count == 0 else 'warning',
                category='document',
                reference_id=batch.id,
                reference_type='batch',
                priority='medium',
                metadata=json.dumps({
                    'batch_id': batch_id,
                    'processed_count': processed_count,
                    'failed_count': failed_count,
                    'total_files': len(files)
                })
            )
            db.session.add(notification)
        
        # Update usage
        user.monthly_api_calls_used += 1
        user.monthly_uploads_used += processed_count + failed_count  # Count all attempted uploads
        
        # Log batch analysis
        audit_log = AuditLog(
            user_id=user.id,
            action='batch_document_analysis',
            resource_type='batch',
            resource_id=batch.id,
            details=json.dumps({
                'batch_id': batch_id,
                'total_files': len(files),
                'processed_count': processed_count,
                'failed_count': failed_count,
                'skipped_count': skipped_count,
                'total_size_bytes': total_file_size,
                'batch_time_seconds': (datetime.utcnow() - batch_start_time).total_seconds()
            }),
            ip_address=request.remote_addr,
            user_agent=request.user_agent.string if request.user_agent else None
        )
        db.session.add(audit_log)
        
        db.session.commit()
        
        batch_time = (datetime.utcnow() - batch_start_time).total_seconds()
        
        return jsonify({
            'success': True,
            'batch': {
                'batch_id': batch_id,
                'total_files': len(files),
                'processed': processed_count,
                'failed': failed_count,
                'skipped': skipped_count,
                'success_rate': round((processed_count / len(files)) * 100, 1) if files else 0,
                'batch_time_seconds': round(batch_time, 2),
                'average_time_per_file': round(batch_time / len(files), 2) if files and processed_count > 0 else 0,
                'total_size_bytes': total_file_size,
                'total_size_mb': round(total_file_size / (1024 * 1024), 2),
                'status': 'completed' if failed_count == 0 else 'partial',
                'results': results,
                'failed_files': failed_files if failed_count > 0 else []
            },
            'summary': {
                'high_risk_count': len([r for r in results if r.get('risk_level') == 'high']),
                'medium_risk_count': len([r for r in results if r.get('risk_level') == 'medium']),
                'low_risk_count': len([r for r in results if r.get('risk_level') == 'low']),
                'average_risk_score': round(sum(r.get('risk_score', 0) for r in results) / processed_count, 1) if processed_count > 0 else 0,
                'average_compliance_score': round(sum(r.get('compliance_score', 0) for r in results) / processed_count, 1) if processed_count > 0 else 0
            },
            'usage_stats': request.usage_stats,
            'plan_info': {
                'current_plan': request.effective_plan,
                'batch_limit': batch_limit,
                'max_file_size_mb': request.plan_limits.get('max_file_size_mb', 10),
                'uploads_used': user.monthly_uploads_used,
                'uploads_remaining': request.usage_stats['uploads']['remaining']
            },
            'download_options': {
                'batch_report': f"/api/batches/report/{batch_id}",
                'high_risk_documents': f"/api/documents/batch/{batch_id}/high-risk"
            } if processed_count > 0 else {}
        }), 200
        
    except Exception as e:
        logger.error(f"Multi-document analysis error: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Batch document analysis failed',
            'details': str(e) if current_app.debug else 'An unexpected error occurred during batch processing.'
        }), 500
# Incidents - Report
@app.route('/api/incidents/report', methods=['POST', 'OPTIONS'])
@jwt_required
def report_incident():
    """Report a new safety incident with evidence file uploads"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        current_user = request.user
        data = request.get_json()
        
        if not data:
            return jsonify({'error': 'No JSON data provided'}), 400
        
        # ✅ Get company_id from user if not provided
        company_id = data.get('company_id')
        if not company_id and current_user.company_id:
            company_id = current_user.company_id
        elif not company_id:
            company = current_user.company if hasattr(current_user, 'company') else None
            if company:
                company_id = company.id
        
        # Check incident reporting limits for non-enterprise plans
        if request.effective_plan != 'enterprise':
            max_monthly_incidents = request.plan_limits.get('max_monthly_incidents', 50)
            current_month = datetime.utcnow().month
            current_year = datetime.utcnow().year
            incidents_this_month = Incident.query.filter(
                Incident.reported_by == current_user.id,
                db.extract('year', Incident.date_reported) == current_year,
                db.extract('month', Incident.date_reported) == current_month
            ).count()
            
            if incidents_this_month >= max_monthly_incidents:
                return jsonify({
                    'success': False,
                    'error': f'Monthly incident reporting limit reached ({max_monthly_incidents})',
                    'code': 'MONTHLY_INCIDENT_LIMIT',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited incident reporting',
                    'current_usage': incidents_this_month,
                    'reset_date': (datetime.utcnow().replace(day=1) + timedelta(days=32)).replace(day=1).isoformat(),
                    'emergency_contact': 'safety-hotline@company.com'
                }), 403
        
        # Validate required fields
        required_fields = ['title', 'description', 'incident_type', 'severity', 'date_occurred']
        missing_fields = [field for field in required_fields if field not in data]
        
        if missing_fields:
            return jsonify({
                'success': False,
                'error': f'Missing required fields: {", ".join(missing_fields)}',
                'code': 'MISSING_REQUIRED_FIELDS',
                'suggestion': f'Provide {", ".join(missing_fields)} for incident reporting'
            }), 400
        
        # Validate severity level
        allowed_severities = ['low', 'medium', 'high', 'critical']
        if data['severity'] not in allowed_severities:
            return jsonify({
                'success': False,
                'error': f'Invalid severity. Allowed values: {", ".join(allowed_severities)}',
                'code': 'INVALID_SEVERITY',
                'suggestion': f'Choose from allowed severity levels'
            }), 400
        
        # Generate incident number
        timestamp = datetime.utcnow().strftime('%Y%m%d')
        random_str = str(uuid.uuid4())[:6].upper()
        plan_prefix = {
            'free': 'F',
            'pro': 'P',
            'business': 'B',
            'enterprise': 'E'
        }.get(request.effective_plan, 'G')
        incident_number = f"INC-{plan_prefix}{timestamp}-{random_str}"
        
        # Parse date_occurred
        date_occurred = data.get('date_occurred')
        if date_occurred:
            try:
                date_occurred = datetime.fromisoformat(date_occurred.replace('Z', '+00:00'))
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid date format',
                    'code': 'INVALID_DATE_FORMAT',
                    'suggestion': 'Use ISO 8601 format: YYYY-MM-DDTHH:MM:SSZ'
                }), 400
        else:
            date_occurred = datetime.utcnow()
        
        # ✅ Create incident with ALL valid fields
        incident = Incident(
            incident_number=incident_number,
            title=data['title'],
            description=data['description'],
            incident_type=data['incident_type'],
            severity=data['severity'],
            status=data.get('status', 'reported'),
            location=data.get('location'),
            department=data.get('department'),
            company_id=company_id,  # ✅ Required field
            hospital_id=data.get('hospital_id'),
            department_id=data.get('department_id'),
            industry_id=data.get('industry_id'),
            reported_by=current_user.id,  # ✅ Required field
            assigned_to=data.get('assigned_to'),
            date_occurred=date_occurred,  # ✅ Required field
            date_reported=datetime.utcnow(),  # ✅ Required field
            investigation_details=data.get('investigation_details'),
            corrective_actions=data.get('corrective_actions'),
            root_cause=data.get('root_cause')
        )
        
        db.session.add(incident)
        db.session.flush()  # Get incident ID
        
        # ==================== HANDLE EVIDENCE FILES ====================
        evidence_files = data.get('evidence_files', [])
        uploaded_attachments = []
        
        if evidence_files:
            # Create incident directory
            incident_folder = os.path.join(UPLOAD_FOLDER, 'incidents', str(incident.id))
            os.makedirs(incident_folder, exist_ok=True)
            
            # Process each file
            for file_data in evidence_files:
                try:
                    file_name = file_data.get('name', '')
                    file_size = file_data.get('size', 0)
                    file_type = file_data.get('type', '')
                    file_url = file_data.get('url', '')
                    
                    file_extension = file_name.rsplit('.', 1)[1].lower() if '.' in file_name else ''
                    stored_filename = f"{uuid.uuid4().hex}.{file_extension}" if file_extension else f"{uuid.uuid4().hex}"
                    file_path = os.path.join(incident_folder, stored_filename)
                    
                    file_type_category = 'other'
                    if file_type and file_type.startswith('image/'):
                        file_type_category = 'image'
                    elif file_type and file_type.startswith('video/'):
                        file_type_category = 'video'
                    elif file_type in ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document']:
                        file_type_category = 'document'
                    elif file_type in ['application/zip', 'application/x-rar-compressed']:
                        file_type_category = 'archive'
                    
                    attachment = IncidentAttachment(
                        incident_id=incident.id,
                        upload_file_id=None,
                        filename=file_name,
                        stored_filename=stored_filename,
                        file_path=file_path,
                        file_size=file_size,
                        mime_type=file_type or 'application/octet-stream',
                        file_type=file_type_category,
                        uploaded_by=current_user.id,
                        uploaded_at=datetime.utcnow(),
                        description=data.get('evidence_description', f'Evidence file: {file_name}'),
                        extra_data={
                            'uploaded_via': 'incident_report',
                            'file_url': file_url,
                            'processed': False,
                            'needs_download': True,
                            'uploaded_by_name': current_user.name or current_user.email
                        }
                    )
                    
                    db.session.add(attachment)
                    uploaded_attachments.append(attachment)
                    
                    timeline_entry = IncidentTimeline(
                        incident_id=incident.id,
                        action='file_uploaded',
                        details=f'Evidence file uploaded: {file_name}',
                        user_id=current_user.id,
                        timestamp=datetime.utcnow(),
                        data={
                            'filename': file_name,
                            'file_size': file_size,
                            'file_type': file_type,
                            'attachment_id': attachment.id
                        }
                    )
                    db.session.add(timeline_entry)
                    
                except Exception as e:
                    current_app.logger.error(f'Failed to process evidence file: {str(e)}')
                    continue
            
            db.session.commit()
        
        # ✅ Add timeline entry for incident creation
        timeline_entry = IncidentTimeline(
            incident_id=incident.id,
            action='created',
            details=f'Incident reported by {current_user.name}',
            user_id=current_user.id,
            timestamp=datetime.utcnow(),
            data={'reported_via': 'api'}
        )
        db.session.add(timeline_entry)
        
        # ✅ Create incident report log
        report_log = IncidentReportLog(
            incident_id=incident.id,
            user_id=current_user.id,
            action='reported',
            details=f"Incident reported: {data['title']}",
            plan=request.effective_plan
        )
        db.session.add(report_log)
        
        db.session.commit()
        
        # ✅ Create notifications for the incident
        notify_incident_report(incident, current_user)
        
        # ✅ Create activity log
        create_activity_log(
            user_id=current_user.id,
            activity_type='incident_reported',
            description=f"Reported incident: {incident.title}",
            metadata={'incident_id': incident.id, 'incident_number': incident.incident_number}
        )
        
        # Prepare response
        incident_dict = incident.to_dict()
        incident_dict['attachments'] = [att.to_dict() for att in uploaded_attachments]
        incident_dict['attachments_count'] = len(uploaded_attachments)
        
        return jsonify({
            'success': True,
            'incident': incident_dict,
            'message': 'Incident reported successfully',
            'reporting_info': {
                'incident_number': incident.incident_number,
                'reporting_timestamp': incident.date_reported.isoformat(),
                'expected_response_time': '2 hours' if data['severity'] in ['high', 'critical'] else '24 hours',
                'next_steps': [
                    'Incident will be reviewed by safety team',
                    'Investigator will be assigned shortly',
                    'Check status updates in dashboard'
                ]
            },
            'attachments_info': {
                'uploaded_count': len(uploaded_attachments),
                'total_attachments': len(uploaded_attachments),
                'attachments': [att.to_dict() for att in uploaded_attachments]
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error reporting incident: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': f'Failed to report incident: {str(e)}',
            'code': 'INCIDENT_REPORT_ERROR'
        }), 500

# ============================================
# ADMIN INCIDENTS ENDPOINT
# ============================================

@app.route('/api/admin/incidents', methods=['GET', 'OPTIONS'])
@jwt_required
def admin_incidents():
    """Get all incidents for admin with company-based filtering"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        current_user = request.user
        
        # ✅ Check if user is admin or system team
        if current_user.user_type != 'admin' and not request.is_system_team and current_user.user_type != 'super_admin':
            return jsonify({
                'success': False,
                'error': 'Admin access required',
                'code': 'ADMIN_ACCESS_REQUIRED'
            }), 403
        
        # Get query parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        status_filter = request.args.get('status')
        severity_filter = request.args.get('severity')
        incident_type_filter = request.args.get('type')
        company_id_filter = request.args.get('company_id')
        search = request.args.get('search')
        
        # ✅ Build query with company-based filtering
        query = Incident.query
        
        # ✅ If not super admin, filter by company
        if current_user.user_type != 'super_admin' and not request.is_system_team:
            if current_user.company_id:
                query = query.filter_by(company_id=current_user.company_id)
            else:
                # Admin without company - no incidents
                return jsonify({
                    'success': True,
                    'incidents': [],
                    'total': 0,
                    'pages': 0,
                    'current_page': page,
                    'message': 'No company assigned to this admin'
                }), 200
        
        # Apply filters
        if status_filter:
            query = query.filter_by(status=status_filter)
        if severity_filter:
            query = query.filter_by(severity=severity_filter)
        if incident_type_filter:
            query = query.filter_by(incident_type=incident_type_filter)
        if company_id_filter:
            query = query.filter_by(company_id=company_id_filter)
        if search:
            query = query.filter(
                db.or_(
                    Incident.title.ilike(f'%{search}%'),
                    Incident.description.ilike(f'%{search}%'),
                    Incident.incident_number.ilike(f'%{search}%')
                )
            )
        
        # Paginate
        incidents = query.order_by(Incident.created_at.desc()).paginate(
            page=page, per_page=per_page, error_out=False
        )
        
        # Format incidents
        incidents_data = []
        for incident in incidents.items:
            reporter_name = incident.reporter.name if incident.reporter else 'Unknown'
            assignee_name = incident.assignee.name if incident.assignee else None
            
            incidents_data.append({
                'id': incident.id,
                'incident_number': incident.incident_number,
                'title': incident.title,
                'description': incident.description,
                'incident_type': incident.incident_type,
                'severity': incident.severity,
                'status': incident.status,
                'location': incident.location,
                'department': incident.department,
                'company_id': incident.company_id,
                'hospital_id': incident.hospital_id,
                'reported_by': incident.reported_by,
                'reporter_name': reporter_name,
                'assigned_to': incident.assigned_to,
                'assignee_name': assignee_name,
                'date_occurred': incident.date_occurred.isoformat() if incident.date_occurred else None,
                'date_reported': incident.date_reported.isoformat() if incident.date_reported else None,
                'created_at': incident.created_at.isoformat() if incident.created_at else None,
                'updated_at': incident.updated_at.isoformat() if incident.updated_at else None,
                'attachments_count': len(incident.attachments) if incident.attachments else 0
            })
        
        # Update API usage
        current_user.monthly_api_calls_used = getattr(current_user, 'monthly_api_calls_used', 0) + 1
        db.session.commit()
        
        return jsonify({
            'success': True,
            'incidents': incidents_data,
            'total': incidents.total,
            'pages': incidents.pages,
            'current_page': page,
            'per_page': per_page,
            'has_next': incidents.has_next,
            'has_prev': incidents.has_prev,
            'user_id': current_user.id,
            'user_type': current_user.user_type,
            'company_id': current_user.company_id
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Admin incidents error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR'
        }), 500
# AI Services
@app.route('/api/ai/documents/generate', methods=['POST', 'OPTIONS'])
@jwt_required
def ai_documents_generate():
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        user = request.user
        
        # Check AI feature access
        if not request.plan_features.get('ai_document_generation', False) and not request.is_system_team:
            return jsonify({
                'error': 'AI document generation not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'upgrade_required': True
            }), 403
        
        # Check AI request limits
        if (request.usage_stats['ai_requests']['remaining'] is not None and 
            request.usage_stats['ai_requests']['remaining'] <= 0):
            return jsonify({
                'error': 'Monthly AI request limit reached',
                'code': 'AI_LIMIT_REACHED',
                'usage': request.usage_stats['ai_requests']
            }), 429
        
        data = request.get_json()
        
        if not data:
            return jsonify({'error': 'No JSON data provided'}), 400
        
        if not data.get('title') or not data.get('content_type'):
            return jsonify({'error': 'Title and content type are required'}), 400
        
        # Generate AI content
        generated_content = generate_ai_content(
            data.get('title'),
            data.get('content_type'),
            data.get('parameters', {}),
            user.company_name,
            user.industry
        )
        
        # Save AI document
        ai_doc = AIDocument(
            user_id=user.id,
            title=data.get('title'),
            content_type=data.get('content_type'),
            generated_content=generated_content,
            parameters=json.dumps(data.get('parameters', {}))
        )
        db.session.add(ai_doc)
        
        # Log AI request
        ai_request = AIRequest(
            user_id=user.id,
            request_type=f"document_generation_{data.get('content_type')}",
            user_input=json.dumps(data),
            ai_response=generated_content,
            company_name=user.company_name,
            include_logo=bool(user.company_logo),
            status='completed',
            processing_time=2.5,  # Simulated processing time
            tokens_used=len(generated_content) // 4,  # Rough estimate
            cost=0.02  # Simulated cost
        )
        db.session.add(ai_request)
        
        # Update usage
        user.monthly_api_calls_used += 1
        user.monthly_ai_requests_used += 1
        db.session.commit()
        
        return jsonify({
            'doc': {
                'id': ai_doc.id,
                'title': ai_doc.title,
                'content': ai_doc.generated_content,
                'content_type': ai_doc.content_type,
                'created_at': ai_doc.created_at.isoformat()
            },
            'usage_stats': request.usage_stats
        }), 200
        
    except Exception as e:
        logger.error(f"AI document generation error: {e}")
        db.session.rollback()
        return jsonify({'error': 'AI document generation failed'}), 500

