# Analytics endpoints
@app.route('/api/analytics/<module>', methods=['GET', 'OPTIONS'])
@jwt_required
def module_analytics(module):
    """Advanced module analytics with industrial-standard ISO-compliant processing"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        user = request.user
        
        # Check analytics feature access
        if not request.plan_features.get('advanced_analytics', False) and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Advanced analytics not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'upgrade_required': True
            }), 403
        
        # Parse query parameters
        timeframe = request.args.get('timeframe', 'monthly')
        compare_previous = request.args.get('compare_previous', 'true').lower() == 'true'
        include_forecast = request.args.get('include_forecast', 'false').lower() == 'true'
        metrics = request.args.getlist('metrics')  # Specific metrics to include
        
        # Validate module access
        if not has_module_access(user.id, module, user.role):
            return jsonify({
                'success': False,
                'error': f'Access denied to module: {module}'
            }), 403
        
        # Generate comprehensive analytics with ISO standards
        analytics_data = generate_comprehensive_module_analytics(
            user_id=user.id,
            module=module,
            timeframe=timeframe,
            compare_previous=compare_previous,
            include_forecast=include_forecast,
            requested_metrics=metrics
        )
        
        # Generate industrial-standard insights
        industrial_insights = generate_industrial_module_insights(analytics_data, module, user.id)
        
        # Performance metrics
        processing_time = analytics_data.get('_metadata', {}).get('processing_time_ms', 0)
        
        response_data = {
            'success': True,
            'module': module,
            'timeframe': timeframe,
            'generated_at': datetime.utcnow().isoformat() + 'Z',  # ISO 8601 with UTC
            'data_freshness': analytics_data.get('_metadata', {}).get('data_freshness'),
            'processing_time_ms': processing_time,
            'analytics': {
                'summary_metrics': analytics_data.get('summary_metrics', {}),
                'trend_analysis': analytics_data.get('trend_analysis', {}),
                'performance_indicators': analytics_data.get('performance_indicators', {}),
                'comparative_analysis': analytics_data.get('comparative_analysis', {}),
                'risk_assessment': analytics_data.get('risk_assessment', {}),
                'forecast_data': analytics_data.get('forecast_data', {})
            },
            'industrial_insights': industrial_insights,
            'recommendations': generate_iso_compliant_recommendations(analytics_data, module),
            'data_sources': analytics_data.get('_metadata', {}).get('data_sources', []),
            'compliance_standards': get_applicable_iso_standards(module),
            'plan_info': {
                'current_plan': request.effective_plan,
                'is_trial': request.is_trial_active,
                'is_system_team': request.is_system_team
            }
        }
        
        # Cache the response for performance
        cache_analytics_response(module, user.id, timeframe, response_data)
        
        # Update API usage
        user.monthly_api_calls_used += 1
        db.session.commit()
        response_data['usage_stats'] = request.usage_stats
        
        return jsonify(response_data), 200
        
    except Exception as e:
        logger.error(f"Module analytics error for {module}: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to generate analytics',
            'message': 'Please try again or contact support'
        }), 500

def generate_comprehensive_module_analytics(user_id, module, timeframe, compare_previous, include_forecast, requested_metrics):
    """Generate comprehensive analytics for a module with ISO standards"""
    start_time = datetime.utcnow()
    
    with db.session() as session:
        # Get time range based on timeframe
        date_range = calculate_date_range(timeframe)
        previous_range = calculate_date_range(timeframe, previous_period=True) if compare_previous else None
        
        # Base data collection with ISO-compliant validation
        base_data = collect_module_base_data(session, user_id, module, date_range)
        previous_data = collect_module_base_data(session, user_id, module, previous_range) if compare_previous else None
        
        # Initialize analytics structure with ISO metadata
        analytics = {
            'summary_metrics': calculate_iso_compliant_metrics(base_data, module),
            'trend_analysis': analyze_trends_with_iso_standards(base_data, timeframe),
            'performance_indicators': calculate_iso_performance_indicators(base_data, module),
            'risk_assessment': assess_module_risks_iso_31000(base_data, module),
            '_metadata': {
                'data_sources': ['incidents', 'documents', 'users', 'activities'],
                'record_count': len(base_data.get('incidents', [])),
                'processing_time_ms': 0,
                'data_freshness': 'real_time',
                'quality_standards': ['ISO 9001', 'ISO 14001', 'ISO 45001', 'ISO 31000'],
                'data_integrity_level': 'verified',
                'audit_trail_available': True
            }
        }
        
        # Add comparative analysis if requested
        if compare_previous and previous_data:
            analytics['comparative_analysis'] = perform_iso_comparative_analysis(
                base_data, previous_data, timeframe
            )
        
        # Add forecasting if requested
        if include_forecast:
            analytics['forecast_data'] = generate_iso_forecasts(base_data, timeframe, module)
        
        # Filter metrics if specific ones requested
        if requested_metrics:
            analytics = filter_requested_metrics(analytics, requested_metrics)
        
        # Calculate processing time
        processing_time = (datetime.utcnow() - start_time).total_seconds() * 1000
        analytics['_metadata']['processing_time_ms'] = round(processing_time, 2)
        
        return analytics

def calculate_iso_compliant_metrics(data, module):
    """Calculate comprehensive summary metrics following ISO standards"""
    incidents = data.get('incidents', [])
    documents = data.get('documents', [])
    
    metrics = {
        'incidents': {
            'total': len(incidents),
            'by_severity': count_by_severity(incidents),
            'by_status': count_by_status(incidents),
            'avg_resolution_time': calculate_avg_resolution_time(incidents),
            'trend': calculate_incident_trend(incidents),
            'iso_45001_compliance': assess_iso_45001_compliance(incidents),
            'ohs_performance': calculate_ohs_performance(incidents)
        },
        'documents': {
            'total': len(documents),
            'by_type': count_documents_by_type(documents),
            'total_size': sum(doc.file_size for doc in documents if doc.file_size),
            'avg_risk_score': calculate_avg_risk_score(documents),
            'iso_9001_compliance': assess_document_control_compliance(documents)
        },
        'compliance': {
            'score': calculate_iso_compliance_score(data.get('compliance_checks', [])),
            'checks_performed': len(data.get('compliance_checks', [])),
            'pass_rate': calculate_compliance_pass_rate(data.get('compliance_checks', [])),
            'non_conformities': identify_non_conformities(data.get('compliance_checks', [])),
            'corrective_actions': track_corrective_actions(data.get('compliance_checks', []))
        },
        'user_engagement': {
            'active_days': calculate_active_days(data.get('user_activities', [])),
            'total_actions': len(data.get('user_activities', [])),
            'most_used_features': get_most_used_features(data.get('user_activities', [])),
            'training_effectiveness': assess_training_effectiveness(data.get('user_activities', []))
        },
        'environmental_metrics': calculate_iso_14001_metrics(data, module) if module == 'hse' else {},
        'quality_metrics': calculate_iso_9001_metrics(data, module)
    }
    
    # Add module-specific ISO metrics
    module_specific_metrics = calculate_module_specific_iso_metrics(data, module)
    metrics.update(module_specific_metrics)
    
    return metrics

def analyze_trends_with_iso_standards(data, timeframe):
    """Analyze trends following ISO standards"""
    incidents = data.get('incidents', [])
    
    if timeframe == 'daily':
        interval = 'hour'
    elif timeframe == 'weekly':
        interval = 'day'
    else:  # monthly, quarterly, yearly
        interval = 'week'
    
    trend_data = {
        'incident_frequency': calculate_frequency_trend(incidents, interval),
        'severity_trends': calculate_severity_trends(incidents, interval),
        'response_time_trends': calculate_response_time_trends(incidents, interval),
        'compliance_trends': calculate_compliance_trends(data.get('compliance_checks', []), interval),
        'quality_trends': calculate_quality_trends(data.get('documents', []), interval),
        'environmental_trends': calculate_environmental_trends(data.get('environmental_data', []), interval)
    }
    
    return trend_data

