def generate_iso_compliant_recommendations(analytics_data, module):
    """Generate ISO-compliant actionable recommendations"""
    recommendations = []
    
    # Safety recommendations (ISO 45001)
    if analytics_data.get('summary_metrics', {}).get('incidents', {}).get('total', 0) > 5:
        recommendations.append({
            'category': 'safety',
            'priority': 'high',
            'action': 'Implement enhanced safety training program',
            'standard': 'ISO 45001',
            'expected_impact': 'Reduce incident rate by 25%',
            'timeline': '30 days',
            'responsible_party': 'Safety Manager'
        })
    
    # Quality recommendations (ISO 9001)
    compliance_score = analytics_data.get('summary_metrics', {}).get('compliance', {}).get('score', 0)
    if compliance_score < 90:
        recommendations.append({
            'category': 'quality',
            'priority': 'medium',
            'action': 'Conduct internal quality audit',
            'standard': 'ISO 9001',
            'expected_impact': 'Improve compliance score to 95%',
            'timeline': '14 days',
            'responsible_party': 'Quality Manager'
        })
    
    # Environmental recommendations (ISO 14001)
    if module == 'hse':
        environmental_metrics = analytics_data.get('summary_metrics', {}).get('environmental_metrics', {})
        if environmental_metrics.get('carbon_footprint', 0) > industry_average(module):
            recommendations.append({
                'category': 'environmental',
                'priority': 'medium',
                'action': 'Implement energy efficiency measures',
                'standard': 'ISO 14001',
                'expected_impact': 'Reduce carbon footprint by 15%',
                'timeline': '90 days',
                'responsible_party': 'Environmental Officer'
            })
    
    return recommendations

def get_applicable_iso_standards(module):
    """Get applicable ISO standards based on module"""
    standards = {
        'common': ['ISO 9001', 'ISO 31000'],
        'hospital': ['ISO 9001', 'ISO 45001', 'ISO 14001', 'ISO 15189'],
        'hse': ['ISO 45001', 'ISO 14001', 'ISO 9001', 'ISO 31000'],
        'manufacturing': ['ISO 9001', 'ISO 14001', 'ISO 45001', 'ISO 50001'],
        'construction': ['ISO 45001', 'ISO 14001', 'ISO 9001', 'ISO 19650']
    }
    
    return standards.get(module, standards['common'])

# Industrial Document Generation Functions
def generate_industrial_document(title, content_type, parameters, company_name, industry):
    """Advanced industrial document generation following ISO standards"""
    try:
        # Validate input parameters
        if not all([title, content_type, company_name, industry]):
            raise ValueError("Missing required parameters for document generation")
        
        # Select template based on content type and industry
        template = select_industrial_template(content_type, industry, parameters)
        
        # Prepare industrial context
        context = build_industrial_context(company_name, industry, parameters)
        
        # Generate content using industrial templates
        content = generate_with_industrial_templates(template, title, context, parameters)
        
        # Apply ISO formatting and standards
        formatted_content = apply_iso_formatting(content, content_type, parameters)
        
        # Generate metadata and compliance information
        metadata = {
            'generation_time': datetime.utcnow().isoformat() + 'Z',
            'content_quality_score': assess_industrial_content_quality(formatted_content),
            'compliance_status': check_iso_compliance(formatted_content, industry),
            'applicable_standards': get_document_iso_standards(content_type, industry),
            'review_required': requires_technical_review(content_type),
            'version_control': initialize_version_control()
        }
        
        return {
            'content': formatted_content,
            'metadata': metadata,
            'success': True
        }
        
    except Exception as e:
        logger.error(f"Industrial document generation failed: {str(e)}")
        return {
            'content': generate_industrial_fallback_content(title, content_type, company_name, industry),
            'metadata': {
                'provider': 'industrial_fallback',
                'error': str(e),
                'generation_time': datetime.utcnow().isoformat() + 'Z'
            },
            'success': False
        }

def select_industrial_template(content_type, industry, parameters):
    """Select appropriate industrial template"""
    templates = {
        'safety_report': {
            'hospital': 'templates/hospital_safety_report_iso_45001.jinja2',
            'manufacturing': 'templates/manufacturing_safety_report_iso_45001.jinja2',
            'construction': 'templates/construction_safety_report_iso_45001.jinja2'
        },
        'risk_assessment': {
            'default': 'templates/risk_assessment_iso_31000.jinja2'
        },
        'compliance_report': {
            'default': 'templates/compliance_report_iso_9001.jinja2'
        }
    }
    
    content_templates = templates.get(content_type, templates.get('default', {}))
    return content_templates.get(industry, content_templates.get('default'))

