@app.route('/api/files', methods=['GET'])
@jwt_required
def get_files():
    """Advanced file management with search and filtering"""
    try:
        user = request.user
        user_id = user.id
        
        
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        folder = request.args.get('folder')
        file_type = request.args.get('type')
        search = request.args.get('search')
        
        with db.session() as session:
            query = session.query(File).filter_by(user_id=user_id)
            
            # Apply filters
            if folder:
                query = query.filter_by(folder=folder)
            if file_type:
                query = query.filter(File.mime_type.like(f'%{file_type}%'))
            if search:
                query = query.filter(
                    db.or_(
                        File.original_name.ilike(f'%{search}%'),
                        File.description.ilike(f'%{search}%')
                    )
                )
            
            total_files = query.count()
            total_size = session.query(db.func.sum(File.file_size)).filter_by(
                user_id=user_id
            ).scalar() or 0
            
            files = query.order_by(File.uploaded_at.desc()).offset(
                (page - 1) * per_page
            ).limit(per_page).all()
            
            files_data = []
            for file in files:
                files_data.append({
                    'id': file.id,
                    'filename': file.filename,
                    'original_name': file.original_name,
                    'file_size': file.file_size,
                    'formatted_size': format_file_size(file.file_size),
                    'mime_type': file.mime_type,
                    'folder': file.folder,
                    'description': file.description,
                    'uploaded_at': file.uploaded_at.isoformat(),
                    'download_url': f'/api/files/download/{file.id}',
                    'preview_url': f'/api/files/preview/{file.id}' if is_previewable(file.mime_type) else None
                })
            
            # Folder statistics
            folder_stats = session.query(
                File.folder,
                db.func.count(File.id).label('file_count'),
                db.func.sum(File.file_size).label('total_size')
            ).filter_by(user_id=user_id).group_by(File.folder).all()
            
            folders_data = []
            for folder_stat in folder_stats:
                folders_data.append({
                    'name': folder_stat.folder,
                    'file_count': folder_stat.file_count,
                    'total_size': folder_stat.total_size,
                    'formatted_size': format_file_size(folder_stat.total_size)
                })
            
            return jsonify({
                'success': True,
                'files': files_data,
                'statistics': {
                    'total_files': total_files,
                    'total_size': total_size,
                    'formatted_total_size': format_file_size(total_size),
                    'folders': folders_data
                },
                'pagination': {
                    'page': page,
                    'per_page': per_page,
                    'total': total_files,
                    'pages': (total_files + per_page - 1) // per_page
                }
            }), 200
            
    except Exception as e:
        logger.error(f"Files list error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch files'
        }), 500

def format_file_size(size_bytes):
    """Format file size in human-readable format"""
    if size_bytes == 0:
        return "0 Bytes"
    
    size_names = ["Bytes", "KB", "MB", "GB"]
    i = 0
    while size_bytes >= 1024 and i < len(size_names) - 1:
        size_bytes /= 1024.0
        i += 1
        
    return f"{size_bytes:.2f} {size_names[i]}"

def is_previewable(mime_type):
    """Check if file type can be previewed"""
    previewable_types = [
        'image/', 'text/', 'application/pdf', 
        'application/msword', 'application/vnd.openxmlformats-officedocument'
    ]
    return any(mime_type.startswith(pt) for pt in previewable_types)

