@app.route('/api/environmental/incidents', methods=['GET', 'OPTIONS'])
@cross_origin()
@jwt_required
def get_environmental_incidents():
    """Get environmental incidents with filtering and pagination"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ==================== QUERY PARAMETERS ====================
        status = request.args.get('status')
        incident_type = request.args.get('type')
        severity = request.args.get('severity')
        location = request.args.get('location')
        search = request.args.get('search', '').strip()
        date_from = request.args.get('date_from')
        date_to = request.args.get('date_to')
        limit = request.args.get('limit', 50, type=int)
        offset = request.args.get('offset', 0, type=int)
        sort_by = request.args.get('sort_by', 'reported_date')
        sort_order = request.args.get('sort_order', 'desc')
        
        # Validate limit
        if limit > 100:
            limit = 100
        if limit < 1:
            limit = 10
        
        # ==================== BUILD QUERY ====================
        if is_super_admin:
            company_id = request.args.get('company_id')
            if company_id:
                try:
                    company_id = int(company_id)
                    query = EnvironmentalIncident.query.filter_by(company_id=company_id)
                except ValueError:
                    return jsonify({
                        'success': False,
                        'error': 'Invalid company_id format',
                        'code': 'INVALID_COMPANY_ID'
                    }), 400
            else:
                query = EnvironmentalIncident.query
        else:
            query = EnvironmentalIncident.query.filter_by(company_id=current_user.company_id or 1)
        
        # ==================== APPLY FILTERS ====================
        if status:
            allowed_statuses = ['reported', 'investigating', 'resolved', 'closed', 'pending', 'all']
            if status == 'all':
                pass
            elif status in allowed_statuses:
                query = query.filter_by(status=status)
            else:
                return jsonify({
                    'success': False,
                    'error': f'Invalid status. Allowed: {", ".join(allowed_statuses)}',
                    'code': 'INVALID_STATUS'
                }), 400
        
        # ✅ FIX: Use 'type' column, not 'incident_type'
        if incident_type:
            allowed_types = ['spill', 'emission', 'waste', 'water', 'air', 'soil', 
                            'chemical', 'radiation', 'noise', 'other', 'fire', 'explosion']
            if incident_type not in allowed_types:
                return jsonify({
                    'success': False,
                    'error': f'Invalid type. Allowed: {", ".join(allowed_types)}',
                    'code': 'INVALID_TYPE'
                }), 400
            query = query.filter_by(type=incident_type)  # ✅ Fixed: type=incident_type
        
        if severity:
            allowed_severities = ['low', 'medium', 'high', 'critical', 'minor', 'major', 'severe']
            if severity not in allowed_severities:
                return jsonify({
                    'success': False,
                    'error': f'Invalid severity. Allowed: {", ".join(allowed_severities)}',
                    'code': 'INVALID_SEVERITY'
                }), 400
            query = query.filter_by(severity=severity)
        
        if location:
            query = query.filter(EnvironmentalIncident.location.ilike(f'%{location}%'))
        
        if search:
            query = query.filter(
                db.or_(
                    EnvironmentalIncident.title.ilike(f'%{search}%'),
                    EnvironmentalIncident.description.ilike(f'%{search}%'),
                    EnvironmentalIncident.location.ilike(f'%{search}%')
                )
            )
        
        # Date range filters
        if date_from:
            try:
                date_from_dt = datetime.fromisoformat(date_from.replace('Z', '+00:00'))
                query = query.filter(EnvironmentalIncident.reported_date >= date_from_dt)
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid date_from format. Use ISO format (YYYY-MM-DDTHH:MM:SS)',
                    'code': 'INVALID_DATE_FROM'
                }), 400
        
        if date_to:
            try:
                date_to_dt = datetime.fromisoformat(date_to.replace('Z', '+00:00'))
                query = query.filter(EnvironmentalIncident.reported_date <= date_to_dt)
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid date_to format. Use ISO format (YYYY-MM-DDTHH:MM:SS)',
                    'code': 'INVALID_DATE_TO'
                }), 400
        
        # ==================== SORTING ====================
        if sort_by == 'title':
            order_col = EnvironmentalIncident.title
        elif sort_by == 'severity':
            order_col = EnvironmentalIncident.severity
        elif sort_by == 'status':
            order_col = EnvironmentalIncident.status
        elif sort_by == 'location':
            order_col = EnvironmentalIncident.location
        elif sort_by == 'cost_estimate':
            order_col = EnvironmentalIncident.cost_estimate
        else:
            order_col = EnvironmentalIncident.reported_date
        
        if sort_order.lower() == 'asc':
            query = query.order_by(order_col.asc())
        else:
            query = query.order_by(order_col.desc())
        
        # ==================== PAGINATION ====================
        total = query.count()
        incidents = query.limit(limit).offset(offset).all()
        
        # ==================== PREPARE RESPONSE ====================
        incidents_data = []
        for incident in incidents:
            incident_dict = {
                'id': incident.id,
                'title': incident.title,
                'type': incident.type,  # ✅ FIXED: Use incident.type
                'severity': incident.severity,
                'status': incident.status,
                'location': incident.location,
                'description': incident.description,
                'impact': incident.impact,  # ✅ FIXED: Use incident.impact
                'action_required': incident.action_required,
                'cost_estimate': incident.cost_estimate,
                'department': incident.department,  # ✅ FIXED: Use incident.department
                'reported_by': incident.reported_by,
                'reported_date': incident.reported_date.isoformat() if incident.reported_date else None,
                'estimated_completion': incident.estimated_completion.isoformat() if incident.estimated_completion else None,
                'actual_completion': incident.actual_completion.isoformat() if incident.actual_completion else None,
                'created_at': incident.created_at.isoformat() if incident.created_at else None,
                'updated_at': incident.updated_at.isoformat() if incident.updated_at else None,
                'company_id': incident.company_id,
                'user_id': incident.user_id
            }
            
            # Add user info for super admin
            if is_super_admin and incident.user_id:
                user = User.query.get(incident.user_id)
                if user:
                    incident_dict['reported_by_user'] = {
                        'id': user.id,
                        'email': user.email,
                        'name': user.name
                    }
            
            incidents_data.append(incident_dict)
        
        return jsonify({
            'success': True,
            'incidents': incidents_data,
            'pagination': {
                'total': total,
                'limit': limit,
                'offset': offset,
                'has_more': offset + limit < total
            },
            'filters_applied': {
                'status': status,
                'type': incident_type,
                'severity': severity,
                'location': location,
                'search': search,
                'date_from': date_from,
                'date_to': date_to,
                'sort_by': sort_by,
                'sort_order': sort_order
            },
            'access_level': 'super_admin' if is_super_admin else 'user'
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching environmental incidents: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': 'Failed to fetch environmental incidents',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500

# ============================================================================
# ENVIRONMENTAL INCIDENTS - COMPLETE CRUD WITH VALIDATION
# ============================================================================

@app.route('/api/environmental/incidents', methods=['GET', 'POST'])
@jwt_required
def manage_incidents():
    """Get all incidents or create a new incident - WITH JWT"""
    user = request.user
    
    if request.method == 'GET':
        try:
            logger.info(f"User {user.email} accessing incidents")
            
            # Get pagination parameters
            page = request.args.get('page', 1, type=int)
            per_page = request.args.get('per_page', 10, type=int)
            status_filter = request.args.get('status')
            type_filter = request.args.get('type')
            severity_filter = request.args.get('severity')
            location_filter = request.args.get('location')
            search = request.args.get('search', '').strip()
            
            # Validate pagination
            if page < 1:
                page = 1
            if per_page < 1 or per_page > 100:
                per_page = 10
            
            # Build query with filters
            query = EnvironmentalIncident.query
            
            # Super admin can see all, regular users see their company's incidents
            if not check_super_admin():
                query = query.filter_by(company_id=user.company_id or 1)
            
            if status_filter:
                allowed_statuses = ['reported', 'investigating', 'resolved', 'closed', 'pending']
                if status_filter not in allowed_statuses:
                    return jsonify({
                        'success': False,
                        'error': f'Invalid status. Allowed: {", ".join(allowed_statuses)}',
                        'code': 'INVALID_STATUS'
                    }), 400
                query = query.filter_by(status=status_filter)
            
            if type_filter:
                allowed_types = ['spill', 'emission', 'waste', 'water', 'air', 'soil', 
                                'chemical', 'radiation', 'noise', 'other', 'fire', 'explosion']
                if type_filter not in allowed_types:
                    return jsonify({
                        'success': False,
                        'error': f'Invalid type. Allowed: {", ".join(allowed_types)}',
                        'code': 'INVALID_TYPE'
                    }), 400
                query = query.filter_by(type=type_filter)
            
            if severity_filter:
                allowed_severities = ['low', 'medium', 'high', 'critical', 'minor', 'major', 'severe']
                if severity_filter not in allowed_severities:
                    return jsonify({
                        'success': False,
                        'error': f'Invalid severity. Allowed: {", ".join(allowed_severities)}',
                        'code': 'INVALID_SEVERITY'
                    }), 400
                query = query.filter_by(severity=severity_filter)
            
            if location_filter:
                query = query.filter(EnvironmentalIncident.location.ilike(f'%{location_filter}%'))
            
            if search:
                query = query.filter(
                    db.or_(
                        EnvironmentalIncident.title.ilike(f'%{search}%'),
                        EnvironmentalIncident.description.ilike(f'%{search}%'),
                        EnvironmentalIncident.location.ilike(f'%{search}%')
                    )
                )
                
            # Execute paginated query
            incidents = query.order_by(EnvironmentalIncident.reported_date.desc()).paginate(
                page=page, per_page=per_page, error_out=False
            )
            
            incidents_data = []
            for incident in incidents.items:
                incident_dict = {
                    'id': incident.id,
                    'title': incident.title,
                    'type': incident.type,
                    'severity': incident.severity,
                    'status': incident.status,
                    'location': incident.location,
                    'description': incident.description,
                    'impact': incident.impact,
                    'action_required': incident.action_required,
                    'reported_by': incident.reported_by,
                    'reported_name': incident.reported_name,
                    'reported_date': incident.reported_date.isoformat() if incident.reported_date else None,
                    'estimated_completion': incident.estimated_completion.isoformat() if incident.estimated_completion else None,
                    'actual_completion': incident.actual_completion.isoformat() if incident.actual_completion else None,
                    'department': incident.department,
                    'cost_estimate': incident.cost_estimate,
                    'created_at': incident.created_at.isoformat() if incident.created_at else None,
                    'updated_at': incident.updated_at.isoformat() if incident.updated_at else None
                }
                incidents_data.append(incident_dict)
            
            return jsonify({
                'success': True,
                'incidents': incidents_data,
                'pagination': {
                    'page': page,
                    'per_page': per_page,
                    'total': incidents.total,
                    'pages': incidents.pages,
                    'has_next': incidents.has_next,
                    'has_prev': incidents.has_prev
                },
                'user': {
                    'id': user.id,
                    'email': user.email,
                    'name': user.name
                }
            }), 200
            
        except Exception as e:
            logger.error(f"Get incidents error: {str(e)}", exc_info=True)
            return jsonify({
                'success': False,
                'error': 'Failed to fetch incidents',
                'details': str(e) if app.debug else 'Please try again',
                'code': 'INTERNAL_ERROR'
            }), 500
    
    elif request.method == 'POST':
        try:
            data = request.get_json()
            logger.info(f"User {user.email} creating incident")
            
            if not data:
                return jsonify({
                    'success': False,
                    'error': 'No JSON data provided',
                    'code': 'NO_DATA'
                }), 400
            
            # ==================== COMPREHENSIVE VALIDATION ====================
            
            # 1. Required fields
            required_fields = ['title', 'type', 'severity', 'location', 'description']
            missing_fields = [field for field in required_fields if not data.get(field)]
            
            if missing_fields:
                return jsonify({
                    'success': False,
                    'error': f'Missing required fields: {", ".join(missing_fields)}',
                    'code': 'MISSING_FIELDS',
                    'required_fields': required_fields,
                    'received_fields': list(data.keys())
                }), 400
            
            # 2. Title validation
            title = data['title'].strip()
            if len(title) < 3:
                return jsonify({
                    'success': False,
                    'error': 'Title must be at least 3 characters long',
                    'code': 'TITLE_TOO_SHORT'
                }), 400
            if len(title) > 200:
                return jsonify({
                    'success': False,
                    'error': 'Title must be less than 200 characters',
                    'code': 'TITLE_TOO_LONG'
                }), 400
            
            # 3. Type validation
            allowed_types = ['spill', 'emission', 'waste', 'water', 'air', 'soil', 
                            'chemical', 'radiation', 'noise', 'other', 'fire', 'explosion']
            incident_type = data['type'].lower()
            if incident_type not in allowed_types:
                return jsonify({
                    'success': False,
                    'error': f'Invalid incident type. Allowed: {", ".join(allowed_types)}',
                    'code': 'INVALID_TYPE',
                    'received_type': incident_type
                }), 400
            
            # 4. Severity validation
            allowed_severities = ['low', 'medium', 'high', 'critical', 'minor', 'major', 'severe']
            severity = data['severity'].lower()
            if severity not in allowed_severities:
                return jsonify({
                    'success': False,
                    'error': f'Invalid severity. Allowed: {", ".join(allowed_severities)}',
                    'code': 'INVALID_SEVERITY',
                    'received_severity': severity
                }), 400
            
            # 5. Location validation
            location = data['location'].strip()
            if len(location) < 2:
                return jsonify({
                    'success': False,
                    'error': 'Location must be at least 2 characters',
                    'code': 'LOCATION_TOO_SHORT'
                }), 400
            if len(location) > 500:
                return jsonify({
                    'success': False,
                    'error': 'Location must be less than 500 characters',
                    'code': 'LOCATION_TOO_LONG'
                }), 400
            
            # 6. Description validation
            description = data['description'].strip()
            if len(description) < 10:
                return jsonify({
                    'success': False,
                    'error': 'Description must be at least 10 characters',
                    'code': 'DESCRIPTION_TOO_SHORT'
                }), 400
            if len(description) > 5000:
                return jsonify({
                    'success': False,
                    'error': 'Description must be less than 5000 characters',
                    'code': 'DESCRIPTION_TOO_LONG'
                }), 400
            
            # 7. Impact validation (optional)
            impact = data.get('impact', '').strip()
            if impact and len(impact) > 2000:
                return jsonify({
                    'success': False,
                    'error': 'Impact assessment must be less than 2000 characters',
                    'code': 'IMPACT_TOO_LONG'
                }), 400
            
            # 8. Action required validation (optional)
            action_required = data.get('action_required', '').strip()
            if action_required and len(action_required) > 2000:
                return jsonify({
                    'success': False,
                    'error': 'Action required must be less than 2000 characters',
                    'code': 'ACTION_TOO_LONG'
                }), 400
            
            # 9. Status validation (optional)
            allowed_statuses = ['reported', 'investigating', 'resolved', 'closed', 'pending']
            status = data.get('status', 'reported').lower()
            if status not in allowed_statuses:
                return jsonify({
                    'success': False,
                    'error': f'Invalid status. Allowed: {", ".join(allowed_statuses)}',
                    'code': 'INVALID_STATUS'
                }), 400
            
            # 10. Department validation (optional)
            department = data.get('department', '').strip()
            if department and len(department) > 200:
                return jsonify({
                    'success': False,
                    'error': 'Department must be less than 200 characters',
                    'code': 'DEPARTMENT_TOO_LONG'
                }), 400
            
            # 11. Cost estimate validation (optional)
            cost_estimate = data.get('cost_estimate')
            if cost_estimate is not None:
                try:
                    cost_estimate = float(cost_estimate)
                    if cost_estimate < 0:
                        return jsonify({
                            'success': False,
                            'error': 'Cost estimate cannot be negative',
                            'code': 'COST_NEGATIVE'
                        }), 400
                    if cost_estimate > 999999999:
                        return jsonify({
                            'success': False,
                            'error': 'Cost estimate is too large',
                            'code': 'COST_TOO_LARGE'
                        }), 400
                except (ValueError, TypeError):
                    return jsonify({
                        'success': False,
                        'error': 'Cost estimate must be a valid number',
                        'code': 'INVALID_COST'
                    }), 400
            
            # 12. Estimated completion validation (optional)
            estimated_completion = None
            if data.get('estimated_completion'):
                try:
                    estimated_completion = datetime.fromisoformat(data['estimated_completion'].replace('Z', '+00:00'))
                    estimated_completion = estimated_completion.replace(tzinfo=None)
                    if estimated_completion < datetime.utcnow():
                        return jsonify({
                            'success': False,
                            'error': 'Estimated completion cannot be in the past',
                            'code': 'ESTIMATED_COMPLETION_PAST'
                        }), 400
                except ValueError:
                    return jsonify({
                        'success': False,
                        'error': 'Invalid estimated_completion format. Use ISO format (YYYY-MM-DDTHH:MM:SS)',
                        'code': 'INVALID_ESTIMATED_COMPLETION'
                    }), 400
            
            # ==================== CREATE INCIDENT ====================
            incident = EnvironmentalIncident(
                title=title,
                type=incident_type,
                severity=severity,
                location=location,
                description=description,
                impact=impact,
                action_required=action_required,
                status=status,
                reported_by=user.id,
                reported_name=user.name,
                department=department,
                cost_estimate=cost_estimate,
                estimated_completion=estimated_completion,
                company_id=user.company_id or 1,
                created_at=datetime.utcnow(),
                updated_at=datetime.utcnow()
            )
            
            db.session.add(incident)
            db.session.commit()
            
            # Log incident creation
            activity_log = ActivityLog(
                user_id=user.id,
                activity_type='incident_created',
                description=f'Created incident: {title} ({severity} severity)',
                ip_address=request.remote_addr,
                activity_data={
                    'incident_id': incident.id,
                    'title': title,
                    'type': incident_type,
                    'severity': severity,
                    'location': location
                }
            )
            db.session.add(activity_log)
            db.session.commit()
            
            # Create notifications for high severity
            if severity in ['high', 'critical', 'major', 'severe']:
                try:
                    if 'create_notification' in globals():
                        admins = User.query.filter_by(company_id=user.company_id or 1).filter(
                            User.user_type.in_(['admin', 'safety_officer', 'manager'])
                        ).all()
                        for admin in admins:
                            if admin.id != user.id:
                                create_notification(
                                    admin.id,
                                    f"🚨 {severity.upper()} Environmental Incident",
                                    f"New {severity} severity incident: {title} at {location}",
                                    "warning",
                                    "high",
                                    f"/environmental/incidents/{incident.id}"
                                )
                except Exception as notify_error:
                    logger.warning(f"Failed to create notifications: {notify_error}")
            
            return jsonify({
                'success': True,
                'message': 'Incident created successfully',
                'incident_id': incident.id,
                'incident': {
                    'id': incident.id,
                    'title': incident.title,
                    'type': incident.type,
                    'severity': incident.severity,
                    'status': incident.status,
                    'location': incident.location,
                    'reported_date': incident.reported_date.isoformat() if incident.reported_date else None
                },
                'user': {
                    'id': user.id,
                    'email': user.email,
                    'name': user.name
                },
                'next_steps': [
                    'Incident has been logged and assigned a tracking number',
                    'Environmental team will review and investigate',
                    'You will receive updates on the investigation progress'
                ]
            }), 201
            
        except Exception as e:
            db.session.rollback()
            logger.error(f"Create incident error: {str(e)}", exc_info=True)
            return jsonify({
                'success': False,
                'error': 'Failed to create incident',
                'details': str(e) if app.debug else 'Please try again',
                'code': 'INTERNAL_ERROR'
            }), 500


@app.route('/api/environmental/incidents/<int:incident_id>', methods=['GET', 'PUT', 'DELETE'])
@jwt_required
def manage_single_incident(incident_id):
    """Get, update, or delete a specific incident - WITH JWT"""
    user = request.user
    
    try:
        incident = EnvironmentalIncident.query.get_or_404(incident_id)
        
        # Check company ownership
        if not check_super_admin() and incident.company_id != (user.company_id or 1):
            return jsonify({
                'success': False,
                'error': 'Access denied. Incident does not belong to your company.',
                'code': 'ACCESS_DENIED'
            }), 403
        
        # Check permission for modifications
        is_creator = incident.reported_by == user.id
        is_admin = user.user_type in ['admin', 'safety_officer', 'manager'] or check_super_admin()
        
        if request.method in ['PUT', 'DELETE'] and not (is_creator or is_admin):
            return jsonify({
                'success': False,
                'error': 'Permission denied: You can only modify incidents you created or have admin access',
                'code': 'PERMISSION_DENIED',
                'is_creator': is_creator,
                'is_admin': is_admin
            }), 403
        
        if request.method == 'GET':
            logger.info(f"User {user.email} accessing incident {incident_id}")
            
            incident_data = {
                'id': incident.id,
                'title': incident.title,
                'type': incident.type,
                'severity': incident.severity,
                'status': incident.status,
                'location': incident.location,
                'description': incident.description,
                'impact': incident.impact,
                'action_required': incident.action_required,
                'reported_by': incident.reported_by,
                'reported_name': incident.reported_name,
                'reported_date': incident.reported_date.isoformat() if incident.reported_date else None,
                'estimated_completion': incident.estimated_completion.isoformat() if incident.estimated_completion else None,
                'actual_completion': incident.actual_completion.isoformat() if incident.actual_completion else None,
                'department': incident.department,
                'cost_estimate': incident.cost_estimate,
                'created_at': incident.created_at.isoformat() if incident.created_at else None,
                'updated_at': incident.updated_at.isoformat() if incident.updated_at else None,
                'company_id': incident.company_id
            }
            
            return jsonify({
                'success': True,
                'incident': incident_data,
                'user': {
                    'id': user.id,
                    'email': user.email,
                    'can_modify': is_creator or is_admin
                },
                'permissions': {
                    'can_update': is_creator or is_admin,
                    'can_delete': is_creator or is_admin,
                    'is_creator': is_creator,
                    'is_admin': is_admin
                }
            }), 200
            
        elif request.method == 'PUT':
            data = request.get_json()
            logger.info(f"User {user.email} updating incident {incident_id}")
            
            if not data:
                return jsonify({
                    'success': False,
                    'error': 'No JSON data provided',
                    'code': 'NO_DATA'
                }), 400
            
            # ==================== VALIDATE UPDATES ====================
            changes = []
            
            # 1. Title validation
            if 'title' in data:
                new_title = data['title'].strip()
                if len(new_title) < 3:
                    return jsonify({
                        'success': False,
                        'error': 'Title must be at least 3 characters',
                        'code': 'TITLE_TOO_SHORT'
                    }), 400
                if len(new_title) > 200:
                    return jsonify({
                        'success': False,
                        'error': 'Title must be less than 200 characters',
                        'code': 'TITLE_TOO_LONG'
                    }), 400
                changes.append('title')
                incident.title = new_title
            
            # 2. Type validation
            if 'type' in data:
                allowed_types = ['spill', 'emission', 'waste', 'water', 'air', 'soil', 
                                'chemical', 'radiation', 'noise', 'other', 'fire', 'explosion']
                new_type = data['type'].lower()
                if new_type not in allowed_types:
                    return jsonify({
                        'success': False,
                        'error': f'Invalid type. Allowed: {", ".join(allowed_types)}',
                        'code': 'INVALID_TYPE'
                    }), 400
                changes.append(f'type: {incident.type} -> {new_type}')
                incident.type = new_type
            
            # 3. Severity validation
            if 'severity' in data:
                allowed_severities = ['low', 'medium', 'high', 'critical', 'minor', 'major', 'severe']
                new_severity = data['severity'].lower()
                if new_severity not in allowed_severities:
                    return jsonify({
                        'success': False,
                        'error': f'Invalid severity. Allowed: {", ".join(allowed_severities)}',
                        'code': 'INVALID_SEVERITY'
                    }), 400
                changes.append(f'severity: {incident.severity} -> {new_severity}')
                incident.severity = new_severity
            
            # 4. Status validation
            if 'status' in data:
                allowed_statuses = ['reported', 'investigating', 'resolved', 'closed', 'pending']
                new_status = data['status'].lower()
                if new_status not in allowed_statuses:
                    return jsonify({
                        'success': False,
                        'error': f'Invalid status. Allowed: {", ".join(allowed_statuses)}',
                        'code': 'INVALID_STATUS'
                    }), 400
                
                # If status is resolved, set actual_completion
                if new_status == 'resolved' and incident.status != 'resolved':
                    incident.actual_completion = datetime.utcnow()
                    changes.append(f'status: {incident.status} -> {new_status} (resolved)')
                else:
                    changes.append(f'status: {incident.status} -> {new_status}')
                incident.status = new_status
            
            # 5. Location validation
            if 'location' in data:
                new_location = data['location'].strip()
                if len(new_location) < 2:
                    return jsonify({
                        'success': False,
                        'error': 'Location must be at least 2 characters',
                        'code': 'LOCATION_TOO_SHORT'
                    }), 400
                if len(new_location) > 500:
                    return jsonify({
                        'success': False,
                        'error': 'Location must be less than 500 characters',
                        'code': 'LOCATION_TOO_LONG'
                    }), 400
                changes.append('location')
                incident.location = new_location
            
            # 6. Description validation
            if 'description' in data:
                new_description = data['description'].strip()
                if len(new_description) < 10:
                    return jsonify({
                        'success': False,
                        'error': 'Description must be at least 10 characters',
                        'code': 'DESCRIPTION_TOO_SHORT'
                    }), 400
                if len(new_description) > 5000:
                    return jsonify({
                        'success': False,
                        'error': 'Description must be less than 5000 characters',
                        'code': 'DESCRIPTION_TOO_LONG'
                    }), 400
                changes.append('description')
                incident.description = new_description
            
            # 7. Impact validation
            if 'impact' in data:
                new_impact = data['impact'].strip() if data['impact'] else ''
                if len(new_impact) > 2000:
                    return jsonify({
                        'success': False,
                        'error': 'Impact assessment must be less than 2000 characters',
                        'code': 'IMPACT_TOO_LONG'
                    }), 400
                changes.append('impact')
                incident.impact = new_impact
            
            # 8. Action required validation
            if 'action_required' in data:
                new_action = data['action_required'].strip() if data['action_required'] else ''
                if len(new_action) > 2000:
                    return jsonify({
                        'success': False,
                        'error': 'Action required must be less than 2000 characters',
                        'code': 'ACTION_TOO_LONG'
                    }), 400
                changes.append('action_required')
                incident.action_required = new_action
            
            # 9. Department validation
            if 'department' in data:
                new_department = data['department'].strip() if data['department'] else ''
                if len(new_department) > 200:
                    return jsonify({
                        'success': False,
                        'error': 'Department must be less than 200 characters',
                        'code': 'DEPARTMENT_TOO_LONG'
                    }), 400
                changes.append('department')
                incident.department = new_department
            
            # 10. Cost estimate validation
            if 'cost_estimate' in data:
                if data['cost_estimate'] is None:
                    incident.cost_estimate = None
                    changes.append('cost_estimate: cleared')
                else:
                    try:
                        new_cost = float(data['cost_estimate'])
                        if new_cost < 0:
                            return jsonify({
                                'success': False,
                                'error': 'Cost estimate cannot be negative',
                                'code': 'COST_NEGATIVE'
                            }), 400
                        if new_cost > 999999999:
                            return jsonify({
                                'success': False,
                                'error': 'Cost estimate is too large',
                                'code': 'COST_TOO_LARGE'
                            }), 400
                        changes.append(f'cost_estimate: {incident.cost_estimate} -> {new_cost}')
                        incident.cost_estimate = new_cost
                    except (ValueError, TypeError):
                        return jsonify({
                            'success': False,
                            'error': 'Cost estimate must be a valid number',
                            'code': 'INVALID_COST'
                        }), 400
            
            # 11. Estimated completion validation
            if 'estimated_completion' in data:
                if data['estimated_completion'] is None:
                    incident.estimated_completion = None
                    changes.append('estimated_completion: cleared')
                else:
                    try:
                        new_estimated = datetime.fromisoformat(data['estimated_completion'].replace('Z', '+00:00'))
                        new_estimated = new_estimated.replace(tzinfo=None)
                        if new_estimated < datetime.utcnow():
                            return jsonify({
                                'success': False,
                                'error': 'Estimated completion cannot be in the past',
                                'code': 'ESTIMATED_COMPLETION_PAST'
                            }), 400
                        changes.append(f'estimated_completion: {incident.estimated_completion} -> {new_estimated}')
                        incident.estimated_completion = new_estimated
                    except ValueError:
                        return jsonify({
                            'success': False,
                            'error': 'Invalid estimated_completion format. Use ISO format (YYYY-MM-DDTHH:MM:SS)',
                            'code': 'INVALID_ESTIMATED_COMPLETION'
                        }), 400
            
            # 11. Actual completion validation (can only be set by admins)
            if 'actual_completion' in data and is_admin:
                if data['actual_completion'] is None:
                    incident.actual_completion = None
                    changes.append('actual_completion: cleared')
                else:
                    try:
                        new_actual = datetime.fromisoformat(data['actual_completion'].replace('Z', '+00:00'))
                        new_actual = new_actual.replace(tzinfo=None)
                        if new_actual > datetime.utcnow():
                            return jsonify({
                                'success': False,
                                'error': 'Actual completion cannot be in the future',
                                'code': 'ACTUAL_COMPLETION_FUTURE'
                            }), 400
                        changes.append(f'actual_completion: {incident.actual_completion} -> {new_actual}')
                        incident.actual_completion = new_actual
                    except ValueError:
                        return jsonify({
                            'success': False,
                            'error': 'Invalid actual_completion format. Use ISO format (YYYY-MM-DDTHH:MM:SS)',
                            'code': 'INVALID_ACTUAL_COMPLETION'
                        }), 400
            
            if not changes:
                return jsonify({
                    'success': False,
                    'error': 'No valid fields to update',
                    'code': 'NO_VALID_FIELDS'
                }), 400
            
            incident.updated_at = datetime.utcnow()
            
            # Log update
            activity_log = ActivityLog(
                user_id=user.id,
                activity_type='incident_updated',
                description=f'Updated incident: {incident.title}',
                ip_address=request.remote_addr,
                activity_data={
                    'incident_id': incident_id,
                    'changes': changes,
                    'updated_by': user.email
                }
            )
            db.session.add(activity_log)
            db.session.commit()
            
            logger.info(f"✅ Incident {incident_id} updated. Changes: {', '.join(changes)}")
            
            # Create notification for status change
            if 'status' in data and changes:
                try:
                    if 'create_notification' in globals():
                        create_notification(
                            incident.reported_by,
                            f"Incident Status Updated",
                            f"Your incident '{incident.title}' status has been updated to {incident.status}",
                            "info",
                            "medium",
                            f"/environmental/incidents/{incident.id}"
                        )
                except Exception as notify_error:
                    logger.warning(f"Failed to create notification: {notify_error}")
            
            return jsonify({
                'success': True,
                'message': 'Incident updated successfully',
                'changes': changes,
                'updated_by': user.email,
                'incident': {
                    'id': incident.id,
                    'title': incident.title,
                    'status': incident.status,
                    'severity': incident.severity,
                    'updated_at': incident.updated_at.isoformat() if incident.updated_at else None
                }
            }), 200
            
        elif request.method == 'DELETE':
            logger.info(f"User {user.email} deleting incident {incident_id}")
            
            # Prevent deleting resolved incidents
            if incident.status == 'resolved':
                return jsonify({
                    'success': False,
                    'error': 'Cannot delete a resolved incident. Mark it as closed first.',
                    'code': 'RESOLVED_INCIDENT_DELETE'
                }), 400
            
            # Store incident info for response
            incident_info = {
                'id': incident.id,
                'title': incident.title,
                'type': incident.type,
                'severity': incident.severity,
                'status': incident.status
            }
            
            # Log deletion
            activity_log = ActivityLog(
                user_id=user.id,
                activity_type='incident_deleted',
                description=f'Deleted incident: {incident.title}',
                ip_address=request.remote_addr,
                activity_data={
                    'incident_id': incident_id,
                    'title': incident.title,
                    'severity': incident.severity,
                    'deleted_by': user.email
                }
            )
            db.session.add(activity_log)
            
            db.session.delete(incident)
            db.session.commit()
            
            logger.info(f"✅ Incident {incident_id} deleted by {user.email}")
            
            # Create notification
            try:
                if 'create_notification' in globals():
                    create_notification(
                        incident_info['reported_by'] if hasattr(incident_info, 'reported_by') else user.id,
                        "Incident Deleted",
                        f"Incident '{incident_info['title']}' has been deleted",
                        "warning",
                        "medium",
                        "/environmental/incidents"
                    )
            except Exception as notify_error:
                logger.warning(f"Failed to create notification: {notify_error}")
            
            return jsonify({
                'success': True,
                'message': f'Incident "{incident_info["title"]}" deleted successfully',
                'deleted_incident': incident_info,
                'deleted_by': user.email
            }), 200
            
    except Exception as e:
        db.session.rollback()
        logger.error(f"Manage incident error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': f'Failed to {"get" if request.method == "GET" else "update" if request.method == "PUT" else "delete"} incident',
            'details': str(e) if app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500

# =============================================
# SENSOR MANAGEMENT ENDPOINTS
# =============================================

@app.route('/api/environmental/sensors/register', methods=['POST'])
@jwt_required
def register_sensor():
    """Register a new environmental sensor - WITH JWT"""
    try:
        user = request.user
        data = request.get_json()
        logger.info(f"User {user.email} registering sensor")
        
        # Only admins and safetypro can register sensors
        if user.user_type not in ['admin', 'safetypro', 'system', 'platform_owner']:
            return jsonify({
                'success': False,
                'error': 'Permission denied: Only administrators can register sensors'
            }), 403
        
        # Validate required fields
        required_fields = ['device_id', 'name', 'location', 'type']
        for field in required_fields:
            if field not in data or not data[field]:
                return jsonify({
                    'success': False,
                    'error': f'Missing required field: {field}'
                }), 400
        
        # Check if device_id already exists
        existing_sensor = AirQualitySensor.query.filter_by(device_id=data['device_id']).first()
        if existing_sensor:
            return jsonify({
                'success': False,
                'error': 'Sensor with this device ID already exists'
            }), 409
        
        # Create new sensor
        sensor = AirQualitySensor(
            device_id=data['device_id'],
            name=data['name'],
            location=data['location'],
            type=data['type'],
            status=data.get('status', 'active'),
            latitude=data.get('latitude'),
            longitude=data.get('longitude'),
            department=data.get('department'),
            installation_date=datetime.utcnow(),
            registered_by=user.id
        )
        
        db.session.add(sensor)
        
        # Log registration
        activity_log = ActivityLog(
            user_id=user.id,
            activity_type='sensor_registered',
            description=f'Registered sensor: {data["name"]} ({data["device_id"]})',
            ip_address=request.remote_addr,
            activity_data={
                'sensor_id': sensor.id,
                'device_id': data['device_id'],
                'location': data['location']
            }
        )
        db.session.add(activity_log)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Sensor registered successfully',
            'sensor_id': sensor.id,
            'registered_by': user.email
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Register sensor error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to register sensor'
        }), 500

@app.route('/api/environmental/sensors/<int:sensor_id>', methods=['PUT'])
@jwt_required
def update_sensor(sensor_id):
    """Update sensor information - WITH JWT"""
    try:
        user = request.user
        sensor = AirQualitySensor.query.get_or_404(sensor_id)
        data = request.get_json()
        
        # Check permission
        if user.user_type not in ['admin', 'safetypro', 'system', 'platform_owner']:
            return jsonify({
                'success': False,
                'error': 'Permission denied: Only administrators can update sensors'
            }), 403
        
        logger.info(f"User {user.email} updating sensor {sensor_id}")
        
        # Update allowed fields
        updatable_fields = ['name', 'location', 'status', 'latitude', 'longitude', 'department']
        
        for field in updatable_fields:
            if field in data:
                setattr(sensor, field, data[field])
        
        sensor.updated_at = datetime.utcnow()
        sensor.updated_by = user.id
        
        # Log update
        activity_log = ActivityLog(
            user_id=user.id,
            activity_type='sensor_updated',
            description=f'Updated sensor: {sensor.name}',
            ip_address=request.remote_addr,
            activity_data={
                'sensor_id': sensor_id,
                'updates': data
            }
        )
        db.session.add(activity_log)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Sensor updated successfully',
            'updated_by': user.email
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Update sensor error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to update sensor'
        }), 500

@app.route('/api/environmental/sensors/<int:sensor_id>/deactivate', methods=['POST'])
@jwt_required
def deactivate_sensor(sensor_id):
    """Deactivate a sensor - WITH JWT"""
    try:
        user = request.user
        sensor = AirQualitySensor.query.get_or_404(sensor_id)
        
        # Check permission
        if user.user_type not in ['admin', 'safetypro', 'system', 'platform_owner']:
            return jsonify({
                'success': False,
                'error': 'Permission denied: Only administrators can deactivate sensors'
            }), 403
        
        logger.info(f"User {user.email} deactivating sensor {sensor_id}")
        
        sensor.status = 'inactive'
        sensor.updated_at = datetime.utcnow()
        sensor.deactivated_by = user.id
        sensor.deactivated_at = datetime.utcnow()
        
        # Log deactivation
        activity_log = ActivityLog(
            user_id=user.id,
            activity_type='sensor_deactivated',
            description=f'Deactivated sensor: {sensor.name}',
            ip_address=request.remote_addr,
            activity_data={
                'sensor_id': sensor_id,
                'device_id': sensor.device_id,
                'reason': request.get_json().get('reason', 'No reason provided') if request.is_json else 'No reason provided'
            }
        )
        db.session.add(activity_log)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Sensor deactivated successfully',
            'deactivated_by': user.email
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Deactivate sensor error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to deactivate sensor'
        }), 500

