@app.route('/api/environmental/sustainability-goals', methods=['GET', 'POST'])
@jwt_required
def manage_sustainability_goals():
    """Get all sustainability goals or create a new goal - WITH JWT"""
    user = request.user
    
    if request.method == 'GET':
        try:
            logger.info(f"User {user.email} accessing sustainability goals")
            
            goals = SustainabilityGoal.query.order_by(SustainabilityGoal.deadline.asc()).all()
            
            goals_data = []
            for goal in goals:
                goals_data.append({
                    'id': goal.id,
                    'goal': goal.goal,
                    'target': goal.target,
                    'current_value': goal.current_value,
                    'target_value': goal.target_value,
                    'unit': goal.unit,
                    'progress': goal.progress,
                    'deadline': goal.deadline.isoformat(),
                    'category': goal.category,
                    'status': goal.status,
                    'created_at': goal.created_at.isoformat()
                })
            
            return jsonify({
                'success': True,
                'goals': goals_data,
                'user': {
                    'id': user.id,
                    'email': user.email
                }
            }), 200
            
        except Exception as e:
            logger.error(f"Get sustainability goals error: {str(e)}", exc_info=True)
            return jsonify({
                'success': False,
                'error': 'Failed to fetch sustainability goals'
            }), 500
    
    elif request.method == 'POST':
        try:
            data = request.get_json()
            
            # Only admins can create goals
            if user.user_type not in ['admin', 'safetypro', 'system', 'platform_owner']:
                return jsonify({
                    'success': False,
                    'error': 'Permission denied: Only administrators can create sustainability goals'
                }), 403
            
            logger.info(f"User {user.email} creating sustainability goal")
            
            # Validate required fields
            required_fields = ['goal', 'target', 'current_value', 'target_value', 'unit', 'deadline', 'category']
            for field in required_fields:
                if field not in data or not data[field]:
                    return jsonify({
                        'success': False,
                        'error': f'Missing required field: {field}'
                    }), 400
            
            # Calculate initial progress
            progress = (data['current_value'] / data['target_value']) * 100 if data['target_value'] > 0 else 0
            
            # Create new goal
            goal = SustainabilityGoal(
                goal=data['goal'],
                target=data['target'],
                current_value=data['current_value'],
                target_value=data['target_value'],
                unit=data['unit'],
                progress=min(progress, 100),
                deadline=datetime.fromisoformat(data['deadline'].replace('Z', '+00:00')),
                category=data['category'],
                status=data.get('status', 'active'),
                created_by=user.id
            )
            
            db.session.add(goal)
            
            # Log creation
            activity_log = ActivityLog(
                user_id=user.id,
                activity_type='sustainability_goal_created',
                description=f'Created sustainability goal: {data["goal"]}',
                ip_address=request.remote_addr,
                activity_data={
                    'goal_id': goal.id,
                    'goal': data['goal'],
                    'target': data['target']
                }
            )
            db.session.add(activity_log)
            db.session.commit()
            
            return jsonify({
                'success': True,
                'message': 'Sustainability goal created successfully',
                'goal_id': goal.id,
                'created_by': user.email
            }), 201
            
        except Exception as e:
            db.session.rollback()
            logger.error(f"Create sustainability goal error: {str(e)}", exc_info=True)
            return jsonify({
                'success': False,
                'error': 'Failed to create sustainability goal'
            }), 500

