@app.route('/api/environmental/water-quality/alerts', methods=['GET'])
@jwt_required
def get_water_quality_alerts():
    """Get water quality alerts - WITH JWT"""
    try:
        user = request.user
        logger.info(f"User {user.email} accessing water quality alerts")
        
        # Get water quality alerts from monitoring alerts
        water_alerts = MonitoringAlert.query.filter(
            MonitoringAlert.parameter.in_(['ph', 'turbidity', 'dissolved_oxygen', 'conductivity', 'e_coli'])
        ).filter_by(status='Active').order_by(MonitoringAlert.created_at.desc()).all()
        
        alerts_data = []
        for alert in water_alerts:
            # Get related water sample if available
            water_sample = WaterSample.query.filter_by(id=alert.station_id).first() if alert.station_id else None
            
            alert_data = {
                'id': alert.id,
                'sample_id': alert.station_id,
                'parameter': alert.parameter,
                'value': alert.value,
                'threshold': alert.threshold,
                'severity': alert.severity.lower(),
                'message': alert.message,
                'timestamp': alert.created_at.isoformat(),
                'location': water_sample.site.location if water_sample and water_sample.site else 'Unknown Location'
            }
            alerts_data.append(alert_data)
        
        return jsonify({
            'success': True,
            'alerts': alerts_data,
            'count': len(alerts_data),
            'user': {
                'id': user.id,
                'email': user.email
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Water quality alerts error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to fetch water quality alerts',
            'alerts': []
        }), 500
# =============================================
# HELPER FUNCTIONS FOR ANALYTICS
# =============================================

def calculate_air_quality_trend(readings):
    """Calculate air quality trend from readings"""
    if not readings:
        return {'trend': 'stable', 'change_percentage': 0}
    
    # Group by day and calculate average AQI
    daily_averages = {}
    for reading in readings:
        date = reading.timestamp.date()
        if date not in daily_averages:
            daily_averages[date] = []
        daily_averages[date].append(reading.aqi)
    
    # Calculate trend
    dates = sorted(daily_averages.keys())
    if len(dates) < 2:
        return {'trend': 'stable', 'change_percentage': 0}
    
    first_avg = sum(daily_averages[dates[0]]) / len(daily_averages[dates[0]])
    last_avg = sum(daily_averages[dates[-1]]) / len(daily_averages[dates[-1]])
    
    change_percentage = ((last_avg - first_avg) / first_avg) * 100 if first_avg > 0 else 0
    
    if change_percentage > 5:
        trend = 'improving'
    elif change_percentage < -5:
        trend = 'deteriorating'
    else:
        trend = 'stable'
    
    return {
        'trend': trend,
        'change_percentage': round(change_percentage, 1),
        'current_aqi': round(last_avg, 1),
        'data_points': len(readings)
    }

def calculate_water_quality_trend(samples):
    """Calculate water quality trend from samples"""
    if not samples:
        return {'trend': 'stable', 'change_percentage': 0}
    
    compliant_samples = sum(1 for sample in samples if sample.compliant)
    compliance_rate = (compliant_samples / len(samples)) * 100
    
    # Simple trend calculation based on time
    early_samples = samples[:len(samples)//2]
    late_samples = samples[len(samples)//2:]
    
    early_compliance = sum(1 for sample in early_samples if sample.compliant) / len(early_samples) * 100 if early_samples else 0
    late_compliance = sum(1 for sample in late_samples if sample.compliant) / len(late_samples) * 100 if late_samples else 0
    
    change_percentage = late_compliance - early_compliance
    
    if change_percentage > 5:
        trend = 'improving'
    elif change_percentage < -5:
        trend = 'deteriorating'
    else:
        trend = 'stable'
    
    return {
        'trend': trend,
        'change_percentage': round(change_percentage, 1),
        'current_compliance': round(compliance_rate, 1),
        'data_points': len(samples)
    }

def calculate_compliance_trend(air_readings, water_samples):
    """Calculate overall compliance trend"""
    air_compliant = sum(1 for reading in air_readings if reading.aqi <= 100) / len(air_readings) * 100 if air_readings else 0
    water_compliant = sum(1 for sample in water_samples if sample.compliant) / len(water_samples) * 100 if water_samples else 0
    
    overall_compliance = (air_compliant + water_compliant) / 2
    
    return {
        'overall_compliance': round(overall_compliance, 1),
        'air_quality_compliance': round(air_compliant, 1),
        'water_quality_compliance': round(water_compliant, 1)
    }

def calculate_alert_statistics(start_date, end_date):
    """Calculate alert statistics for the period"""
    alerts = MonitoringAlert.query.filter(
        MonitoringAlert.created_at >= start_date,
        MonitoringAlert.created_at <= end_date
    ).all()
    
    total_alerts = len(alerts)
    active_alerts = sum(1 for alert in alerts if alert.status == 'Active')
    resolved_alerts = total_alerts - active_alerts
    
    # Group by severity
    severity_counts = {}
    for alert in alerts:
        severity = alert.severity.lower()
        severity_counts[severity] = severity_counts.get(severity, 0) + 1
    
    return {
        'total_alerts': total_alerts,
        'active_alerts': active_alerts,
        'resolved_alerts': resolved_alerts,
        'severity_breakdown': severity_counts
    }

def calculate_incident_statistics(start_date, end_date):
    """Calculate incident statistics for the period"""
    incidents = EnvironmentalIncident.query.filter(
        EnvironmentalIncident.reported_date >= start_date,
        EnvironmentalIncident.reported_date <= end_date
    ).all()
    
    total_incidents = len(incidents)
    resolved_incidents = sum(1 for incident in incidents if incident.status == 'resolved')
    active_incidents = total_incidents - resolved_incidents
    
    # Group by type and severity
    type_counts = {}
    severity_counts = {}
    
    for incident in incidents:
        # Type counts
        incident_type = incident.type
        type_counts[incident_type] = type_counts.get(incident_type, 0) + 1
        
        # Severity counts
        severity = incident.severity
        severity_counts[severity] = severity_counts.get(severity, 0) + 1
    
    return {
        'total_incidents': total_incidents,
        'resolved_incidents': resolved_incidents,
        'active_incidents': active_incidents,
        'type_breakdown': type_counts,
        'severity_breakdown': severity_counts
    }

def calculate_sensor_performance():
    """Calculate sensor performance metrics"""
    total_sensors = AirQualitySensor.query.count()
    active_sensors = AirQualitySensor.query.filter_by(status='active').count()
    inactive_sensors = total_sensors - active_sensors
    
    # Calculate uptime (simplified)
    recent_readings = AirQualityReading.query.join(AirQualitySensor).filter(
        AirQualityReading.timestamp >= datetime.utcnow() - timedelta(days=1)
    ).group_by(AirQualityReading.sensor_id).count()
    
    uptime_percentage = (recent_readings / total_sensors) * 100 if total_sensors > 0 else 0
    
    return {
        'total_sensors': total_sensors,
        'active_sensors': active_sensors,
        'inactive_sensors': inactive_sensors,
        'uptime_percentage': round(uptime_percentage, 1),
        'performance_score': round(uptime_percentage * 0.8 + (active_sensors / total_sensors * 100 * 0.2), 1)
    }

def check_environmental_access(user, feature_type='basic'):
    """Check if user has access to environmental features based on subscription"""
    if not user:
        return False
    
    # Get user's effective plan from request context or user object
    effective_plan = getattr(request, 'effective_plan', user.subscription_plan)
    
    # Subscription feature mapping
    feature_access = {
        'air_quality_basic': ['free', 'basic', 'pro', 'professional', 'custom', 'custom_enterprise'],
        'air_quality_advanced': ['pro', 'professional', 'custom', 'custom_enterprise'],
        'predictive_analytics': ['professional', 'custom', 'custom_enterprise'],
        'real_time_monitoring': ['pro', 'professional', 'custom', 'custom_enterprise'],
        'water_quality': ['professional', 'custom', 'custom_enterprise'],
        'advanced_analytics': ['custom', 'custom_enterprise'],
        'ml_training': ['custom_enterprise']
    }
    
    # System users always have full access
    if user.user_type in ['safetypro', 'system', 'platform_owner']:
        return True
    
    # Check trial access
    trial_active = user.trial_ends_at and datetime.utcnow() < user.trial_ends_at
    if trial_active and user.trial_plan in ['pro', 'professional']:
        # During trial, users get elevated access
        effective_plan = user.trial_plan
    
    # Check access based on feature type
    allowed_plans = feature_access.get(feature_type, [])
    return effective_plan in allowed_plans

def require_subscription(feature_type='basic'):
    """Decorator to require specific subscription level"""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            try:
                current_user = request.user
                
                if not check_environmental_access(current_user, feature_type):
                    required_plan = {
                        'air_quality_basic': 'Free',
                        'air_quality_advanced': 'Pro',
                        'predictive_analytics': 'Professional',
                        'real_time_monitoring': 'Pro',
                        'water_quality': 'Professional',
                        'advanced_analytics': 'Custom',
                        'ml_training': 'Custom Enterprise'
                    }.get(feature_type, 'Unknown')
                    
                    # Check if user is on trial
                    trial_active = current_user.trial_ends_at and datetime.utcnow() < current_user.trial_ends_at
                    
                    return jsonify({
                        'success': False,
                        'error': 'Subscription required',
                        'code': 'SUBSCRIPTION_REQUIRED',
                        'message': f'This feature requires {required_plan} plan or higher',
                        'current_plan': current_user.subscription_plan,
                        'effective_plan': getattr(request, 'effective_plan', current_user.subscription_plan),
                        'trial_active': trial_active,
                        'trial_ends_at': current_user.trial_ends_at.isoformat() if trial_active else None,
                        'upgrade_url': '/subscription/upgrade',
                        'required_plan': required_plan
                    }), 402  # 402 Payment Required
                
                return f(*args, **kwargs)
            except Exception as e:
                logger.error(f"Subscription check error: {e}")
                return jsonify({
                    'success': False,
                    'error': 'Access verification failed'
                }), 500
        return decorated_function
    return decorator

