@app.route('/api/environmental/water-quality/samples', methods=['POST'])
@jwt_required
def create_water_sample():
    try:
        user = request.user
        is_super = check_super_admin()
        
        data = request.get_json()
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400
        
        # Validate required
        if not data.get('location') or data.get('ph_level') is None:
            return jsonify({'success': False, 'error': 'location and ph_level required'}), 400
        
        company_id = get_user_company_id(user)
        
        # ✅ Handle empty site_id - set to None if empty string
        site_id = data.get('site_id')
        if site_id == '' or site_id is None:
            site_id = None
        
        # Handle collection_time
        collection_time = datetime.utcnow()
        if data.get('collection_time'):
            try:
                collection_time = datetime.fromisoformat(data['collection_time'].replace('Z', '+00:00'))
            except ValueError:
                try:
                    collection_time = datetime.fromisoformat(data['collection_time'])
                except ValueError:
                    pass
        
        sample = WaterSample(
            site_id=site_id,  # ✅ Now None instead of empty string
            site_name=data.get('site_name'),
            location=data.get('location'),
            sample_type=data.get('sample_type', 'water'),
            collection_time=collection_time,
            temperature=data.get('temperature'),
            ph=data.get('ph_level'),
            turbidity=data.get('turbidity'),
            tds=data.get('tds'),
            dissolved_oxygen=data.get('dissolved_oxygen'),
            coliform_count=data.get('coliform_count'),
            compliant=data.get('compliant', True),
            violations=data.get('violations', ''),
            notes=data.get('notes', ''),
            user_id=user.id,
            company_id=company_id
        )
        
        db.session.add(sample)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Water sample created',
            'sample': sample.to_dict()
        }), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

