# ============================================================================
# HELPER FUNCTION: CHECK WATER COMPLIANCE
# ============================================================================

def check_water_compliance(data):
    """Check if water sample meets compliance standards"""
    try:
        # WHO/EPA water quality standards
        standards = {
            'ph': (6.5, 8.5),
            'temperature': (10, 30),
            'turbidity': (0, 5),
            'dissolved_oxygen': (6, 15),
            'conductivity': (0, 1000),
            'lead': (0, 0.015),
            'mercury': (0, 0.002),
            'arsenic': (0, 0.01),
            'e_coli': False,  # Should be absent
            'coliform_count': 0  # Should be 0
        }
        
        # Check each parameter against standards
        for param, standard in standards.items():
            if param in data and data[param] is not None:
                value = data[param]
                
                if isinstance(standard, tuple):
                    min_val, max_val = standard
                    if value < min_val or value > max_val:
                        current_app.logger.info(f"Compliance check failed for {param}: {value} (expected {min_val}-{max_val})")
                        return False
                elif isinstance(standard, bool):
                    if value != standard:
                        current_app.logger.info(f"Compliance check failed for {param}: {value} (expected {standard})")
                        return False
                elif isinstance(standard, (int, float)):
                    if value != standard:
                        current_app.logger.info(f"Compliance check failed for {param}: {value} (expected {standard})")
                        return False
        
        return True
        
    except Exception as e:
        current_app.logger.warning(f"Error checking compliance: {e}")
        return True  # Default to compliant if check fails
