@app.route('/api/environmental/air-quality/readings', methods=['POST'])
@jwt_required
def add_air_quality_reading():
    """Add new air quality reading"""
    try:
        user_id = request.user_id
        data = request.get_json()
        
        # Validate required fields
        required_fields = ['sensor_id', 'pm2_5', 'pm10']  # Note: pm2_5 not pm25
        for field in required_fields:
            if field not in data:
                return jsonify({
                    'success': False,
                    'error': f'Missing required field: {field}'
                }), 400
        
        # Verify sensor belongs to user
        sensor = AirQualitySensor.query.filter_by(
            id=data['sensor_id'],
            user_id=current_user
        ).first()
        
        if not sensor:
            return jsonify({
                'success': False,
                'error': 'Sensor not found or access denied'
            }), 404
        
        # Calculate AQI based on PM2.5
        pm25 = data['pm2_5']
        aqi = calculate_aqi_from_pm25(pm25)
        
        # Determine AQI category
        aqi_category = get_aqi_category(aqi)
        
        # Create reading - matching your model field names
        reading = AirQualityReading(
            sensor_id=data['sensor_id'],
            pm2_5=data['pm2_5'],  # Note: pm2_5 not pm25
            pm10=data['pm10'],
            co=data.get('co'),
            no2=data.get('no2'),
            o3=data.get('o3'),
            so2=data.get('so2'),
            temperature=data.get('temperature'),
            humidity=data.get('humidity'),
            pressure=data.get('air_pressure'),  # Note: pressure not air_pressure
            aqi=aqi,
            aqi_category=aqi_category
        )
        
        db.session.add(reading)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Reading added successfully',
            'reading_id': reading.id,
            'aqi': aqi,
            'aqi_category': aqi_category
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Add air quality reading error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to add reading'
        }), 500


# Helper functions
def calculate_aqi_from_pm25(pm25):
    """Calculate AQI from PM2.5 value"""
    if pm25 <= 12:
        return pm25 * (50 / 12)
    elif pm25 <= 35:
        return 50 + (pm25 - 12) * (50 / 23)
    elif pm25 <= 55:
        return 100 + (pm25 - 35) * (50 / 20)
    elif pm25 <= 150:
        return 150 + (pm25 - 55) * (100 / 95)
    elif pm25 <= 250:
        return 200 + (pm25 - 150) * (100 / 100)
    else:
        return 300 + (pm25 - 250) * (100 / 150)

def get_aqi_category(aqi):
    """Get AQI category from AQI value"""
    if aqi <= 50:
        return 'Good'
    elif aqi <= 100:
        return 'Moderate'
    elif aqi <= 150:
        return 'Unhealthy for Sensitive Groups'
    elif aqi <= 200:
        return 'Unhealthy'
    elif aqi <= 300:
        return 'Very Unhealthy'
    else:
        return 'Hazardous'

def check_water_compliance(sample_data):
    """Check if water sample is compliant with standards"""
    # Basic compliance checks
    if sample_data.get('ph') and (sample_data['ph'] < 6.5 or sample_data['ph'] > 8.5):
        return False
    if sample_data.get('turbidity') and sample_data['turbidity'] > 5:
        return False
    if sample_data.get('e_coli') and sample_data['e_coli']:
        return False
    return True

