def check_resource_permission(user, resource_type, resource_id, action):
    """Generic permission checker for any resource"""
    try:
        if not user or not user.is_active:
            return False
        
        # Super users always have permission
        if user.user_type in ['platform_owner', 'system', 'safetypro']:
            return True
        
        # Check resource-specific logic
        if resource_type == 'incident':
            incident = Incident.query.get(resource_id)
            if not incident:
                return False
            
            if action == 'view':
                return (incident.reported_by == user.id or 
                       incident.assigned_to == user.id or
                       user.user_type in ['admin'])
            
            elif action == 'edit':
                return (incident.reported_by == user.id or
                       incident.assigned_to == user.id)
            
            elif action == 'delete':
                return user.user_type in ['admin', 'platform_owner']
        
        elif resource_type == 'document':
            document = Document.query.get(resource_id)
            if not document:
                return False
            
            if action == 'view':
                return (document.user_id == user.id or
                       user.user_type in ['admin'])
            
            elif action == 'edit':
                return document.user_id == user.id
            
            elif action == 'delete':
                return (document.user_id == user.id or
                       user.user_type in ['admin'])
        
        return False
        
    except Exception as e:
        logger.error(f"Error checking permission: {e}")
        return False


def get_user_accessible_incidents(user, query=None):
    """Get incidents accessible to user with proper filtering"""
    try:
        if query is None:
            query = Incident.query
        
        # Super users see all
        if user.user_type in ['platform_owner', 'system', 'safetypro', 'admin']:
            return query
        
        # Regular users see only their incidents
        return query.filter(
            db.or_(
                Incident.reported_by == user.id,
                Incident.assigned_to == user.id
            )
        )
        
    except Exception as e:
        logger.error(f"Error filtering incidents: {e}")
        return query


def format_file_size(bytes_size):
    """Format file size in human-readable format"""
    try:
        if not bytes_size:
            return '0 B'
        
        for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
            if bytes_size < 1024.0:
                return f"{bytes_size:.1f} {unit}"
            bytes_size /= 1024.0
        return f"{bytes_size:.1f} PB"
    except:
        return 'Unknown'


def safe_getattr(obj, attr, default=None):
    """Safely get attribute with error handling"""
    try:
        return getattr(obj, attr, default)
    except:
        return default


def log_user_activity(user_id, activity_type, description, data=None):
    """Safely log user activity"""
    try:
        if 'ActivityLog' not in dir() and 'ActivityLog' not in globals():
            return False
        
        activity = ActivityLog(
            user_id=user_id,
            activity_type=activity_type,
            description=description,
            ip_address=request.remote_addr if request else None,
            activity_data=json.dumps(data) if data else None
        )
        db.session.add(activity)
        db.session.commit()
        return True
    except Exception as e:
        logger.warning(f"Failed to log activity: {e}")
        db.session.rollback()
        return False

@app.route('/api/analytics/export/files/<int:export_id>', methods=['GET'])
@jwt_required  # Added JWT authentication
def serve_export_file(export_id):
    """Serve the actual export file with security validation - SECURED WITH JWT"""
    try:
        # Get current user from JWT authentication
        current_user = request.user
        print(f"👤 User requesting export file: {current_user.email} (ID: {current_user.id}) for export {export_id}")
        
        # Get download token from query parameters
        download_token = request.args.get('token')
        if not download_token:
            print(f"❌ No download token provided for export {export_id}")
            return jsonify({
                'success': False,
                'error': 'Download token required',
                'code': 'TOKEN_REQUIRED'
            }), 401
        
        # Validate download token
        token_data = validate_download_token(download_token)
        if not token_data:
            print(f"❌ Invalid download token for export {export_id}")
            return jsonify({
                'success': False,
                'error': 'Invalid or expired download token',
                'code': 'INVALID_TOKEN'
            }), 401
        
        user_id = token_data.get('user_id')
        token_export_id = token_data.get('export_id')
        
        # Verify token matches requested export
        if token_export_id != export_id:
            print(f"❌ Token mismatch: token export {token_export_id} != requested {export_id}")
            return jsonify({
                'success': False,
                'error': 'Token mismatch',
                'code': 'TOKEN_MISMATCH'
            }), 403
        
        # Verify token user matches JWT user
        if user_id != current_user.id:
            print(f"❌ User mismatch: token user {user_id} != JWT user {current_user.id}")
            return jsonify({
                'success': False,
                'error': 'User authentication mismatch',
                'code': 'USER_MISMATCH'
            }), 403
        
        with db.session() as session:
            # Verify export exists and user has access
            export_job = session.query(ExportJob).filter_by(
                id=export_id,
                user_id=current_user.id,
                status='completed'
            ).first()
            
            if not export_job:
                print(f"❌ Export job not found: {export_id} for user {current_user.id}")
                return jsonify({
                    'success': False,
                    'error': 'Export job not found',
                    'code': 'EXPORT_NOT_FOUND'
                }), 404
            
            if not export_job.file_path:
                print(f"❌ Export file path missing for job {export_id}")
                return jsonify({
                    'success': False,
                    'error': 'Export file not found',
                    'code': 'FILE_NOT_FOUND'
                }), 404
            
            # Security check - validate file path
            if not is_safe_file_path(export_job.file_path):
                print(f"❌ Unsafe file path detected: {export_job.file_path}")
                return jsonify({
                    'success': False,
                    'error': 'File security violation',
                    'code': 'SECURITY_VIOLATION'
                }), 403
            
            if not os.path.exists(export_job.file_path):
                print(f"❌ File does not exist: {export_job.file_path}")
                return jsonify({
                    'success': False,
                    'error': 'Export file not found on server',
                    'code': 'FILE_MISSING'
                }), 404
            
            # Generate appropriate filename for download
            download_filename = generate_download_filename(export_job)
            
            # Log file access
            file_access_log = FileAccessLog(
                export_id=export_id,
                user_id=current_user.id,
                accessed_at=datetime.utcnow(),
                ip_address=request.remote_addr,
                user_agent=request.headers.get('User-Agent', ''),
                download_successful=True
            )
            session.add(file_access_log)
            
            # Update export job access count
            export_job.access_count = (export_job.access_count or 0) + 1
            export_job.last_accessed_at = datetime.utcnow()
            
            session.commit()
            
            print(f"✅ Serving export file {export_job.file_path} to user {current_user.email}")
            
            # Serve file with appropriate headers
            return send_file(
                export_job.file_path,
                as_attachment=True,
                download_name=download_filename,
                mimetype=get_file_mime_type(export_job.file_path),
                last_modified=export_job.completed_at,
                etag=False,  # Let Flask handle ETag generation
                max_age=0  # No caching for security
            )
            
    except Exception as e:
        logger.error(f"❌ File serving error for export {export_id}: {str(e)}")
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")
        
        # Log failed access attempt
        if 'current_user' in locals() and 'export_id' in locals():
            try:
                failed_log = FileAccessLog(
                    export_id=export_id,
                    user_id=current_user.id,
                    accessed_at=datetime.utcnow(),
                    ip_address=request.remote_addr,
                    user_agent=request.headers.get('User-Agent', ''),
                    download_successful=False,
                    error_message=str(e)[:500]
                )
                db.session.add(failed_log)
                db.session.commit()
            except:
                db.session.rollback()
        
        return jsonify({
            'success': False,
            'error': 'Failed to serve file',
            'code': 'FILE_SERVING_ERROR',
            'message': 'An error occurred while serving the file. Please try again or contact support.'
        }), 500
# Security and Utility Functions

def generate_download_token(export_id, user_id):
    """Generate a secure download token"""
    payload = {
        'export_id': export_id,
        'user_id': user_id,
        'exp': datetime.utcnow() + timedelta(hours=24),
        'iat': datetime.utcnow(),
        'type': 'export_download'
    }
    
    token = jwt.encode(payload, app.config['JWT_SECRET_KEY'], algorithm='HS256')
    return token

def validate_download_token(token):
    """Validate download token and return payload"""
    try:
        payload = jwt.decode(token, app.config['JWT_SECRET_KEY'], algorithms=['HS256'])
        
        # Check token type and expiration
        if payload.get('type') != 'export_download':
            return None
        
        if datetime.utcnow() > datetime.fromtimestamp(payload['exp']):
            return None
        
        return payload
        
    except jwt.ExpiredSignatureError:
        logger.warning("Expired download token attempted")
        return None
    except jwt.InvalidTokenError:
        logger.warning("Invalid download token attempted")
        return None

def is_safe_file_path(file_path):
    """Validate that file path is safe and within allowed directories"""
    try:
        # Resolve absolute path
        absolute_path = os.path.abspath(file_path)
        
        # Define allowed directories
        allowed_dirs = [
            os.path.abspath('/exports'),
            os.path.abspath('./exports'),
            os.path.abspath('./storage/exports')
        ]
        
        # Check if path is within allowed directories
        for allowed_dir in allowed_dirs:
            if absolute_path.startswith(allowed_dir):
                return True
        
        return False
        
    except Exception:
        return False

def generate_download_filename(export_job):
    """Generate user-friendly download filename"""
    timestamp = export_job.created_at.strftime('%Y%m%d_%H%M%S')
    safe_name = "".join(c for c in export_job.name if c.isalnum() or c in (' ', '-', '_')).rstrip()
    file_extension = get_file_extension(export_job.file_path)
    
    return f"{safe_name}_{timestamp}.{file_extension}"

def get_file_extension(file_path):
    """Get file extension from path"""
    return file_path.split('.')[-1].lower() if '.' in file_path else 'pdf'

def get_file_mime_type(file_path):
    """Get MIME type based on file extension"""
    extension = get_file_extension(file_path)
    mime_types = {
        'pdf': 'application/pdf',
        'csv': 'text/csv',
        'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'json': 'application/json',
        'txt': 'text/plain'
    }
    return mime_types.get(extension, 'application/octet-stream')

def calculate_file_checksum(file_path):
    """Calculate file checksum for integrity verification"""
    try:
        import hashlib
        hash_sha256 = hashlib.sha256()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_sha256.update(chunk)
        return hash_sha256.hexdigest()
    except Exception:
        return None

def get_estimated_completion(export_job):
    """Get estimated completion time for in-progress exports"""
    if export_job.status == 'processing':
        started_time = export_job.created_at
        elapsed = datetime.utcnow() - started_time
        estimated_total = timedelta(minutes=5)  # Default 5 minutes estimate
        remaining = estimated_total - elapsed
        
        if remaining.total_seconds() > 0:
            return f"Approximately {int(remaining.total_seconds() / 60)} minutes"
        else:
            return "Almost complete"
    
    return None

@app.route('/api/analytics/export/<int:export_id>/progress', methods=['GET'])
@jwt_required
def get_export_progress(export_id):
    """Get current progress for an export"""
    try:
        user_id = request.user_id
        
        with db.session() as session:
            # Verify user access
            export_job = session.query(ExportJob).filter_by(
                id=export_id,
                user_id=user_id
            ).first()
            
            if not export_job:
                return jsonify({
                    'success': False,
                    'error': 'Export not found'
                }), 404
            
            # Get progress information
            progress = session.query(ExportProgress).filter_by(
                export_job_id=export_id
            ).first()
            
            if not progress:
                return jsonify({
                    'success': True,
                    'progress': {
                        'status': export_job.status,
                        'progress_percentage': 0,
                        'current_step': 'Not started',
                        'status_message': 'Progress tracking not initialized'
                    }
                }), 200
            
            # Get recent events
            recent_events = session.query(ProgressEvent).filter_by(
                progress_id=progress.id
            ).order_by(ProgressEvent.created_at.desc()).limit(10).all()
            
            events_data = []
            for event in recent_events:
                events_data.append({
                    'type': event.event_type,
                    'message': event.message,
                    'data': event.data,
                    'timestamp': event.created_at.isoformat()
                })
            
            # Calculate time estimates
            time_estimates = calculate_time_estimates(progress, export_job)
            
            response_data = {
                'success': True,
                'progress': {
                    'export_id': export_id,
                    'status': export_job.status,
                    'progress_percentage': round(progress.progress_percentage, 1),
                    'current_step': progress.current_step,
                    'current_step_number': progress.current_step_number,
                    'total_steps': progress.total_steps,
                    'status_message': progress.status_message,
                    'data_processed': progress.data_processed,
                    'total_data': progress.total_data,
                    'started_at': progress.started_at.isoformat(),
                    'updated_at': progress.updated_at.isoformat(),
                    'time_estimates': time_estimates
                },
                'recent_events': events_data,
                'websocket_channel': export_job.progress_channel
            }
            
            return jsonify(response_data), 200
            
    except Exception as e:
        logger.error(f"Progress fetch error for export {export_id}: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch progress'
        }), 500

