def get_safety_metrics(user_id):
    """Get comprehensive safety performance metrics with real data"""
    try:
        # Get user and their organization context
        user = User.query.get(user_id)
        if not user:
            return {}
        
        # Time periods for analysis
        now = datetime.utcnow()
        today = now.date()
        week_ago = now - timedelta(days=7)
        month_ago = now - timedelta(days=30)
        three_months_ago = now - timedelta(days=90)
        year_ago = now - timedelta(days=365)
        
        # 1. INCIDENT METRICS
        incident_metrics = get_incident_metrics(user_id, now, month_ago, year_ago)
        
        # 2. VIOLATION METRICS
        violation_metrics = get_violation_metrics(user_id, now, week_ago, month_ago)
        
        # 3. PREVENTION METRICS
        prevention_metrics = get_prevention_metrics(user_id, now, month_ago, three_months_ago)
        
        # 4. COMPLIANCE METRICS
        compliance_metrics = get_compliance_metrics(user_id, now, month_ago)
        
        # 5. TREND ANALYSIS
        trend_analysis = get_safety_trends(user_id, now, three_months_ago)
        
        # 6. RISK ASSESSMENT
        risk_assessment = get_risk_assessment_metrics(user_id, now, month_ago)
        
        return {
            'incident_metrics': incident_metrics,
            'violation_metrics': violation_metrics,
            'prevention_metrics': prevention_metrics,
            'compliance_metrics': compliance_metrics,
            'trend_analysis': trend_analysis,
            'risk_assessment': risk_assessment,
            'overall_safety_score': calculate_overall_safety_score(
                incident_metrics, violation_metrics, prevention_metrics, compliance_metrics
            ),
            'last_updated': now.isoformat(),
            'period_covered': {
                'current_month': now.strftime('%Y-%m'),
                'last_30_days': True,
                'comparison_period': 'previous_month'
            }
        }
        
    except Exception as e:
        logger.error(f"Get safety metrics error for user {user_id}: {e}")
        return get_fallback_safety_metrics()

def get_incident_metrics(user_id, now, month_ago, year_ago):
    """Get comprehensive incident metrics"""
    try:
        # Total incidents
        total_incidents = Incident.query.filter_by(reported_by=user_id).count()
        
        # Current period incidents
        monthly_incidents = Incident.query.filter(
            Incident.reported_by == user_id,
            Incident.date_reported >= month_ago
        ).count()
        
        # Previous period for comparison
        previous_month_start = month_ago - timedelta(days=30)
        previous_month_incidents = Incident.query.filter(
            Incident.reported_by == user_id,
            Incident.date_reported >= previous_month_start,
            Incident.date_reported < month_ago
        ).count()
        
        # Open incidents
        open_incidents = Incident.query.filter(
            Incident.reported_by == user_id,
            Incident.status.in_(['reported', 'investigating'])
        ).count()
        
        # Critical incidents
        critical_incidents = Incident.query.filter(
            Incident.reported_by == user_id,
            Incident.severity == 'critical'
        ).count()
        
        # Incident rate calculations
        incident_trend = calculate_incident_trend(user_id)
        monthly_incident_rate = monthly_incidents
        incident_rate_change = calculate_percentage_change(monthly_incidents, previous_month_incidents)
        
        # Average time to resolution
        avg_resolution_time = calculate_avg_incident_resolution_time(user_id)
        
        # Incident by severity
        severity_breakdown = get_incident_severity_breakdown(user_id, month_ago, now)
        
        return {
            'total_incidents': total_incidents,
            'monthly_incidents': monthly_incidents,
            'open_incidents': open_incidents,
            'critical_incidents': critical_incidents,
            'monthly_incident_rate': monthly_incident_rate,
            'incident_trend': incident_trend,
            'incident_rate_change': incident_rate_change,
            'avg_resolution_days': avg_resolution_time,
            'severity_breakdown': severity_breakdown,
            'previous_period_comparison': {
                'current_period': monthly_incidents,
                'previous_period': previous_month_incidents,
                'change_percentage': incident_rate_change
            }
        }
        
    except Exception as e:
        logger.error(f"Incident metrics error: {e}")
        return {}

