def calculate_overall_safety_score(incident_metrics, violation_metrics, prevention_metrics, compliance_metrics):
    """Calculate overall safety score from multiple metrics"""
    try:
        weights = {
            'incidents': 0.3,
            'violations': 0.25,
            'prevention': 0.25,
            'compliance': 0.2
        }
        
        # Calculate component scores (0-100 scale)
        incident_score = max(0, 100 - (incident_metrics.get('monthly_incidents', 0) * 5))
        violation_score = violation_metrics.get('compliance_rate', 0)
        prevention_score = calculate_prevention_score(prevention_metrics)
        compliance_score = compliance_metrics.get('document_compliance', {}).get('rate', 0)
        
        # Weighted average
        overall_score = (
            incident_score * weights['incidents'] +
            violation_score * weights['violations'] +
            prevention_score * weights['prevention'] +
            compliance_score * weights['compliance']
        )
        
        return round(overall_score, 1)
        
    except Exception as e:
        logger.error(f"Calculate overall safety score error: {e}")
        return 0.0

def calculate_prevention_score(prevention_metrics):
    """Calculate prevention score from proactive metrics"""
    try:
        training_score = prevention_metrics.get('training_metrics', {}).get('completion_rate', 0)
        observation_score = min(100, prevention_metrics.get('safety_observations', {}).get('recent', 0) * 10)
        inspection_score = prevention_metrics.get('inspections', {}).get('avg_compliance_rate', 0)
        
        return (training_score + observation_score + inspection_score) / 3
        
    except Exception as e:
        logger.error(f"Calculate prevention score error: {e}")
        return 0.0

