def get_training_compliance_summary(user_id):
    """Get training compliance summary"""
    try:
        user = User.query.get(user_id)
        required_trainings = Training.query.filter(
            Training.required_for_roles.isnot(None)
        ).all()
        
        required_trainings = [t for t in required_trainings 
                            if t.required_for_roles and user.role in json.loads(t.required_for_roles)]
        
        completed_count = 0
        for training in required_trainings:
            completion = TrainingRecord.query.filter_by(
                user_id=user_id,
                training_id=training.id,
                status='completed'
            ).first()
            if completion:
                # Check if still valid
                if training.frequency_days:
                    next_due = completion.completion_date + timedelta(days=training.frequency_days)
                    if datetime.utcnow() <= next_due:
                        completed_count += 1
                else:
                    completed_count += 1
        
        total_required = len(required_trainings)
        compliance_rate = (completed_count / total_required * 100) if total_required > 0 else 100
        
        return {
            'rate': round(compliance_rate, 1),
            'completed': completed_count,
            'required': total_required,
            'overdue': total_required - completed_count
        }
    except Exception as e:
        logger.error(f"Get training compliance summary error: {e}")
        return {'rate': 0, 'completed': 0, 'required': 0, 'overdue': 0}

