def generate_excel_export(export_data, filename, metadata):
    """Generate Excel export with multiple sheets"""
    try:
        import pandas as pd
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment
        from openpyxl.utils.dataframe import dataframe_to_rows
        
        filename += '.xlsx'
        file_path = os.path.join(UPLOAD_DIRS['reports'], filename)
        
        wb = Workbook()
        
        # Remove default sheet
        wb.remove(wb.active)
        
        # Safety Metrics Sheet
        if 'safety' in export_data:
            ws_safety = wb.create_sheet("Safety Metrics")
            safety_data = export_data['safety']
            
            # Add header
            ws_safety.append(['SAFETY METRICS REPORT'])
            ws_safety.append(['Generated:', metadata['generated_at']])
            ws_safety.append(['Date Range:', metadata['date_range']])
            ws_safety.append([])
            
            # Overall Safety Score
            ws_safety.append(['Overall Safety Score', safety_data.get('overall_safety_score', 0)])
            ws_safety.append(['Safety Rating', get_safety_rating(safety_data.get('overall_safety_score', 0))])
            ws_safety.append([])
            
            # Incident Metrics
            ws_safety.append(['INCIDENT METRICS'])
            incident_metrics = safety_data.get('incident_metrics', {})
            ws_safety.append(['Total Incidents', incident_metrics.get('total_incidents', 0)])
            ws_safety.append(['Monthly Incidents', incident_metrics.get('monthly_incidents', 0)])
            ws_safety.append(['Open Incidents', incident_metrics.get('open_incidents', 0)])
            ws_safety.append(['Critical Incidents', incident_metrics.get('critical_incidents', 0)])
            ws_safety.append(['Incident Rate Change', incident_metrics.get('incident_rate_change', 0)])
            ws_safety.append([])
            
            # Violation Metrics
            ws_safety.append(['VIOLATION METRICS'])
            violation_metrics = safety_data.get('violation_metrics', {})
            ws_safety.append(['Total Violations', violation_metrics.get('total_violations', 0)])
            ws_safety.append(['Monthly Violations', violation_metrics.get('monthly_violations', 0)])
            ws_safety.append(['Compliance Rate', violation_metrics.get('compliance_rate', 0)])
            ws_safety.append([])
            
            # Style the safety sheet
            style_excel_sheet(ws_safety)
        
        # Compliance Metrics Sheet
        if 'compliance' in export_data:
            ws_compliance = wb.create_sheet("Compliance Metrics")
            compliance_data = export_data['compliance']
            
            ws_compliance.append(['COMPLIANCE METRICS REPORT'])
            ws_compliance.append([])
            
            comp_data = [
                ['Compliance Area', 'Rate', 'Status'],
                ['Document Compliance', compliance_data.get('document_compliance', {}).get('rate', 0), get_compliance_status(compliance_data.get('document_compliance', {}).get('rate', 0))],
                ['Regulatory Compliance', compliance_data.get('regulatory_compliance', {}).get('overall_rate', 0), compliance_data.get('regulatory_compliance', {}).get('status', 'Unknown')],
                ['PPE Compliance', compliance_data.get('ppe_compliance', {}).get('rate', 0), get_compliance_status(compliance_data.get('ppe_compliance', {}).get('rate', 0))]
            ]
            
            for row in comp_data:
                ws_compliance.append(row)
            
            style_excel_sheet(ws_compliance)
        
        # Operations Metrics Sheet
        if 'operations' in export_data:
            ws_operations = wb.create_sheet("Operations Metrics")
            operations_data = export_data['operations']
            
            ws_operations.append(['OPERATIONS METRICS REPORT'])
            ws_operations.append([])
            
            ops_data = [
                ['Metric', 'Value'],
                ['Operational Efficiency', operations_data.get('operational_efficiency', 0)],
                ['Equipment Uptime', operations_data.get('equipment', {}).get('uptime_rate', 0)],
                ['Productivity Score', operations_data.get('productivity', {}).get('score', 0)]
            ]
            
            for row in ops_data:
                ws_operations.append(row)
            
            style_excel_sheet(ws_operations)
        
        wb.save(file_path)
        return file_path
        
    except Exception as e:
        logger.error(f"Excel export generation error: {e}")
        return None

