def style_excel_sheet(worksheet):
    """Apply styling to Excel worksheet"""
    from openpyxl.styles import Font, PatternFill, Alignment
    
    # Style headers
    header_fill = PatternFill(start_color='2c5aa0', end_color='2c5aa0', fill_type='solid')
    header_font = Font(color='FFFFFF', bold=True)
    
    for row in worksheet.iter_rows():
        for cell in row:
            if cell.value and any(header in str(cell.value) for header in ['METRICS', 'Metric', 'Compliance Area', 'Value']):
                cell.fill = header_fill
                cell.font = header_font
                cell.alignment = Alignment(horizontal='center')

def get_safety_rating(score):
    """Get safety rating based on score"""
    if score >= 90:
        return "Excellent"
    elif score >= 80:
        return "Good"
    elif score >= 70:
        return "Fair"
    elif score >= 60:
        return "Needs Improvement"
    else:
        return "Poor"

def get_compliance_status(rate):
    """Get compliance status based on rate"""
    if rate >= 95:
        return "Fully Compliant"
    elif rate >= 85:
        return "Mostly Compliant"
    elif rate >= 75:
        return "Partially Compliant"
    else:
        return "Non-Compliant"

def get_trend_icon(change):
    """Get trend icon based on change percentage"""
    if change > 5:
        return "↗️"  # Increasing
    elif change < -5:
        return "↘️"  # Decreasing
    else:
        return "➡️"  # Stable

