def get_mime_type(export_type):
    """Get MIME type for export file"""
    mime_types = {
        'pdf': 'application/pdf',
        'excel': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'csv': 'text/csv',
        'json': 'application/json'
    }
    return mime_types.get(export_type, 'application/octet-stream')


 

@app.route('/api/notifications', methods=['GET'])
@jwt_required
def get_notifications():
    """Get user notifications with advanced filtering - FIXED NULL HANDLING"""
    try:
        user = getattr(request, 'user', None)
        
        if not user:
            return jsonify({
                'success': False,
                'error': 'User not found',
                'code': 'USER_NOT_FOUND'
            }), 404
        
        user_id = user.id
        
        print(f"\n🔔 GET NOTIFICATIONS FOR USER {user_id}:")
        
        # Get query parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        notification_type = request.args.get('type')
        priority = request.args.get('priority')
        category = request.args.get('category')
        unread_only = request.args.get('unread_only', 'false').lower() == 'true'
        include_expired = request.args.get('include_expired', 'false').lower() == 'true'
        
        # Build query
        query = Notification.query.filter_by(user_id=user_id)
        
        # Apply expiry filter
        if not include_expired:
            current_time = datetime.utcnow()
            print(f"  Applying expiry filter (current time: {current_time})")
            query = query.filter(
                or_(
                    Notification.expires_at.is_(None),
                    Notification.expires_at >= current_time
                )
            )
        
        # Apply other filters
        if notification_type:
            query = query.filter_by(type=notification_type)
        if priority:
            query = query.filter_by(priority=priority)
        if category:
            query = query.filter_by(category=category)
        
        # Handle null is_read values properly
        if unread_only:
            query = query.filter(
                or_(
                    Notification.is_read.is_(None),
                    Notification.is_read == False
                )
            )
            print(f"  Filtering for unread only (including null values)")
        
        # Get total count
        total_count = query.count()
        print(f"  Total notifications found: {total_count}")
        
        if total_count == 0:
            print(f"  No notifications found for user {user_id}")
            return jsonify({
                'success': True,
                'notifications': [],
                'statistics': {
                    'total': 0,
                    'unread': 0,
                    'critical': 0,
                    'categories': {}
                },
                'pagination': {
                    'total': 0,
                    'pages': 0,
                    'current_page': page,
                    'per_page': per_page,
                    'has_next': False,
                    'has_prev': False
                },
                'message': 'No notifications found'
            }), 200
        
        # Paginate
        notifications = query.order_by(Notification.created_at.desc()).paginate(
            page=page, per_page=per_page, error_out=False
        )
        
        # Format notifications
        notifications_data = []
        for notification in notifications.items:
            is_expired = notification.expires_at and notification.expires_at < datetime.utcnow()
            days_ago = (datetime.utcnow().date() - notification.created_at.date()).days
            
            # Treat null as False for is_read
            is_read = notification.is_read if notification.is_read is not None else False
            
            notifications_data.append({
                'id': notification.id,
                'title': notification.title,
                'message': notification.message,
                'type': notification.type,
                'priority': notification.priority,
                'category': notification.category,
                'is_read': is_read,
                'action_url': notification.action_url,
                'expires_at': notification.expires_at.isoformat() if notification.expires_at else None,
                'created_at': notification.created_at.isoformat(),
                'is_expired': is_expired,
                'days_ago': days_ago,
                'user_name': notification.user.name if notification.user else None
            })
        
        # Get statistics
        unread_query = Notification.query.filter_by(user_id=user_id).filter(
            or_(
                Notification.is_read.is_(None),
                Notification.is_read == False
            )
        )
        
        if not include_expired:
            unread_query = unread_query.filter(
                or_(
                    Notification.expires_at.is_(None),
                    Notification.expires_at >= datetime.utcnow()
                )
            )
        
        unread_count = unread_query.count()
        
        # Critical unread count
        critical_unread_query = unread_query.filter_by(priority='critical')
        critical_count = critical_unread_query.count()
        
        # Build categories statistics
        categories_stats = {}
        if not category:
            categories = ['system', 'safety', 'compliance', 'training', 'project', 'incident']
            for cat in categories:
                cat_query = Notification.query.filter_by(user_id=user_id, category=cat)
                if not include_expired:
                    cat_query = cat_query.filter(
                        or_(
                            Notification.expires_at.is_(None),
                            Notification.expires_at >= datetime.utcnow()
                        )
                    )
                count = cat_query.count()
                if count > 0:
                    categories_stats[cat] = count
        
        print(f"  Statistics: total={total_count}, unread={unread_count}, critical={critical_count}")
        print(f"  Returning {len(notifications_data)} notifications")
        
        return jsonify({
            'success': True,
            'notifications': notifications_data,
            'statistics': {
                'total': total_count,
                'unread': unread_count,
                'critical': critical_count,
                'categories': categories_stats
            },
            'pagination': {
                'total': notifications.total,
                'pages': notifications.pages,
                'current_page': page,
                'per_page': per_page,
                'has_next': notifications.has_next,
                'has_prev': notifications.has_prev
            }
        }), 200

    except Exception as e:
        print(f"❌ ERROR in get_notifications: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'NOTIFICATIONS_FETCH_ERROR'
        }), 500



    
def format_notification(notification):
    """Helper function to format a notification"""
    is_expired = notification.expires_at and notification.expires_at < datetime.utcnow()
    days_ago = (datetime.utcnow().date() - notification.created_at.date()).days
    
    return {
        'id': notification.id,
        'title': notification.title,
        'message': notification.message,
        'type': notification.type,
        'priority': notification.priority,
        'category': notification.category,
        'is_read': notification.is_read,
        'action_url': notification.action_url,
        'expires_at': notification.expires_at.isoformat() if notification.expires_at else None,
        'created_at': notification.created_at.isoformat(),
        'is_expired': is_expired,
        'days_ago': days_ago,
        'user_name': notification.user.name if notification.user else None
    }


