@app.route('/api/powerbi/training', methods=['GET'], endpoint='get_training')
@jwt_required
def get_training():
    """Get training completion statistics - Filtered by user_id, company_id, and project_id"""
    try:
        print(f"\n{'='*60}")
        print(f"📊 GET TRAINING - START")
        print(f"{'='*60}")
        
        user = getattr(request, 'user', None)
        if not user:
            return jsonify({'success': False, 'error': 'User authentication failed'}), 401
        
        print(f"👤 User: ID={user.id}, Email={user.email}")
        
        company_id = user.company_id or 1
        print(f"🏢 Company ID: {company_id}")
        
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        project_id = request.args.get('project_id')
        
        print(f"📅 Date range: {start_date} to {end_date}")
        print(f"📌 Project ID: {project_id if project_id else 'All Projects'}")
        
        # ✅ FILTER BY company_id AND project_id
        query = Training.query.filter(Training.company_id == company_id)
        
        # ✅ Apply project filter
        if project_id:
            try:
                query = query.filter(Training.project_id == int(project_id))
                print(f"  ✅ Applied project filter: {project_id}")
            except ValueError:
                print(f"  ⚠️ Invalid project_id format: {project_id}")
        
        company_trainings = query.all()
        training_ids = [t.id for t in company_trainings]
        
        if training_ids:
            record_query = TrainingRecord.query.filter(
                TrainingRecord.user_id == user.id,
                TrainingRecord.training_id.in_(training_ids)
            )
        else:
            record_query = TrainingRecord.query.filter(TrainingRecord.user_id == user.id, False)
        
        if start_date:
            try:
                record_query = record_query.filter(TrainingRecord.completion_date >= datetime.strptime(start_date, '%Y-%m-%d'))
            except:
                pass
        
        if end_date:
            try:
                record_query = record_query.filter(TrainingRecord.completion_date <= datetime.strptime(end_date, '%Y-%m-%d'))
            except:
                pass
        
        records = record_query.all()
        print(f"📊 Total training records found for user {user.id}: {len(records)}")
        
        training_stats = {}
        for record in records:
            if record.training:
                training_name = record.training.title
                if training_name not in training_stats:
                    training_stats[training_name] = {
                        'count': 0,
                        'latest_date': record.completion_date
                    }
                training_stats[training_name]['count'] += 1
                if record.completion_date > training_stats[training_name]['latest_date']:
                    training_stats[training_name]['latest_date'] = record.completion_date
        
        data = []
        for i, (name, stats) in enumerate(training_stats.items(), 1):
            data.append({
                'id': i,
                'type': name,
                'count': stats['count'],
                'completed_date': stats['latest_date'].isoformat() if stats['latest_date'] else None
            })
        
        print(f"✅ Returning {len(data)} training records for user {user.id}")
        print(f"{'='*60}\n")
        
        return jsonify({'success': True, 'data': data}), 200
        
    except Exception as e:
        print(f"❌ ERROR in get_training: {e}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e),
            'message': 'Failed to load training data'
        }), 500

@app.route('/api/powerbi/training', methods=['POST'], endpoint='create_training')
@jwt_required
def create_training():
    """Create new training record with project_id"""
    try:
        print(f"\n📝 CREATE TRAINING RECORD:")
        
        user = getattr(request, 'user', None)
        if not user:
            return jsonify({'success': False, 'error': 'User authentication failed'}), 401
        
        data = request.get_json()
        if not data:
            return jsonify({'success': False, 'error': 'No JSON data provided'}), 400
        
        company_id = user.company_id or 1
        project_id = data.get('project_id')
        
        print(f"  User ID: {user.id}")
        print(f"  Company ID: {company_id}")
        print(f"  Project ID: {project_id if project_id else 'None'}")
        
        from models import TrainingRecord, Training
        
        training_course = None
        if data.get('type'):
            training_course = Training.query.filter(
                (Training.title.ilike(f"%{data['type']}%")) | 
                (Training.category.ilike(f"%{data['type']}%"))
            ).first()
        
        if not training_course:
            training_course = Training(
                code=f"TR{datetime.utcnow().strftime('%Y%m%d%H%M%S')}",
                title=data.get('type', 'Safety Training'),
                category=data.get('type', 'safety'),
                duration_minutes=data.get('duration_minutes', 60),
                company_id=company_id,
                project_id=project_id,
                created_by=user.id
            )
            db.session.add(training_course)
            db.session.flush()
        
        training_record = TrainingRecord(
            user_id=user.id,
            training_id=training_course.id,
            completion_date=datetime.strptime(data['completed_date'], '%Y-%m-%d') if data.get('completed_date') else datetime.utcnow(),
            score=data.get('score'),
            status='completed',
            notes=data.get('notes'),
            company_id=company_id,
            project_id=project_id
        )
        
        db.session.add(training_record)
        db.session.commit()
        
        log_admin_action(
            user_id=user.id,
            action=f"Created training record for {data.get('type')}",
            resource_type='training_record',
            resource_id=training_record.id
        )
        
        return jsonify({
            'success': True,
            'message': 'Training record created successfully',
            'id': training_record.id,
            'project_id': training_record.project_id
        }), 201
        
    except Exception as e:
        print(f"❌ ERROR in create_training: {e}")
        traceback.print_exc()
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

