@app.route('/api/powerbi/projects', methods=['POST'], endpoint='create_powerbi_project')
@jwt_required
def create_powerbi_project():
    """Create a new project for PowerBI"""
    try:
        print(f"\n{'='*60}")
        print(f"📝 CREATE POWERBI PROJECT - START")
        print(f"{'='*60}")
        
        user = getattr(request, 'user', None)
        if not user:
            return jsonify({
                'success': False,
                'error': 'User authentication failed',
                'code': 'AUTHENTICATION_ERROR'
            }), 401
        
        data = request.get_json()
        print(f"📊 Received data: {data}")
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'VALIDATION_ERROR'
            }), 400
        
        company_id = user.company_id or 1
        print(f"👤 User: ID={user.id}, Email={user.email}")
        print(f"🏢 Company ID: {company_id}")
        
        from models import Project
        import random
        
        # Generate project number
        project_number = f"PRJ-{datetime.utcnow().strftime('%Y%m%d')}-{random.randint(1000, 9999)}"
        
        # Parse dates
        start_date = None
        if data.get('start_date'):
            try:
                start_date = datetime.strptime(data['start_date'], '%Y-%m-%d')
            except:
                try:
                    start_date = datetime.strptime(data['start_date'], '%Y-%m-%dT%H:%M:%S.%f')
                except:
                    start_date = datetime.utcnow()
        
        end_date = None
        if data.get('end_date'):
            try:
                end_date = datetime.strptime(data['end_date'], '%Y-%m-%d')
            except:
                try:
                    end_date = datetime.strptime(data['end_date'], '%Y-%m-%dT%H:%M:%S.%f')
                except:
                    pass
        
        # Create project
        project = Project(
            project_number=project_number,
            name=data['name'],
            description=data.get('description', ''),
            status=data.get('status', 'planning'),
            priority=data.get('priority', 'medium'),
            start_date=start_date,
            end_date=end_date,
            budget=data.get('budget'),
            department=data.get('department'),
            user_id=user.id,
            created_by=user.id,
            company_id=company_id,
            industry=data.get('industry')
        )
        
        db.session.add(project)
        db.session.commit()
        
        print(f"✅ Created project:")
        print(f"   ID: {project.id}")
        print(f"   Number: {project.project_number}")
        print(f"   Name: {project.name}")
        print(f"   Created By: {project.created_by}")
        print(f"   Company ID: {project.company_id}")
        print(f"{'='*60}\n")
        
        return jsonify({
            'success': True,
            'message': 'Project created successfully',
            'id': project.id,
            'project_number': project.project_number,
            'data': {
                'id': project.id,
                'project_number': project.project_number,
                'name': project.name,
                'status': project.status,
                'created_by': project.created_by,
                'company_id': project.company_id
            }
        }), 201
        
    except Exception as e:
        print(f"❌ ERROR in create_powerbi_project: {e}")
        import traceback
        traceback.print_exc()
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': str(e),
            'code': 'INTERNAL_SERVER_ERROR'
        }), 500

