@app.route('/api/auth/reset-password', methods=['POST'])
@app.route('/api/reset-password', methods=['POST'])
@limiter.limit("5 per minute")
def reset_password():
    """Enhanced password reset"""
    try:
        data = request.get_json()
        token = data.get('token', '').strip()
        new_password = data.get('new_password', '')

        if not token or not new_password:
            return jsonify({'error': 'Token and new password are required'}), 400

        # Validate password strength
        if len(new_password) < 8:
            return jsonify({'error': 'Password must be at least 8 characters long'}), 400

        # Find valid reset request
        reset_request = PasswordReset.query.filter_by(
            token=token,
            used=False
        ).first()

        if not reset_request:
            return jsonify({'error': 'Invalid or expired reset token'}), 400

        if datetime.utcnow() > reset_request.expires_at:
            return jsonify({'error': 'Reset token has expired'}), 400

        # Update user password
        user = User.query.filter_by(email=reset_request.email).first()
        if user:
            user.password_hash = generate_password_hash(new_password)
            reset_request.used = True
            reset_request.resolved_at = datetime.utcnow()
            db.session.commit()

            # Send confirmation email
            email_body = """
            <h2>Password Updated Successfully</h2>
            <p>Your SafetyTrack Pro password has been successfully reset.</p>
            <p>If you did not make this change, please contact support immediately.</p>
            """
            send_email(user.email, "Password Updated - SafetyTrack Pro", email_body)

            # Create notification
            create_notification(
                user.id,
                "Password Updated",
                "Your password has been successfully reset.",
                "info",
                "medium"
            )

            # Log the action
            log_admin_action(user.id, "Password reset completed", "authentication", user.id)

            return jsonify({'message': 'Password reset successfully'}), 200
        else:
            return jsonify({'error': 'User not found'}), 404

    except Exception as e:
        logger.error(f"Reset password error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500
    
