@app.route('/api/documents', methods=['GET'])
@jwt_required
def get_documents():
    """Get documents with filtering and pagination - Full access control"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user has document access
        if not is_super_admin:
            has_access = (
                has_document_feature_access(current_user, 'view') or
                has_document_feature_access(current_user, 'upload') or
                has_document_feature_access(current_user, 'download')
            )
            if not has_access:
                return jsonify({
                    'success': False,
                    'error': 'Document access not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE',
                    'required_plan': 'free',
                    'current_plan': getattr(current_user, 'subscription_plan', 'free')
                }), 403
        
        # ==================== QUERY PARAMETERS ====================
        search = request.args.get('search', '')
        status = request.args.get('status')
        document_type = request.args.get('document_type')
        module = request.args.get('module')
        category = request.args.get('category')
        priority = request.args.get('priority')
        date_from = request.args.get('date_from')
        date_to = request.args.get('date_to')
        created_by = request.args.get('created_by')
        limit = request.args.get('limit', 20, type=int)
        offset = request.args.get('offset', 0, type=int)
        sort_by = request.args.get('sort_by', 'created_at')
        sort_order = request.args.get('sort_order', 'desc')
        
        # Validate pagination
        if limit > 100:
            limit = 100
        if limit < 1:
            limit = 10
        
        # ==================== BUILD QUERY WITH SCOPE ====================
        query = Document.query
        
        # ✅ Apply scope based on user role
        if is_super_admin:
            # Super admin sees all documents
            pass
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                # User has company - show company documents
                query = query.filter_by(company_id=user_company_id)
            else:
                # User has no company - show only their own documents
                query = query.filter_by(user_id=current_user.id)
        
        # ==================== APPLY FILTERS ====================
        if search:
            search_term = f"%{search}%"
            query = query.filter(
                db.or_(
                    Document.title.ilike(search_term),
                    Document.description.ilike(search_term),
                    Document.file_name.ilike(search_term)
                )
            )
        
        if status:
            query = query.filter_by(status=status)
        
        if document_type:
            query = query.filter_by(document_type=document_type)
        
        if module:
            query = query.filter_by(module=module)
        
        if category:
            query = query.filter_by(category=category)
        
        if priority:
            query = query.filter_by(priority=priority)
        
        # Date range
        if date_from:
            try:
                date_from_dt = datetime.fromisoformat(date_from)
                query = query.filter(Document.created_at >= date_from_dt)
            except ValueError:
                pass
        
        if date_to:
            try:
                date_to_dt = datetime.fromisoformat(date_to)
                query = query.filter(Document.created_at <= date_to_dt)
            except ValueError:
                pass
        
        # Created by filter
        if created_by:
            try:
                query = query.filter_by(created_by=created_by)
            except:
                pass
        
        # ==================== SORTING ====================
        sort_mapping = {
            'title': Document.title,
            'created_at': Document.created_at,
            'updated_at': Document.updated_at,
            'status': Document.status,
            'version': Document.version,
            'file_name': Document.file_name
        }
        
        order_col = sort_mapping.get(sort_by, Document.created_at)
        if sort_order.lower() == 'asc':
            query = query.order_by(order_col.asc())
        else:
            query = query.order_by(order_col.desc())
        
        # ==================== PAGINATION ====================
        total = query.count()
        documents = query.limit(limit).offset(offset).all()
        
        # ==================== PREPARE RESPONSE ====================
        documents_data = []
        for doc in documents:
            doc_dict = {
                'id': str(doc.id) if hasattr(doc, 'id') else doc.id,
                'title': doc.title,
                'description': doc.description,
                'document_type': doc.document_type,
                'category': doc.category,
                'module': doc.module,
                'priority': doc.priority,
                'status': doc.status,
                'version': doc.version,
                'file_url': doc.file_url,
                'file_name': doc.file_name,
                'file_size': doc.file_size,
                'mime_type': doc.mime_type,
                'tags': doc.tags or [],
                'is_confidential': doc.is_confidential,
                'requires_approval': doc.requires_approval,
                'review_status': doc.review_status,
                'review_frequency': doc.review_frequency,
                'next_review_date': doc.next_review_date.isoformat() if doc.next_review_date else None,
                'expires_at': doc.expires_at.isoformat() if doc.expires_at else None,
                'created_at': doc.created_at.isoformat() if doc.created_at else None,
                'updated_at': doc.updated_at.isoformat() if doc.updated_at else None,
                'published_at': doc.published_at.isoformat() if doc.published_at else None,
                'archived_at': doc.archived_at.isoformat() if doc.archived_at else None,
                'created_by': str(doc.created_by) if doc.created_by else None,
                'updated_by': str(doc.updated_by) if doc.updated_by else None,
                'created_by_name': doc.creator.name if hasattr(doc, 'creator') and doc.creator else None,
                'updated_by_name': doc.updater.name if hasattr(doc, 'updater') and doc.updater else None,
                'company_id': str(doc.company_id) if doc.company_id else None,
                'user_id': str(doc.user_id) if doc.user_id else None,
                'permissions': {
                    'can_edit': can_edit_document(current_user, doc, is_super_admin),
                    'can_delete': can_delete_document(current_user, doc, is_super_admin),
                    'can_view': True,
                    'can_download': can_download_document(current_user, doc, is_super_admin)
                }
            }
            documents_data.append(doc_dict)
        
        # ==================== GET STATS ====================
        if is_super_admin:
            stats = {
                'total': Document.query.count(),
                'draft': Document.query.filter_by(status='draft').count(),
                'review': Document.query.filter_by(status='review').count(),
                'approved': Document.query.filter_by(status='approved').count(),
                'published': Document.query.filter_by(status='published').count(),
                'archived': Document.query.filter_by(status='archived').count(),
                'rejected': Document.query.filter_by(status='rejected').count()
            }
        else:
            # Use the same scope for stats
            stats_query = query  # Reuse the filtered query
            stats = {
                'total': stats_query.count(),
                'draft': stats_query.filter_by(status='draft').count(),
                'review': stats_query.filter_by(status='review').count(),
                'approved': stats_query.filter_by(status='approved').count(),
                'published': stats_query.filter_by(status='published').count(),
                'archived': stats_query.filter_by(status='archived').count(),
                'rejected': stats_query.filter_by(status='rejected').count()
            }
        
        return jsonify({
            'success': True,
            'documents': documents_data,
            'pagination': {
                'total': total,
                'limit': limit,
                'offset': offset,
                'has_more': offset + limit < total
            },
            'stats': stats,
            'access_level': 'super_admin' if is_super_admin else 'user',
            'scope': 'all' if is_super_admin else ('company' if getattr(current_user, 'company_id', None) else 'user'),
            'permissions': {
                'can_upload': can_upload_document(current_user, is_super_admin),
                'can_create': can_create_document(current_user, is_super_admin),
                'can_view': True,
                'can_edit': can_edit_document(current_user, None, is_super_admin)
            }
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Get documents error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'details': str(e) if current_app.debug else None
        }), 500

