# ============================================================================
# PERMISSION HELPER FUNCTIONS
# ============================================================================

def can_upload_document(user, is_super_admin=False):
    """Check if user can upload documents"""
    if is_super_admin:
        return True
    return has_document_feature_access(user, 'upload')

def can_create_document(user, is_super_admin=False):
    """Check if user can create documents"""
    if is_super_admin:
        return True
    return has_document_feature_access(user, 'create')

def can_edit_document(user, document, is_super_admin=False):
    """Check if user can edit a document"""
    if is_super_admin:
        return True
    
    if not document:
        return has_document_feature_access(user, 'edit')
    
    # Check if user owns the document
    if hasattr(document, 'user_id') and document.user_id == user.id:
        return True
    
    # Check if user is in the same company
    user_company_id = getattr(user, 'company_id', None)
    if user_company_id and hasattr(document, 'company_id') and document.company_id == user_company_id:
        return has_document_feature_access(user, 'edit')
    
    return False

def can_delete_document(user, document, is_super_admin=False):
    """Check if user can delete a document"""
    if is_super_admin:
        return True
    
    if not document:
        return has_document_feature_access(user, 'delete')
    
    # Only document owner or company admin can delete
    if hasattr(document, 'user_id') and document.user_id == user.id:
        return has_document_feature_access(user, 'delete')
    
    user_company_id = getattr(user, 'company_id', None)
    if user_company_id and hasattr(document, 'company_id') and document.company_id == user_company_id:
        # Company member can delete if they have delete permission
        return has_document_feature_access(user, 'delete')
    
    return False

def can_download_document(user, document, is_super_admin=False):
    """Check if user can download a document"""
    if is_super_admin:
        return True
    
    if not document:
        return has_document_feature_access(user, 'download')
    
    # Check if user has access to the document
    return can_access_document(user, document, is_super_admin) and has_document_feature_access(user, 'download')


