@app.route('/api/documents/<int:document_id>', methods=['GET'])
@jwt_required
def get_document(document_id):
    """Get detailed document information"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # Get document with scope
        if is_super_admin:
            document = Document.query.get(document_id)
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter_by(
                    id=document_id,
                    company_id=user_company_id
                ).first()
            else:
                document = Document.query.filter_by(
                    id=document_id,
                    user_id=current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found or you do not have permission to access it',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # Check if user has view access
        if not can_access_document(current_user, document, is_super_admin):
            return jsonify({
                'success': False,
                'error': 'You do not have permission to view this document',
                'code': 'ACCESS_DENIED'
            }), 403
        
        # Parse analysis results
        analysis_results = {}
        if document.analysis_result:
            try:
                analysis_results = json.loads(document.analysis_result)
            except:
                analysis_results = {}
        
        return jsonify({
            'success': True,
            'document': {
                'id': document.id,
                'title': document.title,
                'description': document.description,
                'document_type': document.document_type,
                'category': document.category,
                'module': document.module,
                'priority': document.priority,
                'status': document.status,
                'version': document.version,
                'file_url': document.file_url,
                'file_name': document.file_name,
                'file_size': document.file_size,
                'mime_type': document.mime_type,
                'tags': document.tags or [],
                'is_confidential': document.is_confidential,
                'requires_approval': document.requires_approval,
                'review_status': document.review_status,
                'review_frequency': document.review_frequency,
                'next_review_date': document.next_review_date.isoformat() if document.next_review_date else None,
                'expires_at': document.expires_at.isoformat() if document.expires_at else None,
                'created_at': document.created_at.isoformat() if document.created_at else None,
                'updated_at': document.updated_at.isoformat() if document.updated_at else None,
                'analysis': analysis_results,
                'download_url': f'/api/documents/{document.id}/download',
                'report_url': f'/api/reports/report_{document.id}.pdf' if document.id else None,
                'company_id': document.company_id,
                'user_id': document.user_id,
                'permissions': {
                    'can_edit': can_edit_document(current_user, document, is_super_admin),
                    'can_delete': can_delete_document(current_user, document, is_super_admin),
                    'can_download': can_download_document(current_user, document, is_super_admin),
                    'can_view': True
                }
            },
            'access_level': 'super_admin' if is_super_admin else 'user'
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Get document error: {e}")
        return jsonify({
            'success': False,
            'error': 'Internal server error'
        }), 500


