# In your SocketIO setup
@socketio.on('join_progress_channel')
def handle_join_progress_channel(data):
    """Join a progress channel for real-time updates"""
    export_id = data.get('export_id')
    user_id = data.get('user_id')  # Should be validated
    
    # Verify user has access to this export
    with db.session() as session:
        export_job = session.query(ExportJob).filter_by(
            id=export_id,
            user_id=user_id
        ).first()
        
        if export_job:
            channel = f"export_progress_{export_id}"
            join_room(channel)
            emit('channel_joined', {'channel': channel, 'export_id': export_id})
        else:
            emit('error', {'message': 'Access denied'})

@socketio.on('leave_progress_channel')
def handle_leave_progress_channel(data):
    """Leave a progress channel"""
    export_id = data.get('export_id')
    channel = f"export_progress_{export_id}"
    leave_room(channel)
    emit('channel_left', {'channel': channel})

@app.route('/api/teams', methods=['POST'], endpoint='create_team')
@jwt_required
def create_team():
    """Create a new team"""
    try:
        user_id = request.user_id
        data = request.get_json()

        name = data.get('name', '').strip()
        description = data.get('description', '').strip()
        hospital_id = data.get('hospital_id')

        if not name:
            return jsonify({'error': 'Team name is required'}), 400

        # Check if user can create more teams (based on plan)
        user_teams_count = Team.query.filter_by(created_by=user_id).count()
        user_plan = get_effective_plan(User.query.get(user_id))
        max_teams = PLANS.get(user_plan, {}).get('limits', {}).get('team_members', 1)

        if user_teams_count >= max_teams:
            return jsonify({
                'error': f'Team creation limit reached for your {user_plan} plan',
                'current_teams': user_teams_count,
                'max_teams': max_teams
            }), 403

        # Create team
        team = Team(
            name=name,
            description=description,
            hospital_id=hospital_id,
            created_by=user_id
        )
        db.session.add(team)
        db.session.commit()

        # Add creator as team owner
        team_member = TeamMember(
            team_id=team.id,
            user_id=user_id,
            role='owner',
            permissions=json.dumps(['read', 'write', 'admin', 'delete'])
        )
        db.session.add(team_member)
        db.session.commit()

        # Log action
        log_admin_action(user_id, f"Created team: {name}", "team", team.id)

        return jsonify({
            'message': 'Team created successfully',
            'team': {
                'id': team.id,
                'name': team.name,
                'description': team.description,
                'created_at': team.created_at.isoformat(),
                'member_count': 1
            }
        }), 201

    except Exception as e:
        logger.error(f"Create team error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/permits', methods=['GET'], endpoint='get_permits')
@jwt_required
def get_permits():
    """Get permits with advanced filtering"""
    try:
        user_id = user.id
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 10, type=int)
        status = request.args.get('status')
        permit_type = request.args.get('type')
        risk_level = request.args.get('risk_level')
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        sort_by = request.args.get('sort_by', 'created_at')
        sort_order = request.args.get('sort_order', 'desc')

        # Build query - users can see their own permits and permits they approved
        query = Permit.query.filter(
            or_(
                Permit.user_id == user_id,
                Permit.approved_by == user_id
            )
        )

        # Apply filters
        if status:
            query = query.filter_by(status=status)
        if permit_type:
            query = query.filter_by(permit_type=permit_type)
        if risk_level:
            query = query.filter_by(risk_level=risk_level)
        if start_date:
            start_date_obj = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
            query = query.filter(Permit.start_date >= start_date_obj)
        if end_date:
            end_date_obj = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
            query = query.filter(Permit.end_date <= end_date_obj)

        # Apply sorting
        if sort_by == 'start_date':
            if sort_order == 'asc':
                query = query.order_by(Permit.start_date.asc())
            else:
                query = query.order_by(Permit.start_date.desc())
        elif sort_by == 'risk_level':
            risk_order = case(
                (Permit.risk_level == 'critical', 1),
                (Permit.risk_level == 'high', 2),
                (Permit.risk_level == 'medium', 3),
                (Permit.risk_level == 'low', 4),
                else_=5
            )
            if sort_order == 'asc':
                query = query.order_by(risk_order.asc())
            else:
                query = query.order_by(risk_order.desc())
        else:  # created_at
            if sort_order == 'asc':
                query = query.order_by(Permit.created_at.asc())
            else:
                query = query.order_by(Permit.created_at.desc())

        # Paginate results
        permits = query.paginate(page=page, per_page=per_page, error_out=False)

        permits_data = []
        for permit in permits.items:
            # Calculate days remaining
            days_remaining = (permit.end_date.date() - datetime.utcnow().date()).days
            is_expired = days_remaining < 0
            is_expiring_soon = 0 <= days_remaining <= 7

            permits_data.append({
                'id': permit.id,
                'permit_number': permit.permit_number,
                'permit_type': permit.permit_type,
                'title': permit.title,
                'description': permit.description,
                'location': permit.location,
                'start_date': permit.start_date.isoformat(),
                'end_date': permit.end_date.isoformat(),
                'status': permit.status,
                'risk_level': permit.risk_level,
                'required_ppe': json.loads(permit.required_ppe) if permit.required_ppe else [],
                'safety_precautions': permit.safety_precautions,
                'applicant': {
                    'id': permit.applicant.id,
                    'name': permit.applicant.name,
                    'email': permit.applicant.email
                },
                'approver': {
                    'id': permit.approver.id if permit.approver else None,
                    'name': permit.approver.name if permit.approver else None
                } if permit.approved_by else None,
                'approved_at': permit.approved_at.isoformat() if permit.approved_at else None,
                'rejection_reason': permit.rejection_reason,
                'department': {
                    'id': permit.department.id if permit.department else None,
                    'name': permit.department.name if permit.department else None
                },
                'days_remaining': days_remaining,
                'is_expired': is_expired,
                'is_expiring_soon': is_expiring_soon,
                'can_approve': permit.status == 'pending' and permit.user_id != user_id  # Can't approve own permits
            })

        return jsonify({
            'permits': permits_data,
            'pagination': {
                'total': permits.total,
                'pages': permits.pages,
                'current_page': page,
                'per_page': per_page
            }
        }), 200

    except Exception as e:
        logger.error(f"Get permits error: {e}")
        return jsonify({'error': 'Internal server error'}), 500



