@app.route('/api/user/update-language', methods=['POST'])
@jwt_required  # ✅ Use your custom decorator
@limiter.limit("10 per minute")
def update_language():
    """Update user's preferred language"""
    try:
        # ✅ Use request.user
        current_user = request.user
        
        if not current_user:
            return jsonify({'error': 'User not found'}), 404
        
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No JSON data provided'}), 400

        new_language = data.get('language')
        
        # Validate language
        if not new_language:
            return jsonify({'error': 'Language is required'}), 400
        
        # List of supported languages
        supported_languages = ['en', 'hi', 'ja', 'ar', 'ru', 'fr', 'es', 'de', 'pt', 'zh']
        
        if new_language not in supported_languages:
            return jsonify({'error': f'Language {new_language} is not supported'}), 400

        # Update user's language preference
        current_user.preferred_language = new_language
        current_user.updated_at = datetime.utcnow()
        db.session.commit()

        # Log the change
        logger.info(f"User {current_user.id} changed language to {new_language}")

        return jsonify({
            'message': 'Language preference updated successfully',
            'language': new_language
        }), 200

    except Exception as e:
        logger.error(f"Language update error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500


