# ✅ FIXED: Approve Permit - Using @jwt_required
# ============================================
@app.route('/api/permits/<int:permit_id>/approve', methods=['POST'], endpoint='approve_permit')
@jwt_required  # ✅ Use your custom decorator
def approve_permit(permit_id):
    """Approve a permit application"""
    try:
        # ✅ Use request.user
        current_user = request.user
        
        if not current_user:
            return jsonify({'error': 'User not found'}), 404
        
        data = request.get_json()

        permit = Permit.query.get(permit_id)
        if not permit:
            return jsonify({'error': 'Permit not found'}), 404

        # Check if user can approve (not the applicant and has appropriate role)
        if permit.user_id == current_user.id:
            return jsonify({'error': 'Cannot approve your own permit'}), 403

        # Check user role and permissions
        approver_roles = ['Safety Officer', 'Site Supervisor', 'Manager', 'Administrator']
        if current_user.role not in approver_roles:
            return jsonify({'error': 'Insufficient permissions to approve permits'}), 403

        # Update permit status
        permit.status = 'approved'
        permit.approved_by = current_user.id
        permit.approved_at = datetime.utcnow()
        permit.updated_at = datetime.utcnow()

        db.session.commit()

        # Create notification for applicant
        create_notification(
            permit.user_id,
            "Permit Approved",
            f"Your permit '{permit.title}' has been approved",
            "success",
            "medium",
            f"/permits/{permit.id}"
        )

        return jsonify({
            'message': 'Permit approved successfully',
            'permit': {
                'id': permit.id,
                'status': permit.status,
                'approved_at': permit.approved_at.isoformat()
            }
        }), 200

    except Exception as e:
        logger.error(f"Approve permit error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/permits/<int:permit_id>/reject', methods=['POST'], endpoint='reject_permit')
@jwt_required
def reject_permit(permit_id):
    """Reject a permit application"""
    try:
        user_id = user.id
        data = request.get_json()

        permit = Permit.query.get(permit_id)
        if not permit:
            return jsonify({'error': 'Permit not found'}), 404

        # Check permissions (same as approve)
        if permit.user_id == user_id:
            return jsonify({'error': 'Cannot reject your own permit'}), 403

        user = User.query.get(user_id)
        approver_roles = ['Safety Officer', 'Site Supervisor', 'Manager', 'Administrator']
        if user.role not in approver_roles:
            return jsonify({'error': 'Insufficient permissions to reject permits'}), 403

        rejection_reason = data.get('rejection_reason', '')
        if not rejection_reason:
            return jsonify({'error': 'Rejection reason is required'}), 400

        # Update permit status
        permit.status = 'rejected'
        permit.approved_by = user_id
        permit.approved_at = datetime.utcnow()
        permit.rejection_reason = rejection_reason
        permit.updated_at = datetime.utcnow()

        db.session.commit()

        # Create notification for applicant
        create_notification(
            permit.user_id,
            "Permit Rejected",
            f"Your permit '{permit.title}' was rejected. Reason: {rejection_reason}",
            "error",
            "medium",
            f"/permits/{permit.id}"
        )

        return jsonify({
            'message': 'Permit rejected successfully',
            'permit': {
                'id': permit.id,
                'status': permit.status,
                'rejection_reason': rejection_reason
            }
        }), 200

    except Exception as e:
        logger.error(f"Reject permit error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/training', methods=['GET'], endpoint='get_pbi_training')
@jwt_required
def get_pbi_training():
    """Get training programs and sessions"""
    try:
        user_id = user.id
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 10, type=int)
        training_type = request.args.get('type')
        status = request.args.get('status')
        show_required = request.args.get('show_required', 'false').lower() == 'true'

        user = User.query.get(user_id)

        # Build query for training programs
        query = Training.query

        if training_type:
            query = query.filter_by(training_type=training_type)

        if show_required:
            # Filter trainings required for user's role
            query = query.filter(
                or_(
                    Training.required_for_roles.is_(None),
                    Training.required_for_roles.like(f'%"{user.role}"%')
                )
            )

        trainings = query.order_by(Training.created_at.desc()).paginate(
            page=page, per_page=per_page, error_out=False
        )

        training_data = []
        for training in trainings.items:
            # Check if user has completed this training
            user_completion = TrainingRecord.query.filter_by(
                user_id=user_id,
                training_id=training.id,
                status='completed'
            ).order_by(TrainingRecord.completion_date.desc()).first()

            # Check if training is overdue
            is_overdue = False
            days_until_due = None
            if user_completion and training.frequency_days:
                next_due = user_completion.completion_date + timedelta(days=training.frequency_days)
                days_until_due = (next_due.date() - datetime.utcnow().date()).days
                is_overdue = days_until_due < 0

            # Get upcoming sessions
            upcoming_sessions = TrainingSession.query.filter(
                TrainingSession.training_id == training.id,
                TrainingSession.session_date >= datetime.utcnow(),
                TrainingSession.status == 'scheduled'
            ).order_by(TrainingSession.session_date.asc()).limit(3).all()

            training_data.append({
                'id': training.id,
                'title': training.title,
                'description': training.description,
                'training_type': training.training_type,
                'duration_minutes': training.duration_minutes,
                'frequency_days': training.frequency_days,
                'department': {
                    'id': training.department.id if training.department else None,
                    'name': training.department.name if training.department else None
                },
                'trainer': {
                    'id': training.trainer.id if training.trainer else None,
                    'name': training.trainer.name if training.trainer else None
                },
                'user_status': {
                    'completed': user_completion is not None,
                    'completion_date': user_completion.completion_date.isoformat() if user_completion else None,
                    'score': user_completion.score if user_completion else None,
                    'is_overdue': is_overdue,
                    'days_until_due': days_until_due
                },
                'upcoming_sessions': [{
                    'id': session.id,
                    'session_date': session.session_date.isoformat(),
                    'location': session.location,
                    'max_attendees': session.max_attendees,
                    'attendees_registered': session.attendees_registered,
                    'spots_available': session.max_attendees - session.attendees_registered if session.max_attendees else None
                } for session in upcoming_sessions],
                'is_required': training.required_for_roles and user.role in json.loads(training.required_for_roles) if training.required_for_roles else False
            })

        return jsonify({
            'trainings': training_data,
            'pagination': {
                'total': trainings.total,
                'pages': trainings.pages,
                'current_page': page,
                'per_page': per_page
            }
        }), 200

    except Exception as e:
        logger.error(f"Get training error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/training/sessions', methods=['GET'], endpoint='get_training_sessions')
@jwt_required
def get_training_sessions():
    """Get training sessions with filtering"""
    try:
        user_id = user.id
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 10, type=int)
        training_id = request.args.get('training_id')
        status = request.args.get('status')
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')

        query = TrainingSession.query

        if training_id:
            query = query.filter_by(training_id=training_id)
        if status:
            query = query.filter_by(status=status)
        if start_date:
            start_date_obj = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
            query = query.filter(TrainingSession.session_date >= start_date_obj)
        if end_date:
            end_date_obj = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
            query = query.filter(TrainingSession.session_date <= end_date_obj)

        # Only show future sessions or sessions user is registered for
        query = query.filter(
            or_(
                TrainingSession.session_date >= datetime.utcnow(),
                TrainingSession.id.in_(
                    db.session.query(TrainingRecord.session_id).filter_by(user_id=user_id)
                )
            )
        )

        sessions = query.order_by(TrainingSession.session_date.asc()).paginate(
            page=page, per_page=per_page, error_out=False
        )

        sessions_data = []
        for session in sessions.items:
            # Check if user is registered
            user_registration = TrainingRecord.query.filter_by(
                user_id=user_id,
                session_id=session.id
            ).first()

            sessions_data.append({
                'id': session.id,
                'training': {
                    'id': session.training.id,
                    'title': session.training.title,
                    'duration_minutes': session.training.duration_minutes
                },
                'session_date': session.session_date.isoformat(),
                'location': session.location,
                'max_attendees': session.max_attendees,
                'attendees_registered': session.attendees_registered,
                'status': session.status,
                'is_registered': user_registration is not None,
                'registration_status': user_registration.status if user_registration else None,
                'spots_available': session.max_attendees - session.attendees_registered if session.max_attendees else None,
                'can_register': session.status == 'scheduled' and (
                    session.max_attendees is None or 
                    session.attendees_registered < session.max_attendees
                ) and not user_registration
            })

        return jsonify({
            'sessions': sessions_data,
            'pagination': {
                'total': sessions.total,
                'pages': sessions.pages,
                'current_page': page,
                'per_page': per_page
            }
        }), 200

    except Exception as e:
        logger.error(f"Get training sessions error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/training/sessions/<int:session_id>/register', methods=['POST'], endpoint='register_training_session')
@jwt_required
def register_training_session(session_id):
    """Register for a training session"""
    try:
        user_id = user.id

        session = TrainingSession.query.get(session_id)
        if not session:
            return jsonify({'error': 'Training session not found'}), 404

        # Check if session is available for registration
        if session.status != 'scheduled':
            return jsonify({'error': 'Session is not available for registration'}), 400

        if session.max_attendees and session.attendees_registered >= session.max_attendees:
            return jsonify({'error': 'Session is full'}), 400

        # Check if already registered
        existing_registration = TrainingRecord.query.filter_by(
            user_id=user_id,
            session_id=session_id
        ).first()

        if existing_registration:
            return jsonify({'error': 'Already registered for this session'}), 400

        # Create training record
        training_record = TrainingRecord(
            user_id=user_id,
            training_id=session.training_id,
            session_id=session_id,
            completion_date=session.session_date,  # Will be updated when completed
            status='registered'
        )

        # Update session attendance
        session.attendees_registered += 1

        db.session.add(training_record)
        db.session.commit()

        # Create notification
        create_notification(
            user_id,
            "Training Registration Confirmed",
            f"You are registered for '{session.training.title}' on {session.session_date.strftime('%Y-%m-%d')}",
            "success",
            "medium",
            f"/training/sessions/{session_id}"
        )

        return jsonify({
            'message': 'Successfully registered for training session',
            'registration': {
                'id': training_record.id,
                'session_date': session.session_date.isoformat(),
                'location': session.location
            }
        }), 200

    except Exception as e:
        logger.error(f"Register training session error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/training/compliance', methods=['GET'], endpoint='get_training_compliance')
@jwt_required
def get_training_compliance():
    """Get training compliance report"""
    try:
        user_id = user.id
        user = User.query.get(user_id)

        # Get required trainings for user's role
        required_trainings = Training.query.filter(
            Training.required_for_roles.isnot(None)
        ).all()

        required_trainings = [t for t in required_trainings 
                            if t.required_for_roles and user.role in json.loads(t.required_for_roles)]

        compliance_data = []
        total_required = len(required_trainings)
        completed_count = 0
        overdue_count = 0

        for training in required_trainings:
            # Get latest completion record
            latest_completion = TrainingRecord.query.filter_by(
                user_id=user_id,
                training_id=training.id,
                status='completed'
            ).order_by(TrainingRecord.completion_date.desc()).first()

            is_completed = latest_completion is not None
            is_compliant = is_completed

            # Check if training is current (not expired)
            if is_completed and training.frequency_days:
                next_due_date = latest_completion.completion_date + timedelta(days=training.frequency_days)
                is_compliant = datetime.utcnow() <= next_due_date
                is_overdue = datetime.utcnow() > next_due_date
            else:
                next_due_date = None
                is_overdue = False

            if is_completed:
                completed_count += 1
            if is_overdue:
                overdue_count += 1

            compliance_data.append({
                'training_id': training.id,
                'title': training.title,
                'training_type': training.training_type,
                'frequency_days': training.frequency_days,
                'is_completed': is_completed,
                'is_compliant': is_compliant,
                'is_overdue': is_overdue,
                'completion_date': latest_completion.completion_date.isoformat() if latest_completion else None,
                'score': latest_completion.score if latest_completion else None,
                'next_due_date': next_due_date.isoformat() if next_due_date else None,
                'days_until_due': (next_due_date.date() - datetime.utcnow().date()).days if next_due_date else None
            })

        compliance_rate = (completed_count / total_required * 100) if total_required > 0 else 100

        return jsonify({
            'compliance_summary': {
                'total_required': total_required,
                'completed': completed_count,
                'overdue': overdue_count,
                'compliance_rate': round(compliance_rate, 1),
                'current_rate': round(((completed_count - overdue_count) / total_required * 100), 1) if total_required > 0 else 100
            },
            'trainings': compliance_data,
            'user': {
                'id': user.id,
                'name': user.name,
                'role': user.role,
                'department': user.department
            }
        }), 200

    except Exception as e:
        logger.error(f"Get training compliance error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/teams/<int:team_id>/invite', methods=['POST'], endpoint='invite_to_team')
@jwt_required
def invite_to_team(team_id):
    """Invite user to team"""
    try:
        user_id = user.id
        data = request.get_json()

        email = data.get('email', '').lower().strip()
        role = data.get('role', 'member')

        # Verify user has permission to invite
        user_membership = TeamMember.query.filter_by(
            team_id=team_id, 
            user_id=user_id
        ).first()

        if not user_membership or user_membership.role not in ['owner', 'admin']:
            return jsonify({'error': 'Insufficient permissions to invite members'}), 403

        # Check if user exists
        invited_user = User.query.filter_by(email=email).first()
        if not invited_user:
            return jsonify({'error': 'User with this email not found'}), 404

        # Check if already a member
        existing_member = TeamMember.query.filter_by(
            team_id=team_id,
            user_id=invited_user.id
        ).first()

        if existing_member:
            return jsonify({'error': 'User is already a team member'}), 409

        # Check team size limits
        team_member_count = TeamMember.query.filter_by(team_id=team_id).count()
        team = Team.query.get(team_id)
        team_owner = User.query.get(team.created_by)
        max_members = PLANS.get(get_effective_plan(team_owner), {}).get('limits', {}).get('team_members', 1)

        if team_member_count >= max_members:
            return jsonify({
                'error': f'Team member limit reached for this team',
                'current_members': team_member_count,
                'max_members': max_members
            }), 403

        # Create invitation
        invitation_token = str(uuid.uuid4())
        invitation = TeamInvitation(
            team_id=team_id,
            user_id=invited_user.id,
            email=email,
            invited_by=user_id,
            token=invitation_token,
            role=role,
            expires_at=datetime.utcnow() + timedelta(days=7)
        )
        db.session.add(invitation)
        db.session.commit()

        # Send invitation email
        invitation_link = f"https://yourdomain.com/accept-invitation?token={invitation_token}"
        email_body = f"""
        <h2>Team Invitation</h2>
        <p>You have been invited to join the team <strong>{team.name}</strong> on SafetyTrack Pro.</p>
        <p>Role: {role.title()}</p>
        <p><a href="{invitation_link}" style="background: #2c5aa0; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px;">Accept Invitation</a></p>
        <p>This invitation will expire in 7 days.</p>
        """

        if send_email(email, f"Invitation to join {team.name} - SafetyTrack Pro", email_body):
            logger.info(f"Team invitation sent to {email}")
        else:
            logger.error(f"Failed to send team invitation to {email}")

        # Create notification for invited user
        create_notification(
            invited_user.id,
            "Team Invitation",
            f"You have been invited to join the team '{team.name}' as {role}",
            "info",
            "medium",
            f"/teams/invitations/{invitation_token}"
        )

        return jsonify({
            'message': 'Invitation sent successfully',
            'invitation': {
                'id': invitation.id,
                'email': email,
                'role': role,
                'expires_at': invitation.expires_at.isoformat()
            }
        }), 200

    except Exception as e:
        logger.error(f"Team invitation error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/subscriptions/current', methods=['GET'], endpoint='get_current_subscription')
@jwt_required
def get_current_subscription():
    """Get current subscription details"""
    try:
        user_id = user.id
        user = User.query.get(user_id)

        if not user:
            return jsonify({'error': 'User not found'}), 404

        # Get active subscription
        subscription = Subscription.query.filter_by(
            user_id=user_id,
            status='active'
        ).first()

        trial_active = user.trial_ends_at and datetime.utcnow() < user.trial_ends_at
        effective_plan = user.trial_plan if trial_active else user.plan

        # Get usage statistics
        current_month_start = datetime.utcnow().replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        
        uploads_used = Document.query.filter(
            Document.user_id == user_id,
            Document.uploaded_at >= current_month_start
        ).count()

        ai_requests_used = AIRequest.query.filter(
            AIRequest.user_id == user_id,
            AIRequest.created_at >= current_month_start
        ).count()

        camera_feeds_used = CameraFeed.query.filter_by(user_id=user_id).count()

        plan_limits = PLANS.get(effective_plan, {}).get('limits', {})
        plan_features = PLANS.get(effective_plan, {}).get('features', [])

        return jsonify({
            'current_plan': {
                'code': user.plan,
                'effective_plan': effective_plan,
                'label': PLANS.get(effective_plan, {}).get('label', 'Unknown'),
                'trial_active': trial_active,
                'trial_ends_at': user.trial_ends_at.isoformat() if user.trial_ends_at else None
            },
            'subscription': {
                'status': subscription.status if subscription else 'none',
                'start_date': subscription.start_date.isoformat() if subscription else None,
                'end_date': subscription.end_date.isoformat() if subscription else None,
                'auto_renew': subscription.auto_renew if subscription else False
            } if subscription else None,
            'usage': {
                'uploads': {
                    'used': uploads_used,
                    'limit': plan_limits.get('uploads_per_month', 0),
                    'percentage': min(100, (uploads_used / plan_limits.get('uploads_per_month', 1)) * 100) if plan_limits.get('uploads_per_month') != "Unlimited" else 0
                },
                'ai_requests': {
                    'used': ai_requests_used,
                    'limit': plan_limits.get('ai_requests_per_month', 0),
                    'percentage': min(100, (ai_requests_used / plan_limits.get('ai_requests_per_month', 1)) * 100) if plan_limits.get('ai_requests_per_month') != "Unlimited" else 0
                },
                'camera_feeds': {
                    'used': camera_feeds_used,
                    'limit': plan_limits.get('camera_feeds', 0),
                    'percentage': min(100, (camera_feeds_used / plan_limits.get('camera_feeds', 1)) * 100) if plan_limits.get('camera_feeds') != "Unlimited" else 0
                }
            },
            'features': plan_features,
            'pricing': get_pricing(user.country or 'default')
        }), 200

    except Exception as e:
        logger.error(f"Get subscription error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/subscriptions/upgrade', methods=['POST'], endpoint='upgrade_subscription')
@jwt_required
def upgrade_subscription():
    """Upgrade subscription plan with cache invalidation"""
    try:
        # ==================== GET USER FROM CACHE ====================
        user = request.user
        is_from_cache = getattr(request, 'is_from_cache', False)
        
        print(f"📈 Subscription upgrade requested by: {user.email} (ID: {user.id})")
        print(f"⚡ From cache: {is_from_cache}")
        
        # ==================== VALIDATE INPUT ====================
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400

        plan = data.get('plan')
        duration = data.get('duration')  # 1_month, 6_month, 1_year

        if not plan or not duration:
            return jsonify({'error': 'Plan and duration are required'}), 400

        if plan not in PLANS:
            return jsonify({'error': 'Invalid plan'}), 400

        if duration not in ['1_month', '6_month', '1_year']:
            return jsonify({'error': 'Invalid duration'}), 400

        # ==================== GET FRESH USER DATA ====================
        # Always get fresh user from database for subscription changes
        user = User.query.get(user.id)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        # ==================== GET PRICING ====================
        pricing = get_pricing(user.country or 'default')
        plan_pricing = pricing.get(plan, {})

        if plan_pricing.get(duration) == 'Custom':
            return jsonify({
                'message': 'Please contact us for enterprise pricing',
                'requires_contact': True,
                'contact_email': 'sales@safetytrack.com'
            }), 200

        amount = plan_pricing.get(duration, 0)
        currency = plan_pricing.get('currency', 'USD')

        # ==================== CREATE PAYMENT RECORD ====================
        payment = Payment(
            user_id=user.id,
            amount=amount,
            currency=currency,
            plan=plan,
            duration=duration,
            payment_method='pending',
            status='pending',
            transaction_id=f"UPG_{user.id}_{int(time.time())}"
        )
        db.session.add(payment)
        db.session.commit()

        # ==================== UPDATE USER SUBSCRIPTION ====================
        # Update user subscription details immediately
        user.subscription_plan = plan
        user.subscription_status = 'pending_payment'
        user.billing_cycle = duration
        user.subscription_starts_at = datetime.utcnow()
        user.subscription_ends_at = calculate_subscription_end(datetime.utcnow(), duration)
        
        # 🆕 INCREMENT TOKEN VERSION (force re-login)
        user.token_version = (user.token_version or 0) + 1
        
        # 🆕 UPDATE TIMESTAMP
        user.updated_at = datetime.utcnow()
        
        db.session.commit()

        # ==================== 🆕 CLEAR CACHE ====================
        UserCache.clear(user.id)
        print(f"✅ Cache cleared for user {user.id} after subscription upgrade")

        # ==================== LOG SUBSCRIPTION CHANGE ====================
        try:
            audit_log = AuditLog(
                user_id=user.id,
                action='subscription_upgrade',
                resource_type='subscription',
                resource_id=payment.id,
                details=json.dumps({
                    'old_plan': getattr(user, 'subscription_plan', None),
                    'new_plan': plan,
                    'duration': duration,
                    'amount': amount,
                    'currency': currency,
                    'payment_id': payment.id,
                    'from_cache': is_from_cache
                }),
                ip_address=request.remote_addr,
                user_agent=request.headers.get('User-Agent', '')
            )
            db.session.add(audit_log)
            db.session.commit()
            print(f"✅ Subscription upgrade logged for user {user.email}")
        except Exception as e:
            print(f"⚠️ Could not create audit log: {str(e)}")

        # ==================== RETURN RESPONSE ====================
        return jsonify({
            'success': True,
            'message': 'Subscription upgrade initiated',
            'payment_required': True,
            'payment_options': {
                'paystack': {
                    'available': PAYSTACK_AVAILABLE,
                    'method': 'Paystack (Card/Mobile Money)',
                    'instructions': 'Pay securely online with card or mobile money'
                },
                'manual': {
                    'available': True,
                    'method': 'Manual Transfer',
                    'account_details': plan_pricing.get('account_details', {})
                }
            },
            'payment_details': {
                'plan': plan,
                'duration': duration,
                'amount': amount,
                'currency': currency,
                'payment_id': payment.id
            },
            # 🆕 CACHE AND TOKEN INFO
            'subscription_update': {
                'token_version': user.token_version,
                'cache_cleared': True,
                'requires_re_login': True,
                'message': 'Please login again to refresh your session with the new subscription'
            }
        }), 200

    except Exception as e:
        logger.error(f"Upgrade subscription error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500


# ============== HELPER FUNCTIONS ==============
def get_team_performance_stats():
    """Get SafetyPro team performance statistics"""
    today = datetime.utcnow().date()
    one_week_ago = today - timedelta(days=7)
    
    # Get team members
    team_members = User.query.filter(
        (User.user_type.in_(['safetypro', 'system', 'platform_owner'])) |
        (User.admin_role == 'safetypro')
    ).filter_by(is_active=True).all()
    
    team_stats = []
    for member in team_members:
        # Count approvals in last 7 days
        approvals = AdminApprovalLog.query.filter_by(
            approved_by=member.id,
            action='approved'
        ).filter(
            AdminApprovalLog.created_at >= one_week_ago
        ).count()
        
        # Average approval time for this member
        avg_time_result = db.session.query(
            func.avg(func.extract('epoch', AdminApprovalLog.created_at - User.created_at))
        ).join(User, AdminApprovalLog.user_id == User.id
        ).filter(
            AdminApprovalLog.approved_by == member.id,
            AdminApprovalLog.action == 'approved',
            AdminApprovalLog.created_at >= one_week_ago
        ).scalar()
        
        avg_time_hours = round(avg_time_result / 3600, 2) if avg_time_result else 0
        
        team_stats.append({
            'id': member.id,
            'name': member.name,
            'email': member.email,
            'role': member.user_type,
            'approvals_last_7_days': approvals,
            'avg_approval_time_hours': avg_time_hours,
            'is_online': is_user_online(member.id)
        })
    
    # Calculate team totals
    total_approvals = sum(stat['approvals_last_7_days'] for stat in team_stats)
    avg_approval_time = sum(stat['avg_approval_time_hours'] for stat in team_stats) / len(team_stats) if team_stats else 0
    
    return {
        'team_members': team_stats,
        'total_approvals': total_approvals,
        'avg_approval_time_hours': round(avg_approval_time, 2),
        'team_size': len(team_stats),
        'online_count': sum(1 for stat in team_stats if stat['is_online'])
    }

def get_approval_trends(days=30):
    """Get approval trends for the last N days"""
    end_date = datetime.utcnow().date()
    start_date = end_date - timedelta(days=days)
    
    trends = []
    current_date = start_date
    
    while current_date <= end_date:
        next_date = current_date + timedelta(days=1)
        
        # Count approvals
        approvals = User.query.filter_by(approval_status='approved').filter(
            func.date(User.approved_at) == current_date
        ).count()
        
        # Count pending
        pending = User.query.filter_by(approval_status='pending').filter(
            func.date(User.created_at) == current_date
        ).count()
        
        # Count rejections
        rejections = User.query.filter_by(approval_status='rejected').filter(
            func.date(User.rejected_at) == current_date
        ).count()
        
        trends.append({
            'date': current_date.isoformat(),
            'approvals': approvals,
            'pending': pending,
            'rejections': rejections,
            'total': approvals + pending + rejections
        })
        
        current_date = next_date
    
    return trends

def get_pending_by_type():
    """Get pending users grouped by type"""
    pending_users = User.query.filter_by(approval_status='pending').all()
    
    by_type = {}
    for user in pending_users:
        user_type = user.user_type or 'unknown'
        if user_type not in by_type:
            by_type[user_type] = []
        
        days_waiting = (datetime.utcnow() - user.created_at).days if user.created_at else 0
        
        by_type[user_type].append({
            'id': user.id,
            'name': user.name,
            'email': user.email,
            'days_waiting': days_waiting,
            'subscription_plan': user.subscription_plan,
            'created_at': user.created_at.isoformat() if user.created_at else None
        })
    
    # Sort each group by days waiting (descending)
    for user_type in by_type:
        by_type[user_type].sort(key=lambda x: x['days_waiting'], reverse=True)
    
    return by_type

def get_urgent_cases():
    """Get urgent approval cases (waiting > 3 days or custom plan)"""
    urgent_cases = []
    pending_users = User.query.filter_by(approval_status='pending').all()
    
    for user in pending_users:
        days_waiting = (datetime.utcnow() - user.created_at).days if user.created_at else 0
        
        # Criteria for urgency
        is_urgent = (
            days_waiting > 3 or  # Waiting more than 3 days
            user.subscription_plan == 'custom' or  # Custom subscription
            user.employee_count > 100 or  # Large company
            (hasattr(user, 'company_size') and user.company_size == 'enterprise')  # Enterprise
        )
        
        if is_urgent:
            urgent_cases.append({
                'id': user.id,
                'name': user.name,
                'email': user.email,
                'days_waiting': days_waiting,
                'subscription_plan': user.subscription_plan,
                'company_name': user.company_name,
                'employee_count': user.employee_count,
                'reason': 'Long wait time' if days_waiting > 3 else 'Enterprise account',
                'priority': 'high' if days_waiting > 5 else 'medium',
                'created_at': user.created_at.isoformat() if user.created_at else None
            })
    
    # Sort by priority and days waiting
    urgent_cases.sort(key=lambda x: (x['priority'] == 'high', x['days_waiting']), reverse=True)
    
    return urgent_cases

def is_user_online(user_id):
    """Check if user is currently online (simple implementation)"""
    # Check if user has recent activity (last 5 minutes)
    recent_activity = UserActivityLog.query.filter_by(
        user_id=user_id
    ).order_by(
        UserActivityLog.timestamp.desc()
    ).first()
    
    if recent_activity:
        time_diff = datetime.utcnow() - recent_activity.timestamp
        return time_diff.total_seconds() < 300  # 5 minutes
    
    return False

def can_mass_approve():
    """Check if mass approval is possible"""
    # Check if there are pending users with uploaded documents
    pending_with_docs = User.query.filter_by(
        approval_status='pending'
    ).filter(
        User.documents_uploaded == True
    ).count()
    
    return pending_with_docs > 5  # Allow mass approve if more than 5 users have documents

def get_admin_name(admin_id):
    """Get admin name by ID"""
    if not admin_id:
        return 'System'
    
    admin = User.query.get(admin_id)
    return admin.name if admin else f'Admin #{admin_id}'


 


@app.route('/api/debug/check-jwt', methods=['GET'])
def debug_check_jwt():
    """Debug endpoint to check JWT token"""
    auth_header = request.headers.get('Authorization')
    
    debug_info = {
        'has_auth_header': bool(auth_header),
        'auth_header': auth_header,
        'headers_received': dict(request.headers),
        'local_storage': {}
    }
    
    if auth_header:
        debug_info['starts_with_bearer'] = auth_header.startswith('Bearer ')
        if auth_header.startswith('Bearer '):
            token = auth_header[7:]
            debug_info['token_length'] = len(token)
            debug_info['token_preview'] = token[:50] + '...' if len(token) > 50 else token
            debug_info['has_three_parts'] = len(token.split('.')) == 3
            
            # Try to decode payload (without verification)
            try:
                import base64
                import json
                parts = token.split('.')
                if len(parts) == 3:
                    payload_b64 = parts[1]
                    payload_b64 += '=' * ((4 - len(payload_b64) % 4) % 4)
                    payload_json = base64.b64decode(payload_b64).decode('utf-8')
                    payload_data = json.loads(payload_json)
                    debug_info['payload'] = payload_data
            except Exception as e:
                debug_info['decode_error'] = str(e)
    
    return jsonify({
        'success': True,
        'debug': debug_info,
        'message': 'JWT Debug Info'
    }), 200

