@app.route('/api/safetypro/dashboard', methods=['GET'])
@safetypro_required
def safetypro_dashboard():
    """SafetyPro dashboard with optimized queries and robust error handling"""
    try:
        current_user = request.user
        # Use app.logger for consistent logging
        app.logger.info(f"Dashboard accessed by {current_user.email} ({current_user.user_type}) from IP {request.remote_addr}")

        today = datetime.utcnow().date()
        one_week_ago = today - timedelta(days=7)
        one_month_ago = today - timedelta(days=30)

        # ========== OPTIMIZED DATABASE QUERIES ==========
        # Use single queries with conditional aggregation to reduce database load
        stats_subquery = db.session.query(
            func.sum(case((User.approval_status == 'approved', 1), else_=0)).label('total_approved'),
            func.sum(case((User.approval_status == 'pending', 1), else_=0)).label('total_pending'),
            func.sum(case((User.approval_status == 'rejected', 1), else_=0)).label('total_rejected'),
            func.count(User.id).label('total_users'),
            func.sum(case((User.is_active == True, 1), else_=0)).label('active_users')
        ).subquery()

        # Get today's approvals efficiently
        approved_today_subq = db.session.query(
            func.count(User.id).label('count')
        ).filter(
            User.approval_status == 'approved',
            func.date(User.approved_at) == today
        ).subquery()

        # Get time-based approvals
        time_based_approvals = db.session.query(
            func.sum(case((
                User.approval_status == 'approved',
                case((func.date(User.approved_at) == today, 1), else_=0)
            ), else_=0)).label('approved_today'),
            func.sum(case((
                User.approval_status == 'approved',
                case((User.approved_at >= one_week_ago, 1), else_=0)
            ), else_=0)).label('approved_weekly'),
            func.sum(case((
                User.approval_status == 'approved',
                case((User.approved_at >= one_month_ago, 1), else_=0)
            ), else_=0)).label('approved_monthly')
        ).first()

        # Execute all main queries in one go
        main_stats = db.session.query(stats_subquery).first()
        approved_today = db.session.query(approved_today_subq).scalar() or 0

        # ========== CALCULATE METRICS ==========
        total_approved = main_stats.total_approved or 0
        total_pending = main_stats.total_pending or 0
        total_rejected = main_stats.total_rejected or 0
        total_users = main_stats.total_users or 0
        active_users = main_stats.active_users or 0

        # Calculate conversion rate safely
        total_processed = total_approved + total_rejected
        conversion_rate = 0
        if total_processed > 0:
            conversion_rate = round((total_approved / total_processed) * 100, 2)

        # Calculate average approval time (efficient batch calculation)
        avg_approval_time = calculate_avg_approval_time_batch()

        # ========== FETCH DETAILED LISTS ==========
        # Recent approvals (limited, ordered)
        recent_approvals = User.query.filter_by(approval_status='approved')\
            .order_by(User.approved_at.desc())\
            .limit(10)\
            .all()

        # Pending users with documents check
        pending_users = User.query\
            .filter_by(approval_status='pending')\
            .order_by(User.created_at.desc())\
            .limit(5)\
            .all()

        # Pending by plan distribution
        pending_by_plan_query = db.session.query(
            User.subscription_plan,
            func.count(User.id).label('count')
        ).filter(
            User.approval_status == 'pending'
        ).group_by(User.subscription_plan).all()
        
        pending_by_plan = {plan: count for plan, count in pending_by_plan_query}

        # Users by type distribution
        users_by_type_query = db.session.query(
            User.user_type,
            func.count(User.id).label('count')
        ).filter(User.user_type.in_(['user', 'admin', 'safetypro', 'system', 'platform_owner']))\
         .group_by(User.user_type).all()
        
        users_by_type = {user_type: count for user_type, count in users_by_type_query if count > 0}

        # ========== ADDED: PLAN DISTRIBUTION ==========
        # Get plan distribution across all users
        plan_distribution_query = db.session.query(
            User.subscription_plan,
            func.count(User.id).label('count')
        ).filter(
            User.subscription_plan.isnot(None)
        ).group_by(User.subscription_plan).all()

        plan_distribution = {}
        for plan, count in plan_distribution_query:
            plan_distribution[plan] = count

        # Get counts for each plan type (for charts)
        plan_stats = {
            'free': User.query.filter_by(subscription_plan='free').count(),
            'basic': User.query.filter_by(subscription_plan='basic').count(),
            'pro': User.query.filter_by(subscription_plan='pro').count(),
            'professional': User.query.filter_by(subscription_plan='professional').count(),
            'enterprise': User.query.filter_by(subscription_plan='enterprise').count(),
            'custom': User.query.filter_by(subscription_plan='custom').count(),
            'custom_enterprise': User.query.filter_by(subscription_plan='custom_enterprise').count(),
            'platform_owner': User.query.filter_by(subscription_plan='platform_owner').count(),
            'platform_admin': User.query.filter_by(subscription_plan='platform_admin').count()
        }

        # Get approved by plan (for conversion rates)
        approved_by_plan = {}
        for plan in plan_stats.keys():
            approved_by_plan[plan] = User.query.filter_by(
                subscription_plan=plan,
                approval_status='approved'
            ).count()

        # Recent activity logs
        recent_activity = ActivityLog.query\
            .order_by(ActivityLog.timestamp.desc())\
            .limit(10)\
            .all()

        # ========== BUILD RESPONSE ==========
        dashboard_data = {
            'summary': {
                'total_users': total_users,
                'active_users': active_users,
                'pending_approvals': total_pending,
                'approved_today': time_based_approvals.approved_today or 0,
                'approved_weekly': time_based_approvals.approved_weekly or 0,
                'approved_monthly': time_based_approvals.approved_monthly or 0,
                'conversion_rate': conversion_rate,
                'avg_approval_time_hours': avg_approval_time,
                'total_approved': total_approved,
                'total_rejected': total_rejected
            },
            'recent_approvals': [{
                'id': user.id,
                'name': user.name,
                'email': user.email,
                'user_type': user.user_type,
                'subscription_plan': user.subscription_plan,
                'approved_at': user.approved_at.isoformat() if user.approved_at else None,
                'company_name': user.company_name,
                'time_to_approval_hours': calculate_hours_difference(user.created_at, user.approved_at) if user.created_at and user.approved_at else None
            } for user in recent_approvals],
            'pending_users': [{
                'id': user.id,
                'email': user.email,
                'name': user.name,
                'user_type': user.user_type,
                'created_at': user.created_at.isoformat() if user.created_at else None,
                'documents_uploaded': getattr(user, 'documents_uploaded', False),
                'subscription_plan': user.subscription_plan,
                'days_waiting': (datetime.utcnow() - user.created_at).days if user.created_at else 0,
                'priority_score': calculate_priority_score(user)
            } for user in pending_users],
            'users_by_type': users_by_type,
            # ========== ADDED PLAN DISTRIBUTION DATA ==========
            'plan_distribution': plan_distribution,
            'plan_stats': plan_stats,
            'approved_by_plan': approved_by_plan,
            'pending_by_plan': pending_by_plan,
            'recent_activity': [{
                'id': activity.id,
                'user_id': activity.user_id,
                'activity_type': activity.activity_type,
                'description': activity.description,
                'timestamp': activity.timestamp.isoformat() if activity.timestamp else None,
                'severity': get_activity_severity(activity.activity_type)
            } for activity in recent_activity],
            'pending_distribution': {
                'by_plan': pending_by_plan,
                'total': total_pending,
                'percentage_by_plan': {
                    plan: round((count / total_pending * 100), 2) if total_pending > 0 else 0
                    for plan, count in pending_by_plan.items()
                }
            }
        }

        app.logger.debug(f"Dashboard data prepared successfully for {current_user.email}")

        return jsonify({
            'success': True,
            'message': 'SafetyPro dashboard loaded successfully',
            'code': 'DASHBOARD_LOADED',
            'user': {
                'id': current_user.id,
                'email': current_user.email,
                'name': current_user.name,
                'user_type': current_user.user_type,
                'admin_role': getattr(current_user, 'admin_role', None),
                'admin_level': getattr(current_user, 'admin_level', None)
            },
            'dashboard': dashboard_data,
            'metadata': {
                'generated_at': datetime.utcnow().isoformat(),
                'data_freshness_seconds': 0,  # Real-time data
                'cache_status': 'disabled'
            }
        }), 200

    except Exception as e:
        # Use structured error handling
        app.logger.error(f"Dashboard error for user {getattr(current_user, 'email', 'unknown')}: {str(e)}", 
                        exc_info=True, 
                        extra={'ip_address': request.remote_addr})
        
        return jsonify({
            'success': False,
            'error': 'Failed to load dashboard',
            'code': 'DASHBOARD_ERROR',
            'message': 'An internal error occurred while loading the dashboard data.',
            'timestamp': datetime.utcnow().isoformat()
        }), 500


# Helper function for the dashboard
def calculate_avg_approval_time_batch():
    """Efficiently calculate average approval time for all approved users"""
    try:
        # Single query to calculate average in database
        result = db.session.query(
            func.avg(
                func.extract('epoch', User.approved_at - User.created_at) / 3600.0
            ).label('avg_hours')
        ).filter(
            User.approval_status == 'approved',
            User.approved_at.isnot(None),
            User.created_at.isnot(None)
        ).scalar()
        
        return round(result or 0, 2)
    except Exception:
        return 0

def calculate_hours_difference(start_time, end_time):
    """Calculate hours difference between two datetimes"""
    if start_time and end_time:
        diff = end_time - start_time
        return round(diff.total_seconds() / 3600, 2)
    return None

def calculate_priority_score(user):
    """Calculate priority score for pending user"""
    score = 0
    # Days waiting (max 50 points)
    if user.created_at:
        days_waiting = (datetime.utcnow() - user.created_at).days
        score += min(days_waiting * 5, 50)
    
    # Subscription plan weight
    plan_weights = {'custom_enterprise': 30, 'custom': 25, 'professional': 20, 'pro': 15, 'free': 10}
    score += plan_weights.get(user.subscription_plan, 10)
    
    # Documents uploaded
    if getattr(user, 'documents_uploaded', False):
        score += 20
    
    return min(score, 100)

def get_activity_severity(activity_type):
    """Determine severity level for activity"""
    if 'error' in activity_type or 'failed' in activity_type:
        return 'error'
    elif 'warning' in activity_type:
        return 'warning'
    elif 'approval' in activity_type or 'verified' in activity_type:
        return 'success'
    else:
        return 'info'
