@app.route('/api/safetypro/dashboard/recent-activity', methods=['GET'])
@safetypro_required
def safetypro_dashboard_recent_activity():
    """Get recent team activity - SECURED WITH JWT"""
    try:
        # Get current admin from JWT authentication
        current_user = request.user
        print(f"👤 Admin accessing recent activity: {current_user.name}")
        
        # Check if user has SafetyPro access
        if not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Access restricted to SafetyPro system administrators',
                'code': 'ACCESS_DENIED'
            }), 403
        
        # Get limit parameter
        limit = request.args.get('limit', 20, type=int)
        limit = min(limit, 100)  # Cap at 100 for performance
        show_all = request.args.get('show_all', 'false').lower() == 'true'
        
        print(f"📋 Recent activity request - Limit: {limit}, Show all: {show_all}")
        
        # Build query
        query = AdminApprovalLog.query
        
        # If not showing all, filter by recent time
        if not show_all:
            one_week_ago = datetime.utcnow() - timedelta(days=7)
            query = query.filter(AdminApprovalLog.created_at >= one_week_ago)
        
        # Execute query
        recent_activity = query\
            .order_by(AdminApprovalLog.created_at.desc())\
            .limit(limit)\
            .all()
        
        print(f"📊 Retrieved {len(recent_activity)} activity records")
        
        # Process activity data
        activity_data = []
        for activity in recent_activity:
            try:
                user = User.query.get(activity.user_id)
                admin = User.query.get(activity.approved_by)
                
                activity_item = {
                    'id': activity.id,
                    'user': {
                        'id': user.id if user else None,
                        'name': user.name if user else 'Unknown User',
                        'email': user.email if user else None,
                        'user_type': user.user_type if user else None,
                        'subscription_plan': user.subscription_plan if user else None
                    },
                    'action': activity.action,
                    'status': activity.new_status,
                    'admin': {
                        'id': admin.id if admin else None,
                        'name': admin.name if admin else 'System',
                        'email': admin.email if admin else None
                    },
                    'notes': activity.notes,
                    'timestamp': activity.created_at.isoformat() if activity.created_at else None,
                    'time_ago': get_time_ago(activity.created_at) if activity.created_at else None,
                    'ip_address': activity.ip_address,
                    'user_agent': activity.user_agent
                }
                
                # Add additional info for approvals
                if activity.action == 'approved' and user:
                    # Calculate time to approval
                    if user.created_at and user.approved_at:
                        time_to_approval = (user.approved_at - user.created_at).total_seconds() / 3600  # hours
                        activity_item['time_to_approval_hours'] = round(time_to_approval, 2)
                
                activity_data.append(activity_item)
                
            except Exception as e:
                logger.error(f"❌ Error processing activity {activity.id}: {e}")
                # Add minimal activity data
                activity_data.append({
                    'id': activity.id,
                    'action': activity.action,
                    'status': activity.new_status,
                    'timestamp': activity.created_at.isoformat() if activity.created_at else None,
                    'error': 'Error loading activity details'
                })
        
        # Get additional activity types if available
        other_activities = []
        try:
            # Get recent user registrations
            recent_users = User.query\
                .order_by(User.created_at.desc())\
                .limit(5)\
                .all()
            
            for user in recent_users:
                other_activities.append({
                    'type': 'user_registration',
                    'user': {
                        'id': user.id,
                        'name': user.name,
                        'email': user.email
                    },
                    'timestamp': user.created_at.isoformat() if user.created_at else None,
                    'time_ago': get_time_ago(user.created_at) if user.created_at else None,
                    'status': user.approval_status
                })
        except Exception as e:
            print(f"⚠️ Error loading recent users: {e}")
        
        # Create audit log
        audit_log = ActivityLog(
            user_id=current_user.id,
            activity_type='admin_view_recent_activity',
            description=f'Viewed {len(activity_data)} recent activities',
            ip_address=request.remote_addr,
            activity_data={
                'limit': limit,
                'show_all': show_all,
                'activity_count': len(activity_data),
                'other_activities_count': len(other_activities)
            }
        )
        db.session.add(audit_log)
        db.session.commit()
        
        print(f"✅ Recent activity loaded successfully")
        
        return jsonify({
            'success': True,
            'message': 'Recent activity retrieved successfully',
            'code': 'RECENT_ACTIVITY_RETRIEVED',
            'recent_activity': activity_data,
            'other_activities': other_activities,
            'count': len(activity_data),
            'summary': {
                'approvals_today': AdminApprovalLog.query.filter_by(
                    action='approved'
                ).filter(
                    func.date(AdminApprovalLog.created_at) == datetime.utcnow().date()
                ).count(),
                'rejections_today': AdminApprovalLog.query.filter_by(
                    action='rejected'
                ).filter(
                    func.date(AdminApprovalLog.created_at) == datetime.utcnow().date()
                ).count(),
                'total_actions_today': AdminApprovalLog.query.filter(
                    func.date(AdminApprovalLog.created_at) == datetime.utcnow().date()
                ).count()
            },
            'accessed_by': {
                'admin_id': current_user.id,
                'admin_name': current_user.name,
                'admin_email': current_user.email
            },
            'timestamp': datetime.utcnow().isoformat(),
            'audit_log_id': audit_log.id
        }), 200
        
    except Exception as e:
        logger.error(f"❌ Recent activity error: {str(e)}")
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Failed to load recent activity',
            'code': 'INTERNAL_ERROR',
            'message': 'An error occurred while loading recent activity'
        }), 500
# ============== HELPER FUNCTIONS FOR METRICS ==============
def calculate_approval_efficiency():
    """Calculate overall approval efficiency"""
    # Calculate based on approval times
    fast_approvals = User.query.filter_by(approval_status='approved').filter(
        (User.approved_at - User.created_at) <= timedelta(hours=24)
    ).count()
    
    total_approvals = User.query.filter_by(approval_status='approved').count()
    
    return round((fast_approvals / total_approvals * 100), 2) if total_approvals > 0 else 0

def calculate_team_productivity():
    """Calculate team productivity score"""
    team_stats = get_team_performance_stats()
    avg_approvals = team_stats.get('total_approvals', 0) / 7 if team_stats.get('team_size', 0) > 0 else 0
    
    # Scale to 0-100
    productivity = min(100, (avg_approvals / 15) * 100)  # Target: 15 approvals per team member per week
    return round(productivity, 2)

def calculate_sla_compliance():
    """Calculate SLA compliance percentage"""
    sla_compliant = User.query.filter_by(approval_status='approved').filter(
        (User.approved_at - User.created_at) <= timedelta(hours=48)
    ).count()
    
    total_approvals = User.query.filter_by(approval_status='approved').count()
    
    return round((sla_compliant / total_approvals * 100), 2) if total_approvals > 0 else 0


def calculate_response_time_score(admin_id):
    """Calculate response time score"""
    avg_time_result = db.session.query(
        func.avg(func.extract('epoch', AdminApprovalLog.created_at - User.created_at))
    ).join(User, AdminApprovalLog.user_id == User.id
    ).filter(
        AdminApprovalLog.approved_by == admin_id,
        AdminApprovalLog.action == 'approved'
    ).scalar()
    
    avg_hours = avg_time_result / 3600 if avg_time_result else 0
    
    # Score based on response time (lower is better)
    if avg_hours <= 1:
        return 100
    elif avg_hours <= 24:
        return 80
    elif avg_hours <= 48:
        return 60
    elif avg_hours <= 72:
        return 40
    else:
        return 20

def get_time_ago(timestamp):
    """Get human-readable time ago string"""
    if not timestamp:
        return "Unknown"
    
    now = datetime.utcnow()
    diff = now - timestamp
    
    if diff.days > 0:
        return f"{diff.days} day{'s' if diff.days > 1 else ''} ago"
    elif diff.seconds > 3600:
        hours = diff.seconds // 3600
        return f"{hours} hour{'s' if hours > 1 else ''} ago"
    elif diff.seconds > 60:
        minutes = diff.seconds // 60
        return f"{minutes} minute{'s' if minutes > 1 else ''} ago"
    else:
        return "Just now"

def calculate_approval_priority(user):
    """
    Calculate priority score for approval - RETURNS INTEGER
    """
    priority_score = 0
    
    # Custom plan gets higher priority
    if user.subscription_plan == 'custom':
        priority_score += 10
    
    # ✅ SAFE: Large company gets higher priority
    employee_count = getattr(user, 'employee_count', 0)
    if employee_count:
        try:
            # Convert to int if it's a string
            if isinstance(employee_count, str):
                employee_count = int(float(employee_count))
            
            if isinstance(employee_count, (int, float)):
                if employee_count > 100:
                    priority_score += 5
                elif employee_count > 10:
                    priority_score += 2
        except (ValueError, TypeError):
            pass
    
    # Verified email
    if user.verified:
        priority_score += 3
    
    # Waiting time
    if user.created_at:
        try:
            days_waiting = (datetime.utcnow() - user.created_at).days
            if days_waiting > 3:
                priority_score += 2
            if days_waiting > 7:
                priority_score += 3
        except:
            pass
    
    # ✅ Return INTEGER score
    return priority_score


def get_priority_level(priority_score):
    """
    Convert priority score to level string
    """
    # ✅ Ensure priority_score is an integer
    try:
        priority_score = int(priority_score)
    except (ValueError, TypeError):
        priority_score = 0
    
    if priority_score >= 8:
        return 'high'
    elif priority_score >= 4:
        return 'medium'
    else:
        return 'low'


def calculate_average_days_waiting(approvals):
    """
    Calculate average days waiting from approvals list
    """
    if not approvals:
        return 0
    
    total_days = 0
    count = 0
    for approval in approvals:
        days_waiting = approval.get('days_waiting')
        # ✅ Safe handling
        if days_waiting is not None:
            try:
                total_days += int(days_waiting)
                count += 1
            except (ValueError, TypeError):
                pass
    
    return round(total_days / count, 1) if count > 0 else 0


def calculate_subscription_value(user):
    """
    Calculate estimated subscription value
    """
    plan_pricing = {
        'enterprise': 299,
        'business': 199,
        'pro': 99,
        'basic': 49,
        'free': 0,
        'custom': 500
    }
    
    subscription_plan = getattr(user, 'subscription_plan', 'free')
    
    # ✅ Ensure plan is a string
    if subscription_plan is None:
        subscription_plan = 'free'
    subscription_plan = str(subscription_plan)
    
    base_price = plan_pricing.get(subscription_plan, 0)
    
    # Add multiplier for employee count
    employee_count = getattr(user, 'employee_count', 0)
    multiplier = 1.0
    
    if employee_count:
        try:
            if isinstance(employee_count, str):
                employee_count = int(float(employee_count))
            
            if isinstance(employee_count, (int, float)):
                if employee_count > 100:
                    multiplier = 2.5
                elif employee_count > 50:
                    multiplier = 2.0
                elif employee_count > 10:
                    multiplier = 1.5
        except (ValueError, TypeError):
            pass
    
    # ✅ Ensure base_price is a number
    try:
        base_price = float(base_price)
    except (ValueError, TypeError):
        base_price = 0
    
    return round(base_price * multiplier, 2)


def calculate_user_risk_score(user_id):
    """
    Calculate risk score for user - RETURNS INTEGER
    """
    try:
        user = User.query.get(user_id)
        if not user:
            return 50
        
        risk_score = 50
        
        # Higher risk for custom plans
        if user.subscription_plan == 'custom':
            risk_score += 20
        
        # ✅ SAFE: Risk based on employee count
        employee_count = getattr(user, 'employee_count', 0)
        if employee_count:
            try:
                if isinstance(employee_count, str):
                    employee_count = int(float(employee_count))
                
                if isinstance(employee_count, (int, float)):
                    if employee_count > 1000:
                        risk_score += 15
            except:
                pass
        
        # Risk based on documents
        if not getattr(user, 'documents_uploaded', False):
            risk_score += 20
        
        if not getattr(user, 'documents_verified', False):
            risk_score += 15
        
        # Risk based on verification status
        if not user.verified:
            risk_score += 10
        
        # ✅ Ensure integer
        return min(int(risk_score), 100)
    except:
        return 50

def get_last_user_activity(user_id):
    """Get last activity timestamp for user"""
    try:
        user = User.query.get(user_id)
        if not user:
            return None
        
        # Use last_login if available
        if user.last_login:
            days_ago = (datetime.utcnow() - user.last_login).days
            
            activity_data = {
                'type': 'login',
                'timestamp': user.last_login.isoformat(),
                'days_ago': days_ago,
                'status': 'active' if days_ago <= 7 else 'inactive' if days_ago <= 30 else 'dormant'
            }
            
            if user.last_activity:
                activity_data['type'] = 'general_activity'
                activity_data['last_activity'] = user.last_activity.isoformat()
            
            return activity_data
        
        return {
            'type': 'no_activity',
            'timestamp': None,
            'days_ago': None,
            'status': 'never_active'
        }
        
    except Exception as e:
        print(f"⚠️ Error getting last activity for user {user_id}: {e}")
        return None

def count_by_field(items, field_name):
    """Count items grouped by a specific field"""
    counts = {}
    for item in items:
        value = item.get(field_name, 'unknown')
        # Convert to string for counting
        if value is None:
            value = 'unknown'
        elif not isinstance(value, str):
            value = str(value)
        counts[value] = counts.get(value, 0) + 1
    return counts


