@app.route('/api/admin/payments/manual', methods=['GET'])
@safetypro_required
def get_manual_payments():
    """Get all manual payments with filters - SECURED WITH JWT"""
    try:
        # Get current admin from JWT authentication
        current_user = request.user
        app.logger.info(f"Fetching manual payments for {current_user.email}")
        
        # Check if user has SafetyPro access
        if not request.is_system_team:
            app.logger.warning(f"Access denied: User {current_user.email} is not SafetyPro team")
            return jsonify({
                'success': False,
                'error': 'Access restricted to SafetyPro system administrators',
                'code': 'ACCESS_DENIED'
            }), 403
        
        # Get query parameters
        status = request.args.get('status', 'all')
        payment_method = request.args.get('payment_method', 'all')
        plan = request.args.get('plan', 'all')
        search = request.args.get('search', '')
        from_date = request.args.get('from', None)
        to_date = request.args.get('to', None)
        page = int(request.args.get('page', 1))
        per_page = int(request.args.get('per_page', 20))
        
        # Build query on ManualPayment table
        query = ManualPayment.query
        
        # ✅ Map status filter to correct database values
        if status != 'all':
            status_map = {
                'pending': 'pending_verification',
                'pending_verification': 'pending_verification',
                'verified': 'verified',
                'completed': 'verified',
                'rejected': 'rejected',
                'all': 'all'
            }
            db_status = status_map.get(status, status)
            if db_status != 'all':
                query = query.filter(ManualPayment.status == db_status)
        
        if payment_method != 'all':
            query = query.filter(ManualPayment.payment_method == payment_method)
        if plan != 'all':
            query = query.filter(ManualPayment.plan == plan)
        if search:
            query = query.filter(
                db.or_(
                    ManualPayment.payment_reference.ilike(f'%{search}%'),
                    ManualPayment.transaction_id.ilike(f'%{search}%'),
                    ManualPayment.user.has(User.email.ilike(f'%{search}%')),
                    ManualPayment.user.has(User.name.ilike(f'%{search}%'))
                )
            )
        if from_date:
            query = query.filter(ManualPayment.created_at >= from_date)
        if to_date:
            query = query.filter(ManualPayment.created_at <= to_date)
        
        # Order by created_at descending
        query = query.order_by(ManualPayment.created_at.desc())
        
        # Paginate
        paginated = query.paginate(page=page, per_page=per_page, error_out=False)
        
        # Build response
        payments = []
        for payment in paginated.items:
            payments.append({
                'id': payment.id,
                'payment_reference': payment.payment_reference,
                'transaction_id': payment.transaction_id,
                'payment_method': payment.payment_method,
                'amount': payment.amount,
                'currency': payment.currency,
                'plan': payment.plan,
                'status': payment.status,
                'user_notes': payment.user_notes,
                'admin_notes': payment.admin_notes,
                'receipt_url': getattr(payment, 'receipt_url', None),
                'created_at': payment.created_at.isoformat() if payment.created_at else None,
                'updated_at': payment.updated_at.isoformat() if payment.updated_at else None,
                'verified_at': payment.verified_at.isoformat() if hasattr(payment, 'verified_at') and payment.verified_at else None,
                'expires_at': payment.expires_at.isoformat() if payment.expires_at else None,
                'user': {
                    'id': payment.user.id,
                    'name': payment.user.name,
                    'email': payment.user.email,
                    'phone': getattr(payment.user, 'phone', None),
                    'company_name': getattr(payment.user, 'company_name', None),
                    'subscription_plan': getattr(payment.user, 'subscription_plan', 'free'),
                    'is_active': getattr(payment.user, 'is_active', True),
                    'created_at': payment.user.created_at.isoformat() if payment.user.created_at else None
                } if payment.user else None
            })
        
        # Create audit log
        try:
            audit_log = ActivityLog(
                user_id=current_user.id,
                activity_type='admin_view_manual_payments',
                description=f'Viewed {len(payments)} manual payments',
                ip_address=request.remote_addr,
                activity_data={
                    'filters': {
                        'status': status,
                        'payment_method': payment_method,
                        'plan': plan,
                        'search': search,
                        'from_date': from_date,
                        'to_date': to_date
                    },
                    'total_count': paginated.total,
                    'returned_count': len(payments)
                }
            )
            db.session.add(audit_log)
            db.session.commit()
        except Exception as e:
            app.logger.warning(f"Audit log error: {e}")
        
        return jsonify({
            'success': True,
            'payments': payments,
            'pagination': {
                'page': page,
                'per_page': per_page,
                'total': paginated.total,
                'pages': paginated.pages
            }
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error fetching manual payments: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e),
            'message': 'Failed to fetch manual payments'
        }), 500


@app.route('/api/admin/payments/<int:payment_id>/verify', methods=['POST'])
@safetypro_required
def verify_manual_payment(payment_id):
    """Verify a manual payment - also updates company plan"""
    try:
        current_user = request.user
        app.logger.info(f"Verifying payment {payment_id} by {current_user.email}")
        
        if not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Access restricted to SafetyPro system administrators',
                'code': 'ACCESS_DENIED'
            }), 403
        
        data = request.get_json() or {}
        
        # Find payment
        payment = ManualPayment.query.get(payment_id)
        if not payment:
            return jsonify({'success': False, 'error': 'Payment not found'}), 404
        
        if payment.status == 'verified':
            return jsonify({'success': False, 'error': 'Payment already verified'}), 400
        
        # Update payment status
        payment.status = 'verified'
        payment.verified_at = datetime.utcnow()
        payment.admin_notes = data.get('notes', '') or payment.admin_notes
        payment.verified_by = current_user.id
        
        # ✅ Get user
        user = payment.user
        if user:
            # Get duration
            duration = getattr(payment, 'duration', '1_month')
            expiry_date = calculate_expiry_date_from_duration(duration)
            plan = payment.plan
            
            # ✅ UPDATE USER'S PLAN
            user.subscription_plan = plan
            user.subscription_status = 'active'
            user.billing_cycle = duration
            user.subscription_ends_at = expiry_date
            user.last_payment_date = datetime.utcnow()
            user.is_active = True
            
            # ✅ UPDATE COMPANY'S PLAN (if user has a company)
            if user.company_id:
                company = Company.query.get(user.company_id)
                if company:
                    # ✅ Update company plan to match the payment
                    company.plan = plan
                    company.subscription_status = 'active'
                    company.billing_cycle = duration
                    company.subscription_ends_at = expiry_date
                    company.updated_at = datetime.utcnow()
                    app.logger.info(f"✅ Updated company {company.name} plan to {plan}")
                    
                    # ✅ Also sync ALL other users in the company
                    other_users = User.query.filter(
                        User.company_id == user.company_id,
                        User.id != user.id
                    ).all()
                    
                    for other_user in other_users:
                        other_user.subscription_plan = plan
                        other_user.subscription_status = 'active'
                        other_user.billing_cycle = duration
                        other_user.subscription_ends_at = expiry_date
                    
                    app.logger.info(f"✅ Synced {len(other_users)} other users to {plan} plan")
            
            # Create or update subscription record
            existing_sub = Subscription.query.filter_by(user_id=user.id).first()
            if existing_sub:
                existing_sub.plan = plan
                existing_sub.status = 'active'
                existing_sub.end_date = expiry_date
                existing_sub.payment_method = payment.payment_method
            else:
                new_sub = Subscription(
                    user_id=user.id,
                    plan=plan,
                    status='active',
                    start_date=datetime.utcnow(),
                    end_date=expiry_date,
                    payment_method=payment.payment_method
                )
                db.session.add(new_sub)
            
            # Create payment history record
            payment_history = PaymentHistory(
                user_id=user.id,
                plan=plan,
                billing_cycle=duration,
                country=user.country or 'default',
                currency=payment.currency,
                amount=payment.amount,
                payment_method=payment.payment_method,
                payment_gateway='manual',
                payment_id=payment.payment_reference,
                status='completed',
                paid_at=datetime.utcnow(),
                created_at=datetime.utcnow()
            )
            db.session.add(payment_history)
        
        db.session.commit()
        
        # Send confirmation email
        try:
            send_payment_confirmation_email(user, payment)
        except Exception as email_error:
            app.logger.warning(f"Failed to send confirmation email: {email_error}")
        
        return jsonify({
            'success': True,
            'message': 'Payment verified successfully. Company plan updated.',
            'payment': {
                'id': payment.id,
                'status': payment.status,
                'verified_at': payment.verified_at.isoformat() if payment.verified_at else None
            },
            'company_updated': True if user and user.company_id else False
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error verifying payment {payment_id}: {str(e)}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/payments/<int:payment_id>/reject', methods=['POST'])
@safetypro_required
def reject_manual_payment(payment_id):
    """Reject a manual payment - SECURED WITH JWT"""
    try:
        current_user = request.user
        app.logger.info(f"Rejecting payment {payment_id} by {current_user.email}")
        
        # Check if user has SafetyPro access
        if not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Access restricted to SafetyPro system administrators',
                'code': 'ACCESS_DENIED'
            }), 403
        
        data = request.get_json() or {}
        
        # Find payment
        payment = ManualPayment.query.get(payment_id)
        if not payment:
            return jsonify({'success': False, 'error': 'Payment not found'}), 404
        
        # Check if already processed
        if payment.status in ['verified', 'rejected']:
            return jsonify({'success': False, 'error': f'Payment already {payment.status}'}), 400
        
        # Update payment status
        payment.status = 'rejected'
        payment.admin_notes = data.get('notes', 'Payment rejected by admin') or payment.admin_notes
        payment.rejected_at = datetime.utcnow()
        payment.rejected_by = current_user.id
        
        db.session.commit()
        
        # Send rejection email to user
        try:
            send_payment_rejection_email(payment.user, payment)
        except Exception as email_error:
            app.logger.warning(f"Failed to send rejection email: {email_error}")
        
        # Create audit log
        try:
            audit_log = ActivityLog(
                user_id=current_user.id,
                activity_type='admin_reject_payment',
                description=f'Rejected payment {payment.payment_reference}',
                ip_address=request.remote_addr,
                activity_data={
                    'payment_id': payment.id,
                    'payment_reference': payment.payment_reference,
                    'user_id': payment.user_id
                }
            )
            db.session.add(audit_log)
            db.session.commit()
        except Exception as e:
            app.logger.warning(f"Audit log error: {e}")
        
        return jsonify({
            'success': True,
            'message': 'Payment rejected',
            'payment': {
                'id': payment.id,
                'status': payment.status
            }
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error rejecting payment {payment_id}: {str(e)}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/payments/bulk/verify', methods=['POST'])
@safetypro_required
def bulk_verify_payments():
    """Bulk verify multiple payments - SECURED WITH JWT"""
    try:
        current_user = request.user
        data = request.get_json()
        payment_ids = data.get('payment_ids', [])
        
        # Check if user has SafetyPro access
        if not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Access restricted to SafetyPro system administrators',
                'code': 'ACCESS_DENIED'
            }), 403
        
        if not payment_ids:
            return jsonify({'success': False, 'error': 'No payment IDs provided'}), 400
        
        app.logger.info(f"Bulk verifying {len(payment_ids)} payments by {current_user.email}")
        
        verified_count = 0
        failed_ids = []
        
        for payment_id in payment_ids:
            try:
                payment = ManualPayment.query.get(payment_id)
                if payment and payment.status == 'pending_verification':
                    payment.status = 'verified'
                    payment.verified_at = datetime.utcnow()
                    payment.verified_by = current_user.id
                    
                    # Update user subscription
                    if payment.user:
                        duration = getattr(payment, 'duration', '1_month')
                        expiry_date = calculate_expiry_date_from_duration(duration)
                        
                        payment.user.subscription_plan = payment.plan
                        payment.user.subscription_status = 'active'
                        payment.user.billing_cycle = duration
                        payment.user.subscription_ends_at = expiry_date
                        payment.user.last_payment_date = datetime.utcnow()
                        payment.user.is_active = True
                    
                    verified_count += 1
                else:
                    failed_ids.append(payment_id)
            except Exception as e:
                app.logger.error(f"Error verifying payment {payment_id}: {str(e)}")
                failed_ids.append(payment_id)
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Verified {verified_count} payments',
            'verified_count': verified_count,
            'failed_ids': failed_ids
        }), 200
        
    except Exception as e:
        app.logger.error(f"Error bulk verifying payments: {str(e)}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


