def create_payment_notification(user, payment, action):
    """Create notification for payment action"""
    try:
        notification = Notification(
            user_id=user.id,
            title=f"Payment {action.capitalize()} - {payment.payment_reference}",
            message=f"Your manual payment of {payment.currency} {payment.amount} for {payment.plan} plan has been {action}.",
            type="payment_update",
            priority="high",
            read=False,
            metadata=json.dumps({
                'payment_id': payment.id,
                'payment_reference': payment.payment_reference,
                'action': action,
                'amount': payment.amount,
                'currency': payment.currency,
                'plan': payment.plan
            })
        )
        db.session.add(notification)
        db.session.commit()
        return True
    except Exception as e:
        app.logger.error(f"Error creating notification: {str(e)}")
        return False

@app.route('/api/safetypro/pending', methods=['GET'])
@safetypro_required
def get_pending_approvals():
    """Get all pending approvals for SafetyPro team - SECURED WITH JWT"""
    try:
        # Get current admin from JWT authentication
        current_user = request.user
        print(f"👤 Admin fetching pending approvals: {current_user.name} (ID: {current_user.id})")
        
        # Check if user has SafetyPro access
        if not request.is_system_team:
            print(f"❌ Access denied: User is not SafetyPro team")
            return jsonify({
                'success': False,
                'error': 'Access restricted to SafetyPro system administrators',
                'code': 'ACCESS_DENIED',
                'debug_info': {
                    'user_type': current_user.user_type,
                    'admin_role': getattr(current_user, 'admin_role', None),
                    'admin_level': getattr(current_user, 'admin_level', None),
                    'is_system_team': request.is_system_team
                }
            }), 403
        
        # Get filter parameters
        user_type = request.args.get('user_type', 'all')
        subscription_plan = request.args.get('plan', 'all')
        date_from = request.args.get('from')
        date_to = request.args.get('to')
        limit = request.args.get('limit', type=int)
        offset = request.args.get('offset', 0, type=int)
        
        print(f"🔍 Filters - Type: {user_type}, Plan: {subscription_plan}, From: {date_from}, To: {date_to}")
        
        # Build query for pending users
        query = User.query.filter_by(approval_status='pending')
        
        # Apply filters
        if user_type != 'all' and user_type:
            query = query.filter_by(user_type=user_type)
        
        if subscription_plan != 'all' and subscription_plan:
            query = query.filter_by(subscription_plan=subscription_plan)
        
        if date_from:
            try:
                from_date = datetime.fromisoformat(date_from.replace('Z', '+00:00'))
                query = query.filter(User.created_at >= from_date)
                print(f"📅 Filter: From {from_date}")
            except ValueError as e:
                print(f"⚠️ Invalid date_from format: {date_from}, error: {e}")
        
        if date_to:
            try:
                to_date = datetime.fromisoformat(date_to.replace('Z', '+00:00'))
                query = query.filter(User.created_at <= to_date)
                print(f"📅 Filter: To {to_date}")
            except ValueError as e:
                print(f"⚠️ Invalid date_to format: {date_to}, error: {e}")
        
        # Order by creation date (newest first)
        query = query.order_by(User.created_at.desc())
        
        # Get total count before pagination
        total_count = query.count()
        print(f"📊 Total pending users: {total_count}")
        
        # Apply pagination
        if limit:
            query = query.limit(limit)
        if offset:
            query = query.offset(offset)
        
        pending_users = query.all()
        print(f"📄 Retrieved {len(pending_users)} pending users")
        
        approvals = []
        for user in pending_users:
            try:
                # Get document summary
                document_summary = get_user_documents_summary(user.id)
                
                # Get required documents
                required_docs = get_required_documents_for_user(user)
                
                # Check if all documents uploaded
                documents_uploaded = check_documents_uploaded(user.id)
                
                # Get user notes
                user_notes = get_user_notes(user.id)
                
                # ✅ Calculate priority - RETURNS INTEGER NOW
                priority_score = calculate_approval_priority(user)
                
                # ✅ Ensure priority_score is an integer
                try:
                    priority_score = int(priority_score)
                except (ValueError, TypeError):
                    priority_score = 0
                
                # ✅ Get priority level from score
                priority_level = get_priority_level(priority_score)
                
                # ✅ Safe comparison for high priority
                has_high_priority = priority_score >= 8
                
                # ✅ Safe comparison for requires attention
                requires_attention = (
                    not documents_uploaded or 
                    len(user_notes) > 0 or 
                    priority_score >= 7
                )
                
                # ✅ Safe calculation for days waiting
                days_waiting = 0
                if user.created_at:
                    try:
                        days_waiting = (datetime.utcnow() - user.created_at).days
                    except:
                        days_waiting = 0
                
                user_data = {
                    'id': user.id,
                    'name': user.name,
                    'email': user.email,
                    'user_type': user.user_type,
                    'subscription_plan': user.subscription_plan,
                    'company_name': user.company_name,
                    'phone': user.phone,
                    'country': user.country,
                    'employee_count': user.employee_count,
                    'industry': user.industry,
                    'custom_requirements': getattr(user, 'custom_requirements', ''),
                    'created_at': user.created_at.isoformat() if user.created_at else None,
                    'last_login': user.last_login.isoformat() if user.last_login else None,
                    'verified': user.verified,
                    'documents_uploaded': documents_uploaded,
                    'documents_verified': user.documents_verified,
                    'document_summary': document_summary,
                    'required_documents': required_docs,
                    'days_waiting': days_waiting,
                    'notes': user_notes,
                    'priority': priority_score,  # ✅ Now an integer
                    'priority_level': priority_level,  # 'high'/'medium'/'low'
                    'subscription_value': calculate_subscription_value(user),
                    'risk_score': calculate_user_risk_score(user.id),
                    'last_activity': get_last_user_activity(user.id),
                    'has_high_priority': has_high_priority,
                    'requires_attention': requires_attention
                }
                approvals.append(user_data)
                
            except Exception as e:
                print(f"⚠️ Error processing user {user.id}: {e}")
                import traceback
                traceback.print_exc()
                # Add minimal user data
                approvals.append({
                    'id': user.id,
                    'name': user.name,
                    'email': user.email,
                    'user_type': user.user_type,
                    'subscription_plan': user.subscription_plan,
                    'created_at': user.created_at.isoformat() if user.created_at else None,
                    'error': 'Error loading user details'
                })
        
        # Create audit log
        try:
            audit_log = ActivityLog(
                user_id=current_user.id,
                activity_type='admin_view_pending_approvals',
                description=f'Viewed {len(approvals)} pending approvals',
                ip_address=request.remote_addr,
                activity_data={
                    'filters': {
                        'user_type': user_type,
                        'plan': subscription_plan,
                        'date_from': date_from,
                        'date_to': date_to,
                        'limit': limit,
                        'offset': offset
                    },
                    'total_count': total_count,
                    'returned_count': len(approvals),
                    'high_priority_count': len([a for a in approvals if a.get('has_high_priority', False)]),
                    'requires_attention_count': len([a for a in approvals if a.get('requires_attention', False)])
                }
            )
            db.session.add(audit_log)
            db.session.commit()
            audit_log_id = audit_log.id
        except Exception as e:
            print(f"⚠️ Audit log error: {e}")
            audit_log_id = None
        
        print(f"✅ Successfully fetched {len(approvals)} pending approvals")
        
        return jsonify({
            'success': True,
            'message': 'Pending approvals retrieved successfully',
            'code': 'PENDING_APPROVALS_RETRIEVED',
            'count': len(approvals),
            'total_count': total_count,
            'approvals': approvals,
            'summary': {
                'total': total_count,
                'displayed': len(approvals),
                'high_priority': len([a for a in approvals if a.get('has_high_priority', False)]),
                'requires_attention': len([a for a in approvals if a.get('requires_attention', False)]),
                'by_user_type': count_by_field(approvals, 'user_type'),
                'by_plan': count_by_field(approvals, 'subscription_plan'),
                'avg_days_waiting': calculate_average_days_waiting(approvals)
            },
            'filters': {
                'user_type': user_type,
                'plan': subscription_plan,
                'date_range': {'from': date_from, 'to': date_to},
                'pagination': {
                    'limit': limit,
                    'offset': offset,
                    'has_more': total_count > (offset + len(approvals))
                }
            },
            'accessed_by': {
                'admin_id': current_user.id,
                'admin_name': current_user.name,
                'admin_email': current_user.email,
                'admin_role': current_user.admin_role,
                'admin_level': current_user.admin_level
            },
            'timestamp': datetime.utcnow().isoformat(),
            'audit_log_id': audit_log_id
        }), 200
        
    except Exception as e:
        logger.error(f"❌ Error fetching pending approvals: {str(e)}")
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Failed to fetch pending approvals',
            'code': 'INTERNAL_ERROR',
            'message': 'An error occurred while retrieving pending approvals'
        }), 500

