@app.route('/api/user/documents/upload', methods=['POST'], endpoint='upload_user_document')
@jwt_required
def upload_user_document():
    """Upload a document"""
    try:
        user_id = user.id
        user = User.query.get(user_id)
        
        if 'document' not in request.files:
            return jsonify({'error': 'No document file provided'}), 400
        
        file = request.files['document']
        if file.filename == '':
            return jsonify({'error': 'No selected file'}), 400
        
        # Get document info from form
        document_type = request.form.get('document_type', 'other')
        document_name = request.form.get('document_name', file.filename)
        
        # Validate file type and size
        allowed_extensions = ['pdf', 'jpg', 'jpeg', 'png', 'doc', 'docx']
        max_size = 10 * 1024 * 1024  # 10MB
        
        if not allowed_file(file.filename, allowed_extensions):
            return jsonify({'error': f'File type not allowed. Allowed: {allowed_extensions}'}), 400
        
        if len(file.read()) > max_size:
            return jsonify({'error': 'File too large. Maximum size is 10MB'}), 400
        
        # Reset file pointer
        file.seek(0)
        
        # Save file
        filename = secure_filename(f"{user_id}_{document_type}_{int(time.time())}_{file.filename}")
        file_path = os.path.join(app.config['UPLOAD_FOLDER'], 'documents', filename)
        
        # Ensure directory exists
        os.makedirs(os.path.dirname(file_path), exist_ok=True)
        
        file.save(file_path)
        
        # Create document record
        document = UserDocument(
            user_id=user_id,
            document_type=document_type,
            document_name=document_name,
            file_path=file_path,
            file_size=os.path.getsize(file_path),
            mime_type=file.mimetype,
            status='pending'
        )
        
        db.session.add(document)
        
        # Update user's documents_uploaded status
        user.documents_uploaded = True
        user.documents_uploaded_at = datetime.utcnow()
        
        db.session.commit()
        
        # Add note about document upload
        add_user_note(
            user_id=user_id,
            content=f"Uploaded document: {document_name} ({document_type})",
            note_type='document_upload',
            created_by=user_id
        )
        
        return jsonify({
            'success': True,
            'message': 'Document uploaded successfully',
            'document': document.to_dict()
        }), 200
        
    except Exception as e:
        logger.error(f"Error uploading document: {str(e)}")
        db.session.rollback()
        return jsonify({'error': 'Failed to upload document'}), 500


