def calculate_subscription_end(start_date, billing_cycle):
    """Calculate subscription end date based on billing cycle"""
    from datetime import timedelta
    
    if billing_cycle == '1_month':
        return start_date + timedelta(days=30)
    elif billing_cycle == '6_month':
        return start_date + timedelta(days=180)
    elif billing_cycle == '1_year':
        return start_date + timedelta(days=365)
    else:
        return start_date + timedelta(days=30)  # Default 1 month

