@app.route('/api/performance/overview', methods=['GET'], endpoint='get_performance_overview')
@safetypro_required
def get_performance_overview():
    """Get performance overview for all users (SafetyPro admins only)"""
    try:
        days = int(request.args.get('days', 30))
        end_date = datetime.utcnow()
        start_date = end_date - timedelta(days=days)
        
        # Get overall metrics
        total_users = User.query.count()
        active_users = User.query.filter(
            User.last_login >= start_date,
            User.is_active == True
        ).count()
        
        new_users = User.query.filter(
            User.created_at >= start_date
        ).count()
        
        churned_users = User.query.filter(
            User.last_login < start_date - timedelta(days=60),
            User.is_active == True
        ).count()
        
        # Get activity metrics
        total_logins = LoginLog.query.filter(
            LoginLog.login_time >= start_date
        ).count()
        
        avg_logins_per_user = total_logins / active_users if active_users > 0 else 0
        
        # Get user type distribution
        user_types = db.session.query(
            User.user_type,
            func.count(User.id).label('count')
        ).group_by(User.user_type).all()
        
        # Get subscription performance
        subscription_stats = db.session.query(
            User.subscription_plan,
            func.count(User.id).label('total'),
            func.avg(case(
                (User.last_login >= start_date, 1),
                else_=0
            )).label('active_rate')
        ).group_by(User.subscription_plan).all()
        
        # Top performers
        top_performers = get_top_performers(start_date, end_date, limit=10)
        
        # At-risk users (inactive for >30 days)
        at_risk_users = User.query.filter(
            User.last_login < end_date - timedelta(days=30),
            User.is_active == True
        ).order_by(User.last_login).limit(20).all()
        
        return jsonify({
            'success': True,
            'overview': {
                'total_users': total_users,
                'active_users': active_users,
                'active_rate': (active_users / total_users * 100) if total_users > 0 else 0,
                'new_users': new_users,
                'churned_users': churned_users,
                'churn_rate': (churned_users / total_users * 100) if total_users > 0 else 0,
                'total_logins': total_logins,
                'avg_logins_per_user': round(avg_logins_per_user, 2),
                'avg_session_duration': get_avg_session_duration(start_date, end_date)
            },
            'distribution': {
                'user_types': [{'type': t[0], 'count': t[1]} for t in user_types],
                'subscriptions': [{
                    'plan': s[0],
                    'total': s[1],
                    'active_rate': float(s[2]) * 100 if s[2] else 0
                } for s in subscription_stats]
            },
            'top_performers': top_performers,
            'at_risk_users': [{
                'id': u.id,
                'name': u.name,
                'email': u.email,
                'last_active': u.last_login.isoformat() if u.last_login else None,
                'days_inactive': (end_date - u.last_login).days if u.last_login else None
            } for u in at_risk_users],
            'period': {
                'start': start_date.isoformat(),
                'end': end_date.isoformat(),
                'days': days
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Performance overview error: {str(e)}")
        return jsonify({'error': 'Failed to fetch performance overview'}), 500

@app.route('/api/performance/monthly', methods=['GET'], endpoint='get_monthly_performance')
@safetypro_required
def get_monthly_performance():
    """Get monthly performance trends (SafetyPro admins only)"""
    try:
        months = int(request.args.get('months', 12))
        
        # Generate monthly data
        monthly_data = []
        for i in range(months - 1, -1, -1):
            month_start = datetime.utcnow().replace(
                day=1, hour=0, minute=0, second=0, microsecond=0
            ) - timedelta(days=30 * i)
            month_end = month_start + timedelta(days=30)
            
            # Monthly metrics
            new_users = User.query.filter(
                User.created_at >= month_start,
                User.created_at < month_end
            ).count()
            
            active_users = User.query.filter(
                User.last_login >= month_start,
                User.last_login < month_end,
                User.is_active == True
            ).count()
            
            monthly_logins = LoginLog.query.filter(
                LoginLog.login_time >= month_start,
                LoginLog.login_time < month_end
            ).count()
            
            # Calculate retention rate (users active this month who were active last month)
            if i > 0:
                prev_month_start = month_start - timedelta(days=30)
                retained_users = User.query.filter(
                    User.last_login >= month_start,
                    User.last_login < month_end,
                    User.id.in_(
                        db.session.query(User.id).filter(
                            User.last_login >= prev_month_start,
                            User.last_login < month_start
                        )
                    )
                ).count()
                
                prev_month_active = User.query.filter(
                    User.last_login >= prev_month_start,
                    User.last_login < month_start
                ).count()
                
                retention_rate = (retained_users / prev_month_active * 100) if prev_month_active > 0 else 0
            else:
                retention_rate = None
            
            monthly_data.append({
                'month': month_start.strftime('%Y-%m'),
                'month_name': month_start.strftime('%B %Y'),
                'new_users': new_users,
                'active_users': active_users,
                'monthly_logins': monthly_logins,
                'retention_rate': retention_rate,
                'avg_daily_logins': monthly_logins / 30
            })
        
        # Calculate trends
        trends = calculate_monthly_trends(monthly_data)
        
        return jsonify({
            'success': True,
            'monthly_data': monthly_data,
            'trends': trends,
            'months_analyzed': months
        }), 200
        
    except Exception as e:
        logger.error(f"Monthly performance error: {str(e)}")
        return jsonify({'error': 'Failed to fetch monthly performance'}), 500

@app.route('/api/performance/engagement', methods=['GET'], endpoint='get_engagement_metrics')
@safetypro_required
def get_engagement_metrics():
    """Get user engagement metrics (SafetyPro admins only)"""
    try:
        days = int(request.args.get('days', 30))
        end_date = datetime.utcnow()
        start_date = end_date - timedelta(days=days)
        
        # Engagement metrics
        daily_active_users = []
        weekly_active_users = []
        
        # Calculate DAU (Daily Active Users)
        for i in range(days):
            day_start = end_date - timedelta(days=i)
            day_end = day_start + timedelta(days=1)
            
            dau = User.query.filter(
                User.last_login >= day_start,
                User.last_login < day_end,
                User.is_active == True
            ).count()
            
            daily_active_users.append({
                'date': day_start.strftime('%Y-%m-%d'),
                'dau': dau
            })
        
        # Calculate WAU (Weekly Active Users)
        weeks = days // 7
        for i in range(weeks):
            week_start = end_date - timedelta(days=(i + 1) * 7)
            week_end = week_start + timedelta(days=7)
            
            wau = User.query.filter(
                User.last_login >= week_start,
                User.last_login < week_end,
                User.is_active == True
            ).count()
            
            weekly_active_users.append({
                'week_start': week_start.strftime('%Y-%m-%d'),
                'week_end': week_end.strftime('%Y-%m-%d'),
                'wau': wau
            })
        
        # Calculate MAU (Monthly Active Users)
        mau = User.query.filter(
            User.last_login >= start_date,
            User.is_active == True
        ).count()
        
        # Calculate stickiness (DAU/MAU)
        avg_dau = sum(d['dau'] for d in daily_active_users) / len(daily_active_users)
        stickiness = (avg_dau / mau * 100) if mau > 0 else 0
        
        # User activity distribution
        activity_distribution = {
            'power_users': User.query.filter(
                User.last_login >= start_date,
                User.login_count >= 20
            ).count(),
            'regular_users': User.query.filter(
                User.last_login >= start_date,
                User.login_count.between(5, 19)
            ).count(),
            'casual_users': User.query.filter(
                User.last_login >= start_date,
                User.login_count.between(1, 4)
            ).count(),
            'inactive_users': User.query.filter(
                User.last_login < start_date,
                User.is_active == True
            ).count()
        }
        
        return jsonify({
            'success': True,
            'engagement': {
                'dau_data': daily_active_users,
                'wau_data': weekly_active_users,
                'mau': mau,
                'avg_dau': round(avg_dau, 2),
                'stickiness': round(stickiness, 2),
                'activity_distribution': activity_distribution
            },
            'period': {
                'start': start_date.isoformat(),
                'end': end_date.isoformat(),
                'days': days
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Engagement metrics error: {str(e)}")
        return jsonify({'error': 'Failed to fetch engagement metrics'}), 500
# ============== HELPER FUNCTIONS ==============
def calculate_user_performance(user_id, start_date, end_date):
    """Calculate performance metrics for a user"""
    
    # Login frequency
    login_count = LoginLog.query.filter(
        LoginLog.user_id == user_id,
        LoginLog.login_time >= start_date,
        LoginLog.login_time <= end_date
    ).count()
    
    # Average session duration
    sessions = LoginLog.query.filter(
        LoginLog.user_id == user_id,
        LoginLog.login_time >= start_date,
        LoginLog.logout_time.isnot(None)
    ).all()
    
    total_duration = sum(
        (s.logout_time - s.login_time).total_seconds() 
        for s in sessions if s.logout_time
    )
    avg_session_duration = total_duration / len(sessions) if sessions else 0
    
    # Activity count
    activity_count = UserActivityLog.query.filter(
        UserActivityLog.user_id == user_id,
        UserActivityLog.timestamp >= start_date
    ).count()
    
    # Feature usage
    feature_usage = db.session.query(
        UserActivityLog.activity_type,
        func.count(UserActivityLog.id).label('count')
    ).filter(
        UserActivityLog.user_id == user_id,
        UserActivityLog.timestamp >= start_date
    ).group_by(UserActivityLog.activity_type).all()
    
    # Calculate performance score
    performance_score = calculate_performance_score(
        login_count,
        activity_count,
        avg_session_duration
    )
    
    return {
        'login_count': login_count,
        'avg_session_duration_minutes': round(avg_session_duration / 60, 2),
        'activity_count': activity_count,
        'feature_usage': {f[0]: f[1] for f in feature_usage},
        'performance_score': performance_score,
        'performance_grade': get_performance_grade(performance_score),
        'days_active': get_days_active(user_id, start_date, end_date),
        'avg_daily_logins': round(login_count / ((end_date - start_date).days or 1), 2)
    }

def get_user_activity_timeline(user_id, start_date, end_date):
    """Get user activity timeline"""
    activities = UserActivityLog.query.filter(
        UserActivityLog.user_id == user_id,
        UserActivityLog.timestamp >= start_date,
        UserActivityLog.timestamp <= end_date
    ).order_by(UserActivityLog.timestamp.desc()).limit(50).all()
    
    return [{
        'timestamp': a.timestamp.isoformat(),
        'activity_type': a.activity_type,
        'description': a.description,
        'ip_address': a.ip_address
    } for a in activities]

def get_comparative_analysis(user, days):
    """Get comparative analysis with similar users"""
    
    # Find similar users (same user_type and subscription_plan)
    similar_users = User.query.filter(
        User.user_type == user.user_type,
        User.subscription_plan == user.subscription_plan,
        User.id != user.id,
        User.is_active == True
    ).all()
    
    if not similar_users:
        return None
    
    # Calculate average metrics for similar users
    similar_user_ids = [u.id for u in similar_users]
    
    # Get average login count
    avg_logins = db.session.query(
        func.avg(func.coalesce(User.login_count, 0))
    ).filter(User.id.in_(similar_user_ids)).scalar() or 0
    
    # Get average activity count
    avg_activities = db.session.query(
        func.avg(func.coalesce(User.activity_count, 0))
    ).filter(User.id.in_(similar_user_ids)).scalar() or 0
    
    # Calculate user's metrics
    user_logins = user.login_count or 0
    user_activities = user.activity_count or 0
    
    return {
        'similar_users_count': len(similar_users),
        'comparison': {
            'logins': {
                'user': user_logins,
                'average': round(avg_logins, 2),
                'percentile': calculate_percentile(user_logins, [u.login_count or 0 for u in similar_users])
            },
            'activities': {
                'user': user_activities,
                'average': round(avg_activities, 2),
                'percentile': calculate_percentile(user_activities, [u.activity_count or 0 for u in similar_users])
            }
        }
    }

def get_top_performers(start_date, end_date, limit=10):
    """Get top performing users"""
    
    # Calculate performance scores for all users
    top_users = db.session.query(
        User.id,
        User.name,
        User.email,
        User.user_type,
        User.subscription_plan,
        func.count(LoginLog.id).label('login_count'),
        func.count(UserActivityLog.id).label('activity_count')
    ).outerjoin(
        LoginLog, and_(
            LoginLog.user_id == User.id,
            LoginLog.login_time >= start_date
        )
    ).outerjoin(
        UserActivityLog, and_(
            UserActivityLog.user_id == User.id,
            UserActivityLog.timestamp >= start_date
        )
    ).filter(
        User.is_active == True
    ).group_by(User.id).order_by(
        func.count(LoginLog.id).desc(),
        func.count(UserActivityLog.id).desc()
    ).limit(limit).all()
    
    return [{
        'id': u[0],
        'name': u[1],
        'email': u[2],
        'user_type': u[3],
        'subscription_plan': u[4],
        'login_count': u[5],
        'activity_count': u[6],
        'performance_score': calculate_performance_score(u[5], u[6], 0)
    } for u in top_users]

def calculate_performance_score(login_count, activity_count, avg_session_duration):
    """Calculate performance score (0-100)"""
    
    # Weighted scoring
    login_score = min(login_count * 2, 40)  # Max 40 points
    activity_score = min(activity_count * 0.5, 40)  # Max 40 points
    duration_score = min(avg_session_duration / 60, 20)  # Max 20 points (1 point per minute)
    
    return min(login_score + activity_score + duration_score, 100)

def get_performance_grade(score):
    """Convert score to letter grade"""
    if score >= 90:
        return 'A+'
    elif score >= 80:
        return 'A'
    elif score >= 70:
        return 'B'
    elif score >= 60:
        return 'C'
    elif score >= 50:
        return 'D'
    else:
        return 'F'

def calculate_monthly_trends(monthly_data):
    """Calculate trends from monthly data"""
    if len(monthly_data) < 2:
        return {}
    
    latest = monthly_data[-1]
    previous = monthly_data[-2]
    
    trends = {}
    
    # New users trend
    if previous['new_users'] > 0:
        trends['new_users'] = {
            'change': latest['new_users'] - previous['new_users'],
            'percent': ((latest['new_users'] - previous['new_users']) / previous['new_users']) * 100
        }
    
    # Active users trend
    if previous['active_users'] > 0:
        trends['active_users'] = {
            'change': latest['active_users'] - previous['active_users'],
            'percent': ((latest['active_users'] - previous['active_users']) / previous['active_users']) * 100
        }
    
    return trends

def get_avg_session_duration(start_date, end_date):
    """Calculate average session duration"""
    sessions = LoginLog.query.filter(
        LoginLog.login_time >= start_date,
        LoginLog.logout_time.isnot(None)
    ).all()
    
    if not sessions:
        return 0
    
    total_duration = sum(
        (s.logout_time - s.login_time).total_seconds()
        for s in sessions if s.logout_time
    )
    
    return round(total_duration / len(sessions) / 60, 2)  # Convert to minutes

def get_days_active(user_id, start_date, end_date):
    """Get number of days user was active"""
    distinct_days = db.session.query(
    func.strftime('%Y-%m-%d', LoginLog.login_time)
).filter(
    LoginLog.user_id == user_id,
    LoginLog.login_time >= start_date
).distinct().count()
    
    return distinct_days

def calculate_percentile(value, values_list):
    """Calculate percentile rank"""
    if not values_list:
        return 50
    
    values_list = [v for v in values_list if v is not None]
    values_list.sort()
    
    count = len(values_list)
    if count == 0:
        return 50
    
    # Count values less than or equal to target value
    less_or_equal = sum(1 for v in values_list if v <= value)
    
    # Calculate percentile
    percentile = (less_or_equal / count) * 100
    
    return round(percentile, 1)



@app.route('/api/admin/login', methods=['POST', 'OPTIONS'])

@limiter.limit("5 per minute")
def admin_login():
    """Admin-specific login WITH proper approval checks and tracking"""
    try:
        print('=== ADMIN LOGIN REQUEST ===')
        
        if request.method == 'OPTIONS':
            response = jsonify({'status': 'ok'})
            return response, 200
        
        data = request.get_json()
        
        if not data:
            return jsonify({'error': 'No JSON data provided'}), 400

        email = data.get('email', '').lower().strip()
        password = data.get('password', '')

        if not email or not password:
            return jsonify({'error': 'Email and password are required'}), 400

        # Find admin user - USE user_type='admin'
        user = User.query.filter_by(email=email, user_type='admin').first()

        if not user:
            logger.warning(f"Admin login attempt - user not found or not admin: {email}")
            return jsonify({'error': 'Invalid admin credentials'}), 401

        # Verify password
        if not check_password_hash(user.password_hash, password):
            logger.warning(f"Failed admin login for user {user.id}")
            return jsonify({'error': 'Invalid credentials'}), 401

        # CHECK 1: Email verification - Use 'verified' field
        if not user.verified:
            return jsonify({
                'error': 'Email not verified',
                'message': 'Please check your email for verification code',
                'requires_verification': True,
                'email': user.email
            }), 401

        # CHECK 2: Admin approval status
        if user.approval_status != 'approved':
            status_message = {
                'pending': 'Your admin account is pending approval. Our team will contact you soon.',
                'rejected': 'Your admin account was rejected. Contact support for details.',
                'suspended': 'Your admin account is suspended. Contact support.'
            }.get(user.approval_status, 'Admin account requires approval.')
            
            return jsonify({
                'error': 'Admin approval required',
                'message': status_message,
                'approval_status': user.approval_status,
                'requires_approval': True
            }), 401

        # CHECK 3: Account active status
        if not user.is_active:
            return jsonify({
                'error': 'Account deactivated',
                'message': 'Your admin account has been deactivated. Contact support.'
            }), 401

        # SUCCESSFUL ADMIN LOGIN
        user.last_login = datetime.utcnow()
        
        # Initialize performance fields if they don't exist
        if not hasattr(user, 'login_count'):
            user.login_count = 0
        user.login_count = (user.login_count or 0) + 1
        
        if not hasattr(user, 'activity_count'):
            user.activity_count = 0
            
        if not hasattr(user, 'total_session_duration'):
            user.total_session_duration = 0
            
        if not hasattr(user, 'performance_score'):
            user.performance_score = 0
        
        if not hasattr(user, 'performance_grade'):
            user.performance_grade = 'F'
        
        # Create admin session with expiration (24 hours from now)
        session_id = str(uuid.uuid4())
        expires_at = datetime.utcnow() + timedelta(hours=24)  # 🔥 ADD EXPIRATION
        
        admin_session = UserSession(
            session_id=session_id,
            user_id=user.id,
            ip_address=request.remote_addr,
            user_agent=request.headers.get('User-Agent', ''),
            expires_at=expires_at,  # 🔥 MUST PROVIDE THIS
            is_active=True
        )
        db.session.add(admin_session)
    
        db.session.commit()
        
        # 🔥 CREATE ACTIVITY LOG
        create_activity_log(
            user_id=user.id,
            activity_type='admin_login',
            description=f'Admin login from {request.remote_addr}',
            ip_address=request.remote_addr,
            metadata={
                'user_agent': request.headers.get('User-Agent'),
                'session_id': session_id,
                'login_type': 'admin',
                'device_info': extract_device_info(request.headers.get('User-Agent', ''))
            }
        )

        # Determine admin permissions based on role/level
        permissions = get_admin_permissions(user)
        
        # Create admin access token (also expires in 24 hours)
        access_token = create_access_token(
            identity=user.id,
            expires_delta=timedelta(hours=24),  # Match session expiration
            additional_claims={
                'email': user.email,
                'role': user.admin_role or user.role,
                'user_type': user.user_type,
                'session_id': session_id,
                'is_admin': True,
                'permissions': permissions,
                'subscription_plan': user.subscription_plan or 'custom_enterprise',
                'company_name': user.company_name,
                'login_timestamp': datetime.utcnow().isoformat(),
                'expires_at': expires_at.isoformat()  # Include in token
            }
        )

        logger.info(f"Successful admin login for user {user.id}")

        # Calculate performance metrics for admin dashboard
        performance_data = calculate_user_performance(user.id, datetime.utcnow() - timedelta(days=30), datetime.utcnow())
        
        response_data = {
            'access_token': access_token,
            'token_type': 'bearer',
            'expires_in': 24 * 3600,
            'session_id': session_id,
            'session_expires_at': expires_at.isoformat(),  # Send expiration to frontend
            'user': {
                'id': user.id,
                'name': user.name,
                'email': user.email,
                'role': user.admin_role or user.role,
                'user_type': user.user_type,
                'company_name': user.company_name,
                'company_size': user.employee_count,
                'country': user.country,
                'phone': user.phone,
                'subscription_plan': user.subscription_plan or 'custom_enterprise',
                'approval_status': user.approval_status,
                'last_login': user.last_login.isoformat() if user.last_login else None,
                'created_at': user.created_at.isoformat() if user.created_at else None,
                'permissions': permissions,
                'preferred_language': user.preferred_language,
                'admin_level': getattr(user, 'admin_level', 'standard'),
                'verified': user.verified,
                # 🔥 ADD PERFORMANCE METRICS
                'performance_metrics': {
                    'login_count': user.login_count,
                    'activity_count': user.activity_count,
                    'performance_score': user.performance_score,
                    'performance_grade': user.performance_grade,
                    'total_session_duration': user.total_session_duration,
                    'last_activity': getattr(user, 'last_activity', None),
                    'avg_session_duration': performance_data.get('avg_session_duration_minutes', 0),
                    'days_active': performance_data.get('days_active', 0),
                    'feature_usage': performance_data.get('feature_usage', {})
                }
            }
        }

        response = jsonify(response_data)
        return response, 200

    except Exception as e:
        logger.error(f"Admin login error: {str(e)}")
        db.session.rollback()
        return jsonify({'error': 'Authentication service temporarily unavailable'}), 500
    
def sync_user_with_company(user):
    """Sync user's plan with company's plan"""
    if not user.company_id:
        print(f"⚠️ User {user.email} has no company_id, skipping sync")
        return False
    
    company = Company.query.get(user.company_id)
    if not company:
        print(f"⚠️ Company not found for user {user.email} (company_id: {user.company_id})")
        return False
    
    # ✅ Always sync user with company
    if user.subscription_plan != company.plan:
        user.subscription_plan = company.plan
        user.subscription_status = company.subscription_status
        user.billing_cycle = company.billing_cycle
        user.subscription_ends_at = company.subscription_ends_at
        db.session.commit()
        print(f"🔄 Synced user {user.email} to company plan: {company.plan}")
        return True
    elif user.subscription_status != company.subscription_status:
        user.subscription_status = company.subscription_status
        db.session.commit()
        print(f"🔄 Synced user {user.email} subscription status: {company.subscription_status}")
        return True
    
    print(f"✅ User {user.email} already in sync with company plan: {company.plan}")
    return False


def check_company_plan_status(company):
    """
    Check company plan status and return appropriate stage and redirect
    
    Returns:
        tuple: (stage, redirect_to, requires_payment, requires_plan_selection, payment_status, message)
    """
    if not company:
        return ('needs_company_setup', '/company-setup', False, False, 'no_company', 'Company not found')
    
    company_plan = getattr(company, 'plan', None)
    company_status = getattr(company, 'subscription_status', 'inactive')
    
    print(f"🏢 Checking company plan: {company_plan} (Status: {company_status})")
    
    # ✅ CASE 1: Company has NO plan or plan is 'free'
    if not company_plan or company_plan == 'free':
        return ('needs_plan', '/select-plan', False, True, 'no_plan', 'Company needs to select a plan')
    
    # ✅ CASE 2: Company has pending payment
    if company_status in ['pending', 'pending_payment']:
        return ('needs_payment', '/payment', True, False, 'pending', 'Company payment is pending')
    
    # ✅ CASE 3: Company plan is inactive
    if company_status in ['inactive', 'suspended']:
        return ('needs_payment', '/payment', True, False, 'inactive', 'Company plan is inactive')
    
    # ✅ CASE 4: Company has active plan (enterprise/custom)
    if company_status == 'active':
        return ('complete', '/dashboard', False, False, 'completed', 'Company plan is active')
    
    # ✅ DEFAULT: Something went wrong
    return ('needs_plan', '/select-plan', False, True, 'unknown', 'Unknown company plan status')

@app.route('/api/company/logo/upload', methods=['POST', 'OPTIONS'])
@jwt_required
def upload_company_logo():
    """Upload company logo"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        current_user = request.user
        print(f"📤 Uploading company logo for user: {current_user.email}")
        
        # Check if user has a company
        if not current_user.company_id:
            return jsonify({
                'success': False,
                'error': 'User does not belong to a company'
            }), 400
        
        # Check if file is present
        if 'logo' not in request.files:
            return jsonify({
                'success': False,
                'error': 'No logo file provided'
            }), 400
        
        file = request.files['logo']
        
        if file.filename == '':
            return jsonify({
                'success': False,
                'error': 'No file selected'
            }), 400
        
        # Validate file type
        allowed_extensions = {'png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'}
        if '.' not in file.filename or file.filename.rsplit('.', 1)[1].lower() not in allowed_extensions:
            return jsonify({
                'success': False,
                'error': 'Invalid file type. Allowed: PNG, JPG, JPEG, GIF, WEBP, SVG'
            }), 400
        
        # Validate file size (max 5MB)
        max_size = 5 * 1024 * 1024  # 5MB
        file.seek(0, 2)  # Seek to end
        file_size = file.tell()
        file.seek(0)  # Reset file pointer
        if file_size > max_size:
            return jsonify({
                'success': False,
                'error': 'File size exceeds 5MB limit'
            }), 400
        
        # Create uploads directory if it doesn't exist
        import os
        upload_folder = os.path.join('static', 'logos')
        os.makedirs(upload_folder, exist_ok=True)
        
        # Generate unique filename
        import uuid
        file_extension = file.filename.rsplit('.', 1)[1].lower()
        filename = f"logo_{current_user.company_id}_{uuid.uuid4().hex[:8]}.{file_extension}"
        filepath = os.path.join(upload_folder, filename)
        
        # Save file
        file.save(filepath)
        print(f"✅ Logo saved to: {filepath}")
        
        # Get company
        company = Company.query.get(current_user.company_id)
        if not company:
            return jsonify({
                'success': False,
                'error': 'Company not found'
            }), 404
        
        # Remove old logo if exists
        if company.logo_url:
            old_filepath = os.path.join('static', company.logo_url.lstrip('/static/'))
            if os.path.exists(old_filepath):
                try:
                    os.remove(old_filepath)
                    print(f"🗑️ Removed old logo: {old_filepath}")
                except Exception as e:
                    print(f"⚠️ Could not remove old logo: {e}")
        
        # Update database
        logo_url = f"/static/logos/{filename}"
        company.logo_url = logo_url
        company.updated_at = datetime.utcnow()
        db.session.commit()
        
        # Update user context (for immediate reflection)
        current_user.company_logo = logo_url
        db.session.commit()
        
        print(f"✅ Company logo updated: {logo_url}")
        
        return jsonify({
            'success': True,
            'message': 'Company logo uploaded successfully',
            'logo_url': logo_url,
            'data': {
                'logo_url': logo_url,
                'company_id': company.id,
                'company_name': company.name
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        print(f"❌ Error uploading company logo: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/company/logo/<int:company_id>', methods=['DELETE', 'OPTIONS'])
@jwt_required
def remove_company_logo(company_id):
    """Remove company logo"""
    if request.method == 'OPTIONS':
        return jsonify({'status': 'ok'}), 200
    
    try:
        current_user = request.user
        print(f"🗑️ Removing company logo for company {company_id} by user: {current_user.email}")
        
        # Check if user has permission
        if current_user.company_id != company_id and current_user.user_type not in ['super_admin', 'platform_owner']:
            return jsonify({
                'success': False,
                'error': 'Unauthorized to remove logo'
            }), 403
        
        company = Company.query.get(company_id)
        if not company:
            return jsonify({
                'success': False,
                'error': 'Company not found'
            }), 404
        
        # Remove file if exists
        if company.logo_url:
            import os
            filepath = os.path.join('static', company.logo_url.lstrip('/static/'))
            if os.path.exists(filepath):
                try:
                    os.remove(filepath)
                    print(f"🗑️ Removed logo file: {filepath}")
                except Exception as e:
                    print(f"⚠️ Could not remove logo file: {e}")
        
        # Clear logo URL in database
        company.logo_url = None
        company.updated_at = datetime.utcnow()
        db.session.commit()
        
        # Clear user context
        if current_user.company_id == company_id:
            current_user.company_logo = None
            db.session.commit()
        
        print(f"✅ Company logo removed for {company.name}")
        
        return jsonify({
            'success': True,
            'message': 'Company logo removed successfully'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        print(f"❌ Error removing company logo: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


