def get_approval_count(admin_id):
    """Get number of approvals made by admin"""
    try:
        return User.query.filter_by(approved_by=admin_id, approval_status='approved').count()
    except:
        return 0

def get_admin_avg_approval_time(admin_id):
    """Get average approval time for admin"""
    try:
        users = User.query.filter_by(approved_by=admin_id, approval_status='approved').all()
        
        total_seconds = 0
        count = 0
        
        for user in users:
            if user.created_at and user.approved_at:
                diff = (user.approved_at - user.created_at).total_seconds()
                total_seconds += diff
                count += 1
        
        if count > 0:
            avg_seconds = total_seconds / count
            hours = int(avg_seconds // 3600)
            minutes = int((avg_seconds % 3600) // 60)
            return f"{hours}h {minutes}m"
        
        return "0h 0m"
        
    except:
        return "0h 0m"
