def extract_device_info(user_agent):
    """Extract device information from user agent string"""
    try:
        if not user_agent:
            return {}
        
        # Simple parsing - you can use a library like user-agents for better parsing
        ua = user_agent.lower()
        
        info = {
            'browser': 'Unknown',
            'browser_version': 'Unknown',
            'os': 'Unknown',
            'device_type': 'Desktop',
            'is_mobile': False,
            'is_tablet': False,
            'is_bot': False
        }
        
        # Check for bots
        if 'bot' in ua or 'crawler' in ua or 'spider' in ua:
            info['is_bot'] = True
            info['device_type'] = 'Bot'
            return info
        
        # Browser detection
        if 'chrome' in ua and 'edge' not in ua and 'opr' not in ua:
            info['browser'] = 'Chrome'
        elif 'firefox' in ua:
            info['browser'] = 'Firefox'
        elif 'safari' in ua and 'chrome' not in ua:
            info['browser'] = 'Safari'
        elif 'edge' in ua:
            info['browser'] = 'Edge'
        elif 'opera' in ua or 'opr' in ua:
            info['browser'] = 'Opera'
        
        # OS detection
        if 'windows' in ua:
            info['os'] = 'Windows'
        elif 'mac os' in ua or 'macintosh' in ua:
            info['os'] = 'macOS'
        elif 'linux' in ua:
            info['os'] = 'Linux'
        elif 'android' in ua:
            info['os'] = 'Android'
            info['device_type'] = 'Mobile'
            info['is_mobile'] = True
        elif 'iphone' in ua or 'ipad' in ua or 'ipod' in ua:
            info['os'] = 'iOS'
            if 'ipad' in ua:
                info['device_type'] = 'Tablet'
                info['is_tablet'] = True
            else:
                info['device_type'] = 'Mobile'
                info['is_mobile'] = True
        
        return info
        
    except Exception as e:
        logger.error(f"Error extracting device info: {e}")
        return {}

