@jwt_required
def logout():
    """Logout endpoint with tracking"""
    try:
        user_id = request.user_id  # Already available from jwt_required decorator
        login_log_id = get_jwt().get('login_log_id')
        
        # Track logout
        if login_log_id:
            session_duration = track_logout(login_log_id, user_id)
            
            # Track activity
            track_activity(
                user_id=user_id,
                activity_type='user_logout',
                description=f'User logged out. Session duration: {session_duration}s' if session_duration else 'User logged out',
                metadata={
                    'session_duration': session_duration,
                    'login_log_id': login_log_id
                }
            )
        
        # Remove session
        session_id = get_jwt().get('session_id')
        if session_id:
            UserSession.query.filter_by(session_id=session_id).delete()
            db.session.commit()
        
        logger.info(f"User {user_id} logged out successfully")
        
        return jsonify({
            'success': True,
            'message': 'Logged out successfully',
            'tracking_data': {
                'login_log_id': login_log_id,
                'session_duration': session_duration,
                'logout_time': datetime.utcnow().isoformat()
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Logout error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Logout failed'}), 500

def get_admin_permissions(user):
    """Determine permissions based on admin role/level"""
    base_permissions = ['dashboard_access', 'profile_management']
    
    # Role-based permissions
    role_permissions = {
        'System Administrator': ['user_management', 'system_config', 'analytics', 'admin_approval', 'billing', 'audit_logs'],
        'Hospital Administrator': ['user_management', 'analytics', 'reports', 'facility_management', 'compliance'],
        'IT Manager': ['system_config', 'user_management', 'api_management', 'integration'],
        'Safety Director': ['analytics', 'reports', 'compliance', 'audit_logs', 'risk_assessment'],
        'Compliance Manager': ['compliance', 'reports', 'audit_logs', 'document_management'],
        'Operations Manager': ['user_management', 'analytics', 'reports', 'workflow_management']
    }
    
    # Get admin role (prefer admin_role field, fall back to role)
    admin_role = getattr(user, 'admin_role', user.role)
    
    # Get permissions for the user's role
    permissions = role_permissions.get(admin_role, base_permissions)
    
    # Add subscription-based permissions
    subscription_plan = getattr(user, 'subscription_plan', 'custom_enterprise')
    if subscription_plan == 'custom_enterprise':
        permissions.extend(['enterprise_features', 'custom_integrations', 'priority_support', 'unlimited_users'])
    
    # Add super admin permissions if applicable
    if hasattr(user, 'admin_level') and user.admin_level == 'super':
        permissions.extend(['super_admin', 'all_permissions', 'system_settings', 'database_management'])
    
    return list(set(permissions))  # Remove duplicates


