@app.route('/api/admin/permissions', methods=['GET'])
@jwt_required
def get_permissions():
    """Get all permissions"""
    try:
        user = getattr(request, 'user', None)
        if not user:
            return jsonify({'success': False, 'error': 'User authentication failed'}), 401
        
        # Check if user has permission to view permissions
        if user.user_type != 'admin' and not user.is_system_team:
            return jsonify({'success': False, 'error': 'Unauthorized'}), 403
        
        # Get all permissions grouped by role
        permissions = Permission.query.filter(Permission.is_active == True).all()
        
        grouped = {}
        all_permissions = []
        
        for perm in permissions:
            if perm.role not in grouped:
                grouped[perm.role] = []
            grouped[perm.role].append(perm.permission_key)
            all_permissions.append({
                'key': perm.permission_key,
                'role': perm.role,
                'description': perm.description
            })
        
        # Get unique permissions
        unique_permissions = {}
        for perm in permissions:
            if perm.permission_key not in unique_permissions:
                unique_permissions[perm.permission_key] = {
                    'key': perm.permission_key,
                    'label': perm.permission_key.replace('_', ' ').title(),
                    'description': perm.description or ''
                }
        
        return jsonify({
            'success': True,
            'permissions': grouped,
            'all_permissions': list(unique_permissions.values())
        }), 200
        
    except Exception as e:
        print(f"❌ ERROR in get_permissions: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/permissions', methods=['POST'])
@jwt_required
def save_permissions():
    """Save permissions for roles"""
    try:
        user = getattr(request, 'user', None)
        if not user:
            return jsonify({'success': False, 'error': 'User authentication failed'}), 401
        
        # Check if user has permission to manage permissions
        if user.user_type != 'admin' and not user.is_system_team:
            return jsonify({'success': False, 'error': 'Unauthorized'}), 403
        
        data = request.get_json()
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400
        
        permissions_data = data.get('permissions', {})
        
        # Delete existing permissions
        Permission.query.delete()
        
        # Insert new permissions
        for role, perm_keys in permissions_data.items():
            for perm_key in perm_keys:
                new_perm = Permission(
                    role=role,
                    permission_key=perm_key,
                    is_active=True
                )
                db.session.add(new_perm)
        
        db.session.commit()
        
        # Log the action
        log_admin_action(
            user_id=user.id,
            action=f"Updated permissions for {len(permissions_data)} roles",
            resource_type='permissions',
            details=f"Updated by {user.email}"
        )
        
        return jsonify({
            'success': True,
            'message': 'Permissions saved successfully'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        print(f"❌ ERROR in save_permissions: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/user-role', methods=['POST'])
@jwt_required
def assign_user_role():
    """Assign a role to a user"""
    try:
        user = getattr(request, 'user', None)
        if not user:
            return jsonify({'success': False, 'error': 'User authentication failed'}), 401
        
        if user.user_type != 'admin' and not user.is_system_team:
            return jsonify({'success': False, 'error': 'Unauthorized'}), 403
        
        data = request.get_json()
        user_id = data.get('user_id')
        role_name = data.get('role')
        
        if not user_id or not role_name:
            return jsonify({'success': False, 'error': 'Missing user_id or role'}), 400
        
        target_user = User.query.get(user_id)
        if not target_user:
            return jsonify({'success': False, 'error': 'User not found'}), 404
        
        role = Role.query.filter_by(name=role_name).first()
        if not role:
            return jsonify({'success': False, 'error': 'Role not found'}), 404
        
        # Check if user already has this role
        existing = UserRole.query.filter_by(user_id=user_id, role_id=role.id).first()
        if existing:
            return jsonify({'success': False, 'error': 'User already has this role'}), 400
        
        # Assign role
        user_role = UserRole(
            user_id=user_id,
            role_id=role.id,
            assigned_by=user.id
        )
        db.session.add(user_role)
        
        # Update user's role field for backward compatibility
        target_user.role = role_name
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Role {role_name} assigned to user {target_user.email}'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        print(f"❌ ERROR in assign_user_role: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/employees', methods=['GET', 'OPTIONS'])
@app.route('/api/admin/users', methods=['GET', 'OPTIONS'])
@jwt_required
def admin_employees():
    """Get employees list for admin dashboard - with company plan inheritance"""
    try:
        # Handle OPTIONS request
        if request.method == 'OPTIONS':
            response = jsonify({'status': 'ok'})
            return response, 200

        # Check if user is admin or super admin
        current_user = request.user
        if current_user.user_type not in ['admin', 'super_admin', 'platform_owner']:
            return jsonify({'error': 'Admin access required'}), 403
            
        # ✅ Get admin's company
        if current_user.company_id:
            admin_company_id = current_user.company_id
            admin_company = Company.query.get(admin_company_id)
        else:
            return jsonify({'error': 'Admin has no company associated'}), 400
        
        if not admin_company:
            return jsonify({'error': 'Company not found'}), 404
        
        # ✅ Get query parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 10, type=int)
        search = request.args.get('search', '', type=str)
        department = request.args.get('department', '', type=str)
        status = request.args.get('status', 'all', type=str)

        # ✅ Build query for employees from the same company
        query = User.query.filter_by(company_id=admin_company_id)
        
        # ✅ Exclude admins and company owners from employee list
        query = query.filter(User.user_type != 'admin')
        query = query.filter(User.user_type != 'platform_owner')
        query = query.filter(User.user_type != 'super_admin')

        # Apply search filter
        if search:
            search_filter = (
                User.name.ilike(f'%{search}%') |
                User.email.ilike(f'%{search}%') |
                User.role.ilike(f'%{search}%')
            )
            query = query.filter(search_filter)

        # Apply department filter
        if department:
            query = query.filter(User.department == department)
        
        # Apply status filter
        if status == 'active':
            query = query.filter(User.is_active == True)
        elif status == 'inactive':
            query = query.filter(User.is_active == False)

        # Get paginated results
        employees = query.order_by(User.created_at.desc()).paginate(
            page=page, 
            per_page=per_page, 
            error_out=False
        )

        # ✅ Get company plan - using 'plan' (not 'subscription_plan')
        company_plan = admin_company.plan or 'enterprise'
        company_status = admin_company.subscription_status or 'active'
        
        # ✅ Sync employee plans with company plan
        synced_count = 0
        for employee in employees.items:
            if employee.subscription_plan != company_plan:
                employee.subscription_plan = company_plan
                employee.subscription_status = company_status
                employee.billing_cycle = admin_company.billing_cycle
                synced_count += 1
        
        if synced_count > 0:
            db.session.commit()
            logger.info(f"🔄 Synced {synced_count} employees to company plan: {company_plan}")

        # Format response
        employees_data = []
        for employee in employees.items:
            employees_data.append({
                'id': employee.id,
                'name': employee.name,
                'email': employee.email,
                'role': employee.role,
                'department': employee.department,
                'phone': employee.phone,
                'country': employee.country,
                'company_id': employee.company_id,
                'company_name': employee.company_name,
                'subscription_plan': employee.subscription_plan,
                'subscription_status': employee.subscription_status,
                'created_at': employee.created_at.isoformat() if employee.created_at else None,
                'last_login': employee.last_login.isoformat() if employee.last_login else None,
                'is_active': employee.is_active,
                'verified': employee.verified,
                'user_type': employee.user_type,
                'approved': employee.approval_status == 'approved'
            })

        return jsonify({
            'success': True,
            'data': employees_data,
            'company': {
                'id': admin_company.id,
                'name': admin_company.name,
                'plan': company_plan,
                'status': company_status
            },
            'synced_count': synced_count,
            'pagination': {
                'page': page,
                'per_page': per_page,
                'total': employees.total,
                'pages': employees.pages
            }
        }), 200

    except Exception as e:
        logger.error(f"Admin employees endpoint error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': 'Failed to fetch employees data'}), 500
    
@app.route('/api/admin/stats', methods=['GET', 'OPTIONS'])
@jwt_required
def admin_stats():
    """Get admin dashboard statistics"""
    try:
        if request.method == 'OPTIONS':
            return jsonify({'status': 'ok'}), 200

        # Check if user is customer admin
        if request.user_type != 'admin':
            return jsonify({'error': 'Admin access required'}), 403
            
        # Get customer admin's company
        admin_company = request.user.company_name

        # Calculate statistics for the admin's company only
        query = User.query.filter_by(company_name=admin_company)
        total_users = query.count()
        total_admins = query.filter_by(user_type='admin').count()
        total_employees = query.filter_by(user_type='employee').count()
        total_regular_users = query.filter_by(user_type='user').count()
        
        active_users = query.filter_by(is_active=True).count()
        verified_users = query.filter_by(verified=True).count()

        # Recent registrations (last 7 days)
        week_ago = datetime.utcnow() - timedelta(days=7)
        recent_registrations = query.filter(User.created_at >= week_ago).count()

        return jsonify({
            'stats': {
                'total_users': total_users,
                'total_admins': total_admins,
                'total_employees': total_employees,
                'total_regular_users': total_regular_users,
                'active_users': active_users,
                'verified_users': verified_users,
                'recent_registrations': recent_registrations
            }
        }), 200

    except Exception as e:
        logger.error(f"Admin stats endpoint error: {str(e)}")
        return jsonify({'error': 'Failed to fetch statistics'}), 500

