@app.route('/api/admin/users/all', methods=['GET'])
@jwt_required  # ✅ Your custom decorator
def admin_get_all_users():
    """
    Get ALL users across all companies (Super Admin only)
    """
    try:
        # ✅ Use request.user (set by your custom jwt_required decorator)
        current_user = request.user
        
        if not current_user:
            return jsonify({'error': 'User not found'}), 404
        
        # ✅ SUPER ADMIN CHECK
        is_super_admin = (
            current_user.user_type in ['platform_owner', 'super_admin', 'safetypro'] or
            getattr(current_user, 'is_platform_owner', False) or
            getattr(current_user, 'is_super_admin', False) or
            getattr(current_user, 'admin_level', '') == 'super' or
            current_user.email.lower() in ['abigalisticstudious@gmail.com', 'Abigalisticstudious@gmail.com']
        )
        
        if not is_super_admin:
            logger.warning(f"❌ Super admin access denied for user: {current_user.email}")
            return jsonify({'error': 'Super admin access required'}), 403
        
        logger.info(f"✅ Super admin access granted for: {current_user.email}")

        # Pagination parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        
        # Filter parameters
        user_type = request.args.get('user_type')  # filter by user_type
        plan = request.args.get('plan')  # filter by subscription_plan
        status = request.args.get('status')  # active/inactive/pending/approved/rejected
        search = request.args.get('search')  # search by name/email/company
        company = request.args.get('company')  # filter by company name
        country = request.args.get('country')  # filter by country
        date_from = request.args.get('date_from')  # created after this date
        date_to = request.args.get('date_to')  # created before this date
        
        # Sorting parameters
        sort_by = request.args.get('sort_by', 'created_at')
        sort_order = request.args.get('sort_order', 'desc')

        # Build query - NO COMPANY FILTER - get ALL users
        query = User.query

        # Apply filters
        if user_type and user_type != 'all':
            if ',' in user_type:
                user_types = user_type.split(',')
                query = query.filter(User.user_type.in_(user_types))
            else:
                query = query.filter_by(user_type=user_type)
        
        if plan and plan != 'all':
            if ',' in plan:
                plans = plan.split(',')
                query = query.filter(User.subscription_plan.in_(plans))
            else:
                query = query.filter_by(subscription_plan=plan)
        
        if status and status != 'all':
            if status == 'active':
                query = query.filter_by(is_active=True)
            elif status == 'inactive':
                query = query.filter_by(is_active=False)
            elif status in ['pending', 'approved', 'rejected']:
                query = query.filter_by(approval_status=status)
        
        if company:
            query = query.filter(User.company_name.ilike(f'%{company}%'))
        
        if country and country != 'all':
            query = query.filter_by(country=country)
        
        if date_from:
            date_from_obj = datetime.strptime(date_from, '%Y-%m-%d')
            query = query.filter(User.created_at >= date_from_obj)
        
        if date_to:
            date_to_obj = datetime.strptime(date_to, '%Y-%m-%d') + timedelta(days=1)
            query = query.filter(User.created_at <= date_to_obj)
        
        if search:
            search_term = f'%{search}%'
            query = query.filter(
                or_(
                    User.name.ilike(search_term),
                    User.email.ilike(search_term),
                    User.company_name.ilike(search_term)
                )
            )

        # Apply sorting
        sort_columns = {
            'name': User.name,
            'email': User.email,
            'created_at': User.created_at,
            'last_login': User.last_login,
            'user_type': User.user_type,
            'subscription_plan': User.subscription_plan,
            'approval_status': User.approval_status,
            'is_active': User.is_active,
            'company_name': User.company_name,
            'country': User.country
        }
        
        sort_column = sort_columns.get(sort_by, User.created_at)
        
        if sort_order == 'asc':
            query = query.order_by(sort_column.asc())
        else:
            query = query.order_by(sort_column.desc())

        # Get total count before pagination
        total_count = query.count()

        # Apply pagination
        users = query.offset((page - 1) * per_page).limit(per_page).all()

        # Format user data
        users_data = []
        for user in users:
            users_data.append({
                'id': user.id,
                'name': user.name,
                'email': user.email,
                'user_type': user.user_type,
                'subscription_plan': user.subscription_plan,
                'approval_status': user.approval_status,
                'is_active': user.is_active,
                'is_verified': getattr(user, 'is_verified', False),
                'email_verified': getattr(user, 'email_verified', False),
                'company_name': user.company_name,
                'country': user.country,
                'phone': user.phone,
                'role': user.role,
                'industry': user.industry,
                'department': user.department,
                'employee_count': user.employee_count,
                'created_at': user.created_at.isoformat() if user.created_at else None,
                'last_login': user.last_login.isoformat() if user.last_login else None,
                'login_count': user.login_count,
                'documents_uploaded': getattr(user, 'documents_uploaded', False),
                'documents_verified': getattr(user, 'documents_verified', False),
                'billing_cycle': getattr(user, 'billing_cycle', '1_month'),
                'trial_ends_at': user.trial_ends_at.isoformat() if user.trial_ends_at else None,
                
                # Admin specific fields
                'admin_level': getattr(user, 'admin_level', 'standard'),
                'admin_tier': getattr(user, 'admin_tier', 'company'),
                'is_platform_owner': getattr(user, 'is_platform_owner', False),
                'is_system_team': getattr(user, 'is_system_team', False),
                
                # Stats
                'documents_count': Document.query.filter_by(user_id=user.id).count() if has_document_model() else 0,
                'api_calls_count': APIUsage.query.filter_by(user_id=user.id).count() if has_api_usage_model() else 0
            })

        return jsonify({
            'success': True,
            'data': {
                'users': users_data,
                'pagination': {
                    'current_page': page,
                    'per_page': per_page,
                    'total': total_count,
                    'pages': (total_count + per_page - 1) // per_page,
                    'has_next': page * per_page < total_count,
                    'has_prev': page > 1
                }
            },
            'filters_applied': {
                'user_type': user_type,
                'plan': plan,
                'status': status,
                'search': search,
                'company': company,
                'country': country,
                'date_from': date_from,
                'date_to': date_to
            }
        }), 200

    except Exception as e:
        logger.error(f"Error in admin_get_all_users: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/users/company/<string:company_name>', methods=['GET'])
@jwt_required
def admin_get_company_users(company_name):
    """Get users for a specific company (Admin access required)"""
    try:
        current_user = User.query.get(request.user_id)
        if not current_user:
            return jsonify({'error': 'User not found'}), 404
            
        # Check if user has admin privileges
        if current_user.user_type not in ['admin', 'platform_owner', 'system', 'safetypro']:
            return jsonify({'error': 'Admin access required'}), 403

        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        
        # Get users for the specified company
        query = User.query.filter_by(company_name=company_name)
        
        # Apply additional filters
        status = request.args.get('status')
        if status == 'active':
            query = query.filter_by(is_active=True)
        elif status == 'inactive':
            query = query.filter_by(is_active=False)
        elif status in ['pending', 'approved', 'rejected']:
            query = query.filter_by(approval_status=status)
        
        # Paginate
        total = query.count()
        users = query.order_by(User.created_at.desc()).offset((page - 1) * per_page).limit(per_page).all()

        users_data = [{
            'id': u.id,
            'name': u.name,
            'email': u.email,
            'user_type': u.user_type,
            'subscription_plan': u.subscription_plan,
            'approval_status': u.approval_status,
            'is_active': u.is_active,
            'created_at': u.created_at.isoformat() if u.created_at else None,
            'last_login': u.last_login.isoformat() if u.last_login else None
        } for u in users]

        return jsonify({
            'success': True,
            'data': {
                'company': company_name,
                'users': users_data,
                'pagination': {
                    'current_page': page,
                    'per_page': per_page,
                    'total': total,
                    'pages': (total + per_page - 1) // per_page
                }
            }
        }), 200

    except Exception as e:
        logger.error(f"Error in admin_get_company_users: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/users/stats/overview', methods=['GET'])
@jwt_required
def admin_get_users_stats_overview():
    """Get comprehensive user statistics overview (Super Admin only)"""
    try:
        current_user = User.query.get(request.user_id)
        if not current_user:
            return jsonify({'error': 'User not found'}), 404
            
        if current_user.user_type not in ['platform_owner', 'system', 'safetypro']:
            return jsonify({'error': 'Super admin access required'}), 403

        # Total counts
        total_users = User.query.count()
        total_active = User.query.filter_by(is_active=True).count()
        total_inactive = User.query.filter_by(is_active=False).count()
        
        # Approval status counts
        pending_approvals = User.query.filter_by(approval_status='pending').count()
        approved_users = User.query.filter_by(approval_status='approved').count()
        rejected_users = User.query.filter_by(approval_status='rejected').count()
        
        # User type breakdown
        user_types = {}
        for ut in ['user', 'employee', 'admin', 'safetypro', 'platform_owner', 'system']:
            count = User.query.filter_by(user_type=ut).count()
            if count > 0:
                user_types[ut] = count
        
        # Plan breakdown
        plan_distribution = {}
        for plan in ['free', 'basic', 'pro', 'enterprise', 'custom']:
            count = User.query.filter_by(subscription_plan=plan).count()
            if count > 0:
                plan_distribution[plan] = count
        
        # Recent signups (last 30 days)
        thirty_days_ago = datetime.utcnow() - timedelta(days=30)
        recent_signups = User.query.filter(User.created_at >= thirty_days_ago).count()
        
        # Active today
        today_start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        active_today = User.query.filter(User.last_login >= today_start).count()
        
        # Company distribution
        top_companies = db.session.query(
            User.company_name, 
            func.count(User.id).label('count')
        ).filter(
            User.company_name.isnot(None),
            User.company_name != ''
        ).group_by(User.company_name).order_by(func.count(User.id).desc()).limit(10).all()
        
        # Country distribution
        country_distribution = db.session.query(
            User.country, 
            func.count(User.id).label('count')
        ).filter(
            User.country.isnot(None),
            User.country != ''
        ).group_by(User.country).order_by(func.count(User.id).desc()).all()

        return jsonify({
            'success': True,
            'data': {
                'totals': {
                    'all': total_users,
                    'active': total_active,
                    'inactive': total_inactive
                },
                'approvals': {
                    'pending': pending_approvals,
                    'approved': approved_users,
                    'rejected': rejected_users
                },
                'user_types': user_types,
                'plan_distribution': plan_distribution,
                'activity': {
                    'recent_signups_30d': recent_signups,
                    'active_today': active_today,
                    'active_7d': User.query.filter(User.last_login >= thirty_days_ago - timedelta(days=23)).count()
                },
                'demographics': {
                    'top_companies': [{'name': c[0], 'count': c[1]} for c in top_companies],
                    'country_distribution': [{'country': c[0], 'count': c[1]} for c in country_distribution]
                }
            }
        }), 200

    except Exception as e:
        logger.error(f"Error in admin_get_users_stats_overview: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/users/<int:user_id>/full-details', methods=['GET'])
@jwt_required
def admin_get_user_full_details(user_id):
    """Get comprehensive details for a specific user (Admin only)"""
    try:
        current_user = User.query.get(request.user_id)
        if not current_user:
            return jsonify({'error': 'User not found'}), 404
            
        if current_user.user_type not in ['admin', 'platform_owner', 'system', 'safetypro']:
            return jsonify({'error': 'Admin access required'}), 403

        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        # Get user's documents
        documents = []
        if has_document_model():
            docs = Document.query.filter_by(user_id=user_id).order_by(Document.uploaded_at.desc()).limit(20).all()
            documents = [{
                'id': d.id,
                'filename': d.filename,
                'originalname': d.originalname,
                'uploaded_at': d.uploaded_at.isoformat() if d.uploaded_at else None,
                'file_size': d.file_size,
                'doc_type': d.doc_type
            } for d in docs]

        # Get recent activity
        recent_activity = []
        if has_audit_log_model():
            logs = AdminAuditLog.query.filter_by(user_id=user_id).order_by(AdminAuditLog.timestamp.desc()).limit(20).all()
            recent_activity = [{
                'id': log.id,
                'action': log.action,
                'resource_type': log.resource_type,
                'timestamp': log.timestamp.isoformat() if log.timestamp else None,
                'ip_address': log.ip_address
            } for log in logs]

        # Get subscription history
        subscriptions = []
        if has_subscription_model():
            subs = Subscription.query.filter_by(user_id=user_id).order_by(Subscription.start_date.desc()).all()
            subscriptions = [{
                'id': s.id,
                'plan': s.plan,
                'status': s.status,
                'start_date': s.start_date.isoformat() if s.start_date else None,
                'end_date': s.end_date.isoformat() if s.end_date else None,
                'auto_renew': s.auto_renew
            } for s in subs]

        # Get payment history
        payments = []
        if has_payment_model():
            pays = Payment.query.filter_by(user_id=user_id).order_by(Payment.created_at.desc()).limit(20).all()
            payments = [{
                'id': p.id,
                'amount': p.amount,
                'currency': p.currency,
                'plan': p.plan,
                'status': p.status,
                'created_at': p.created_at.isoformat() if p.created_at else None
            } for p in pays]

        # Calculate usage statistics
        current_month = datetime.utcnow().month
        current_year = datetime.utcnow().year
        
        monthly_uploads = Document.query.filter(
            Document.user_id == user_id,
            db.extract('month', Document.uploaded_at) == current_month,
            db.extract('year', Document.uploaded_at) == current_year
        ).count() if has_document_model() else 0
        
        monthly_api_calls = APIUsage.query.filter(
            APIUsage.user_id == user_id,
            db.extract('month', APIUsage.timestamp) == current_month,
            db.extract('year', APIUsage.timestamp) == current_year
        ).count() if has_api_usage_model() else 0

        return jsonify({
            'success': True,
            'data': {
                'user': {
                    'id': user.id,
                    'name': user.name,
                    'email': user.email,
                    'user_type': user.user_type,
                    'subscription_plan': user.subscription_plan,
                    'approval_status': user.approval_status,
                    'is_active': user.is_active,
                    'is_verified': getattr(user, 'is_verified', False),
                    'email_verified': getattr(user, 'email_verified', False),
                    'company_name': user.company_name,
                    'country': user.country,
                    'phone': user.phone,
                    'role': user.role,
                    'industry': user.industry,
                    'department': user.department,
                    'employee_count': user.employee_count,
                    'created_at': user.created_at.isoformat() if user.created_at else None,
                    'last_login': user.last_login.isoformat() if user.last_login else None,
                    'login_count': user.login_count,
                    'billing_cycle': getattr(user, 'billing_cycle', '1_month'),
                    'trial_ends_at': user.trial_ends_at.isoformat() if user.trial_ends_at else None,
                    
                    # Admin specific
                    'admin_level': getattr(user, 'admin_level', 'standard'),
                    'admin_tier': getattr(user, 'admin_tier', 'company'),
                    'is_platform_owner': getattr(user, 'is_platform_owner', False),
                    'is_system_team': getattr(user, 'is_system_team', False),
                    
                    # Document status
                    'documents_uploaded': getattr(user, 'documents_uploaded', False),
                    'documents_verified': getattr(user, 'documents_verified', False),
                    
                    # Usage stats
                    'monthly_uploads': monthly_uploads,
                    'monthly_api_calls': monthly_api_calls,
                    'total_documents': len(documents)
                },
                'documents': documents,
                'recent_activity': recent_activity,
                'subscriptions': subscriptions,
                'payments': payments
            }
        }), 200

    except Exception as e:
        logger.error(f"Error in admin_get_user_full_details: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500

# ==================== ADMIN AUDIT LOGS ENDPOINT ====================

@app.route('/api/admin/audit-logs', methods=['GET'], endpoint='admin_get_audit_logs')
@jwt_required
def admin_get_audit_logs():
    """Get audit logs (admin only)"""
    try:
        current_user = getattr(request, 'user', None)
        if not current_user:
            return jsonify({'success': False, 'error': 'User authentication failed'}), 401
        
        # Check if user has admin access
        if current_user.user_type != 'admin' and not current_user.is_system_team:
            return jsonify({'success': False, 'error': 'Unauthorized'}), 403
        
        # Get query parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        action = request.args.get('action')
        user_id = request.args.get('user_id')
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        search = request.args.get('search')
        
        # Build query
        query = AdminAuditLog.query
        
        # Apply filters
        if action and action != 'all':
            query = query.filter(AdminAuditLog.action.ilike(f'%{action}%'))
        
        if user_id and user_id != 'all':
            try:
                query = query.filter(AdminAuditLog.user_id == int(user_id))
            except:
                pass
        
        if start_date:
            try:
                start = datetime.strptime(start_date, '%Y-%m-%d')
                query = query.filter(AdminAuditLog.timestamp >= start)
            except:
                pass
        
        if end_date:
            try:
                end = datetime.strptime(end_date, '%Y-%m-%d') + timedelta(days=1)
                query = query.filter(AdminAuditLog.timestamp <= end)
            except:
                pass
        
        if search:
            query = query.filter(
                db.or_(
                    AdminAuditLog.action.ilike(f'%{search}%'),
                    AdminAuditLog.details.ilike(f'%{search}%'),
                    AdminAuditLog.resource_type.ilike(f'%{search}%')
                )
            )
        
        # Order by timestamp descending
        query = query.order_by(AdminAuditLog.timestamp.desc())
        
        # Paginate
        paginated = query.paginate(page=page, per_page=per_page, error_out=False)
        
        # Get user emails for display
        user_ids = [log.user_id for log in paginated.items]
        users = User.query.filter(User.id.in_(user_ids)).all() if user_ids else []
        user_map = {u.id: u for u in users}
        
        # Format response
        logs = []
        for log in paginated.items:
            user = user_map.get(log.user_id)
            logs.append({
                'id': log.id,
                'user': user.name if user else 'Unknown',
                'user_email': user.email if user else 'Unknown',
                'user_id': log.user_id,
                'action': log.action,
                'details': log.details or '',
                'resource_type': log.resource_type or '',
                'resource_id': log.resource_id,
                'timestamp': log.timestamp.isoformat() if log.timestamp else None,
                'ip_address': log.ip_address or '—',
                'status': 'success'  # Default status
            })
        
        # Get action counts for statistics
        action_counts = db.session.query(
            AdminAuditLog.action,
            db.func.count(AdminAuditLog.id)
        ).group_by(AdminAuditLog.action).all()
        
        # Get user counts
        user_activity = db.session.query(
            AdminAuditLog.user_id,
            db.func.count(AdminAuditLog.id)
        ).group_by(AdminAuditLog.user_id).order_by(db.func.count(AdminAuditLog.id).desc()).limit(10).all()
        
        user_activity_data = []
        for ua in user_activity:
            user = user_map.get(ua[0])
            if user:
                user_activity_data.append({
                    'user_id': ua[0],
                    'name': user.name,
                    'email': user.email,
                    'count': ua[1]
                })
        
        return jsonify({
            'success': True,
            'data': logs,
            'logs': logs,
            'pagination': {
                'page': page,
                'per_page': per_page,
                'total': paginated.total,
                'pages': paginated.pages
            },
            'statistics': {
                'total': paginated.total,
                'action_types': [{'action': a[0], 'count': a[1]} for a in action_counts],
                'top_users': user_activity_data
            }
        }), 200
        
    except Exception as e:
        print(f"❌ ERROR in admin_get_audit_logs: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/audit-logs', methods=['POST'], endpoint='admin_create_audit_log')
@jwt_required
def admin_create_audit_log():
    """Create an audit log entry (for internal use)"""
    try:
        current_user = getattr(request, 'user', None)
        if not current_user:
            return jsonify({'success': False, 'error': 'User authentication failed'}), 401
        
        data = request.get_json()
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400
        
        log = AdminAuditLog(
            user_id=current_user.id,
            action=data.get('action'),
            resource_type=data.get('resource_type'),
            resource_id=data.get('resource_id'),
            details=data.get('details'),
            ip_address=request.remote_addr,
            user_agent=request.headers.get('User-Agent')
        )
        
        db.session.add(log)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Audit log created',
            'id': log.id
        }), 201
        
    except Exception as e:
        db.session.rollback()
        print(f"❌ ERROR in admin_create_audit_log: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/audit-logs/export', methods=['GET'], endpoint='admin_export_audit_logs')
@jwt_required
def admin_export_audit_logs():
    """Export audit logs to CSV/Excel (admin only)"""
    try:
        current_user = getattr(request, 'user', None)
        if not current_user:
            return jsonify({'success': False, 'error': 'User authentication failed'}), 401
        
        if current_user.user_type != 'admin' and not current_user.is_system_team:
            return jsonify({'success': False, 'error': 'Unauthorized'}), 403
        
        # Get filters
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        action = request.args.get('action')
        format_type = request.args.get('format', 'csv')
        
        # Build query
        query = AdminAuditLog.query.order_by(AdminAuditLog.timestamp.desc())
        
        if start_date:
            try:
                start = datetime.strptime(start_date, '%Y-%m-%d')
                query = query.filter(AdminAuditLog.timestamp >= start)
            except:
                pass
        
        if end_date:
            try:
                end = datetime.strptime(end_date, '%Y-%m-%d') + timedelta(days=1)
                query = query.filter(AdminAuditLog.timestamp <= end)
            except:
                pass
        
        if action and action != 'all':
            query = query.filter(AdminAuditLog.action.ilike(f'%{action}%'))
        
        logs = query.all()
        
        # Get user names
        user_ids = [log.user_id for log in logs]
        users = User.query.filter(User.id.in_(user_ids)).all() if user_ids else []
        user_map = {u.id: u for u in users}
        
        # Prepare data for export
        export_data = []
        for log in logs:
            user = user_map.get(log.user_id)
            export_data.append({
                'Timestamp': log.timestamp.strftime('%Y-%m-%d %H:%M:%S') if log.timestamp else '',
                'User': user.name if user else 'Unknown',
                'Email': user.email if user else '',
                'Action': log.action,
                'Resource Type': log.resource_type or '',
                'Resource ID': log.resource_id or '',
                'Details': log.details or '',
                'IP Address': log.ip_address or ''
            })
        
        # For now, return JSON
        return jsonify({
            'success': True,
            'data': export_data,
            'count': len(export_data)
        }), 200
        
    except Exception as e:
        print(f"❌ ERROR in admin_export_audit_logs: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500

