@app.route('/api/admin/users', methods=['GET', 'OPTIONS'])
@jwt_required
def admin_get_users():
    """Admin endpoint to get all users"""
    try:
        if request.method == 'OPTIONS':
            return jsonify({'status': 'ok'}), 200

        # Get the requesting user
        current_user = User.query.get(request.user_id)
        
        if not current_user:
            return jsonify({'error': 'User not found'}), 404

        # Check if user is platform owner or super admin
        is_super_admin = current_user.user_type in ['platform_owner', 'system', 'safetypro']
        is_admin = current_user.user_type == 'admin'

        if not is_super_admin and not is_admin:
            return jsonify({'error': 'Admin access required'}), 403

        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        status_filter = request.args.get('status')
        search_query = request.args.get('search')
        sort_by = request.args.get('sort_by', 'created_at')
        sort_order = request.args.get('sort_order', 'desc')
        user_type_filter = request.args.get('user_type')
        plan_filter = request.args.get('plan')

        # Build base query
        if is_super_admin:
            # Super admins see all users
            query = User.query
        else:
            # Regular admins only see users in their company
            query = User.query.filter_by(company_name=current_user.company_name)

        # Apply filters
        if status_filter == 'active':
            query = query.filter_by(is_active=True)
        elif status_filter == 'inactive':
            query = query.filter_by(is_active=False)
            
        if user_type_filter and user_type_filter != 'all':
            query = query.filter_by(user_type=user_type_filter)
            
        if plan_filter and plan_filter != 'all':
            query = query.filter_by(subscription_plan=plan_filter)
            
        if search_query:
            search_filter = or_(
                User.name.ilike(f'%{search_query}%'),
                User.email.ilike(f'%{search_query}%'),
                User.company_name.ilike(f'%{search_query}%')
            )
            query = query.filter(search_filter)

        # Apply sorting
        sort_column = {
            'name': User.name,
            'last_login': User.last_login,
            'created_at': User.created_at,
            'email': User.email
        }.get(sort_by, User.created_at)
        
        if sort_order == 'asc':
            query = query.order_by(sort_column.asc())
        else:
            query = query.order_by(sort_column.desc())

        # Paginate results
        users = query.paginate(page=page, per_page=per_page, error_out=False)

        # Format user data
        users_data = []
        for user in users.items:
            users_data.append({
                'id': user.id,
                'name': user.name,
                'email': user.email,
                'role': user.role,
                'company_name': user.company_name,
                'country': user.country,
                'verified': user.verified,
                'is_active': user.is_active,
                'created_at': user.created_at.isoformat(),
                'last_login': user.last_login.isoformat() if user.last_login else None,
                'user_type': user.user_type,
                'subscription_plan': user.subscription_plan,
                'approval_status': user.approval_status
            })

        return jsonify({
            'users': users_data,
            'pagination': {
                'total': users.total,
                'pages': users.pages,
                'current_page': page,
                'per_page': per_page,
                'has_next': users.has_next,
                'has_prev': users.has_prev
            }
        }), 200

    except Exception as e:
        logger.error(f"Admin get users error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/admin/users/<int:user_id>', methods=['PUT', 'DELETE', 'OPTIONS'])
@jwt_required
def admin_update_user(user_id):
    """Update or delete user"""
    try:
        if request.method == 'OPTIONS':
            return jsonify({'status': 'ok'}), 200

        current_user = User.query.get(request.user_id)
        
        # Check if user is super admin (can access all users regardless of company)
        is_super_admin = current_user.user_type in ['platform_owner', 'system', 'safetypro']
        
        # For non-super admins, check if they are a regular admin
        if not is_super_admin and current_user.user_type != 'admin':
            return jsonify({'error': 'Admin access required'}), 403

        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        
        # Only enforce company check for regular admins, NOT for super admins
        if not is_super_admin:
            admin_company = current_user.company_name
            if user.company_name != admin_company:
                return jsonify({'error': 'Unauthorized access to user'}), 403
        
        # Don't allow deleting yourself
        if request.method == 'DELETE' and current_user.id == user_id:
            return jsonify({'error': 'Cannot delete your own account'}), 400
        
        # Protect super admins from being deleted by lower-level admins
        if request.method == 'DELETE' and user.user_type in ['platform_owner', 'system']:
            if current_user.user_type != 'platform_owner':
                return jsonify({'error': 'Cannot delete platform owner or system admin'}), 403

        if request.method == 'PUT':
            data = request.get_json()
            
            # Update user fields
            updatable_fields = ['name', 'email', 'role', 'company_name', 'country', 'department']
            for field in updatable_fields:
                if field in data:
                    setattr(user, field, data[field])
            
            if 'is_active' in data:
                user.is_active = data['is_active']

            db.session.commit()
            
            logger.info(f"Admin {current_user.email} updated user {user.email}")

            return jsonify({
                'success': True,
                'message': 'User updated successfully'
            }), 200

        elif request.method == 'DELETE':
            # Log the deletion
            logger.info(f"Admin {current_user.email} deleted user {user.email} (ID: {user.id})")
            
            db.session.delete(user)
            db.session.commit()

            return jsonify({
                'success': True,
                'message': f'User {user.email} deleted successfully'
            }), 200

    except Exception as e:
        logger.error(f"Admin update user error: {e}")
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

@app.route('/api/safetypro/users/<int:user_id>', methods=['DELETE', 'OPTIONS'])
@jwt_required
def safetypro_delete_user(user_id):
    """SafetyPro delete user - can delete any user"""
    try:
        if request.method == 'OPTIONS':
            return jsonify({'status': 'ok'}), 200

        current_user = User.query.get(request.user_id)
        
        # Check if user has safetypro or super admin privileges
        if current_user.user_type not in ['safetypro', 'platform_owner', 'system']:
            return jsonify({'error': 'SafetyPro access required'}), 403
        
        # Don't allow deleting yourself
        if current_user.id == user_id:
            return jsonify({'error': 'Cannot delete your own account'}), 400
        
        user_to_delete = User.query.get(user_id)
        if not user_to_delete:
            return jsonify({'error': 'User not found'}), 404
        
        # Protect platform owners
        if user_to_delete.user_type == 'platform_owner' and current_user.user_type != 'platform_owner':
            return jsonify({'error': 'Cannot delete platform owner'}), 403
        
        db.session.delete(user_to_delete)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'User {user_to_delete.email} deleted successfully'
        }), 200
        
    except Exception as e:
        logger.error(f"SafetyPro delete user error: {e}")
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

@app.route('/api/admin/approve/<int:admin_id>', methods=['POST'] , endpoint='approve_admin_account')
@jwt_required
def approve_admin(admin_id):
    """Approve a pending admin account"""
    try:
        # Check if user is customer admin
        if request.user_type != 'admin':
            return jsonify({'error': 'Admin access required'}), 403
            
        # Get customer admin's company
        admin_company = request.user.company_name

        approving_admin = request.user

        pending_admin = User.query.filter_by(
            id=admin_id, 
            user_type='admin', 
            approval_status='pending'
        ).first()

        if not pending_admin:
            return jsonify({'error': 'Pending admin not found'}), 404
            
        # Check if pending admin belongs to the same company
        if pending_admin.company_name != admin_company:
            return jsonify({'error': 'Unauthorized access to admin'}), 403

        # Approve the admin
        pending_admin.approval_status = 'approved'
        pending_admin.is_active = True
        pending_admin.approved_at = datetime.utcnow()
        pending_admin.approved_by = approving_admin.id

        db.session.commit()

        # Send approval notification email
        try:
            send_admin_approval_confirmation(pending_admin.email, pending_admin.name)
        except Exception as e:
            logger.error(f"Failed to send approval email: {e}")

        logger.info(f"Admin {pending_admin.email} approved by {approving_admin.email}")

        return jsonify({'message': 'Admin account approved successfully'}), 200

    except Exception as e:
        logger.error(f"Approve admin error: {e}")
        db.session.rollback()
        return jsonify({'error': 'Internal server error'}), 500

