def get_user_company_id(user):
    """Get user's company_id safely"""
    if not user:
        return None
    company_id = getattr(user, 'company_id', None)
    if not company_id and hasattr(user, 'company') and user.company:
        company_id = user.company.id
    return company_id

def get_scope(query, model, user, is_super_admin=False):
    """Apply company/user scope filter to query"""
    if is_super_admin:
        return query
    
    company_id = get_user_company_id(user)
    if company_id:
        return query.filter_by(company_id=company_id)
    else:
        return query.filter_by(user_id=user.id)

def check_access(record, user, is_super_admin=False):
    """Check if user can access a record"""
    if is_super_admin:
        return True
    
    company_id = get_user_company_id(user)
    if company_id:
        if hasattr(record, 'company_id') and record.company_id == company_id:
            return True
        if hasattr(record, 'user_id') and record.user_id == user.id:
            return True
        return False
    else:
        if hasattr(record, 'user_id') and record.user_id == user.id:
            return True
        return False

def validate_device_id(device_id):
    if not device_id or len(device_id.strip()) < 2:
        return False, "Device ID must be at least 2 characters"
    if len(device_id) > 64:
        return False, "Device ID must be less than 64 characters"
    import re
    if not re.match(r'^[a-zA-Z0-9\-_]+$', device_id):
        return False, "Device ID can only contain letters, numbers, hyphens, and underscores"
    return True, device_id.strip()

def validate_name(name):
    if not name or len(name.strip()) < 2:
        return False, "Name must be at least 2 characters"
    if len(name) > 100:
        return False, "Name must be less than 100 characters"
    return True, name.strip()

def check_super_admin():
    try:
        current_user = request.user
        if not current_user:
            return False
        return getattr(current_user, 'is_super_admin', False)
    except:
        return False

