# ============================================================================
# HELPER FUNCTIONS - NO COMPANY CREATION
# ============================================================================

def get_user_company_or_user_id(user):
    """
    Get user's company_id if they have one, otherwise return user_id for filtering.
    Returns: (filter_field, filter_value, filter_type)
    """
    if not user:
        return None, None, None
    
    company_id = getattr(user, 'company_id', None)
    
    if company_id:
        return 'company_id', company_id, 'company'
    else:
        return 'user_id', user.id, 'user'

def apply_data_filter(query, model, user, is_super_admin=False):
    """
    Apply filter to query based on user's company or user_id.
    Super admin sees all data.
    """
    if is_super_admin:
        return query
    
    company_id = getattr(user, 'company_id', None)
    
    if company_id:
        # User belongs to a company - filter by company
        return query.filter_by(company_id=company_id)
    else:
        # User has no company - filter by user_id
        return query.filter_by(user_id=user.id)

def check_data_access(model_instance, user, is_super_admin=False):
    """
    Check if user has access to a specific data instance.
    Returns True if user can access, False otherwise.
    """
    if is_super_admin:
        return True
    
    company_id = getattr(user, 'company_id', None)
    
    if company_id:
        # User belongs to a company - check if data belongs to same company
        if hasattr(model_instance, 'company_id'):
            return model_instance.company_id == company_id
        elif hasattr(model_instance, 'user_id'):
            return model_instance.user_id == user.id
        return False
    else:
        # User has no company - check if data belongs to user
        if hasattr(model_instance, 'user_id'):
            return model_instance.user_id == user.id
        return False

