@app.route('/api/environmental/water-quality/samples/<int:sample_id>', methods=['PUT'])
@jwt_required
def update_water_quality_sample(sample_id):
    """Update a water quality sample with validation"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # Get sample with permission check
        if is_super_admin:
            sample = WaterSample.query.get(sample_id)
        else:
            sample = WaterSample.query.filter_by(
                id=sample_id,
                company_id=current_user.company_id or 1
            ).first()
        
        if not sample:
            return jsonify({
                'success': False,
                'error': 'Sample not found or you do not have permission to update it',
                'code': 'SAMPLE_NOT_FOUND'
            }), 404
        
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA'
            }), 400
        
        # ==================== COMPREHENSIVE VALIDATION ====================
        changes = []
        
        # Validate numeric parameters
        numeric_fields = {
            'temperature': (0, 50),
            'ph': (0, 14),
            'turbidity': (0, 1000),
            'conductivity': (0, 5000),
            'tds': (0, 3000),
            'dissolved_oxygen': (0, 20),
            'bod': (0, 100),
            'cod': (0, 500),
            'lead': (0, 0.1),
            'mercury': (0, 0.01),
            'arsenic': (0, 0.1)
        }
        
        for field, (min_val, max_val) in numeric_fields.items():
            if field in data and data[field] is not None:
                try:
                    value = float(data[field])
                    if value < min_val or value > max_val:
                        return jsonify({
                            'success': False,
                            'error': f'{field} must be between {min_val} and {max_val}',
                            'code': 'INVALID_RANGE'
                        }), 400
                    if getattr(sample, field) != value:
                        changes.append(f'{field}: {getattr(sample, field)} -> {value}')
                    setattr(sample, field, value)
                except (ValueError, TypeError):
                    return jsonify({
                        'success': False,
                        'error': f'Invalid value for {field}. Must be a number',
                        'code': 'INVALID_NUMBER'
                    }), 400
        
        # Validate coliform count
        if 'coliform_count' in data:
            try:
                coliform_count = int(data['coliform_count'])
                if coliform_count < 0:
                    return jsonify({
                        'success': False,
                        'error': 'Coliform count cannot be negative',
                        'code': 'INVALID_COLIFORM'
                    }), 400
                if sample.coliform_count != coliform_count:
                    changes.append(f'coliform_count: {sample.coliform_count} -> {coliform_count}')
                sample.coliform_count = coliform_count
            except (ValueError, TypeError):
                return jsonify({
                    'success': False,
                    'error': 'Invalid coliform count. Must be an integer',
                    'code': 'INVALID_COLIFORM'
                }), 400
        
        # Validate E. coli
        if 'e_coli' in data:
            if not isinstance(data['e_coli'], bool):
                return jsonify({
                    'success': False,
                    'error': 'e_coli must be a boolean',
                    'code': 'INVALID_BOOLEAN'
                }), 400
            if sample.e_coli != data['e_coli']:
                changes.append(f'e_coli: {sample.e_coli} -> {data["e_coli"]}')
            sample.e_coli = data['e_coli']
        
        # Validate compliance
        if 'compliant' in data:
            if not isinstance(data['compliant'], bool):
                return jsonify({
                    'success': False,
                    'error': 'compliant must be a boolean',
                    'code': 'INVALID_BOOLEAN'
                }), 400
            if sample.compliant != data['compliant']:
                changes.append(f'compliant: {sample.compliant} -> {data["compliant"]}')
            sample.compliant = data['compliant']
        
        # Validate violations
        if 'violations' in data:
            violations = data['violations'].strip() if data['violations'] else ''
            if len(violations) > 1000:
                return jsonify({
                    'success': False,
                    'error': 'Violations must be less than 1000 characters',
                    'code': 'VIOLATIONS_TOO_LONG'
                }), 400
            if sample.violations != violations:
                changes.append('violations')
            sample.violations = violations
        
        # Validate notes
        if 'notes' in data:
            notes = data['notes'].strip() if data['notes'] else ''
            if len(notes) > 2000:
                return jsonify({
                    'success': False,
                    'error': 'Notes must be less than 2000 characters',
                    'code': 'NOTES_TOO_LONG'
                }), 400
            if sample.notes != notes:
                changes.append('notes')
            sample.notes = notes
        
        # Validate lab report URL
        if 'lab_report_url' in data:
            lab_report_url = data['lab_report_url'].strip() if data['lab_report_url'] else ''
            if lab_report_url and len(lab_report_url) > 500:
                return jsonify({
                    'success': False,
                    'error': 'Lab report URL must be less than 500 characters',
                    'code': 'URL_TOO_LONG'
                }), 400
            if sample.lab_report_url != lab_report_url:
                changes.append('lab_report_url')
            sample.lab_report_url = lab_report_url
        
        if not changes:
            return jsonify({
                'success': False,
                'error': 'No valid fields to update',
                'code': 'NO_VALID_FIELDS'
            }), 400
        
        sample.updated_at = datetime.utcnow()
        db.session.commit()
        
        current_app.logger.info(f"✅ Water sample {sample_id} updated. Changes: {', '.join(changes)}")
        
        return jsonify({
            'success': True,
            'message': 'Water sample updated successfully',
            'changes': changes,
            'sample': {
                'id': sample.id,
                'site_id': sample.site_id,
                'compliant': sample.compliant,
                'updated_at': sample.updated_at.isoformat() if sample.updated_at else None
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error updating water sample {sample_id}: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to update water sample',
            'details': str(e) if app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


