@app.route('/api/environmental/air-quality/sensors', methods=['GET'])
@jwt_required
def get_air_quality_sensors():
    try:
        user = request.user
        is_super = check_super_admin()
        
        query = AirQualitySensor.query
        query = get_scope(query, AirQualitySensor, user, is_super)
        
        # Filters
        status = request.args.get('status')
        if status and status != 'all':
            query = query.filter_by(status=status)
        
        sensor_type = request.args.get('type')
        if sensor_type:
            query = query.filter_by(sensor_type=sensor_type)
        
        search = request.args.get('search', '').strip()
        if search:
            query = query.filter(
                db.or_(
                    AirQualitySensor.name.ilike(f'%{search}%'),
                    AirQualitySensor.device_id.ilike(f'%{search}%'),
                    AirQualitySensor.location.ilike(f'%{search}%')
                )
            )
        
        sensors = query.order_by(AirQualitySensor.created_at.desc()).all()
        
        return jsonify({
            'success': True,
            'sensors': [s.to_dict() for s in sensors],
            'total': len(sensors)
        }), 200
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

