@app.route('/api/environmental/air-quality/sensors', methods=['POST'])
@jwt_required
def create_air_quality_sensor():
    try:
        user = request.user
        is_super = check_super_admin()
        
        data = request.get_json()
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400
        
        # Validate
        valid, msg = validate_device_id(data.get('device_id'))
        if not valid:
            return jsonify({'success': False, 'error': msg}), 400
        
        valid, msg = validate_name(data.get('name'))
        if not valid:
            return jsonify({'success': False, 'error': msg}), 400
        
        # Check duplicate
        company_id = get_user_company_id(user)
        if company_id:
            existing = AirQualitySensor.query.filter_by(device_id=data['device_id'], company_id=company_id).first()
        else:
            existing = AirQualitySensor.query.filter_by(device_id=data['device_id'], user_id=user.id).first()
        
        if existing:
            return jsonify({'success': False, 'error': 'Device ID already exists'}), 400
        
        # Create
        sensor = AirQualitySensor(
            device_id=data['device_id'].strip(),
            name=data['name'].strip(),
            sensor_type=data.get('sensor_type', 'air_quality'),
            location=data.get('location', ''),
            latitude=data.get('latitude'),
            longitude=data.get('longitude'),
            min_range=data.get('min_range', 0),
            max_range=data.get('max_range', 500),
            unit=data.get('unit', 'AQI'),
            compliance_score=data.get('compliance_score', 100),
            status=data.get('status', 'active'),
            department=data.get('department', ''),
            user_id=user.id,
            company_id=company_id
        )
        
        db.session.add(sensor)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Sensor created',
            'sensor': sensor.to_dict()
        }), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500
