@app.route('/api/ai/environmental/thermal-comfort', methods=['POST'])
@jwt_required
def thermal_comfort_endpoint():
    """Get thermal comfort logs or calculate thermal comfort"""
    try:
        data = request.get_json() or {}
        location_id = data.get('location_id')
        
        # If we're just fetching logs
        if data.get('fetch_logs'):
            query = ThermalComfortLog.query
            if location_id:
                query = query.filter_by(location_id=location_id)
            
            logs = query.order_by(ThermalComfortLog.measurement_time.desc()).limit(20).all()
            
            logs_data = []
            for log in logs:
                logs_data.append({
                    'id': log.id,
                    'location_id': log.location_id,
                    'air_temperature': log.air_temperature,
                    'relative_humidity': log.relative_humidity,
                    'heat_index': log.heat_index,
                    'predicted_mean_vote': log.predicted_mean_vote,
                    'comfort_level': log.comfort_level,
                    'thermal_sensation': log.thermal_sensation,
                    'measurement_time': log.measurement_time.isoformat() if log.measurement_time else None
                })
            
            return jsonify({
                'success': True,
                'logs': logs_data
            }), 200
        
        # Otherwise calculate thermal comfort from provided data
        temperature = data.get('temperature', 25)
        humidity = data.get('humidity', 50)
        wind_speed = data.get('wind_speed', 1)
        
        # Calculate thermal comfort indices
        # Heat Index
        if temperature >= 27:
            heat_index = -8.784695 + 1.61139411 * temperature + 2.338549 * humidity - 0.14611605 * temperature * humidity \
                        - 0.012308094 * temperature**2 - 0.016424827 * humidity**2 \
                        + 0.002211732 * temperature**2 * humidity + 0.00072546 * temperature * humidity**2 \
                        - 0.000003582 * temperature**2 * humidity**2
        else:
            heat_index = temperature
        
        # Dew point
        dew_point = (243.04 * (np.log(humidity/100) + (17.625 * temperature)/(243.04 + temperature))) \
                    / (17.625 - np.log(humidity/100) - (17.625 * temperature)/(243.04 + temperature))
        
        # PMV (simplified)
        if temperature < 18:
            pmv = -2 + (temperature - 18) / 6
        elif temperature < 22:
            pmv = -1 + (temperature - 22) / 4
        elif temperature < 26:
            pmv = 0 + (temperature - 26) / 4
        elif temperature < 30:
            pmv = 1 + (temperature - 30) / 4
        else:
            pmv = 2 + (temperature - 34) / 4
        
        pmv = max(-3, min(3, pmv))
        
        # PPD
        ppd = 100 - 95 * np.exp(-0.03353 * pmv**4 - 0.2179 * pmv**2)
        
        # Discomfort index
        discomfort_index = max(0, min(100, (abs(temperature - 22) * 5) + (abs(humidity - 50) * 0.5)))
        
        # Comfort level
        if discomfort_index <= 20:
            comfort_level = 'Excellent'
        elif discomfort_index <= 40:
            comfort_level = 'Good'
        elif discomfort_index <= 60:
            comfort_level = 'Moderate'
        elif discomfort_index <= 80:
            comfort_level = 'Poor'
        else:
            comfort_level = 'Very Poor'
        
        # Thermal sensation
        if pmv <= -2.5:
            thermal_sensation = 'Very Cold'
        elif pmv <= -1.5:
            thermal_sensation = 'Cold'
        elif pmv <= -0.5:
            thermal_sensation = 'Cool'
        elif pmv <= 0.5:
            thermal_sensation = 'Neutral'
        elif pmv <= 1.5:
            thermal_sensation = 'Warm'
        elif pmv <= 2.5:
            thermal_sensation = 'Hot'
        else:
            thermal_sensation = 'Very Hot'
        
        # Create comfort log if location provided
        if location_id:
            log = ThermalComfortLog(
                location_id=location_id,
                air_temperature=temperature,
                relative_humidity=humidity,
                heat_index=heat_index,
                predicted_mean_vote=pmv,
                predicted_percentage_dissatisfied=ppd,
                discomfort_index=discomfort_index,
                comfort_level=comfort_level,
                thermal_sensation=thermal_sensation,
                measurement_time=datetime.utcnow()
            )
            db.session.add(log)
            db.session.commit()
        
        return jsonify({
            'success': True,
            'thermal_comfort': {
                'heat_index': round(heat_index, 1),
                'dew_point': round(dew_point, 1),
                'predicted_mean_vote': round(pmv, 2),
                'predicted_percentage_dissatisfied': round(ppd, 1),
                'discomfort_index': round(discomfort_index, 1),
                'comfort_level': comfort_level,
                'thermal_sensation': thermal_sensation
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Thermal comfort error: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/ai/environmental/thermal-sensors/<sensor_id>', methods=['DELETE'])
@jwt_required
def delete_thermal_alert_sensor(sensor_id):
    """Delete a thermal sensor and all its associated data"""
    try:
        # Check if user is admin (optional - you can remove this if not needed)
        is_super_admin = check_super_admin()
        if not is_super_admin:
            return jsonify({'success': False, 'error': 'Admin access required'}), 403
        
        # Find the sensor by ID (could be numeric id or string sensor_id)
        sensor = None
        if sensor_id.isdigit():
            # Try numeric ID first
            sensor = ThermalSensor.query.get(int(sensor_id))
        
        if not sensor:
            # Try string sensor_id
            sensor = ThermalSensor.query.filter_by(sensor_id=sensor_id).first()
        
        if not sensor:
            return jsonify({
                'success': False,
                'error': f'Sensor with ID {sensor_id} not found'
            }), 404
        
        # Store sensor info for response
        sensor_info = {
            'id': sensor.id,
            'sensor_id': sensor.sensor_id,
            'name': sensor.name
        }
        
        # Delete the sensor (cascade will delete related readings and alerts)
        db.session.delete(sensor)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Sensor {sensor.name} deleted successfully',
            'deleted_sensor': sensor_info
        }), 200
        
    except Exception as e:
        logger.error(f"Error deleting thermal sensor: {e}")
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500       

