@app.route('/api/environmental/impact/advanced-scorecard', methods=['GET'])
@jwt_required
def get_advanced_impact_scorecard():
    """Advanced environmental impact scoring with AI insights"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # Check feature access
        if not is_super_admin and not has_feature_access('advanced_scorecard'):
            return jsonify({
                'success': False,
                'error': 'Advanced scorecard requires Business or Enterprise plan',
                'code': 'FEATURE_NOT_AVAILABLE'
            }), 403
        
        # ✅ GET REAL DATA FROM DATABASE - NO MOCK
        try:
            from models import EnvironmentalScore, EnvironmentalInitiative, EnvironmentalMetric
            
            # Get user's company
            company_id = current_user.company_id
            user_id = current_user.id
            
            # If user has company, get company data, else get user data
            filter_kwargs = {}
            if company_id:
                filter_kwargs['company_id'] = company_id
            else:
                filter_kwargs['user_id'] = user_id
            
            # ✅ Get environmental scores from database
            scores = EnvironmentalScore.query.filter_by(**filter_kwargs).all()
            
            scorecard_data = []
            
            if scores:
                # ✅ Build from real database scores
                for score in scores:
                    # Get initiatives for this category
                    initiatives = EnvironmentalInitiative.query.filter_by(
                        category=score.category
                    ).filter(
                        db.or_(
                            EnvironmentalInitiative.company_id == company_id if company_id else False,
                            EnvironmentalInitiative.user_id == user_id
                        )
                    ).all()
                    
                    entry = {
                        'id': score.id,
                        'category': score.category,
                        'score': score.score or 0,
                        'trend': getattr(score, 'trend', 'stable'),
                        'impact': getattr(score, 'impact_level', 'medium'),
                        'description': getattr(score, 'description', f'{score.category} performance'),
                        'target': getattr(score, 'target_score', 90),
                        'progress': int((score.score / getattr(score, 'target_score', 90)) * 100) if getattr(score, 'target_score', 90) > 0 else 0,
                        'initiatives': [i.name for i in initiatives[:5]] if initiatives else ['No initiatives yet'],
                        'last_updated': score.updated_at.isoformat() if score.updated_at else datetime.utcnow().isoformat()
                    }
                    
                    # ✅ Add AI insights for enterprise/super admin
                    if is_super_admin or (current_user.subscription_plan and current_user.subscription_plan.lower() in ['enterprise', 'custom']):
                        entry['ai_prediction'] = get_ai_prediction(score.category, score.score, getattr(score, 'trend', 'stable'))
                        entry['confidence'] = getattr(score, 'ai_confidence', 0.85)
                    
                    scorecard_data.append(entry)
            
            # ✅ If no scores in database, try to get from environmental metrics
            if not scorecard_data:
                metrics = EnvironmentalMetric.query.filter_by(**filter_kwargs).order_by(
                    EnvironmentalMetric.created_at.desc()
                ).limit(50).all()
                
                if metrics:
                    # Group metrics by category
                    categories = {}
                    for metric in metrics:
                        category = getattr(metric, 'category', 'General')
                        if category not in categories:
                            categories[category] = []
                        categories[category].append(getattr(metric, 'value', 0))
                    
                    for category, values in categories.items():
                        if values:
                            avg_score = int(sum(values) / len(values)) if values else 75
                            entry = {
                                'id': len(scorecard_data) + 1,
                                'category': category,
                                'score': avg_score,
                                'trend': 'stable',
                                'impact': 'medium',
                                'description': f'{category} performance based on {len(values)} metrics',
                                'target': 90,
                                'progress': int((avg_score / 90) * 100) if avg_score > 0 else 0,
                                'initiatives': ['Track performance metrics', 'Set improvement targets'],
                                'last_updated': datetime.utcnow().isoformat()
                            }
                            
                            if is_super_admin or (current_user.subscription_plan and current_user.subscription_plan.lower() in ['enterprise', 'custom']):
                                entry['ai_prediction'] = get_ai_prediction(category, avg_score, 'stable')
                                entry['confidence'] = 0.85
                            
                            scorecard_data.append(entry)
            
            # ✅ Calculate overall score
            if scorecard_data:
                overall_score = int(sum(entry['score'] for entry in scorecard_data) / len(scorecard_data))
            else:
                overall_score = 0
            
            # ✅ Build response from REAL DATA
            response = {
                'success': True,
                'scorecard': scorecard_data,
                'overall_score': overall_score,
                'last_updated': datetime.utcnow().isoformat(),
                'access_level': 'premium' if (is_super_admin or (current_user.subscription_plan and current_user.subscription_plan.lower() in ['enterprise', 'custom'])) else 'standard',
                'total_categories': len(scorecard_data),
                'data_source': 'database'
            }
            
            # ✅ Add AI analysis for enterprise/super admin
            if is_super_admin or (current_user.subscription_plan and current_user.subscription_plan.lower() in ['enterprise', 'custom']):
                if scorecard_data:
                    # Find lowest scoring category
                    lowest = min(scorecard_data, key=lambda x: x['score']) if scorecard_data else None
                    highest = max(scorecard_data, key=lambda x: x['score']) if scorecard_data else None
                    
                    response['ai_analysis'] = {
                        'confidence_level': 'high',
                        'recommendations': [
                            f'Focus on improving {lowest["category"]} (current score: {lowest["score"]})' if lowest else 'Track all categories',
                            f'Maintain momentum on {highest["category"]} (current score: {highest["score"]})' if highest else 'Continue current efforts'
                        ],
                        'overall_assessment': 'Good performance with improvement opportunities' if overall_score > 70 else 'Significant improvement needed'
                    }
            
            # ✅ If no data at all, return empty with message
            if not scorecard_data:
                response['message'] = 'No environmental scorecard data available yet. Start tracking your environmental metrics to see insights.'
            
            return jsonify(response), 200
            
        except ImportError as import_error:
            current_app.logger.error(f"Model import error: {import_error}")
            # Return empty if models don't exist
            return jsonify({
                'success': True,
                'scorecard': [],
                'overall_score': 0,
                'last_updated': datetime.utcnow().isoformat(),
                'access_level': 'standard',
                'total_categories': 0,
                'data_source': 'empty',
                'message': 'No environmental scorecard data available yet. Start tracking your environmental metrics to see insights.'
            }), 200
            
        except Exception as db_error:
            current_app.logger.error(f"Database error in scorecard: {str(db_error)}")
            # Return error - NO MOCK DATA
            return jsonify({
                'success': False,
                'error': 'Failed to retrieve scorecard data',
                'message': str(db_error),
                'code': 'DATABASE_ERROR'
            }), 500
        
    except Exception as e:
        current_app.logger.error(f"Advanced impact scorecard error: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


def get_ai_prediction(category, score, trend):
    """Generate AI prediction based on category performance"""
    predictions = {
        'Carbon Emissions': {
            'improving': 'On track to exceed carbon reduction targets',
            'stable': 'Current pace sufficient to meet targets',
            'declining': 'Need accelerated action to meet targets'
        },
        'Energy Efficiency': {
            'improving': 'Energy targets achievable with current trajectory',
            'stable': 'Maintain current efficiency measures',
            'declining': 'Efficiency improvements needed'
        },
        'Waste Management': {
            'improving': 'Waste reduction targets on track',
            'stable': 'Current waste management effective',
            'declining': 'Waste reduction efforts need review'
        },
        'Water Usage': {
            'improving': 'Water conservation targets achievable',
            'stable': 'Maintain current water usage levels',
            'declining': 'Water usage reduction needed'
        },
        'Biodiversity': {
            'improving': 'Biodiversity initiatives showing results',
            'stable': 'Maintain current biodiversity efforts',
            'declining': 'Biodiversity protection needs urgent attention'
        }
    }
    
    category_pred = predictions.get(category, {})
    prediction = category_pred.get(trend, 'Performance stable, continue current initiatives')
    
    # Add score-based context
    if score >= 85:
        return f"{prediction} - Excellent performance"
    elif score >= 70:
        return f"{prediction} - Good performance with room for improvement"
    else:
        return f"{prediction} - Needs significant improvement"
