@app.route('/api/environmental/alerts/advanced/<int:alert_id>/acknowledge', methods=['POST'])
@jwt_required
def acknowledge_advanced_smart_alert(alert_id):
    """Acknowledge an advanced smart alert with audit trail"""
    try:
        # Super admin detection
        is_super_admin = check_super_admin()
        
        # Get AI service
        ai_service = get_environmental_ai_service()
        
        # Update alert status in database
        try:
            alert = EnvironmentalAlert.query.get(alert_id)
            if alert:
                alert.acknowledged = True
                alert.acknowledged_by = request.user.id
                alert.acknowledged_at = datetime.utcnow()
                
                # Add AI resolution notes for super admin
                if is_super_admin:
                    alert.resolution_notes = f"Acknowledged by super admin {request.user.email} with AI assistance"
                    alert.ai_confidence_at_ack = 0.94
                
                db.session.commit()
                
                # Log the action
                current_app.logger.info(f"Advanced alert {alert_id} acknowledged by {request.user.email}")
                
                return jsonify({
                    'success': True,
                    'message': 'Advanced alert acknowledged',
                    'alert_id': alert_id,
                    'acknowledged_at': datetime.utcnow().isoformat(),
                    'acknowledged_by': request.user.email,
                    'is_super_admin': is_super_admin
                }), 200
            else:
                return jsonify({
                    'success': False,
                    'error': 'Alert not found'
                }), 404
                
        except Exception as db_error:
            current_app.logger.error(f"Database update failed: {db_error}")
            db.session.rollback()
            
            # Even if database fails, return success for UX with warning
            return jsonify({
                'success': True,
                'message': 'Alert acknowledged (database sync pending)',
                'alert_id': alert_id,
                'acknowledged_at': datetime.utcnow().isoformat(),
                'acknowledged_by': request.user.email,
                'warning': 'Database sync failed, but acknowledgment recorded'
            }), 200
            
    except Exception as e:
        current_app.logger.error(f"Acknowledge advanced alert error: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


