def calculate_deviation_percent(value, limit):
    """Calculate deviation percentage from limit"""
    if 'max' in limit and value > limit['max']:
        return ((value - limit['max']) / limit['max']) * 100
    elif 'min' in limit and value < limit['min']:
        return ((limit['min'] - value) / limit['min']) * 100
    return 0

def calculate_compliance_score(parameter_analysis):
    """Calculate compliance score (0-100)"""
    if not parameter_analysis:
        return 100
    
    compliant_params = sum(1 for param in parameter_analysis.values() if param['status'] == 'compliant')
    total_params = len(parameter_analysis)
    
    return (compliant_params / total_params) * 100 if total_params > 0 else 100

def assign_quality_grade(compliance_score):
    """Assign quality grade based on compliance score"""
    if compliance_score >= 95:
        return 'A'
    elif compliance_score >= 85:
        return 'B'
    elif compliance_score >= 75:
        return 'C'
    elif compliance_score >= 65:
        return 'D'
    else:
        return 'F'

def identify_risk_factors(sensor_data, satellite_data):
    """Identify risk factors - 2 parameters"""
    risk_factors = []
    if sensor_data:
        air_score = sensor_data.get('air_quality', {}).get('index', 100)
        if air_score < 60:
            risk_factors.append({
                'category': 'air_quality',
                'severity': 'high' if air_score < 40 else 'medium',
                'description': f'Poor air quality detected (Score: {air_score})'
            })
        water_score = sensor_data.get('water_quality', {}).get('score', 100)
        if water_score < 60:
            risk_factors.append({
                'category': 'water_quality',
                'severity': 'high' if water_score < 40 else 'medium',
                'description': f'Water quality concerns (Score: {water_score})'
            })
    if satellite_data:
        drought = satellite_data.get('environmental_indicators', {}).get('drought_index', 0)
        if drought > 0.6:
            risk_factors.append({
                'category': 'drought',
                'severity': 'high',
                'description': 'Severe drought conditions detected'
            })
    return risk_factors

def analyze_parameter_trends(location, current_parameters, session):
    """Analyze parameter trends for a location"""
    try:
        # Get historical samples for this location (last 30 days)
        thirty_days_ago = datetime.utcnow() - timedelta(days=30)
        
        historical_samples = session.query(WaterQualitySample).filter(
            WaterQualitySample.location == location,
            WaterQualitySample.sample_date >= thirty_days_ago
        ).order_by(WaterQualitySample.sample_date.asc()).all()
        
        if len(historical_samples) < 2:
            return {'trend': 'insufficient_data', 'message': 'Not enough historical data'}
        
        trends = {}
        
        for param in current_parameters.keys():
            values = []
            dates = []
            
            for sample in historical_samples:
                if sample.parameters and param in sample.parameters:
                    values.append(sample.parameters[param])
                    dates.append(sample.sample_date)
            
            if len(values) >= 2:
                # Simple trend analysis
                first_value = values[0]
                last_value = values[-1]
                change_percent = ((last_value - first_value) / first_value) * 100 if first_value != 0 else 0
                
                if abs(change_percent) > 10:
                    trend = 'increasing' if change_percent > 0 else 'decreasing'
                else:
                    trend = 'stable'
                
                trends[param] = {
                    'trend': trend,
                    'change_percent': change_percent,
                    'data_points': len(values)
                }
        
        return trends
        
    except Exception as e:
        logger.error(f"Trend analysis error for location {location}: {str(e)}")
        return {'trend': 'analysis_error', 'message': str(e)}

def calculate_next_sampling_date(sample):
    """Calculate next sampling date based on sample type and results"""
    base_date = sample.sample_date
    
    if sample.compliance_status == 'non_compliant':
        return base_date + timedelta(days=1)  # Daily sampling for non-compliant
    elif sample.sample_type == 'tap_water':
        return base_date + timedelta(days=7)  # Weekly for tap water
    elif sample.sample_type == 'cooling_tower':
        return base_date + timedelta(days=14)  # Bi-weekly for cooling towers
    else:
        return base_date + timedelta(days=30)  # Monthly for others

def update_parameter_stats(parameter_stats, parameters):
    """Update parameter statistics"""
    for param, value in parameters.items():
        if param not in parameter_stats:
            parameter_stats[param] = {
                'count': 0,
                'sum': 0,
                'min': float('inf'),
                'max': float('-inf'),
                'values': []
            }
        
        stats = parameter_stats[param]
        stats['count'] += 1
        stats['sum'] += value
        stats['min'] = min(stats['min'], value)
        stats['max'] = max(stats['max'], value)
        stats['values'].append(value)

def update_location_stats(location_stats, location, status):
    """Update location statistics"""
    if location not in location_stats:
        location_stats[location] = {
            'total_samples': 0,
            'compliant_samples': 0,
            'non_compliant_samples': 0,
            'warning_samples': 0
        }
    
    stats = location_stats[location]
    stats['total_samples'] += 1
    
    if status == 'compliant':
        stats['compliant_samples'] += 1
    elif status == 'non_compliant':
        stats['non_compliant_samples'] += 1
    elif status == 'warning':
        stats['warning_samples'] += 1

def calculate_parameter_statistics(parameter_stats):
    """Calculate comprehensive parameter statistics"""
    statistics = {}
    
    for param, stats in parameter_stats.items():
        if stats['count'] > 0:
            statistics[param] = {
                'samples_count': stats['count'],
                'average': stats['sum'] / stats['count'],
                'min': stats['min'],
                'max': stats['max'],
                'range': stats['max'] - stats['min']
            }
    
    return statistics

def calculate_location_performance(location_stats):
    """Calculate location performance metrics"""
    performance = {}
    
    for location, stats in location_stats.items():
        total = stats['total_samples']
        if total > 0:
            performance[location] = {
                'total_samples': total,
                'compliance_rate': (stats['compliant_samples'] / total) * 100,
                'non_compliance_rate': (stats['non_compliant_samples'] / total) * 100,
                'warning_rate': (stats['warning_samples'] / total) * 100
            }
    
    return performance

def calculate_overall_compliance_rate(samples_data):
    """Calculate overall compliance rate"""
    if not samples_data:
        return 0
    
    compliant_count = len([s for s in samples_data if s['status'] == 'compliant'])
    return (compliant_count / len(samples_data)) * 100

def analyze_overall_trends(samples_data):
    """Analyze overall trends across all samples"""
    if len(samples_data) < 2:
        return {'status': 'insufficient_data', 'message': 'Need more samples for trend analysis'}
    
    # Group by month for trend analysis
    monthly_data = {}
    
    for sample in samples_data:
        sample_date = datetime.fromisoformat(sample['sample_date'].replace('Z', '+00:00'))
        month_key = sample_date.strftime('%Y-%m')
        
        if month_key not in monthly_data:
            monthly_data[month_key] = {
                'samples': 0,
                'compliance_rate': 0,
                'compliant_samples': 0
            }
        
        monthly_data[month_key]['samples'] += 1
        if sample['status'] == 'compliant':
            monthly_data[month_key]['compliant_samples'] += 1
    
    # Calculate monthly compliance rates
    trends = []
    for month, data in sorted(monthly_data.items()):
        compliance_rate = (data['compliant_samples'] / data['samples']) * 100
        trends.append({
            'month': month,
            'compliance_rate': compliance_rate,
            'total_samples': data['samples']
        })
    
    return {
        'monthly_trends': trends,
        'status': 'adequate_data' if len(trends) >= 3 else 'developing_trends'
    }

def calculate_air_quality_index(sensors_data):
    """Calculate overall air quality index"""
    if not sensors_data:
        return 'unknown'
    
    # Calculate average PM2.5 from all sensors
    valid_readings = [sensor['current_metrics']['pm25'] for sensor in sensors_data if sensor['current_metrics']['pm25'] > 0]
    
    if not valid_readings:
        return 'unknown'
    
    avg_pm25 = sum(valid_readings) / len(valid_readings)
    
    if avg_pm25 <= 12:
        return 'good'
    elif avg_pm25 <= 35:
        return 'moderate'
    elif avg_pm25 <= 55:
        return 'unhealthy_sensitive'
    elif avg_pm25 <= 150:
        return 'unhealthy'
    else:
        return 'hazardous'

