def analyze_water_parameters(parameters, sample_type):
    """Analyze water parameters against regulatory limits"""
    analysis = {}
    regulatory_limits = get_regulatory_limits(sample_type)
    
    for param, value in parameters.items():
        if param in regulatory_limits:
            limit = regulatory_limits[param]
            status = 'compliant'
            
            if 'max' in limit and value > limit['max']:
                status = 'exceeded'
            elif 'warning' in limit and value > limit['warning']:
                status = 'warning'
            elif 'min' in limit and value < limit['min']:
                status = 'below_minimum'
            
            analysis[param] = {
                'value': value,
                'unit': limit.get('unit', ''),
                'limit_max': limit.get('max'),
                'limit_min': limit.get('min'),
                'limit_warning': limit.get('warning'),
                'status': status,
                'deviation_percent': calculate_deviation_percent(value, limit) if status != 'compliant' else 0
            }
        else:
            # For parameters not in specific limits, use standard limits
            standard_limits = get_standard_regulatory_limits()
            if param in standard_limits:
                limit = standard_limits[param]
                status = 'compliant'
                
                if 'max' in limit and value > limit['max']:
                    status = 'exceeded'
                elif 'warning' in limit and value > limit['warning']:
                    status = 'warning'
                elif 'min' in limit and value < limit['min']:
                    status = 'below_minimum'
                
                analysis[param] = {
                    'value': value,
                    'unit': limit.get('unit', ''),
                    'limit_max': limit.get('max'),
                    'limit_min': limit.get('min'),
                    'limit_warning': limit.get('warning'),
                    'status': status,
                    'deviation_percent': calculate_deviation_percent(value, limit) if status != 'compliant' else 0
                }
    
    return analysis

def determine_sample_status(parameter_analysis):
    """Determine overall sample status based on parameter analysis"""
    if not parameter_analysis:
        return 'unknown'
    
    if any(param['status'] == 'exceeded' for param in parameter_analysis.values()):
        return 'non_compliant'
    elif any(param['status'] == 'warning' for param in parameter_analysis.values()):
        return 'warning'
    elif any(param['status'] == 'below_minimum' for param in parameter_analysis.values()):
        return 'warning'
    else:
        return 'compliant'

def generate_water_quality_recommendations(parameter_analysis):
    """Generate recommendations based on water quality analysis"""
    recommendations = []
    
    for param, analysis in parameter_analysis.items():
        if analysis['status'] == 'exceeded':
            recommendations.append(f"Immediate action required: {param} levels exceeded regulatory limits by {analysis['deviation_percent']:.1f}%")
        elif analysis['status'] == 'warning':
            recommendations.append(f"Monitor closely: {param} approaching regulatory limits")
        elif analysis['status'] == 'below_minimum':
            recommendations.append(f"Investigate: {param} below recommended minimum levels")
    
    # Add general recommendations
    if not recommendations:
        recommendations.append("Water quality within acceptable parameters")
    
    return recommendations

def assess_water_quality_risk(samples_data):
    """Assess overall water quality risk"""
    if not samples_data:
        return {'level': 'unknown', 'description': 'No data available'}
    
    non_compliant_count = len([s for s in samples_data if s['status'] == 'non_compliant'])
    warning_count = len([s for s in samples_data if s['status'] == 'warning'])
    total_count = len(samples_data)
    
    if total_count == 0:
        return {'level': 'unknown', 'description': 'No samples available'}
    
    non_compliant_ratio = non_compliant_count / total_count
    warning_ratio = warning_count / total_count
    
    if non_compliant_ratio > 0.1:  # More than 10% non-compliant
        return {'level': 'high', 'description': 'Significant compliance issues detected'}
    elif warning_ratio > 0.2:  # More than 20% warnings
        return {'level': 'medium', 'description': 'Multiple parameters approaching limits'}
    elif non_compliant_ratio > 0:
        return {'level': 'low', 'description': 'Minor compliance issues'}
    else:
        return {'level': 'very_low', 'description': 'Good water quality compliance'}

def calculate_aqi_from_pm25(pm25):
    """Calculate AQI from PM2.5 value"""
    # Simplified AQI calculation based on PM2.5
    if pm25 <= 12:
        return pm25 * (50 / 12)  # Good
    elif pm25 <= 35:
        return 50 + (pm25 - 12) * (50 / 23)  # Moderate
    elif pm25 <= 55:
        return 100 + (pm25 - 35) * (50 / 20)  # Unhealthy for sensitive groups
    elif pm25 <= 150:
        return 150 + (pm25 - 55) * (100 / 95)  # Unhealthy
    elif pm25 <= 250:
        return 200 + (pm25 - 150) * (100 / 100)  # Very unhealthy
    else:
        return 300 + (pm25 - 250) * (100 / 150)  # Hazardous

def check_air_quality_alerts(reading, user_id, session):
    """Check if reading triggers any air quality alerts"""
    
    # EPA Air Quality Standards
    standards = {
        'pm25': {'good': 12, 'moderate': 35, 'unhealthy': 55},
        'pm10': {'good': 54, 'moderate': 154, 'unhealthy': 254},
        'co': {'good': 4.4, 'moderate': 9.4, 'unhealthy': 12.4},
        'no2': {'good': 53, 'moderate': 100, 'unhealthy': 360},
        'o3': {'good': 54, 'moderate': 70, 'unhealthy': 85},
        'so2': {'good': 35, 'moderate': 75, 'unhealthy': 185}
    }
    
    alerts_created = []
    
    for parameter, thresholds in standards.items():
        value = getattr(reading, parameter, None)
        if value is not None:
            if value >= thresholds['unhealthy']:
                severity = 'high'
                alert_type = f'{parameter.upper()}_UNHEALTHY'
            elif value >= thresholds['moderate']:
                severity = 'medium'
                alert_type = f'{parameter.upper()}_ELEVATED'
            elif value >= thresholds['good']:
                severity = 'low'
                alert_type = f'{parameter.upper()}_MODERATE'
            else:
                continue
            
            # Create alert
            alert = AirQualityAlert(
                user_id=user_id,
                sensor_id=reading.sensor_id,
                alert_type=alert_type,
                severity=severity,
                parameter=parameter,
                value=value,
                threshold=thresholds['moderate'] if severity == 'low' else thresholds['unhealthy'],
                message=f'{parameter.upper()} levels at {value} ({severity} risk)',
                resolved=False
            )
            
            session.add(alert)
            alerts_created.append(alert_type)
    
    return alerts_created



