# ========================= NEURAL NETWORKS =========================

class LandCoverClassifier(nn.Module):
    """Advanced neural network for land cover classification"""
    def __init__(self, input_dim: int = 768, num_classes: int = 6, dropout_rate: float = 0.3):
        super().__init__()
        self.num_classes = num_classes
        
        # Feature extraction layers
        self.feature_extractor = nn.Sequential(
            nn.Linear(input_dim, 1024),
            nn.BatchNorm1d(1024),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            
            nn.Linear(1024, 512),
            nn.BatchNorm1d(512),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            
            nn.Linear(512, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(),
        )
        
        # Attention mechanism for feature weighting
        self.attention = nn.Sequential(
            nn.Linear(256, 128),
            nn.Tanh(),
            nn.Linear(128, 256),
            nn.Sigmoid()
        )
        
        # Classification head
        self.classifier = nn.Sequential(
            nn.Linear(256, 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate * 0.5),
            nn.Linear(128, num_classes)
        )
        
        # Uncertainty estimation head
        self.uncertainty_head = nn.Sequential(
            nn.Linear(256, 64),
            nn.ReLU(),
            nn.Linear(64, 1),
            nn.Sigmoid()
        )
        
    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        # Extract features
        features = self.feature_extractor(x)
        
        # Apply attention
        attention_weights = self.attention(features)
        attended_features = features * attention_weights
        
        # Classification
        logits = self.classifier(attended_features)
        
        # Uncertainty estimation
        uncertainty = self.uncertainty_head(attended_features)
        
        return logits, uncertainty, attention_weights

class ChangeDetectionModel(nn.Module):
    """Advanced Siamese network for change detection"""
    def __init__(self, input_dim: int = 768, num_change_types: int = 8):
        super().__init__()
        
        # Shared encoder
        self.encoder = nn.Sequential(
            nn.Linear(input_dim, 512),
            nn.BatchNorm1d(512),
            nn.ReLU(),
            nn.Dropout(0.2),
            
            nn.Linear(512, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(),
            
            nn.Linear(256, 128),
            nn.BatchNorm1d(128),
            nn.ReLU()
        )
        
        # Change magnitude estimation
        self.magnitude_estimator = nn.Sequential(
            nn.Linear(128 * 2, 64),
            nn.ReLU(),
            nn.Linear(64, 32),
            nn.ReLU(),
            nn.Linear(32, 1),
            nn.Sigmoid()
        )
        
        # Change type classification
        self.type_classifier = nn.Sequential(
            nn.Linear(128 * 2, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(),
            nn.Dropout(0.3),
            
            nn.Linear(256, 128),
            nn.BatchNorm1d(128),
            nn.ReLU(),
            
            nn.Linear(128, num_change_types)
        )
        
        # Temporal pattern recognition
        self.temporal_encoder = nn.LSTM(128, 64, batch_first=True, bidirectional=True)
        
    def forward(self, x1: torch.Tensor, x2: torch.Tensor, 
                historical: Optional[List[torch.Tensor]] = None) -> Dict[str, torch.Tensor]:
        # Encode both images
        feat1 = self.encoder(x1)
        feat2 = self.encoder(x2)
        
        # Combine features
        combined = torch.cat([feat1, feat2], dim=1)
        
        # Estimate change magnitude
        magnitude = self.magnitude_estimator(combined)
        
        # Classify change type
        type_logits = self.type_classifier(combined)
        
        result = {
            'magnitude': magnitude,
            'type_logits': type_logits,
            'features1': feat1,
            'features2': feat2
        }
        
        # Process historical data if available
        if historical and len(historical) > 1:
            historical_features = torch.stack([self.encoder(h) for h in historical])
            temporal_out, _ = self.temporal_encoder(historical_features.unsqueeze(0))
            result['temporal_features'] = temporal_out.squeeze(0)
            
        return result

class SpectralIndexNetwork(nn.Module):
    """Network for calculating spectral indices from raw imagery"""
    def __init__(self):
        super().__init__()
        self.conv_layers = nn.Sequential(
            nn.Conv2d(3, 16, kernel_size=3, padding=1),
            nn.BatchNorm2d(16),
            nn.ReLU(),
            nn.Conv2d(16, 32, kernel_size=3, padding=1),
            nn.BatchNorm2d(32),
            nn.ReLU(),
            nn.Conv2d(32, 64, kernel_size=3, padding=1),
            nn.BatchNorm2d(64),
            nn.ReLU(),
            nn.AdaptiveAvgPool2d((1, 1))
        )
        
        self.index_predictor = nn.Linear(64, 10)  # Predict 10 spectral indices
        
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        features = self.conv_layers(x)
        features = features.view(features.size(0), -1)
        indices = self.index_predictor(features)
        return indices

