def fetch_weather_data(lat, lng):
    """Fetch weather data from WeatherAPI.com - Supports both current and forecast"""
    import traceback
    
    logger.info("=" * 50)
    logger.info("🔍 DEBUG: fetch_weather_data CALLED")
    logger.info(f"🔍 DEBUG: lat={lat}, lng={lng}")
    
    try:
        api_key = os.environ.get('WEATHERAPI_KEY')
        logger.info(f"🔍 DEBUG: WEATHERAPI_KEY present: {bool(api_key)}")
        
        if not api_key:
            logger.error("⚠️ WEATHERAPI_KEY not found")
            return {
                'success': False,
                'error': 'Weather API key not configured',
                'code': 'API_KEY_MISSING'
            }
        
        # ============================================================
        # ✅ DETECT REQUEST TYPE
        # ============================================================
        is_forecast = lat == 'forecast.json'
        is_astronomy = lat == 'astronomy.json'
        
        # ✅ Extract location from lng dict
        location = 'auto:ip'
        params = {}
        if isinstance(lng, dict):
            location = lng.get('q', 'auto:ip')
            params = lng
        
        logger.info(f"🔍 DEBUG: Request type: {'forecast' if is_forecast else 'astronomy' if is_astronomy else 'current'}")
        logger.info(f"🔍 DEBUG: Location from params: {location}")
        
        # ============================================================
        # ✅ BUILD THE CORRECT URL
        # ============================================================
        if is_forecast:
            # ✅ FORECAST ENDPOINT - Use /v1/forecast.json
            url = f"http://api.weatherapi.com/v1/forecast.json?key={api_key}&q={location}&days={params.get('days', 5)}"
            if params.get('aqi') == 'yes':
                url += "&aqi=yes"
            if params.get('alerts') == 'yes':
                url += "&alerts=yes"
            
            logger.info(f"🔍 DEBUG: Using FORECAST endpoint")
            
        elif is_astronomy:
            # ✅ ASTRONOMY ENDPOINT
            url = f"http://api.weatherapi.com/v1/astronomy.json?key={api_key}&q={location}&dt={params.get('dt', '2026-08-23')}"
            
            logger.info(f"🔍 DEBUG: Using ASTRONOMY endpoint")
            
        else:
            # ✅ CURRENT WEATHER ENDPOINT
            url = f"http://api.weatherapi.com/v1/current.json?key={api_key}&q={location}&aqi=yes"
            
            logger.info(f"🔍 DEBUG: Using CURRENT endpoint")
        
        logger.info(f"🔍 DEBUG: Calling WeatherAPI: {url.replace(api_key, 'HIDDEN')}")
        
        # ============================================================
        # ✅ MAKE REQUEST
        # ============================================================
        response = requests.get(url, timeout=15)
        logger.info(f"🔍 DEBUG: Response status code: {response.status_code}")
        
        if response.status_code != 200:
            logger.warning(f"⚠️ WeatherAPI returned status: {response.status_code}")
            logger.warning(f"⚠️ Response: {response.text[:200]}")
            return {
                'success': False,
                'error': f'Weather API returned status {response.status_code}',
                'code': 'API_ERROR',
                'status_code': response.status_code
            }
        
        # ============================================================
        # ✅ PARSE RESPONSE
        # ============================================================
        try:
            data = response.json()
            logger.info(f"🔍 DEBUG: JSON parsed successfully")
        except Exception as e:
            logger.error(f"🔍 DEBUG: Failed to parse JSON: {e}")
            return {
                'success': False,
                'error': 'Invalid JSON response from weather API',
                'code': 'INVALID_JSON'
            }
        
        if not isinstance(data, dict):
            logger.error(f"🔍 DEBUG: Data is NOT a dict! Type: {type(data)}")
            return {
                'success': False,
                'error': 'Unexpected response format from weather API',
                'code': 'INVALID_RESPONSE'
            }
        
        logger.info(f"🔍 DEBUG: Data keys: {list(data.keys())}")
        
        # ============================================================
        # ✅ EXTRACT LOCATION INFO
        # ============================================================
        location_data = data.get('location', {})
        location_name = location_data.get('name', 'Unknown')
        location_country = location_data.get('country', 'Unknown')
        location_region = location_data.get('region', '')
        localtime = location_data.get('localtime', '')
        
        logger.info(f"📍 WeatherAPI returned: {location_name}, {location_country}")
        
        # ============================================================
        # ✅ EXTRACT CURRENT WEATHER
        # ============================================================
        current = data.get('current', {})
        
        if not current:
            logger.error("🔍 DEBUG: 'current' is missing!")
            return {
                'success': False,
                'error': 'Missing current weather data',
                'code': 'MISSING_CURRENT_DATA'
            }
        
        # Extract data safely
        condition_data = current.get('condition', {})
        condition_text = condition_data.get('text', 'Clear') if isinstance(condition_data, dict) else 'Clear'
        
        air_quality = current.get('air_quality', {})
        aqi_value = air_quality.get('us-epa-index', 0) if isinstance(air_quality, dict) else 0
        
        temp_c = current.get('temp_c', 0)
        
        # ============================================================
        # ✅ BUILD WEATHER DATA
        # ============================================================
        weather_data = {
            'success': True,
            'condition': str(condition_text),
            'temperature': float(temp_c or 0),
            'feels_like': float(current.get('feelslike_c', 0) or 0),
            'humidity': int(current.get('humidity', 0) or 0),
            'pressure': int(current.get('pressure_mb', 0) or 0),
            'wind_speed': float(current.get('wind_kph', 0) or 0),
            'wind_kph': float(current.get('wind_kph', 0) or 0),
            'visibility': float(current.get('vis_km', 10) or 10),
            'clouds': int(current.get('cloud', 0) or 0),
            'precipitation': float(current.get('precip_mm', 0) or 0),
            'uv_index': int(current.get('uv', 0) or 0),
            'gust_kph': float(current.get('gust_kph', 0) or 0),
            'air_quality': int(aqi_value or 0),
            'air_quality_score': 50,
            'last_updated': str(current.get('last_updated', '')),
            'location_name': str(location_name),
            'location_region': str(location_region),
            'location_country': str(location_country),
            'localtime': str(localtime),
            'is_day': int(current.get('is_day', 1) or 1),
            'source': 'weatherapi'
        }
        
        # Calculate air quality score
        aqi_map = {1: 80, 2: 60, 3: 40, 4: 20, 5: 10}
        weather_data['air_quality_score'] = aqi_map.get(weather_data['air_quality'], 50)
        
        # ============================================================
        # ✅ ADD FORECAST DATA IF AVAILABLE
        # ============================================================
        if is_forecast and 'forecast' in data:
            forecast_data = data.get('forecast', {})
            forecast_days = forecast_data.get('forecastday', [])
            
            forecast_list = []
            for day in forecast_days:
                day_data = day.get('day', {})
                forecast_list.append({
                    'date': day.get('date', ''),
                    'maxtemp_c': day_data.get('maxtemp_c', 0),
                    'mintemp_c': day_data.get('mintemp_c', 0),
                    'avgtemp_c': day_data.get('avgtemp_c', 0),
                    'avghumidity': day_data.get('avghumidity', 0),
                    'maxwind_kph': day_data.get('maxwind_kph', 0),
                    'daily_chance_of_rain': day_data.get('daily_chance_of_rain', 0),
                    'uv': day_data.get('uv', 0),
                    'condition': day_data.get('condition', {}).get('text', 'Unknown')
                })
            
            weather_data['forecast'] = forecast_list
            logger.info(f"📊 Added {len(forecast_list)} forecast days")
        
        # ============================================================
        # ✅ ADD ASTRONOMY DATA IF AVAILABLE
        # ============================================================
        if is_astronomy and 'astronomy' in data:
            astro_data = data.get('astronomy', {}).get('astro', {})
            weather_data['astronomy'] = {
                'sunrise': astro_data.get('sunrise', '06:00 AM'),
                'sunset': astro_data.get('sunset', '06:00 PM'),
                'moonrise': astro_data.get('moonrise', '12:00 PM'),
                'moonset': astro_data.get('moonset', '12:00 AM'),
                'moon_phase': astro_data.get('moon_phase', 'First Quarter'),
                'moon_illumination': astro_data.get('moon_illumination', 50)
            }
            logger.info(f"🌙 Added astronomy data")
        
        logger.info(f"✅ REAL WEATHER: {weather_data['temperature']}°C, {weather_data['condition']} in {weather_data['location_name']}")
        logger.info(f"🔍 DEBUG: Returning weather_data dict with {len(weather_data)} keys")
        return weather_data
        
    except requests.exceptions.Timeout:
        logger.error("⏰ WeatherAPI timeout")
        return {
            'success': False,
            'error': 'Weather API request timed out',
            'code': 'TIMEOUT'
        }
    except requests.exceptions.ConnectionError:
        logger.error("🌐 WeatherAPI connection error")
        return {
            'success': False,
            'error': 'Could not connect to weather API',
            'code': 'CONNECTION_ERROR'
        }
    except Exception as e:
        logger.error(f"❌ Error in fetch_weather_data: {e}")
        logger.error(f"❌ Full traceback:\n{traceback.format_exc()}")
        return {
            'success': False,
            'error': f'Unexpected error: {str(e)}',
            'code': 'UNEXPECTED_ERROR'
        }


def get_fallback_weather(lat, lng):
    """Generate fallback weather data based on location"""
    logger.info(f"🔍 DEBUG: get_fallback_weather called with lat={lat}, lng={lng}")
    
    try:
        current_hour = datetime.datetime.now().hour
        is_day = 6 <= current_hour <= 18
        
        # Estimate temperature based on latitude
        temp_base = 25 - (abs(lat) / 3)
        temp_variation = 5 + (abs(lat) / 10)
        temperature = temp_base + (temp_variation * (1 if is_day else -0.5))
        temperature = max(-10, min(45, temperature))
        
        # Determine condition based on temperature and time
        if temperature > 30:
            condition = 'Sunny' if is_day else 'Clear'
        elif temperature > 20:
            condition = 'Partly cloudy' if is_day else 'Partly clear'
        elif temperature > 10:
            condition = 'Cloudy' if is_day else 'Overcast'
        else:
            condition = 'Cold'
        
        fallback_data = {
            'condition': condition,
            'temperature': round(temperature, 1),
            'feels_like': round(temperature - 1, 1),
            'humidity': round(40 + (abs(lat) / 4), 0),
            'pressure': 1013,
            'wind_speed': round(5 + (abs(lat) / 20), 1),
            'wind_kph': round((5 + (abs(lat) / 20)) * 3.6, 1),
            'visibility': 10.0,
            'clouds': 30,
            'precipitation': 0.0,
            'uv_index': 3,
            'air_quality': 0,
            'air_quality_score': 70,
            'location_name': f"Location at {lat:.4f}, {lng:.4f}",
            'is_day': 1 if is_day else 0,
            'source': 'fallback'
        }
        
        logger.info(f"📊 Using fallback weather data: {fallback_data['temperature']}°C, {fallback_data['condition']}")
        logger.info(f"🔍 DEBUG: fallback_data type: {type(fallback_data)}, keys: {list(fallback_data.keys())}")
        return fallback_data
        
    except Exception as e:
        logger.error(f"🔍 DEBUG: Error in get_fallback_weather: {e}")
        # Ultimate fallback - always return a dict
        return {
            'condition': 'Clear',
            'temperature': 25.0,
            'feels_like': 25.0,
            'humidity': 50,
            'pressure': 1013,
            'wind_speed': 10.0,
            'wind_kph': 10.0,
            'visibility': 10.0,
            'clouds': 0,
            'precipitation': 0.0,
            'uv_index': 5,
            'air_quality': 2,
            'air_quality_score': 60,
            'last_updated': datetime.datetime.utcnow().isoformat(),
            'location_name': 'Unknown',
            'location_region': 'Unknown',
            'location_country': 'Unknown',
            'localtime': datetime.datetime.utcnow().isoformat(),
            'is_day': 1,
            'source': 'fallback_ultimate'
        }


