    """Add a new thermal sensor"""
    try:
        data = request.get_json()
        
        # Check if sensor already exists
        existing = ThermalSensor.query.filter_by(sensor_id=data.get('sensor_id')).first()
        if existing:
            return jsonify({'success': False, 'error': 'Sensor ID already exists'}), 400
        
        sensor = ThermalSensor(
            sensor_id=data.get('sensor_id'),
            name=data.get('name'),
            location=data.get('location'),
            type=data.get('type'),
            min_temp=data.get('min_temp', -10),
            max_temp=data.get('max_temp', 50),
            status=data.get('status', 'active'),
            battery_level=data.get('battery_level', 100)
        )
        
        db.session.add(sensor)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Sensor added successfully',
            'sensor': sensor.to_dict()
        }), 201
    except Exception as e:
        logger.error(f"Error adding thermal sensor: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


