@app.route('/api/environmental/thermal/uhi-records/<int:record_id>', methods=['PUT'])
@jwt_required
def update_uhi_record(record_id):
    """Update a UHI record with validation"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        if is_super_admin:
            record = UrbanHeatIslandRecord.query.get(record_id)
        else:
            record = UrbanHeatIslandRecord.query.filter_by(
                id=record_id,
                company_id=current_user.company_id or 1
            ).first()
        
        if not record:
            return jsonify({
                'success': False,
                'error': 'UHI record not found',
                'code': 'RECORD_NOT_FOUND'
            }), 404
        
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA'
            }), 400
        
        changes = []
        
        # Urban core temperature validation
        if 'urban_core_temperature' in data:
            try:
                temp = float(data['urban_core_temperature'])
                if temp < -20 or temp > 50:
                    return jsonify({
                        'success': False,
                        'error': 'Urban core temperature must be between -20°C and 50°C',
                        'code': 'INVALID_TEMPERATURE'
                    }), 400
                if record.urban_core_temperature != temp:
                    changes.append(f'urban_core: {record.urban_core_temperature} -> {temp}')
                record.urban_core_temperature = temp
            except (ValueError, TypeError):
                return jsonify({
                    'success': False,
                    'error': 'Urban core temperature must be a valid number',
                    'code': 'INVALID_TEMPERATURE'
                }), 400
        
        # Rural reference temperature validation
        if 'rural_reference_temperature' in data:
            try:
                temp = float(data['rural_reference_temperature'])
                if temp < -20 or temp > 50:
                    return jsonify({
                        'success': False,
                        'error': 'Rural reference temperature must be between -20°C and 50°C',
                        'code': 'INVALID_TEMPERATURE'
                    }), 400
                if record.rural_reference_temperature != temp:
                    changes.append(f'rural: {record.rural_reference_temperature} -> {temp}')
                record.rural_reference_temperature = temp
            except (ValueError, TypeError):
                return jsonify({
                    'success': False,
                    'error': 'Rural reference temperature must be a valid number',
                    'code': 'INVALID_TEMPERATURE'
                }), 400
        
        # Risk level validation
        if 'risk_level' in data:
            allowed_risks = ['low', 'medium', 'high', 'critical']
            if data['risk_level'].lower() not in allowed_risks:
                return jsonify({
                    'success': False,
                    'error': f'Invalid risk level. Allowed: {", ".join(allowed_risks)}',
                    'code': 'INVALID_RISK'
                }), 400
            if record.risk_level != data['risk_level']:
                changes.append(f'risk: {record.risk_level} -> {data["risk_level"]}')
            record.risk_level = data['risk_level'].lower()
        
        # Recalculate heat island intensity
        if 'urban_core_temperature' in data or 'rural_reference_temperature' in data:
            record.heat_island_intensity = record.urban_core_temperature - record.rural_reference_temperature
        
        if not changes:
            return jsonify({
                'success': False,
                'error': 'No valid fields to update',
                'code': 'NO_VALID_FIELDS'
            }), 400
        
        db.session.commit()
        
        current_app.logger.info(f"✅ UHI record {record_id} updated. Changes: {', '.join(changes)}")
        
        return jsonify({
            'success': True,
            'message': 'UHI record updated successfully',
            'changes': changes,
            'record': {
                'id': record.id,
                'heat_island_intensity': record.heat_island_intensity,
                'risk_level': record.risk_level
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error updating UHI record {record_id}: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to update UHI record',
            'code': 'INTERNAL_ERROR'
        }), 500


