@app.route('/api/ai/environmental/thermal-readings', methods=['GET'])
@jwt_required
def get_thermal_readings():
    """Get thermal sensor readings"""
    try:
        sensor_id = request.args.get('sensor_id')
        limit = request.args.get('limit', 100, type=int)
        
        query = ThermalReading.query
        if sensor_id:
            query = query.filter_by(sensor_id=sensor_id)
        
        readings = query.order_by(ThermalReading.reading_time.desc()).limit(limit).all()
        
        return jsonify({
            'success': True,
            'readings': [r.to_dict() for r in readings]
        }), 200
    except Exception as e:
        logger.error(f"Error getting thermal readings: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/ai/environmental/thermal-readings', methods=['POST'])
@jwt_required
def add_thermal_reading():
    """Add a thermal sensor reading"""
    try:
        data = request.get_json()
        
        # Verify sensor exists
        sensor = ThermalSensor.query.filter_by(sensor_id=data.get('sensor_id')).first()
        if not sensor:
            return jsonify({'success': False, 'error': 'Sensor not found'}), 404
        
        reading = ThermalReading(
            sensor_id=data.get('sensor_id'),
            temperature=data.get('temperature'),
            humidity=data.get('humidity'),
            battery_level=data.get('battery_level'),
            reading_time=datetime.fromisoformat(data.get('reading_time')) if data.get('reading_time') else datetime.utcnow()
        )
        
        db.session.add(reading)
        
        # Update sensor battery level if provided
        if data.get('battery_level'):
            sensor.battery_level = data.get('battery_level')
        
        db.session.commit()
        
        # Check for alerts
        alerts = check_temperature_alerts(sensor, reading)
        
        return jsonify({
            'success': True,
            'message': 'Reading added successfully',
            'reading': reading.to_dict(),
            'alerts_generated': alerts
        }), 201
    except Exception as e:
        logger.error(f"Error adding thermal reading: {e}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


def check_temperature_alerts(sensor, reading):
    """Check if temperature reading triggers any alerts"""
    alerts = []
    
    if reading.temperature > sensor.max_temp:
        alert = ThermalAlert(
            sensor_id=sensor.sensor_id,
            alert_type='high_temp',
            severity='critical',
            message=f'Temperature {reading.temperature}°C exceeds maximum {sensor.max_temp}°C',
            temperature=reading.temperature,
            threshold=sensor.max_temp
        )
        db.session.add(alert)
        alerts.append(alert.to_dict())
    elif reading.temperature < sensor.min_temp:
        alert = ThermalAlert(
            sensor_id=sensor.sensor_id,
            alert_type='low_temp',
            severity='warning',
            message=f'Temperature {reading.temperature}°C below minimum {sensor.min_temp}°C',
            temperature=reading.temperature,
            threshold=sensor.min_temp
        )
        db.session.add(alert)
        alerts.append(alert.to_dict())
    
    if reading.battery_level and reading.battery_level < 20:
        alert = ThermalAlert(
            sensor_id=sensor.sensor_id,
            alert_type='battery_low',
            severity='warning',
            message=f'Battery level at {reading.battery_level}%',
            temperature=reading.temperature,
            threshold=20
        )
        db.session.add(alert)
        alerts.append(alert.to_dict())
    
    db.session.commit()
    return alerts





def calculate_esg_scores(esg_data):
    """Calculate ESG scores"""
    scores = {}
    
    env_metrics = [
        esg_data.get('environmental', {}).get('air_quality', 0),
        esg_data.get('environmental', {}).get('water_quality', 0),
        esg_data.get('environmental', {}).get('vegetation_health', 0),
        esg_data.get('environmental', {}).get('biodiversity', 0),
        esg_data.get('environmental', {}).get('carbon_sequestration', 0)
    ]
    valid_env = [m for m in env_metrics if m is not None and m > 0]
    scores['environmental'] = round(sum(valid_env) / len(valid_env), 2) if valid_env else 0
    
    social_metrics = [
        esg_data.get('social', {}).get('health_compliance', 0),
        esg_data.get('social', {}).get('community_impact', 0),
        esg_data.get('social', {}).get('ppe_compliance', 0),
        esg_data.get('social', {}).get('social_wellbeing', 0),
        esg_data.get('social', {}).get('labor_conditions', 0)
    ]
    valid_social = [m for m in social_metrics if m is not None and m > 0]
    scores['social'] = round(sum(valid_social) / len(valid_social), 2) if valid_social else 0
    
    gov_metrics = [
        esg_data.get('governance', {}).get('compliance_score', 0),
        esg_data.get('governance', {}).get('transparency_score', 0),
        esg_data.get('governance', {}).get('environmental_governance', 0),
        esg_data.get('governance', {}).get('regulatory_compliance', 0),
        esg_data.get('governance', {}).get('ethics_score', 0)
    ]
    valid_gov = [m for m in gov_metrics if m is not None and m > 0]
    scores['governance'] = round(sum(valid_gov) / len(valid_gov), 2) if valid_gov else 0
    
    weights = {'env': 0.4, 'social': 0.3, 'gov': 0.3}
    scores['overall'] = round(
        (scores['environmental'] * weights['env'] +
         scores['social'] * weights['social'] +
         scores['governance'] * weights['gov']),
        2
    )
    
    return scores

def create_fallback_map_image(lat, lng, zoom=15, size=(800, 600)):
    """Create a fallback map image when API calls fail"""
    try:
        # Create cache directory
        cache_dir = Path("./map_cache")
        cache_dir.mkdir(exist_ok=True)
        cache_file = cache_dir / f"fallback_map_{lat}_{lng}_{zoom}.png"
        
        # Create a synthetic satellite-like image
        img = Image.new('RGB', size, color=(60, 120, 80))
        draw = ImageDraw.Draw(img)
        
        # Grid lines
        for x in range(0, size[0], 50):
            draw.line([(x, 0), (x, size[1])], fill=(80, 140, 100), width=1)
        for y in range(0, size[1], 50):
            draw.line([(0, y), (size[0], y)], fill=(80, 140, 100), width=1)
        
        # Simulate water bodies (blue areas)
        water_spots = [(random.randint(0, size[0]), random.randint(0, size[1])) for _ in range(random.randint(3, 8))]
        for spot in water_spots:
            radius = random.randint(30, 100)
            draw.ellipse([spot[0]-radius, spot[1]-radius, spot[0]+radius, spot[1]+radius], 
                        fill=(40, 100, 160), outline=(60, 120, 180))
        
        # Simulate urban areas (gray/brown)
        urban_spots = [(random.randint(0, size[0]), random.randint(0, size[1])) for _ in range(random.randint(2, 5))]
        for spot in urban_spots:
            radius = random.randint(20, 60)
            draw.ellipse([spot[0]-radius, spot[1]-radius, spot[0]+radius, spot[1]+radius], 
                        fill=(150, 130, 110), outline=(170, 150, 130))
        
        # Simulate vegetation (green areas)
        veg_spots = [(random.randint(0, size[0]), random.randint(0, size[1])) for _ in range(random.randint(2, 4))]
        for spot in veg_spots:
            radius = random.randint(25, 70)
            draw.ellipse([spot[0]-radius, spot[1]-radius, spot[0]+radius, spot[1]+radius], 
                        fill=(80, 160, 60), outline=(100, 180, 80))
        
        # Add location marker at center
        center = (size[0]//2, size[1]//2)
        marker_size = 15
        
        # Outer ring (red)
        draw.ellipse([center[0]-marker_size, center[1]-marker_size, 
                     center[0]+marker_size, center[1]+marker_size], 
                    fill=(255, 0, 0), outline=(255, 255, 255))
        # Inner dot (white)
        draw.ellipse([center[0]-5, center[1]-5, center[0]+5, center[1]+5], 
                    fill=(255, 255, 255))
        # Line down
        draw.line([center[0], center[1]+marker_size, center[0], center[1]+marker_size+15], 
                 fill=(255, 0, 0), width=3)
        
        # Add info text
        try:
            draw.text((10, 10), f"📍 Location: {lat:.4f}, {lng:.4f}", fill=(255, 255, 255))
            draw.text((10, 30), f"🔍 Zoom: {zoom}", fill=(255, 255, 255))
            draw.text((10, 50), "🛰️ Satellite imagery (simulated)", fill=(255, 255, 255))
            draw.text((10, 70), "📡 No API key found - using fallback", fill=(255, 200, 100))
        except:
            pass
        
        # Save image
        img.save(cache_file)
        logger.info(f"✅ Created fallback map image: {cache_file}")
        return str(cache_file)
        
    except Exception as e:
        logger.error(f"❌ Error creating fallback map image: {e}")
        return None
# ============================================================================
# MAP IMAGE CAPTURE
# ============================================================================

def capture_map_image(lat, lng, zoom=15, size=(800, 600)):
    """Capture satellite image from map using various providers"""
    try:
        import requests
        from PIL import Image
        from io import BytesIO
        import time
        
        cache_dir = Path("./map_cache")
        cache_dir.mkdir(exist_ok=True)
        
        # Generate cache key
        cache_key = f"map_{lat}_{lng}_{zoom}_{size[0]}x{size[1]}"
        cache_file = cache_dir / f"{cache_key}.png"
        
        # Check cache
        if cache_file.exists():
            if time.time() - cache_file.stat().st_mtime < 86400:
                logger.info(f"✅ Using cached image: {cache_file}")
                return str(cache_file)
        
        # Try Google Maps
        api_key = os.environ.get('GOOGLE_MAPS_API_KEY')
        if api_key:
            try:
                logger.info("🌍 Trying Google Maps API...")
                url = "https://maps.googleapis.com/maps/api/staticmap"
                params = {
                    'center': f"{lat},{lng}",
                    'zoom': zoom,
                    'size': f"{size[0]}x{size[1]}",
                    'maptype': 'satellite',
                    'key': api_key
                }
                response = requests.get(url, params=params, timeout=10)
                if response.status_code == 200:
                    image = Image.open(BytesIO(response.content))
                    image.save(cache_file)
                    logger.info(f"✅ Captured map image from Google: {cache_file}")
                    return str(cache_file)
                else:
                    logger.warning(f"⚠️ Google Maps API returned {response.status_code}")
            except Exception as e:
                logger.warning(f"⚠️ Google Maps API error: {e}")
        else:
            logger.warning("⚠️ No Google Maps API key found")
        
        # Try Mapbox
        mapbox_token = os.environ.get('MAPBOX_ACCESS_TOKEN')
        if mapbox_token:
            try:
                logger.info("🌍 Trying Mapbox API...")
                url = f"https://api.mapbox.com/styles/v1/mapbox/satellite-v9/static/{lng},{lat},{zoom}/{size[0]}x{size[1]}"
                params = {'access_token': mapbox_token}
                response = requests.get(url, params=params, timeout=10)
                if response.status_code == 200:
                    image = Image.open(BytesIO(response.content))
                    image.save(cache_file)
                    logger.info(f"✅ Captured map image from Mapbox: {cache_file}")
                    return str(cache_file)
                else:
                    logger.warning(f"⚠️ Mapbox API returned {response.status_code}")
            except Exception as e:
                logger.warning(f"⚠️ Mapbox API error: {e}")
        else:
            logger.warning("⚠️ No Mapbox token found")
        
        # Try OpenStreetMap as fallback
        try:
            logger.info("🌍 Trying OpenStreetMap...")
            import math
            lat_rad = math.radians(lat)
            n = 2.0 ** zoom
            tile_x = int((lng + 180.0) / 360.0 * n)
            tile_y = int((1.0 - math.asinh(math.tan(lat_rad)) / math.pi) / 2.0 * n)
            
            url = f"https://tile.openstreetmap.org/{zoom}/{tile_x}/{tile_y}.png"
            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                image = Image.open(BytesIO(response.content))
                image.save(cache_file)
                logger.info(f"✅ Captured map image from OpenStreetMap: {cache_file}")
                return str(cache_file)
            else:
                logger.warning(f"⚠️ OpenStreetMap returned {response.status_code}")
        except Exception as e:
            logger.warning(f"⚠️ OpenStreetMap error: {e}")
        
        # Create fallback image
        logger.info("📝 Creating fallback map image...")
        return create_fallback_map_image(lat, lng, zoom, size)
        
    except Exception as e:
        logger.error(f"❌ Error capturing map image: {e}")
        return create_fallback_map_image(lat, lng, zoom, size)
