@app.route('/api/environmental/sites/<site_id>/details', methods=['GET'])
@jwt_required
def get_site_details(site_id):
    """Get detailed site information including AI analysis"""
    try:
        user = request.user
        user_id = user.id
        
        ai_service = current_app.config.get('ai_service')
        
        logger.info(f"🔍 get_site_details called with site_id: {site_id}")
        
        # Check if this is an AI-generated site (starts with 'ai_')
        if site_id.startswith('ai_'):
            logger.info(f"🔍 AI site detected: {site_id}")
            
            # Try to get from cache
            site_data = None
            if hasattr(current_app, 'ai_sites_cache'):
                site_data = current_app.ai_sites_cache.get(site_id)
                logger.info(f"🔍 Cache lookup: found={site_data is not None}")
            
            if site_data:
                logger.info(f"✅ Found site in cache: {site_data.get('name')}")
                return jsonify({
                    'success': True,
                    **site_data
                }), 200
            
            # If not in cache, try to regenerate from the site_id
            if ai_service:
                # Parse the site_id to get location info
                # Format: ai_{user_id}_{timestamp}
                parts = site_id.split('_')
                logger.info(f"🔍 Parsed site_id parts: {parts}")
                
                # Try to get lat/lng from the parts
                lat = None
                lng = None
                
                # Check if we have lat/lng in the parts (format: ai_{user_id}_{lat}_{lng}_{timestamp})
                if len(parts) >= 5:
                    try:
                        lat = float(parts[2])
                        lng = float(parts[3])
                        logger.info(f"🔍 Extracted lat/lng from parts: lat={lat}, lng={lng}")
                    except (ValueError, IndexError) as e:
                        logger.warning(f"Could not parse lat/lng from parts: {e}")
                
                # If we have lat/lng, analyze the location
                if lat and lng:
                    logger.info(f"🔍 Analyzing location: lat={lat}, lng={lng}")
                    
                    # Get image path
                    image_path = capture_map_image(lat, lng, 15)
                    
                    if image_path:
                        logger.info(f"🔍 Analyzing image: {image_path}")
                        
                        analysis = ai_service.analyze_satellite_image(
                            image_path=image_path,
                            location_id=site_id,
                            model_preference=ai_service.get_model_for_task('general')
                        )
                        
                        if analysis.get('success'):
                            logger.info(f"✅ Analysis successful")
                            
                            # Create site data from analysis
                            site_data = create_site_data_from_ai_analysis(
                                analysis,
                                lat,
                                lng,
                                user_id
                            )
                            
                            # Cache it
                            if not hasattr(current_app, 'ai_sites_cache'):
                                current_app.ai_sites_cache = {}
                            current_app.ai_sites_cache[site_id] = site_data
                            
                            logger.info(f"✅ Site data created and cached: {site_data.get('name')}")
                            
                            return jsonify({
                                'success': True,
                                **site_data
                            }), 200
                        else:
                            logger.warning(f"❌ Analysis failed: {analysis.get('error', 'Unknown error')}")
                    else:
                        logger.warning(f"❌ Failed to capture map image for lat={lat}, lng={lng}")
                else:
                    logger.warning(f"❌ No lat/lng found in site_id: {site_id}")
            
            # If we couldn't regenerate, return a basic site structure
            logger.warning(f"⚠️ Returning basic site structure for {site_id}")
            return jsonify({
                'success': True,
                'id': site_id,
                'name': f"AI Analysis {site_id}",
                'location': "Unknown",
                'latitude': None,
                'longitude': None,
                'status': 'normal',
                'risk_score': 0,
                'aqi': 0,
                'temperature': None,
                'humidity': None,
                'description': "Site data not available",
                'created_at': datetime.utcnow().isoformat(),
                'updated_at': datetime.utcnow().isoformat(),
                'cameras': [],
                'sensors': [],
                'historical_incidents': [],
                'ai_analysis': None,
                'predictions': [],
                'detections': [],
                'source': 'ai_analysis_fallback'
            }), 200
        
        # For non-AI sites, return a generic response
        return jsonify({
            'success': True,
            'id': site_id,
            'name': f"Site {site_id}",
            'location': "Unknown",
            'latitude': None,
            'longitude': None,
            'status': 'normal',
            'risk_score': 0,
            'aqi': 0,
            'temperature': None,
            'humidity': None,
            'description': "Site information not available",
            'created_at': datetime.utcnow().isoformat(),
            'updated_at': datetime.utcnow().isoformat(),
            'cameras': [],
            'sensors': [],
            'historical_incidents': [],
            'ai_analysis': None,
            'predictions': [],
            'detections': []
        }), 200
        
    except Exception as e:
        logger.error(f"Error getting site details: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


