@app.route('/api/environmental/analyze-with-image', methods=['POST'])
@jwt_required
def analyze_with_image():
    """Analyze a map image sent from frontend"""
    try:
        logger.info("=" * 60)
        logger.info("🔍 DEBUG: analyze_with_image CALLED")
        logger.info("=" * 60)
        
        user = request.user
        user_id = user.id
        logger.info(f"🔍 DEBUG: user_id={user_id}")
        
        data = request.get_json()
        logger.info(f"🔍 DEBUG: Request data: {data}")
        
        lat = data.get('lat')
        lng = data.get('lng')
        zoom = data.get('zoom', 15)
        image_data = data.get('image')
        
        logger.info(f"🔍 DEBUG: lat={lat}, lng={lng}, zoom={zoom}")
        logger.info(f"🔍 DEBUG: image_data present: {bool(image_data)}")
        
        if not lat or not lng:
            logger.error("🔍 DEBUG: Missing lat or lng")
            return jsonify({
                'success': False,
                'error': 'Latitude and longitude required',
                'sites': [],
                'total': 0
            }), 400
        
        ai_service = current_app.config.get('ai_service')
        logger.info(f"🔍 DEBUG: ai_service type: {type(ai_service)}")
        
        if not ai_service:
            logger.error("🔍 DEBUG: AI service not available")
            return jsonify({
                'success': False,
                'error': 'AI service not available',
                'sites': [],
                'total': 0
            }), 500
        
        # Get image path
        image_path = None
        logger.info("🔍 DEBUG: Getting image path...")
        
        if image_data:
            logger.info("🔍 DEBUG: Processing image_data from frontend")
            try:
                import base64
                from PIL import Image
                from io import BytesIO
                
                logger.info(f"🔍 DEBUG: image_data length: {len(image_data)}")
                
                if 'base64,' in image_data:
                    image_data = image_data.split('base64,')[1]
                    logger.info("🔍 DEBUG: Removed base64 prefix")
                
                logger.info("🔍 DEBUG: Decoding base64...")
                image_bytes = base64.b64decode(image_data)
                logger.info(f"🔍 DEBUG: Decoded {len(image_bytes)} bytes")
                
                logger.info("🔍 DEBUG: Opening image with PIL...")
                image = Image.open(BytesIO(image_bytes))
                logger.info(f"🔍 DEBUG: Image size: {image.size}, mode: {image.mode}")
                
                temp_dir = Path("./temp_images")
                temp_dir.mkdir(exist_ok=True)
                temp_path = temp_dir / f"map_{user_id}_{int(datetime.utcnow().timestamp())}.jpg"
                logger.info(f"🔍 DEBUG: Saving to: {temp_path}")
                image.save(temp_path)
                image_path = str(temp_path)
                logger.info(f"✅ Received image from frontend: {temp_path}")
                
            except Exception as e:
                logger.error(f"🔍 DEBUG: Failed to process frontend image: {e}")
                import traceback
                logger.error(f"🔍 DEBUG: Traceback: {traceback.format_exc()}")
                logger.info("🔍 DEBUG: Falling back to capture_map_image")
                image_path = capture_map_image(lat, lng, zoom)
        else:
            logger.info("🔍 DEBUG: No image_data, calling capture_map_image")
            image_path = capture_map_image(lat, lng, zoom)
        
        logger.info(f"🔍 DEBUG: image_path: {image_path}")
        
        if not image_path:
            logger.error("🔍 DEBUG: Failed to get image")
            return jsonify({
                'success': False,
                'error': 'Failed to get image for analysis',
                'sites': [],
                'total': 0
            }), 500
        
        # Analyze the image
        logger.info("🔍 DEBUG: Calling ai_service.analyze_satellite_image...")
        logger.info(f"🔍 DEBUG: image_path={image_path}")
        logger.info(f"🔍 DEBUG: location_id=map_{lat}_{lng}")
        
        model_preference = ai_service.get_model_for_task('general') if hasattr(ai_service, 'get_model_for_task') else None
        logger.info(f"🔍 DEBUG: model_preference: {model_preference}")
        
        try:
            analysis = ai_service.analyze_satellite_image(
                image_path=image_path,
                location_id=f"map_{lat}_{lng}",
                model_preference=model_preference
            )
            logger.info(f"🔍 DEBUG: analysis returned, type: {type(analysis)}")
            logger.info(f"🔍 DEBUG: analysis keys: {list(analysis.keys()) if isinstance(analysis, dict) else 'NOT A DICT'}")
            
            if isinstance(analysis, dict):
                logger.info(f"🔍 DEBUG: analysis['success']: {analysis.get('success')}")
                logger.info(f"🔍 DEBUG: analysis keys: {list(analysis.keys())}")
        except Exception as e:
            logger.error(f"🔍 DEBUG: analyze_satellite_image threw exception: {e}")
            import traceback
            logger.error(f"🔍 DEBUG: Traceback: {traceback.format_exc()}")
            raise
        
        # Clean up temp file
        try:
            if image_path and 'temp_images' in image_path:
                logger.info(f"🔍 DEBUG: Cleaning up temp file: {image_path}")
                Path(image_path).unlink()
                logger.info("🔍 DEBUG: Temp file deleted")
        except Exception as e:
            logger.warning(f"🔍 DEBUG: Failed to delete temp file: {e}")
        
        if analysis.get('success'):
            logger.info("🔍 DEBUG: Analysis successful, calling create_site_data_from_ai_analysis...")
            try:
                site_data = create_site_data_from_ai_analysis(analysis, lat, lng, user_id)
                logger.info(f"🔍 DEBUG: site_data created, type: {type(site_data)}")
                logger.info(f"🔍 DEBUG: site_data keys: {list(site_data.keys()) if isinstance(site_data, dict) else 'NOT A DICT'}")
                
                # Log weather data
                if isinstance(site_data, dict):
                    weather = site_data.get('weather', {})
                    logger.info(f"🔍 DEBUG: Weather data: temp={weather.get('temperature')}°C, condition={weather.get('condition')}, source={weather.get('source')}")
                    
                response = {
                    'success': True,
                    'sites': [site_data],
                    'total': 1,
                    'timestamp': datetime.utcnow().isoformat()
                }
                logger.info("✅ DEBUG: Success! Returning response")
                return jsonify(response), 200
                
            except Exception as e:
                logger.error(f"🔍 DEBUG: create_site_data_from_ai_analysis failed: {e}")
                import traceback
                logger.error(f"🔍 DEBUG: Traceback: {traceback.format_exc()}")
                raise
        else:
            logger.error(f"🔍 DEBUG: Analysis failed: {analysis.get('error', 'Unknown error')}")
            return jsonify({
                'success': False,
                'error': analysis.get('error', 'Analysis failed'),
                'sites': [],
                'total': 0
            }), 500
        
    except Exception as e:
        logger.error(f"❌ Error in analyze-with-image: {e}")
        import traceback
        logger.error(f"❌ Full traceback:\n{traceback.format_exc()}")
        return jsonify({
            'success': False,
            'error': str(e),
            'sites': [],
            'total': 0
        }), 500

@app.route('/api/environmental/predictions', methods=['GET'])
@jwt_required
def get_predictions():
    """Get predictions - AI ONLY"""
    try:
        user = request.user
        user_id = user.id
        
        lat = request.args.get('lat', type=float)
        lng = request.args.get('lng', type=float)
        
        ai_service = current_app.config.get('ai_service')
        if not ai_service:
            return jsonify({'success': False, 'error': 'AI service not available', 'predictions': []}), 500
        
        predictions = []
        
        if lat and lng:
            image_path = capture_map_image(lat, lng, 15)
            if image_path:
                analysis = ai_service.analyze_satellite_image(
                    image_path=image_path,
                    location_id=f"pred_{lat}_{lng}",
                    model_preference=ai_service.get_model_for_task('change_detection') if hasattr(ai_service, 'get_model_for_task') else None
                )
                if analysis.get('success'):
                    change = analysis.get('change_detection', {})
                    if change.get('change_detected'):
                        predictions.append({
                            'id': f"pred_{int(datetime.utcnow().timestamp())}",
                            'type': change.get('change_type', 'Change Detected'),
                            'confidence': change.get('confidence', 0.7) * 100,
                            'severity': change.get('severity', 'medium').capitalize(),
                            'timeframe': '24 hours',
                            'timestamp': datetime.utcnow().isoformat()
                        })
                    
                    indicators = analysis.get('environmental_indicators', {})
                    if indicators.get('drought_index', 0) > 0.5:
                        predictions.append({
                            'id': f"pred_drought_{int(datetime.utcnow().timestamp())}",
                            'type': 'Drought Risk',
                            'confidence': indicators.get('drought_index', 0) * 100,
                            'severity': 'High' if indicators.get('drought_index', 0) > 0.7 else 'Medium',
                            'timeframe': '48 hours',
                            'timestamp': datetime.utcnow().isoformat()
                        })
                    
                    if indicators.get('fire_risk', 0) > 0.4:
                        predictions.append({
                            'id': f"pred_fire_{int(datetime.utcnow().timestamp())}",
                            'type': 'Fire Risk',
                            'confidence': indicators.get('fire_risk', 0) * 100,
                            'severity': 'High' if indicators.get('fire_risk', 0) > 0.6 else 'Medium',
                            'timeframe': '24 hours',
                            'timestamp': datetime.utcnow().isoformat()
                        })
        
        return jsonify({
            'success': True,
            'predictions': predictions,
            'count': len(predictions),
            'timestamp': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        logger.error(f"Error in predictions: {e}")
        return jsonify({'success': False, 'error': str(e), 'predictions': []}), 500


