@app.route('/api/environmental/heatmap', methods=['GET'])
@jwt_required
def get_heatmap_data():
    """Get heatmap - AI ONLY"""
    try:
        user = request.user
        user_id = user.id
        
        lat = request.args.get('lat', type=float)
        lng = request.args.get('lng', type=float)
        heatmap_type = request.args.get('type', 'risk')
        
        ai_service = current_app.config.get('ai_service')
        if not ai_service:
            return jsonify({'success': False, 'error': 'AI service not available', 'data': []}), 500
        
        heatmap_data = []
        
        if lat and lng:
            for lat_offset in [-0.01, 0, 0.01]:
                for lng_offset in [-0.01, 0, 0.01]:
                    point_lat = lat + lat_offset
                    point_lng = lng + lng_offset
                    
                    image_path = capture_map_image(point_lat, point_lng, 15)
                    if image_path:
                        analysis = ai_service.analyze_satellite_image(
                            image_path=image_path,
                            location_id=f"heat_{point_lat}_{point_lng}",
                            model_preference=ai_service.get_model_for_task('thermal') if hasattr(ai_service, 'get_model_for_task') else None
                        )
                        if analysis.get('success'):
                            intensity = 0.1
                            anomalies = analysis.get('anomaly_detection', {})
                            if anomalies.get('anomalies_detected'):
                                intensity = min(1.0, intensity + 0.3)
                            
                            indicators = analysis.get('environmental_indicators', {})
                            if indicators.get('drought_index', 0) > 0.5:
                                intensity = min(1.0, intensity + 0.2)
                            if indicators.get('fire_risk', 0) > 0.4:
                                intensity = min(1.0, intensity + 0.2)
                            
                            thermal = analysis.get('thermal_analysis', {})
                            if thermal:
                                lst = thermal.get('land_surface_temperature', {})
                                if lst.get('mean', 25) > 30:
                                    intensity = min(1.0, intensity + 0.2)
                            
                            heatmap_data.append({
                                'lat': point_lat,
                                'lng': point_lng,
                                'intensity': round(min(1.0, intensity), 2),
                                'type': heatmap_type,
                                'risk_level': 'critical' if intensity > 0.7 else 'warning' if intensity > 0.4 else 'normal'
                            })
        
        return jsonify({
            'success': True,
            'data': heatmap_data,
            'type': heatmap_type,
            'count': len(heatmap_data),
            'timestamp': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        logger.error(f"Error in heatmap: {e}")
        return jsonify({'success': False, 'error': str(e), 'data': []}), 500


