@app.route('/api/environmental/models/status', methods=['GET'])
@jwt_required
def get_model_status():
    """Get status of all loaded AI models with task mappings"""
    try:
        user = request.user
        user_id = user.id
        
        ai_service = current_app.config.get('ai_service')
        if not ai_service:
            return jsonify({
                'success': False,
                'error': 'AI service not available'
            }), 500
        
        status = {
            'success': True,
            'timestamp': datetime.utcnow().isoformat(),
            'device': str(ai_service.device) if hasattr(ai_service, 'device') else 'unknown',
            'models': {},
            'task_models': {},
            'stats': {}
        }
        
        # Get model info
        if hasattr(ai_service, 'downloaded_models'):
            for name, info in ai_service.downloaded_models.items():
                status['models'][name] = {
                    'embedding_dim': info.get('embedding_dim', 0),
                    'strength': info.get('strength', 'unknown'),
                    'use_for': info.get('use_for', []),
                    'loaded_at': info.get('loaded_at', '').isoformat() if isinstance(info.get('loaded_at'), datetime) else str(info.get('loaded_at')),
                    'path': info.get('path', 'unknown'),
                    'status': 'loaded'
                }
        
        # Get task models
        if hasattr(ai_service, 'task_models'):
            status['task_models'] = ai_service.task_models
            
            # Add task descriptions
            task_descriptions = {
                'general': 'General purpose analysis',
                'fast': 'Fast lightweight analysis',
                'air_quality': 'Air quality and pollution detection',
                'ecosystem': 'Ecosystem and biodiversity analysis',
                'vegetation': 'Vegetation health and coverage analysis',
                'urban': 'Urban area and built environment analysis',
                'change_detection': 'Change detection and temporal analysis',
                'thermal': 'Thermal pattern and temperature analysis',
                'real_time': 'Real-time monitoring and quick analysis',
                'batch': 'Batch processing and bulk analysis'
            }
            status['task_descriptions'] = task_descriptions
        
        # Get stats
        if hasattr(ai_service, 'get_model_stats'):
            stats = ai_service.get_model_stats()
            status['stats'] = {
                'cache_size': stats.get('system', {}).get('cache_size', 0),
                'historical_entries': stats.get('system', {}).get('historical_entries', 0),
                'total_models_loaded': len(ai_service.downloaded_models),
                'inference_stats': {k: v for k, v in stats.items() if k != 'system'}
            }
        
        # Get model performance metrics
        if hasattr(ai_service, 'inference_stats'):
            status['performance'] = {}
            for model_name, model_stats in ai_service.inference_stats.items():
                count = model_stats.get('count', 0)
                if count > 0:
                    status['performance'][model_name] = {
                        'total_inferences': count,
                        'avg_time_ms': round((model_stats.get('total_time', 0) / count) * 1000, 2),
                        'error_rate': round(model_stats.get('errors', 0) / count * 100, 2),
                        'cache_hits': model_stats.get('cache_hits', 0)
                    }
        
        # Get cache info
        if hasattr(ai_service, 'inference_cache'):
            status['cache'] = {
                'size': len(ai_service.inference_cache),
                'max_size': ai_service.cache_size if hasattr(ai_service, 'cache_size') else 1000
            }
        
        # Get device info
        if hasattr(ai_service, 'device'):
            status['device_info'] = {
                'type': str(ai_service.device),
                'cuda_available': torch.cuda.is_available() if hasattr(torch, 'cuda') else False,
                'cuda_device_count': torch.cuda.device_count() if hasattr(torch, 'cuda') and torch.cuda.is_available() else 0
            }
        
        return jsonify(status), 200
        
    except Exception as e:
        logger.error(f"Error in model status endpoint: {e}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/environmental/models/switch', methods=['POST'])
@jwt_required
def switch_model_for_task():
    """Switch the model used for a specific task"""
    try:
        user = request.user
        data = request.get_json()
        
        task = data.get('task')
        model_name = data.get('model_name')
        
        if not task or not model_name:
            return jsonify({
                'success': False,
                'error': 'task and model_name are required'
            }), 400
        
        ai_service = current_app.config.get('ai_service')
        if not ai_service:
            return jsonify({
                'success': False,
                'error': 'AI service not available'
            }), 500
        
        # Check if model exists
        if not hasattr(ai_service, 'downloaded_models') or model_name not in ai_service.downloaded_models:
            return jsonify({
                'success': False,
                'error': f'Model {model_name} not found'
            }), 404
        
        # Check if task exists
        if not hasattr(ai_service, 'task_models') or task not in ai_service.task_models:
            return jsonify({
                'success': False,
                'error': f'Task {task} not found'
            }), 404
        
        # Switch model for task
        old_model = ai_service.task_models[task]
        ai_service.task_models[task] = model_name
        
        # Update task models
        if hasattr(ai_service, '_update_task_model_mappings'):
            ai_service._update_task_model_mappings()
        
        logger.info(f"Switched model for task {task} from {old_model} to {model_name}")
        
        return jsonify({
            'success': True,
            'message': f'Model for task {task} switched from {old_model} to {model_name}',
            'task': task,
            'old_model': old_model,
            'new_model': model_name,
            'timestamp': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        logger.error(f"Error switching model: {e}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


# ============================================================================
# HELPER FUNCTIONS
# ============================================================================

def calculate_risk_score(site, detections):
    """Calculate risk score based on site data and detections"""
    risk = 0
    
    # Base risk from site
    if site.risk_score:
        risk += site.risk_score * 0.3
    
    # Add detection risks
    for detection in detections:
        severity_weights = {
            'low': 5,
            'medium': 15,
            'high': 30,
            'critical': 50
        }
        risk += severity_weights.get(detection.severity, 10)
    
    # Add anomaly risks
    anomalies = ThermalAnomaly.query.filter_by(
        location_id=site.id,
        status='active'
    ).count()
    risk += anomalies * 20
    
    # Add alert risks
    alerts = EnvironmentalAlert.query.filter_by(
        site_id=site.id,
        acknowledged=False
    ).count()
    risk += alerts * 10
    
    return min(100, risk)


def get_task_model_mappings(ai_service):
    """Get task model mappings with descriptions"""
    if not ai_service or not hasattr(ai_service, 'task_models'):
        return {}
    
    task_descriptions = {
        'general': 'General purpose analysis for land cover, anomalies, and environmental indicators',
        'fast': 'Fast lightweight analysis for quick results',
        'air_quality': 'Air quality monitoring, pollution detection, and AQI forecasting',
        'ecosystem': 'Ecosystem analysis, biodiversity assessment, and land cover segmentation',
        'vegetation': 'Vegetation health, coverage, biomass, and phenology analysis',
        'urban': 'Urban area analysis, building density, and urban sprawl assessment',
        'change_detection': 'Change detection, temporal analysis, and trend monitoring',
        'thermal': 'Thermal pattern analysis, temperature monitoring, and heat stress assessment',
        'real_time': 'Real-time monitoring with lightweight models for fast inference',
        'batch': 'Batch processing with balanced models for bulk analysis'
    }
    
    mappings = {}
    for task, model in ai_service.task_models.items():
        mappings[task] = {
            'model': model,
            'description': task_descriptions.get(task, 'No description available'),
            'available': model in ai_service.downloaded_models if hasattr(ai_service, 'downloaded_models') else False
        }
    
    return mappings

