@app.route('/api/ai/environmental/thermal-recommendations/<int:rec_id>/implement', methods=['POST'])
@jwt_required
def implement_thermal_recommendation(rec_id):
    """Mark a thermal recommendation as implemented"""
    try:
        data = request.get_json()
        actual_savings = data.get('actual_energy_savings')
        actual_temp_reduction = data.get('actual_temperature_reduction')
        
        recommendation = ThermalRecommendation.query.get(rec_id)
        
        if not recommendation:
            return jsonify({
                'success': False,
                'error': 'Recommendation not found'
            }), 404
        
        recommendation.status = 'implemented'
        recommendation.implemented_at = datetime.utcnow()
        recommendation.implemented_by = request.user.email if hasattr(request, 'user') else 'system'
        
        if actual_savings:
            recommendation.actual_energy_savings = actual_savings
        if actual_temp_reduction:
            recommendation.actual_temperature_reduction = actual_temp_reduction
        
        # Calculate effectiveness score
        if recommendation.estimated_energy_savings and actual_savings:
            recommendation.effectiveness_score = min(100, (actual_savings / recommendation.estimated_energy_savings) * 100)
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Recommendation marked as implemented',
            'recommendation_id': rec_id,
            'implemented_at': recommendation.implemented_at.isoformat()
        }), 200
        
    except Exception as e:
        logger.error(f"Implement recommendation error: {str(e)}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


