@app.route('/api/thermal/anomalies', methods=['GET'])
@jwt_required
def thermal_anomalies_list():
    """Get thermal anomalies - alias for compatibility"""
    try:
        location_id = request.args.get('location_id')
        severity = request.args.get('severity')
        status = request.args.get('status', 'open')
        
        query = ThermalAnomaly.query
        if status:
            if status.lower() == 'open':
                query = query.filter(ThermalAnomaly.resolved_at.is_(None))
            else:
                query = query.filter(ThermalAnomaly.resolved_at.isnot(None))
        
        if location_id:
            query = query.filter_by(location_id=location_id)
        if severity:
            query = query.filter_by(severity=severity)
        
        anomalies = query.order_by(ThermalAnomaly.detection_time.desc()).limit(100).all()
        
        result = []
        for anomaly in anomalies:
            result.append({
                'id': anomaly.id,
                'anomaly_type': anomaly.anomaly_type,
                'severity': anomaly.severity,
                'location_id': anomaly.location_id,
                'current_value': anomaly.current_value,
                'expected_value': anomaly.expected_value,
                'deviation': anomaly.deviation,
                'detection_time': anomaly.detection_time.isoformat() if anomaly.detection_time else None,
                'status': 'open' if anomaly.resolved_at is None else 'resolved',
                'confidence': anomaly.confidence
            })
        
        return jsonify({
            'success': True,
            'anomalies': result,
            'count': len(result)
        }), 200
    except Exception as e:
        logger.error(f"Error getting thermal anomalies: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


