class WeatherCache:
    """Simple in-memory cache for weather data"""
    def __init__(self):
        self.cache = {}
        self.max_age = 600  # 10 minutes
    
    def get(self, key):
        if key in self.cache:
            data, timestamp = self.cache[key]
            if (datetime.utcnow() - timestamp).seconds < self.max_age:
                return data
            del self.cache[key]
        return None
    
    def set(self, key, data):
        self.cache[key] = (data, datetime.utcnow())
    
    def clear(self):
        self.cache.clear()

weather_cache = WeatherCache()

