# WEATHER HELPER FUNCTIONS
# ============================================================================



def get_location_from_request():
    """Get location from request parameters"""
    location = request.args.get('location') or request.args.get('q')
    
    # If no location provided, try to get from IP
    if not location:
        ip = request.headers.get('X-Forwarded-For', request.remote_addr)
        # Get location from IP (simplified)
        try:
            ip_response = requests.get(f'https://ipapi.co/{ip}/json/', timeout=5)
            if ip_response.status_code == 200:
                data = ip_response.json()
                location = f"{data.get('city', '')},{data.get('country_code', '')}"
        except:
            location = 'auto:ip'
    
    return location

