@app.route('/api/weather/current', methods=['GET'])
@jwt_required
def get_weather_current():
    """Get current weather for a location"""
    try:
        location = get_location_from_request()
        aqi = request.args.get('aqi', 'yes')
        
        # Check cache
        cache_key = f"current_{location}_{aqi}"
        cached_data = weather_cache.get(cache_key)
        if cached_data:
            return jsonify(cached_data), 200
        
        # Fetch from API
        data = fetch_weather_data('current.json', {
            'q': location,
            'aqi': aqi
        })
        
        if data:
            weather_cache.set(cache_key, data)
            return jsonify(data), 200
        else:
            return jsonify({'error': 'Failed to fetch weather data'}), 500
            
    except Exception as e:
        logger.error(f"Error in get_weather_current: {e}")
        return jsonify({'error': str(e)}), 500


