@app.route('/api/weather/astronomy', methods=['GET', 'OPTIONS'])
@cross_origin()
@jwt_required
def get_weather_astronomy():
    """Get astronomy data (sunrise/sunset, moon phase)"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        location = get_location_from_request()
        date = request.args.get('date')
        
        if not date:
            date = datetime.now().strftime('%Y-%m-%d')
        
        # Validate date format
        try:
            datetime.strptime(date, '%Y-%m-%d')
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid date format. Use YYYY-MM-DD'
            }), 400
        
        # Check cache
        cache_key = f"astronomy_{location}_{date}"
        cached_data = weather_cache.get(cache_key)
        if cached_data:
            return jsonify({
                'success': True,
                'data': cached_data,
                'cached': True
            }), 200
        
        # Fetch from API
        result = fetch_weather_data('astronomy.json', {
            'q': location,
            'dt': date
        })
        
        if not result or not result.get('success'):
            error_msg = result.get('error', 'Failed to fetch astronomy data')
            return jsonify({
                'success': False,
                'error': error_msg,
                'code': result.get('code', 'API_ERROR')
            }), 503
        
        # Cache the result
        weather_cache.set(cache_key, result)
        
        # Extract astronomy data
        astronomy_data = result.get('astronomy', {})
        
        return jsonify({
            'success': True,
            'data': {
                'location': {
                    'name': result.get('location_name', 'Unknown'),
                    'region': result.get('location_region', 'Unknown'),
                    'country': result.get('location_country', 'Unknown')
                },
                'astronomy': {
                    'sunrise': astronomy_data.get('sunrise', '06:00 AM'),
                    'sunset': astronomy_data.get('sunset', '06:00 PM'),
                    'moon_phase': astronomy_data.get('moon_phase', 'First Quarter'),
                    'moon_illumination': astronomy_data.get('moon_illumination', 50),
                    'moonrise': astronomy_data.get('moonrise', '12:00 PM'),
                    'moonset': astronomy_data.get('moonset', '12:00 AM'),
                    'moon_sign': astronomy_data.get('moon_sign', 'Unknown')
                },
                'date': date,
                'source': result.get('source', 'weatherapi')
            },
            'timestamp': datetime.now().isoformat()
        }), 200
            
    except Exception as e:
        logger.error(f"Error in get_weather_astronomy: {e}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


