@app.route('/api/weather/ip', methods=['GET'])
@jwt_required
def get_weather_by_ip():
    """Get weather for current IP location"""
    try:
        # Get IP from request
        ip = request.headers.get('X-Forwarded-For', request.remote_addr)
        
        # Get location from IP
        try:
            ip_response = requests.get(f'https://ipapi.co/{ip}/json/', timeout=5)
            if ip_response.status_code == 200:
                data = ip_response.json()
                location = f"{data.get('city', '')},{data.get('country_code', '')}"
            else:
                location = 'auto:ip'
        except:
            location = 'auto:ip'
        
        # Fetch weather
        current = fetch_weather_data('current.json', {
            'q': location,
            'aqi': 'yes'
        })
        
        if current:
            return jsonify({
                'location': location,
                'ip': ip,
                'weather': current
            }), 200
        else:
            return jsonify({'error': 'Failed to fetch weather data'}), 500
            
    except Exception as e:
        logger.error(f"Error in get_weather_by_ip: {e}")
        return jsonify({'error': str(e)}), 500


