@app.route('/api/weather/impact', methods=['GET'])
@jwt_required
def get_weather_impact():
    """Get weather impact assessment"""
    try:
        location = get_location_from_request()
        
        # Get current weather
        current = fetch_weather_data('current.json', {
            'q': location,
            'aqi': 'yes'
        })
        
        if not current:
            return jsonify({'error': 'Failed to fetch weather data'}), 500
        
        current_data = current.get('current', {})
        temp = current_data.get('temp_c', 0)
        uv = current_data.get('uv', 0)
        wind = current_data.get('wind_kph', 0)
        precip = current_data.get('precip_mm', 0)
        aqi = current_data.get('air_quality', {}).get('us-epa-index', 0)
        
        impact = {
            'overall_risk': 'low',
            'health_risk': 'low',
            'travel_risk': 'low',
            'outdoor_risk': 'low',
            'factors': [],
            'recommendations': []
        }
        
        # Heat stress
        if temp > 35:
            impact.overall_risk = 'high'
            impact.health_risk = 'high'
            impact.factors.append('Extreme heat risk')
            impact.recommendations.append('Stay hydrated and avoid outdoor activities')
        elif temp > 30:
            impact.overall_risk = 'medium'
            impact.health_risk = 'medium'
            impact.factors.append('Moderate heat risk')
            impact.recommendations.append('Take breaks in shade or air-conditioned areas')
        
        # UV risk
        if uv > 7:
            impact.outdoor_risk = 'high'
            impact.factors.append('High UV radiation')
            impact.recommendations.append('Use sunscreen and wear protective clothing')
        elif uv > 4:
            impact.outdoor_risk = 'medium'
            impact.factors.append('Moderate UV radiation')
            impact.recommendations.append('Consider sun protection')
        
        # Wind risk
        if wind > 40:
            impact.travel_risk = 'high'
            impact.factors.append('Strong winds')
            impact.recommendations.append('Secure outdoor items and drive with caution')
        elif wind > 25:
            impact.travel_risk = 'medium'
            impact.factors.append('Moderate winds')
        
        # Rain risk
        if precip > 5:
            impact.travel_risk = 'medium'
            impact.factors.append('Rain expected')
            impact.recommendations.append('Carry umbrella and drive carefully')
        
        # Air quality
        if aqi > 3:
            impact.health_risk = 'high'
            impact.factors.append('Poor air quality')
            impact.recommendations.append('Limit outdoor activities and close windows')
        elif aqi > 2:
            impact.health_risk = 'medium'
            impact.factors.append('Moderate air quality')
        
        # Determine overall risk
        risk_levels = ['low', 'medium', 'high']
        risk_scores = {
            'health_risk': risk_levels.index(impact.health_risk),
            'travel_risk': risk_levels.index(impact.travel_risk),
            'outdoor_risk': risk_levels.index(impact.outdoor_risk)
        }
        max_risk = max(risk_scores.values())
        impact.overall_risk = risk_levels[max_risk]
        
        return jsonify(impact), 200
        
    except Exception as e:
        logger.error(f"Error in get_weather_impact: {e}")
        return jsonify({'error': str(e)}), 500


