class EnvironmentalModelLoader:
    """
    Loader for environmental AI models with automatic detection and fallback
    """
    
    @staticmethod
    def auto_load(model_path: Path, device: torch.device) -> Optional[Dict[str, Any]]:
        """
        Automatically detect and load a model from the given path
        """
        try:
            model_path = Path(model_path)
            
            if not model_path.exists():
                logger.error(f"Model path does not exist: {model_path}")
                return None
            
            # Try different loading strategies
            loaders = [
                EnvironmentalModelLoader._load_pytorch_model,
                EnvironmentalModelLoader._load_onnx_model,
                EnvironmentalModelLoader._load_tensorflow_model,
                EnvironmentalModelLoader._load_huggingface_model,
                EnvironmentalModelLoader._load_custom_model
            ]
            
            for loader in loaders:
                try:
                    result = loader(model_path, device)
                    if result and result.get('model') is not None:
                        logger.info(f"✅ Successfully loaded model using {loader.__name__}")
                        return result
                except Exception as e:
                    logger.debug(f"Loader {loader.__name__} failed: {e}")
                    continue
            
            # If all loaders fail, try to load as generic PyTorch model
            return EnvironmentalModelLoader._load_generic_model(model_path, device)
            
        except Exception as e:
            logger.error(f"Failed to auto-load model from {model_path}: {e}")
            return None
    
    @staticmethod
    def _load_pytorch_model(model_path: Path, device: torch.device) -> Optional[Dict[str, Any]]:
        """Load a PyTorch model from .pt or .pth file"""
        try:
            # Look for .pt or .pth files
            pt_files = list(model_path.glob("*.pt")) + list(model_path.glob("*.pth"))
            
            if not pt_files:
                if model_path.suffix in ['.pt', '.pth'] and model_path.exists():
                    pt_files = [model_path]
                else:
                    return None
            
            # Load the model
            checkpoint = torch.load(pt_files[0], map_location=device, weights_only=False)
            
            model = None
            embedding_dim = 768
            
            if isinstance(checkpoint, dict):
                # Try to extract model state dict
                if 'model_state_dict' in checkpoint:
                    state_dict = checkpoint['model_state_dict']
                elif 'state_dict' in checkpoint:
                    state_dict = checkpoint['state_dict']
                else:
                    state_dict = checkpoint
                
                # Try to determine embedding dimension
                if 'embedding_dim' in checkpoint:
                    embedding_dim = checkpoint['embedding_dim']
                elif 'config' in checkpoint and hasattr(checkpoint['config'], 'hidden_size'):
                    embedding_dim = checkpoint['config'].hidden_size
                
                # Create model from state dict
                try:
                    # Try to infer model architecture
                    first_layer = None
                    for key in state_dict.keys():
                        if 'weight' in key and len(state_dict[key].shape) == 2:
                            first_layer = state_dict[key].shape[1]
                            break
                    
                    if first_layer:
                        # Create simple model with matching input dimension
                        model = nn.Sequential(
                            nn.Linear(first_layer, 512),
                            nn.ReLU(),
                            nn.Dropout(0.3),
                            nn.Linear(512, 256),
                            nn.ReLU(),
                            nn.Dropout(0.3),
                            nn.Linear(256, embedding_dim)
                        )
                        model.load_state_dict(state_dict, strict=False)
                    else:
                        model = nn.Sequential(
                            nn.Linear(embedding_dim, 512),
                            nn.ReLU(),
                            nn.Dropout(0.3),
                            nn.Linear(512, embedding_dim)
                        )
                        model.load_state_dict(state_dict, strict=False)
                except Exception as e:
                    logger.debug(f"Failed to create model from state dict: {e}")
                    # Fallback to simple model
                    model = nn.Sequential(
                        nn.Linear(embedding_dim, 512),
                        nn.ReLU(),
                        nn.Linear(512, 256),
                        nn.ReLU(),
                        nn.Linear(256, embedding_dim)
                    )
                    
            elif isinstance(checkpoint, nn.Module):
                model = checkpoint
            else:
                return None
            
            if model is not None:
                model = model.to(device)
                model.eval()
                
                return {
                    'model': model,
                    'embedding_dim': embedding_dim,
                    'type': 'pytorch',
                    'loaded_from': str(pt_files[0])
                }
            
            return None
            
        except Exception as e:
            logger.debug(f"PyTorch model loading failed: {e}")
            return None
    
    @staticmethod
    def _load_onnx_model(model_path: Path, device: torch.device) -> Optional[Dict[str, Any]]:
        """Load an ONNX model"""
        try:
            import onnx
            import onnxruntime as ort
            
            onnx_files = list(model_path.glob("*.onnx"))
            if not onnx_files:
                if model_path.suffix == '.onnx' and model_path.exists():
                    onnx_files = [model_path]
                else:
                    return None
            
            onnx_model = onnx.load(onnx_files[0])
            onnx.checker.check_model(onnx_model)
            
            providers = ['CPUExecutionProvider']
            if device.type == 'cuda':
                providers.insert(0, 'CUDAExecutionProvider')
            
            session = ort.InferenceSession(onnx_files[0], providers=providers)
            
            class ONNXModelWrapper(nn.Module):
                def __init__(self, session):
                    super().__init__()
                    self.session = session
                    self.input_name = session.get_inputs()[0].name
                    
                def forward(self, x):
                    if isinstance(x, torch.Tensor):
                        x = x.cpu().numpy()
                    outputs = self.session.run(None, {self.input_name: x})
                    return torch.FloatTensor(outputs[0])
            
            model = ONNXModelWrapper(session)
            model = model.to(device)
            
            embedding_dim = session.get_outputs()[0].shape[-1] if session.get_outputs() else 768
            
            return {
                'model': model,
                'embedding_dim': embedding_dim,
                'type': 'onnx',
                'loaded_from': str(onnx_files[0])
            }
            
        except Exception as e:
            logger.debug(f"ONNX model loading failed: {e}")
            return None
    
    @staticmethod
    def _load_tensorflow_model(model_path: Path, device: torch.device) -> Optional[Dict[str, Any]]:
        """Load a TensorFlow model"""
        try:
            import tensorflow as tf
            
            if model_path.is_dir() and (model_path / "saved_model.pb").exists():
                tf_model = tf.saved_model.load(str(model_path))
            else:
                h5_files = list(model_path.glob("*.h5")) + list(model_path.glob("*.hdf5"))
                if not h5_files:
                    return None
                tf_model = tf.keras.models.load_model(str(h5_files[0]))
            
            class TFModelWrapper(nn.Module):
                def __init__(self, tf_model):
                    super().__init__()
                    self.tf_model = tf_model
                    self.output_dim = 768
                    try:
                        dummy = np.random.randn(1, 224, 224, 3).astype(np.float32)
                        if hasattr(tf_model, 'predict'):
                            output = tf_model.predict(dummy)
                            self.output_dim = output.shape[-1]
                    except:
                        pass
                
                def forward(self, x):
                    if isinstance(x, torch.Tensor):
                        x = x.cpu().numpy()
                        if len(x.shape) == 4 and x.shape[1] == 3:
                            x = np.transpose(x, (0, 2, 3, 1))
                    
                    if hasattr(self.tf_model, 'predict'):
                        output = self.tf_model.predict(x)
                    else:
                        output = self.tf_model(x)
                    
                    return torch.FloatTensor(output)
            
            model = TFModelWrapper(tf_model)
            model = model.to(device)
            
            return {
                'model': model,
                'embedding_dim': model.output_dim,
                'type': 'tensorflow',
                'loaded_from': str(model_path)
            }
            
        except Exception as e:
            logger.debug(f"TensorFlow model loading failed: {e}")
            return None
    
    @staticmethod
    def _load_huggingface_model(model_path: Path, device: torch.device) -> Optional[Dict[str, Any]]:
        """Load a HuggingFace model"""
        try:
            from transformers import AutoModel, AutoConfig
            
            if not (model_path / "config.json").exists():
                return None
            
            config = AutoConfig.from_pretrained(str(model_path))
            model = AutoModel.from_pretrained(str(model_path))
            
            model = model.to(device)
            model.eval()
            
            embedding_dim = config.hidden_size if hasattr(config, 'hidden_size') else 768
            
            return {
                'model': model,
                'processor': None,
                'embedding_dim': embedding_dim,
                'type': 'huggingface',
                'config': config,
                'loaded_from': str(model_path)
            }
            
        except Exception as e:
            logger.debug(f"HuggingFace model loading failed: {e}")
            return None
    
    @staticmethod
    def _load_custom_model(model_path: Path, device: torch.device) -> Optional[Dict[str, Any]]:
        """Load a custom model from a Python file"""
        try:
            import importlib.util
            import sys
            
            py_files = list(model_path.glob("*.py"))
            if not py_files:
                return None
            
            spec = importlib.util.spec_from_file_location("custom_model", py_files[0])
            module = importlib.util.module_from_spec(spec)
            sys.modules["custom_model"] = module
            spec.loader.exec_module(module)
            
            model_classes = []
            for attr_name in dir(module):
                attr = getattr(module, attr_name)
                if isinstance(attr, type) and issubclass(attr, nn.Module) and attr != nn.Module:
                    model_classes.append(attr)
            
            if not model_classes:
                return None
            
            model_class = model_classes[0]
            model = model_class()
            model = model.to(device)
            model.eval()
            
            embedding_dim = 768
            if hasattr(model, 'embedding_dim'):
                embedding_dim = model.embedding_dim
            
            return {
                'model': model,
                'embedding_dim': embedding_dim,
                'type': 'custom',
                'loaded_from': str(py_files[0])
            }
            
        except Exception as e:
            logger.debug(f"Custom model loading failed: {e}")
            return None
    
    @staticmethod
    def _load_generic_model(model_path: Path, device: torch.device) -> Optional[Dict[str, Any]]:
        """Load a generic PyTorch model as fallback"""
        try:
            from torchvision import models as tv_models
            
            # Try to load ResNet50
            model = tv_models.resnet50(pretrained=True)
            model = nn.Sequential(*list(model.children())[:-1])
            model = model.to(device)
            model.eval()
            
            return {
                'model': model,
                'embedding_dim': 2048,
                'type': 'resnet_fallback',
                'loaded_from': 'pretrained_resnet50'
            }
            
        except Exception as e:
            logger.debug(f"Generic model loading failed: {e}")
            return None


