    @staticmethod
    def _detect_platform():
        """Detect the current platform"""
        import platform
        system = platform.system().lower()
        if 'windows' in system:
            return 'Windows'
        elif 'darwin' in system:
            return 'macOS'
        elif 'linux' in system:
            return 'Linux'
        else:
            return 'Unknown'
    
    @staticmethod
    def _get_backend_name(backend):
        """Get backend name from OpenCV constant"""
        backend_names = {
            cv2.CAP_DSHOW: 'DSHOW',
            cv2.CAP_MSMF: 'MSMF',
            cv2.CAP_V4L2: 'V4L2',
            cv2.CAP_AVFOUNDATION: 'AVFOUNDATION',
            cv2.CAP_ANY: 'AUTO'
        }
        return backend_names.get(backend, 'UNKNOWN')
    
    def analyze_frame_for_api(self, frame, camera_id="default", enable_debug=False):
        """
        API-friendly frame analysis with rate limiting
        """
        try:
            # Temporarily enable debug mode
            original_debug_mode = self.debug_mode
            if enable_debug:
                self.debug_mode = True
            
            # Rate limiting: Check if we should skip detection
            current_time = time.time()
            time_since_last = current_time - self.last_detection_time
            
            if time_since_last < self.detection_stats['min_detection_interval']:
                # Return previous detections to prevent too frequent detection
                if self.previous_detections and enable_debug:
                    logger.debug(f"⏱️ Skipping detection - too soon: {time_since_last:.3f}s")
                
                hazards = self.previous_detections
            else:
                # Run detection
                hazards = self.detect_safety_hazards(frame)
                self.last_detection_time = current_time
                self.previous_detections = hazards
            
            # Calculate metrics
            ppe_violations = [h for h in hazards if h.get('is_ppe_violation', False)]
            critical_hazards = [h for h in hazards if h['risk_level'] == 'critical']
            persons = [h for h in hazards if h.get('is_person', False)]
            workers = [h for h in hazards if h.get('is_worker', False)]
            
            # Enhanced risk score calculation
            risk_score = 25  # Base score
            for hazard in hazards:
                if hazard['risk_level'] == 'critical':
                    risk_score += 30
                elif hazard['risk_level'] == 'high':
                    risk_score += 15
                elif hazard['risk_level'] == 'medium':
                    risk_score += 10
                elif hazard['risk_level'] == 'low':
                    risk_score += 5
            
            risk_score = min(95, max(5, risk_score))
            
            # Determine risk level
            if len(critical_hazards) > 0:
                risk_level = 'CRITICAL'
            elif len(ppe_violations) > 0:
                risk_level = 'HIGH'
            elif risk_score >= 60:
                risk_level = 'MEDIUM'
            elif risk_score >= 40:
                risk_level = 'LOW'
            else:
                risk_level = 'SAFE'
            
            # Get detected classes with colors
            detected_classes = []
            class_colors = {}
            for class_name in set([h['class'] for h in hazards]):
                color = self.get_class_color(class_name)
                detected_classes.append({
                    'class': class_name,
                    'color': color,
                    'count': len([h for h in hazards if h['class'] == class_name])
                })
                class_colors[class_name] = color
            
            # Create comprehensive analysis
            analysis = {
                'risk_level': risk_level,
                'risk_score': risk_score,
                'objects_detected': len(hazards),
                'ppe_violations': len(ppe_violations),
                'critical_hazards': len(critical_hazards),
                'persons_detected': len(persons),
                'workers_detected': len(workers),
                'ai_detections': len(hazards),
                'confidence': min(0.95, 0.5 + (len(hazards) * 0.05)),
                'analysis_method': 'yolov8_19class_safety',
                'model_version': '1.0',
                'timestamp': datetime.now().isoformat(),
                'camera_id': camera_id,
                'color_system_enabled': True,
                'detected_classes': detected_classes,
                'class_colors': class_colors,
                'detection_stats': self.detection_stats.copy(),
                'detection_settings': {
                    'conf_threshold_used': self.confidence_threshold,
                    'detection_rate': f"{1/self.detection_stats['min_detection_interval']:.1f} FPS",
                    'nms_enabled': True
                },
                'hazards': [
                    {
                        'type': h['type'],
                        'class': h['class'],
                        'confidence': h['confidence'],
                        'risk_level': h['risk_level'],
                        'is_ppe_violation': h.get('is_ppe_violation', False),
                        'is_worker': h.get('is_worker', False),
                        'is_person': h.get('is_person', False),
                        'color': h.get('color', self.get_class_color(h['class'])),
                        'bbox': h['bbox'],
                        'bbox_ratio': h.get('bbox_ratio', 0)
                    }
                    for h in hazards[:10]
                ]
            }
            
            # Draw detections with class colors
            processed_frame = self.draw_detections(frame, hazards, show_debug_info=enable_debug)
            
            # Restore debug mode
            self.debug_mode = original_debug_mode
            
            return analysis, processed_frame
            
        except Exception as e:
            logger.error(f"❌ API frame analysis error: {e}")
            
            # Fallback analysis
            fallback_analysis = {
                'risk_level': 'LOW',
                'risk_score': 25,
                'objects_detected': 0,
                'ppe_violations': 0,
                'critical_hazards': 0,
                'persons_detected': 0,
                'workers_detected': 0,
                'ai_detections': 0,
                'confidence': 0.5,
                'analysis_method': 'fallback',
                'timestamp': datetime.now().isoformat(),
                'camera_id': camera_id,
                'color_system_enabled': False,
                'error': str(e)
            }
            
            return fallback_analysis, frame
    
    def get_detection_statistics(self):
        """Get detailed detection statistics including tracking info"""
        stats = {
            'detection_stats': self.detection_stats.copy(),
            'model_info': self.model_info.copy(),
            'ppe_classes': self.ppe_classes.copy(),
            'debug_mode': self.debug_mode,
            'input_format': self.input_format,
            'detection_failures': self.detection_failures,
            'confidence_threshold': self.confidence_threshold,
            'rate_limiting': {
                'min_detection_interval': self.detection_stats['min_detection_interval'],
                'max_detection_fps': 1 / self.detection_stats['min_detection_interval'],
                'nms_enabled': True
            },
            'tracking_info': {
                'unique_persons_tracked': len(self.unique_persons),
                'tracker_type': 'SORT',
                'max_age': 20,
                'min_hits': 3,
                'iou_threshold': 0.3
            }
        }
        return stats
    
    def set_debug_mode(self, enabled=True):
        self.debug_mode = enabled
        if self.model_info:
            self.model_info['debug_mode'] = enabled
        logger.info(f"🔧 Debug mode {'enabled' if enabled else 'disabled'}")
    
    def set_confidence_threshold(self, threshold):
        self.confidence_threshold = threshold
        if self.model_info:
            self.model_info['confidence_threshold'] = threshold
        self.detection_stats['confidence_threshold'] = threshold
        logger.info(f"🎯 Confidence threshold set to: {threshold}")
    
    def set_detection_rate(self, fps=10):
        if fps > 0:
            self.detection_stats['min_detection_interval'] = 1.0 / fps
            logger.info(f"📊 Detection rate set to: {fps} FPS")
    
    def analyze_frame(self, frame, camera_id=None, enable_debug=False):
        return self.analyze_frame_for_api(frame, camera_id, enable_debug)


