            logger.error(f"❌ YOLOv8HazardDetector.analyze_frame error: {e}")
            fallback_analysis = {
                'risk_level': 'LOW',
                'risk_score': 25,
                'objects_detected': 0,
                'ppe_violations': 0,
                'ai_detections': 0,
                'confidence': 0.5,
                'analysis_method': 'fallback',
                'timestamp': datetime.now().isoformat(),
                'camera_id': camera_id
            }
            return fallback_analysis, frame

