safety_detector = None

def initialize_safety_detector(model_path=r'C:\Users\DELL\Downloads\checkpoint_20251205_164718_last.pt', debug_mode=True):
    global safety_detector
    try:
        logger.info("🔄 Initializing Safety Detector with 19-class model...")
        
        possible_paths = [
            model_path,
            r'C:\Users\DELL\Downloads\checkpoint_20251205_164718_last.pt',
            'yolov8/last.pt',
            'yolov8/best.pt'
        ]
        
        actual_path = model_path
        for path in possible_paths:
            if os.path.exists(path):
                actual_path = path
                logger.info(f"✅ Found model at: {path}")
                break
        
        safety_detector = YOLOv8SafetyDetector(
            model_path=actual_path, 
            debug_mode=debug_mode
        )
        
        if safety_detector and safety_detector.model:
            logger.info("🎉 19-Class Safety Detector initialized successfully!")
            logger.info(f"📊 Using model: {os.path.basename(actual_path)}")
            logger.info(f"📊 Model has {safety_detector.model_info['num_classes']} classes")
            logger.info(f"🎯 Confidence threshold: {safety_detector.confidence_threshold}")
            logger.info(f"🔧 Debug mode: {safety_detector.debug_mode}")
            logger.info(f"👤 Tracking: SORT tracker active")
            
            safety_detector.test_camera_connection(0)
            
            return safety_detector
        else:
            logger.error("❌ Safety detector creation failed")
            safety_detector = YOLOv8SafetyDetector(debug_mode=debug_mode)
            return safety_detector
    except Exception as e:
        logger.error(f"💥 Failed to initialize Safety Detector: {e}")
        import traceback
        logger.error(traceback.format_exc())
        return None

def get_safety_detector():
    global safety_detector
    if safety_detector is None:
        return initialize_safety_detector()
    return safety_detector

def detect_available_cameras(max_to_check=10):
    return YOLOv8SafetyDetector.detect_available_cameras(max_to_check)

def analyze_safety_frame(frame, camera_id="default", enable_debug=False):
    try:
        detector = get_safety_detector()
        if detector is None:
            logger.warning("⚠️ Using fallback analysis (no detector)")
            return _get_fallback_analysis(camera_id), frame
        
        analysis, annotated_frame = detector.analyze_frame_for_api(frame, camera_id, enable_debug)
        
        if enable_debug:
            logger.info(f"📊 Safety Analysis: {analysis['risk_level']} risk, "
                       f"{analysis['ppe_violations']} violations, "
                       f"{analysis['objects_detected']} objects, "
                       f"{analysis['persons_detected']} persons")
        
        return analysis, annotated_frame
        
    except Exception as e:
        logger.error(f"❌ Safety analysis error: {e}")
        return _get_fallback_analysis(camera_id), frame

def _get_fallback_analysis(camera_id):
    return {
        'risk_level': 'LOW',
        'risk_score': 25,
        'objects_detected': 0,
        'ppe_violations': 0,
        'ai_detections': 0,
        'confidence': 0.5,
        'analysis_method': 'fallback',
        'timestamp': datetime.now().isoformat(),
        'camera_id': camera_id,
        'hazards': []
    }


