def camera_stream_thread_with_yolov8(camera_id, socketio, session_id):
    """Camera streaming thread with YOLOv8 detection for CCTV feeds"""
    try:
        logger.info(f"🎥 Starting CCTV stream thread for camera {camera_id}")
        
        detector = get_safety_detector()
        
        cap = cv2.VideoCapture(camera_id)
        if not cap.isOpened():
            logger.error(f"❌ Could not open CCTV camera {camera_id}")
            return
        
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        cap.set(cv2.CAP_PROP_FPS, 10)
        
        frame_count = 0
        start_time = time.time()
        
        while camera_sessions.get(camera_id, {}).get('active', False):
            ret, frame = cap.read()
            if not ret:
                logger.warning(f"⚠️ CCTV camera {camera_id} frame read failed")
                break
            
            frame_count += 1
            
            if frame_count % 5 == 0:
                try:
                    if detector:
                        frame_rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                        hazards = detector.detect_safety_hazards(frame_rgb)
                        
                        ppe_violations = [h for h in hazards if h.get('is_ppe_violation', False)]
                        critical_hazards = [h for h in hazards if h['risk_level'] == 'critical']
                        
                        # Get unique person count from tracking
                        unique_persons = detector.get_unique_person_count()
                        
                        risk_score = 25
                        for hazard in hazards:
                            if hazard['risk_level'] == 'critical':
                                risk_score += 30
                            elif hazard['risk_level'] == 'high':
                                risk_score += 15
                            elif hazard['risk_level'] == 'medium':
                                risk_score += 10
                        
                        risk_score = min(95, risk_score)
                        
                        if len(critical_hazards) > 0:
                            risk_level = 'CRITICAL'
                        elif len(ppe_violations) > 0:
                            risk_level = 'HIGH'
                        elif risk_score >= 60:
                            risk_level = 'MEDIUM'
                        elif risk_score >= 40:
                            risk_level = 'LOW'
                        else:
                            risk_level = 'SAFE'
                        
                        analysis = {
                            'risk_level': risk_level,
                            'risk_score': risk_score,
                            'objects_detected': len(hazards),
                            'ppe_violations': len(ppe_violations),
                            'critical_hazards': len(critical_hazards),
                            'persons_detected': unique_persons,
                            'ai_detections': len(hazards),
                            'timestamp': datetime.now().isoformat(),
                            'camera_id': camera_id,
                            'session_id': session_id,
                            'color_system_enabled': True,
                            'confidence_threshold': detector.confidence_threshold,
                            'detected_classes': list(set([h['class'] for h in hazards]))
                        }
                        
                        processed_frame = detector.draw_detections(frame, hazards)
                        
                        _, buffer = cv2.imencode('.jpg', processed_frame, [cv2.IMWRITE_JPEG_QUALITY, 70])
                        frame_data = base64.b64encode(buffer).decode('utf-8')
                        
                        socketio.emit('cctv_frame', {
                            'session_id': session_id,
                            'frame_data': f"data:image/jpeg;base64,{frame_data}",
                            'analysis': analysis,
                            'timestamp': datetime.now().isoformat()
                        })
                        
                        if session_id in active_sessions:
                            active_sessions[session_id]['last_frame'] = datetime.now().isoformat()
                            active_sessions[session_id]['frame_count'] = frame_count
                            
                            if len(ppe_violations) > 0:
                                for violation in ppe_violations:
                                    violation_record = {
                                        'id': str(uuid.uuid4()),
                                        'session_id': session_id,
                                        'camera_id': camera_id,
                                        'type': 'ppe_violation',
                                        'class': violation['class'],
                                        'confidence': violation['confidence'],
                                        'severity': 'high' if violation['class'] == 'no-helmet' else 'medium',
                                        'timestamp': datetime.now().isoformat(),
                                        'acknowledged': False,
                                        'image_data': frame_data[:100] + '...'
                                    }
                                    violation_history.append(violation_record)
                                    active_sessions[session_id]['violations_detected'] += 1
                    
                except Exception as e:
                    logger.error(f"❌ CCTV frame processing error: {e}")
            
            time.sleep(0.1)
        
        cap.release()
        logger.info(f"🎥 CCTV stream thread stopped for camera {camera_id}")
        
    except Exception as e:
        logger.error(f"❌ CCTV stream thread error: {e}")
        import traceback
        logger.error(traceback.format_exc())

    
class PDFReportGenerator:
    """Generate professional PDF reports for safety video analysis"""
    
    def __init__(self, analysis_result, video_path, output_dir='reports'):
        self.analysis = analysis_result
        self.video_path = video_path
        self.output_dir = output_dir
        self.styles = getSampleStyleSheet()
        self._create_custom_styles()
        
        # Ensure output directory exists
        os.makedirs(output_dir, exist_ok=True)
        
