    def generate_filename(self):
        """Generate filename for the report"""
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        filename = f"safety_analysis_{self.analysis.get('id', timestamp)}_{timestamp}.pdf"
        return os.path.join(self.output_dir, filename)
    
    def create_header(self, canvas, doc):
        """Create header for each page"""
        canvas.saveState()
        
        # Draw header line
        canvas.setStrokeColor(colors.HexColor('#3498db'))
        canvas.setLineWidth(2)
        canvas.line(doc.leftMargin, doc.height + doc.topMargin - 10, 
                   doc.width + doc.leftMargin, doc.height + doc.topMargin - 10)
        
        # Add title
        canvas.setFont('Helvetica-Bold', 10)
        canvas.setFillColor(colors.HexColor('#2c3e50'))
        canvas.drawString(doc.leftMargin, doc.height + doc.topMargin, 
                         "SAFETY VIDEO ANALYSIS REPORT")
        
        # Add date
        canvas.setFont('Helvetica', 8)
        canvas.setFillColor(colors.gray)
        canvas.drawRightString(doc.width + doc.leftMargin, doc.height + doc.topMargin,
                              f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M')}")
        
        canvas.restoreState()
    
    def create_footer(self, canvas, doc):
        """Create footer for each page"""
        canvas.saveState()
        
        # Draw footer line
        canvas.setStrokeColor(colors.HexColor('#bdc3c7'))
        canvas.setLineWidth(1)
        canvas.line(doc.leftMargin, doc.bottomMargin - 10, 
                   doc.width + doc.leftMargin, doc.bottomMargin - 10)
        
        # Add page number
        canvas.setFont('Helvetica', 8)
        canvas.setFillColor(colors.gray)
        canvas.drawRightString(doc.width + doc.leftMargin, doc.bottomMargin - 25,
                              f"Page {doc.page}")
        
        # Add company info
        canvas.setFont('Helvetica', 8)
        canvas.drawString(doc.leftMargin, doc.bottomMargin - 25,
                         "AI-Powered Safety Analysis System")
        
        canvas.restoreState()
    
    def generate_risk_gauge(self, risk_score):
        """Generate a risk gauge visualization"""
        try:
            fig, ax = plt.subplots(figsize=(4, 1.5))
            
            # Create gauge
            colors_list = ['#27ae60', '#f1c40f', '#e67e22', '#e74c3c']
            ax.barh([0], [risk_score], color=colors_list[min(3, int(risk_score/25))], 
                   height=0.3, alpha=0.8)
            ax.barh([0], [100], left=[risk_score], color='lightgray', height=0.3, alpha=0.3)
            
            # Add labels
            ax.set_xlim(0, 100)
            ax.set_yticks([])
            ax.set_xticks([0, 25, 50, 75, 100])
            ax.set_xticklabels(['Safe', 'Low', 'Medium', 'High', 'Critical'])
            
            # Add risk score text
            ax.text(risk_score, 0, f' {risk_score}', va='center', ha='left', 
                   fontweight='bold', fontsize=12)
            
            plt.tight_layout()
            
            # Save to BytesIO
            img_data = BytesIO()
            plt.savefig(img_data, format='png', dpi=100, bbox_inches='tight', 
                       facecolor='white', edgecolor='none')
            plt.close()
            img_data.seek(0)
            
            return Image(img_data, width=6*inch, height=1.5*inch)
        except Exception as e:
            print(f"⚠️ Failed to generate risk gauge: {e}")
            return None
    
    def generate_detection_chart(self, class_counts):
        """Generate bar chart of detections"""
        try:
            if not class_counts:
                return None
            
            # Prepare data
            classes = list(class_counts.keys())[:10]  # Top 10
            counts = [class_counts[c] for c in classes]
            
            fig, ax = plt.subplots(figsize=(6, 4))
            
            # Create bar chart
            bars = ax.bar(range(len(classes)), counts, color='#3498db', alpha=0.7)
            
            # Customize
            ax.set_xticks(range(len(classes)))
            ax.set_xticklabels(classes, rotation=45, ha='right', fontsize=8)
            ax.set_ylabel('Detection Count', fontsize=10)
            ax.set_title('Top Detected Objects/Hazards', fontsize=12, fontweight='bold')
            
            # Add value labels on bars
            for i, (bar, count) in enumerate(zip(bars, counts)):
                height = bar.get_height()
                ax.text(bar.get_x() + bar.get_width()/2., height,
                       f'{count}', ha='center', va='bottom', fontsize=8)
            
            plt.tight_layout()
            
            # Save to BytesIO
            img_data = BytesIO()
            plt.savefig(img_data, format='png', dpi=100, bbox_inches='tight',
                       facecolor='white', edgecolor='none')
            plt.close()
            img_data.seek(0)
            
            return Image(img_data, width=6*inch, height=3.5*inch)
        except Exception as e:
            print(f"⚠️ Failed to generate detection chart: {e}")
            return None
    
    def generate_timeline_chart(self, timeline):
        """Generate timeline visualization"""
        try:
            if not timeline:
                return None
            
            fig, ax = plt.subplots(figsize=(6.5, 2))
            
            # Prepare data
            times = [t['start'] for t in timeline]
            risk_levels = [{'CRITICAL': 4, 'HIGH': 3, 'MEDIUM': 2, 'LOW': 1, 'SAFE': 0}
                          .get(t.get('riskLevel', 'SAFE'), 0) for t in timeline]
            
            # Create color map
            colors_list = ['#27ae60', '#f1c40f', '#e67e22', '#e74c3c']
            bar_colors = [colors_list[min(3, max(0, r))] for r in risk_levels]
            
            # Create bar chart
            bars = ax.bar(times, [1]*len(times), width=4, color=bar_colors, alpha=0.7)
            
            # Customize
            ax.set_xlabel('Time (seconds)', fontsize=9)
            ax.set_yticks([])
            ax.set_ylim(0, 1.5)
            ax.set_title('Risk Level Timeline', fontsize=10, fontweight='bold')
            
            # Add legend
            from matplotlib.patches import Patch
            legend_elements = [
                Patch(facecolor='#27ae60', label='SAFE/LOW'),
                Patch(facecolor='#f1c40f', label='MEDIUM'),
                Patch(facecolor='#e67e22', label='HIGH'),
                Patch(facecolor='#e74c3c', label='CRITICAL')
            ]
            ax.legend(handles=legend_elements, loc='upper right', fontsize=7)
            
            plt.tight_layout()
            
            # Save to BytesIO
            img_data = BytesIO()
            plt.savefig(img_data, format='png', dpi=100, bbox_inches='tight',
                       facecolor='white', edgecolor='none')
            plt.close()
            img_data.seek(0)
            
            return Image(img_data, width=6.5*inch, height=2*inch)
        except Exception as e:
            print(f"⚠️ Failed to generate timeline chart: {e}")
            return None
    
