@app.route('/api/camera/<session_id>/stop', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
@limiter.limit("10 per minute")
def stop_yolov_camera_session(session_id):
    """Stop camera monitoring session"""
    try:
        print(f"🛑 Camera stop requested by: {request.user_email}")
        print(f"📹 Session ID: {session_id}")
        
        if session_id in active_sessions:
            # Check if user owns this session (unless admin)
            session_owner_id = active_sessions[session_id].get('user_id')
            if session_owner_id != request.user_id and not request.is_system_team:
                return jsonify({
                    'success': False,
                    'error': 'You can only stop your own camera sessions',
                    'code': 'PERMISSION_DENIED'
                }), 403
            
            camera_id = active_sessions[session_id]['camera_id']
            active_sessions[session_id]['status'] = 'stopped'
            active_sessions[session_id]['stopped_at'] = datetime.utcnow().isoformat()
            active_sessions[session_id]['stopped_by'] = request.user_email
            
            if camera_id in camera_sessions:
                camera_sessions[camera_id]['active'] = False
            
            logger.info(f"Stopped camera session: {session_id} by user {request.user_email}")
            
            # Log this action
            log_activity(
                level='info',
                module='camera',
                action='stop_camera_session',
                description=f'User {request.user_email} stopped camera session',
                user_id=request.user_id,
                resource_id=session_id,
                resource_type='camera_session',
                additional_data={
                    'session_id': session_id,
                    'camera_id': camera_id,
                    'camera_type': active_sessions[session_id].get('type')
                }
            )
            
            return jsonify({
                'success': True,
                'message': 'Camera monitoring stopped successfully',
                'session_id': session_id,
                'status': 'stopped',
                'stopped_by': request.user_email,
                'stopped_at': datetime.utcnow().isoformat()
            }), 200
        else:
            return jsonify({
                'success': False,
                'error': 'Session not found'
            }), 404
    except Exception as e:
        logger.error(f"Stop camera session error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to stop camera session'
        }), 500

# ========== HELPER FUNCTIONS FOR VIDEO ANALYSIS ==========

# ========== HELPER FUNCTIONS FOR COMPREHENSIVE ANALYSIS ==========

def get_risk_level(score):
    """Convert score to risk level"""
    if score >= 80:
        return 'CRITICAL'
    elif score >= 60:
        return 'HIGH'
    elif score >= 40:
        return 'MEDIUM'
    elif score >= 20:
        return 'LOW'
    else:
        return 'SAFE'

def perform_risk_assessment(detections, class_counts):
    """Aggregate risk data from detector's output"""
    # Count by risk level
    critical_risks = [d for d in detections if d.get('risk_level') == 'critical']
    high_risks = [d for d in detections if d.get('risk_level') == 'high']
    medium_risks = [d for d in detections if d.get('risk_level') == 'medium']
    low_risks = [d for d in detections if d.get('risk_level') == 'low']
    
    # Calculate overall risk score
    risk_score = 25
    risk_score += len(critical_risks) * 15
    risk_score += len(high_risks) * 8
    risk_score += len(medium_risks) * 3
    risk_score = min(95, max(5, risk_score))
    
    # Get top hazards
    top_hazards = sorted(class_counts.items(), key=lambda x: x[1], reverse=True)[:5]
    
    return {
        'riskScore': risk_score,
        'riskLevel': get_risk_level(risk_score),
        'criticalRisks': len(critical_risks),
        'highRisks': len(high_risks),
        'mediumRisks': len(medium_risks),
        'lowRisks': len(low_risks),
        'topHazards': [{'class': h[0], 'count': h[1]} for h in top_hazards],
        'immediateActions': []
    }

def perform_incident_investigation(detections, timeline):
    """Analyze for incident patterns"""
    critical_events = [t for t in timeline if t.get('risk_level') == 'critical']
    
    if len(critical_events) > 2:
        likelihood = 'HIGH'
    elif len(critical_events) > 0:
        likelihood = 'MEDIUM'
    else:
        likelihood = 'LOW'
    
    return {
        'hasIncidentIndicators': len(critical_events) > 0,
        'incidentLikelihood': likelihood,
        'criticalEvents': len(critical_events),
        'firstCriticalEvent': critical_events[0]['timestamp'] if critical_events else None,
        'lastCriticalEvent': critical_events[-1]['timestamp'] if critical_events else None
    }

def analyze_work_at_height(height_hazards, safety_equipment, all_detections):
    """Analyze work at height safety"""
    workers = [d for d in all_detections if d.get('is_worker', False) or d.get('is_person', False)]
    
    harness_count = len([e for e in safety_equipment if e['class'] == 'harness'])
    ladder_count = len([h for h in height_hazards if h['class'] == 'ladder'])
    
    compliance_percentage = 0
    if ladder_count > 0:
        compliance_percentage = min(100, (harness_count / ladder_count) * 100)
    
    return {
        'workAtHeightDetected': len(height_hazards) > 0,
        'laddersDetected': ladder_count,
        'harnessDetected': harness_count,
        'workersNearHeight': len(workers) if height_hazards else 0,
        'harnessCompliance': {
            'percentage': compliance_percentage,
            'status': 'GOOD' if compliance_percentage > 80 else 'WARNING' if compliance_percentage > 50 else 'CRITICAL'
        }
    }

def analyze_ppe_compliance(ppe_violations, ppe_items, persons):
    """Analyze PPE compliance"""
    total_persons = len(persons)
    
    if total_persons > 0:
        expected_ppe = total_persons * 2  # helmet + vest
        actual_ppe = len([p for p in ppe_items if p['class'] in ['Hard Hat', 'helmet', 'Reflective Vest', 'vest']])
        compliance_rate = min(100, (actual_ppe / expected_ppe) * 100) if expected_ppe > 0 else 100
    else:
        compliance_rate = 100
    
    no_helmet_count = len([v for v in ppe_violations if v['class'] == 'no-helmet'])
    no_vest_count = len([v for v in ppe_violations if v['class'] == 'no-vest'])
    
    return {
        'complianceRate': compliance_rate,
        'complianceLevel': 'EXCELLENT' if compliance_rate > 90 else 'GOOD' if compliance_rate > 70 else 'POOR' if compliance_rate > 50 else 'CRITICAL',
        'totalViolations': len(ppe_violations),
        'ppeItemsDetected': len(ppe_items),
        'personsDetected': total_persons,
        'violationsByType': {
            'no-helmet': no_helmet_count,
            'no-vest': no_vest_count
        }
    }

def analyze_chemical_hazards(chemical_hazards, all_detections):
    """Analyze chemical hazards"""
    if not chemical_hazards:
        return {
            'chemicalHazardsDetected': False,
            'totalChemicals': 0,
            'workersNearChemicals': 0,
            'msdsRequired': [],
            'riskLevel': 'LOW'
        }
    
    chemical_types = list(set([h['class'] for h in chemical_hazards]))
    
    workers_near = 0
    for chem in chemical_hazards:
        nearby = [d for d in all_detections 
                 if (d.get('is_worker', False) or d.get('is_person', False))
                 and abs(d.get('timestamp', 0) - chem.get('timestamp', 0)) < 2]
        workers_near += len(nearby)
    
    return {
        'chemicalHazardsDetected': True,
        'totalChemicals': len(chemical_hazards),
        'workersNearChemicals': workers_near,
        'msdsRequired': chemical_types,
        'riskLevel': 'HIGH' if workers_near > 0 else 'MEDIUM'
    }

def identify_all_hazards(detections, class_counts):
    """Identify all hazards"""
    categories = {
        'PPE Violations': len([d for d in detections if d.get('is_ppe_violation', False)]),
        'Chemical Hazards': len([d for d in detections if d['class'] == 'chemical']),
        'Fire Hazards': len([d for d in detections if d['class'] == 'fire']),
        'Equipment Hazards': len([d for d in detections if d['class'] in ['Diggingrotation', 'Swingingrotation']]),
        'Work at Height': len([d for d in detections if d['class'] == 'ladder'])
    }
    
    return {
        'totalHazards': len(detections),
        'hazardCategories': categories,
        'topHazards': [{'class': k, 'count': v} for k, v in sorted(class_counts.items(), key=lambda x: x[1], reverse=True)[:10]]
    }

def analyze_emergency_preparedness(fire_hazards, emergency_equipment, all_detections):
    """Analyze emergency preparedness"""
    fire_count = len(fire_hazards)
    harness_count = len([e for e in emergency_equipment if e['class'] == 'harness'])
    
    if fire_count == 0:
        preparedness = 'GOOD'
    elif harness_count > 0:
        preparedness = 'ADEQUATE'
    else:
        preparedness = 'NEEDS_IMPROVEMENT'
    
    return {
        'fireHazardsDetected': fire_count > 0,
        'emergencyEquipmentDetected': {
            'harnesses': harness_count
        },
        'preparednessLevel': preparedness
    }

def analyze_custom_prompt(prompt, detections, timeline, risk_assessment):
    """Custom prompt analysis"""
    prompt_lower = prompt.lower()
    focus_areas = []
    
    if any(word in prompt_lower for word in ['chemical', 'msds', 'hazardous']):
        focus_areas.append('chemical')
    if any(word in prompt_lower for word in ['height', 'ladder', 'fall']):
        focus_areas.append('work_at_height')
    if any(word in prompt_lower for word in ['ppe', 'helmet', 'vest', 'glove']):
        focus_areas.append('ppe')
    if any(word in prompt_lower for word in ['fire', 'emergency', 'evacuation']):
        focus_areas.append('emergency')
    
    return {
        'prompt': prompt,
        'focusAreas': focus_areas if focus_areas else ['general'],
        'summary': f"Analysis focused on: {', '.join(focus_areas) if focus_areas else 'all safety aspects'}"
    }

def generate_detection_timeline(timeline_data, duration):
    """Generate timeline from detections"""
    segments = []
    interval = 5
    
    for start in range(0, int(duration) + interval, interval):
        end = min(start + interval, duration)
        segment_dets = [t for t in timeline_data if start <= t['timestamp'] < end]
        
        if any(t['risk_level'] == 'critical' for t in segment_dets):
            risk = 'CRITICAL'
        elif any(t['risk_level'] == 'high' for t in segment_dets):
            risk = 'HIGH'
        elif any(t['risk_level'] == 'medium' for t in segment_dets):
            risk = 'MEDIUM'
        elif any(t['risk_level'] == 'low' for t in segment_dets):
            risk = 'LOW'
        else:
            risk = 'SAFE'
        
        segments.append({
            'start': round(start, 1),
            'end': round(end, 1),
            'detections': len(segment_dets),
            'riskLevel': risk,
            'hazards': list(set([t['class'] for t in segment_dets]))[:3]
        })
    
    return segments

def calculate_overall_risk_score(risk_assessment, ppe_compliance, chemical_analysis, work_at_height):
    """Calculate overall risk score"""
    scores = [
        risk_assessment.get('riskScore', 25),
        100 - ppe_compliance.get('complianceRate', 100) * 0.7,
        80 if chemical_analysis.get('chemicalHazardsDetected', False) else 20,
        70 if work_at_height.get('workAtHeightDetected', False) else 20
    ]
    return round(sum(scores) / len(scores), 1)

def generate_safety_recommendations(risk_assessment, ppe_compliance, chemical_analysis, work_at_height, emergency_plan):
    """Generate safety recommendations"""
    recommendations = []
    
    if risk_assessment.get('criticalRisks', 0) > 0:
        recommendations.append({
            'priority': 'IMMEDIATE',
            'category': 'Critical Hazards',
            'actions': ['Address critical hazards immediately']
        })
    
    if ppe_compliance.get('complianceRate', 100) < 80:
        actions = []
        if ppe_compliance.get('violationsByType', {}).get('no-helmet', 0) > 0:
            actions.append("Enforce hard hat usage")
        if ppe_compliance.get('violationsByType', {}).get('no-vest', 0) > 0:
            actions.append("Enforce safety vest usage")
        
        recommendations.append({
            'priority': 'HIGH',
            'category': 'PPE Compliance',
            'actions': actions if actions else ["Improve PPE compliance"]
        })
    
    if chemical_analysis.get('chemicalHazardsDetected', False):
        recommendations.append({
            'priority': 'HIGH',
            'category': 'Chemical Safety',
            'actions': [
                "Ensure MSDS sheets are available",
                "Provide chemical handling training"
            ]
        })
    
    if work_at_height.get('workAtHeightDetected', False):
        recommendations.append({
            'priority': 'HIGH',
            'category': 'Work at Height',
            'actions': [
                "Ensure fall protection is used",
                "Inspect ladders and harnesses"
            ]
        })
    
    return recommendations

# ========== END OF HELPER FUNCTIONS ==========


@app.route('/api/ai/video/analyze', methods=['POST'])
@jwt_required
@limiter.limit("10 per minute")
def comprehensive_video_analysis():
    """
    COMPREHENSIVE VIDEO ANALYSIS ENDPOINT
    Detects all 19 classes: chemicals, PPE, hazards, equipment, etc.
    Handles: Risk Assessment, Incident Investigation, Work at Height,
             PPE Compliance, MSDS, Hazard ID, Emergency Planning
    """
    try:
        print(f"\n{'='*60}")
        print(f"🎥 COMPREHENSIVE VIDEO ANALYSIS STARTED")
        print(f"{'='*60}")
        print(f"📧 User: {request.user_email}")
        print(f"🕒 Time: {datetime.now().isoformat()}")
        
        # ========== VALIDATE REQUEST ==========
        if 'analysis_config' not in request.form:
            return jsonify({
                'success': False,
                'error': 'analysis_config is required'
            }), 400
        
        # Parse analysis config
        try:
            analysis_config = json.loads(request.form['analysis_config'])
        except json.JSONDecodeError:
            return jsonify({
                'success': False,
                'error': 'Invalid analysis_config JSON'
            }), 400
        
        print(f"\n📋 ANALYSIS CONFIGURATION:")
        print(json.dumps(analysis_config, indent=2))
        
        # Extract configuration
        analysis_type = analysis_config.get('analysis_type', 'custom')
        industry = analysis_config.get('industry', 'general')
        confidence_threshold = float(analysis_config.get('confidence_threshold', 0.15))
        include_timestamps = analysis_config.get('include_timestamps', True)
        generate_report = analysis_config.get('generate_report', False)
        custom_prompt = analysis_config.get('custom_prompt', '')
        
        # Validate video file
        if 'video' not in request.files:
            return jsonify({
                'success': False,
                'error': 'Video file is required'
            }), 400
        
        video_file = request.files['video']
        if video_file.filename == '':
            return jsonify({
                'success': False,
                'error': 'Empty video filename'
            }), 400
        
        # ========== INITIALIZE DETECTOR ==========
        detector = get_safety_detector()
        if not detector or not detector.model:
            return jsonify({
                'success': False,
                'error': 'YOLOv8 detector not available'
            }), 500
        
        # Store original threshold and set new one
        original_threshold = detector.confidence_threshold
        detector.set_confidence_threshold(confidence_threshold)
        
        print(f"\n🔧 DETECTOR CONFIGURATION:")
        print(f"   • Model: 19-Class YOLOv8 Safety Detector")
        print(f"   • Classes: {detector.model_info.get('num_classes', 19)}")
        print(f"   • Confidence threshold: {confidence_threshold}")
        print(f"   • Analysis type: {analysis_type}")
        print(f"   • Industry: {industry}")
        
        # ========== SAVE VIDEO TEMPORARILY ==========
        temp_dir = 'temp_videos'
        os.makedirs(temp_dir, exist_ok=True)
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        temp_path = os.path.join(temp_dir, f"video_{timestamp}_{video_file.filename}")
        video_file.save(temp_path)
        
        file_size_mb = os.path.getsize(temp_path) / (1024 * 1024)
        print(f"\n💾 VIDEO INFORMATION:")
        print(f"   • Filename: {video_file.filename}")
        print(f"   • Size: {file_size_mb:.2f} MB")
        print(f"   • Path: {temp_path}")
        
        # ========== OPEN VIDEO WITH OPENCV ==========
        cap = cv2.VideoCapture(temp_path)
        if not cap.isOpened():
            return jsonify({
                'success': False,
                'error': 'Failed to open video file'
            }), 400
        
        # Get video properties
        total_frames = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
        fps = cap.get(cv2.CAP_PROP_FPS)
        width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        duration = total_frames / fps if fps > 0 else 0
        
        print(f"\n📊 VIDEO PROPERTIES:")
        print(f"   • Resolution: {width}x{height}")
        print(f"   • Total frames: {total_frames}")
        print(f"   • FPS: {fps:.2f}")
        print(f"   • Duration: {duration:.2f} seconds")
        
        # ========== ANALYZE VIDEO FRAME BY FRAME ==========
        print(f"\n🔍 ANALYZING VIDEO...")
        
        # Sampling rate: analyze every N frames (adjust based on video length)
        if duration < 30:  # Short video (<30s)
            sample_rate = 15  # Analyze every 15 frames
        elif duration < 120:  # Medium video (30s-2min)
            sample_rate = 30  # Analyze every 30 frames
        else:  # Long video (>2min)
            sample_rate = 60  # Analyze every 60 frames
        
        print(f"   • Sampling rate: Every {sample_rate} frames")
        
        frame_count = 0
        analyzed_frames = 0
        all_detections = []
        
        # Tracking for timeline
        timeline_data = []
        
        # Class-specific counters
        class_counts = {}
        ppe_violations = []
        chemical_hazards = []
        fire_hazards = []
        equipment_hazards = []
        work_at_height_hazards = []
        emergency_equipment = []
        
        # For MSDS relevance
        chemical_substances = set()
        
        start_time = time.time()
        
        while True:
            ret, frame = cap.read()
            if not ret:
                break
            
            frame_count += 1
            
            # Analyze sampled frames
            if frame_count % sample_rate == 0:
                analyzed_frames += 1
                timestamp_sec = frame_count / fps
                
                # Progress indicator
                if analyzed_frames % 10 == 0:
                    progress = (frame_count / total_frames) * 100
                    print(f"   ⏳ Progress: {progress:.1f}% ({analyzed_frames} frames analyzed)")
                
                # Convert BGR to RGB for model
                frame_rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                
                # Run detection
                hazards = detector.detect_safety_hazards(frame_rgb)
                
                # Add timestamp to each detection
                for hazard in hazards:
                    hazard['timestamp'] = round(timestamp_sec, 2)
                    hazard['frame'] = frame_count
                
                # Categorize detections based on class
                for hazard in hazards:
                    class_name = hazard['class']
                    
                    # Update class counts
                    if class_name not in class_counts:
                        class_counts[class_name] = 0
                    class_counts[class_name] += 1
                    
                    # Categorize by hazard type
                    if hazard.get('is_ppe_violation', False):
                        ppe_violations.append(hazard)
                    
                    elif class_name in ['chemical']:
                        chemical_hazards.append(hazard)
                        chemical_substances.add(class_name)
                    
                    elif class_name in ['fire']:
                        fire_hazards.append(hazard)
                    
                    elif class_name in ['Diggingrotation', 'Swingingrotation']:
                        equipment_hazards.append(hazard)
                    
                    elif class_name in ['ladder']:
                        work_at_height_hazards.append(hazard)
                    
                    elif class_name in ['harness']:
                        # Safety equipment for height work
                        emergency_equipment.append(hazard)
                    
                    # Store for timeline
                    timeline_data.append({
                        'timestamp': round(timestamp_sec, 2),
                        'class': class_name,
                        'confidence': hazard['confidence'],
                        'risk_level': hazard['risk_level']
                    })
                
                all_detections.extend(hazards)
        
        analysis_time = time.time() - start_time
        cap.release()
        
        print(f"\n✅ ANALYSIS COMPLETE:")
        print(f"   • Frames analyzed: {analyzed_frames}")
        print(f"   • Total detections: {len(all_detections)}")
        print(f"   • Analysis time: {analysis_time:.2f} seconds")
        
        # ========== COMPREHENSIVE ANALYSIS RESULTS ==========
        
        # 1. RISK ASSESSMENT
        risk_assessment = perform_risk_assessment(all_detections, class_counts)
        
        # 2. INCIDENT INVESTIGATION
        incident_investigation = perform_incident_investigation(all_detections, timeline_data)
        
        # 3. WORK AT HEIGHT ANALYSIS
        work_at_height_analysis = analyze_work_at_height(
            work_at_height_hazards, 
            emergency_equipment,
            all_detections
        )
        
        # 4. PPE COMPLIANCE ANALYSIS
        ppe_compliance_analysis = analyze_ppe_compliance(
            ppe_violations,
            [d for d in all_detections if d['class'] in detector.ppe_classes],
            [d for d in all_detections if d.get('is_person', False) or d.get('is_worker', False)]
        )
        
        # 5. CHEMICAL & MSDS ANALYSIS
        chemical_analysis = analyze_chemical_hazards(chemical_hazards, all_detections)
        
        # 6. HAZARD IDENTIFICATION
        hazard_identification = identify_all_hazards(all_detections, class_counts)
        
        # 7. EMERGENCY PLAN ANALYSIS
        emergency_plan_analysis = analyze_emergency_preparedness(
            fire_hazards,
            emergency_equipment,
            all_detections
        )
        
        # 8. CUSTOM PROMPT ANALYSIS (if provided)
        custom_analysis = None
        if custom_prompt:
            custom_analysis = analyze_custom_prompt(
                custom_prompt,
                all_detections,
                timeline_data,
                risk_assessment
            )
        
        # ========== GENERATE TIMELINE ==========
        timeline = generate_detection_timeline(timeline_data, duration)
        
        # ========== CALCULATE OVERALL RISK SCORE ==========
        overall_risk_score = calculate_overall_risk_score(
            risk_assessment,
            ppe_compliance_analysis,
            chemical_analysis,
            work_at_height_analysis
        )
        
        # ========== GENERATE RECOMMENDATIONS ==========
        recommendations = generate_safety_recommendations(
            risk_assessment,
            ppe_compliance_analysis,
            chemical_analysis,
            work_at_height_analysis,
            emergency_plan_analysis
        )
        
        # ========== CREATE FINAL ANALYSIS RESULT ==========
        analysis_id = f"analysis_{timestamp}_{uuid.uuid4().hex[:8]}"
        
        analysis_result = {
            'id': analysis_id,
            'timestamp': datetime.now().isoformat(),
            'fileName': video_file.filename,
            'fileSize': round(file_size_mb, 2),
            'duration': round(duration, 2),
            'analysisType': analysis_type,
            'customPrompt': custom_prompt,
            'industry': industry,
            
            # Video metadata
            'videoMetadata': {
                'width': width,
                'height': height,
                'fps': round(fps, 2),
                'totalFrames': total_frames,
                'analyzedFrames': analyzed_frames,
                'codec': 'H.264'  # You could detect this
            },
            
            # Model information
            'modelInfo': {
                'name': 'YOLOv8 19-Class Safety Detector',
                'version': '2.0',
                'classes': list(detector.model_info.get('classes', {}).values()),
                'numClasses': detector.model_info.get('num_classes', 19),
                'confidenceThreshold': confidence_threshold
            },
            
            # Comprehensive analysis sections
            'riskAssessment': risk_assessment,
            'incidentInvestigation': incident_investigation,
            'workAtHeightAnalysis': work_at_height_analysis,
            'ppeCompliance': ppe_compliance_analysis,
            'chemicalAnalysis': chemical_analysis,
            'hazardIdentification': hazard_identification,
            'emergencyPlanAnalysis': emergency_plan_analysis,
            
            # Overall metrics
            'overallRiskScore': overall_risk_score,
            'overallRiskLevel': get_risk_level(overall_risk_score),
            'recommendations': recommendations,
            
            # Detection summary
            'summary': {
                'totalDetections': len(all_detections),
                'uniqueClasses': list(class_counts.keys()),
                'classCounts': class_counts,
                'ppeViolations': len(ppe_violations),
                'chemicalHazards': len(chemical_hazards),
                'fireHazards': len(fire_hazards),
                'equipmentHazards': len(equipment_hazards),
                'workAtHeightHazards': len(work_at_height_hazards),
                'personsDetected': class_counts.get('person', 0) + class_counts.get('worker', 0)
            },
            
            # Detailed detections (limited to keep response size manageable)
            'detections': [
                {
                    'class': d['class'],
                    'confidence': round(d['confidence'], 3),
                    'riskLevel': d['risk_level'],
                    'timestamp': d.get('timestamp', 0),
                    'isPPEViolation': d.get('is_ppe_violation', False),
                    'isWorker': d.get('is_worker', False),
                    'isPerson': d.get('is_person', False)
                }
                for d in all_detections[:50]  # Limit to 50 detections
            ],
            
            # Detection timeline
            'timeline': timeline,
            
            # Custom analysis results
            'customAnalysis': custom_analysis,
            
            # User context
            'userInfo': {
                'analyzedBy': request.user_email,
                'userId': request.user_id,
                'userPlan': request.effective_plan
            }
        }
        
        # ========== SAVE ANALYSIS TO DATABASE ==========
        try:
            # Create new VideoAnalysis record
            video_analysis = VideoAnalysis(
                user_id=request.user_id,
                video_path=temp_path,
                analysis_results=json.dumps(analysis_result),
                duration=duration,
                violations_count=len(all_detections),
                compliance_score=100 - overall_risk_score,  # Convert risk to compliance
                industry=industry,
                status='completed',
                analyzed_at=datetime.utcnow(),
                processing_time=analysis_time
            )
            
            db.session.add(video_analysis)
            db.session.flush()  # Get the ID without committing yet
            
            # Save each detection as a SafetyViolation
            for detection in all_detections[:100]:  # Limit to 100 for performance
                violation = SafetyViolation(
                    camera_id=f"video_analysis_{video_analysis.id}",
                    violation_type=detection['class'],
                    confidence=detection['confidence'],
                    frame_image=f"video_{video_analysis.id}_frame_{detection.get('frame', 0)}",
                    department=industry,
                    industry=industry,
                    risk_level=detection['risk_level'].upper(),
                    acknowledged=False,
                    analysis_data=json.dumps({
                        'timestamp': detection.get('timestamp', 0),
                        'bbox': detection.get('bbox', []),
                        'is_ppe_violation': detection.get('is_ppe_violation', False)
                    }),
                    timestamp=datetime.utcnow()
                )
                db.session.add(violation)
            
            # Save AI request context
            ai_request = AIRequest(
                user_id=request.user_id,
                request_type='safety_analysis',
                user_input=custom_prompt or analysis_type,
                ai_response=json.dumps(analysis_result['summary']),
                status='completed',
                processing_time=analysis_time,
                created_at=datetime.utcnow()
            )
            db.session.add(ai_request)
            
            # Commit all changes
            db.session.commit()
            
            print(f"✅ Analysis saved to database with ID: {video_analysis.id}")
            
            # Add database ID to result
            analysis_result['database_id'] = video_analysis.id
            
        except Exception as e:
            print(f"⚠️ Failed to save to database: {e}")
            db.session.rollback()
            # Continue even if DB save fails - we still have the analysis result
        
        # ========== GENERATE REPORT IF REQUESTED ==========
        report_url = None
        if generate_report:
            try:
                report_url = generate_pdf_report(analysis_result, temp_path)
                print(f"📄 Report URL: {report_url}")
            except Exception as e:
                print(f"⚠️ Failed to generate report: {e}")
        
        # ========== CLEANUP ==========
        try:
            os.remove(temp_path)
            print(f"🧹 Cleaned up temp file: {temp_path}")
        except Exception as e:
            print(f"⚠️ Failed to delete temp file: {e}")
        
        # Restore original confidence threshold
        detector.set_confidence_threshold(original_threshold)
        
        # ========== LOG ACTIVITY ==========
        log_activity(
            level='info',
            module='ai',
            action='video_analysis',
            description=f'User {request.user_email} analyzed video: {video_file.filename}',
            user_id=request.user_id,
            resource_id=str(video_analysis.id) if 'video_analysis' in locals() else None,
            resource_type='video_analysis',
            additional_data={
                'analysis_id': analysis_id,
                'database_id': video_analysis.id if 'video_analysis' in locals() else None,
                'analysis_type': analysis_type,
                'duration': duration,
                'detections': len(all_detections),
                'risk_score': overall_risk_score,
                'file_size': file_size_mb,
                'report_generated': report_url is not None
            }
        )
        
        print(f"\n{'='*60}")
        print(f"✅ ANALYSIS COMPLETED SUCCESSFULLY")
        print(f"📊 Analysis ID: {analysis_id}")
        print(f"📊 Database ID: {video_analysis.id if 'video_analysis' in locals() else 'N/A'}")
        print(f"📊 Risk Score: {overall_risk_score} - {get_risk_level(overall_risk_score)}")
        print(f"📊 Total Detections: {len(all_detections)}")
        print(f"📊 Report URL: {report_url}")
        print(f"{'='*60}\n")
        
        return jsonify({
            'success': True,
            'analysis': analysis_result,
            'report_url': report_url,
            'database_id': video_analysis.id if 'video_analysis' in locals() else None,
            'message': 'Video analysis completed successfully'
        }), 200
        
    except Exception as e:
        print(f"\n❌ VIDEO ANALYSIS ERROR: {str(e)}")
        import traceback
        traceback.print_exc()
        
        # Cleanup on error
        try:
            if 'temp_path' in locals() and os.path.exists(temp_path):
                os.remove(temp_path)
        except:
            pass
        
        return jsonify({
            'success': False,
            'error': f'Video analysis failed: {str(e)}'
        }), 500
# ========== HELPER FUNCTIONS FOR COMPREHENSIVE ANALYSIS ==========


# ============================================
# 1. GET VIDEO ANALYSIS BY ID
# ============================================
@app.route('/api/ai/video/analysis/<analysis_id>', methods=['GET'])
@jwt_required
def get_video_analysis_by_id(analysis_id):
    """Get specific video analysis by ID"""
    try:
        print(f"\n📊 FETCHING ANALYSIS: {analysis_id}")
        print(f"👤 User: {request.user_email}")
        
        # Try to find by database ID or analysis string ID
        analysis = None
        
        # Try by database ID first
        try:
            if analysis_id.isdigit():
                analysis = VideoAnalysis.query.get(int(analysis_id))
        except:
            pass
        
        # If not found, try by analysis_results JSON containing the ID
        if not analysis:
            analyses = VideoAnalysis.query.filter_by(user_id=request.user_id).all()
            for a in analyses:
                if a.analysis_results:
                    try:
                        results = json.loads(a.analysis_results)
                        if results.get('id') == analysis_id:
                            analysis = a
                            break
                    except:
                        continue
        
        if not analysis:
            return jsonify({
                'success': False,
                'error': 'Video analysis not found'
            }), 404
        
        # Check permissions
        if analysis.user_id != request.user_id and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Permission denied'
            }), 403
        
        # Parse analysis results
        analysis_results = {}
        if analysis.analysis_results:
            try:
                analysis_results = json.loads(analysis.analysis_results)
            except:
                analysis_results = {'raw': analysis.analysis_results}
        
        # Get related violations
        violations = SafetyViolation.query.filter(
            SafetyViolation.frame_image.contains(f"video_{analysis.id}")
        ).order_by(SafetyViolation.timestamp.desc()).limit(50).all()
        
        violations_data = []
        for v in violations:
            violations_data.append({
                'id': v.id,
                'type': v.violation_type,
                'confidence': v.confidence,
                'risk_level': v.risk_level,
                'timestamp': v.timestamp.isoformat() if v.timestamp else None,
                'acknowledged': v.acknowledged
            })
        
        response = {
            'success': True,
            'analysis': {
                'id': analysis.id,
                'analysis_id': analysis_results.get('id', analysis_id),
                'fileName': os.path.basename(analysis.video_path) if analysis.video_path else 'Unknown',
                'duration': analysis.duration,
                'violations_count': analysis.violations_count,
                'compliance_score': analysis.compliance_score,
                'industry': analysis.industry,
                'status': analysis.status,
                'analyzed_at': analysis.analyzed_at.isoformat() if analysis.analyzed_at else None,
                'results': analysis_results,
                'violations': violations_data
            }
        }
        
        print(f"✅ Analysis found: {analysis.id}")
        return jsonify(response), 200
        
    except Exception as e:
        print(f"❌ Error: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


