# 2. GENERATE VIDEO ANALYSIS REPORT
# ============================================
@app.route('/api/ai/video/analysis/<analysis_id>/report', methods=['POST', 'OPTIONS'])
@app.route('/api/video/analysis/<analysis_id>/report', methods=['POST', 'OPTIONS'])
@app.route('/api/api/video/analysis/<analysis_id>/report', methods=['POST', 'OPTIONS'])
@jwt_required
def generate_video_analysis_report(analysis_id):
    """Generate PDF report for a video analysis"""
    try:
        print(f"\n📄 GENERATING REPORT FOR ANALYSIS: {analysis_id}")
        print(f"👤 User: {request.user_email}")
        
        # Get format from request body or query params
        data = request.get_json() or {}
        report_format = data.get('format', request.args.get('format', 'pdf')).lower()
        analysis_type = data.get('type', 'object_detection')
        
        print(f"📋 Format: {report_format}, Type: {analysis_type}")
        
        # Find the analysis
        analysis = None
        
        # Try by database ID
        try:
            if analysis_id.isdigit():
                analysis = VideoAnalysis.query.get(int(analysis_id))
                if analysis:
                    print(f"✅ Found analysis by database ID: {analysis.id}")
        except Exception as e:
            print(f"⚠️ Error searching by ID: {e}")
        
        # If not found, try by analysis_results
        if not analysis:
            try:
                analyses = VideoAnalysis.query.filter_by(user_id=request.user_id).all()
                for a in analyses:
                    if a.analysis_results:
                        try:
                            results = json.loads(a.analysis_results)
                            if results.get('id') == analysis_id:
                                analysis = a
                                print(f"✅ Found analysis by results ID: {analysis.id}")
                                break
                        except:
                            continue
            except Exception as e:
                print(f"⚠️ Error searching by results: {e}")
        
        if not analysis:
            print(f"❌ Analysis not found: {analysis_id}")
            return jsonify({
                'success': False,
                'error': 'Video analysis not found'
            }), 404
        
        # Check permissions
        if analysis.user_id != request.user_id and not request.is_system_team:
            print(f"❌ Permission denied: User {request.user_id} vs Owner {analysis.user_id}")
            return jsonify({
                'success': False,
                'error': 'Permission denied'
            }), 403
        
        # Parse analysis results
        analysis_results = {}
        if analysis.analysis_results:
            try:
                analysis_results = json.loads(analysis.analysis_results)
                print(f"✅ Parsed analysis results JSON")
            except Exception as e:
                print(f"⚠️ Failed to parse analysis_results JSON: {e}")
                analysis_results = {'raw': analysis.analysis_results}
        
        print(f"📊 Analysis summary: Risk Score: {analysis_results.get('overallRiskScore', 'N/A')}, "
              f"Detections: {len(analysis_results.get('detections', []))}")
        
        # Generate report based on format
        if report_format == 'pdf':
            # Generate PDF report
            report_url = generate_pdf_report(analysis_results, analysis.video_path)
            
            if report_url:
                return jsonify({
                    'success': True,
                    'report_url': report_url,
                    'message': 'Report generated successfully',
                    'format': 'pdf'
                }), 200
            else:
                return jsonify({
                    'success': False,
                    'error': 'Failed to generate PDF report'
                }), 500
                
        elif report_format == 'csv':
            # Generate CSV export
            import io
            import csv
            
            output = io.StringIO()
            writer = csv.writer(output)
            
            # Write headers
            writer.writerow(['Timestamp', 'Class', 'Confidence', 'Risk Level', 'Is PPE Violation'])
            
            # Write detections
            detections = analysis_results.get('detections', [])
            for d in detections:
                writer.writerow([
                    d.get('timestamp', 0),
                    d.get('class', 'Unknown'),
                    d.get('confidence', 0),
                    d.get('riskLevel', 'LOW'),
                    d.get('isPPEViolation', False)
                ])
            
            # Add summary section
            writer.writerow([])
            writer.writerow(['SUMMARY'])
            writer.writerow(['Total Detections', len(detections)])
            writer.writerow(['Overall Risk Score', analysis_results.get('overallRiskScore', 0)])
            writer.writerow(['Overall Risk Level', analysis_results.get('overallRiskLevel', 'UNKNOWN')])
            
            # Create response
            response = make_response(output.getvalue())
            response.headers['Content-Type'] = 'text/csv'
            response.headers['Content-Disposition'] = f'attachment; filename=analysis_{analysis_id}_report.csv'
            return response
            
        elif report_format == 'json':
            # Return JSON export
            return jsonify({
                'success': True,
                'analysis': analysis_results,
                'format': 'json',
                'metadata': {
                    'id': analysis.id,
                    'user_id': analysis.user_id,
                    'analyzed_at': analysis.analyzed_at.isoformat() if analysis.analyzed_at else None,
                    'duration': analysis.duration,
                    'violations_count': analysis.violations_count
                }
            }), 200
        
        else:
            return jsonify({
                'success': False,
                'error': f'Unsupported format: {report_format}'
            }), 400
            
    except Exception as e:
        print(f"❌ Error generating report: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': f'Failed to generate report: {str(e)}'
        }), 500

