@app.route('/api/ai/video/analysis/history', methods=['GET', 'POST'])
@jwt_required
def get_video_analysis_history():
    """Get video analysis history for current user"""
    try:
        print(f"\n📋 FETCHING ANALYSIS HISTORY")
        print(f"👤 User: {request.user_email}")
        
        # Get pagination parameters
        page = int(request.args.get('page', 1))
        per_page = int(request.args.get('per_page', 20))
        
        # Build query
        query = VideoAnalysis.query.filter_by(user_id=request.user_id)
        
        # Apply filters from POST body if provided
        if request.method == 'POST' and request.is_json:
            filters = request.get_json()
            if filters.get('industry'):
                query = query.filter_by(industry=filters['industry'])
            if filters.get('status'):
                query = query.filter_by(status=filters['status'])
        
        # Order by most recent
        query = query.order_by(VideoAnalysis.analyzed_at.desc())
        
        # Paginate
        paginated = query.paginate(page=page, per_page=per_page, error_out=False)
        
        history = []
        for a in paginated.items:
            # Parse analysis results to get additional info
            results = {}
            if a.analysis_results:
                try:
                    results = json.loads(a.analysis_results)
                except:
                    pass
            
            history.append({
                'id': a.id,
                'analysis_id': results.get('id', f"analysis_{a.id}"),
                'fileName': os.path.basename(a.video_path) if a.video_path else 'Unknown',
                'duration': a.duration,
                'violations_count': a.violations_count,
                'compliance_score': a.compliance_score,
                'industry': a.industry,
                'status': a.status,
                'analyzed_at': a.analyzed_at.isoformat() if a.analyzed_at else None,
                'risk_level': results.get('overallRiskLevel', 'UNKNOWN'),
                'risk_score': results.get('overallRiskScore', 0),
                'thumbnail': results.get('thumbnail')  # If you store thumbnails
            })
        
        response = {
            'success': True,
            'history': history,
            'pagination': {
                'page': page,
                'per_page': per_page,
                'total': paginated.total,
                'pages': paginated.pages,
                'has_next': paginated.has_next,
                'has_prev': paginated.has_prev
            }
        }
        
        print(f"✅ Found {len(history)} analyses")
        return jsonify(response), 200
        
    except Exception as e:
        print(f"❌ Error: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


