@app.route('/api/ai/video/analysis/<analysis_id>', methods=['DELETE'])
@jwt_required
def delete_video_analysis(analysis_id):
    """Delete a video analysis"""
    try:
        print(f"\n🗑️ DELETING ANALYSIS: {analysis_id}")
        print(f"👤 User: {request.user_email}")
        
        # Find the analysis
        analysis = None
        try:
            if analysis_id.isdigit():
                analysis = VideoAnalysis.query.get(int(analysis_id))
        except:
            pass
        
        if not analysis:
            return jsonify({
                'success': False,
                'error': 'Video analysis not found'
            }), 404
        
        # Check permissions
        if analysis.user_id != request.user_id and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Permission denied'
            }), 403
        
        # Delete related violations
        SafetyViolation.query.filter(
            SafetyViolation.frame_image.contains(f"video_{analysis.id}")
        ).delete()
        
        # Delete the analysis
        db.session.delete(analysis)
        db.session.commit()
        
        print(f"✅ Deleted analysis: {analysis_id}")
        
        return jsonify({
            'success': True,
            'message': 'Video analysis deleted successfully'
        }), 200
        
    except Exception as e:
        print(f"❌ Error: {str(e)}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


