# ============================================
@app.route('/api/ai/video/analysis/bulk-delete', methods=['POST'])
@jwt_required
def bulk_delete_video_analyses():
    """Delete multiple video analyses"""
    try:
        print(f"\n🗑️ BULK DELETING ANALYSES")
        print(f"👤 User: {request.user_email}")
        
        data = request.get_json()
        analysis_ids = data.get('analysis_ids', [])
        
        if not analysis_ids:
            return jsonify({
                'success': False,
                'error': 'No analysis IDs provided'
            }), 400
        
        deleted_count = 0
        for analysis_id in analysis_ids:
            try:
                if str(analysis_id).isdigit():
                    analysis = VideoAnalysis.query.get(int(analysis_id))
                    if analysis and (analysis.user_id == request.user_id or request.is_system_team):
                        # Delete related violations
                        SafetyViolation.query.filter(
                            SafetyViolation.frame_image.contains(f"video_{analysis.id}")
                        ).delete()
                        
                        db.session.delete(analysis)
                        deleted_count += 1
            except:
                continue
        
        db.session.commit()
        
        print(f"✅ Deleted {deleted_count} analyses")
        
        return jsonify({
            'success': True,
            'deleted_count': deleted_count,
            'message': f'Successfully deleted {deleted_count} analyses'
        }), 200
        
    except Exception as e:
        print(f"❌ Error: {str(e)}")
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500


