# 7. GET ANALYSIS STATISTICS
# ============================================
@app.route('/api/ai/video/analysis/statistics', methods=['GET'])
@jwt_required
def get_analysis_statistics():
    """Get statistics about video analyses"""
    try:
        print(f"\n📊 FETCHING ANALYSIS STATISTICS")
        print(f"👤 User: {request.user_email}")
        
        # Get date range from query params
        days = int(request.args.get('days', 30))
        since_date = datetime.utcnow() - timedelta(days=days)
        
        # Base query for user's analyses
        base_query = VideoAnalysis.query.filter(
            VideoAnalysis.user_id == request.user_id,
            VideoAnalysis.analyzed_at >= since_date
        )
        
        # Calculate statistics
        total_analyses = base_query.count()
        total_violations = db.session.query(db.func.sum(VideoAnalysis.violations_count))\
            .filter(VideoAnalysis.user_id == request.user_id,
                   VideoAnalysis.analyzed_at >= since_date).scalar() or 0
        
        avg_compliance = db.session.query(db.func.avg(VideoAnalysis.compliance_score))\
            .filter(VideoAnalysis.user_id == request.user_id,
                   VideoAnalysis.analyzed_at >= since_date).scalar() or 0
        
        # Group by industry
        industry_stats = db.session.query(
            VideoAnalysis.industry,
            db.func.count(VideoAnalysis.id),
            db.func.avg(VideoAnalysis.compliance_score)
        ).filter(
            VideoAnalysis.user_id == request.user_id,
            VideoAnalysis.analyzed_at >= since_date
        ).group_by(VideoAnalysis.industry).all()
        
        # Group by day for trend
        daily_stats = db.session.query(
            db.func.date(VideoAnalysis.analyzed_at),
            db.func.count(VideoAnalysis.id),
            db.func.sum(VideoAnalysis.violations_count)
        ).filter(
            VideoAnalysis.user_id == request.user_id,
            VideoAnalysis.analyzed_at >= since_date
        ).group_by(db.func.date(VideoAnalysis.analyzed_at)).all()
        
        statistics = {
            'total_analyses': total_analyses,
            'total_violations': total_violations,
            'avg_compliance_score': float(avg_compliance) if avg_compliance else 0,
            'by_industry': [
                {
                    'industry': ind,
                    'count': cnt,
                    'avg_compliance': float(comp) if comp else 0
                }
                for ind, cnt, comp in industry_stats
            ],
            'trend': [
                {
                    'date': date.isoformat() if date else None,
                    'count': cnt,
                    'violations': vios
                }
                for date, cnt, vios in daily_stats
            ]
        }
        
        return jsonify({
            'success': True,
            'statistics': statistics
        }), 200
        
    except Exception as e:
        print(f"❌ Error: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


