@app.route('/api/ai/video/analysis/<analysis_id>/export', methods=['GET'])
@jwt_required
def export_analysis_data(analysis_id):
    """Export analysis data in various formats"""
    try:
        print(f"\n📤 EXPORTING ANALYSIS: {analysis_id}")
        
        export_format = request.args.get('format', 'json').lower()
        
        # Find the analysis
        analysis = None
        try:
            if analysis_id.isdigit():
                analysis = VideoAnalysis.query.get(int(analysis_id))
        except:
            pass
        
        if not analysis:
            return jsonify({
                'success': False,
                'error': 'Video analysis not found'
            }), 404
        
        # Check permissions
        if analysis.user_id != request.user_id and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Permission denied'
            }), 403
        
        # Parse analysis results
        analysis_results = {}
        if analysis.analysis_results:
            try:
                analysis_results = json.loads(analysis.analysis_results)
            except:
                analysis_results = {'raw': analysis.analysis_results}
        
        if export_format == 'json':
            return jsonify({
                'success': True,
                'analysis': analysis_results,
                'metadata': {
                    'id': analysis.id,
                    'user_id': analysis.user_id,
                    'analyzed_at': analysis.analyzed_at.isoformat() if analysis.analyzed_at else None,
                    'duration': analysis.duration,
                    'violations_count': analysis.violations_count,
                    'compliance_score': analysis.compliance_score
                }
            }), 200
            
        elif export_format == 'csv':
            import io
            import csv
            
            output = io.StringIO()
            writer = csv.writer(output)
            
            # Write metadata
            writer.writerow(['Metadata', 'Value'])
            writer.writerow(['Analysis ID', analysis.id])
            writer.writerow(['Filename', os.path.basename(analysis.video_path) if analysis.video_path else 'Unknown'])
            writer.writerow(['Analyzed At', analysis.analyzed_at.isoformat() if analysis.analyzed_at else ''])
            writer.writerow(['Duration', analysis.duration])
            writer.writerow(['Total Violations', analysis.violations_count])
            writer.writerow(['Compliance Score', analysis.compliance_score])
            writer.writerow([])
            
            # Write detections
            writer.writerow(['Timestamp', 'Class', 'Confidence', 'Risk Level', 'Is PPE Violation'])
            for d in analysis_results.get('detections', []):
                writer.writerow([
                    d.get('timestamp', 0),
                    d.get('class', 'Unknown'),
                    d.get('confidence', 0),
                    d.get('riskLevel', 'LOW'),
                    d.get('isPPEViolation', False)
                ])
            
            response = make_response(output.getvalue())
            response.headers['Content-Type'] = 'text/csv'
            response.headers['Content-Disposition'] = f'attachment; filename=analysis_{analysis_id}_export.csv'
            return response
            
        else:
            return jsonify({
                'success': False,
                'error': f'Unsupported export format: {export_format}'
            }), 400
            
    except Exception as e:
        print(f"❌ Error: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


