# Add endpoint to get specific analysis
@app.route('/api/ai/video/<analysis_id>', methods=['GET'])
@jwt_required
def get_video_analysis(analysis_id):
    """Get specific video analysis by ID with full details from database"""
    try:
        print(f"\n📊 FETCHING ANALYSIS: {analysis_id}")
        print(f"👤 User: {request.user_email}")
        print(f"🆔 User ID: {request.user_id}")
        
        # ===== FETCH FROM DATABASE =====
        # Try to find by integer ID first (since your VideoAnalysis.id is Integer)
        try:
            # Convert to int if it's a string number
            if analysis_id.isdigit():
                analysis = VideoAnalysis.query.get(int(analysis_id))
            else:
                # If not integer, try to find by custom ID format
                analysis = VideoAnalysis.query.filter(
                    VideoAnalysis.video_path.contains(analysis_id)
                ).first()
        except:
            analysis = None
        
        if not analysis:
            print(f"❌ Analysis not found: {analysis_id}")
            return jsonify({
                'success': False,
                'error': 'Video analysis not found'
            }), 404
        
        # ===== CHECK PERMISSIONS =====
        # Users can only access their own analyses (unless system team)
        if analysis.user_id != request.user_id and not request.is_system_team:
            print(f"❌ Permission denied: User {request.user_id} tried to access analysis {analysis_id} owned by {analysis.user_id}")
            return jsonify({
                'success': False,
                'error': 'You do not have permission to access this analysis'
            }), 403
        
        print(f"✅ Analysis found in database")
        print(f"   • Video: {analysis.video_path}")
        print(f"   • Status: {analysis.status}")
        print(f"   • Violations: {analysis.violations_count}")
        print(f"   • Compliance Score: {analysis.compliance_score}")
        
        # ===== PARSE ANALYSIS RESULTS =====
        analysis_results = {}
        if analysis.analysis_results:
            try:
                analysis_results = json.loads(analysis.analysis_results)
                print(f"✅ Parsed analysis results JSON")
            except json.JSONDecodeError as e:
                print(f"⚠️ Failed to parse analysis_results JSON: {e}")
                analysis_results = {'raw': analysis.analysis_results}
        
        # ===== FETCH RELATED VIOLATIONS =====
        # Find violations associated with this analysis
        # You might need to link them - assuming video_path or upload_file_id connects them
        violations = []
        
        if analysis.upload_file_id:
            # If linked to an upload file, find violations from that file
            violations = SafetyViolation.query.filter(
                SafetyViolation.frame_image.contains(f"upload_{analysis.upload_file_id}")
            ).order_by(SafetyViolation.timestamp.desc()).limit(50).all()
        else:
            # Otherwise try to find by video name
            video_name = os.path.basename(analysis.video_path)
            violations = SafetyViolation.query.filter(
                SafetyViolation.frame_image.contains(video_name)
            ).order_by(SafetyViolation.timestamp.desc()).limit(50).all()
        
        print(f"📊 Found {len(violations)} related violations")
        
        # Format violations for response
        violations_data = []
        for v in violations:
            violation_data = {
                'id': v.id,
                'type': v.violation_type,
                'confidence': v.confidence,
                'risk_level': v.risk_level,
                'timestamp': v.timestamp.isoformat() if v.timestamp else None,
                'acknowledged': v.acknowledged,
                'department': v.department,
                'industry': v.industry
            }
            
            # Parse additional analysis data if available
            if v.analysis_data:
                try:
                    violation_data['analysis'] = json.loads(v.analysis_data)
                except:
                    pass
            
            violations_data.append(violation_data)
        
        # ===== FETCH AI REQUEST CONTEXT =====
        # Find related AI requests for this analysis
        ai_requests = AIRequest.query.filter(
            AIRequest.user_id == analysis.user_id,
            AIRequest.request_type == 'safety_analysis',
            AIRequest.created_at >= analysis.analyzed_at
        ).order_by(AIRequest.created_at.desc()).limit(5).all()
        
        ai_context = []
        for req in ai_requests:
            ai_context.append({
                'id': req.id,
                'type': req.request_type,
                'user_input': req.user_input[:200] + '...' if len(req.user_input) > 200 else req.user_input,
                'ai_response': req.ai_response[:200] + '...' if req.ai_response and len(req.ai_response) > 200 else req.ai_response,
                'created_at': req.created_at.isoformat(),
                'tokens_used': req.tokens_used,
                'company_name': req.company_name
            })
        
        # ===== FETCH CAMERA CONTEXT (if applicable) =====
        camera_context = None
        # Try to extract camera info from video path or violations
        if violations and violations[0].camera_id:
            camera = CameraFeed.query.filter_by(
                monitor_id=violations[0].camera_id
            ).first()
            
            if camera:
                camera_context = {
                    'id': camera.id,
                    'name': camera.name,
                    'location': camera.location,
                    'department': camera.department,
                    'industry': camera.industry,
                    'resolution': camera.resolution,
                    'frame_rate': camera.frame_rate
                }
        
        # ===== BUILD COMPREHENSIVE RESPONSE =====
        response_data = {
            'success': True,
            'analysis': {
                # Basic info
                'id': analysis.id,
                'user_id': analysis.user_id,
                'video_path': analysis.video_path,
                'upload_file_id': analysis.upload_file_id,
                
                # Analysis metadata
                'status': analysis.status,
                'duration': analysis.duration,
                'violations_count': analysis.violations_count,
                'compliance_score': analysis.compliance_score,
                'industry': analysis.industry,
                'analyzed_at': analysis.analyzed_at.isoformat() if analysis.analyzed_at else None,
                'processing_time': analysis.processing_time,
                
                # Full analysis results
                'results': analysis_results,
                
                # Related data
                'violations': violations_data,
                'violations_summary': {
                    'total': len(violations),
                    'by_risk': {
                        'Critical': len([v for v in violations if v.risk_level == 'Critical']),
                        'High': len([v for v in violations if v.risk_level == 'High']),
                        'Medium': len([v for v in violations if v.risk_level == 'Medium']),
                        'Low': len([v for v in violations if v.risk_level == 'Low'])
                    },
                    'by_type': {}
                },
                'ai_requests': ai_context,
                'camera_context': camera_context,
                
                # Permissions
                'access_level': 'owner' if analysis.user_id == request.user_id else 'system_team'
            },
            'user_info': {
                'user_id': request.user_id,
                'user_email': request.user_email,
                'is_system_team': request.is_system_team
            }
        }
        
        # Add violation type summary
        for v in violations:
            v_type = v.violation_type
            if v_type not in response_data['analysis']['violations_summary']['by_type']:
                response_data['analysis']['violations_summary']['by_type'][v_type] = 0
            response_data['analysis']['violations_summary']['by_type'][v_type] += 1
        
        print(f"✅ Successfully retrieved analysis {analysis_id}")
        
        # Log this access
        log_activity(
            level='info',
            module='video_analysis',
            action='view_analysis',
            description=f'User {request.user_email} viewed video analysis {analysis_id}',
            user_id=request.user_id,
            resource_id=str(analysis.id),
            resource_type='video_analysis',
            additional_data={
                'violations_count': analysis.violations_count,
                'compliance_score': analysis.compliance_score
            }
        )
        
        return jsonify(response_data), 200
        
    except Exception as e:
        print(f"❌ Error fetching analysis {analysis_id}: {str(e)}")
        import traceback
        traceback.print_exc()
        
        return jsonify({
            'success': False,
            'error': f'Failed to fetch analysis: {str(e)}'
        }), 500


