@app.route('/api/camera/analyze/frame', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
@limiter.limit("30 per minute")
def analyze_camera_frame():
    """Analyze frame from device camera or CCTV for safety violations using YOLOv8"""
    try:
        print(f"🔍 Frame analysis requested by: {request.user_email}")
        
        data = request.get_json()
        frame_data = data.get('frame_data')
        session_id = data.get('session_id')
        analysis_type = data.get('analysis_type', 'safety_monitoring')
        enable_debug = data.get('enable_debug', False)
        
        if not frame_data:
            return jsonify({
                'success': False,
                'error': 'Frame data is required'
            }), 400
        
        # Check if user has access to this session
        if session_id and session_id in active_sessions:
            session_owner_id = active_sessions[session_id].get('user_id')
            if session_owner_id != request.user_id and not request.is_system_team:
                return jsonify({
                    'success': False,
                    'error': 'You do not have access to this camera session',
                    'code': 'SESSION_ACCESS_DENIED'
                }), 403
        
        # ========== CRITICAL: DEBUG FRAME DATA ==========
        print(f"\n🔍 [ANALYZE] User: {request.user_email}")
        print(f"📧 User Email: {request.user_email}")
        print(f"📋 Data length: {len(frame_data)}")
        print(f"📷 Session ID: {session_id}")
        print(f"🎯 Analysis type: {analysis_type}")
        print(f"🔧 Enable debug: {enable_debug}")
        
        # Initialize YOLOv8 detector
        detector = get_safety_detector()
        if detector is None:
            print("❌ [ANALYZE] Detector not available!")
            return jsonify({
                'success': False,
                'error': 'YOLOv8 detector not available'
            }), 500
        
        print(f"✅ [ANALYZE] Detector loaded: {detector.model is not None}")
        print(f"🎯 [ANALYZE] Confidence threshold: {detector.confidence_threshold}")
        
        # Temporarily enable debug if requested
        original_debug_mode = detector.debug_mode
        if enable_debug:
            detector.set_debug_mode(True)
        
        # Decode the frame data
        try:
            if frame_data.startswith('data:image'):
                frame_data = frame_data.split(',')[1]
                print("✅ [ANALYZE] Extracted base64 from data:image string")
            
            image_data = base64.b64decode(frame_data)
            nparr = np.frombuffer(image_data, np.uint8)
            frame = cv2.imdecode(nparr, cv2.IMREAD_COLOR)
            
            if frame is None:
                print("❌ [ANALYZE] Failed to decode image data")
                return jsonify({
                    'success': False,
                    'error': 'Failed to decode image data'
                }), 400
            
            print(f"✅ [ANALYZE] Frame decoded: {frame.shape}")
            
            # ✅ USE YOLOv8 FOR AI ANALYSIS - uses class confidence threshold
            print(f"🔍 [ANALYZE] Running YOLOv8 detection with confidence {detector.confidence_threshold}...")
            
            hazards = detector.detect_safety_hazards(frame)
            
            print(f"🔍 [ANALYZE] Detected {len(hazards)} hazards")
            
            if hazards:
                print("🎯 [ANALYZE] Detections found:")
                for h in hazards[:5]:
                    color = h.get('color', [255, 255, 255])
                    print(f"   • {h['class']}: {h['confidence']:.3f} (Risk: {h['risk_level']}, Color: {color})")
            
            # Draw detections with class colors
            processed_frame = detector.draw_detections(frame, hazards, show_debug_info=enable_debug)
            
            # Calculate risk metrics
            ppe_violations = [h for h in hazards if h.get('is_ppe_violation', False)]
            critical_hazards = [h for h in hazards if h['risk_level'] == 'critical']
            persons = [h for h in hazards if h.get('is_person', False)]
            workers = [h for h in hazards if h.get('is_worker', False)]
            
            # Enhanced risk score calculation
            risk_score = 25  # Base score
            for hazard in hazards:
                if hazard['risk_level'] == 'critical':
                    risk_score += 30
                elif hazard['risk_level'] == 'high':
                    risk_score += 15
                elif hazard['risk_level'] == 'medium':
                    risk_score += 10
                elif hazard['risk_level'] == 'low':
                    risk_score += 5
            
            risk_score = min(95, max(5, risk_score))  # Clamp between 5-95
            
            # Determine risk level based on detections
            if len(critical_hazards) > 0:
                risk_level = 'CRITICAL'
            elif len(ppe_violations) > 0:
                risk_level = 'HIGH'
            elif risk_score >= 60:
                risk_level = 'MEDIUM'
            elif risk_score >= 40:
                risk_level = 'LOW'
            else:
                risk_level = 'SAFE'
            
            # Get detected classes with colors
            detected_classes = []
            for class_name in set([h['class'] for h in hazards]):
                color = detector.get_class_color(class_name)
                detected_classes.append({
                    'class': class_name,
                    'color': color,
                    'count': len([h for h in hazards if h['class'] == class_name])
                })
            
            # Create comprehensive analysis
            analysis = {
                'risk_level': risk_level,
                'risk_score': risk_score,
                'objects_detected': len(hazards),
                'ppe_violations': len(ppe_violations),
                'critical_hazards': len(critical_hazards),
                'persons_detected': len(persons),
                'workers_detected': len(workers),
                'ai_detections': len(hazards),
                'confidence': min(0.95, 0.5 + (len(hazards) * 0.05)),
                'analysis_method': 'yolov8_19class_safety',
                'model_version': '1.0',
                'confidence_threshold': detector.confidence_threshold,
                'color_system_enabled': True,
                'detected_classes': detected_classes,
                'timestamp': datetime.now().isoformat(),
                'camera_id': f"session_{session_id}",
                'analyzed_by_user': request.user_email,
                'user_id': request.user_id,
                'hazards': [
                    {
                        'type': h['type'],
                        'class': h['class'],
                        'confidence': h['confidence'],
                        'risk_level': h['risk_level'],
                        'is_ppe_violation': h.get('is_ppe_violation', False),
                        'is_worker': h.get('is_worker', False),
                        'is_person': h.get('is_person', False),
                        'color': h.get('color', [255, 255, 255]),
                        'bbox': h['bbox'],
                        'bbox_ratio': h.get('bbox_ratio', 0)
                    }
                    for h in hazards[:10]
                ]
            }
            
            print(f"✅ [ANALYZE] Analysis complete: {len(hazards)} objects, {len(ppe_violations)} violations, {risk_level} risk")
            
            # Convert processed frame back to base64
            _, buffer = cv2.imencode('.jpg', processed_frame, [cv2.IMWRITE_JPEG_QUALITY, 70])
            processed_image_data = base64.b64encode(buffer).decode('utf-8')
            
            # Restore original debug mode
            if enable_debug:
                detector.set_debug_mode(original_debug_mode)
            
            # Log this analysis
            log_activity(
                level='info',
                module='camera',
                action='analyze_frame',
                description=f'User {request.user_email} analyzed camera frame',
                user_id=request.user_id,
                additional_data={
                    'session_id': session_id,
                    'hazards_detected': len(hazards),
                    'ppe_violations': len(ppe_violations),
                    'risk_level': risk_level
                }
            )
            
            return jsonify({
                'success': True,
                'analysis': analysis,
                'processed_image': f"data:image/jpeg;base64,{processed_image_data}",
                'timestamp': datetime.now().isoformat(),
                'session_id': session_id,
                'user_info': {
                    'analyzed_by': request.user_email,
                    'user_id': request.user_id,
                    'effective_plan': request.effective_plan
                },
                'debug_info': {
                    'frame_shape': frame.shape,
                    'detections': len(hazards),
                    'confidence_threshold': detector.confidence_threshold,
                    'model_name': detector.model_info.get('model_name', 'Unknown'),
                    'color_system': 'enabled'
                }
            }), 200
            
        except Exception as e:
            print(f"❌ [ANALYZE] Frame processing error: {str(e)}")
            import traceback
            print(traceback.format_exc())
            
            # Restore original debug mode on error
            if enable_debug:
                detector.set_debug_mode(original_debug_mode)
                
            return jsonify({
                'success': False,
                'error': f'Failed to process frame: {str(e)}'
            }), 400

    except Exception as e:
        print(f"❌ [ANALYZE] Frame analysis error: {str(e)}")
        import traceback
        print(traceback.format_exc())
        return jsonify({
            'success': False,
            'error': f'Failed to analyze frame: {str(e)}'
        }), 500

# =============================================
