@app.route('/api/camera/yolov8/test', methods=['GET'])
def test_yolov8_connection():
    """Test YOLOv8 connection - matches frontend call"""
    try:
        detector = get_safety_detector()
        if detector is None:
            return jsonify({
                'success': False,
                'error': 'YOLOv8 detector not available'
            }), 500
        
        # Test with a simple image
        test_img = np.ones((480, 640, 3), dtype=np.uint8) * 255
        cv2.rectangle(test_img, (200, 150), (440, 380), (150, 150, 150), -1)
        
        hazards = detector.detect_safety_hazards(test_img)
        
        return jsonify({
            'success': True,
            'model_info': {
                'model_name': detector.model_info.get('model_name', 'Unknown'),
                'model_version': detector.model_info.get('version', '1.0'),
                'num_classes': detector.model_info.get('num_classes', 0),
                'classes': list(detector.model_info.get('classes', {}).values()),
                'confidence_threshold': detector.confidence_threshold,
                'color_system': True,
                'status': 'loaded'
            },
            'test_detections': len(hazards),
            'message': 'YOLOv8 model is loaded and ready',
            'timestamp': datetime.now().isoformat()
        }), 200
        
    except Exception as e:
        logger.error(f"YOLOv8 connection test error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'YOLOv8 test failed: {str(e)}'
        }), 500

@app.route('/api/camera/test/yolov8', methods=['GET'])
def test_yolov8_camera():
    """Test YOLOv8 detection on camera"""
    try:
        detector = get_safety_detector()
        if detector is None:
            return jsonify({
                'success': False,
                'error': 'YOLOv8 detector not available'
            }), 500
        
        # Test on default camera
        result = detector.test_live_detection(camera_id=0, duration_seconds=3)
        
        return jsonify({
            'success': result.get('success', False),
            'message': 'YOLOv8 camera test completed',
            'detector_status': 'working' if detector.model else 'failed',
            'model_info': {
                'classes': list(detector.model_info.get('classes', {}).values()) if detector.model_info else [],
                'confidence_threshold': detector.confidence_threshold,
                'color_system': True
            },
            'test_results': result,
            'color_palette': detector.class_colors if hasattr(detector, 'class_colors') else {}
        }), 200
        
    except Exception as e:
        logger.error(f"YOLOv8 camera test error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Test failed: {str(e)}'
        }), 500

@app.route('/api/camera/test-simple', methods=['POST'])
def test_simple_detection():
    """Simple test endpoint with minimal processing"""
    try:
        data = request.get_json()
        frame_data = data.get('frame_data')
        
        if not frame_data:
            return jsonify({'success': False, 'error': 'No frame data'}), 400
        
        # Decode frame
        if frame_data.startswith('data:image'):
            frame_data = frame_data.split(',')[1]
        
        image_data = base64.b64decode(frame_data)
        nparr = np.frombuffer(image_data, np.uint8)
        frame = cv2.imdecode(nparr, cv2.IMREAD_COLOR)
        
        if frame is None:
            return jsonify({'success': False, 'error': 'Failed to decode image'}), 400
        
        # Test with class confidence threshold
        detector = get_safety_detector()
        if detector and detector.model:
            # Test with class confidence threshold
            hazards = detector.detect_safety_hazards(frame)
            
            # Log raw model output
            print(f"🔍 TEST - Frame shape: {frame.shape}")
            print(f"🔍 TEST - Detector model: {detector.model is not None}")
            print(f"🔍 TEST - Confidence threshold: {detector.confidence_threshold}")
            print(f"🔍 TEST - Raw hazards count: {len(hazards)}")
            
            if hazards:
                print(f"🔍 TEST - Hazards found:")
                for h in hazards[:5]:
                    color = h.get('color', [255, 255, 255])
                    print(f"  • {h['class']}: {h['confidence']:.3f} (Color: {color})")
            
            # Get class colors
            class_colors = {}
            for h in hazards:
                class_name = h['class']
                if class_name not in class_colors:
                    class_colors[class_name] = detector.get_class_color(class_name)
            
            return jsonify({
                'success': True,
                'frame_shape': frame.shape,
                'hazards_count': len(hazards),
                'confidence_threshold': detector.confidence_threshold,
                'class_colors': class_colors,
                'hazards': [
                    {
                        'class': h['class'], 
                        'confidence': h['confidence'],
                        'color': h.get('color', [255, 255, 255]),
                        'risk_level': h.get('risk_level', 'low')
                    }
                    for h in hazards[:10]
                ]
            })
        else:
            return jsonify({'success': False, 'error': 'Detector not available'}), 500
            
    except Exception as e:
        print(f"❌ Simple test error: {e}")
        import traceback
        print(traceback.format_exc())
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/camera/debug/detection', methods=['POST'])
@limiter.limit("10 per minute")
def debug_yolov8_detection():
    """Debug endpoint to test YOLOv8 detection with color system"""
    try:
        data = request.get_json()
        frame_data = data.get('frame_data')
        
        if not frame_data:
            return jsonify({
                'success': False,
                'error': 'Frame data is required'
            }), 400
        
        # Decode frame
        if frame_data.startswith('data:image'):
            frame_data = frame_data.split(',')[1]
        
        image_data = base64.b64decode(frame_data)
        nparr = np.frombuffer(image_data, np.uint8)
        frame = cv2.imdecode(nparr, cv2.IMREAD_COLOR)
        
        if frame is None:
            return jsonify({
                'success': False,
                'error': 'Failed to decode image data'
            }), 400
        
        # Test YOLOv8 detection
        detector = get_safety_detector()
        if detector is None:
            return jsonify({
                'success': False,
                'error': 'YOLOv8 detector not initialized'
            }), 500
        
        # Enable debug mode temporarily
        original_debug_mode = detector.debug_mode
        detector.set_debug_mode(True)
        
        # Run detection with class confidence threshold
        hazards = detector.detect_safety_hazards(frame)
        
        # Draw debug information with class colors
        processed_frame = frame.copy()
        
        # Draw all detections with their class colors
        for hazard in hazards:
            bbox = hazard['bbox']
            x1, y1, x2, y2 = map(int, bbox)
            
            # Get class color
            color = hazard.get('color', detector.get_class_color(hazard['class']))
            
            # Create label
            if hazard.get('is_ppe_violation', False):
                label = f"🚨 {hazard['class']} ({hazard['confidence']:.2f})"
                thickness = 3
            elif hazard['class'] == 'person':
                label = f"👤 {hazard['class']} ({hazard['confidence']:.2f})"
                thickness = 2
            elif hazard['class'] in ['Hard Hat', 'helmet']:
                label = f"⛑️ {hazard['class']} ({hazard['confidence']:.2f})"
                thickness = 2
            else:
                label = f"{hazard['class']} ({hazard['confidence']:.2f})"
                thickness = 2
            
            cv2.rectangle(processed_frame, (x1, y1), (x2, y2), color, thickness)
            cv2.putText(processed_frame, label, (x1, y1 - 10),
                       cv2.FONT_HERSHEY_SIMPLEX, 0.5, color, 2)
        
        # Add debug text
        cv2.putText(processed_frame, f"Total detections: {len(hazards)}", (10, 30),
                   cv2.FONT_HERSHEY_SIMPLEX, 0.7, (255, 255, 255), 2)
        cv2.putText(processed_frame, f"Confidence threshold: {detector.confidence_threshold}", (10, 60),
                   cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 255, 255), 2)
        cv2.putText(processed_frame, f"Color system: Enabled", (10, 90),
                   cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 255, 255), 2)
        
        # List detected classes with their colors
        y_offset = 120
        unique_classes = list(set([h['class'] for h in hazards]))
        for i, class_name in enumerate(unique_classes[:6]):  # Show up to 6 classes
            color = detector.get_class_color(class_name)
            count = len([h for h in hazards if h['class'] == class_name])
            cv2.putText(processed_frame, f"{class_name}: {count}", 
                       (10, y_offset + i*20), cv2.FONT_HERSHEY_SIMPLEX, 0.4, color, 1)
            # Draw small color box
            cv2.rectangle(processed_frame, (100, y_offset + i*20 - 5), 
                         (110, y_offset + i*20), color, -1)
        
        # Restore original debug mode
        detector.set_debug_mode(original_debug_mode)
        
        # Encode results
        _, buffer = cv2.imencode('.jpg', processed_frame)
        processed_image_data = base64.b64encode(buffer).decode('utf-8')
        
        # Get class colors mapping
        class_colors = {}
        for h in hazards:
            class_name = h['class']
            if class_name not in class_colors:
                class_colors[class_name] = detector.get_class_color(class_name)
        
        return jsonify({
            'success': True,
            'hazards': hazards,
            'hazard_count': len(hazards),
            'detected_classes': unique_classes,
            'class_colors': class_colors,
            'ppe_violations': len([h for h in hazards if h.get('is_ppe_violation', False)]),
            'processed_image': f"data:image/jpeg;base64,{processed_image_data}",
            'detection_details': {
                'model_loaded': detector.model is not None,
                'model_classes': list(detector.model_info.get('classes', {}).values()) if detector.model_info else [],
                'confidence_threshold': detector.confidence_threshold,
                'color_system': True
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Debug detection error: {str(e)}")
        import traceback
        logger.error(traceback.format_exc())
        return jsonify({
            'success': False,
            'error': f'Debug detection failed: {str(e)}'
        }), 500

# WebRTC Endpoints
@app.route('/api/camera/webrtc/offer', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
@limiter.limit("20 per minute")
def handle_yolov_webrtc_offer():
    """Handle WebRTC offer for device camera streaming"""
    try:
        print(f"📡 WebRTC offer received from: {request.user_email}")
        print(f"👤 User type: {request.user_type}, Plan: {request.effective_plan}")
        
        data = request.get_json()
        session_id = data.get('session_id', f"webrtc_{uuid.uuid4().hex[:8]}")
        
        # Check plan restrictions for WebRTC
        if request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'WebRTC camera streaming requires Pro or Enterprise plan',
                'code': 'PLAN_UPGRADE_REQUIRED',
                'upgrade_url': '/billing/upgrade'
            }), 403
        
        # Store session info with user context
        webrtc_sessions[session_id] = {
            'camera_type': 'browser',
            'created_at': datetime.utcnow().isoformat(),
            'status': 'active',
            'last_activity': datetime.utcnow().isoformat(),
            'ai_model': 'yolov8_19class_safety',
            'user_id': request.user_id,
            'user_email': request.user_email,
            'effective_plan': request.effective_plan
        }
        
        # Log WebRTC session creation
        log_activity(
            level='info',
            module='camera',
            action='create_webrtc_session',
            description=f'User {request.user_email} created WebRTC session',
            user_id=request.user_id,
            resource_id=session_id,
            resource_type='webrtc_session',
            additional_data={
                'session_id': session_id,
                'camera_type': 'browser',
                'user_plan': request.effective_plan
            }
        )
        
        print(f"✅ WebRTC session created: {session_id} for user {request.user_email}")
        
        return jsonify({
            'success': True,
            'message': 'WebRTC connection established',
            'session_id': session_id,
            'camera_type': 'browser',
            'ai_model': 'YOLOv8 19-Class Safety Detector',
            'user_context': {
                'user_id': request.user_id,
                'user_email': request.user_email,
                'effective_plan': request.effective_plan,
                'session_owner': True
            }
        }), 200
        
    except Exception as e:
        logger.error(f"WebRTC offer error for user {request.user_email}: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to handle WebRTC offer: {str(e)}',
            'user_info': {
                'user_email': request.user_email,
                'user_id': request.user_id
            }
        }), 500

@app.route('/api/camera/webrtc/analyze-frame', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
@limiter.limit("30 per minute")
def analyze_yolov_webrtc_frame():
    """Analyze frame from WebRTC browser camera"""
    try:
        print(f"🔍 WebRTC frame analysis requested by: {request.user_email}")
        
        data = request.get_json()
        session_id = data.get('session_id')
        frame_data = data.get('frame_data')
        analysis_type = data.get('analysis_type', 'safety_monitoring')
        enable_debug = data.get('enable_debug', False)
        
        if not session_id or not frame_data:
            return jsonify({
                'success': False,
                'error': 'Session ID and frame data are required',
                'code': 'MISSING_PARAMETERS'
            }), 400
        
        # Check if user has access to this session
        if session_id in webrtc_sessions:
            session_owner_id = webrtc_sessions[session_id].get('user_id')
            if session_owner_id != request.user_id and not request.is_system_team:
                return jsonify({
                    'success': False,
                    'error': 'You do not have access to this WebRTC session',
                    'code': 'SESSION_ACCESS_DENIED'
                }), 403
            
            # Update session activity
            webrtc_sessions[session_id]['last_activity'] = datetime.utcnow().isoformat()
            webrtc_sessions[session_id]['frames_analyzed'] = webrtc_sessions[session_id].get('frames_analyzed', 0) + 1
        else:
            # Create new session if not exists (for backward compatibility)
            webrtc_sessions[session_id] = {
                'camera_type': 'browser',
                'created_at': datetime.utcnow().isoformat(),
                'status': 'active',
                'last_activity': datetime.utcnow().isoformat(),
                'ai_model': 'yolov8_19class_safety',
                'user_id': request.user_id,
                'user_email': request.user_email,
                'frames_analyzed': 1
            }
        
        # ========== DEBUG INFO ==========
        print(f"\n🔍 [WebRTC] User: {request.user_email}")
        print(f"📧 User Email: {request.user_email}")
        print(f"📋 Frame data length: {len(frame_data)}")
        print(f"📷 Session ID: {session_id}")
        print(f"🎯 Analysis type: {analysis_type}")
        print(f"🔧 Enable debug: {enable_debug}")
        
        # Decode base64 frame data
        try:
            if frame_data.startswith('data:image'):
                frame_data = frame_data.split(',')[1]
                print("✅ [WebRTC] Extracted base64 from data:image string")
            
            image_data = base64.b64decode(frame_data)
            nparr = np.frombuffer(image_data, np.uint8)
            frame = cv2.imdecode(nparr, cv2.IMREAD_COLOR)
            
            if frame is None:
                print("❌ [WebRTC] Failed to decode image data")
                return jsonify({
                    'success': False,
                    'error': 'Failed to decode image data'
                }), 400
            
            print(f"✅ [WebRTC] Frame decoded: {frame.shape}")
            
            # Analyze the frame with AI
            detector = get_safety_detector()
            if detector:
                print(f"🔍 [WebRTC] Running YOLOv8 detection...")
                hazards = detector.detect_safety_hazards(frame)
                print(f"✅ [WebRTC] Detected {len(hazards)} hazards")
                
                # Sample logging of detections
                if hazards and len(hazards) > 0:
                    print("🎯 [WebRTC] Sample detections:")
                    for h in hazards[:3]:
                        print(f"   • {h['class']}: {h['confidence']:.3f} (Risk: {h['risk_level']})")
                
                ppe_violations = [h for h in hazards if h.get('is_ppe_violation', False)]
                critical_hazards = [h for h in hazards if h['risk_level'] == 'critical']
                persons = [h for h in hazards if h.get('is_person', False)]
                workers = [h for h in hazards if h.get('is_worker', False)]
                
                # Calculate risk score
                risk_score = 25  # Base score
                for hazard in hazards:
                    if hazard['risk_level'] == 'critical':
                        risk_score += 30
                    elif hazard['risk_level'] == 'high':
                        risk_score += 15
                    elif hazard['risk_level'] == 'medium':
                        risk_score += 10
                    elif hazard['risk_level'] == 'low':
                        risk_score += 5
                
                risk_score = min(95, max(5, risk_score))  # Clamp between 5-95
                
                # Determine risk level
                if len(critical_hazards) > 0:
                    risk_level = 'CRITICAL'
                elif len(ppe_violations) > 0:
                    risk_level = 'HIGH'
                elif risk_score >= 60:
                    risk_level = 'MEDIUM'
                elif risk_score >= 40:
                    risk_level = 'LOW'
                else:
                    risk_level = 'SAFE'
                
                # Get detected classes
                detected_classes = list(set([h['class'] for h in hazards]))
                
                analysis = {
                    'risk_level': risk_level,
                    'risk_score': risk_score,
                    'objects_detected': len(hazards),
                    'ppe_violations': len(ppe_violations),
                    'critical_hazards': len(critical_hazards),
                    'persons_detected': len(persons),
                    'workers_detected': len(workers),
                    'ai_detections': len(hazards),
                    'confidence_threshold': detector.confidence_threshold,
                    'color_system': True,
                    'detected_classes': detected_classes,
                    'timestamp': datetime.utcnow().isoformat(),
                    'analyzed_by_user': request.user_email,
                    'user_id': request.user_id,
                    'hazards_sample': [
                        {
                            'class': h['class'],
                            'confidence': h['confidence'],
                            'risk_level': h['risk_level'],
                            'is_ppe_violation': h.get('is_ppe_violation', False)
                        }
                        for h in hazards[:5]
                    ] if hazards else []
                }
            else:
                print("⚠️ [WebRTC] Detector not available, returning fallback analysis")
                analysis = {
                    'risk_level': 'LOW',
                    'risk_score': 25,
                    'objects_detected': 0,
                    'ppe_violations': 0,
                    'critical_hazards': 0,
                    'persons_detected': 0,
                    'workers_detected': 0,
                    'ai_detections': 0,
                    'confidence_threshold': 0.15,
                    'color_system': False,
                    'detected_classes': [],
                    'timestamp': datetime.utcnow().isoformat(),
                    'analyzed_by_user': request.user_email,
                    'user_id': request.user_id
                }
            
            print(f"✅ [WebRTC] Analysis complete: {len(hazards) if detector else 0} objects, Risk: {analysis['risk_level']}")
            
            # Log successful frame analysis
            log_activity(
                level='info',
                module='camera',
                action='analyze_webrtc_frame',
                description=f'User {request.user_email} analyzed WebRTC frame',
                user_id=request.user_id,
                additional_data={
                    'session_id': session_id,
                    'hazards_detected': analysis.get('objects_detected', 0),
                    'ppe_violations': analysis.get('ppe_violations', 0),
                    'risk_level': analysis.get('risk_level', 'UNKNOWN')
                }
            )
            
            return jsonify({
                'success': True,
                'analysis': analysis,
                'timestamp': datetime.utcnow().isoformat(),
                'session_id': session_id,
                'user_context': {
                    'analyzed_by': request.user_email,
                    'user_id': request.user_id,
                    'effective_plan': request.effective_plan,
                    'session_owner': webrtc_sessions.get(session_id, {}).get('user_id') == request.user_id
                },
                'debug_info': {
                    'frame_shape': frame.shape if 'frame' in locals() else 'N/A',
                    'detections': len(hazards) if detector else 0,
                    'confidence_threshold': detector.confidence_threshold if detector else 0.15,
                    'color_system_enabled': detector is not None
                }
            }), 200
            
        except Exception as e:
            print(f"❌ [WebRTC] Frame processing error: {str(e)}")
            import traceback
            traceback.print_exc()
            
            # Log the error
            log_activity(
                level='error',
                module='camera',
                action='webrtc_frame_error',
                description=f'WebRTC frame analysis error for user {request.user_email}',
                user_id=request.user_id,
                additional_data={
                    'session_id': session_id,
                    'error': str(e)[:200]
                }
            )
            
            return jsonify({
                'success': False,
                'error': f'Failed to process frame: {str(e)}'
            }), 400
        
    except Exception as e:
        logger.error(f"WebRTC frame analysis error for user {request.user_email}: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to analyze frame: {str(e)}',
            'user_info': {
                'user_email': request.user_email,
                'user_id': request.user_id
            }
        }), 500

@app.route('/api/camera/webrtc/sessions/active', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
@limiter.limit("15 per minute")
def get_active_webrtc_sessions():
    """Get all active WebRTC sessions"""
    try:
        print(f"📡 Active WebRTC sessions requested by: {request.user_email}")
        
        active_list = []
        for session_id, session in webrtc_sessions.items():
            # Filter by user access (unless system team)
            if request.is_system_team or session.get('user_id') == request.user_id:
                if session.get('status') == 'active':
                    # Calculate session duration
                    created_at = datetime.fromisoformat(session.get('created_at', datetime.utcnow().isoformat()))
                    duration_minutes = int((datetime.utcnow() - created_at).total_seconds() / 60)
                    
                    active_list.append({
                        'session_id': session_id,
                        'camera_type': session.get('camera_type', 'browser'),
                        'created_at': session.get('created_at'),
                        'last_activity': session.get('last_activity'),
                        'duration_minutes': duration_minutes,
                        'frames_analyzed': session.get('frames_analyzed', 0),
                        'ai_model': session.get('ai_model', 'yolov8_19class_safety'),
                        'user_email': session.get('user_email', 'Unknown'),
                        'user_plan': session.get('effective_plan', 'unknown'),
                        'is_owned_by_me': session.get('user_id') == request.user_id
                    })
        
        # Log this access
        log_activity(
            level='info',
            module='camera',
            action='view_webrtc_sessions',
            description=f'User {request.user_email} viewed active WebRTC sessions',
            user_id=request.user_id,
            additional_data={'active_sessions_count': len(active_list)}
        )
        
        print(f"✅ Active WebRTC sessions: {len(active_list)} for user {request.user_email}")
        
        return jsonify({
            'success': True,
            'active_sessions': active_list,
            'total_active': len(active_list),
            'access_info': {
                'viewed_by': request.user_email,
                'showing_my_sessions_only': not request.is_system_team,
                'is_system_team': request.is_system_team
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Get active WebRTC sessions error for {request.user_email}: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to get active WebRTC sessions'
        }), 500

@app.route('/api/camera/webrtc/session/<session_id>/stop', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
@limiter.limit("10 per minute")
def stop_webrtc_session(session_id):
    """Stop WebRTC camera session"""
    try:
        print(f"🛑 WebRTC stop requested by: {request.user_email}")
        print(f"📡 Session ID: {session_id}")
        
        if session_id in webrtc_sessions:
            # Check if user owns this session (unless admin)
            session_owner_id = webrtc_sessions[session_id].get('user_id')
            if session_owner_id != request.user_id and not request.is_system_team:
                return jsonify({
                    'success': False,
                    'error': 'You can only stop your own WebRTC sessions',
                    'code': 'PERMISSION_DENIED'
                }), 403
            
            webrtc_sessions[session_id]['status'] = 'stopped'
            webrtc_sessions[session_id]['stopped_at'] = datetime.utcnow().isoformat()
            webrtc_sessions[session_id]['stopped_by'] = request.user_email
            
            logger.info(f"Stopped WebRTC session: {session_id} by user {request.user_email}")
            
            # Log this action
            log_activity(
                level='info',
                module='camera',
                action='stop_webrtc_session',
                description=f'User {request.user_email} stopped WebRTC session',
                user_id=request.user_id,
                resource_id=session_id,
                resource_type='webrtc_session',
                additional_data={
                    'session_id': session_id,
                    'frames_analyzed': webrtc_sessions[session_id].get('frames_analyzed', 0),
                    'duration_minutes': int((datetime.utcnow() - datetime.fromisoformat(webrtc_sessions[session_id].get('created_at'))).total_seconds() / 60)
                }
            )
            
            return jsonify({
                'success': True,
                'message': 'WebRTC session stopped successfully',
                'session_id': session_id,
                'status': 'stopped',
                'stopped_by': request.user_email,
                'stopped_at': datetime.utcnow().isoformat(),
                'session_stats': {
                    'frames_analyzed': webrtc_sessions[session_id].get('frames_analyzed', 0),
                    'duration_minutes': int((datetime.utcnow() - datetime.fromisoformat(webrtc_sessions[session_id].get('created_at'))).total_seconds() / 60)
                }
            }), 200
        else:
            return jsonify({
                'success': False,
                'error': 'WebRTC session not found'
            }), 404
    except Exception as e:
        logger.error(f"Stop WebRTC session error for {request.user_email}: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to stop WebRTC session'
        }), 500


@app.route('/api/camera/test-detection', methods=['GET'])
def test_detection():
    """Test if YOLOv8 detection is working"""
    try:
        detector = get_safety_detector()
        if not detector or not detector.model:
            return jsonify({
                'success': False, 
                'error': 'Detector not loaded',
                'color_system': False
            })
        
        # Create a test image with a person
        test_img = np.ones((480, 640, 3), dtype=np.uint8) * 255
        cv2.rectangle(test_img, (200, 150), (440, 380), (150, 150, 150), -1)
        cv2.circle(test_img, (320, 120), 50, (150, 150, 150), -1)
        
        # Run detection with class confidence threshold
        hazards = detector.detect_safety_hazards(test_img)
        
        # Get class colors
        class_colors = {}
        for h in hazards:
            class_name = h['class']
            if class_name not in class_colors:
                class_colors[class_name] = detector.get_class_color(class_name)
        
        return jsonify({
            'success': True,
            'detections': len(hazards),
            'classes_found': list(set([h['class'] for h in hazards])),
            'class_colors': class_colors,
            'confidence_threshold': detector.confidence_threshold,
            'color_system': True,
            'message': f'Found {len(hazards)} detections with confidence threshold {detector.confidence_threshold}'
        })
    except Exception as e:
        return jsonify({
            'success': False, 
            'error': str(e),
            'color_system': False
        })

# SocketIO event handlers
@socketio.on('connect')
def handle_connect():
    logger.info(f"Client connected: {request.sid}")

@socketio.on('disconnect')
def handle_disconnect():
    logger.info(f"Client disconnected: {request.sid}")

@socketio.on('camera_frame')
def handle_camera_frame(data):
    """Handle camera frame from client"""
    try:
        session_id = data.get('session_id')
        frame_data = data.get('frame_data')
        
        if not session_id or not frame_data:
            return
        
        # Process frame with YOLOv8
        detector = get_safety_detector()
        if detector:
            # Decode frame
            if frame_data.startswith('data:image'):
                frame_data = frame_data.split(',')[1]
            
            image_data = base64.b64decode(frame_data)
            nparr = np.frombuffer(image_data, np.uint8)
            frame = cv2.imdecode(nparr, cv2.IMREAD_COLOR)
            
            if frame is not None:
                hazards = detector.detect_safety_hazards(frame)
                
                # Send analysis back
                emit('frame_analysis', {
                    'session_id': session_id,
                    'hazards_count': len(hazards),
                    'ppe_violations': len([h for h in hazards if h.get('is_ppe_violation', False)]),
                    'detected_classes': list(set([h['class'] for h in hazards])),
                    'timestamp': datetime.utcnow().isoformat()
                })
                
    except Exception as e:
        logger.error(f"SocketIO frame handling error: {e}")




class DocumentGenerator:
    def __init__(self):
        self.templates_dir = "templates"
        self.output_dir = "generated_documents"
        os.makedirs(self.output_dir, exist_ok=True)
    
    # ========== PUBLIC METHODS ==========
    
    def generate_iso_compliance_report(self, data, format_type='pdf'):
        """Generate ISO 14001 Environmental Management System Report"""
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        
        if format_type == 'pdf':
            filename = f"ISO_14001_Compliance_Report_{timestamp}.pdf"
            filepath = os.path.join(self.output_dir, filename)
            self._generate_iso_pdf(data, filepath)
        elif format_type == 'excel':
            filename = f"ISO_14001_Data_{timestamp}.xlsx"
            filepath = os.path.join(self.output_dir, filename)
            self._generate_iso_excel(data, filepath)
        elif format_type == 'word':
            filename = f"ISO_14001_Report_{timestamp}.docx"
            filepath = os.path.join(self.output_dir, filename)
            self._generate_iso_word(data, filepath)
        else:
            # Default to PDF
            filename = f"ISO_14001_Compliance_Report_{timestamp}.pdf"
            filepath = os.path.join(self.output_dir, filename)
            self._generate_iso_pdf(data, filepath)
        
        return filename, filepath
    
