    def _generate_iso_excel(self, data, filepath):
        """Generate ISO 14001 Excel Report"""
        try:
            import pandas as pd
            from openpyxl import Workbook
            from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
            
            with pd.ExcelWriter(filepath, engine='openpyxl') as writer:
                # Company Info Sheet
                company_info = {
                    'Company Name': [data.get('company_name', 'Environmental Solutions Inc.')],
                    'Report Period': [data.get('report_period', 'Q1 2024')],
                    'Generated Date': [datetime.now().strftime('%Y-%m-%d %H:%M:%S')],
                    'Compliance Status': [data.get('compliance_status', 'COMPLIANT')]
                }
                info_df = pd.DataFrame(company_info)
                info_df.to_excel(writer, sheet_name='Company Info', index=False)
                
                # Environmental Performance Sheet
                env_data = data.get('environmental_performance', {})
                performance_df = pd.DataFrame({
                    'Parameter': ['Carbon Emissions', 'Water Usage', 'Waste Generated', 'Energy Consumption'],
                    'Value': [
                        env_data.get('carbon_emissions', 850),
                        env_data.get('water_usage', 3200),
                        env_data.get('waste_generated', 1500),
                        env_data.get('energy_consumption', 8500)
                    ],
                    'Unit': ['tCO₂e', 'm³', 'kg', 'kWh'],
                    'Target': ['< 1000', '< 5000', '< 2000', '< 10000'],
                    'Status': ['Within Limit', 'Within Limit', 'Within Limit', 'Within Limit']
                })
                performance_df.to_excel(writer, sheet_name='Environmental Performance', index=False)
                
                # Compliance Checklist Sheet
                compliance_df = pd.DataFrame({
                    'ISO 14001 Requirement': [
                        'Environmental Policy',
                        'Planning',
                        'Implementation & Operation',
                        'Checking & Corrective Action',
                        'Management Review'
                    ],
                    'Status': ['Compliant', 'Compliant', 'Compliant', 'Compliant', 'Compliant'],
                    'Evidence': ['Policy Document v2.1', 'Objectives & Targets 2024', 
                                'Operational Controls', 'Audit Report Q1 2024', 'Review Minutes 2024-02-15'],
                    'Next Review Date': [
                        (datetime.now() + timedelta(days=90)).strftime('%Y-%m-%d'),
                        (datetime.now() + timedelta(days=60)).strftime('%Y-%m-%d'),
                        (datetime.now() + timedelta(days=30)).strftime('%Y-%m-%d'),
                        (datetime.now() + timedelta(days=45)).strftime('%Y-%m-%d'),
                        (datetime.now() + timedelta(days=180)).strftime('%Y-%m-%d')
                    ]
                })
                compliance_df.to_excel(writer, sheet_name='Compliance Checklist', index=False)
                
                # Format the Excel sheets
                workbook = writer.book
                for sheet_name in workbook.sheetnames:
                    worksheet = workbook[sheet_name]
                    
                    # Format headers
                    for cell in worksheet[1]:
                        cell.font = Font(bold=True, color="FFFFFF")
                        cell.fill = PatternFill(start_color="27AE60", end_color="27AE60", fill_type="solid")
                        cell.alignment = Alignment(horizontal='center')
                    
                    # Adjust column widths
                    for column in worksheet.columns:
                        max_length = 0
                        column_letter = column[0].column_letter
                        for cell in column:
                            try:
                                if len(str(cell.value)) > max_length:
                                    max_length = len(str(cell.value))
                            except:
                                pass
                        adjusted_width = min(max_length + 2, 50)
                        worksheet.column_dimensions[column_letter].width = adjusted_width
            
            print(f"✅ Excel generated successfully: {filepath}")
            
        except ImportError:
            print("⚠️ pandas or openpyxl not installed, using fallback")
            # Simple fallback using openpyxl directly
            from openpyxl import Workbook
            
            wb = Workbook()
            ws = wb.active
            ws.title = "ISO 14001 Report"
            
            # Add headers and data
            ws['A1'] = 'ISO 14001 Environmental Management System Report'
            ws['A1'].font = Font(bold=True, size=14)
            
            # Add more data...
            wb.save(filepath)
    
    def _generate_iso_word(self, data, filepath):
        """Generate ISO 14001 Word Document with proper formatting"""
        try:
            from docx import Document
            from docx.shared import Inches, Pt, RGBColor
            from docx.enum.text import WD_ALIGN_PARAGRAPH
            from docx.enum.table import WD_TABLE_ALIGNMENT
            
            doc = Document()
            
            # Title
            title = doc.add_heading('ISO 14001:2015 Environmental Management System Report', 0)
            title.alignment = WD_ALIGN_PARAGRAPH.CENTER
            
            # Company Information
            doc.add_heading('Company Information', level=1)
            p = doc.add_paragraph()
            p.add_run('Company Name: ').bold = True
            p.add_run(data.get('company_name', 'Environmental Solutions Inc.'))
            
            p = doc.add_paragraph()
            p.add_run('Report Period: ').bold = True
            p.add_run(data.get('report_period', 'Q1 2024'))
            
            p = doc.add_paragraph()
            p.add_run('Generated Date: ').bold = True
            p.add_run(datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
            
            p = doc.add_paragraph()
            p.add_run('Compliance Status: ').bold = True
            status_run = p.add_run(data.get('compliance_status', 'COMPLIANT'))
            status_run.font.color.rgb = RGBColor(39, 174, 96)  # Green
            status_run.bold = True
            p.add_run(' ✓')
            
            doc.add_paragraph()
            
            # Environmental Performance
            doc.add_heading('Environmental Performance Parameters', level=1)
            
            env_data = data.get('environmental_performance', {})
            
            # Create table
            table = doc.add_table(rows=5, cols=4)
            table.style = 'Light Shading Accent 3'
            table.alignment = WD_TABLE_ALIGNMENT.CENTER
            
            # Header row
            hdr_cells = table.rows[0].cells
            hdr_cells[0].text = 'Parameter'
            hdr_cells[1].text = 'Value'
            hdr_cells[2].text = 'Target'
            hdr_cells[3].text = 'Status'
            
            # Data rows
            parameters = [
                ('Carbon Emissions (tCO₂e)', env_data.get('carbon_emissions', 850), '< 1000', '✓ Within Limit'),
                ('Water Usage (m³)', env_data.get('water_usage', 3200), '< 5000', '✓ Within Limit'),
                ('Waste Generated (kg)', env_data.get('waste_generated', 1500), '< 2000', '✓ Within Limit'),
                ('Energy Consumption (kWh)', env_data.get('energy_consumption', 8500), '< 10000', '✓ Within Limit')
            ]
            
            for i, (param, value, target, status) in enumerate(parameters, start=1):
                row_cells = table.rows[i].cells
                row_cells[0].text = param
                row_cells[1].text = str(value)
                row_cells[2].text = target
                row_cells[3].text = status
                
                # Color the status cell green
                row_cells[3].paragraphs[0].runs[0].font.color.rgb = RGBColor(39, 174, 96)
            
            doc.add_paragraph()
            
            # Footer
            footer = doc.add_paragraph()
            footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
            footer.add_run(f"Generated by AI Environmental Management System • ISO 14001:2015 Compliant • {datetime.now().strftime('%Y-%m-%d')}")
            
            doc.save(filepath)
            print(f"✅ Word document generated successfully: {filepath}")
            
        except ImportError:
            print("⚠️ python-docx not installed, using simple text file")
            with open(filepath, 'w') as f:
                f.write("ISO 14001 Environmental Management System Report\n")
                f.write("="*50 + "\n\n")
                f.write(f"Company: {data.get('company_name', 'Environmental Solutions Inc.')}\n")
                f.write(f"Report Period: {data.get('report_period', 'Q1 2024')}\n")
                f.write(f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                f.write(f"Status: {data.get('compliance_status', 'COMPLIANT')}\n\n")
                f.write("Environmental Performance:\n")
                f.write("-"*30 + "\n")
                env_data = data.get('environmental_performance', {})
                f.write(f"Carbon Emissions: {env_data.get('carbon_emissions', 850)} tCO₂e (< 1000) ✓\n")
                f.write(f"Water Usage: {env_data.get('water_usage', 3200)} m³ (< 5000) ✓\n")
                f.write(f"Waste Generated: {env_data.get('waste_generated', 1500)} kg (< 2000) ✓\n")
                f.write(f"Energy Consumption: {env_data.get('energy_consumption', 8500)} kWh (< 10000) ✓\n")
    
