# Filter favicon requests from logs (optional)
import logging

class FaviconFilter(logging.Filter):
    def filter(self, record):
        message = record.getMessage()
        return not ('/favicon.ico' in message or '/robots.txt' in message)

logging.getLogger('werkzeug').addFilter(FaviconFilter())

