def generate_impact_assessment_fallback(data):
    """Generate impact assessment when AI service is unavailable"""
    project_type = data.get('project_type', 'general')
    location = data.get('location', 'unknown')
    
    # Base impact categories
    impact_categories = [
        'Air Quality',
        'Water Resources',
        'Biodiversity',
        'Noise Pollution',
        'Soil Contamination',
        'Visual Impact',
        'Traffic Impact',
        'Community Impact'
    ]
    
    # Generate impact scores based on project type
    if project_type == 'industrial':
        impact_scores = {
            'Air Quality': 75,
            'Water Resources': 65,
            'Biodiversity': 60,
            'Noise Pollution': 80,
            'Soil Contamination': 70,
            'Visual Impact': 55,
            'Traffic Impact': 70,
            'Community Impact': 65
        }
    elif project_type == 'infrastructure':
        impact_scores = {
            'Air Quality': 60,
            'Water Resources': 55,
            'Biodiversity': 70,
            'Noise Pollution': 75,
            'Soil Contamination': 50,
            'Visual Impact': 65,
            'Traffic Impact': 85,
            'Community Impact': 70
        }
    elif project_type == 'commercial':
        impact_scores = {
            'Air Quality': 45,
            'Water Resources': 40,
            'Biodiversity': 35,
            'Noise Pollution': 55,
            'Soil Contamination': 40,
            'Visual Impact': 50,
            'Traffic Impact': 60,
            'Community Impact': 55
        }
    else:
        impact_scores = {cat: 50 for cat in impact_categories}
    
    # Determine overall impact level
    avg_impact = sum(impact_scores.values()) / len(impact_scores)
    if avg_impact >= 70:
        overall_impact = 'High'
    elif avg_impact >= 45:
        overall_impact = 'Moderate'
    else:
        overall_impact = 'Low'
    
    # Generate mitigation measures
    mitigation_measures = [
        {
            'impact': cat,
            'measure': f'Implement {cat.lower()} control measures',
            'effectiveness': f'{min(100, 100 - impact_scores[cat] + 30)}%'
        }
        for cat in impact_categories[:4]  # Top 4 impacts
    ]
    
    return {
        'overall_impact': overall_impact,
        'impact_score': round(avg_impact, 1),
        'impact_categories': [
            {
                'category': cat,
                'score': score,
                'significance': 'High' if score >= 70 else 'Medium' if score >= 45 else 'Low'
            }
            for cat, score in impact_scores.items()
        ],
        'mitigation_measures': mitigation_measures,
        'recommendations': [
            'Conduct detailed environmental study',
            'Engage with local stakeholders',
            'Develop environmental management plan',
            'Implement monitoring program'
        ],
        'confidence_score': 0.75,
        'method_used': 'fallback_rule_based'
    }


def generate_compliance_prediction_fallback(data):
    """Generate compliance prediction when AI service is unavailable"""
    current_data = data.get('current_metrics', {})
    regulatory_standards = data.get('regulatory_standards', ['ISO 14001', 'EPA', 'Local'])
    
    # Compliance metrics
    compliance_metrics = {
        'air_quality_compliance': current_data.get('air_quality', 85),
        'water_quality_compliance': current_data.get('water_quality', 88),
        'waste_management_compliance': current_data.get('waste_management', 82),
        'emissions_compliance': current_data.get('emissions', 90)
    }
    
    # Calculate overall compliance
    overall_compliance = sum(compliance_metrics.values()) / len(compliance_metrics)
    
    # Predict future compliance (simple trend)
    predicted_compliance = {
        '30_days': min(100, overall_compliance + 2),
        '90_days': min(100, overall_compliance + 5),
        '1_year': min(100, overall_compliance + 8)
    }
    
    # Identify risk areas
    risk_areas = []
    for metric, value in compliance_metrics.items():
        if value < 75:
            risk_areas.append({
                'area': metric.replace('_', ' ').title(),
                'current_score': value,
                'risk_level': 'High' if value < 60 else 'Medium',
                'recommended_action': f'Immediate action needed for {metric}'
            })
    
    # Generate compliance timeline
    timeline = [
        {
            'date': (datetime.utcnow() + timedelta(days=30)).strftime('%Y-%m-%d'),
            'predicted_compliance': predicted_compliance['30_days'],
            'required_actions': ['Monthly reporting', 'Parameter checks']
        },
        {
            'date': (datetime.utcnow() + timedelta(days=90)).strftime('%Y-%m-%d'),
            'predicted_compliance': predicted_compliance['90_days'],
            'required_actions': ['Quarterly audit', 'Corrective actions review']
        },
        {
            'date': (datetime.utcnow() + timedelta(days=365)).strftime('%Y-%m-%d'),
            'predicted_compliance': predicted_compliance['1_year'],
            'required_actions': ['Annual certification', 'Management review']
        }
    ]
    
    return {
        'current_compliance_score': round(overall_compliance, 1),
        'compliance_status': 'Compliant' if overall_compliance >= 75 else 'At Risk' if overall_compliance >= 60 else 'Non-Compliant',
        'predicted_compliance': predicted_compliance,
        'risk_areas': risk_areas,
        'compliance_timeline': timeline,
        'recommendations': [
            'Strengthen monitoring frequency',
            'Document all compliance activities',
            'Train staff on regulatory requirements',
            'Conduct internal audits'
        ],
        'confidence_score': 0.80,
        'regulatory_standards_applicable': regulatory_standards,
        'method_used': 'fallback_statistical'
    }

