# Helper functions for optimization
def generate_optimization_suggestions(satellite_result):
    """Generate optimization suggestions based on satellite analysis"""
    suggestions = []
    
    # Energy optimization
    urban_analysis = satellite_result.get('urban_analysis', {})
    if urban_analysis.get('heat_island_risk') == 'high':
        suggestions.append('Install green roofs to reduce heat island effect')
    
    # Water optimization
    water_analysis = satellite_result.get('water_analysis', {})
    if water_analysis.get('water_coverage', 0) < 10:
        suggestions.append('Implement rainwater harvesting systems')
    
    # Vegetation optimization
    veg_analysis = satellite_result.get('vegetation_analysis', {})
    if veg_analysis.get('health') in ['poor', 'very poor']:
        suggestions.append('Enhance green spaces with drought-resistant plants')
    
    # Default suggestions if none generated
    if not suggestions:
        suggestions = [
            'Optimize building energy management systems',
            'Implement smart water metering',
            'Increase renewable energy adoption',
            'Enhance waste segregation practices'
        ]
    
    return suggestions[:5]  # Return top 5 suggestions


def calculate_potential_savings(satellite_result):
    """Calculate potential resource savings"""
    # Base savings estimates
    savings = {
        'energy': '10-15%',
        'water': '8-12%',
        'waste': '15-20%',
        'cost': '$25,000 - $50,000 annually'
    }
    
    # Adjust based on satellite data
    veg_health = satellite_result.get('vegetation_analysis', {}).get('health_index', 0.5)
    if veg_health > 0.8:
        savings['energy'] = '15-20%'  # Better vegetation means better cooling
    
    urban_density = satellite_result.get('urban_analysis', {}).get('urban_coverage', 50)
    if urban_density > 70:
        savings['cost'] = '$75,000 - $100,000 annually'  # Higher savings in dense areas
    
    return savings


