class AdvancedConstructionDatabase:
    def __init__(self, db_path='construction_safety_advanced.db'):
        self.db_path = db_path
        self._initialize_database()
    
    def _initialize_database(self):
        """Initialize advanced database schema"""
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()
        
        # Incidents table with advanced fields
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS incidents (
                id TEXT PRIMARY KEY,
                type TEXT,
                severity TEXT,
                location TEXT,
                description TEXT,
                workers_involved INTEGER,
                status TEXT,
                reported_at TEXT,
                resolved_at TEXT,
                ai_analysis TEXT,
                risk_score REAL,
                corrective_actions TEXT,
                investigation_status TEXT,
                cost_impact REAL,
                downtime_hours REAL
            )
        ''')
        
        # Risk assessments table
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS risk_assessments (
                id TEXT PRIMARY KEY,
                site_id TEXT,
                assessment_data TEXT,
                risk_score REAL,
                risk_level TEXT,
                mitigation_plan TEXT,
                created_at TEXT,
                ai_analysis TEXT,
                monitoring_requirements TEXT
            )
        ''')
        
        # Safety metrics table
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS safety_metrics (
                id TEXT PRIMARY KEY,
                metric_date TEXT,
                safety_compliance REAL,
                training_completion REAL,
                incident_rate REAL,
                equipment_uptime REAL,
                risk_index REAL,
                ai_insights TEXT
            )
        ''')
        
        conn.commit()
        conn.close()
        logger.info("Advanced database initialized")
    
    def save_incident(self, incident_data):
        """Save incident with AI analysis"""
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()
        
        incident_id = f"INC-{datetime.now().strftime('%Y%m%d-%H%M%S')}"
        
        cursor.execute('''
            INSERT INTO incidents 
            (id, type, severity, location, description, workers_involved, status, reported_at, ai_analysis)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            incident_id,
            incident_data.get('type'),
            incident_data.get('severity'),
            incident_data.get('location'),
            incident_data.get('description'),
            incident_data.get('workers_involved', 0),
            'reported',
            datetime.now().isoformat(),
            json.dumps(incident_data.get('ai_analysis', {}))
        ))
        
        conn.commit()
        conn.close()
        return incident_id
    
    def get_incidents(self, filters=None):
        """Get incidents with optional filtering"""
        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()
        
        query = "SELECT * FROM incidents WHERE 1=1"
        params = []
        
        if filters:
            if 'status' in filters:
                query += " AND status = ?"
                params.append(filters['status'])
            if 'severity' in filters:
                query += " AND severity = ?"
                params.append(filters['severity'])
            if 'date_from' in filters:
                query += " AND reported_at >= ?"
                params.append(filters['date_from'])
            if 'date_to' in filters:
                query += " AND reported_at <= ?"
                params.append(filters['date_to'])
        
        cursor.execute(query, params)
        columns = [description[0] for description in cursor.description]
        incidents = [dict(zip(columns, row)) for row in cursor.fetchall()]
        
        conn.close()
        return incidents

