@jwt_required  # ✅ Added JWT protection
def run_advanced_site_analysis():
    """Comprehensive AI site safety analysis"""
    start_time = datetime.now()  # ADD THIS LINE - Capture start time at the beginning
    
    try:
        # Extract user info for logging
        print(f"🏗️ Site analysis requested by: {request.user.email}")
        print(f"🔧 User type: {request.user_type}, Plan: {request.effective_plan}")
        
        # Enhanced request validation
        if not request.data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400
            
        # Handle both JSON and form data for image uploads
        content_type = request.content_type or ''
        
        if 'multipart/form-data' in content_type:
            # Handle file upload with site data
            site_data_json = request.form.get('siteData', '{}')
            try:
                site_data = json.loads(site_data_json)
            except json.JSONDecodeError:
                return jsonify({'success': False, 'error': 'Invalid siteData JSON'}), 400
                
            # Handle uploaded image file
            if 'image' in request.files:
                image_file = request.files['image']
                if image_file and image_file.filename:
                    try:
                        # Convert image to base64 for AI service
                        image_bytes = image_file.read()
                        site_data['site_image'] = base64.b64encode(image_bytes).decode('utf-8')
                        print(f"📸 Image uploaded: {image_file.filename}, size: {len(image_bytes)} bytes")
                    except Exception as e:
                        print(f"❌ Image processing error: {e}")
                        return jsonify({'success': False, 'error': f'Image processing failed: {str(e)}'}), 400
        else:
            # Standard JSON request
            data = request.get_json()
            if not data:
                return jsonify({'success': False, 'error': 'Invalid JSON data'}), 400
                
            site_data = data.get('siteData', {})
            if not site_data:
                return jsonify({'success': False, 'error': 'No siteData provided'}), 400

        # Add user context to site data
        site_data['analysis_requested_by'] = {
            'user_id': request.user_id,
            'email': request.user_email,
            'user_type': request.user_type,
            'effective_plan': request.effective_plan,
            'is_system_team': request.is_system_team
        }
        
        print(f"🚀 Starting AI site analysis for site: {site_data.get('siteId', 'unknown')}")
        print(f"👤 Requested by: {request.user.email}")
        
        # Initialize analysis results with safe defaults
        risk_analysis = {'risk_level': 'unknown', 'confidence': 0.0}
        hazard_analysis = {'hazards_detected': [], 'confidence_scores': {'overall_confidence': 0.0}}
        compliance_analysis = {}
        environmental_analysis = {}
        
        # Track analysis components status
        analysis_components = {
            'risk_analysis': False,
            'hazard_analysis': False,
            'compliance_analysis': False,
            'environmental_analysis': False
        }
        
        # Multi-dimensional analysis with error handling for each component
        try:
            risk_analysis = ai_service.predict_advanced_risk(site_data)
            analysis_components['risk_analysis'] = True
            print("✅ Risk analysis completed successfully")
        except Exception as e:
            print(f"❌ Risk analysis error: {e}")
            risk_analysis = {
                'risk_level': 'unknown', 
                'confidence': 0.0,
                'error': str(e)
            }

        # Handle image analysis with enhanced validation
        site_image = site_data.get('site_image', '')
        if site_image:
            try:
                # Validate image data before processing
                if isinstance(site_image, str) and site_image.startswith('data:image'):
                    # Extract base64 from data URL if needed
                    site_image = site_image.split(',')[1] if ',' in site_image else site_image
                
                hazard_analysis = ai_service.detect_hazards_from_image(site_image)
                
                # Ensure confidence_scores exists with proper structure
                if 'confidence_scores' not in hazard_analysis:
                    hazard_analysis['confidence_scores'] = {'overall_confidence': 0.0}
                elif not isinstance(hazard_analysis['confidence_scores'], dict):
                    hazard_analysis['confidence_scores'] = {'overall_confidence': 0.0}
                    
                analysis_components['hazard_analysis'] = True
                print(f"✅ Hazard analysis completed: {len(hazard_analysis.get('hazards_detected', []))} hazards detected")
                
            except Exception as e:
                print(f"❌ Image analysis error: {e}")
                hazard_analysis = {
                    'hazards_detected': [],
                    'confidence_scores': {'overall_confidence': 0.0},
                    'error': str(e)
                }
        else:
            print("⚠️ No site image provided for analysis")
            hazard_analysis = {
                'hazards_detected': [],
                'confidence_scores': {'overall_confidence': 0.0},
                'warning': 'No image provided for hazard analysis'
            }
        
        # Compliance analysis
        try:
            compliance_analysis = analyze_advanced_compliance(site_data)
            analysis_components['compliance_analysis'] = True
            print("✅ Compliance analysis completed")
        except Exception as e:
            print(f"❌ Compliance analysis error: {e}")
            compliance_analysis = {'error': str(e)}
        
        # Environmental analysis
        try:
            environmental_analysis = analyze_environmental_factors(site_data)
            analysis_components['environmental_analysis'] = True
            print("✅ Environmental analysis completed")
        except Exception as e:
            print(f"❌ Environmental analysis error: {e}")
            environmental_analysis = {'error': str(e)}
        
        # Safe confidence calculation with fallbacks
        risk_confidence = risk_analysis.get('confidence', 0.0)
        hazard_confidence = hazard_analysis.get('confidence_scores', {}).get('overall_confidence', 0.0)
        
        # Calculate weighted average confidence
        confidences = []
        if risk_confidence > 0:
            confidences.append(risk_confidence)
        if hazard_confidence > 0:
            confidences.append(hazard_confidence)
        
        avg_confidence = sum(confidences) / len(confidences) if confidences else 0.0
        ai_confidence = min(0.95, max(0.1, avg_confidence))  # Ensure between 0.1 and 0.95
        
        # Determine analysis status
        analysis_status = get_analysis_status(analysis_components, risk_analysis, hazard_analysis)
        
        # Generate comprehensive report with enhanced fallbacks
        analysis_report = {
            'siteId': site_data.get('siteId', 'unknown'),
            'overallRisk': risk_analysis.get('risk_level', 'unknown'),
            'safetyScore': calculate_advanced_safety_score(risk_analysis, hazard_analysis, compliance_analysis),
            'riskDistribution': analyze_risk_distribution(site_data),
            'hazardsDetected': hazard_analysis.get('hazards_detected', []),
            'complianceStatus': compliance_analysis,
            'environmentalFactors': environmental_analysis,
            'recommendations': generate_advanced_recommendations(risk_analysis, hazard_analysis, compliance_analysis),
            'predictiveAlerts': generate_advanced_alerts(risk_analysis, site_data),
            'aiConfidence': ai_confidence,
            'analysisDate': datetime.now().isoformat(),
            'nextReview': (datetime.now() + timedelta(days=14)).isoformat(),
            'monitoringPlan': generate_site_monitoring_plan(risk_analysis.get('risk_level', 'unknown')),
            'analysisStatus': analysis_status,
            'componentsExecuted': analysis_components,
            'analysisVersion': '2.1.0',
            'processingTime': f"{(datetime.now() - start_time).total_seconds():.2f}s",
            'userContext': {  # Include user context in report
                'analyzed_for_user_id': request.user_id,
                'analyzed_for_email': request.user_email,
                'user_type': request.user_type,
                'plan_limits': request.plan_limits if hasattr(request, 'plan_limits') else {},
                'is_system_team': request.is_system_team
            }
        }
        
        print(f"✅ AI Site Analysis completed successfully for {analysis_report['siteId']}")
        print(f"   - Overall Risk: {analysis_report['overallRisk']}")
        print(f"   - Safety Score: {analysis_report['safetyScore']}")
        print(f"   - AI Confidence: {analysis_report['aiConfidence']:.2f}")
        print(f"   - Status: {analysis_report['analysisStatus']}")
        print(f"   - Processing Time: {analysis_report['processingTime']}")
        print(f"   - User: {request.user.email}")
        
        return jsonify({'success': True, 'data': analysis_report})
        
    except Exception as e:
        print(f"❌ Site analysis error: {e}")
        print(f"   - User: {request.user.email if hasattr(request, 'user') else 'Unknown'}")
        return jsonify({
            'success': False, 
            'error': 'Internal server error during analysis',
            'details': str(e) if os.getenv('FLASK_DEBUG') else 'Enable debug mode for details',
            'user_info': {
                'user_id': request.user_id if hasattr(request, 'user_id') else None,
                'email': request.user_email if hasattr(request, 'user_email') else None
            }
        }), 500


def get_analysis_status(analysis_components, risk_analysis, hazard_analysis):
    """Determine the overall status of the analysis"""
    # Count successful components
    successful_components = sum(analysis_components.values())
    total_components = len(analysis_components)
    
    # Check for critical errors
    has_critical_errors = any([
        'error' in risk_analysis,
        'error' in hazard_analysis,
        risk_analysis.get('risk_level') == 'unknown'
    ])
    
    # Determine status based on success rate and critical errors
    if has_critical_errors:
        return 'partial'
    elif successful_components == total_components:
        return 'complete'
    elif successful_components >= total_components * 0.7:  # At least 70% successful
        return 'mostly_complete'
    elif successful_components >= total_components * 0.5:  # At least 50% successful
        return 'partial'
    else:
        return 'degraded'

# Enhanced helper functions with better error handling
def calculate_advanced_safety_score(risk_analysis, hazard_analysis, compliance_analysis):
    """Calculate advanced safety score with robust error handling"""
    try:
        # Risk component (40%)
        risk_score = (1 - risk_analysis.get('risk_score', 0.5)) * 100
        
        # Hazard component (30%)
        hazard_count = len(hazard_analysis.get('hazards_detected', []))
        hazard_score = max(0, 100 - (hazard_count * 5))
        
        # Compliance component (30%)
        compliance_scores = []
        if isinstance(compliance_analysis, dict):
            for key, value in compliance_analysis.items():
                if isinstance(value, dict) and 'score' in value:
                    compliance_scores.append(value['score'])
        
        compliance_score = np.mean(compliance_scores) if compliance_scores else 85
        
        # Weighted average
        final_score = (risk_score * 0.4 + hazard_score * 0.3 + compliance_score * 0.3)
        return round(max(0, min(100, final_score)), 1)
        
    except Exception as e:
        logger.error(f"Safety score calculation error: {e}")
        return 50.0  # Fallback score

def analyze_risk_distribution(site_data):
    """Analyze risk distribution across site areas with fallbacks"""
    try:
        # Simple risk distribution based on site data
        high_risk_factors = []
        if site_data.get('work_at_height', 0) > 0.6:
            high_risk_factors.append('elevated_work_zones')
        if site_data.get('heavy_equipment', 0) > 0.5:
            high_risk_factors.append('equipment_operation_areas')
        if site_data.get('electrical_work', 0) > 0.4:
            high_risk_factors.append('electrical_work_areas')
            
        return {
            'high_risk_areas': high_risk_factors,
            'medium_risk_areas': ['material_storage', 'access_routes'],
            'low_risk_areas': ['administration_areas', 'break_rooms'],
            'risk_concentration': 'high' if len(high_risk_factors) > 2 else 'moderate',
            'hot_spots': len(high_risk_factors)
        }
    except Exception as e:
        logger.error(f"Risk distribution analysis error: {e}")
        return {
            'high_risk_areas': [],
            'medium_risk_areas': [],
            'low_risk_areas': [],
            'risk_concentration': 'unknown',
            'hot_spots': 0
        }

def generate_advanced_recommendations(risk_analysis, hazard_analysis, compliance_analysis):
    """Generate advanced safety recommendations with fallbacks"""
    recommendations = []
    
    try:
        # Risk-based recommendations
        risk_level = risk_analysis.get('risk_level', 'unknown')
        if risk_level in ['Very High', 'High']:
            recommendations.append({
                'priority': 'critical',
                'category': 'risk_mitigation',
                'action': 'Implement immediate risk reduction measures and increase supervision',
                'impact': '40-60% risk reduction',
                'timeline': '48 hours',
                'resources_required': ['additional_supervisors', 'safety_equipment'],
                'success_metrics': ['risk_score_reduction', 'incident_rate_decrease']
            })
        
        # Hazard-based recommendations
        hazards_detected = hazard_analysis.get('hazards_detected', [])
        if len(hazards_detected) > 0:
            recommendations.append({
                'priority': 'high',
                'category': 'hazard_control',
                'action': 'Address detected hazards and implement control measures',
                'impact': f'Address {len(hazards_detected)} identified hazards',
                'timeline': '1 week',
                'resources_required': ['safety_engineers', 'inspection_equipment'],
                'success_metrics': ['hazard_elimination', 'safety_improvement']
            })
        
        # Compliance-based recommendations
        if isinstance(compliance_analysis, dict):
            for standard, data in compliance_analysis.items():
                if isinstance(data, dict) and data.get('score', 100) < 85:
                    recommendations.append({
                        'priority': 'medium',
                        'category': 'compliance',
                        'action': f'Improve {standard.upper()} compliance',
                        'impact': f'Increase compliance score to >85%',
                        'timeline': '2 weeks',
                        'resources_required': ['compliance_specialist', 'training_materials'],
                        'success_metrics': ['compliance_score', 'audit_results']
                    })
        
        # Default recommendation if none generated
        if not recommendations:
            recommendations.append({
                'priority': 'medium',
                'category': 'general_safety',
                'action': 'Continue current safety protocols and conduct regular inspections',
                'impact': 'Maintain current safety standards',
                'timeline': 'ongoing',
                'resources_required': ['standard_safety_equipment'],
                'success_metrics': ['safety_score_maintenance']
            })
            
    except Exception as e:
        logger.error(f"Recommendations generation error: {e}")
        recommendations.append({
            'priority': 'medium',
            'category': 'system_recovery',
            'action': 'System experienced an error. Please try the analysis again.',
            'impact': 'Error recovery',
            'timeline': 'immediate',
            'resources_required': ['technical_support'],
            'success_metrics': ['system_stability']
        })
    
    return recommendations
