 # ✅ Additional admin protection
def get_system_logs():
    """Get system logs with automatic table creation - ADMIN ONLY"""
    try:
        # Check admin/system team access
        if not request.is_system_team and request.user_type not in ['admin', 'super_admin', 'platform_owner']:
            print(f"⚠️ Unauthorized access attempt to system logs by: {request.user.email}")
            return jsonify({
                'success': False,
                'error': 'Admin access required',
                'code': 'ADMIN_ACCESS_REQUIRED'
            }), 403
        
        print(f"📋 Admin logs requested by: {request.user.email}")
        print(f"👑 User type: {request.user_type}, System Team: {request.is_system_team}")
        
        # Ensure system_logs table exists
        create_system_logs_table()
        
        # Get pagination parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        level = request.args.get('level')
        module = request.args.get('module')
        
        # Calculate offset
        offset = (page - 1) * per_page
        
        # Build query
        query = "SELECT * FROM system_logs WHERE 1=1"
        params = {}
        
        if level:
            query += " AND level = :level"
            params['level'] = level
            
        if module:
            query += " AND module = :module" 
            params['module'] = module
        
        query += " ORDER BY timestamp DESC LIMIT :limit OFFSET :offset"
        params['limit'] = per_page
        params['offset'] = offset
        
        # Execute query
        with db.engine.connect() as connection:
            result = connection.execute(text(query), params)
            logs = [dict(row._mapping) for row in result]
        
        # Get total count
        count_query = "SELECT COUNT(*) as total FROM system_logs WHERE 1=1"
        count_params = {}
        
        if level:
            count_query += " AND level = :level"
            count_params['level'] = level
            
        if module:
            count_query += " AND module = :module"
            count_params['module'] = module
        
        with db.engine.connect() as connection:
            count_result = connection.execute(text(count_query), count_params)
            total = count_result.scalar()
        
        # Format timestamps
        for log in logs:
            if 'timestamp' in log and log['timestamp']:
                log['timestamp'] = log['timestamp'].isoformat()
        
        # Log this admin access
        log_activity(
            level='info',
            module='admin',
            action='view_raw_logs',
            description=f'Admin {request.user.email} viewed system logs',
            user_id=request.user_id,
            ip_address=request.remote_addr,
            additional_data={
                'page': page,
                'per_page': per_page,
                'filters': {'level': level, 'module': module}
            }
        )
        
        print(f"✅ Admin logs retrieved by: {request.user.email}")
        print(f"   - Total logs: {total}")
        print(f"   - Page: {page}/{((total + per_page - 1) // per_page)}")
        
        return jsonify({
            'success': True,
            'data': {
                'logs': logs,
                'pagination': {
                    'page': page,
                    'per_page': per_page,
                    'total': total,
                    'pages': (total + per_page - 1) // per_page
                },
                'access_info': {
                    'accessed_by': request.user_email,
                    'user_role': request.user_type,
                    'is_system_team': request.is_system_team,
                    'timestamp': datetime.now().isoformat()
                }
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching system logs for {request.user.email}: {e}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch system logs',
            'details': str(e)
        }), 500

