@app.route('/api/construction/documents/<int:document_id>', methods=['DELETE'])
@jwt_required  # ✅ Added JWT protection
def delete_document(document_id):
    """Delete document and its file"""
    try:
        print(f"🗑️ Document delete requested by: {request.user.email}")
        print(f"📄 Document ID: {document_id}")
        
        document = ConstructionDocument.query.get(document_id)
        
        if not document:
            return jsonify({'success': False, 'error': 'Document not found'}), 404
        
        # Check permissions - user can only delete their own docs unless admin
        if document.user_id != request.user_id and not request.is_system_team and request.user_type not in ['admin', 'super_admin']:
            return jsonify({
                'success': False,
                'error': 'You do not have permission to delete this document',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # Log before deletion
        log_data = {
            'document_id': document.id,
            'title': document.title,
            'file_name': document.file_name,
            'deleted_by': request.user_email
        }
        
        # Delete physical file
        if document.file_path and os.path.exists(document.file_path):
            try:
                os.remove(document.file_path)
                print(f"🗑️ Physical file deleted: {document.file_path}")
            except Exception as e:
                logger.warning(f"Could not delete physical file: {e}")
                log_data['file_deletion_error'] = str(e)
        
        # Delete database record
        db.session.delete(document)
        db.session.commit()
        
        # Log the deletion
        log_activity(
            level='warning',
            module='documents',
            action='delete_document',
            description=f'User {request.user.email} deleted document: {document.title}',
            user_id=request.user_id,
            additional_data=log_data
        )
        
        print(f"✅ Document deleted by {request.user.email}")
        
        return jsonify({
            'success': True,
            'data': {
                'message': 'Document deleted successfully',
                'deleted_by': request.user_email,
                'deleted_at': datetime.now().isoformat()
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error deleting document for {request.user.email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to delete document'}), 500

