@app.route('/api/construction/documents/search', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
def search_documents():
    """Search documents with advanced filtering"""
    try:
        print(f"🔍 Document search requested by: {request.user.email}")
        
        data = request.get_json()
        query_text = data.get('query', '')
        filters = data.get('filters', {})
        
        # Build search query - filter by user unless admin
        if request.is_system_team or request.user_type in ['admin', 'super_admin', 'platform_owner']:
            search_query = ConstructionDocument.query
        else:
            search_query = ConstructionDocument.query.filter_by(user_id=request.user_id)
        
        if query_text:
            search_query = search_query.filter(
                db.or_(
                    ConstructionDocument.title.ilike(f'%{query_text}%'),
                    ConstructionDocument.description.ilike(f'%{query_text}%'),
                    ConstructionDocument.original_file_name.ilike(f'%{query_text}%')
                )
            )
            
        # Apply filters
        for key, value in filters.items():
            if hasattr(ConstructionDocument, key) and value:
                if isinstance(value, list):
                    search_query = search_query.filter(getattr(ConstructionDocument, key).in_(value))
                else:
                    search_query = search_query.filter(getattr(ConstructionDocument, key) == value)
                
        documents = search_query.order_by(ConstructionDocument.created_at.desc()).all()
        
        # Log the search
        log_activity(
            level='info',
            module='documents',
            action='search_documents',
            description=f'User {request.user.email} searched documents: "{query_text}"',
            user_id=request.user_id,
            additional_data={
                'query': query_text,
                'filters': filters,
                'result_count': len(documents)
            }
        )
        
        print(f"✅ Search completed for {request.user.email}: {len(documents)} results")
        
        return jsonify({
            'success': True,
            'data': {
                'documents': [doc.to_dict() for doc in documents],
                'total': len(documents),
                'search_metadata': {
                    'query': query_text,
                    'searched_by': request.user_email,
                    'search_timestamp': datetime.now().isoformat()
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error searching documents for {request.user.email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to search documents'}), 500

