@app.route('/api/construction/performance/targets', methods=['PUT'])
@jwt_required  # ✅ Added JWT protection
def update_spi_targets():
    """Update SPI targets with actual database operations"""
    try:
        print(f"🎯 SPI targets update requested by: {request.user_email}")
        print(f"👤 User type: {request.user_type}, Plan: {request.effective_plan}")
        
        # Check if user has permission to update targets
        if not request.is_system_team and request.user_type not in ['admin', 'super_admin', 'safetypro']:
            return jsonify({
                'success': False,
                'error': 'Permission denied. Only safety administrators can update targets',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        data = request.get_json()
        targets = data.get('targets', [])
        
        if not targets:
            return jsonify({'success': False, 'error': 'No targets provided'}), 400
        
        updated_count = 0
        created_count = 0
        updated_targets = []
        
        for target_data in targets:
            if target_data.get('id'):
                # Update existing target
                target = SafetyPerformanceTarget.query.get(target_data['id'])
                if target:
                    # Log the changes
                    changes = []
                    if 'current_value' in target_data and target.current_value != target_data['current_value']:
                        changes.append(f"current_value: {target.current_value} → {target_data['current_value']}")
                    if 'target_value' in target_data and target.target_value != target_data['target_value']:
                        changes.append(f"target_value: {target.target_value} → {target_data['target_value']}")
                    if 'is_active' in target_data and target.is_active != target_data['is_active']:
                        changes.append(f"is_active: {target.is_active} → {target_data['is_active']}")
                    
                    target.current_value = target_data.get('current_value', target.current_value)
                    target.target_value = target_data.get('target_value', target.target_value)
                    target.is_active = target_data.get('is_active', target.is_active)
                    target.updated_at = datetime.utcnow()
                    target.updated_by = request.user_id
                    updated_count += 1
                    
                    if changes:
                        updated_targets.append({
                            'id': target.id,
                            'name': target.name,
                            'changes': changes
                        })
            else:
                # Create new target
                target = SafetyPerformanceTarget(
                    name=target_data['name'],
                    description=target_data.get('description', ''),
                    category=target_data.get('category', 'leading'),
                    current_value=target_data.get('current_value'),
                    target_value=target_data['target_value'],
                    unit=target_data.get('unit', ''),
                    period=target_data.get('period', 'monthly'),
                    site_id=target_data.get('site_id'),
                    department=target_data.get('department', ''),
                    is_active=target_data.get('is_active', True),
                    created_by=request.user_id,
                    created_at=datetime.utcnow()
                )
                db.session.add(target)
                created_count += 1
                updated_targets.append({
                    'id': 'new',
                    'name': target.name,
                    'action': 'created'
                })
        
        db.session.commit()
        
        # Log this action
        log_activity(
            level='info',
            module='performance',
            action='update_spi_targets',
            description=f'User {request.user_email} updated {updated_count} and created {created_count} SPI targets',
            user_id=request.user_id,
            additional_data={
                'updated_count': updated_count,
                'created_count': created_count,
                'targets_processed': updated_targets,
                'total_targets': len(targets)
            }
        )
        
        print(f"✅ SPI targets updated by {request.user_email}: {updated_count} updated, {created_count} created")
        
        return jsonify({
            'success': True,
            'data': {
                'message': 'SPI targets updated successfully',
                'updated_targets': updated_count,
                'created_targets': created_count,
                'total_processed': len(targets),
                'updated_by': request.user_email,
                'updated_at': datetime.utcnow().isoformat(),
                'user_context': {
                    'user_id': request.user_id,
                    'user_email': request.user_email,
                    'user_type': request.user_type,
                    'is_system_team': request.is_system_team
                }
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating SPI targets for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to update SPI targets'}), 500


