@app.route('/api/construction/safety/objectives', methods=['PUT'])
@jwt_required  # ✅ Added JWT protection
def update_construction_safety_objectives():
    """Update safety objectives with actual database operations"""
    try:
        print(f"🎯 Safety objectives update requested by: {request.user_email}")
        
        data = request.get_json()
        
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400
        
        # Check if user has permission to update safety objectives
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            return jsonify({
                'success': False,
                'error': 'Permission denied. Only safety administrators can update safety objectives',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        objectives = data.get('objectives', [])
        
        if not objectives:
            return jsonify({
                'success': False,
                'error': 'No objectives provided in request'
            }), 400
        
        # Deactivate old objectives
        old_objectives = ConstructionDocument.query.filter_by(
            document_type='safety_objectives',
            status='active'
        ).all()
        
        for old_obj in old_objectives:
            old_obj.status = 'inactive'
            old_obj.updated_at = datetime.utcnow()
            old_obj.updated_by = request.user_id
        
        # Create new objectives
        created_count = 0
        created_objectives = []
        
        for idx, obj_data in enumerate(objectives):
            if obj_data.get('title'):
                objective = ConstructionDocument(
                    user_id=request.user_id,
                    title=obj_data.get('title'),
                    description=obj_data.get('description', ''),
                    document_type='safety_objectives',
                    status='active',
                    created_at=datetime.utcnow(),
                    updated_at=datetime.utcnow(),
                    metadata={
                        'priority': obj_data.get('priority', 'medium'),
                        'target_date': obj_data.get('target_date'),
                        'department': obj_data.get('department', 'general'),
                        'kpi_metric': obj_data.get('kpi_metric'),
                        'target_value': obj_data.get('target_value')
                    }
                )
                db.session.add(objective)
                created_count += 1
                created_objectives.append({
                    'title': objective.title,
                    'priority': obj_data.get('priority', 'medium'),
                    'department': obj_data.get('department', 'general')
                })
        
        db.session.commit()
        
        # Log this update
        log_activity(
            level='info',
            module='safety',
            action='update_safety_objectives',
            description=f'User {request.user_email} updated {created_count} safety objectives',
            user_id=request.user_id,
            additional_data={
                'old_objectives_deactivated': len(old_objectives),
                'new_objectives_created': created_count,
                'objectives_created': created_objectives
            }
        )
        
        print(f"✅ Safety objectives updated by {request.user_email}: {created_count} new objectives created")
        
        return jsonify({
            'success': True,
            'data': {
                'message': 'Safety objectives updated successfully',
                'updated_count': created_count,
                'objectives': objectives,
                'old_objectives_deactivated': len(old_objectives),
                'updated_by': request.user_email,
                'updated_at': datetime.utcnow().isoformat()
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating safety objectives for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to update safety objectives'}), 500

@app.route('/api/construction/risk/matrix', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
def get_construction_risk_matrix():
    """Get actual risk matrix from database"""
    try:
        print(f"⚡ Risk matrix requested by: {request.user_email}")
        
        # Check plan restrictions for risk matrix
        if request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Risk matrix visualization requires Pro or Enterprise plan',
                'code': 'PLAN_UPGRADE_REQUIRED',
                'upgrade_url': '/billing/upgrade'
            }), 403
        
        # Get active risk assessments or incidents for risk matrix
        incidents = Incident.query.filter(
            Incident.status.in_(['reported', 'investigating'])
        ).all()
        
        # Also get audit findings for risk assessment
        findings = AuditFinding.query.filter_by(resolved=False).all()
        
        risk_data = []
        
        # Process incidents for risk matrix
        for incident in incidents:
            risk_level = calculate_risk_level(incident.severity, 'incident')
            risk_data.append({
                'risk': incident.title,
                'type': 'incident',
                'probability': get_probability_from_severity(incident.severity),
                'impact': get_impact_from_severity(incident.severity),
                'level': risk_level,
                'source_id': incident.id,
                'source_type': 'incident',
                'severity': incident.severity,
                'date': incident.created_at.isoformat() if incident.created_at else None,
                'department_id': incident.department_id
            })
        
        # Process audit findings for risk matrix
        for finding in findings:
            risk_level = calculate_risk_level(finding.severity, 'finding')
            risk_data.append({
                'risk': finding.title,
                'type': 'audit_finding',
                'probability': get_probability_from_severity(finding.severity),
                'impact': get_impact_from_severity(finding.severity),
                'level': risk_level,
                'source_id': finding.id,
                'source_type': 'audit_finding',
                'severity': finding.severity,
                'date': finding.created_at.isoformat() if finding.created_at else None,
                'department_id': finding.department_id
            })
        
        # Filter by user department if not system team
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            user_department_id = getattr(request.user, 'department_id', None)
            if user_department_id:
                risk_data = [r for r in risk_data if r.get('department_id') == user_department_id]
        
        # Categorize risks
        critical_risks = [r for r in risk_data if r['level'] == 'Critical']
        high_risks = [r for r in risk_data if r['level'] == 'High']
        medium_risks = [r for r in risk_data if r['level'] == 'Medium']
        low_risks = [r for r in risk_data if r['level'] == 'Low']
        
        risk_matrix = {
            'categories': ['Critical', 'High', 'Medium', 'Low'],
            'data': risk_data,
            'summary': {
                'critical_count': len(critical_risks),
                'high_count': len(high_risks),
                'medium_count': len(medium_risks),
                'low_count': len(low_risks),
                'total_risks': len(risk_data),
                'by_type': {
                    'incident': len([r for r in risk_data if r['type'] == 'incident']),
                    'audit_finding': len([r for r in risk_data if r['type'] == 'audit_finding'])
                }
            }
        }
        
        # Add AI-powered insights for Pro/Enterprise plans
        ai_insights = None
        if request.effective_plan == 'enterprise' and risk_data:
            try:
                ai_insights = generate_risk_insights(risk_data)
            except Exception as e:
                print(f"⚠️ AI insights generation failed: {e}")
        
        # Log this access
        log_activity(
            level='info',
            module='risk',
            action='view_risk_matrix',
            description=f'User {request.user_email} viewed risk matrix',
            user_id=request.user_id,
            additional_data={
                'total_risks': len(risk_data),
                'critical_risks': len(critical_risks),
                'user_plan': request.effective_plan
            }
        )
        
        print(f"✅ Risk matrix retrieved for {request.user_email}: {len(risk_data)} risks")
        
        return jsonify({
            'success': True,
            'data': {
                'risk_matrix': risk_matrix,
                'ai_insights': ai_insights,
                'access_info': {
                    'viewed_by': request.user_email,
                    'user_type': request.user_type,
                    'is_system_team': request.is_system_team,
                    'effective_plan': request.effective_plan,
                    'ai_enhanced': request.effective_plan == 'enterprise',
                    'filtered_for_department': not request.is_system_team and request.user_type not in ['admin', 'safetypro']
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching risk matrix for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch risk matrix'}), 500

# Helper methods for risk calculation
def _calculate_risk_level(self, severity, source_type):
    """Calculate risk level based on severity and source type"""
    severity_map = {
        'critical': 'Critical',
        'high': 'High', 
        'medium': 'Medium',
        'low': 'Low'
    }
    
    if not severity:
        return 'Medium'
    
    severity_lower = severity.lower()
    return severity_map.get(severity_lower, 'Medium')


def _get_probability_from_severity(self, severity):
    """Get probability based on severity"""
    probability_map = {
        'critical': 'Very High',
        'high': 'High',
        'medium': 'Medium', 
        'low': 'Low'
    }
    
    if not severity:
        return 'Medium'
    
    severity_lower = severity.lower()
    return probability_map.get(severity_lower, 'Medium')

def _get_impact_from_severity(self, severity):
    """Get impact based on severity"""
    impact_map = {
        'critical': 'Catastrophic',
        'high': 'Major',
        'medium': 'Moderate',
        'low': 'Minor'
    }
    
    if not severity:
        return 'Moderate'
    
    severity_lower = severity.lower()
    return impact_map.get(severity_lower, 'Moderate')

@app.route('/api/construction/incidents', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
def get_construction_incidents():
    """Get construction incidents with filtering"""
    try:
        print(f"🚨 Incidents requested by: {request.user_email}")
        
        status = request.args.get('status', 'all')
        severity = request.args.get('severity')
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 10, type=int)
        site_id = request.args.get('site_id')
        department_id = request.args.get('department_id')
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        
        query = Incident.query
        
        # Check user access - non-system users may have restricted access
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            user_site_id = getattr(request.user, 'primary_site_id', None)
            user_department_id = getattr(request.user, 'department_id', None)
            
            if user_site_id:
                query = query.filter_by(site_id=user_site_id)
            if user_department_id:
                query = query.filter_by(department_id=user_department_id)
        
        # Apply filters
        if status != 'all':
            query = query.filter_by(status=status)
        if severity:
            query = query.filter_by(severity=severity)
        if site_id:
            query = query.filter_by(site_id=site_id)
        if department_id:
            query = query.filter_by(department_id=department_id)
        
        # Date filters
        if start_date:
            try:
                start_date_obj = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
                query = query.filter(Incident.created_at >= start_date_obj)
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid start date format',
                    'code': 'INVALID_DATE_FORMAT'
                }), 400
        
        if end_date:
            try:
                end_date_obj = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
                query = query.filter(Incident.created_at <= end_date_obj)
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid end date format',
                    'code': 'INVALID_DATE_FORMAT'
                }), 400
        
        # Check plan restrictions for incident history
        if request.effective_plan == 'free':
            # Free users get limited data (last 30 days only)
            thirty_days_ago = datetime.utcnow() - timedelta(days=30)
            query = query.filter(Incident.created_at >= thirty_days_ago)
        
        incidents = query.order_by(Incident.created_at.desc()).paginate(
            page=page, per_page=per_page, error_out=False
        )
        
        # Calculate statistics for the current filter
        total_incidents = query.count()
        critical_count = query.filter_by(severity='critical').count()
        open_count = query.filter(Incident.status.in_(['reported', 'investigating'])).count()
        
        # Log this access
        log_activity(
            level='info',
            module='incidents',
            action='view_incidents',
            description=f'User {request.user_email} viewed incidents',
            user_id=request.user_id,
            additional_data={
                'page': page,
                'per_page': per_page,
                'filters': {
                    'status': status,
                    'severity': severity,
                    'site_id': site_id,
                    'department_id': department_id
                },
                'incident_count': len(incidents.items),
                'user_plan': request.effective_plan
            }
        )
        
        print(f"✅ Incidents retrieved for {request.user_email}: {len(incidents.items)} incidents")
        
        return jsonify({
            'success': True,
            'data': {
                'incidents': [{
                    'id': incident.id,
                    'incident_number': incident.incident_number,
                    'title': incident.title,
                    'description': incident.description,
                    'type': incident.incident_type,
                    'severity': incident.severity,
                    'status': incident.status,
                    'location': incident.location,
                    'reported_by': incident.reported_by,
                    'date_occurred': incident.date_occurred.isoformat() if incident.date_occurred else None,
                    'created_at': incident.created_at.isoformat(),
                    'site_id': incident.site_id,
                    'department_id': incident.department_id,
                    'investigation_status': incident.investigation_status,
                    'is_my_report': incident.user_id == request.user_id
                } for incident in incidents.items],
                'total': incidents.total,
                'pages': incidents.pages,
                'current_page': page,
                'summary': {
                    'total': total_incidents,
                    'critical': critical_count,
                    'open': open_count,
                    'resolved': total_incidents - open_count
                },
                'access_info': {
                    'viewed_by': request.user_email,
                    'user_type': request.user_type,
                    'effective_plan': request.effective_plan,
                    'scope': 'restricted' if not request.is_system_team else 'full',
                    'data_limited': request.effective_plan == 'free'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching construction incidents for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch construction incidents'}), 500

@app.route('/api/construction/incidents/<int:incident_id>', methods=['PUT'])
@jwt_required  # ✅ Added JWT protection
def update_construction_incident(incident_id):
    """Update incident"""
    try:
        print(f"✏️ Incident update requested by: {request.user_email}")
        print(f"🚨 Incident ID: {incident_id}")
        
        data = request.get_json()
        incident = Incident.query.get(incident_id)
        
        if not incident:
            return jsonify({'success': False, 'error': 'Incident not found'}), 404
        
        # Check if user has permission to update this incident
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            # Regular users can only update incidents they reported
            if incident.user_id != request.user_id:
                return jsonify({
                    'success': False,
                    'error': 'You can only update incidents you reported',
                    'code': 'PERMISSION_DENIED'
                }), 403
        
        # Track changes for logging
        changes = []
        allowed_fields = ['title', 'description', 'severity', 'status', 'location', 'investigation_details', 'corrective_actions']
        
        for field in allowed_fields:
            if field in data:
                old_value = getattr(incident, field, None)
                new_value = data[field]
                
                # Special handling for certain fields
                if field == 'severity' and new_value not in ['critical', 'high', 'medium', 'low']:
                    return jsonify({
                        'success': False,
                        'error': 'Invalid severity value',
                        'code': 'INVALID_SEVERITY'
                    }), 400
                
                if field == 'status' and new_value not in ['reported', 'investigating', 'resolved', 'closed']:
                    return jsonify({
                        'success': False,
                        'error': 'Invalid status value',
                        'code': 'INVALID_STATUS'
                    }), 400
                
                setattr(incident, field, new_value)
                
                # Log changes
                if str(old_value) != str(new_value):
                    changes.append({
                        'field': field,
                        'old': old_value,
                        'new': new_value
                    })
        
        incident.updated_at = datetime.utcnow()
        incident.updated_by = request.user_id
        
        # If incident is resolved, set resolution date
        if incident.status == 'resolved' and not incident.resolution_date:
            incident.resolution_date = datetime.utcnow()
            incident.resolved_by = request.user_id
            changes.append({
                'field': 'resolution',
                'action': 'marked_as_resolved',
                'resolved_by': request.user_email,
                'resolved_at': incident.resolution_date.isoformat()
            })
        
        db.session.commit()
        
        # Log this update
        log_activity(
            level='info',
            module='incidents',
            action='update_incident',
            description=f'User {request.user_email} updated incident #{incident_id}',
            user_id=request.user_id,
            resource_id=incident_id,
            resource_type='incident',
            additional_data={
                'incident_id': incident_id,
                'incident_title': incident.title,
                'severity': incident.severity,
                'status': incident.status,
                'changes': changes,
                'updated_by': request.user_email
            }
        )
        
        print(f"✅ Incident updated by {request.user_email}: {incident.title}")
        
        return jsonify({
            'success': True,
            'data': {
                'incident': {
                    'id': incident.id,
                    'title': incident.title,
                    'status': incident.status,
                    'updated_at': incident.updated_at.isoformat(),
                    'updated_by': request.user_email,
                    'changes_made': [c['field'] for c in changes],
                    'severity': incident.severity
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error updating incident for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to update incident'}), 500

@app.route('/api/construction/incidents/<int:incident_id>/status', methods=['PUT'])
@jwt_required  # ✅ Added JWT protection
def update_construction_incident_status(incident_id):
    """Update incident status"""
    try:
        print(f"🔄 Incident status update requested by: {request.user_email}")
        print(f"🚨 Incident ID: {incident_id}")
        
        data = request.get_json()
        incident = Incident.query.get(incident_id)
        
        if not incident:
            return jsonify({'success': False, 'error': 'Incident not found'}), 404
        
        # Check if user has permission to update incident status
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            # Regular users can only update status of incidents they reported
            if incident.user_id != request.user_id:
                return jsonify({
                    'success': False,
                    'error': 'You can only update status of incidents you reported',
                    'code': 'PERMISSION_DENIED'
                }), 403
        
        new_status = data.get('status')
        if new_status not in ['reported', 'investigating', 'resolved', 'closed']:
            return jsonify({
                'success': False,
                'error': 'Invalid status',
                'code': 'INVALID_STATUS'
            }), 400
        
        # Check if status transition is valid
        valid_transitions = {
            'reported': ['investigating', 'resolved'],
            'investigating': ['resolved', 'closed'],
            'resolved': ['closed'],
            'closed': []  # Once closed, cannot change
        }
        
        if new_status not in valid_transitions.get(incident.status, []):
            return jsonify({
                'success': False,
                'error': f'Cannot change status from {incident.status} to {new_status}',
                'code': 'INVALID_STATUS_TRANSITION'
            }), 400
        
        old_status = incident.status
        incident.status = new_status
        incident.updated_at = datetime.utcnow()
        incident.updated_by = request.user_id
        
        # If resolving incident, set resolution date
        if new_status == 'resolved' and not incident.resolution_date:
            incident.resolution_date = datetime.utcnow()
            incident.resolved_by = request.user_id
        
        # If closing incident, ensure it's resolved first
        if new_status == 'closed' and incident.status != 'resolved':
            return jsonify({
                'success': False,
                'error': 'Incident must be resolved before closing',
                'code': 'INVALID_CLOSE'
            }), 400
        
        db.session.commit()
        
        # Log this status change
        log_activity(
            level='info',
            module='incidents',
            action='update_incident_status',
            description=f'User {request.user_email} changed incident #{incident_id} status from {old_status} to {new_status}',
            user_id=request.user_id,
            resource_id=incident_id,
            resource_type='incident',
            additional_data={
                'incident_id': incident_id,
                'incident_title': incident.title,
                'old_status': old_status,
                'new_status': new_status,
                'updated_by': request.user_email,
                'resolution_date': incident.resolution_date.isoformat() if incident.resolution_date else None
            }
        )
        
        print(f"✅ Incident status updated by {request.user_email}: {old_status} → {new_status}")
        
        return jsonify({
            'success': True,
            'data': {
                'incident': {
                    'id': incident.id,
                    'status': incident.status,
                    'resolution_date': incident.resolution_date.isoformat() if incident.resolution_date else None,
                    'updated_at': incident.updated_at.isoformat(),
                    'updated_by': request.user_email,
                    'status_transition': f'{old_status} → {new_status}'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error updating incident status for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to update incident status'}), 500

@app.route('/api/construction/incidents/<int:incident_id>/analysis', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
def conduct_root_cause_analysis(incident_id):
    """Conduct root cause analysis"""
    try:
        print(f"🔍 Root cause analysis requested by: {request.user_email}")
        print(f"🚨 Incident ID: {incident_id}")
        
        # Check plan restrictions for AI analysis
        if request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Root cause analysis requires Pro or Enterprise plan',
                'code': 'PLAN_UPGRADE_REQUIRED',
                'upgrade_url': '/billing/upgrade'
            }), 403
        
        incident = Incident.query.get(incident_id)
        
        if not incident:
            return jsonify({'success': False, 'error': 'Incident not found'}), 404
        
        # Check if user has permission to analyze this incident
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            # Regular users can only analyze incidents they reported
            if incident.user_id != request.user_id:
                return jsonify({
                    'success': False,
                    'error': 'You can only analyze incidents you reported',
                    'code': 'PERMISSION_DENIED'
                }), 403
        
        # Use AI service for analysis if available
        try:
            # This would call your actual AI service
            analysis_result = {
                'root_causes': ['Inadequate training', 'Poor supervision', 'Equipment failure'],
                'contributing_factors': ['Time pressure', 'Weather conditions', 'Workload'],
                'prevention_recommendations': [
                    'Enhance safety training programs',
                    'Improve equipment maintenance schedules',
                    'Implement additional supervision'
                ],
                'risk_level': 'high',
                'confidence_score': 0.85,
                'analysis_method': 'ai_enhanced' if request.effective_plan == 'enterprise' else 'standard',
                'analyzed_by_ai': True
            }
        except Exception as ai_error:
            print(f"⚠️ AI analysis failed, using fallback: {ai_error}")
            # Fallback analysis
            analysis_result = {
                'root_causes': ['Systematic analysis not available'],
                'contributing_factors': ['Manual analysis required'],
                'prevention_recommendations': ['Review incident details manually'],
                'risk_level': 'medium',
                'confidence_score': 0.5,
                'analysis_method': 'manual_fallback',
                'analyzed_by_ai': False
            }
        
        # Update incident with analysis results
        incident.root_cause_analysis = json.dumps(analysis_result)
        incident.analysis_date = datetime.utcnow()
        incident.analyzed_by = request.user_id
        incident.updated_at = datetime.utcnow()
        db.session.commit()
        
        # Create action items from recommendations (for Enterprise plan)
        if request.effective_plan == 'enterprise' and analysis_result.get('analyzed_by_ai'):
            try:
                for recommendation in analysis_result.get('prevention_recommendations', [])[:3]:  # Limit to top 3
                    action_plan = AuditActionPlan(
                        finding_id=None,
                        incident_id=incident_id,
                        action=recommendation,
                        responsible_person=request.user_email,
                        due_date=datetime.utcnow() + timedelta(days=30),
                        status='pending',
                        user_id=request.user_id,
                        source='ai_analysis'
                    )
                    db.session.add(action_plan)
                db.session.commit()
            except Exception as action_error:
                print(f"⚠️ Failed to create action items: {action_error}")
                db.session.rollback()
        
        # Log this analysis
        log_activity(
            level='info',
            module='incidents',
            action='conduct_root_cause_analysis',
            description=f'User {request.user_email} conducted root cause analysis for incident #{incident_id}',
            user_id=request.user_id,
            resource_id=incident_id,
            resource_type='incident',
            additional_data={
                'incident_id': incident_id,
                'incident_title': incident.title,
                'analysis_method': analysis_result.get('analysis_method'),
                'confidence_score': analysis_result.get('confidence_score'),
                'root_causes_count': len(analysis_result.get('root_causes', [])),
                'recommendations_count': len(analysis_result.get('prevention_recommendations', [])),
                'user_plan': request.effective_plan,
                'ai_enhanced': analysis_result.get('analyzed_by_ai', False)
            }
        )
        
        print(f"✅ Root cause analysis completed by {request.user_email}: {len(analysis_result.get('root_causes', []))} root causes identified")
        
        return jsonify({
            'success': True,
            'data': {
                'analysis': analysis_result,
                'incident_id': incident_id,
                'incident_title': incident.title,
                'analyzed_by': request.user_email,
                'analysis_date': incident.analysis_date.isoformat(),
                'ai_enhanced': analysis_result.get('analyzed_by_ai', False),
                'plan_features': {
                    'ai_analysis': request.effective_plan == 'enterprise',
                    'auto_action_items': request.effective_plan == 'enterprise',
                    'confidence_score': analysis_result.get('confidence_score', 0)
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error conducting root cause analysis for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to conduct root cause analysis'}), 500

@app.route('/api/construction/incidents/statistics', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
def get_construction_incident_statistics():
    """Get incident statistics"""
    try:
        print(f"📈 Incident statistics requested by: {request.user_email}")
        
        # Check plan restrictions for statistics
        if request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Advanced incident statistics require Pro or Enterprise plan',
                'code': 'PLAN_UPGRADE_REQUIRED',
                'upgrade_url': '/billing/upgrade'
            }), 403
        
        # Check user access
        user_site_id = getattr(request.user, 'primary_site_id', None)
        user_department_id = getattr(request.user, 'department_id', None)
        
        # Build base queries
        base_query = Incident.query
        base_severity_query = db.session.query(Incident.severity, db.func.count(Incident.id))
        base_type_query = db.session.query(Incident.incident_type, db.func.count(Incident.id))
        
        # Apply user filters
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            if user_site_id:
                base_query = base_query.filter_by(site_id=user_site_id)
                base_severity_query = base_severity_query.filter(Incident.site_id == user_site_id)
                base_type_query = base_type_query.filter(Incident.site_id == user_site_id)
            if user_department_id:
                base_query = base_query.filter_by(department_id=user_department_id)
                base_severity_query = base_severity_query.filter(Incident.department_id == user_department_id)
                base_type_query = base_type_query.filter(Incident.department_id == user_department_id)
        
        # Calculate statistics for different time periods
        current_date = datetime.utcnow()
        month_start = current_date.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        year_start = current_date.replace(month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
        
        # Total incidents
        total_incidents = base_query.count()
        
        # Recent incidents
        incidents_this_month = base_query.filter(
            Incident.created_at >= month_start
        ).count()
        
        incidents_this_year = base_query.filter(
            Incident.created_at >= year_start
        ).count()
        
        # By severity
        by_severity = base_severity_query.group_by(Incident.severity).all()
        
        # By type
        by_type = base_type_query.group_by(Incident.incident_type).all()
        
        # Trend analysis
        last_month_start = month_start - timedelta(days=30)
        incidents_last_month = base_query.filter(
            Incident.created_at >= last_month_start,
            Incident.created_at < month_start
        ).count()
        
        # Calculate trend
        if incidents_last_month == 0:
            trend_percentage = 100 if incidents_this_month > 0 else 0
        else:
            trend_percentage = ((incidents_this_month - incidents_last_month) / incidents_last_month) * 100
        
        if incidents_this_month < incidents_last_month:
            trend = 'improving'
            trend_direction = 'down'
        elif incidents_this_month > incidents_last_month:
            trend = 'worsening'
            trend_direction = 'up'
        else:
            trend = 'stable'
            trend_direction = 'same'
        
        # Calculate additional statistics for Enterprise plan
        additional_stats = None
        if request.effective_plan == 'enterprise':
            try:
                # Average resolution time
                resolved_incidents = base_query.filter_by(status='resolved').all()
                if resolved_incidents:
                    resolution_times = []
                    for incident in resolved_incidents:
                        if incident.resolution_date and incident.created_at:
                            resolution_time = (incident.resolution_date - incident.created_at).days
                            resolution_times.append(resolution_time)
                    
                    if resolution_times:
                        avg_resolution_days = sum(resolution_times) / len(resolution_times)
                        additional_stats = {
                            'average_resolution_days': round(avg_resolution_days, 1),
                            'fastest_resolution': min(resolution_times) if resolution_times else 0,
                            'slowest_resolution': max(resolution_times) if resolution_times else 0
                        }
            except Exception as stats_error:
                print(f"⚠️ Additional statistics calculation failed: {stats_error}")
        
        # Log this access
        log_activity(
            level='info',
            module='incidents',
            action='view_incident_statistics',
            description=f'User {request.user_email} viewed incident statistics',
            user_id=request.user_id,
            additional_data={
                'total_incidents': total_incidents,
                'incidents_this_month': incidents_this_month,
                'trend': trend,
                'user_plan': request.effective_plan,
                'scope': 'restricted' if not request.is_system_team else 'full'
            }
        )
        
        print(f"✅ Incident statistics retrieved for {request.user_email}: {total_incidents} total incidents")
        
        return jsonify({
            'success': True,
            'data': {
                'total_incidents': total_incidents,
                'incidents_this_month': incidents_this_month,
                'incidents_this_year': incidents_this_year,
                'by_severity': dict(by_severity),
                'by_type': dict(by_type),
                'trend': trend,
                'trend_direction': trend_direction,
                'trend_percentage': round(abs(trend_percentage), 1),
                'period': 'monthly',
                'calculated_at': current_date.isoformat(),
                'additional_stats': additional_stats,
                'scope': {
                    'site_id': user_site_id if not request.is_system_team else 'all',
                    'department_id': user_department_id if not request.is_system_team else 'all',
                    'user_access': 'restricted' if not request.is_system_team else 'full'
                },
                'access_info': {
                    'viewed_by': request.user_email,
                    'user_type': request.user_type,
                    'effective_plan': request.effective_plan,
                    'advanced_analytics': request.effective_plan == 'enterprise'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching incident statistics for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch incident statistics'}), 500

@app.route('/api/construction/assurance/audits', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
def submit_safety_audit():
    """Submit safety audit"""
    try:
        print(f"📋 Safety audit submission requested by: {request.user_email}")
        
        data = request.get_json()
        
        # Check if user has permission to submit audits
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            return jsonify({
                'success': False,
                'error': 'Permission denied. Only safety administrators can submit audits',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # Check plan restrictions for audit submissions
        if request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Safety audit submissions require Pro or Enterprise plan',
                'code': 'PLAN_UPGRADE_REQUIRED',
                'upgrade_url': '/billing/upgrade'
            }), 403
        
        # Validate required fields
        required_fields = ['title', 'area', 'findings']
        missing_fields = [field for field in required_fields if field not in data]
        if missing_fields:
            return jsonify({
                'success': False,
                'error': f'Missing required fields: {", ".join(missing_fields)}',
                'code': 'MISSING_FIELDS'
            }), 400
        
        # Validate score if provided
        score = data.get('score')
        if score is not None:
            try:
                score = float(score)
                if score < 0 or score > 100:
                    return jsonify({
                        'success': False,
                        'error': 'Score must be between 0 and 100',
                        'code': 'INVALID_SCORE'
                    }), 400
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Score must be a number',
                    'code': 'INVALID_SCORE_FORMAT'
                }), 400
        
        # Create audit record
        audit = SafetyInspection(
            user_id=request.user_id,
            inspection_number=f"AUD-{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}",
            title=data.get('title', 'Safety Audit'),
            type='audit',
            area=data.get('area', 'General'),
            department=data.get('department', 'Construction'),
            conducted_by=request.user_id,
            inspection_date=datetime.utcnow(),
            findings=data.get('findings', ''),
            status='completed',
            score=score,
            recommendations=data.get('recommendations', ''),
            site_id=data.get('site_id'),
            created_at=datetime.utcnow(),
            updated_at=datetime.utcnow(),
            metadata={
                'audit_type': data.get('audit_type', 'routine'),
                'duration_hours': data.get('duration_hours'),
                'team_size': data.get('team_size'),
                'standards_referenced': data.get('standards_referenced', []),
                'compliance_rate': data.get('compliance_rate')
            }
        )
        
        db.session.add(audit)
        db.session.commit()
        
        # Create findings from audit if provided
        audit_findings = data.get('audit_findings', [])
        findings_created = 0
        
        for finding_data in audit_findings:
            if finding_data.get('title'):
                finding = AuditFinding(
                    audit_id=audit.id,
                    title=finding_data.get('title'),
                    description=finding_data.get('description', ''),
                    severity=finding_data.get('severity', 'medium'),
                    standard_reference=finding_data.get('standard_reference', ''),
                    user_id=request.user_id,
                    status='open'
                )
                db.session.add(finding)
                findings_created += 1
        
        if audit_findings:
            db.session.commit()
        
        # Log this audit submission
        log_activity(
            level='info',
            module='assurance',
            action='submit_safety_audit',
            description=f'User {request.user_email} submitted safety audit #{audit.inspection_number}',
            user_id=request.user_id,
            resource_id=audit.id,
            resource_type='safety_audit',
            additional_data={
                'audit_id': audit.id,
                'inspection_number': audit.inspection_number,
                'title': audit.title,
                'area': audit.area,
                'score': audit.score,
                'findings_count': findings_created,
                'user_plan': request.effective_plan
            }
        )
        
        print(f"✅ Safety audit submitted by {request.user_email}: {audit.inspection_number}")
        
        return jsonify({
            'success': True,
            'data': {
                'audit_id': audit.id,
                'inspection_number': audit.inspection_number,
                'message': 'Safety audit submitted successfully',
                'findings_created': findings_created,
                'submitted_by': request.user_email,
                'submitted_at': datetime.utcnow().isoformat(),
                'audit_details': {
                    'title': audit.title,
                    'area': audit.area,
                    'score': audit.score,
                    'status': audit.status
                }
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error submitting safety audit for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to submit safety audit'}), 500


@app.route('/api/construction/assurance/findings/<int:finding_id>/action-plans', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
def create_construction_action_plan(finding_id):
    """Create action plan for audit finding"""
    try:
        print(f"📝 Action plan creation requested by: {request.user_email}")
        print(f"🔍 Finding ID: {finding_id}")
        
        data = request.get_json()
        
        finding = AuditFinding.query.get(finding_id)
        if not finding:
            return jsonify({'success': False, 'error': 'Audit finding not found'}), 404
        
        # Check if user has permission to create action plans
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            # Regular users can only create action plans for findings they created
            if finding.user_id != request.user_id:
                return jsonify({
                    'success': False,
                    'error': 'You can only create action plans for your own findings',
                    'code': 'PERMISSION_DENIED'
                }), 403
        
        # Validate required fields
        required_fields = ['action', 'responsible_person']
        missing_fields = [field for field in required_fields if field not in data]
        if missing_fields:
            return jsonify({
                'success': False,
                'error': f'Missing required fields: {", ".join(missing_fields)}',
                'code': 'MISSING_FIELDS'
            }), 400
        
        # Validate due date
        due_date = None
        if data.get('due_date'):
            try:
                due_date = datetime.fromisoformat(data['due_date'].replace('Z', '+00:00'))
                # Ensure due date is not in the past
                if due_date < datetime.utcnow():
                    return jsonify({
                        'success': False,
                        'error': 'Due date cannot be in the past',
                        'code': 'INVALID_DUE_DATE'
                    }), 400
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid due date format',
                    'code': 'INVALID_DATE_FORMAT'
                }), 400
        
        # Check for duplicate action plans
        existing_plan = AuditActionPlan.query.filter_by(
            finding_id=finding_id,
            action=data['action']
        ).first()
        
        if existing_plan:
            return jsonify({
                'success': False,
                'error': 'An action plan with this description already exists for this finding',
                'code': 'DUPLICATE_ACTION_PLAN'
            }), 400
        
        action_plan = AuditActionPlan(
            finding_id=finding_id,
            action=data.get('action'),
            responsible_person=data.get('responsible_person'),
            due_date=due_date,
            status=data.get('status', 'pending'),
            user_id=request.user_id,
            created_at=datetime.utcnow(),
            updated_at=datetime.utcnow()
        )
        
        db.session.add(action_plan)
        db.session.commit()
        
        # Update finding status if this is the first action plan
        if not finding.action_plans or len(finding.action_plans) == 1:
            finding.updated_at = datetime.utcnow()
            db.session.commit()
        
        # Log this action
        log_activity(
            level='info',
            module='assurance',
            action='create_action_plan',
            description=f'User {request.user_email} created action plan for finding #{finding_id}',
            user_id=request.user_id,
            resource_id=action_plan.id,
            resource_type='action_plan',
            additional_data={
                'finding_id': finding_id,
                'finding_title': finding.title,
                'action_plan_action': action_plan.action,
                'responsible_person': action_plan.responsible_person,
                'due_date': action_plan.due_date.isoformat() if action_plan.due_date else None,
                'status': action_plan.status
            }
        )
        
        print(f"✅ Action plan created by {request.user_email} for finding #{finding_id}")
        
        return jsonify({
            'success': True,
            'data': {
                'action_plan': {
                    'id': action_plan.id,
                    'finding_id': action_plan.finding_id,
                    'action': action_plan.action,
                    'responsible_person': action_plan.responsible_person,
                    'due_date': action_plan.due_date.isoformat() if action_plan.due_date else None,
                    'status': action_plan.status,
                    'created_at': action_plan.created_at.isoformat(),
                    'created_by': request.user_email,
                    'finding_title': finding.title
                },
                'message': 'Action plan created successfully',
                'created_by': request.user_email
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error creating action plan for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to create action plan'}), 500

@app.route('/api/construction/assurance/action-plans/<int:action_plan_id>', methods=['PUT'])
@jwt_required  # ✅ Added JWT protection
def update_construction_action_plan(action_plan_id):
    """Update action plan status"""
    try:
        print(f"✏️ Action plan update requested by: {request.user_email}")
        print(f"📋 Action Plan ID: {action_plan_id}")
        
        data = request.get_json()
        
        action_plan = AuditActionPlan.query.get(action_plan_id)
        if not action_plan:
            return jsonify({'success': False, 'error': 'Action plan not found'}), 404
        
        # Check if user has permission to update this action plan
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            # Regular users can only update action plans they created or are responsible for
            if action_plan.user_id != request.user_id and action_plan.responsible_person != request.user_email:
                return jsonify({
                    'success': False,
                    'error': 'You can only update action plans you created or are responsible for',
                    'code': 'PERMISSION_DENIED'
                }), 403
        
        # Track changes for logging
        changes = []
        
        # Update allowed fields
        if 'status' in data:
            old_status = action_plan.status
            action_plan.status = data['status']
            changes.append(f"status: {old_status} → {data['status']}")
        
        if 'action' in data:
            old_action = action_plan.action
            action_plan.action = data['action']
            if old_action != data['action']:
                changes.append(f"action updated")
        
        if 'responsible_person' in data:
            old_responsible = action_plan.responsible_person
            action_plan.responsible_person = data['responsible_person']
            if old_responsible != data['responsible_person']:
                changes.append(f"responsible_person: {old_responsible} → {data['responsible_person']}")
        
        if 'due_date' in data and data['due_date']:
            old_due_date = action_plan.due_date
            try:
                new_due_date = datetime.fromisoformat(data['due_date'].replace('Z', '+00:00'))
                action_plan.due_date = new_due_date
                changes.append(f"due_date: {old_due_date.isoformat() if old_due_date else 'None'} → {new_due_date.isoformat()}")
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid due date format',
                    'code': 'INVALID_DATE_FORMAT'
                }), 400
        
        action_plan.updated_at = datetime.utcnow()
        action_plan.updated_by = request.user_id
        db.session.commit()
        
        # If action plan is marked as completed, check if all action plans for the finding are completed
        if action_plan.status == 'completed':
            finding = action_plan.finding
            all_plans_completed = all(plan.status == 'completed' for plan in finding.action_plans)
            if all_plans_completed and not finding.resolved:
                finding.resolved = True
                finding.resolution_notes = f"All action plans completed by {request.user_email}"
                finding.updated_at = datetime.utcnow()
                db.session.commit()
        
        # Log this update
        log_activity(
            level='info',
            module='assurance',
            action='update_action_plan',
            description=f'User {request.user_email} updated action plan #{action_plan_id}',
            user_id=request.user_id,
            resource_id=action_plan_id,
            resource_type='action_plan',
            additional_data={
                'action_plan_id': action_plan_id,
                'finding_id': action_plan.finding_id,
                'finding_title': action_plan.finding.title if action_plan.finding else 'Unknown',
                'changes': changes,
                'new_status': action_plan.status,
                'updated_by': request.user_email
            }
        )
        
        print(f"✅ Action plan updated by {request.user_email}: {action_plan.action}")
        
        return jsonify({
            'success': True,
            'data': {
                'action_plan': {
                    'id': action_plan.id,
                    'status': action_plan.status,
                    'updated_at': action_plan.updated_at.isoformat(),
                    'updated_by': request.user_email,
                    'changes_made': changes,
                    'is_all_completed': action_plan.finding.resolved if action_plan.finding else False
                },
                'message': 'Action plan updated successfully'
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating action plan for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to update action plan'}), 500

@app.route('/api/construction/safety/status', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
def get_construction_safety_status():
    """Get overall safety status"""
    try:
        print(f"🛡️ Safety status requested by: {request.user_email}")
        
        # Check user access - non-system users may have restricted access
        user_site_id = getattr(request.user, 'primary_site_id', None)
        user_department_id = getattr(request.user, 'department_id', None)
        
        # Calculate safety metrics
        recent_incidents_query = Incident.query.filter(
            Incident.created_at >= datetime.utcnow() - timedelta(days=30)
        )
        
        active_risks_query = RiskAssessment.query.filter_by(status='active')
        
        # Apply user filters
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            if user_site_id:
                recent_incidents_query = recent_incidents_query.filter_by(site_id=user_site_id)
                active_risks_query = active_risks_query.filter_by(site_id=user_site_id)
            if user_department_id:
                recent_incidents_query = recent_incidents_query.filter_by(department_id=user_department_id)
                active_risks_query = active_risks_query.filter_by(department_id=user_department_id)
        
        recent_incidents = recent_incidents_query.count()
        active_risks = active_risks_query.count()
        
        # Calculate safety score (0-100)
        # Base score is 100, deduct points for incidents and risks
        safety_score = max(0, 100 - (recent_incidents * 5) - (active_risks * 2))
        
        # Determine status level
        if safety_score >= 90:
            status_level = 'excellent'
            status_color = 'green'
            status_message = 'Excellent safety performance'
        elif safety_score >= 80:
            status_level = 'good'
            status_color = 'blue'
            status_message = 'Good safety performance'
        elif safety_score >= 70:
            status_level = 'fair'
            status_color = 'yellow'
            status_message = 'Fair safety performance - monitor closely'
        else:
            status_level = 'poor'
            status_color = 'red'
            status_message = 'Poor safety performance - immediate action needed'
        
        # Get additional metrics for context
        total_incidents = Incident.query.count()
        resolved_incidents = Incident.query.filter_by(status='resolved').count()
        open_action_plans = AuditActionPlan.query.filter(
            AuditActionPlan.status.in_(['pending', 'in_progress'])
        ).count()
        
        # Log this access
        log_activity(
            level='info',
            module='safety',
            action='view_safety_status',
            description=f'User {request.user_email} viewed safety status',
            user_id=request.user_id,
            additional_data={
                'safety_score': safety_score,
                'status_level': status_level,
                'recent_incidents': recent_incidents,
                'active_risks': active_risks,
                'user_scope': 'restricted' if not request.is_system_team else 'full'
            }
        )
        
        print(f"✅ Safety status calculated for {request.user_email}: Score = {safety_score}, Level = {status_level}")
        
        return jsonify({
            'success': True,
            'data': {
                'safety_score': safety_score,
                'status': status_level,
                'status_color': status_color,
                'status_message': status_message,
                'recent_incidents': recent_incidents,
                'active_risks': active_risks,
                'total_incidents': total_incidents,
                'resolved_incidents': resolved_incidents,
                'open_action_plans': open_action_plans,
                'last_updated': datetime.utcnow().isoformat(),
                'metrics_calculated_for': {
                    'site_id': user_site_id if not request.is_system_team else 'all',
                    'department_id': user_department_id if not request.is_system_team else 'all',
                    'scope': 'user_restricted' if not request.is_system_team else 'full_system'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching safety status for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch safety status'}), 500

@app.route('/api/construction/risk/<int:risk_id>/mitigation', methods=['PUT'])
@jwt_required  # ✅ Added JWT protection
def update_construction_risk_mitigation(risk_id):
    """Update risk mitigation"""
    try:
        print(f"🛡️ Risk mitigation update requested by: {request.user_email}")
        print(f"⚠️ Risk ID: {risk_id}")
        
        data = request.get_json()
        risk = RiskAssessment.query.get(risk_id)
        
        if not risk:
            return jsonify({'success': False, 'error': 'Risk not found'}), 404
        
        # Check if user has permission to update this risk
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            # Regular users can only update risks they created
            if risk.user_id != request.user_id:
                return jsonify({
                    'success': False,
                    'error': 'You can only update risks you created',
                    'code': 'PERMISSION_DENIED'
                }), 403
        
        # Validate mitigation data
        if 'mitigation_plan' in data and len(data['mitigation_plan']) > 5000:
            return jsonify({
                'success': False,
                'error': 'Mitigation plan too long (max 5000 characters)',
                'code': 'VALIDATION_ERROR'
            }), 400
        
        if 'mitigation_status' in data and data['mitigation_status'] not in ['not_started', 'in_progress', 'completed', 'on_hold']:
            return jsonify({
                'success': False,
                'error': 'Invalid mitigation status',
                'code': 'INVALID_STATUS'
            }), 400
        
        # Track changes
        changes = []
        
        # Update mitigation details
        if 'mitigation_plan' in data:
            old_plan = risk.mitigation_plan
            risk.mitigation_plan = data['mitigation_plan']
            if old_plan != data['mitigation_plan']:
                changes.append("mitigation_plan updated")
        
        if 'mitigation_status' in data:
            old_status = risk.mitigation_status
            risk.mitigation_status = data['mitigation_status']
            if old_status != data['mitigation_status']:
                changes.append(f"mitigation_status: {old_status} → {data['mitigation_status']}")
        
        risk.updated_at = datetime.utcnow()
        risk.updated_by = request.user_id
        
        # If mitigation is completed, update risk status
        if risk.mitigation_status == 'completed':
            risk.status = 'mitigated'
            risk.mitigation_completion_date = datetime.utcnow()
            changes.append("risk status updated to 'mitigated'")
        
        db.session.commit()
        
        # Log this update
        log_activity(
            level='info',
            module='risk',
            action='update_risk_mitigation',
            description=f'User {request.user_email} updated mitigation for risk #{risk_id}',
            user_id=request.user_id,
            resource_id=risk_id,
            resource_type='risk_assessment',
            additional_data={
                'risk_id': risk_id,
                'risk_title': risk.title,
                'mitigation_status': risk.mitigation_status,
                'changes': changes,
                'updated_by': request.user_email
            }
        )
        
        print(f"✅ Risk mitigation updated by {request.user_email}: {risk.title}")
        
        return jsonify({
            'success': True,
            'data': {
                'risk': {
                    'id': risk.id,
                    'title': risk.title,
                    'mitigation_plan': risk.mitigation_plan,
                    'mitigation_status': risk.mitigation_status,
                    'status': risk.status,
                    'updated_at': risk.updated_at.isoformat(),
                    'updated_by': request.user_email,
                    'changes_made': changes
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error updating risk mitigation for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to update risk mitigation'}), 500

@app.route('/api/construction/risk/hazards', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
def get_construction_hazard_log():
    """Get hazard log"""
    try:
        print(f"⚠️ Hazard log requested by: {request.user_email}")
        
        params = request.args.to_dict()
        
        # Check plan restrictions for hazard log
        if request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Hazard log requires Pro or Enterprise plan',
                'code': 'PLAN_UPGRADE_REQUIRED',
                'upgrade_url': '/billing/upgrade'
            }), 403
        
        # Build query for incidents that are hazards
        query = Incident.query.filter(
            Incident.incident_type.in_(['hazard', 'unsafe_condition'])
        )
        
        # Check user access
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            user_site_id = getattr(request.user, 'primary_site_id', None)
            user_department_id = getattr(request.user, 'department_id', None)
            
            if user_site_id:
                query = query.filter_by(site_id=user_site_id)
            if user_department_id:
                query = query.filter_by(department_id=user_department_id)
        
        # Apply filters
        if 'status' in params:
            query = query.filter_by(status=params['status'])
        if 'severity' in params:
            query = query.filter_by(severity=params['severity'])
        if 'site_id' in params:
            query = query.filter_by(site_id=params['site_id'])
        if 'department_id' in params:
            query = query.filter_by(department_id=params['department_id'])
        
        # Apply date filters
        if 'start_date' in params:
            try:
                start_date = datetime.fromisoformat(params['start_date'].replace('Z', '+00:00'))
                query = query.filter(Incident.created_at >= start_date)
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid start date format',
                    'code': 'INVALID_DATE_FORMAT'
                }), 400
        
        if 'end_date' in params:
            try:
                end_date = datetime.fromisoformat(params['end_date'].replace('Z', '+00:00'))
                query = query.filter(Incident.created_at <= end_date)
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid end date format',
                    'code': 'INVALID_DATE_FORMAT'
                }), 400
        
        # Get pagination parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        
        hazards = query.order_by(Incident.created_at.desc()).paginate(
            page=page, per_page=per_page, error_out=False
        )
        
        # Log this access
        log_activity(
            level='info',
            module='risk',
            action='view_hazard_log',
            description=f'User {request.user_email} viewed hazard log',
            user_id=request.user_id,
            additional_data={
                'page': page,
                'per_page': per_page,
                'filters': params,
                'hazard_count': len(hazards.items),
                'user_plan': request.effective_plan
            }
        )
        
        print(f"✅ Hazard log retrieved for {request.user_email}: {len(hazards.items)} hazards")
        
        return jsonify({
            'success': True,
            'data': {
                'hazards': [{
                    'id': hazard.id,
                    'title': hazard.title,
                    'description': hazard.description,
                    'type': hazard.incident_type,
                    'severity': hazard.severity,
                    'status': hazard.status,
                    'location': hazard.location,
                    'created_at': hazard.created_at.isoformat(),
                    'created_by': hazard.user.email if hazard.user else 'Unknown',
                    'site_id': hazard.site_id,
                    'department_id': hazard.department_id
                } for hazard in hazards.items],
                'total': hazards.total,
                'pages': hazards.pages,
                'current_page': page,
                'summary': {
                    'critical': len([h for h in hazards.items if h.severity == 'critical']),
                    'high': len([h for h in hazards.items if h.severity == 'high']),
                    'medium': len([h for h in hazards.items if h.severity == 'medium']),
                    'low': len([h for h in hazards.items if h.severity == 'low']),
                    'open': len([h for h in hazards.items if h.status in ['reported', 'investigating']]),
                    'resolved': len([h for h in hazards.items if h.status == 'resolved'])
                },
                'access_info': {
                    'viewed_by': request.user_email,
                    'user_type': request.user_type,
                    'effective_plan': request.effective_plan,
                    'scope': 'restricted' if not request.is_system_team else 'full'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching hazard log for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch hazard log'}), 500

@app.route('/api/construction/performance/indicators', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
def get_construction_safety_performance_indicators():
    """Get safety performance indicators"""
    try:
        print(f"📊 Safety performance indicators requested by: {request.user_email}")
        
        # Check plan restrictions for advanced indicators
        if request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Advanced performance indicators require Pro or Enterprise plan',
                'code': 'PLAN_UPGRADE_REQUIRED',
                'upgrade_url': '/billing/upgrade'
            }), 403
        
        # Calculate current SPIs
        current_date = datetime.utcnow()
        month_start = current_date.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        
        # Check user access
        user_site_id = getattr(request.user, 'primary_site_id', None)
        user_department_id = getattr(request.user, 'department_id', None)
        
        # Calculate various safety metrics with user filters
        incidents_query = Incident.query.filter(
            Incident.created_at >= month_start
        )
        
        inspections_query = SafetyInspection.query.filter(
            SafetyInspection.inspection_date >= month_start
        )
        
        training_query = TrainingRecord.query.filter(
            TrainingRecord.completion_date >= month_start
        )
        
        # Apply user filters
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            if user_site_id:
                incidents_query = incidents_query.filter_by(site_id=user_site_id)
                inspections_query = inspections_query.filter_by(site_id=user_site_id)
                training_query = training_query.filter_by(site_id=user_site_id)
            
            if user_department_id:
                incidents_query = incidents_query.filter_by(department_id=user_department_id)
                inspections_query = inspections_query.filter_by(department_id=user_department_id)
                training_query = training_query.filter_by(department_id=user_department_id)
        
        incidents_this_month = incidents_query.count()
        inspections_this_month = inspections_query.count()
        training_completions = training_query.count()
        
        # Calculate additional metrics
        open_action_plans = AuditActionPlan.query.filter(
            AuditActionPlan.status.in_(['pending', 'in_progress'])
        ).count()
        
        resolved_incidents = Incident.query.filter(
            Incident.created_at >= month_start,
            Incident.status == 'resolved'
        ).count()
        
        # Calculate targets based on plan
        if request.effective_plan == 'enterprise':
            incident_target = 3
            inspection_target = 25
            training_target = 75
        else:  # Pro plan
            incident_target = 5
            inspection_target = 20
            training_target = 50
        
        spis = [
            {
                'id': 'incident_rate',
                'name': 'Incident Rate',
                'current': incidents_this_month,
                'target': incident_target,
                'trend': 'improving' if incidents_this_month <= incident_target else 'worsening',
                'unit': 'count',
                'description': 'Number of safety incidents this month',
                'performance': min(100, max(0, 100 - (incidents_this_month / incident_target * 100) + 100)),
                'weight': 0.4  # Weight in overall score
            },
            {
                'id': 'inspection_completion',
                'name': 'Inspection Completion',
                'current': inspections_this_month,
                'target': inspection_target,
                'trend': 'improving' if inspections_this_month >= inspection_target * 0.75 else 'stable',
                'unit': 'count',
                'description': 'Safety inspections completed this month',
                'performance': min(100, (inspections_this_month / inspection_target * 100)),
                'weight': 0.3
            },
            {
                'id': 'training_compliance',
                'name': 'Training Compliance',
                'current': training_completions,
                'target': training_target,
                'trend': 'improving' if training_completions >= training_target * 0.8 else 'needs_improvement',
                'unit': 'count',
                'description': 'Training sessions completed this month',
                'performance': min(100, (training_completions / training_target * 100)),
                'weight': 0.2
            },
            {
                'id': 'action_plan_completion',
                'name': 'Action Plan Completion',
                'current': open_action_plans,
                'target': 5,  # Target: max 5 open action plans
                'trend': 'improving' if open_action_plans <= 5 else 'worsening',
                'unit': 'count',
                'description': 'Open corrective action plans',
                'performance': min(100, max(0, 100 - (open_action_plans * 20))),
                'weight': 0.1
            }
        ]
        
        # Calculate overall SPI score
        overall_score = sum(spi['performance'] * spi['weight'] for spi in spis)
        
        # Determine overall trend
        improving_count = sum(1 for spi in spis if spi['trend'] == 'improving')
        worsening_count = sum(1 for spi in spis if spi['trend'] == 'worsening')
        
        if improving_count >= 3:
            overall_trend = 'improving'
        elif worsening_count >= 2:
            overall_trend = 'worsening'
        else:
            overall_trend = 'stable'
        
        # Log this access
        log_activity(
            level='info',
            module='performance',
            action='view_performance_indicators',
            description=f'User {request.user_email} viewed safety performance indicators',
            user_id=request.user_id,
            additional_data={
                'overall_score': overall_score,
                'indicators_count': len(spis),
                'user_plan': request.effective_plan,
                'scope': 'restricted' if not request.is_system_team else 'full'
            }
        )
        
        print(f"✅ Performance indicators retrieved for {request.user_email}: Overall score = {overall_score}")
        
        return jsonify({
            'success': True,
            'data': {
                'spis': spis,
                'overall_score': round(overall_score, 1),
                'overall_trend': overall_trend,
                'last_calculated': current_date.isoformat(),
                'period': 'monthly',
                'scope': {
                    'site_id': user_site_id if not request.is_system_team else 'all',
                    'department_id': user_department_id if not request.is_system_team else 'all',
                    'calculated_for': 'user_scope' if not request.is_system_team else 'all_sites'
                },
                'access_info': {
                    'viewed_by': request.user_email,
                    'user_type': request.user_type,
                    'effective_plan': request.effective_plan,
                    'ai_enhanced': request.effective_plan == 'enterprise'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching performance indicators for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch performance indicators'}), 500
