@app.route('/api/construction/equipment/maintenance/schedule', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
def get_maintenance_schedule():
    """Get maintenance schedule"""
    try:
        print(f"📅 Maintenance schedule requested by: {request.user_email}")
        
        # Check plan restrictions for maintenance schedule
        if request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Maintenance schedule requires Pro or Enterprise plan',
                'code': 'PLAN_UPGRADE_REQUIRED',
                'upgrade_url': '/billing/upgrade'
            }), 403
        
        # Check user access
        user_site_id = getattr(request.user, 'primary_site_id', None)
        
        # Build maintenance query
        maintenance_query = Equipment.query.filter(
            Equipment.next_maintenance <= datetime.utcnow() + timedelta(days=7)
        )
        
        # Apply user filters
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            if user_site_id:
                maintenance_query = maintenance_query.filter_by(site_id=user_site_id)
            else:
                # Users without site assignment get limited data
                maintenance_query = maintenance_query.limit(5)
        
        # Apply additional filters
        urgency_filter = request.args.get('urgency')
        if urgency_filter == 'high':
            maintenance_query = maintenance_query.filter(
                Equipment.next_maintenance <= datetime.utcnow()
            )
        elif urgency_filter == 'medium':
            maintenance_query = maintenance_query.filter(
                Equipment.next_maintenance > datetime.utcnow(),
                Equipment.next_maintenance <= datetime.utcnow() + timedelta(days=3)
            )
        elif urgency_filter == 'low':
            maintenance_query = maintenance_query.filter(
                Equipment.next_maintenance > datetime.utcnow() + timedelta(days=3),
                Equipment.next_maintenance <= datetime.utcnow() + timedelta(days=7)
            )
        
        # Get pagination parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        
        maintenance_due = maintenance_query.order_by(Equipment.next_maintenance).paginate(
            page=page, per_page=per_page, error_out=False
        )
        
        # Calculate statistics
        total_due = maintenance_query.count()
        overdue = maintenance_query.filter(Equipment.next_maintenance <= datetime.utcnow()).count()
        due_soon = maintenance_query.filter(
            Equipment.next_maintenance > datetime.utcnow(),
            Equipment.next_maintenance <= datetime.utcnow() + timedelta(days=3)
        ).count()
        
        # Log this access
        log_activity(
            level='info',
            module='equipment',
            action='view_maintenance_schedule',
            description=f'User {request.user_email} viewed maintenance schedule',
            user_id=request.user_id,
            additional_data={
                'total_due': total_due,
                'overdue_count': overdue,
                'due_soon_count': due_soon,
                'user_plan': request.effective_plan,
                'scope': 'restricted' if not request.is_system_team else 'full'
            }
        )
        
        print(f"✅ Maintenance schedule retrieved for {request.user_email}: {len(maintenance_due.items)} items due")
        
        return jsonify({
            'success': True,
            'data': {
                'maintenance_schedule': [{
                    'id': eq.id,
                    'name': eq.name,
                    'type': eq.type,
                    'next_maintenance': eq.next_maintenance.isoformat() if eq.next_maintenance else None,
                    'status': eq.status,
                    'urgency': 'high' if eq.next_maintenance and eq.next_maintenance <= datetime.utcnow() else 
                              'medium' if eq.next_maintenance and eq.next_maintenance <= datetime.utcnow() + timedelta(days=3) else 'low',
                    'days_until': (eq.next_maintenance.date() - datetime.utcnow().date()).days if eq.next_maintenance else None,
                    'last_maintenance': eq.last_maintenance.isoformat() if eq.last_maintenance else None,
                    'site_name': eq.site.name if eq.site else 'Unknown',
                    'is_critical': eq.is_critical or False
                } for eq in maintenance_due.items],
                'total': maintenance_due.total,
                'pages': maintenance_due.pages,
                'current_page': page,
                'summary': {
                    'total_due': total_due,
                    'overdue': overdue,
                    'due_soon': due_soon,
                    'critical_equipment': len([eq for eq in maintenance_due.items if eq.is_critical]),
                    'avg_days_overdue': calculate_avg_days_overdue(maintenance_due.items) if overdue > 0 else 0
                },
                'access_info': {
                    'viewed_by': request.user_email,
                    'user_type': request.user_type,
                    'effective_plan': request.effective_plan,
                    'scope': 'restricted' if not request.is_system_team else 'full'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching maintenance schedule for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch maintenance schedule'}), 500

@app.route('/api/construction/equipment/maintenance/schedule', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
def schedule_maintenance():
    """Schedule maintenance"""
    try:
        print(f"📅 Maintenance scheduling requested by: {request.user_email}")
        
        data = request.get_json()
        
        # Check if user has permission to schedule maintenance
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            return jsonify({
                'success': False,
                'error': 'Permission denied. Only safety administrators can schedule maintenance',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        equipment_id = data.get('equipment_id')
        if not equipment_id:
            return jsonify({
                'success': False,
                'error': 'Equipment ID is required',
                'code': 'MISSING_EQUIPMENT_ID'
            }), 400
        
        equipment = Equipment.query.get(equipment_id)
        
        if not equipment:
            return jsonify({'success': False, 'error': 'Equipment not found'}), 404
        
        # Validate scheduled date
        scheduled_date = data.get('scheduled_date')
        if not scheduled_date:
            return jsonify({
                'success': False,
                'error': 'Scheduled date is required',
                'code': 'MISSING_SCHEDULED_DATE'
            }), 400
        
        try:
            scheduled_datetime = datetime.fromisoformat(scheduled_date.replace('Z', '+00:00'))
            if scheduled_datetime < datetime.utcnow():
                return jsonify({
                    'success': False,
                    'error': 'Scheduled date cannot be in the past',
                    'code': 'INVALID_SCHEDULED_DATE'
                }), 400
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid scheduled date format',
                'code': 'INVALID_DATE_FORMAT'
            }), 400
        
        # Validate maintenance type
        maintenance_type = data.get('maintenance_type', 'routine')
        valid_types = ['routine', 'preventive', 'corrective', 'emergency']
        if maintenance_type not in valid_types:
            return jsonify({
                'success': False,
                'error': f'Invalid maintenance type. Must be one of: {", ".join(valid_types)}',
                'code': 'INVALID_MAINTENANCE_TYPE'
            }), 400
        
        # Schedule maintenance
        old_next_maintenance = equipment.next_maintenance
        equipment.next_maintenance = scheduled_datetime
        equipment.maintenance_type = maintenance_type
        equipment.updated_at = datetime.utcnow()
        equipment.updated_by = request.user_id
        
        # Create maintenance schedule record
        schedule_record = MaintenanceSchedule(
            equipment_id=equipment_id,
            scheduled_date=scheduled_datetime,
            maintenance_type=maintenance_type,
            scheduled_by=request.user_id,
            status='scheduled',
            priority=data.get('priority', 'medium'),
            estimated_duration_hours=data.get('estimated_duration_hours'),
            assigned_technician=data.get('assigned_technician'),
            notes=data.get('notes', ''),
            created_at=datetime.utcnow()
        )
        db.session.add(schedule_record)
        
        db.session.commit()
        
        # Log this scheduling
        log_activity(
            level='info',
            module='equipment',
            action='schedule_maintenance',
            description=f'User {request.user_email} scheduled maintenance for equipment #{equipment_id}',
            user_id=request.user_id,
            resource_id=equipment_id,
            resource_type='equipment',
            additional_data={
                'equipment_id': equipment_id,
                'equipment_name': equipment.name,
                'scheduled_date': scheduled_datetime.isoformat(),
                'maintenance_type': maintenance_type,
                'old_next_maintenance': old_next_maintenance.isoformat() if old_next_maintenance else None,
                'schedule_id': schedule_record.id,
                'scheduled_by': request.user_email
            }
        )
        
        print(f"✅ Maintenance scheduled by {request.user_email} for equipment #{equipment_id}")
        
        return jsonify({
            'success': True,
            'data': {
                'message': 'Maintenance scheduled successfully',
                'equipment_id': equipment_id,
                'equipment_name': equipment.name,
                'scheduled_date': equipment.next_maintenance.isoformat(),
                'schedule_id': schedule_record.id,
                'maintenance_type': maintenance_type,
                'scheduled_by': request.user_email,
                'scheduled_at': datetime.utcnow().isoformat(),
                'schedule_details': {
                    'priority': schedule_record.priority,
                    'estimated_duration_hours': schedule_record.estimated_duration_hours,
                    'assigned_technician': schedule_record.assigned_technician
                }
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error scheduling maintenance for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to schedule maintenance'}), 500

@app.route('/api/construction/training/modules', methods=['GET'])
@jwt_required  # ✅ Added JWT protection
def get_training_modules():
    """Get construction training modules"""
    try:
        print(f"🎓 Training modules requested by: {request.user_email}")
        
        # Check user access and plan restrictions
        user_department_id = getattr(request.user, 'department_id', None)
        
        modules_query = Training.query.filter(
            db.or_(
                Training.category.ilike('%construction%'),
                Training.category.ilike('%safety%'),
                Training.category.ilike('%compliance%')
            )
        ).filter_by(is_active=True)
        
        # Apply department-specific filters for non-system users
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            if user_department_id:
                # Filter for department-specific or general training
                modules_query = modules_query.filter(
                    db.or_(
                        Training.department_id == user_department_id,
                        Training.department_id.is_(None)
                    )
                )
        
        # Apply additional filters
        category_filter = request.args.get('category')
        if category_filter:
            modules_query = modules_query.filter_by(category=category_filter)
        
        required_only = request.args.get('required_only', 'false').lower() == 'true'
        if required_only:
            modules_query = modules_query.filter_by(is_required=True)
        
        # Get pagination parameters
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 20, type=int)
        
        modules = modules_query.order_by(Training.is_required.desc(), Training.title).paginate(
            page=page, per_page=per_page, error_out=False
        )
        
        # Check user's training completion status for each module
        user_training_status = {}
        for module in modules.items:
            record = TrainingRecord.query.filter_by(
                user_id=request.user_id,
                training_id=module.id
            ).first()
            
            user_training_status[module.id] = {
                'status': record.status if record else 'not_started',
                'completion_date': record.completion_date.isoformat() if record and record.completion_date else None,
                'score': record.score if record else None
            }
        
        # Calculate training statistics
        total_modules = len(modules.items)
        required_modules = len([m for m in modules.items if m.is_required])
        completed_by_user = len([status for status in user_training_status.values() if status['status'] == 'completed'])
        required_completed = len([
            m for m in modules.items 
            if m.is_required and user_training_status.get(m.id, {}).get('status') == 'completed'
        ])
        
        # Log this access
        log_activity(
            level='info',
            module='training',
            action='view_training_modules',
            description=f'User {request.user_email} viewed training modules',
            user_id=request.user_id,
            additional_data={
                'total_modules': total_modules,
                'required_modules': required_modules,
                'user_completed': completed_by_user,
                'user_required_completed': required_completed,
                'scope': 'restricted' if not request.is_system_team else 'full'
            }
        )
        
        print(f"✅ Training modules retrieved for {request.user_email}: {total_modules} modules")
        
        return jsonify({
            'success': True,
            'data': {
                'modules': [{
                    'id': module.id,
                    'code': module.code,
                    'title': module.title,
                    'description': module.description,
                    'category': module.category,
                    'duration_minutes': module.duration_minutes,
                    'is_required': module.is_required,
                    'department': module.department.name if module.department else 'General',
                    'validity_months': module.validity_months,
                    'prerequisites': module.prerequisites or [],
                    'user_status': user_training_status.get(module.id, {
                        'status': 'not_started',
                        'completion_date': None,
                        'score': None
                    }),
                    'due_date': calculate_training_due_date(module, user_training_status.get(module.id))
                } for module in modules.items],
                'total': modules.total,
                'pages': modules.pages,
                'current_page': page,
                'user_training_summary': {
                    'total_modules': total_modules,
                    'required_modules': required_modules,
                    'completed_modules': completed_by_user,
                    'required_completed': required_completed,
                    'completion_rate': (completed_by_user / total_modules * 100) if total_modules > 0 else 0,
                    'required_completion_rate': (required_completed / required_modules * 100) if required_modules > 0 else 0,
                    'overdue_trainings': len([
                        m for m in modules.items 
                        if m.is_required and user_training_status.get(m.id, {}).get('status') in ['not_started', 'in_progress']
                    ])
                },
                'access_info': {
                    'viewed_by': request.user_email,
                    'user_type': request.user_type,
                    'department_id': user_department_id,
                    'scope': 'department_restricted' if not request.is_system_team else 'full'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching training modules for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch training modules'}), 500

@app.route('/api/construction/training/assign', methods=['POST'])
@jwt_required  # ✅ Added JWT protection
def assign_construction_training():
    """Assign construction training"""
    try:
        print(f"📚 Training assignment requested by: {request.user_email}")
        
        data = request.get_json()
        
        # Check if user has permission to assign training
        if not request.is_system_team and request.user_type not in ['admin', 'safetypro']:
            return jsonify({
                'success': False,
                'error': 'Permission denied. Only safety administrators can assign training',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # Validate required fields
        required_fields = ['user_id', 'training_id']
        missing_fields = [field for field in required_fields if field not in data]
        if missing_fields:
            return jsonify({
                'success': False,
                'error': f'Missing required fields: {", ".join(missing_fields)}',
                'code': 'MISSING_FIELDS'
            }), 400
        
        # Check if training exists
        training = Training.query.get(data['training_id'])
        if not training:
            return jsonify({
                'success': False,
                'error': 'Training module not found',
                'code': 'TRAINING_NOT_FOUND'
            }), 404
        
        # Check if user exists
        assigned_user = User.query.get(data['user_id'])
        if not assigned_user:
            return jsonify({
                'success': False,
                'error': 'User not found',
                'code': 'USER_NOT_FOUND'
            }), 404
        
        # Check if training is already assigned to user
        existing_assignment = TrainingRecord.query.filter_by(
            user_id=data['user_id'],
            training_id=data['training_id']
        ).first()
        
        if existing_assignment:
            return jsonify({
                'success': False,
                'error': 'Training is already assigned to this user',
                'code': 'DUPLICATE_ASSIGNMENT',
                'existing_record': {
                    'id': existing_assignment.id,
                    'status': existing_assignment.status,
                    'assigned_date': existing_assignment.assigned_date.isoformat() if existing_assignment.assigned_date else None
                }
            }), 400
        
        # Calculate due date (default: 30 days from now)
        due_date = None
        if data.get('due_date'):
            try:
                due_date = datetime.fromisoformat(data['due_date'].replace('Z', '+00:00'))
            except ValueError:
                due_date = datetime.utcnow() + timedelta(days=30)
        else:
            due_date = datetime.utcnow() + timedelta(days=30)
        
        # Create training assignment
        training_record = TrainingRecord(
            user_id=data['user_id'],
            training_id=data['training_id'],
            assigned_by=request.user_id,
            assigned_date=datetime.utcnow(),
            due_date=due_date,
            status='assigned',
            notes=data.get('notes', ''),
            priority=data.get('priority', 'medium'),
            created_at=datetime.utcnow()
        )
        
        db.session.add(training_record)
        db.session.commit()
        
        # Log this assignment
        log_activity(
            level='info',
            module='training',
            action='assign_training',
            description=f'User {request.user_email} assigned training to user {assigned_user.email}',
            user_id=request.user_id,
            resource_id=training_record.id,
            resource_type='training_record',
            additional_data={
                'training_id': data['training_id'],
                'training_title': training.title,
                'assigned_to_user_id': data['user_id'],
                'assigned_to_email': assigned_user.email,
                'due_date': due_date.isoformat(),
                'priority': training_record.priority,
                'assigned_by': request.user_email
            }
        )
        
        print(f"✅ Training assigned by {request.user_email} to {assigned_user.email}: {training.title}")
        
        return jsonify({
            'success': True,
            'data': {
                'assignment_id': training_record.id,
                'message': 'Training assigned successfully',
                'training': {
                    'id': training.id,
                    'title': training.title,
                    'category': training.category,
                    'duration_minutes': training.duration_minutes
                },
                'assigned_to': {
                    'user_id': assigned_user.id,
                    'email': assigned_user.email,
                    'name': assigned_user.name
                },
                'assignment_details': {
                    'assigned_by': request.user_email,
                    'assigned_date': training_record.assigned_date.isoformat(),
                    'due_date': training_record.due_date.isoformat(),
                    'status': training_record.status,
                    'priority': training_record.priority
                }
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error assigning training for user {request.user_email}: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to assign training'}), 500
    
@app.route('/api/construction/training/compliance', methods=['GET'])
@jwt_required
def get_construction_training_compliance():
    """Get training compliance"""
    try:
        # Check access permissions
        if request.user_type not in ['admin', 'safety_manager', 'supervisor'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions',
                'code': 'INSUFFICIENT_PERMISSIONS'
            }), 403
        
        # Calculate training compliance metrics
        total_assignments = TrainingRecord.query.count()
        completed_assignments = TrainingRecord.query.filter_by(status='completed').count()
        overdue_assignments = TrainingRecord.query.filter(
            TrainingRecord.completion_date.is_(None),
            TrainingRecord.created_at <= datetime.utcnow() - timedelta(days=30)
        ).count()
        
        compliance_rate = (completed_assignments / total_assignments * 100) if total_assignments > 0 else 0
        
        return jsonify({
            'success': True,
            'data': {
                'compliance_rate': round(compliance_rate, 2),
                'total_assignments': total_assignments,
                'completed_assignments': completed_assignments,
                'overdue_assignments': overdue_assignments,
                'compliance_status': 'compliant' if compliance_rate >= 90 else 'needs_improvement',
                'access_level': request.user_type,
                'effective_plan': request.effective_plan
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching training compliance: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch training compliance'}), 500

@app.route('/api/construction/training/records', methods=['GET'])
@jwt_required
def get_construction_training_records():
    """Get training records"""
    try:
        # Check if user has access to training records
        if request.user_type not in ['admin', 'safety_manager', 'trainer', 'supervisor'] and not request.is_system_team:
            # Regular users can only see their own records
            records = TrainingRecord.query.filter_by(user_id=request.user.id).order_by(
                TrainingRecord.completion_date.desc()
            ).all()
        else:
            # Admins and managers can see all records
            records = TrainingRecord.query.order_by(TrainingRecord.completion_date.desc()).all()
        
        return jsonify({
            'success': True,
            'data': {
                'records': [{
                    'id': record.id,
                    'user_id': record.user_id,
                    'training_title': record.training.title if record.training else 'Unknown',
                    'completion_date': record.completion_date.isoformat() if record.completion_date else None,
                    'status': record.status,
                    'score': record.score
                } for record in records],
                'total_count': len(records),
                'user_type': request.user_type
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching training records: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to fetch training records'}), 500

@app.route('/api/construction/training/records/<int:record_id>', methods=['PUT'])
@jwt_required
def update_construction_training_completion(record_id):
    """Update training completion"""
    try:
        # Only trainers, admins, and safety managers can update training records
        if request.user_type not in ['admin', 'safety_manager', 'trainer'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions to update training records',
                'code': 'INSUFFICIENT_PERMISSIONS'
            }), 403
        
        data = request.get_json()
        record = TrainingRecord.query.get(record_id)
        
        if not record:
            return jsonify({'success': False, 'error': 'Training record not found'}), 404
        
        # Check if user can update this record (unless they're admin/system)
        if request.user_type not in ['admin', 'safety_manager'] and not request.is_system_team:
            # Trainers can only update records for trainings they own/created
            # This assumes you have a way to check trainer assignments
            pass
            
        if 'status' in data:
            record.status = data['status']
        if 'score' in data:
            record.score = data['score']
        if data.get('status') == 'completed':
            record.completion_date = datetime.utcnow()
            
        record.updated_by = request.user.id
        record.updated_at = datetime.utcnow()
        db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'record': {
                    'id': record.id,
                    'status': record.status,
                    'completion_date': record.completion_date.isoformat() if record.completion_date else None,
                    'score': record.score,
                    'updated_by': request.user.email
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error updating training completion: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to update training completion'}), 500

@app.route('/api/construction/training/schedule', methods=['POST'])
@jwt_required
def schedule_construction_training():
    """Schedule training"""
    try:
        # Only trainers, admins, and safety managers can schedule training
        if request.user_type not in ['admin', 'safety_manager', 'trainer'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions to schedule training',
                'code': 'INSUFFICIENT_PERMISSIONS'
            }), 403
        
        # Check plan limits for training scheduling
        if request.effective_plan == 'free':
            # Check if free plan can schedule training
            max_free_trainings = request.plan_limits.get('max_training_sessions', 2)
            existing_trainings = TrainingSession.query.filter_by(created_by=request.user.id).count()
            if existing_trainings >= max_free_trainings:
                return jsonify({
                    'success': False,
                    'error': 'Free plan limit reached for training sessions',
                    'code': 'PLAN_LIMIT_REACHED',
                    'limit': max_free_trainings
                }), 403
        
        data = request.get_json()
        
        # Create training session
        session = TrainingSession(
            training_id=data.get('training_id'),
            session_code=f"TS-{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}",
            title=data.get('title', 'Training Session'),
            instructor_id=request.user.id,
            location=data.get('location', 'Training Room'),
            start_date=datetime.fromisoformat(data.get('start_date').replace('Z', '+00:00')) if data.get('start_date') else datetime.utcnow(),
            end_date=datetime.fromisoformat(data.get('end_date').replace('Z', '+00:00')) if data.get('end_date') else datetime.utcnow() + timedelta(hours=2),
            max_attendees=data.get('max_attendees', 20),
            status='scheduled',
            created_by=request.user.id
        )
        db.session.add(session)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'schedule_id': session.id,
                'session_code': session.session_code,
                'message': 'Training scheduled successfully',
                'scheduled_by': request.user.email
            }
        }), 201
        
    except Exception as e:
        logger.error(f"Error scheduling training: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to schedule training'}), 500

