@app.route('/api/construction/emergency/procedures/<int:procedure_id>', methods=['PUT'])
@jwt_required
def update_construction_emergency_procedure(procedure_id):
    """Update emergency procedure"""
    try:
        # Only safety managers and admins can update emergency procedures
        if request.user_type not in ['admin', 'safety_manager'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions to update emergency procedures',
                'code': 'INSUFFICIENT_PERMISSIONS'
            }), 403
        
        data = request.get_json()
        procedure = ConstructionDocument.query.get(procedure_id)
        
        if not procedure:
            return jsonify({'success': False, 'error': 'Emergency procedure not found'}), 404
            
        procedure.title = data.get('title', procedure.title)
        procedure.description = data.get('description', procedure.description)
        procedure.updated_by = request.user.id
        procedure.updated_at = datetime.utcnow()
        db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'procedure': procedure.to_dict(),
                'updated_by': request.user.email
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error updating emergency procedure: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to update emergency procedure'}), 500

