@app.route('/api/construction/environmental/reports', methods=['POST'])
@jwt_required
def submit_construction_environmental_report():
    """Submit environmental report"""
    try:
        # Check plan limits for report submissions
        if request.effective_plan == 'free':
            max_free_reports = request.plan_limits.get('max_reports_per_month', 5)
            # Count reports submitted this month
            current_month = datetime.utcnow().month
            reports_this_month = ConstructionDocument.query.filter(
                ConstructionDocument.user_id == request.user.id,
                ConstructionDocument.document_type == 'environmental_report',
                db.extract('month', ConstructionDocument.created_at) == current_month
            ).count()
            
            if reports_this_month >= max_free_reports:
                return jsonify({
                    'success': False,
                    'error': 'Monthly report limit reached',
                    'code': 'MONTHLY_LIMIT_REACHED',
                    'limit': max_free_reports
                }), 403
        
        data = request.get_json()
        
        # Create environmental report document
        report = ConstructionDocument(
            user_id=request.user.id,
            title=data.get('title', 'Environmental Report'),
            description=data.get('description', ''),
            document_type='environmental_report',
            status='submitted',
            metadata={
                'submitted_by': request.user.email,
                'user_type': request.user_type,
                'plan': request.effective_plan
            }
        )
        db.session.add(report)
        db.session.commit()
        
        # Track usage for free plans
        if request.effective_plan == 'free':
            request.user.monthly_reports_submitted = (getattr(request.user, 'monthly_reports_submitted', 0) or 0) + 1
            db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'report_id': report.id,
                'message': 'Environmental report submitted successfully',
                'submitted_by': request.user.email,
                'remaining_reports': max_free_reports - reports_this_month - 1 if request.effective_plan == 'free' else 'unlimited'
            }
        }), 201
        
    except Exception as e:
        logger.error(f"Error submitting environmental report: {str(e)}")
        return jsonify({'success': False, 'error': 'Failed to submit environmental report'}), 500

