@app.route('/api/construction/analytics/metrics/calculate', methods=['POST'])
@jwt_required
def calculate_construction_safety_metrics():
    """Calculate safety metrics"""
    try:
        # Custom metric calculation requires Pro plan
        if 'custom_metrics' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Custom metric calculation not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for custom safety metrics'
            }), 403
        
        data = request.get_json()
        
        if not data.get('metrics_data'):
            return jsonify({
                'success': False,
                'error': 'Metrics data is required',
                'code': 'MISSING_METRICS_DATA',
                'suggestion': 'Provide metrics_data in your request body'
            }), 400
        
        # Check calculation frequency limit for non-enterprise plans
        if request.effective_plan != 'enterprise':
            max_daily_calculations = request.plan_limits.get('max_daily_calculations', 50)
            today = datetime.utcnow().date()
            calculations_today = getattr(request.user, 'daily_calculations_count', 0) or 0
            
            if calculations_today >= max_daily_calculations:
                return jsonify({
                    'success': False,
                    'error': f'Daily calculation limit reached ({max_daily_calculations})',
                    'code': 'DAILY_LIMIT_REACHED',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited calculations',
                    'reset_time': (datetime.utcnow() + timedelta(days=1)).replace(hour=0, minute=0, second=0).isoformat()
                }), 403
        
        # Calculate custom metrics
        metrics_data = data.get('metrics_data', {})
        
        # Validate input data
        required_fields = ['incidents', 'inspections', 'training_hours']
        missing_fields = [field for field in required_fields if field not in metrics_data]
        if missing_fields:
            return jsonify({
                'success': False,
                'error': f'Missing required fields: {", ".join(missing_fields)}',
                'code': 'MISSING_REQUIRED_FIELDS',
                'suggestion': f'Include {", ".join(missing_fields)} in your metrics_data'
            }), 400
        
        # Perform calculations
        calculated_metrics = {
            'safety_performance_index': calculate_spi(metrics_data),
            'risk_exposure_score': calculate_risk_score(metrics_data),
            'compliance_rating': calculate_compliance(metrics_data),
            'training_effectiveness': calculate_training_effectiveness(metrics_data),
            'equipment_reliability': calculate_equipment_reliability(metrics_data)
        }
        
        # Update usage counter
        if request.effective_plan != 'enterprise':
            request.user.daily_calculations_count = calculations_today + 1
            db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'calculated_metrics': calculated_metrics,
                'calculation_method': 'weighted_composite',
                'confidence_score': 0.89,
                'usage_info': {
                    'calculations_today': calculations_today + 1,
                    'daily_limit': max_daily_calculations,
                    'remaining_calculations': max_daily_calculations - (calculations_today + 1)
                } if request.effective_plan != 'enterprise' else {'unlimited': True},
                'export_formats': ['json', 'csv'] if 'data_export' in request.plan_features else ['json']
            }
        }), 200
        
    except ValueError as ve:
        logger.error(f"Validation error in metric calculation: {str(ve)}")
        return jsonify({
            'success': False,
            'error': 'Invalid metrics data',
            'code': 'INVALID_METRICS_DATA',
            'suggestion': 'Check your input data format and values'
        }), 400
    except Exception as e:
        logger.error(f"Error calculating safety metrics: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to calculate safety metrics',
            'code': 'METRIC_CALCULATION_ERROR',
            'suggestion': 'Verify your input data and try again. Contact support if the issue persists'
        }), 500

