@app.route('/api/construction/inspections', methods=['GET'])
@jwt_required
def get_construction_safety_inspections():
    """Get safety inspections"""
    try:
        # Inspections are available in all plans, but with different limits
        max_inspections = {
            'free': 20,
            'pro': 100,
            'business': 500,
            'enterprise': 'unlimited'
        }.get(request.effective_plan, 20)
        
        # Determine access level
        if request.user_type in ['admin', 'safety_manager', 'inspector'] or request.is_system_team:
            # Full access - see all inspections
            query = SafetyInspection.query
            access_level = 'full'
        elif request.user_type == 'supervisor':
            # See inspections for their site/department
            query = SafetyInspection.query.filter(
                SafetyInspection.department == getattr(request.user, 'department', 'Construction')
            )
            access_level = 'department'
        else:
            # Regular users see only their assigned inspections
            query = SafetyInspection.query.filter(
                SafetyInspection.assigned_to.contains(request.user.id)
            )
            access_level = 'personal'
        
        # Apply limit for non-enterprise plans
        if max_inspections != 'unlimited':
            query = query.limit(max_inspections)
        
        inspections = query.order_by(
            SafetyInspection.inspection_date.desc()
        ).all()
        
        return jsonify({
            'success': True,
            'data': {
                'inspections': [{
                    'id': inspection.id,
                    'inspection_number': inspection.inspection_number,
                    'title': inspection.title,
                    'type': inspection.type,
                    'area': inspection.area,
                    'inspection_date': inspection.inspection_date.isoformat(),
                    'score': inspection.score,
                    'status': inspection.status,
                    'priority': inspection.priority if hasattr(inspection, 'priority') else 'medium'
                } for inspection in inspections],
                'total_count': len(inspections),
                'max_inspections': max_inspections,
                'access_level': access_level,
                'plan_info': {
                    'current_plan': request.effective_plan,
                    'photo_attachments': 'inspection_photos' in request.plan_features,
                    'digital_signatures': 'digital_signatures' in request.plan_features
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching safety inspections: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch safety inspections',
            'code': 'INSPECTIONS_FETCH_ERROR',
            'suggestion': 'Try again in a few minutes. Contact support if the issue persists'
        }), 500

@app.route('/api/construction/inspections/schedule', methods=['POST'])
@jwt_required
def schedule_construction_inspection():
    """Schedule inspection"""
    try:
        # Check if user can schedule inspections
        if request.user_type not in ['admin', 'safety_manager', 'supervisor', 'inspector'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions to schedule inspections',
                'code': 'INSUFFICIENT_PERMISSIONS',
                'suggestion': 'Only safety managers, supervisors, and inspectors can schedule inspections'
            }), 403
        
        # Check monthly inspection limit for non-enterprise plans
        if request.effective_plan != 'enterprise':
            max_monthly_inspections = request.plan_limits.get('max_monthly_inspections', 50)
            current_month = datetime.utcnow().month
            current_year = datetime.utcnow().year
            inspections_this_month = SafetyInspection.query.filter(
                SafetyInspection.user_id == request.user.id,
                db.extract('year', SafetyInspection.created_at) == current_year,
                db.extract('month', SafetyInspection.created_at) == current_month
            ).count()
            
            if inspections_this_month >= max_monthly_inspections:
                return jsonify({
                    'success': False,
                    'error': f'Monthly inspection scheduling limit reached ({max_monthly_inspections})',
                    'code': 'MONTHLY_LIMIT_REACHED',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited inspections',
                    'current_usage': inspections_this_month,
                    'limit': max_monthly_inspections
                }), 403
        
        data = request.get_json()
        
        if not data.get('title'):
            return jsonify({
                'success': False,
                'error': 'Inspection title is required',
                'code': 'MISSING_TITLE',
                'suggestion': 'Provide a title for the inspection'
            }), 400
        
        # Validate scheduled date
        scheduled_date_str = data.get('scheduled_date')
        if not scheduled_date_str:
            return jsonify({
                'success': False,
                'error': 'Scheduled date is required',
                'code': 'MISSING_SCHEDULED_DATE',
                'suggestion': 'Provide a scheduled_date for the inspection'
            }), 400
        
        scheduled_date = datetime.fromisoformat(scheduled_date_str.replace('Z', '+00:00'))
        if scheduled_date < datetime.utcnow():
            return jsonify({
                'success': False,
                'error': 'Scheduled date cannot be in the past',
                'code': 'INVALID_SCHEDULED_DATE',
                'suggestion': 'Schedule the inspection for a future date'
            }), 400
        
        inspection = SafetyInspection(
            user_id=request.user.id,
            inspection_number=f"INS-{datetime.utcnow().strftime('%Y%m%d')}-{uuid.uuid4().hex[:8].upper()}",
            title=data.get('title', 'Scheduled Inspection'),
            type=data.get('inspection_type', 'routine'),
            area=data.get('area', 'General'),
            department=data.get('department', getattr(request.user, 'department', 'Construction')),
            conducted_by=request.user.id,
            inspection_date=scheduled_date,
            status='scheduled',
            priority=data.get('priority', 'medium'),
            metadata={
                'scheduled_by': request.user.email,
                'user_role': request.user_type,
                'plan': request.effective_plan
            }
        )
        db.session.add(inspection)
        db.session.commit()
        
        # Update usage counter
        if request.effective_plan != 'enterprise':
            request.user.monthly_inspections_scheduled = getattr(request.user, 'monthly_inspections_scheduled', 0) + 1
            db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'inspection_id': inspection.id,
                'inspection_number': inspection.inspection_number,
                'message': 'Inspection scheduled successfully',
                'scheduled_date': scheduled_date.isoformat(),
                'scheduled_by': request.user.email,
                'usage_info': {
                    'inspections_scheduled_this_month': inspections_this_month + 1,
                    'monthly_limit': max_monthly_inspections,
                    'remaining_inspections': max_monthly_inspections - (inspections_this_month + 1)
                } if request.effective_plan != 'enterprise' else {'unlimited': True}
            }
        }), 201
        
    except ValueError as ve:
        logger.error(f"Validation error scheduling inspection: {str(ve)}")
        return jsonify({
            'success': False,
            'error': 'Invalid date format',
            'code': 'INVALID_DATE_FORMAT',
            'suggestion': 'Use ISO 8601 format for dates (e.g., 2024-01-15T10:30:00Z)'
        }), 400
    except Exception as e:
        logger.error(f"Error scheduling inspection: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to schedule inspection',
            'code': 'INSPECTION_SCHEDULING_ERROR',
            'suggestion': 'Check your input data and try again. Contact support if the issue persists'
        }), 500

@app.route('/api/construction/inspections/checklists', methods=['GET'])
@jwt_required
def get_construction_inspection_checklists():
    """Get inspection checklists"""
    try:
        # Checklist access varies by plan
        max_checklists = {
            'free': 5,
            'pro': 20,
            'business': 100,
            'enterprise': 'unlimited'
        }.get(request.effective_plan, 5)
        
        # Using DocumentTemplate as placeholder for inspection checklists
        query = DocumentTemplate.query.filter(
            DocumentTemplate.category.ilike('%inspection%') |
            DocumentTemplate.category.ilike('%checklist%')
        )
        
        # Filter by user permissions
        if request.user_type not in ['admin', 'safety_manager'] and not request.is_system_team:
            # Regular users see only public checklists
            query = query.filter_by(is_public=True)
        
        # Apply limit for non-enterprise plans
        if max_checklists != 'unlimited':
            query = query.limit(max_checklists)
        
        checklists = query.all()
        
        return jsonify({
            'success': True,
            'data': {
                'checklists': [{
                    'id': checklist.id,
                    'name': checklist.name,
                    'description': checklist.description,
                    'category': checklist.category,
                    'items_count': len(checklist.items) if hasattr(checklist, 'items') else 0,
                    'is_editable': 'checklist_customization' in request.plan_features
                } for checklist in checklists],
                'total_available': len(checklists),
                'max_checklists': max_checklists,
                'plan_features': {
                    'custom_checklists': 'checklist_customization' in request.plan_features,
                    'template_library': 'template_library' in request.plan_features,
                    'import_export': 'data_export' in request.plan_features
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching inspection checklists: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch inspection checklists',
            'code': 'CHECKLIST_FETCH_ERROR',
            'suggestion': 'Try again in a few minutes. Contact support if the issue persists'
        }), 500
