# === HELPER FUNCTIONS ===

def generate_trend_data(timeframe):
    """Generate trend data based on timeframe"""
    days = 30 if timeframe == '30d' else 90 if timeframe == '90d' else 365
    
    data = []
    base_date = datetime.utcnow() - timedelta(days=days)
    
    for i in range(days):
        date = base_date + timedelta(days=i)
        data.append({
            'date': date.isoformat(),
            'incidents': max(0, np.random.poisson(0.5)),
            'compliance_rate': min(100, 85 + np.random.normal(0, 5)),
            'training_completion': min(100, 90 + np.random.normal(0, 3)),
            'safety_score': min(100, 88 + np.random.normal(0, 4))
        })
    
    return data

def analyze_trends(trends_data):
    """Analyze trends from data"""
    if not trends_data:
        return {}
    
    incidents = [d['incidents'] for d in trends_data]
    compliance = [d['compliance_rate'] for d in trends_data]
    
    analysis = {
        'incident_trend': 'improving' if np.mean(incidents[-7:]) < np.mean(incidents[:-7]) else 'worsening' if np.mean(incidents[-7:]) > np.mean(incidents[:-7]) else 'stable',
        'compliance_trend': 'improving' if np.mean(compliance[-7:]) > np.mean(compliance[:-7]) else 'worsening' if np.mean(compliance[-7:]) < np.mean(compliance[:-7]) else 'stable',
        'average_incidents': round(np.mean(incidents), 2),
        'average_compliance': round(np.mean(compliance), 2),
        'trend_strength': 'strong' if abs(np.mean(incidents[-7:]) - np.mean(incidents[:-7])) > 1 else 'moderate'
    }
    
    return analysis

def generate_trend_recommendations(analysis):
    """Generate recommendations based on trend analysis"""
    recommendations = []
    
    if analysis.get('incident_trend') == 'worsening':
        recommendations.append('Increase safety inspections and monitoring')
        
    if analysis.get('compliance_trend') == 'worsening':
        recommendations.append('Enhance training and compliance enforcement')
        
    if analysis.get('average_incidents', 0) > 2:
        recommendations.append('Implement additional safety controls and procedures')
        
    if analysis.get('average_compliance', 0) < 85:
        recommendations.append('Review and update safety policies and procedures')
        
    return recommendations

