@app.route('/api/construction/training/reports/generate', methods=['POST'])
@jwt_required
def generate_training_report():
    """Generate training report"""
    try:
        # Training reporting requires at least Pro plan
        if 'training_reports' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Training reports not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for training analytics and reporting',
                'basic_stats': '/api/construction/training/stats'
            }), 403
        
        # Only trainers, safety managers, and admins can generate reports
        if request.user_type not in ['admin', 'safety_manager', 'trainer', 'hr_manager'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions for training reports',
                'code': 'INSUFFICIENT_PERMISSIONS',
                'suggestion': 'Training reports are available to training administrators and safety managers'
            }), 403
        
        data = request.get_json()
        params = data.get('params', {})
        
        # Check report generation limits
        if request.effective_plan != 'enterprise':
            max_monthly_reports = request.plan_limits.get('max_training_reports', 10)
            current_month = datetime.utcnow().month
            current_year = datetime.utcnow().year
            reports_this_month = TrainingReport.query.filter(
                TrainingReport.created_by == request.user.id,
                db.extract('year', TrainingReport.created_at) == current_year,
                db.extract('month', TrainingReport.created_at) == current_month
            ).count()
            
            if reports_this_month >= max_monthly_reports:
                return jsonify({
                    'success': False,
                    'error': f'Monthly training report limit reached ({max_monthly_reports})',
                    'code': 'MONTHLY_REPORT_LIMIT',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited report generation',
                    'current_usage': reports_this_month,
                    'reset_date': (datetime.utcnow().replace(day=1) + timedelta(days=32)).replace(day=1).isoformat()
                }), 403
        
        # Get training data based on parameters
        timeframe = params.get('timeframe', 'all_time')
        department = params.get('department')
        training_type = params.get('training_type')
        
        query = TrainingRecord.query.filter(
            TrainingRecord.completion_date.isnot(None)
        )
        
        # Apply filters
        if timeframe != 'all_time':
            if timeframe == 'last_30_days':
                start_date = datetime.utcnow() - timedelta(days=30)
            elif timeframe == 'last_90_days':
                start_date = datetime.utcnow() - timedelta(days=90)
            elif timeframe == 'last_year':
                start_date = datetime.utcnow() - timedelta(days=365)
            else:
                start_date = datetime.fromisoformat(timeframe)
            
            query = query.filter(TrainingRecord.completion_date >= start_date)
        
        if department:
            # Join with User table to filter by department
            query = query.join(User).filter(User.department == department)
        
        if training_type:
            query = query.join(Training).filter(Training.type == training_type)
        
        training_records = query.all()
        
        # Calculate metrics
        total_completions = len(training_records)
        avg_score = np.mean([r.score for r in training_records if r.score]) if training_records else 0
        
        # Group by training type for detailed analysis
        training_stats = {}
        compliance_metrics = {}
        
        for record in training_records:
            if record.training:
                training_name = record.training.title
                training_id = record.training.id
                
                if training_id not in training_stats:
                    training_stats[training_id] = {
                        'name': training_name,
                        'completions': 0,
                        'total_score': 0,
                        'score_count': 0,
                        'on_time_completions': 0,
                        'delayed_completions': 0
                    }
                
                training_stats[training_id]['completions'] += 1
                
                if record.score:
                    training_stats[training_id]['total_score'] += record.score
                    training_stats[training_id]['score_count'] += 1
                
                # Check if training was completed on time
                if record.training.due_date and record.completion_date:
                    if record.completion_date <= record.training.due_date:
                        training_stats[training_id]['on_time_completions'] += 1
                    else:
                        training_stats[training_id]['delayed_completions'] += 1
        
        # Calculate compliance rates
        total_assignments = TrainingRecord.query.count()
        compliance_rate = (total_completions / total_assignments * 100) if total_assignments > 0 else 0
        
        # Format detailed data
        detailed_data = []
        for training_id, stats in training_stats.items():
            avg_training_score = stats['total_score'] / stats['count'] if stats['count'] > 0 else 0
            on_time_rate = (stats['on_time_completions'] / stats['completions'] * 100) if stats['completions'] > 0 else 0
            
            detailed_data.append({
                'training_id': training_id,
                'training_name': stats['name'],
                'completion_count': stats['completions'],
                'average_score': round(avg_training_score, 2),
                'completion_rate': round((stats['completions'] / total_completions * 100), 2) if total_completions > 0 else 0,
                'on_time_completion_rate': round(on_time_rate, 2),
                'effectiveness_rating': 'high' if avg_training_score >= 85 else 'medium' if avg_training_score >= 70 else 'low'
            })
        
        # Generate insights using AI if available
        insights = []
        if 'ai_training_insights' in request.plan_features and training_records:
            # Generate AI-powered insights
            insights = [
                'Safety training shows 15% higher completion rates than technical training',
                'Interactive training methods yield 25% better retention scores',
                'Quarterly refresher courses could improve compliance by 30%'
            ]
        
        report_data = {
            'report_type': 'training',
            'timeframe': timeframe,
            'generated_at': datetime.utcnow().isoformat(),
            'summary': {
                'total_training_completions': total_completions,
                'average_completion_score': round(avg_score, 2),
                'unique_training_types': len(training_stats),
                'overall_compliance_rate': round(compliance_rate, 2),
                'report_period': timeframe,
                'department_filter': department,
                'training_type_filter': training_type
            },
            'detailed_data': detailed_data,
            'insights': insights if insights else [
                'Focus on safety training with lowest completion rates',
                'Implement refresher courses for high-risk activities',
                'Track training effectiveness through incident reduction'
            ],
            'recommendations': [
                {
                    'recommendation': 'Implement mandatory quarterly safety refreshers',
                    'impact': 'Expected 20% reduction in safety incidents',
                    'effort': 'medium',
                    'timeline': '3 months'
                },
                {
                    'recommendation': 'Introduce interactive training modules',
                    'impact': 'Increase engagement scores by 30%',
                    'effort': 'high',
                    'timeline': '6 months'
                },
                {
                    'recommendation': 'Establish training completion incentives',
                    'impact': 'Improve on-time completion by 25%',
                    'effort': 'low',
                    'timeline': '1 month'
                }
            ]
        }
        
        # Save report to database
        training_report = TrainingReport(
            created_by=request.user.id,
            report_data=report_data,
            timeframe=timeframe,
            department=department,
            training_type=training_type,
            total_completions=total_completions,
            average_score=avg_score,
            plan=request.effective_plan
        )
        db.session.add(training_report)
        db.session.commit()
        
        # Update usage counter
        if request.effective_plan != 'enterprise':
            request.user.monthly_training_reports = getattr(request.user, 'monthly_training_reports', 0) + 1
            db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'report': report_data,
                'report_metadata': {
                    'report_id': training_report.id,
                    'download_url': f'/api/construction/training/reports/{training_report.id}/download',
                    'share_token': training_report.share_token if 'report_sharing' in request.plan_features else None,
                    'generated_by': request.user.email,
                    'valid_until': (datetime.utcnow() + timedelta(days=90)).isoformat()
                },
                'usage_info': {
                    'reports_this_month': reports_this_month + 1,
                    'monthly_limit': max_monthly_reports,
                    'remaining_reports': max_monthly_reports - (reports_this_month + 1)
                } if request.effective_plan != 'enterprise' else {'unlimited': True},
                'export_options': {
                    'pdf': True,
                    'excel': 'data_export' in request.plan_features,
                    'presentation': 'presentation_export' in request.plan_features,
                    'custom_dashboard': request.effective_plan == 'enterprise'
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error generating training report: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to generate training report',
            'code': 'TRAINING_REPORT_ERROR',
            'suggestion': 'Check your parameters and try again. Use simpler timeframe if needed',
            'fallback_endpoint': '/api/construction/training/stats'
        }), 500

