@app.route('/api/construction/regulatory/osha/submit', methods=['POST'])
@jwt_required
def submit_osha_report():
    """Submit OSHA report"""
    try:
        # OSHA reporting requires at least Pro plan
        if 'osha_reporting' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'OSHA reporting not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for regulatory compliance reporting',
                'compliance_assistance': '/compliance/osha/guidelines'
            }), 403
        
        # Only compliance officers, safety managers, and admins can submit OSHA reports
        if request.user_type not in ['admin', 'safety_manager', 'compliance_officer', 'hr_manager'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions for OSHA reporting',
                'code': 'INSUFFICIENT_PERMISSIONS',
                'suggestion': 'OSHA report submission requires compliance or safety management permissions'
            }), 403
        
        data = request.get_json()
        
        if not data.get('report_data'):
            return jsonify({
                'success': False,
                'error': 'OSHA report data is required',
                'code': 'MISSING_REPORT_DATA',
                'suggestion': 'Provide incident data, injury logs, and training records for OSHA 300A'
            }), 400
        
        # Check if this is a test submission or real submission
        is_test = data.get('test_submission', False)
        
        if not is_test and request.effective_plan != 'enterprise':
            max_annual_submissions = request.plan_limits.get('max_osha_submissions', 4)  # Quarterly
            current_year = datetime.utcnow().year
            submissions_this_year = RegulatorySubmission.query.filter(
                RegulatorySubmission.user_id == request.user.id,
                RegulatorySubmission.agency == 'OSHA',
                db.extract('year', RegulatorySubmission.submission_date) == current_year
            ).count()
            
            if submissions_this_year >= max_annual_submissions:
                return jsonify({
                    'success': False,
                    'error': f'Annual OSHA submission limit reached ({max_annual_submissions})',
                    'code': 'ANNUAL_SUBMISSION_LIMIT',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited regulatory submissions',
                    'current_usage': submissions_this_year,
                    'reset_date': f'{current_year + 1}-01-01'
                }), 403
        
        # Create OSHA report document
        report = ConstructionDocument(
            user_id=request.user.id,
            title=f"OSHA 300A Summary Report - {data.get('reporting_period', datetime.utcnow().strftime('%Y'))}",
            description=f"OSHA 300A report for {data.get('reporting_period', 'Current Year')}\nSubmitted by: {request.user.email}",
            document_type='regulatory_report',
            status='submitted' if not is_test else 'draft',
            metadata={
                'agency': 'OSHA',
                'form_type': '300A',
                'reporting_period': data.get('reporting_period'),
                'submitted_by': request.user.email,
                'user_role': request.user_type,
                'plan': request.effective_plan,
                'is_test': is_test,
                'submission_timestamp': datetime.utcnow().isoformat()
            }
        )
        db.session.add(report)
        
        # Record regulatory submission
        submission = RegulatorySubmission(
            user_id=request.user.id,
            agency='OSHA',
            form_type='300A',
            submission_date=datetime.utcnow(),
            document_id=report.id,
            status='submitted' if not is_test else 'test',
            is_test=is_test,
            plan=request.effective_plan
        )
        db.session.add(submission)
        db.session.commit()
        
        # Update usage counter for real submissions
        if not is_test and request.effective_plan != 'enterprise':
            request.user.osha_submissions_count = getattr(request.user, 'osha_submissions_count', 0) + 1
            db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'report_id': report.id,
                'submission_id': submission.id,
                'message': 'OSHA 300A report submitted successfully',
                'submission_type': 'test' if is_test else 'official',
                'submission_date': datetime.utcnow().isoformat(),
                'next_deadline': (datetime.utcnow().replace(month=3, day=2)).isoformat(),  # March 2nd annual deadline
                'verification_required': not is_test,
                'usage_info': {
                    'submissions_this_year': submissions_this_year + (0 if is_test else 1),
                    'annual_limit': max_annual_submissions,
                    'remaining_submissions': max_annual_submissions - (submissions_this_year + (0 if is_test else 1))
                } if not is_test and request.effective_plan != 'enterprise' else None,
                'features': {
                    'auto_filing': 'auto_regulatory_filing' in request.plan_features,
                    'compliance_check': 'compliance_check' in request.plan_features,
                    'audit_trail': True
                }
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error submitting OSHA report: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to submit OSHA report',
            'code': 'OSHA_SUBMISSION_ERROR',
            'suggestion': 'Check your report data format. Use test submission first to validate',
            'test_endpoint': 'Same endpoint with test_submission=true parameter'
        }), 500

@app.route('/api/construction/regulatory/epa/submit', methods=['POST'])
@jwt_required
def submit_epa_report():
    """Submit EPA report"""
    try:
        # EPA reporting requires Business plan
        if 'epa_reporting' not in request.plan_features:
            return jsonify({
                'success': False,
                'error': 'EPA reporting not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'suggestion': 'Upgrade to Business or Enterprise plan for environmental compliance reporting',
                'alternative': 'Basic environmental tracking available in Pro plan'
            }), 403
        
        # Only environmental officers and compliance managers can submit EPA reports
        if request.user_type not in ['admin', 'compliance_officer', 'environmental_officer', 'safety_manager'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions for EPA reporting',
                'code': 'INSUFFICIENT_PERMISSIONS',
                'suggestion': 'EPA report submission requires environmental or compliance management permissions'
            }), 403
        
        data = request.get_json()
        
        if not data.get('stormwater_data'):
            return jsonify({
                'success': False,
                'error': 'Stormwater management data is required',
                'code': 'MISSING_STORMWATER_DATA',
                'suggestion': 'Provide monitoring data, inspection records, and corrective actions'
            }), 400
        
        # Check submission frequency limit
        if request.effective_plan != 'enterprise':
            max_quarterly_submissions = request.plan_limits.get('max_epa_submissions', 4)
            current_quarter = (datetime.utcnow().month - 1) // 3 + 1
            current_year = datetime.utcnow().year
            
            submissions_this_quarter = RegulatorySubmission.query.filter(
                RegulatorySubmission.user_id == request.user.id,
                RegulatorySubmission.agency == 'EPA',
                db.extract('year', RegulatorySubmission.submission_date) == current_year,
                db.extract('quarter', RegulatorySubmission.submission_date) == current_quarter
            ).count()
            
            if submissions_this_quarter >= max_quarterly_submissions:
                return jsonify({
                    'success': False,
                    'error': f'Quarterly EPA submission limit reached ({max_quarterly_submissions})',
                    'code': 'QUARTERLY_SUBMISSION_LIMIT',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited EPA submissions',
                    'current_usage': submissions_this_quarter,
                    'next_quarter_start': (datetime.utcnow().replace(month=((current_quarter) * 3), day=1)).isoformat()
                }), 403
        
        stormwater_data = data.get('stormwater_data', {})
        
        # Create EPA report document
        report = ConstructionDocument(
            user_id=request.user.id,
            title=f"EPA Stormwater Management Report - Q{(datetime.utcnow().month - 1) // 3 + 1} {datetime.utcnow().year}",
            description=f"EPA stormwater report for {data.get('reporting_period', 'Current Quarter')}\nSubmitted by: {request.user.email}",
            document_type='regulatory_report',
            status='submitted',
            metadata={
                'agency': 'EPA',
                'form_type': 'Stormwater',
                'reporting_period': data.get('reporting_period', f'Q{(datetime.utcnow().month - 1) // 3 + 1}'),
                'submitted_by': request.user.email,
                'user_role': request.user_type,
                'plan': request.effective_plan,
                'monitoring_data': stormwater_data.get('monitoring_results', {}),
                'corrective_actions': stormwater_data.get('corrective_actions', []),
                'submission_timestamp': datetime.utcnow().isoformat()
            }
        )
        db.session.add(report)
        
        # Record regulatory submission
        submission = RegulatorySubmission(
            user_id=request.user.id,
            agency='EPA',
            form_type='Stormwater',
            submission_date=datetime.utcnow(),
            document_id=report.id,
            status='submitted',
            is_test=False,
            plan=request.effective_plan
        )
        db.session.add(submission)
        db.session.commit()
        
        # Update usage counter
        if request.effective_plan != 'enterprise':
            request.user.epa_submissions_count = getattr(request.user, 'epa_submissions_count', 0) + 1
            db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'report_id': report.id,
                'submission_id': submission.id,
                'message': 'EPA stormwater report submitted successfully',
                'submission_date': datetime.utcnow().isoformat(),
                'next_deadline': (datetime.utcnow() + timedelta(days=90)).isoformat(),  # Quarterly requirement
                'verification_number': f"EPA-{submission.id:06d}",
                'compliance_status': 'pending_review',
                'usage_info': {
                    'submissions_this_quarter': submissions_this_quarter + 1,
                    'quarterly_limit': max_quarterly_submissions,
                    'remaining_submissions': max_quarterly_submissions - (submissions_this_quarter + 1)
                } if request.effective_plan != 'enterprise' else None,
                'environmental_features': {
                    'water_quality_monitoring': 'water_quality_monitoring' in request.plan_features,
                    'spill_prevention': 'spill_prevention' in request.plan_features,
                    'environmental_audits': 'environmental_audits' in request.plan_features
                }
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error submitting EPA report: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to submit EPA report',
            'code': 'EPA_SUBMISSION_ERROR',
            'suggestion': 'Ensure all required stormwater data is included. Contact environmental consultant if needed',
            'emergency_contact': 'env-compliance@safetyplatform.com'
        }), 500

@app.route('/api/construction/regulatory/deadlines', methods=['GET'])
@jwt_required
def get_regulatory_deadlines():
    """Get regulatory deadlines"""
    try:
        # Regulatory deadline tracking requires Pro plan
        if 'regulatory_deadlines' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Regulatory deadline tracking not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for regulatory compliance calendar',
                'basic_calendar': '/calendar/regulatory'
            }), 403
        
        current_date = datetime.utcnow()
        
        # Calculate deadlines based on current date and plan features
        deadlines = [
            {
                'agency': 'OSHA',
                'report_type': '300A Summary',
                'deadline': (current_date.replace(month=3, day=2)).isoformat(),  # March 2nd
                'frequency': 'annual',
                'status': 'upcoming',
                'days_remaining': max(0, (current_date.replace(month=3, day=2) - current_date).days),
                'penalty': '$13,653 per violation',
                'submission_method': 'electronic' if 'electronic_filing' in request.plan_features else 'paper',
                'preparation_time_estimate': '2 weeks'
            },
            {
                'agency': 'EPA',
                'report_type': 'Stormwater Management',
                'deadline': (current_date.replace(day=1) + timedelta(days=90)).isoformat(),  # Next quarter
                'frequency': 'quarterly',
                'status': 'upcoming',
                'days_remaining': max(0, ((current_date.replace(day=1) + timedelta(days=90)) - current_date).days),
                'penalty': '$56,460 per day of violation',
                'submission_method': 'electronic',
                'preparation_time_estimate': '1 week'
            },
            {
                'agency': 'State',
                'report_type': 'Safety Compliance',
                'deadline': (current_date + timedelta(days=15)).isoformat(),  # 15 days
                'frequency': 'monthly',
                'status': 'urgent' if (current_date + timedelta(days=15) - current_date).days <= 7 else 'upcoming',
                'days_remaining': 15,
                'penalty': 'Varies by state',
                'submission_method': 'electronic' if 'state_portal' in request.plan_features else 'paper',
                'preparation_time_estimate': '3 days'
            }
        ]
        
        # Add custom deadlines for Business/Enterprise plans
        if request.effective_plan in ['business', 'enterprise']:
            deadlines.extend([
                {
                    'agency': 'DOT',
                    'report_type': 'Hazardous Materials',
                    'deadline': (current_date + timedelta(days=45)).isoformat(),
                    'frequency': 'quarterly',
                    'status': 'upcoming',
                    'days_remaining': 45,
                    'penalty': '$78,376 per violation',
                    'submission_method': 'electronic',
                    'preparation_time_estimate': '2 weeks'
                },
                {
                    'agency': 'Local',
                    'report_type': 'Building Permits',
                    'deadline': (current_date + timedelta(days=30)).isoformat(),
                    'frequency': 'monthly',
                    'status': 'upcoming',
                    'days_remaining': 30,
                    'penalty': 'Project delays',
                    'submission_method': 'electronic' if 'local_portal' in request.plan_features else 'in_person',
                    'preparation_time_estimate': '1 week'
                }
            ])
        
        # Sort by urgency
        deadlines.sort(key=lambda x: x['days_remaining'])
        
        # Calculate overall compliance risk
        urgent_deadlines = [d for d in deadlines if d['status'] == 'urgent']
        compliance_risk = 'high' if len(urgent_deadlines) > 2 else 'medium' if len(urgent_deadlines) > 0 else 'low'
        
        return jsonify({
            'success': True,
            'data': {
                'deadlines': deadlines,
                'summary': {
                    'total_deadlines': len(deadlines),
                    'urgent_count': len(urgent_deadlines),
                    'compliance_risk': compliance_risk,
                    'next_deadline': deadlines[0]['agency'] if deadlines else None,
                    'days_to_next': deadlines[0]['days_remaining'] if deadlines else None
                },
                'current_date': current_date.isoformat(),
                'plan_features': {
                    'deadline_alerts': 'deadline_alerts' in request.plan_features,
                    'auto_reminders': 'auto_reminders' in request.plan_features,
                    'compliance_dashboard': 'compliance_dashboard' in request.plan_features
                },
                'integration_options': {
                    'calendar_sync': 'calendar_sync' in request.plan_features,
                    'team_notifications': 'team_notifications' in request.plan_features,
                    'mobile_alerts': 'mobile_alerts' in request.plan_features
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching regulatory deadlines: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch regulatory deadlines',
            'code': 'DEADLINES_FETCH_ERROR',
            'suggestion': 'Try refreshing the page. Manual deadline tracking recommended as backup',
            'backup_resource': 'https://www.osha.gov/regulatory-compliance'
        }), 500

