@app.route('/api/construction/communication/suggestions', methods=['POST'])
@jwt_required
def submit_safety_suggestion():
    """Submit safety suggestion"""
    try:
        # Safety suggestion system available in all plans
        # Check submission limits for free plan
        if request.effective_plan == 'free':
            max_monthly_suggestions = request.plan_limits.get('max_safety_suggestions', 5)
            current_month = datetime.utcnow().month
            current_year = datetime.utcnow().year
            suggestions_this_month = SafetySuggestion.query.filter(
                SafetySuggestion.user_id == request.user.id,
                db.extract('year', SafetySuggestion.created_at) == current_year,
                db.extract('month', SafetySuggestion.created_at) == current_month
            ).count()
            
            if suggestions_this_month >= max_monthly_suggestions:
                return jsonify({
                    'success': False,
                    'error': f'Monthly safety suggestion limit reached ({max_monthly_suggestions})',
                    'code': 'MONTHLY_SUGGESTION_LIMIT',
                    'suggestion': 'Upgrade to Pro plan for unlimited safety suggestions',
                    'current_usage': suggestions_this_month,
                    'reset_date': (datetime.utcnow().replace(day=1) + timedelta(days=32)).replace(day=1).isoformat()
                }), 403
        
        data = request.get_json()
        
        if not data.get('description'):
            return jsonify({
                'success': False,
                'error': 'Suggestion description is required',
                'code': 'MISSING_DESCRIPTION',
                'suggestion': 'Provide detailed description of your safety improvement idea'
            }), 400
        
        # Create safety suggestion
        suggestion = SafetySuggestion(
            user_id=request.user.id,
            title=data.get('title', 'Safety Suggestion'),
            description=data.get('description', ''),
            category=data.get('category', 'general'),
            priority=data.get('priority', 'medium'),
            location=data.get('location'),
            estimated_impact=data.get('estimated_impact'),
            implementation_cost=data.get('implementation_cost'),
            status='submitted',
            metadata={
                'submitted_by': request.user.email,
                'user_role': request.user_type,
                'plan': request.effective_plan
            }
        )
        db.session.add(suggestion)
        db.session.commit()
        
        # Update usage counter for free plan
        if request.effective_plan == 'free':
            request.user.monthly_safety_suggestions = getattr(request.user, 'monthly_safety_suggestions', 0) + 1
            db.session.commit()
        
        # Notify safety managers if available
        if 'suggestion_notifications' in request.plan_features:
            # Logic to notify safety managers
            pass
        
        return jsonify({
            'success': True,
            'data': {
                'suggestion_id': suggestion.id,
                'suggestion_number': f"SS-{suggestion.id:06d}",
                'message': 'Safety suggestion submitted successfully',
                'review_timeline': '2-3 business days',
                'tracking_info': {
                    'status': suggestion.status,
                    'submitted_at': suggestion.created_at.isoformat(),
                    'assigned_to': 'Safety Committee' if 'suggestion_workflow' in request.plan_features else 'Safety Manager',
                    'expected_response': (datetime.utcnow() + timedelta(days=3)).isoformat()
                },
                'usage_info': {
                    'suggestions_this_month': suggestions_this_month + 1,
                    'monthly_limit': max_monthly_suggestions,
                    'remaining_suggestions': max_monthly_suggestions - (suggestions_this_month + 1)
                } if request.effective_plan == 'free' else {'unlimited': True},
                'features': {
                    'anonymous_submission': 'anonymous_suggestions' in request.plan_features,
                    'feedback_tracking': 'suggestion_feedback' in request.plan_features,
                    'reward_system': 'suggestion_rewards' in request.plan_features
                }
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error submitting safety suggestion: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to submit safety suggestion',
            'code': 'SUGGESTION_SUBMISSION_ERROR',
            'suggestion': 'Try again with a shorter description. Contact safety team directly if urgent',
            'direct_contact': 'safety-team@company.com'
        }), 500

@app.route('/api/construction/communication/alerts', methods=['POST'])
@jwt_required
def publish_safety_alert():
    """Publish safety alert"""
    try:
        # Safety alerts require at least Pro plan
        if 'safety_alerts' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Safety alert system not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for safety communication and alert systems',
                'emergency_protocol': '/emergency/procedures'
            }), 403
        
        # Only safety managers, supervisors, and admins can publish alerts
        if request.user_type not in ['admin', 'safety_manager', 'supervisor', 'emergency_coordinator'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions to publish safety alerts',
                'code': 'INSUFFICIENT_PERMISSIONS',
                'suggestion': 'Only authorized safety personnel can publish alerts'
            }), 403
        
        data = request.get_json()
        
        if not data.get('message'):
            return jsonify({
                'success': False,
                'error': 'Alert message is required',
                'code': 'MISSING_ALERT_MESSAGE',
                'suggestion': 'Provide clear and concise alert message for all recipients'
            }), 400
        
        # Check alert frequency limits
        if request.effective_plan != 'enterprise':
            max_daily_alerts = request.plan_limits.get('max_daily_alerts', 10)
            today = datetime.utcnow().date()
            alerts_today = SafetyAlert.query.filter(
                SafetyAlert.user_id == request.user.id,
                db.func.date(SafetyAlert.created_at) == today
            ).count()
            
            if alerts_today >= max_daily_alerts:
                return jsonify({
                    'success': False,
                    'error': f'Daily safety alert limit reached ({max_daily_alerts})',
                    'code': 'DAILY_ALERT_LIMIT',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited safety alerts',
                    'current_usage': alerts_today,
                    'reset_time': (datetime.utcnow() + timedelta(days=1)).replace(hour=0, minute=0, second=0).isoformat()
                }), 403
        
        # Create safety alert
        alert = SafetyAlert(
            user_id=request.user.id,
            title=data.get('title', 'Safety Alert'),
            message=data.get('message', ''),
            alert_type=data.get('alert_type', 'general'),
            priority=data.get('priority', 'high'),
            target_audience=data.get('target_audience', 'all_construction_workers'),
            affected_areas=data.get('affected_areas', []),
            actions_required=data.get('actions_required', []),
            expires_at=datetime.utcnow() + timedelta(hours=data.get('duration_hours', 24)),
            status='active',
            metadata={
                'published_by': request.user.email,
                'user_role': request.user_type,
                'plan': request.effective_plan,
                'communication_channels': data.get('channels', ['app', 'email', 'sms']),
                'acknowledgement_required': data.get('acknowledgement_required', False)
            }
        )
        db.session.add(alert)
        db.session.commit()
        
        # Trigger notifications based on plan features
        notification_channels = []
        if 'push_notifications' in request.plan_features:
            notification_channels.append('push')
        if 'sms_alerts' in request.plan_features:
            notification_channels.append('sms')
        if 'email_broadcast' in request.plan_features:
            notification_channels.append('email')
        
        # Update usage counter
        if request.effective_plan != 'enterprise':
            request.user.daily_safety_alerts = getattr(request.user, 'daily_safety_alerts', 0) + 1
            db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'alert_id': alert.id,
                'alert_number': f"ALERT-{alert.id:06d}",
                'message': 'Safety alert published successfully',
                'alert_details': {
                    'priority': alert.priority,
                    'audience': alert.target_audience,
                    'expires_at': alert.expires_at.isoformat(),
                    'status': alert.status
                },
                'notification_status': {
                    'channels_used': notification_channels,
                    'recipients_count': 'Calculating...',
                    'delivery_status': 'in_progress'
                },
                'usage_info': {
                    'alerts_today': alerts_today + 1,
                    'daily_limit': max_daily_alerts,
                    'remaining_alerts': max_daily_alerts - (alerts_today + 1)
                } if request.effective_plan != 'enterprise' else {'unlimited': True},
                'communication_features': {
                    'emergency_broadcast': 'emergency_broadcast' in request.plan_features,
                    'two_way_communication': 'two_way_communication' in request.plan_features,
                    'acknowledgement_tracking': 'acknowledgement_tracking' in request.plan_features
                }
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error publishing safety alert: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to publish safety alert',
            'code': 'ALERT_PUBLICATION_ERROR',
            'suggestion': 'Use alternative communication method for urgent alerts',
            'emergency_contact': 'emergency@safetyplatform.com'
        }), 500

    def to_dict(self):
        # Convert value based on data type
        value = self.setting_value
        if self.data_type == 'integer':
            value = int(value) if value else 0
        elif self.data_type == 'float':
            value = float(value) if value else 0.0
        elif self.data_type == 'boolean':
            value = value.lower() == 'true' if value else False
        elif self.data_type == 'json':
            try:
                value = json.loads(value) if value else {}
            except:
                value = {}
        
        return {
            'id': self.id,
            'key': self.setting_key,
            'value': value,
            'data_type': self.data_type,
            'category': self.category,
            'description': self.description,
            'is_public': self.is_public,
            'is_encrypted': self.is_encrypted,
            'min_value': self.min_value,
            'max_value': self.max_value,
            'allowed_values': json.loads(self.allowed_values) if self.allowed_values else [],
            'updated_by': self.updated_by,
            'updated_by_name': self.updater.name if self.updater else None,
            'created_at': self.created_at.isoformat(),
            'updated_at': self.updated_at.isoformat()
        }
    
    @classmethod
    def get_setting(cls, key, default=None):
        """Get a system setting by key"""
        setting = cls.query.filter_by(setting_key=key).first()
        if setting:
            return setting.to_dict()['value']
        return default
    
    @classmethod
    def set_setting(cls, key, value, data_type='string', category='general', description=None, 
                   is_public=False, is_encrypted=False, min_value=None, max_value=None, 
                   allowed_values=None, updated_by=None):
        """Set a system setting"""
        setting = cls.query.filter_by(setting_key=key).first()
        
        # Convert value to string based on data type
        if data_type == 'boolean':
            value_str = 'true' if value else 'false'
        elif data_type == 'json':
            value_str = json.dumps(value) if value else '{}'
        else:
            value_str = str(value)
        
        if setting:
            # Update existing setting
            setting.setting_value = value_str
            setting.data_type = data_type
            setting.category = category
            setting.description = description
            setting.is_public = is_public
            setting.is_encrypted = is_encrypted
            setting.min_value = min_value
            setting.max_value = max_value
            setting.allowed_values = json.dumps(allowed_values) if allowed_values else None
            setting.updated_by = updated_by
            setting.updated_at = datetime.utcnow()
        else:
            # Create new setting
            setting = cls(
                setting_key=key,
                setting_value=value_str,
                data_type=data_type,
                category=category,
                description=description,
                is_public=is_public,
                is_encrypted=is_encrypted,
                min_value=min_value,
                max_value=max_value,
                allowed_values=json.dumps(allowed_values) if allowed_values else None,
                updated_by=updated_by
            )
            db.session.add(setting)
        
        db.session.commit()
        return setting

