@app.route('/api/construction/admin/settings', methods=['GET'])
@jwt_required
def get_system_settings():
    """Get all system settings"""
    try:
        # System settings access requires admin or platform owner
        if request.user_type not in ['admin', 'platform_owner', 'super_admin'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Administrative access required',
                'code': 'ADMIN_ACCESS_REQUIRED',
                'suggestion': 'System settings are only accessible to administrators'
            }), 403
        
        # Check if user has system configuration permissions
        if not request.is_platform_owner:
            # Regular admins can only see non-sensitive settings
            restricted_categories = ['security', 'billing', 'api_keys', 'encryption']
        else:
            restricted_categories = []
        
        category = request.args.get('category')
        is_public = request.args.get('is_public')
        show_sensitive = request.args.get('show_sensitive', 'false').lower() == 'true'
        
        query = SystemSettings.query
        
        if category:
            query = query.filter_by(category=category)
        if is_public:
            query = query.filter_by(is_public=(is_public.lower() == 'true'))
        
        # Filter out sensitive categories for non-platform owners
        if not request.is_platform_owner and not show_sensitive:
            query = query.filter(~SystemSettings.category.in_(restricted_categories))
        
        settings = query.order_by(SystemSettings.category, SystemSettings.setting_key).all()
        
        # Group settings by category for better organization
        settings_by_category = {}
        for setting in settings:
            category_name = setting.category
            if category_name not in settings_by_category:
                settings_by_category[category_name] = []
            
            setting_dict = setting.to_dict()
            
            # Mask sensitive values for non-platform owners
            if setting.is_encrypted and not request.is_platform_owner:
                setting_dict['value'] = '••••••••'
                setting_dict['is_masked'] = True
            
            # Add permission level
            if setting.category in restricted_categories:
                setting_dict['permission_required'] = 'platform_owner'
            elif setting.is_public:
                setting_dict['permission_required'] = 'view_only'
            else:
                setting_dict['permission_required'] = 'admin'
            
            settings_by_category[category_name].append(setting_dict)
        
        # Get plan-specific settings limits
        plan_settings_limits = {
            'free': {'max_custom_settings': 10, 'can_export': False},
            'pro': {'max_custom_settings': 50, 'can_export': True},
            'business': {'max_custom_settings': 200, 'can_export': True},
            'enterprise': {'max_custom_settings': -1, 'can_export': True}  # -1 means unlimited
        }
        
        current_plan_limits = plan_settings_limits.get(request.effective_plan, plan_settings_limits['free'])
        
        return jsonify({
            'success': True,
            'data': {
                'settings_by_category': settings_by_category,
                'total_settings': len(settings),
                'categories': list(settings_by_category.keys()),
                'access_level': {
                    'user_role': request.user_type,
                    'is_platform_owner': request.is_platform_owner,
                    'can_modify_security': request.is_platform_owner,
                    'can_view_sensitive': request.is_platform_owner or show_sensitive
                },
                'plan_limits': current_plan_limits,
                'export_available': current_plan_limits['can_export'],
                'custom_settings_count': SystemSettings.query.filter_by(category='custom').count()
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching system settings: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch system settings',
            'code': 'SETTINGS_FETCH_ERROR',
            'suggestion': 'Try again with more specific category filters'
        }), 500

@app.route('/api/construction/admin/settings', methods=['PUT'])
@jwt_required
def update_system_settings():
    """Update system settings"""
    try:
        # Only platform owners and super admins can update system settings
        if not request.is_platform_owner and request.user_type not in ['super_admin', 'platform_owner']:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions',
                'code': 'INSUFFICIENT_PERMISSIONS',
                'suggestion': 'Only platform owners can modify system settings'
            }), 403
        
        data = request.get_json()
        settings = data.get('settings', [])
        dry_run = data.get('dry_run', False)
        
        if not settings:
            return jsonify({
                'success': False,
                'error': 'No settings provided',
                'code': 'NO_SETTINGS_PROVIDED',
                'suggestion': 'Provide settings array with key-value pairs'
            }), 400
        
        # Check batch update limit
        max_batch_updates = {
            'free': 5,
            'pro': 20,
            'business': 50,
            'enterprise': -1  # Unlimited
        }.get(request.effective_plan, 5)
        
        if max_batch_updates > 0 and len(settings) > max_batch_updates:
            return jsonify({
                'success': False,
                'error': f'Batch update limit exceeded ({max_batch_updates})',
                'code': 'BATCH_UPDATE_LIMIT',
                'suggestion': f'Break updates into batches of {max_batch_updates} or fewer',
                'current_count': len(settings)
            }), 400
        
        updated_settings = []
        validation_errors = []
        restart_required = False
        warnings = []
        
        for setting_data in settings:
            key = setting_data.get('key')
            value = setting_data.get('value')
            
            if not key:
                validation_errors.append({'setting': 'Unknown', 'error': 'Setting key is required'})
                continue
            
            # Get existing setting to validate
            existing_setting = SystemSettings.query.filter_by(setting_key=key).first()
            if not existing_setting:
                validation_errors.append({'setting': key, 'error': 'Setting not found'})
                continue
            
            # Check permission for this setting category
            if existing_setting.category in ['security', 'billing', 'api_keys'] and not request.is_platform_owner:
                validation_errors.append({
                    'setting': key, 
                    'error': 'Insufficient permissions for this setting category',
                    'required_role': 'platform_owner'
                })
                continue
            
            # Validate value based on data type
            try:
                # Type validation
                if existing_setting.data_type == 'integer':
                    try:
                        int_value = int(value)
                        value = str(int_value)  # Store as string in database
                    except (ValueError, TypeError):
                        validation_errors.append({'setting': key, 'error': 'Value must be an integer'})
                        continue
                        
                elif existing_setting.data_type == 'float':
                    try:
                        float_value = float(value)
                        value = str(float_value)
                    except (ValueError, TypeError):
                        validation_errors.append({'setting': key, 'error': 'Value must be a number'})
                        continue
                        
                elif existing_setting.data_type == 'boolean':
                    if str(value).lower() not in ['true', 'false', '1', '0']:
                        validation_errors.append({'setting': key, 'error': 'Value must be a boolean (true/false)'})
                        continue
                    value = 'true' if str(value).lower() in ['true', '1'] else 'false'
                    
                elif existing_setting.data_type == 'json':
                    try:
                        # Validate JSON
                        json.loads(value if isinstance(value, str) else json.dumps(value))
                    except json.JSONDecodeError:
                        validation_errors.append({'setting': key, 'error': 'Invalid JSON format'})
                        continue
                
                # Validate min/max values
                if existing_setting.min_value:
                    min_val = float(existing_setting.min_value) if existing_setting.data_type in ['integer', 'float'] else existing_setting.min_value
                    try:
                        if existing_setting.data_type in ['integer', 'float'] and float(value) < min_val:
                            validation_errors.append({'setting': key, 'error': f'Value must be at least {min_val}'})
                            continue
                    except ValueError:
                        validation_errors.append({'setting': key, 'error': 'Value must be a number for min/max validation'})
                        continue
                
                if existing_setting.max_value:
                    max_val = float(existing_setting.max_value) if existing_setting.data_type in ['integer', 'float'] else existing_setting.max_value
                    try:
                        if existing_setting.data_type in ['integer', 'float'] and float(value) > max_val:
                            validation_errors.append({'setting': key, 'error': f'Value must be at most {max_val}'})
                            continue
                    except ValueError:
                        validation_errors.append({'setting': key, 'error': 'Value must be a number for min/max validation'})
                        continue
                
                # Validate allowed values
                if existing_setting.allowed_values:
                    try:
                        allowed_values = json.loads(existing_setting.allowed_values)
                        if value not in allowed_values:
                            validation_errors.append({
                                'setting': key, 
                                'error': f'Value must be one of: {", ".join(map(str, allowed_values))}'
                            })
                            continue
                    except json.JSONDecodeError:
                        warnings.append({'setting': key, 'warning': 'Allowed values format invalid, skipping validation'})
                
                # Check if value is actually changing
                current_value = existing_setting.value
                if current_value == value:
                    warnings.append({'setting': key, 'warning': 'Value unchanged, skipping update'})
                    continue
                
                # Check for restart-required settings
                if key in ['session_timeout_minutes', 'api_rate_limit', 'cache_duration_minutes']:
                    restart_required = True
                
                # For dry run, just validate
                if dry_run:
                    updated_settings.append({
                        'key': key,
                        'old_value': current_value,
                        'new_value': value,
                        'valid': True
                    })
                else:
                    # Update the setting
                    existing_setting.value = value
                    existing_setting.updated_at = datetime.utcnow()
                    existing_setting.updated_by = request.user.id
                    
                    # Create audit log
                    audit_log = SettingsAuditLog(
                        setting_key=key,
                        old_value=current_value,
                        new_value=value,
                        changed_by=request.user.id,
                        change_reason=setting_data.get('reason', 'Manual update'),
                        ip_address=request.remote_addr
                    )
                    db.session.add(audit_log)
                    
                    updated_settings.append(key)
                    
            except Exception as validation_error:
                validation_errors.append({
                    'setting': key,
                    'error': f'Validation error: {str(validation_error)}'
                })
        
        if validation_errors:
            return jsonify({
                'success': False,
                'error': 'Validation failed for some settings',
                'code': 'SETTINGS_VALIDATION_ERROR',
                'validation_errors': validation_errors,
                'warnings': warnings if warnings else None
            }), 400
        
        if not dry_run:
            db.session.commit()
            
            # Log the batch update
            if updated_settings:
                batch_log = SettingsBatchLog(
                    user_id=request.user.id,
                    settings_updated=len(updated_settings),
                    settings_list=json.dumps(updated_settings),
                    restart_required=restart_required,
                    plan=request.effective_plan
                )
                db.session.add(batch_log)
                db.session.commit()
        
        return jsonify({
            'success': True,
            'data': {
                'message': f'Validated {len(settings)} settings, would update {len(updated_settings)}' if dry_run else f'Successfully updated {len(updated_settings)} settings',
                'updated_settings': updated_settings,
                'restart_required': restart_required,
                'dry_run': dry_run,
                'warnings': warnings if warnings else None,
                'next_steps': [
                    'Review changes in audit log',
                    'Test affected functionality' if updated_settings else None,
                    'Schedule maintenance window for restart' if restart_required else None
                ]
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating system settings: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to update system settings',
            'code': 'SETTINGS_UPDATE_ERROR',
            'suggestion': 'Try updating settings individually or contact support'
        }), 500

@app.route('/api/construction/admin/settings/<string:setting_key>', methods=['GET'])
@jwt_required
def get_system_setting(setting_key):
    """Get a specific system setting"""
    try:
        # Check if user can access this setting
        setting = SystemSettings.query.filter_by(setting_key=setting_key).first()
        
        if not setting:
            return jsonify({
                'success': False,
                'error': 'Setting not found',
                'code': 'SETTING_NOT_FOUND',
                'suggestion': 'Verify the setting key exists'
            }), 404
        
        # Check permissions for sensitive settings
        if setting.category in ['security', 'billing', 'api_keys'] and not request.is_platform_owner:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions',
                'code': 'SETTING_ACCESS_DENIED',
                'suggestion': 'This setting requires platform owner access',
                'category': setting.category
            }), 403
        
        setting_data = setting.to_dict()
        
        # Mask sensitive/encrypted values
        if setting.is_encrypted and not request.is_platform_owner:
            setting_data['value'] = '••••••••'
            setting_data['is_masked'] = True
        
        # Add change history if available
        if request.effective_plan in ['business', 'enterprise']:
            change_history = SettingsAuditLog.query.filter_by(setting_key=setting_key)\
                .order_by(SettingsAuditLog.changed_at.desc())\
                .limit(5).all()
            
            setting_data['change_history'] = [{
                'old_value': log.old_value if not setting.is_encrypted or request.is_platform_owner else '••••••••',
                'new_value': log.new_value if not setting.is_encrypted or request.is_platform_owner else '••••••••',
                'changed_by': User.query.get(log.changed_by).email if User.query.get(log.changed_by) else f'User {log.changed_by}',
                'changed_at': log.changed_at.isoformat(),
                'reason': log.change_reason
            } for log in change_history]
        
        return jsonify({
            'success': True,
            'data': {
                'setting': setting_data,
                'access_info': {
                    'can_modify': request.is_platform_owner or setting.category not in ['security', 'billing'],
                    'requires_restart': setting_key in ['session_timeout_minutes', 'api_rate_limit'],
                    'backup_available': request.effective_plan in ['business', 'enterprise']
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching system setting: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch system setting',
            'code': 'SETTING_FETCH_ERROR',
            'suggestion': 'Try accessing through the settings list endpoint'
        }), 500

@app.route('/api/construction/admin/settings/<string:setting_key>', methods=['PUT'])
@jwt_required
def update_system_setting(setting_key):
    """Update a specific system setting"""
    try:
        # Only platform owners and super admins can update settings
        if not request.is_platform_owner and request.user_type not in ['super_admin', 'platform_owner']:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions',
                'code': 'INSUFFICIENT_PERMISSIONS',
                'suggestion': 'Only platform owners can modify system settings'
            }), 403
        
        data = request.get_json()
        value = data.get('value')
        change_reason = data.get('reason', 'Manual update')
        dry_run = data.get('dry_run', False)
        
        if value is None:
            return jsonify({
                'success': False,
                'error': 'Value is required',
                'code': 'MISSING_VALUE',
                'suggestion': 'Provide a value for the setting'
            }), 400
        
        setting = SystemSettings.query.filter_by(setting_key=setting_key).first()
        if not setting:
            return jsonify({
                'success': False,
                'error': 'Setting not found',
                'code': 'SETTING_NOT_FOUND',
                'suggestion': 'Verify the setting key exists'
            }), 404
        
        # Check permissions for sensitive settings
        if setting.category in ['security', 'billing', 'api_keys'] and not request.is_platform_owner:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions for this setting',
                'code': 'SETTING_ACCESS_DENIED',
                'suggestion': 'This setting requires platform owner access'
            }), 403
        
        # Validate value
        validation_result = validate_setting_value(setting, value)
        if not validation_result['valid']:
            return jsonify({
                'success': False,
                'error': 'Validation failed',
                'code': 'SETTING_VALIDATION_ERROR',
                'validation_errors': validation_result['errors']
            }), 400
        
        # Check if value is changing
        if setting.value == str(value):
            return jsonify({
                'success': True,
                'data': {
                    'message': 'Setting value unchanged',
                    'setting_key': setting_key,
                    'current_value': setting.value
                }
            }), 200
        
        old_value = setting.value
        
        if dry_run:
            return jsonify({
                'success': True,
                'data': {
                    'message': 'Dry run successful',
                    'setting_key': setting_key,
                    'old_value': old_value,
                    'new_value': value,
                    'would_restart': setting_key in ['session_timeout_minutes', 'api_rate_limit'],
                    'validation_passed': True
                }
            }), 200
        
        # Update the setting
        setting.value = str(value)
        setting.updated_at = datetime.utcnow()
        setting.updated_by = request.user.id
        
        # Create audit log
        audit_log = SettingsAuditLog(
            setting_key=setting_key,
            old_value=old_value,
            new_value=value,
            changed_by=request.user.id,
            change_reason=change_reason,
            ip_address=request.remote_addr
        )
        db.session.add(audit_log)
        
        db.session.commit()
        
        # Check if restart is required
        restart_required = setting_key in ['session_timeout_minutes', 'api_rate_limit', 'cache_duration_minutes']
        
        return jsonify({
            'success': True,
            'data': {
                'setting': setting.to_dict(),
                'message': 'Setting updated successfully',
                'audit_log_id': audit_log.id,
                'restart_required': restart_required,
                'next_steps': [
                    'Verify the change works as expected',
                    'Update documentation if needed',
                    'Notify team members of the change' if setting.is_public else None,
                    'Schedule maintenance window for restart' if restart_required else None
                ]
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating system setting: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to update system setting',
            'code': 'SETTING_UPDATE_ERROR',
            'suggestion': 'Check the setting constraints and try again'
        }), 500

@app.route('/api/construction/admin/settings/categories', methods=['GET'])
@jwt_required
def get_setting_categories():
    """Get all setting categories"""
    try:
        # System settings categories require admin access
        if request.user_type not in ['admin', 'platform_owner', 'super_admin'] and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Administrative access required',
                'code': 'ADMIN_ACCESS_REQUIRED',
                'suggestion': 'Setting categories are only accessible to administrators'
            }), 403
        
        # Get categories with counts
        categories = db.session.query(
            SystemSettings.category,
            db.func.count(SystemSettings.id).label('count'),
            db.func.max(SystemSettings.updated_at).label('last_updated')
        ).group_by(SystemSettings.category).all()
        
        # Filter sensitive categories for non-platform owners
        if not request.is_platform_owner:
            sensitive_categories = ['security', 'billing', 'api_keys', 'encryption']
            categories = [c for c in categories if c[0] not in sensitive_categories]
        
        category_list = []
        for category, count, last_updated in categories:
            category_info = {
                'name': category,
                'setting_count': count,
                'last_updated': last_updated.isoformat() if last_updated else None
            }
            
            # Add description for common categories
            category_descriptions = {
                'general': 'General system settings and preferences',
                'security': 'Security and authentication settings',
                'billing': 'Billing and subscription settings',
                'api': 'API and integration settings',
                'notifications': 'Notification and alert settings',
                'compliance': 'Compliance and regulatory settings',
                'training': 'Training and education settings',
                'analytics': 'Analytics and reporting settings',
                'custom': 'Custom user-defined settings'
            }
            
            if category in category_descriptions:
                category_info['description'] = category_descriptions[category]
            
            # Add permission level
            if category in ['security', 'billing', 'api_keys']:
                category_info['permission_required'] = 'platform_owner'
            else:
                category_info['permission_required'] = 'admin'
            
            category_list.append(category_info)
        
        # Sort categories
        category_list.sort(key=lambda x: x['name'])
        
        return jsonify({
            'success': True,
            'data': {
                'categories': category_list,
                'total_categories': len(category_list),
                'access_level': {
                    'can_view_all': request.is_platform_owner,
                    'sensitive_categories_hidden': not request.is_platform_owner
                }
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching setting categories: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to fetch setting categories',
            'code': 'CATEGORIES_FETCH_ERROR',
            'suggestion': 'Try refreshing the page or contact support'
        }), 500

@app.route('/api/construction/admin/settings/reset/<string:setting_key>', methods=['POST'])
@jwt_required
def reset_system_setting(setting_key):
    """Reset a system setting to default value"""
    try:
        # Only platform owners and super admins can reset settings
        if not request.is_platform_owner and request.user_type not in ['super_admin', 'platform_owner']:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions',
                'code': 'INSUFFICIENT_PERMISSIONS',
                'suggestion': 'Only platform owners can reset system settings'
            }), 403
        
        # Get default values based on plan
        default_settings = get_default_settings(request.effective_plan)
        
        if setting_key not in default_settings:
            return jsonify({
                'success': False,
                'error': 'No default value found for this setting',
                'code': 'NO_DEFAULT_FOUND',
                'suggestion': 'Check the setting key or contact support'
            }), 404
        
        setting = SystemSettings.query.filter_by(setting_key=setting_key).first()
        if not setting:
            return jsonify({
                'success': False,
                'error': 'Setting not found',
                'code': 'SETTING_NOT_FOUND',
                'suggestion': 'Verify the setting key exists'
            }), 404
        
        # Check permissions for sensitive settings
        if setting.category in ['security', 'billing', 'api_keys'] and not request.is_platform_owner:
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions for this setting',
                'code': 'SETTING_ACCESS_DENIED',
                'suggestion': 'This setting requires platform owner access'
            }), 403
        
        old_value = setting.value
        default_value = default_settings[setting_key]
        
        # Validate the default value
        validation_result = validate_setting_value(setting, default_value)
        if not validation_result['valid']:
            return jsonify({
                'success': False,
                'error': 'Default value validation failed',
                'code': 'DEFAULT_VALIDATION_ERROR',
                'validation_errors': validation_result['errors']
            }), 400
        
        # Reset to default
        setting.value = str(default_value)
        setting.updated_at = datetime.utcnow()
        setting.updated_by = request.user.id
        
        # Create audit log
        audit_log = SettingsAuditLog(
            setting_key=setting_key,
            old_value=old_value,
            new_value=default_value,
            changed_by=request.user.id,
            change_reason='Reset to default',
            ip_address=request.remote_addr
        )
        db.session.add(audit_log)
        
        db.session.commit()
        
        # Check if restart is required
        restart_required = setting_key in ['session_timeout_minutes', 'api_rate_limit', 'cache_duration_minutes']
        
        return jsonify({
            'success': True,
            'data': {
                'message': f'Setting {setting_key} reset to default value',
                'setting_key': setting_key,
                'old_value': old_value,
                'default_value': default_value,
                'audit_log_id': audit_log.id,
                'restart_required': restart_required,
                'plan_specific_default': True if request.effective_plan in default_settings.get('_plan_specific', []) else False
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error resetting system setting: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to reset system setting',
            'code': 'SETTING_RESET_ERROR',
            'suggestion': 'Try updating manually or contact support'
        }), 500

# Helper functions
def validate_setting_value(setting, value):
    """Validate a setting value against its constraints"""
    errors = []
    
    try:
        # Type validation
        if setting.data_type == 'integer':
            try:
                int(value)
            except (ValueError, TypeError):
                errors.append('Value must be an integer')
                
        elif setting.data_type == 'float':
            try:
                float(value)
            except (ValueError, TypeError):
                errors.append('Value must be a number')
                
        elif setting.data_type == 'boolean':
            if str(value).lower() not in ['true', 'false', '1', '0']:
                errors.append('Value must be a boolean (true/false)')
                
        elif setting.data_type == 'json':
            try:
                json.loads(value if isinstance(value, str) else json.dumps(value))
            except json.JSONDecodeError:
                errors.append('Invalid JSON format')
        
        # Min/max validation
        if not errors and setting.min_value:
            try:
                if setting.data_type in ['integer', 'float'] and float(value) < float(setting.min_value):
                    errors.append(f'Value must be at least {setting.min_value}')
            except ValueError:
                errors.append('Value must be a number for min validation')
        
        if not errors and setting.max_value:
            try:
                if setting.data_type in ['integer', 'float'] and float(value) > float(setting.max_value):
                    errors.append(f'Value must be at most {setting.max_value}')
            except ValueError:
                errors.append('Value must be a number for max validation')
        
        # Allowed values validation
        if not errors and setting.allowed_values:
            try:
                allowed_values = json.loads(setting.allowed_values)
                if value not in allowed_values:
                    errors.append(f'Value must be one of: {", ".join(map(str, allowed_values))}')
            except json.JSONDecodeError:
                # Skip allowed values validation if format is invalid
                pass
    
    except Exception as e:
        errors.append(f'Validation error: {str(e)}')
    
    return {'valid': len(errors) == 0, 'errors': errors}

def get_default_settings(plan):
    """Get default settings based on plan"""
    base_defaults = {
        # General settings
        'system_name': 'Safety Construction Platform',
        'timezone': 'UTC',
        'date_format': 'YYYY-MM-DD',
        
        # Security settings
        'session_timeout_minutes': 60,
        'password_min_length': 8,
        'max_login_attempts': 5,
        'mfa_required': False,
        
        # AI settings
        'ai_confidence_threshold': 0.7,
        'high_risk_threshold': 0.7,
        'medium_risk_threshold': 0.4,
        
        # Compliance settings
        'safety_audit_frequency_days': 30,
        'training_refresh_days': 365,
        'equipment_inspection_frequency_days': 30,
        
        # Notification settings
        'email_notifications_enabled': True,
        'push_notifications_enabled': True,
        'sms_notifications_enabled': False,
        
        # API settings
        'api_rate_limit': 100,
        'api_timeout_seconds': 30,
        
        # Plan-specific defaults
        '_plan_specific': []
    }
    
    # Add plan-specific defaults
    if plan == 'pro':
        base_defaults.update({
            'ai_confidence_threshold': 0.75,
            'api_rate_limit': 500,
            'sms_notifications_enabled': True
        })
        base_defaults['_plan_specific'].extend(['ai_confidence_threshold', 'api_rate_limit'])
    
    elif plan == 'business':
        base_defaults.update({
            'ai_confidence_threshold': 0.8,
            'api_rate_limit': 1000,
            'mfa_required': True,
            'sms_notifications_enabled': True
        })
        base_defaults['_plan_specific'].extend(['ai_confidence_threshold', 'api_rate_limit', 'mfa_required'])
    
    elif plan == 'enterprise':
        base_defaults.update({
            'ai_confidence_threshold': 0.85,
            'api_rate_limit': -1,  # Unlimited
            'mfa_required': True,
            'sms_notifications_enabled': True,
            'custom_branding_enabled': True
        })
        base_defaults['_plan_specific'].extend(['ai_confidence_threshold', 'api_rate_limit', 'custom_branding_enabled'])
    
    return base_defaults


# ===== ENUMS AND DATACLASSES =====

def store_pdf_file(pdf_content: bytes, document_id: int, user_id: int, 
                   filename: str = None) -> str:
    """Store PDF file in storage system with proper organization"""
    try:
        # Create storage directories
        base_dir = os.path.join(os.getcwd(), 'storage', 'pdfs')
        user_dir = os.path.join(base_dir, f'user_{user_id}')
        year_month_dir = os.path.join(user_dir, datetime.now().strftime('%Y-%m'))
        
        # Create directories if they don't exist
        for directory in [base_dir, user_dir, year_month_dir]:
            os.makedirs(directory, exist_ok=True)
        
        # Generate filename if not provided
        if not filename:
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            filename = f"document_{document_id}_{timestamp}.pdf"
        
        # Secure the filename
        safe_filename = secure_filename(filename)
        filepath = os.path.join(year_month_dir, safe_filename)
        
        # Write PDF content
        with open(filepath, 'wb') as f:
            f.write(pdf_content)
        
        # Store file metadata
        metadata = {
            'document_id': document_id,
            'user_id': user_id,
            'filename': safe_filename,
            'original_filename': filename,
            'file_size': len(pdf_content),
            'created_at': datetime.now().isoformat(),
            'file_path': filepath,
            'sha256_hash': hashlib.sha256(pdf_content).hexdigest()
        }
        
        # Save metadata to JSON file
        metadata_file = filepath.replace('.pdf', '.json')
        with open(metadata_file, 'w') as f:
            json.dump(metadata, f, indent=2)
        
        logger.info(f"✅ Stored PDF file: {filepath} ({len(pdf_content)} bytes)")
        return filepath
        
    except Exception as e:
        logger.error(f"❌ Error storing PDF file: {str(e)}")
        raise Exception(f"Failed to store PDF file: {str(e)}")


def get_pdf_file_content(file_path: str) -> Optional[bytes]:
    """Retrieve PDF file content from storage with validation"""
    try:
        if not os.path.exists(file_path):
            # Try to find the file in alternative locations
            alt_path = find_pdf_file(file_path)
            if not alt_path:
                logger.warning(f"PDF file not found: {file_path}")
                return None
            file_path = alt_path
        
        # Read file content
        with open(file_path, 'rb') as f:
            content = f.read()
        
        # Validate it's actually a PDF
        if not validate_pdf_content(content):
            logger.warning(f"Invalid PDF content: {file_path}")
            return None
        
        logger.info(f"✅ Retrieved PDF file: {file_path} ({len(content)} bytes)")
        return content
        
    except Exception as e:
        logger.error(f"❌ Error retrieving PDF file: {str(e)}")
        return None


def find_pdf_file(file_path: str) -> Optional[str]:
    """Find PDF file in storage system"""
    try:
        # If absolute path doesn't exist, try relative
        if not os.path.exists(file_path):
            # Try with just the filename
            filename = os.path.basename(file_path)
            
            # Search in storage directories
            storage_base = os.path.join(os.getcwd(), 'storage', 'pdfs')
            
            for root, dirs, files in os.walk(storage_base):
                if filename in files:
                    return os.path.join(root, filename)
            
            # Try searching by document ID
            if 'document_' in filename:
                doc_id = filename.split('_')[1].split('.')[0]
                for root, dirs, files in os.walk(storage_base):
                    for file in files:
                        if f"document_{doc_id}" in file and file.endswith('.pdf'):
                            return os.path.join(root, file)
        
        return None
        
    except Exception as e:
        logger.error(f"Error finding PDF file: {str(e)}")
        return None


def validate_pdf_content(content: bytes) -> bool:
    """Validate that content is actually a PDF"""
    try:
        if len(content) < 5:  # Too small to be a PDF
            return False
        
        # Check PDF magic number
        if content[:4] != b'%PDF':
            return False
        
        # Try to parse with PyPDF2
        pdf_reader = PyPDF2.PdfReader(io.BytesIO(content))
        return len(pdf_reader.pages) > 0
        
    except Exception:
        return False


def get_mime_type(file_format: str) -> str:
    """Get MIME type for download format"""
    mime_types = {
        'pdf': 'application/pdf',
        'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'html': 'text/html',
        'zip': 'application/zip',
        'txt': 'text/plain',
        'json': 'application/json',
        'csv': 'text/csv'
    }
    return mime_types.get(file_format.lower(), 'application/octet-stream')


# ===== PDF ANALYSIS FUNCTIONS =====

def perform_basic_pdf_analysis(pdf_bytes: bytes, analysis_type: str = 'comprehensive') -> Dict[str, Any]:
    """Perform basic PDF analysis with PyPDF2"""
    try:
        # Basic information
        size_bytes = len(pdf_bytes)
        analysis_time = datetime.now().isoformat()
        
        # Initialize results
        analysis_result = {
            'basic_info': {
                'size_bytes': size_bytes,
                'analysis_type': analysis_type,
                'analyzed_at': analysis_time,
                'file_size_mb': round(size_bytes / (1024 * 1024), 2)
            },
            'estimated_pages': 0,
            'has_text': False,
            'has_images': False,
            'text_content': '',
            'metadata': {},
            'compliance_check': 'basic_analysis',
            'quality_score': 0,
            'warnings': [],
            'recommendations': []
        }
        
        # Try to analyze with PyPDF2
        try:
            pdf_reader = PyPDF2.PdfReader(io.BytesIO(pdf_bytes))
            
            # Get page count
            page_count = len(pdf_reader.pages)
            analysis_result['estimated_pages'] = page_count
            
            # Extract metadata
            if pdf_reader.metadata:
                analysis_result['metadata'] = {
                    'title': str(pdf_reader.metadata.get('/Title', '')),
                    'author': str(pdf_reader.metadata.get('/Author', '')),
                    'subject': str(pdf_reader.metadata.get('/Subject', '')),
                    'creator': str(pdf_reader.metadata.get('/Creator', '')),
                    'producer': str(pdf_reader.metadata.get('/Producer', '')),
                    'creation_date': str(pdf_reader.metadata.get('/CreationDate', '')),
                    'modification_date': str(pdf_reader.metadata.get('/ModDate', ''))
                }
            
            # Check for text content
            text_content = ''
            for page_num in range(min(3, page_count)):  # Check first 3 pages
                page = pdf_reader.pages[page_num]
                page_text = page.extract_text()
                if page_text and len(page_text.strip()) > 0:
                    text_content += page_text + '\n\n'
            
            if text_content:
                analysis_result['has_text'] = True
                analysis_result['text_content'] = text_content[:1000] + '...' if len(text_content) > 1000 else text_content
            
            # Estimate quality score
            quality_score = 50  # Base score
            
            if page_count > 0:
                quality_score += min(20, page_count * 2)  # More pages = higher score
            
            if analysis_result['has_text']:
                quality_score += 20
            
            if analysis_result['metadata'].get('title'):
                quality_score += 10
            
            if analysis_result['metadata'].get('author'):
                quality_score += 10
            
            analysis_result['quality_score'] = min(100, quality_score)
            
            # Check for potential issues
            if page_count == 0:
                analysis_result['warnings'].append('PDF appears to have no pages')
            
            if not analysis_result['has_text']:
                analysis_result['warnings'].append('No text content detected - may be scanned/image-only PDF')
            
            if size_bytes > 10 * 1024 * 1024:  # > 10MB
                analysis_result['warnings'].append('Large file size may affect performance')
            
        except Exception as pdf_error:
            analysis_result['warnings'].append(f'PDF parsing error: {str(pdf_error)}')
            analysis_result['quality_score'] = 30
        
        # Add compliance check based on analysis type
        if analysis_type == 'compliance':
            compliance_result = check_pdf_compliance(pdf_bytes, analysis_result)
            analysis_result.update(compliance_result)
        
        # Generate recommendations
        analysis_result['recommendations'] = generate_analysis_recommendations(analysis_result)
        
        logger.info(f"✅ PDF analysis completed: {analysis_type}, score: {analysis_result['quality_score']}")
        return analysis_result
        
    except Exception as e:
        logger.error(f"❌ PDF analysis failed: {str(e)}")
        return {
            'basic_info': {
                'size_bytes': len(pdf_bytes),
                'analysis_type': analysis_type,
                'analyzed_at': datetime.now().isoformat()
            },
            'estimated_pages': 0,
            'has_text': False,
            'has_images': False,
            'compliance_check': 'analysis_failed',
            'quality_score': 0,
            'error': str(e)
        }


def check_pdf_compliance(pdf_bytes: bytes, analysis_result: Dict[str, Any]) -> Dict[str, Any]:
    """Check PDF for compliance with safety standards"""
    compliance_checks = {
        'has_safety_header': False,
        'has_revision_history': False,
        'has_approval_signature': False,
        'has_risk_assessment': False,
        'has_emergency_procedures': False,
        'has_references': False,
        'has_disclaimer': False
    }
    
    text_content = analysis_result.get('text_content', '').lower()
    
    # Check for safety-related keywords
    safety_keywords = [
        'safety', 'risk', 'hazard', 'emergency', 'procedure',
        'compliance', 'regulation', 'standard', 'guideline',
        'assessment', 'evaluation', 'inspection', 'audit'
    ]
    
    found_keywords = [kw for kw in safety_keywords if kw in text_content]
    
    compliance_score = 0
    
    # Check specific compliance items
    if any(word in text_content for word in ['emergency', 'evacuation', 'procedure']):
        compliance_checks['has_emergency_procedures'] = True
        compliance_score += 15
    
    if any(word in text_content for word in ['risk', 'assessment', 'hazard']):
        compliance_checks['has_risk_assessment'] = True
        compliance_score += 20
    
    if any(word in text_content for word in ['revision', 'version', 'history']):
        compliance_checks['has_revision_history'] = True
        compliance_score += 10
    
    if any(word in text_content for word in ['signature', 'approved', 'authorized']):
        compliance_checks['has_approval_signature'] = True
        compliance_score += 15
    
    if any(word in text_content for word in ['reference', 'standard', 'regulation']):
        compliance_checks['has_references'] = True
        compliance_score += 10
    
    if any(word in text_content for word in ['disclaimer', 'liability', 'responsibility']):
        compliance_checks['has_disclaimer'] = True
        compliance_score += 10
    
    # Add base score for having text
    if analysis_result.get('has_text'):
        compliance_score += 20
    
    return {
        'compliance_checks': compliance_checks,
        'compliance_score': min(100, compliance_score),
        'found_keywords': found_keywords,
        'keyword_count': len(found_keywords)
    }


def generate_analysis_recommendations(analysis_result: Dict[str, Any]) -> List[str]:
    """Generate recommendations based on PDF analysis"""
    recommendations = []
    
    quality_score = analysis_result.get('quality_score', 0)
    
    if quality_score < 60:
        recommendations.append('Consider regenerating with higher quality settings')
    
    if quality_score < 40:
        recommendations.append('Document quality is low - check content and formatting')
    
    if not analysis_result.get('has_text', False):
        recommendations.append('Document appears to be image-only. Consider OCR processing or regenerating with text.')
    
    if analysis_result.get('estimated_pages', 0) > 50:
        recommendations.append('Document is very long. Consider splitting into multiple documents.')
    
    if 'compliance_checks' in analysis_result:
        compliance = analysis_result['compliance_checks']
        if not compliance.get('has_risk_assessment', False):
            recommendations.append('Add risk assessment section for safety compliance')
        if not compliance.get('has_emergency_procedures', False):
            recommendations.append('Include emergency procedures section')
        if not compliance.get('has_revision_history', False):
            recommendations.append('Add revision history for document control')
    
    if analysis_result.get('quality_score', 0) > 80:
        recommendations.append('Document quality is good. Consider saving as a template.')
    
    if len(recommendations) == 0:
        recommendations.append('Document analysis complete. No major issues detected.')
    
    return recommendations


# ===== BATCH PROCESSING FUNCTIONS =====

def process_batch_generation(batch_id: int, batch_documents: List[Any], 
                           template_id: str = None):
    """Process batch PDF generation in background"""
    try:
        from app import create_app
        from models import AIPDFBatch, AIPDFBatchDocument, AIPDFDocument, db
        import time
        
        app = create_app()
        
        with app.app_context():
            # Get batch
            batch = AIPDFBatch.query.get(batch_id)
            if not batch:
                logger.error(f"Batch {batch_id} not found")
                return
            
            batch.status = 'processing'
            batch.started_at = datetime.utcnow()
            db.session.commit()
            
            successful_docs = 0
            failed_docs = 0
            generated_documents = []
            
            logger.info(f"Starting batch generation for {len(batch_documents)} documents")
            
            for i, batch_doc_data in enumerate(batch_documents):
                try:
                    # Get batch document record
                    batch_doc = AIPDFBatchDocument.query.filter_by(
                        batch_id=batch_id,
                        document_index=i
                    ).first()
                    
                    if not batch_doc:
                        logger.warning(f"Batch document {i} not found in database")
                        continue
                    
                    logger.info(f"Processing document {i+1}/{len(batch_documents)}: {batch_doc.document_type}")
                    
                    # Generate PDF content (this would call your actual generation logic)
                    pdf_content = generate_pdf_for_batch_document(batch_doc, template_id)
                    
                    if not pdf_content:
                        raise Exception("Failed to generate PDF content")
                    
                    # Create PDF document record
                    pdf_document = AIPDFDocument(
                        user_id=batch.user_id,
                        document_type=batch_doc.document_type,
                        industry=batch_doc.industry or 'general',
                        template_id=template_id,
                        file_size=len(pdf_content),
                        quality_level='standard',
                        plan=batch.plan,
                        system_team_bypass=batch.system_team_bypass
                    )
                    db.session.add(pdf_document)
                    db.session.flush()  # Get the ID
                    
                    # Store PDF file
                    filename = f"batch_{batch_id}_doc_{i+1}_{batch_doc.document_type}.pdf"
                    file_path = store_pdf_file(pdf_content, pdf_document.id, batch.user_id, filename)
                    pdf_document.file_path = file_path
                    
                    # Update batch document
                    batch_doc.status = 'completed'
                    batch_doc.generated_document_id = pdf_document.id
                    batch_doc.estimated_size = len(pdf_content)
                    
                    successful_docs += 1
                    generated_documents.append(pdf_document.id)
                    
                    # Commit after each document for progress tracking
                    db.session.commit()
                    
                    logger.info(f"✅ Document {i+1} generated successfully: {pdf_document.id}")
                    
                    # Small delay to prevent overwhelming the system
                    time.sleep(0.5)
                    
                except Exception as e:
                    logger.error(f"❌ Failed to generate document {i+1}: {str(e)}")
                    failed_docs += 1
                    
                    if 'batch_doc' in locals():
                        batch_doc.status = 'failed'
                        batch_doc.error_message = str(e)
                    
                    db.session.commit()
                    continue
            
            # Update batch status
            if successful_docs == len(batch_documents):
                batch.status = 'completed'
                batch.message = f'All {successful_docs} documents generated successfully'
            elif successful_docs > 0:
                batch.status = 'partial_completion'
                batch.message = f'{successful_docs} documents generated, {failed_docs} failed'
            else:
                batch.status = 'failed'
                batch.message = f'All {failed_docs} documents failed to generate'
            
            batch.successful_count = successful_docs
            batch.failed_count = failed_docs
            batch.completed_at = datetime.utcnow()
            batch.generated_document_ids = json.dumps(generated_documents)
            
            db.session.commit()
            
            logger.info(f"✅ Batch {batch_id} completed: {successful_docs} successful, {failed_docs} failed")
            
    except Exception as e:
        logger.error(f"❌ Batch generation error: {str(e)}")
        # Update batch status to failed
        try:
            with app.app_context():
                batch = AIPDFBatch.query.get(batch_id)
                if batch:
                    batch.status = 'failed'
                    batch.error_message = str(e)
                    db.session.commit()
        except Exception as inner_error:
            logger.error(f"Failed to update batch status: {inner_error}")


def generate_pdf_for_batch_document(batch_doc, template_id: str = None) -> Optional[bytes]:
    """Generate PDF for a single batch document"""
    try:
        # This is where you'd integrate with your actual PDF generation logic
        # For now, create a simple PDF
        
        from reportlab.lib.pagesizes import letter
        from reportlab.pdfgen import canvas
        import io
        
        buffer = io.BytesIO()
        c = canvas.Canvas(buffer, pagesize=letter)
        
        # Add document info
        c.setFont("Helvetica-Bold", 16)
        c.drawString(100, 750, f"{batch_doc.document_type.replace('_', ' ').title()}")
        
        c.setFont("Helvetica", 12)
        c.drawString(100, 730, f"Industry: {batch_doc.industry.title() if batch_doc.industry else 'General'}")
        
        # Add requirements
        if batch_doc.requirements:
            c.drawString(100, 710, "Requirements:")
            c.setFont("Helvetica", 10)
            
            # Split requirements into lines
            requirements = str(batch_doc.requirements)
            y_position = 690
            
            for line in requirements.split('\n'):
                if len(line) > 80:
                    # Split long lines
                    words = line.split()
                    current_line = ""
                    for word in words:
                        if len(current_line) + len(word) + 1 > 80:
                            c.drawString(100, y_position, current_line)
                            y_position -= 15
                            current_line = word
                        else:
                            current_line += " " + word if current_line else word
                    if current_line:
                        c.drawString(100, y_position, current_line)
                        y_position -= 15
                else:
                    c.drawString(100, y_position, line)
                    y_position -= 15
                
                if y_position < 100:
                    c.showPage()
                    c.setFont("Helvetica", 10)
                    y_position = 750
        
        # Add footer
        c.setFont("Helvetica-Oblique", 8)
        c.drawString(100, 50, f"Generated by SafetyTrack Pro | Batch Document | {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        
        c.save()
        
        buffer.seek(0)
        return buffer.getvalue()
        
    except Exception as e:
        logger.error(f"Error generating PDF for batch document: {str(e)}")
        return None


# ===== PDF EXPORT FUNCTIONS =====

def process_pdf_export(export_id: int, documents: List[Any], 
                      export_format: str = 'zip', 
                      include_metadata: bool = True,
                      compression_level: str = 'normal'):
    """Process PDF export in background"""
    try:
        from app import create_app
        from models import AIPDFExport, AIPDFDocument, db
        import zipfile
        import tempfile
        import json
        
        app = create_app()
        
        with app.app_context():
            # Get export record
            pdf_export = AIPDFExport.query.get(export_id)
            if not pdf_export:
                logger.error(f"Export {export_id} not found")
                return
            
            pdf_export.status = 'processing'
            pdf_export.started_at = datetime.utcnow()
            db.session.commit()
            
            logger.info(f"Starting PDF export {export_id} for {len(documents)} documents")
            
            # Create temporary directory
            with tempfile.TemporaryDirectory() as temp_dir:
                export_files = []
                metadata_files = []
                
                # Process each document
                for i, doc in enumerate(documents):
                    try:
                        # Get document content
                        if isinstance(doc, AIPDFDocument):
                            pdf_doc = doc
                        else:
                            pdf_doc = AIPDFDocument.query.get(doc.id)
                        
                        if not pdf_doc or not pdf_doc.file_path:
                            logger.warning(f"Document {doc.id if hasattr(doc, 'id') else doc} not found or has no file")
                            continue
                        
                        # Get PDF content
                        pdf_content = get_pdf_file_content(pdf_doc.file_path)
                        if not pdf_content:
                            logger.warning(f"Could not read PDF content for document {pdf_doc.id}")
                            continue
                        
                        # Save PDF file
                        filename = f"{pdf_doc.document_type}_{pdf_doc.id}.pdf"
                        filepath = os.path.join(temp_dir, filename)
                        with open(filepath, 'wb') as f:
                            f.write(pdf_content)
                        
                        export_files.append((filepath, filename))
                        
                        # Create metadata file if requested
                        if include_metadata:
                            metadata = {
                                'document_id': pdf_doc.id,
                                'document_type': pdf_doc.document_type,
                                'industry': pdf_doc.industry,
                                'created_at': pdf_doc.created_at.isoformat() if pdf_doc.created_at else None,
                                'file_size': pdf_doc.file_size,
                                'quality_level': pdf_doc.quality_level,
                                'exported_at': datetime.now().isoformat()
                            }
                            
                            metadata_filename = f"{pdf_doc.document_type}_{pdf_doc.id}_metadata.json"
                            metadata_filepath = os.path.join(temp_dir, metadata_filename)
                            with open(metadata_filepath, 'w') as f:
                                json.dump(metadata, f, indent=2)
                            
                            metadata_files.append((metadata_filepath, metadata_filename))
                        
                        logger.info(f"Added document {i+1}/{len(documents)} to export: {filename}")
                        
                    except Exception as e:
                        logger.error(f"Error processing document {i+1}: {str(e)}")
                        continue
                
                # Create export file based on format
                export_file_path = create_export_file(
                    export_files, metadata_files, temp_dir, export_format, compression_level
                )
                
                if not export_file_path:
                    raise Exception("Failed to create export file")
                
                # Store export file
                final_filename = f"export_{export_id}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.{export_format}"
                storage_dir = os.path.join(os.getcwd(), 'storage', 'exports')
                os.makedirs(storage_dir, exist_ok=True)
                final_filepath = os.path.join(storage_dir, final_filename)
                
                # Copy export file to storage
                with open(export_file_path, 'rb') as src, open(final_filepath, 'wb') as dst:
                    dst.write(src.read())
                
                # Update export record
                pdf_export.status = 'completed'
                pdf_export.file_path = final_filepath
                pdf_export.file_size = os.path.getsize(final_filepath)
                pdf_export.completed_at = datetime.utcnow()
                pdf_export.document_count = len(export_files)
                
                db.session.commit()
                
                logger.info(f"✅ Export {export_id} completed: {final_filepath} ({pdf_export.file_size} bytes)")
                
    except Exception as e:
        logger.error(f"❌ PDF export error: {str(e)}")
        # Update export status to failed
        try:
            with app.app_context():
                pdf_export = AIPDFExport.query.get(export_id)
                if pdf_export:
                    pdf_export.status = 'failed'
                    pdf_export.error_message = str(e)
                    db.session.commit()
        except Exception as inner_error:
            logger.error(f"Failed to update export status: {inner_error}")


def create_export_file(export_files: List[Tuple[str, str]], 
                      metadata_files: List[Tuple[str, str]], 
                      temp_dir: str, 
                      export_format: str = 'zip',
                      compression_level: str = 'normal') -> Optional[str]:
    """Create export file in specified format"""
    try:
        compression_map = {
            'low': zipfile.ZIP_STORED,
            'normal': zipfile.ZIP_DEFLATED,
            'high': zipfile.ZIP_BZIP2
        }
        compression = compression_map.get(compression_level, zipfile.ZIP_DEFLATED)
        
        if export_format == 'zip':
            # Create ZIP file
            zip_filename = f"export_{datetime.now().strftime('%Y%m%d_%H%M%S')}.zip"
            zip_filepath = os.path.join(temp_dir, zip_filename)
            
            with zipfile.ZipFile(zip_filepath, 'w', compression=compression) as zipf:
                # Add PDF files
                for filepath, filename in export_files:
                    zipf.write(filepath, filename)
                
                # Add metadata files
                for filepath, filename in metadata_files:
                    zipf.write(filepath, filename)
                
                # Add README file
                readme_content = f"""SafetyTrack Pro PDF Export
Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}
Total Documents: {len(export_files)}
Export Format: {export_format}
Compression: {compression_level}

Contents:
- {len(export_files)} PDF documents
- {len(metadata_files)} metadata files

Instructions:
1. Extract this ZIP file to access the documents
2. Refer to metadata files for document information
3. Use SafetyTrack Pro to regenerate or modify documents

For support: contact@safetytrack.pro
"""
                zipf.writestr('README.txt', readme_content)
            
            return zip_filepath
        
        elif export_format == 'pdf_merged':
            # Merge PDFs into single document
            return merge_pdfs(export_files, temp_dir)
        
        else:
            logger.error(f"Unsupported export format: {export_format}")
            return None
            
    except Exception as e:
        logger.error(f"Error creating export file: {str(e)}")
        return None


def merge_pdfs(export_files: List[Tuple[str, str]], temp_dir: str) -> Optional[str]:
    """Merge multiple PDFs into a single document"""
    try:
        from PyPDF2 import PdfMerger
        
        merger = PdfMerger()
        
        # Add each PDF to merger
        for filepath, filename in export_files:
            merger.append(filepath)
        
        # Create merged PDF
        merged_filename = f"merged_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf"
        merged_filepath = os.path.join(temp_dir, merged_filename)
        
        with open(merged_filepath, 'wb') as f:
            merger.write(f)
        
        merger.close()
        
        return merged_filepath
        
    except Exception as e:
        logger.error(f"Error merging PDFs: {str(e)}")
        return None


# ===== VERSION MANAGEMENT FUNCTIONS =====

def store_pdf_version_file(pdf_bytes: bytes, document_id: int, 
                          version_id: int, user_id: int) -> str:
    """Store PDF version file with proper organization"""
    try:
        # Create version directories
        base_dir = os.path.join(os.getcwd(), 'storage', 'pdfs', 'versions')
        user_dir = os.path.join(base_dir, f'user_{user_id}')
        document_dir = os.path.join(user_dir, f'document_{document_id}')
        
        # Create directories if they don't exist
        for directory in [base_dir, user_dir, document_dir]:
            os.makedirs(directory, exist_ok=True)
        
        # Generate filename
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        filename = f"v{version_id}_{timestamp}.pdf"
        filepath = os.path.join(document_dir, filename)
        
        # Write PDF content
        with open(filepath, 'wb') as f:
            f.write(pdf_bytes)
        
        # Store version metadata
        metadata = {
            'document_id': document_id,
            'version_id': version_id,
            'user_id': user_id,
            'filename': filename,
            'file_size': len(pdf_bytes),
            'created_at': datetime.now().isoformat(),
            'file_path': filepath,
            'sha256_hash': hashlib.sha256(pdf_bytes).hexdigest()
        }
        
        # Save metadata to JSON file
        metadata_file = filepath.replace('.pdf', '.json')
        with open(metadata_file, 'w') as f:
            json.dump(metadata, f, indent=2)
        
        logger.info(f"✅ Stored PDF version {version_id} for document {document_id}")
        return filepath
        
    except Exception as e:
        logger.error(f"❌ Error storing PDF version: {str(e)}")
        raise Exception(f"Failed to store PDF version: {str(e)}")


# ===== STATISTICS AND RECOMMENDATIONS =====

def generate_statistics_recommendations(total_docs: int, docs_by_type: Dict[str, int], 
                                       plan: str) -> List[str]:
    """Generate recommendations based on statistics"""
    recommendations = []
    
    if total_docs == 0:
        recommendations.extend([
            'Start generating documents to build your safety documentation library',
            'Try the Risk Assessment template to begin',
            'Use the AI chat to help you create your first document'
        ])
        return recommendations
    
    # Efficiency recommendations
    if total_docs > 20:
        most_common_type = max(docs_by_type.items(), key=lambda x: x[1])[0]
        recommendations.append(f'Create a template for "{most_common_type}" documents to save time')
    
    # Batch processing recommendations
    if 'risk_assessment' in docs_by_type and docs_by_type['risk_assessment'] > 5:
        recommendations.append('Consider using batch generation for risk assessments to save time')
    
    if 'safety_checklist' in docs_by_type and docs_by_type['safety_checklist'] > 10:
        recommendations.append('Use checklist templates for consistent safety inspections')
    
    # Plan upgrade recommendations
    if total_docs > 50 and plan != 'enterprise':
        recommendations.extend([
            'Upgrade to Enterprise plan for advanced analytics and batch processing',
            'Enterprise plan offers unlimited document generation and custom templates'
        ])
    
    if total_docs > 100:
        recommendations.append('Consider archiving old documents to improve performance')
    
    # Content optimization
    unique_types = len(docs_by_type)
    if unique_types < 3 and total_docs > 10:
        recommendations.append('Expand your document types for comprehensive safety coverage')
    
    # Template usage
    if plan in ['business', 'enterprise'] and total_docs > 5:
        recommendations.append('Create custom templates for your most common document types')
    
    # Add general best practices
    recommendations.extend([
        'Regularly review and update your safety documents',
        'Share documents with team members for collaboration',
        'Use version control to track document changes'
    ])
    
    return recommendations[:10]  # Limit to 10 recommendations


