def calculate_pdf_statistics(user_id: int = None, time_range: str = 'month') -> Dict[str, Any]:
    """Calculate detailed PDF statistics"""
    try:
        from models import AIPDFDocument, AIPDFGeneration, db
        from sqlalchemy import func, extract
        
        with app.app_context():
            # Build query
            query = AIPDFDocument.query
            
            if user_id:
                query = query.filter_by(user_id=user_id)
            
            # Calculate date range
            end_date = datetime.utcnow()
            if time_range == 'day':
                start_date = end_date - timedelta(days=1)
            elif time_range == 'week':
                start_date = end_date - timedelta(weeks=1)
            elif time_range == 'month':
                start_date = end_date - timedelta(days=30)
            elif time_range == 'year':
                start_date = end_date - timedelta(days=365)
            else:  # 'all'
                start_date = datetime.utcnow() - timedelta(days=365*5)
            
            query = query.filter(AIPDFDocument.created_at >= start_date)
            
            # Get documents
            documents = query.all()
            
            # Calculate statistics
            total_docs = len(documents)
            total_size = sum(d.file_size or 0 for d in documents)
            avg_size = total_size / total_docs if total_docs > 0 else 0
            
            # Documents by type
            docs_by_type = {}
            for doc in documents:
                docs_by_type[doc.document_type] = docs_by_type.get(doc.document_type, 0) + 1
            
            # Documents by industry
            docs_by_industry = {}
            for doc in documents:
                docs_by_industry[doc.industry] = docs_by_industry.get(doc.industry, 0) + 1
            
            # Quality distribution
            quality_distribution = {}
            for doc in documents:
                quality_distribution[doc.quality_level] = quality_distribution.get(doc.quality_level, 0) + 1
            
            # Template usage
            template_usage = {}
            for doc in documents:
                if doc.template_id:
                    template_usage[doc.template_id] = template_usage.get(doc.template_id, 0) + 1
            
            # Generate recommendations
            recommendations = generate_statistics_recommendations(total_docs, docs_by_type, 'pro')
            
            return {
                'success': True,
                'statistics': {
                    'total_documents': total_docs,
                    'total_size_bytes': total_size,
                    'total_size_mb': round(total_size / (1024 * 1024), 2),
                    'average_size_kb': round(avg_size / 1024, 2),
                    'documents_by_type': docs_by_type,
                    'documents_by_industry': docs_by_industry,
                    'quality_distribution': quality_distribution,
                    'template_usage': template_usage,
                    'time_period': {
                        'start': start_date.isoformat(),
                        'end': end_date.isoformat(),
                        'range': time_range
                    }
                },
                'recommendations': recommendations
            }
            
    except Exception as e:
        logger.error(f"Error calculating PDF statistics: {str(e)}")
        return {
            'success': False,
            'error': str(e)
        }


def cleanup_orphaned_pdf_files(days_old: int = 30) -> Dict[str, Any]:
    """Clean up orphaned PDF files (files without database records)"""
    try:
        from models import AIPDFDocument
        import time
        
        storage_base = os.path.join(os.getcwd(), 'storage', 'pdfs')
        cutoff_time = time.time() - (days_old * 24 * 60 * 60)
        
        orphaned_files = []
        total_freed_space = 0
        
        with app.app_context():
            # Get all valid file paths from database
            valid_files = set()
            pdf_docs = AIPDFDocument.query.all()
            for doc in pdf_docs:
                if doc.file_path and os.path.exists(doc.file_path):
                    valid_files.add(os.path.abspath(doc.file_path))
            
            # Walk through storage directory
            for root, dirs, files in os.walk(storage_base):
                for file in files:
                    if file.endswith('.pdf'):
                        filepath = os.path.join(root, file)
                        abs_path = os.path.abspath(filepath)
                        
                        # Check if file is in database
                        if abs_path not in valid_files:
                            # Check file age
                            file_mtime = os.path.getmtime(filepath)
                            if file_mtime < cutoff_time:
                                file_size = os.path.getsize(filepath)
                                os.remove(filepath)
                                
                                # Remove metadata file if exists
                                metadata_file = filepath.replace('.pdf', '.json')
                                if os.path.exists(metadata_file):
                                    os.remove(metadata_file)
                                
                                orphaned_files.append(filepath)
                                total_freed_space += file_size
        
        return {
            'success': True,
            'cleaned_files': len(orphaned_files),
            'freed_space_mb': round(total_freed_space / (1024 * 1024), 2),
            'orphaned_files': orphaned_files[:10]  # Limit output
        }
        
    except Exception as e:
        logger.error(f"Error cleaning up orphaned PDF files: {str(e)}")
        return {
            'success': False,
            'error': str(e)
        }

