class AIDocumentClassifier:
    """AI Document Classification Service"""
    
    def __init__(self, model_path=None):
        self.model_path = model_path or os.path.join('models', 'document_classifier.pkl')
        self.vectorizer_path = os.path.join('models', 'vectorizer.pkl')
        self.pipeline = None
        self.vectorizer = None
        
        self.labels = [
            'hse_report', 'environmental_report', 'incident_report',
            'policy', 'procedure', 'permit', 'training_material',
            'quality_document', 'compliance_document', 'technical_document',
            'safety_plan', 'risk_assessment', 'audit_report'
        ]
        
        self.label_names = {
            'hse_report': 'HSE Report',
            'environmental_report': 'Environmental Report',
            'incident_report': 'Incident Report',
            'policy': 'Policy Document',
            'procedure': 'Procedure',
            'permit': 'Permit/License',
            'training_material': 'Training Material',
            'quality_document': 'Quality Document',
            'compliance_document': 'Compliance Document',
            'technical_document': 'Technical Document',
            'safety_plan': 'Safety Plan',
            'risk_assessment': 'Risk Assessment',
            'audit_report': 'Audit Report'
        }
        
        self._load_or_init_model()
    
    def _load_or_init_model(self):
        """Load existing model or initialize new one"""
        try:
            if os.path.exists(self.model_path) and os.path.exists(self.vectorizer_path):
                self.pipeline = joblib.load(self.model_path)
                self.vectorizer = joblib.load(self.vectorizer_path)
                print("✅ AI Document Classifier loaded successfully")
            else:
                self._init_new_model()
        except Exception as e:
            print(f"⚠️ Could not load AI model: {e}")
            self._init_new_model()
    
    def _init_new_model(self):
        """Initialize a new model with training data"""
        self.pipeline = Pipeline([
            ('tfidf', TfidfVectorizer(
                max_features=10000,
                stop_words='english',
                ngram_range=(1, 2)
            )),
            ('classifier', MultinomialNB(alpha=0.1))
        ])
        self.vectorizer = TfidfVectorizer(
            max_features=10000,
            stop_words='english',
            ngram_range=(1, 2)
        )
        self._train_with_sample_data()
    
    def _train_with_sample_data(self):
        """Train model with sample data"""
        sample_docs = [
            ("Worker suffered minor injury while operating machinery. Safety protocols were followed.", "hse_report"),
            ("Chemical spill contained. No injuries reported. Cleanup in progress.", "hse_report"),
            ("Safety inspection found several violations. Corrective actions required.", "hse_report"),
            ("Air quality monitoring shows PM2.5 levels within acceptable limits.", "environmental_report"),
            ("Water samples tested negative for contaminants. Standards met.", "environmental_report"),
            ("Waste disposal audit completed. All procedures followed correctly.", "environmental_report"),
            ("Serious accident occurred at construction site. Investigation underway.", "incident_report"),
            ("Near miss reported. No injuries, but potential for serious harm.", "incident_report"),
            ("Equipment failure caused production stop. Investigation initiated.", "incident_report"),
            ("All employees must wear PPE at all times. Non-compliance will be reported.", "policy"),
            ("Company policy requires annual safety training for all staff.", "policy"),
            ("Drug and alcohol policy strictly enforced. Random testing conducted.", "policy"),
            ("Step-by-step guide for equipment startup and shutdown.", "procedure"),
            ("Emergency evacuation procedure for all buildings.", "procedure"),
            ("Maintenance procedure for all production equipment.", "procedure"),
            ("Training module on proper lifting techniques and back safety.", "training_material"),
            ("Fire safety training includes proper extinguisher use.", "training_material"),
            ("Chemical handling training module with safety protocols.", "training_material"),
            ("Quality control checklist for production batches.", "quality_document"),
            ("Quality management system procedures and standards.", "quality_document"),
            ("Inspection and testing requirements for finished products.", "quality_document"),
        ]
        
        texts = [doc[0] for doc in sample_docs]
        labels = [doc[1] for doc in sample_docs]
        
        try:
            self.vectorizer.fit(texts)
            self.pipeline.fit(texts, labels)
            
            os.makedirs(os.path.dirname(self.model_path), exist_ok=True)
            joblib.dump(self.pipeline, self.model_path)
            joblib.dump(self.vectorizer, self.vectorizer_path)
            
            print("✅ AI Document Classifier trained with sample data")
        except Exception as e:
            print(f"❌ Failed to train AI model: {e}")
    
    def classify(self, text, title=""):
        """Classify a document based on content and title"""
        if not text or not self.pipeline:
            return {
                'primary': {'category': 'general', 'confidence': 0},
                'predictions': [],
                'suggested_tags': [],
                'summary': 'No content to classify'
            }
        
        combined_text = f"{title} {text[:2000]}"
        
        try:
            proba = self.pipeline.predict_proba([combined_text])[0]
            classes = self.pipeline.classes_
            
            top_indices = np.argsort(proba)[-5:][::-1]
            predictions = []
            for idx in top_indices:
                if proba[idx] > 0.01:
                    predictions.append({
                        'category': classes[idx],
                        'label': self.label_names.get(classes[idx], classes[idx]),
                        'confidence': round(float(proba[idx] * 100), 2)
                    })
            
            tags = self._extract_keywords(text)
            suggested_tags = tags[:5]
            summary = self._generate_summary(text)
            
            return {
                'primary': predictions[0] if predictions else None,
                'predictions': predictions,
                'suggested_tags': suggested_tags,
                'summary': summary,
                'confidence_score': predictions[0]['confidence'] if predictions else 0
            }
            
        except Exception as e:
            print(f"Classification error: {e}")
            return {
                'primary': None,
                'predictions': [],
                'suggested_tags': [],
                'summary': 'Classification failed',
                'error': str(e)
            }
    
    def _extract_keywords(self, text):
        """Extract keywords from text"""
        try:
            clean_text = re.sub(r'[^a-zA-Z\s]', '', text.lower())
            words = clean_text.split()
            word_freq = Counter(words)
            
            common_words = {'the', 'and', 'for', 'are', 'but', 'not', 'you', 'all',
                          'can', 'had', 'her', 'was', 'one', 'our', 'out', 'has',
                          'its', 'may', 'new', 'now', 'old', 'see', 'two', 'way',
                          'who', 'boy', 'did', 'yet', 'she', 'say', 'too', 'use'}
            
            keywords = [word for word, count in word_freq.most_common(20)
                       if len(word) > 3 and word not in common_words]
            
            return keywords[:10]
        except Exception:
            return []
    
    def _generate_summary(self, text):
        """Generate a brief summary of the content"""
        try:
            sentences = re.split(r'[.!?]+', text)
            sentences = [s.strip() for s in sentences if len(s.strip()) > 20]
            
            if len(sentences) >= 3:
                summary = '. '.join(sentences[:3]) + '.'
            elif len(sentences) >= 1:
                summary = sentences[0] + '.'
            else:
                summary = text[:200] + '...' if len(text) > 200 else text
            
            return summary[:500]
        except Exception:
            return text[:200] + '...' if len(text) > 200 else text
    
    def suggest_document_type(self, content, title=""):
        """Suggest document type based on classification"""
        result = self.classify(content, title)
        
        if result['primary']:
            return {
                'suggested_type': result['primary']['category'],
                'suggested_label': result['primary']['label'],
                'confidence': result['primary']['confidence'],
                'alternatives': [
                    {'type': p['category'], 'label': p['label'], 'confidence': p['confidence']}
                    for p in result['predictions'][1:3]
                ],
                'suggested_tags': result['suggested_tags'],
                'summary': result['summary']
            }
        
        return {
            'suggested_type': 'general',
            'suggested_label': 'General Document',
            'confidence': 0,
            'alternatives': [],
            'suggested_tags': [],
            'summary': 'Unable to classify document'
        }
    
    def batch_classify(self, documents):
        """Classify multiple documents at once"""
        results = []
        for doc in documents:
            result = self.classify(doc.get('content', ''), doc.get('title', ''))
            results.append({
                'id': doc.get('id'),
                'title': doc.get('title', ''),
                'classification': result
            })
        return results
    
    def update_model(self, documents, labels):
        """Update model with new training data"""
        if len(documents) < 10:
            return {'success': False, 'message': 'Need at least 10 documents to train'}
        
        try:
            texts = [doc.get('content', '') or doc.get('title', '') for doc in documents]
            
            self.vectorizer.fit(texts)
            self.pipeline.fit(texts, labels)
            
            joblib.dump(self.pipeline, self.model_path)
            joblib.dump(self.vectorizer, self.vectorizer_path)
            
            return {
                'success': True,
                'message': f'Model updated with {len(documents)} documents'
            }
        except Exception as e:
            return {
                'success': False,
                'message': f'Failed to update model: {str(e)}'
            }


