class DocumentAnalyticsService:
    """Document Analytics Service"""
    
    def __init__(self):
        self.timeframes = {
            '7d': 7,
            '30d': 30,
            '90d': 90,
            '1y': 365
        }
    
    def get_overview_analytics(self, db, company_id=None, timeframe='30d'):
        """Get comprehensive overview analytics"""
        from models import Document, DocumentVersion, DocumentComment, DocumentAuditLog
        
        days = self.timeframes.get(timeframe, 30)
        since = datetime.utcnow() - timedelta(days=days)
        
        if company_id:
            query = Document.query.filter_by(company_id=company_id)
        else:
            query = Document.query
        
        total = query.count()
        by_status = self._get_status_distribution(db, company_id)
        by_module = self._get_module_distribution(db, company_id)
        by_type = self._get_type_distribution(db, company_id)
        
        new_documents = query.filter(Document.created_at >= since).count()
        updated_documents = query.filter(Document.updated_at >= since).count()
        
        version_stats = self._get_version_stats(db, company_id)
        comment_stats = self._get_comment_stats(db, company_id)  # ✅ Fixed
        user_stats = self._get_user_stats(db, company_id)
        lifecycle_stats = self._get_lifecycle_stats(db, company_id)
        growth_trends = self._get_growth_trends(db, company_id, days)
        
        return {
            'success': True,
            'overview': {
                'total_documents': total,
                'new_documents': new_documents,
                'updated_documents': updated_documents,
                'documents_by_status': by_status,
                'documents_by_module': by_module,
                'documents_by_type': by_type
            },
            'version_metrics': version_stats,
            'comment_metrics': comment_stats,
            'user_engagement': user_stats,
            'lifecycle_metrics': lifecycle_stats,
            'growth_trends': growth_trends,
            'timeframe': timeframe,
            'generated_at': datetime.utcnow().isoformat()
        }
    
    def _get_status_distribution(self, db, company_id):
        """Get distribution by status"""
        from models import Document
        
        query = Document.query
        if company_id:
            query = query.filter_by(company_id=company_id)
        
        results = query.with_entities(
            Document.status,
            func.count(Document.id).label('count')
        ).group_by(Document.status).all()
        
        return [{'status': r[0], 'count': r[1]} for r in results]
    
    def _get_module_distribution(self, db, company_id):
        """Get distribution by module"""
        from models import Document
        
        query = Document.query
        if company_id:
            query = query.filter_by(company_id=company_id)
        
        results = query.with_entities(
            Document.module,
            func.count(Document.id).label('count')
        ).group_by(Document.module).all()
        
        return [{'module': r[0] or 'general', 'count': r[1]} for r in results]
    
    def _get_type_distribution(self, db, company_id):
        """Get distribution by document type"""
        from models import Document
        
        query = Document.query
        if company_id:
            query = query.filter_by(company_id=company_id)
        
        results = query.with_entities(
            Document.document_type,
            func.count(Document.id).label('count')
        ).group_by(Document.document_type).all()
        
        return [{'type': r[0], 'count': r[1]} for r in results]
    
    def _get_version_stats(self, db, company_id):
        """Get version statistics"""
        from models import Document
        
        if company_id:
            avg_versions = db.session.query(
                func.avg(Document.version)
            ).filter(Document.company_id == company_id).scalar() or 0
            
            max_versions = db.session.query(
                func.max(Document.version)
            ).filter(Document.company_id == company_id).scalar() or 0
            
            total_versions = db.session.query(
                func.sum(Document.version)
            ).filter(Document.company_id == company_id).scalar() or 0
        else:
            avg_versions = db.session.query(func.avg(Document.version)).scalar() or 0
            max_versions = db.session.query(func.max(Document.version)).scalar() or 0
            total_versions = db.session.query(func.sum(Document.version)).scalar() or 0
        
        return {
            'average_versions': round(avg_versions, 1),
            'max_versions': max_versions,
            'total_versions': total_versions
        }
    
    def _get_comment_stats(self, db, company_id):
        """Get comment statistics - ✅ FIXED for SQLite"""
        from models import Document, DocumentComment
        
        # Build comment query with company filter
        query = DocumentComment.query.join(Document)
        if company_id:
            query = query.filter(Document.company_id == company_id)
        
        total_comments = query.count()
        
        # ✅ FIXED: Calculate average comments safely
        docs_with_comments = 0
        avg_comments = 0
        
        try:
            # Get documents that have at least one comment
            docs_with_comments_query = Document.query.join(DocumentComment)
            if company_id:
                docs_with_comments_query = docs_with_comments_query.filter(Document.company_id == company_id)
            docs_with_comments = docs_with_comments_query.distinct(Document.id).count()
            
            if docs_with_comments > 0:
                avg_comments = total_comments / docs_with_comments
        except Exception as e:
            print(f"Error calculating avg comments: {e}")
            avg_comments = 0
        
        return {
            'total_comments': total_comments,
            'average_comments_per_doc': round(avg_comments, 1),
            'documents_with_comments': docs_with_comments
        }
    
    def _get_user_stats(self, db, company_id):
        """Get user engagement statistics"""
        from models import User, Document
        
        query = User.query.join(Document, User.id == Document.created_by)
        if company_id:
            query = query.filter(User.company_id == company_id)
        
        active_users = query.distinct(User.id).count()
        
        if company_id:
            top_contributors = db.session.query(
                User.id,
                User.name,
                func.count(Document.id).label('doc_count')
            ).join(Document, User.id == Document.created_by).filter(
                User.company_id == company_id
            ).group_by(User.id, User.name).order_by(
                func.count(Document.id).desc()
            ).limit(10).all()
        else:
            top_contributors = db.session.query(
                User.id,
                User.name,
                func.count(Document.id).label('doc_count')
            ).join(Document, User.id == Document.created_by).group_by(
                User.id, User.name
            ).order_by(func.count(Document.id).desc()).limit(10).all()
        
        return {
            'active_users': active_users,
            'top_contributors': [
                {'id': u[0], 'name': u[1], 'count': u[2]} for u in top_contributors
            ]
        }
    
    def _get_lifecycle_stats(self, db, company_id):
        """Get document lifecycle statistics"""
        from models import Document
        
        query = Document.query
        if company_id:
            query = query.filter_by(company_id=company_id)
        
        draft_time = query.filter_by(status='draft').count()
        review_time = query.filter_by(status='review').count()
        approved_time = query.filter_by(status='approved').count()
        published_time = query.filter_by(status='published').count()
        archived_time = query.filter_by(status='archived').count()
        rejected_time = query.filter_by(status='rejected').count()
        
        published_docs = query.filter_by(status='published').all()
        avg_publish_time = 0
        if published_docs:
            total_time = sum(
                (doc.published_at - doc.created_at).total_seconds()
                for doc in published_docs if doc.published_at and doc.created_at
            )
            avg_publish_time = total_time / len(published_docs) / 86400
        
        return {
            'avg_publish_time_days': round(avg_publish_time, 1),
            'status_distribution': {
                'draft': draft_time,
                'review': review_time,
                'approved': approved_time,
                'published': published_time,
                'archived': archived_time,
                'rejected': rejected_time
            }
        }
    
    def _get_growth_trends(self, db, company_id, days):
        """Get growth trends over time"""
        from models import Document
        
        daily_data = []
        for i in range(days, -1, -1):
            date = datetime.utcnow() - timedelta(days=i)
            date_start = date.replace(hour=0, minute=0, second=0, microsecond=0)
            date_end = date_start + timedelta(days=1)
            
            query = Document.query.filter(
                Document.created_at >= date_start,
                Document.created_at < date_end
            )
            if company_id:
                query = query.filter_by(company_id=company_id)
            
            cumulative_query = Document.query.filter(
                Document.created_at <= date_end
            )
            if company_id:
                cumulative_query = cumulative_query.filter_by(company_id=company_id)
            
            daily_data.append({
                'date': date_start.isoformat(),
                'created': query.count(),
                'cumulative': cumulative_query.count()
            })
        
        return daily_data
    
    def get_compliance_analytics(self, db, company_id=None):
        """Get compliance-related analytics"""
        from models import Document
        
        query = Document.query
        if company_id:
            query = query.filter_by(company_id=company_id)
        
        has_expiry = query.filter(Document.expires_at.isnot(None)).count()
        expired = query.filter(Document.expires_at < datetime.utcnow()).count()
        expiring_soon = query.filter(
            Document.expires_at > datetime.utcnow(),
            Document.expires_at <= datetime.utcnow() + timedelta(days=30)
        ).count()
        
        confidential = query.filter_by(is_confidential=True).count()
        requires_approval = query.filter_by(requires_approval=True).count()
        
        return {
            'success': True,
            'compliance': {
                'has_expiry': has_expiry,
                'expired': expired,
                'expiring_soon': expiring_soon,
                'confidential': confidential,
                'requires_approval': requires_approval,
                'compliance_rate': round((has_expiry - expired) / has_expiry * 100 if has_expiry > 0 else 100, 1)
            }
        }
    
    def get_user_activity_report(self, db, user_id, days=30):
        """Get detailed user activity report"""
        from models import Document, DocumentComment, DocumentAuditLog
        
        since = datetime.utcnow() - timedelta(days=days)
        
        created = Document.query.filter_by(
            created_by=user_id
        ).filter(
            Document.created_at >= since
        ).count()
        
        updated = Document.query.filter(
            Document.updated_by == user_id,
            Document.updated_at >= since
        ).count()
        
        comments = DocumentComment.query.filter_by(
            user_id=user_id
        ).filter(
            DocumentComment.created_at >= since
        ).count()
        
        actions = DocumentAuditLog.query.filter_by(
            user_id=user_id
        ).filter(
            DocumentAuditLog.created_at >= since
        ).count()
        
        return {
            'success': True,
            'user_activity': {
                'documents_created': created,
                'documents_updated': updated,
                'comments_made': comments,
                'actions_performed': actions,
                'total_activity': created + updated + comments + actions
            }
        }


