# ============================================================

class ApprovalService:
    """Document Approval Service"""
    
    def __init__(self):
        self.timeout_check_interval = 3600
    
    def create_approval_from_chain(self, db, document_id, chain_id, submitted_by, notes=''):
        """Create a document approval from an approval chain"""
        from models import DocumentApproval, ApprovalStepStatus, ApprovalChain
        
        existing = DocumentApproval.query.filter_by(
            document_id=document_id,
            status='pending'
        ).first()
        
        if existing:
            return {'success': False, 'error': 'Approval already in progress'}
        
        chain = ApprovalChain.query.get(chain_id)
        if not chain:
            return {'success': False, 'error': 'Approval chain not found'}
        
        if not chain.steps:
            return {'success': False, 'error': 'Approval chain has no steps'}
        
        approval = DocumentApproval(
            document_id=document_id,
            chain_id=chain_id,
            status='pending',
            current_step=0,
            submitted_by=submitted_by,
            notes=notes,
            started_at=datetime.utcnow()
        )
        db.session.add(approval)
        db.session.flush()
        
        for step in chain.steps:
            step_status = ApprovalStepStatus(
                approval_id=approval.id,
                step_id=step.id,
                status='pending',
                assigned_to=self._get_assignee_for_step(step)
            )
            db.session.add(step_status)
        
        first_step = chain.steps[0]
        if self._can_auto_start_step(first_step):
            step_status = ApprovalStepStatus.query.filter_by(
                approval_id=approval.id,
                step_id=first_step.id
            ).first()
            if step_status:
                step_status.status = 'in_progress'
                step_status.started_at = datetime.utcnow()
                approval.status = 'in_progress'
        
        db.session.commit()
        
        return {'success': True, 'approval': approval}
    
    def _get_assignee_for_step(self, step):
        """Get the assignee for a step based on assignee type"""
        if step.assignee_type == 'user':
            return step.assignee_id
        elif step.assignee_type == 'role':
            from models import User
            user = User.query.filter_by(role=step.assignee_name).first()
            return user.id if user else None
        elif step.assignee_type == 'department':
            from models import User, Department
            dept = Department.query.get(step.assignee_id)
            if dept:
                head = User.query.filter_by(
                    department_id=dept.id,
                    role='department_head'
                ).first()
                return head.id if head else None
        return None
    
    def _can_auto_start_step(self, step):
        """Check if a step can be auto-started"""
        if step.condition_type == 'always':
            return True
        return False
    
    def process_approval_action(self, db, approval_id, user_id, action, comment=''):
        """Process an approval action (approve/reject)"""
        from models import DocumentApproval, ApprovalStepStatus, Document
        
        approval = DocumentApproval.query.get(approval_id)
        if not approval:
            return {'success': False, 'error': 'Approval not found'}
        
        if approval.status in ['approved', 'rejected', 'cancelled']:
            return {'success': False, 'error': f'Approval already {approval.status}'}
        
        current_step_status = ApprovalStepStatus.query.filter_by(
            approval_id=approval.id,
            step_id=approval.current_step
        ).first()
        
        if not current_step_status:
            return {'success': False, 'error': 'Current step not found'}
        
        if current_step_status.assigned_to != user_id:
            return {'success': False, 'error': 'You are not assigned to this approval step'}
        
        if action == 'approve':
            current_step_status.status = 'approved'
            current_step_status.comment = comment
            current_step_status.completed_at = datetime.utcnow()
            
            if self._move_to_next_step(approval):
                if self._is_approval_complete(approval):
                    approval.status = 'approved'
                    approval.approved_at = datetime.utcnow()
                    approval.completed_at = datetime.utcnow()
                    
                    doc = Document.query.get(approval.document_id)
                    if doc:
                        doc.status = 'approved'
                
        elif action == 'reject':
            current_step_status.status = 'rejected'
            current_step_status.comment = comment
            current_step_status.completed_at = datetime.utcnow()
            
            approval.status = 'rejected'
            approval.rejected_at = datetime.utcnow()
            approval.completed_at = datetime.utcnow()
            
            doc = Document.query.get(approval.document_id)
            if doc:
                doc.status = 'rejected'
        
        db.session.commit()
        
        return {'success': True, 'approval': approval}
    
    def _move_to_next_step(self, approval):
        """Move approval to the next step"""
        from models import ApprovalStepStatus
        
        current_step = approval.current_step
        next_step = current_step + 1
        
        chain = approval.chain
        steps = chain.steps
        
        if next_step < len(steps):
            approval.current_step = next_step
            
            next_step_status = ApprovalStepStatus.query.filter_by(
                approval_id=approval.id,
                step_id=steps[next_step].id
            ).first()
            
            if next_step_status:
                next_step_status.status = 'in_progress'
                next_step_status.started_at = datetime.utcnow()
            
            return True
        else:
            return False
    
    def _is_approval_complete(self, approval):
        """Check if all steps are approved"""
        from models import ApprovalStepStatus
        
        step_statuses = ApprovalStepStatus.query.filter_by(approval_id=approval.id).all()
        return all(s.status == 'approved' for s in step_statuses)
    
    def check_timeouts(self, db):
        """Check for timed out approval steps and handle escalations"""
        from models import ApprovalStepStatus
        
        now = datetime.utcnow()
        
        timeout_steps = ApprovalStepStatus.query.filter(
            ApprovalStepStatus.status == 'in_progress',
            ApprovalStepStatus.started_at <= now - timedelta(hours=24)
        ).all()
        
        for step_status in timeout_steps:
            step = step_status.step
            if step and step.escalation_days:
                escalation_time = step_status.started_at + timedelta(days=step.escalation_days)
                if now >= escalation_time:
                    step_status.status = 'escalated'
                    step_status.escalated_at = now
                    if step.escalation_user_id:
                        step_status.assigned_to = step.escalation_user_id
        
        db.session.commit()
        return {'success': True, 'processed': len(timeout_steps)}


# Initialize service
approval_service = ApprovalService()

