@app.route('/api/documents/ocr', methods=['POST', 'OPTIONS'])
@cross_origin()
@jwt_required
def perform_ocr():
    """Perform OCR on uploaded document"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ REMOVE or FIX the plan check for OCR
        # OCR should work for enterprise plan
        if not is_super_admin:
            # Check if user has OCR access - allow enterprise users
            plan = getattr(current_user, 'subscription_plan', 'free')
            if plan not in ['enterprise', 'business', 'pro']:
                return jsonify({
                    'success': False,
                    'error': 'OCR feature not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE',
                    'required_plan': 'business',
                    'current_plan': plan
                }), 403
        
        if 'file' not in request.files:
            return jsonify({
                'success': False,
                'error': 'No file uploaded',
                'code': 'MISSING_FILE'
            }), 400
        
        file = request.files['file']
        if file.filename == '':
            return jsonify({
                'success': False,
                'error': 'No file selected',
                'code': 'EMPTY_FILE'
            }), 400
        
        # Validate file extension
        allowed_extensions = ['.pdf', '.jpg', '.jpeg', '.png', '.tiff', '.bmp', '.gif']
        filename = secure_filename(file.filename)
        file_ext = os.path.splitext(filename)[1].lower()
        
        if file_ext not in allowed_extensions:
            return jsonify({
                'success': False,
                'error': f'Unsupported file type. Supported: {", ".join(allowed_extensions)}',
                'code': 'INVALID_FILE_TYPE'
            }), 400
        
        # Create temp directory
        temp_dir = tempfile.mkdtemp()
        temp_path = os.path.join(temp_dir, filename)
        file.save(temp_path)
        
        try:
            # Check if OCR service is available
            if not ocr_service.is_available():
                return jsonify({
                    'success': False,
                    'error': 'OCR service is not available. Please install Tesseract.',
                    'code': 'OCR_UNAVAILABLE',
                    'details': 'Tesseract not found. Install from: https://github.com/tesseract-ocr/tesseract'
                }), 503
            
            # Process file based on type
            start_time = time.time()
            
            if file_ext == '.pdf':
                result = ocr_service.extract_text_from_pdf(temp_path)
            else:
                result = ocr_service.extract_text_from_image(temp_path)
            
            processing_time = time.time() - start_time
            
            if result.get('success'):
                # Extract structured data
                structured_data = ocr_service.extract_structured_data(result.get('text', ''))
                language = ocr_service.detect_language(result.get('text', ''))
                
                # Also try to save OCR result to document if document_id provided
                document_id = request.form.get('document_id')
                if document_id:
                    try:
                        from models import Document
                        doc = Document.query.get(int(document_id))
                        if doc:
                            doc.ocr_text = result.get('text', '')
                            doc.ocr_confidence = result.get('confidence', 0)
                            doc.ocr_processed_at = datetime.utcnow()
                            db.session.commit()
                    except Exception as save_error:
                        current_app.logger.warning(f"Could not save OCR to document: {save_error}")
                
                return jsonify({
                    'success': True,
                    'result': {
                        'text': result.get('text', ''),
                        'word_count': result.get('word_count', 0),
                        'char_count': result.get('char_count', 0),
                        'page_count': result.get('page_count', 1),
                        'confidence': result.get('confidence', 0),
                        'language': language,
                        'structured_data': structured_data,
                        'filename': filename,
                        'file_type': file_ext[1:],
                        'file_size': os.path.getsize(temp_path),
                        'processing_time': round(processing_time, 2),
                        'pages': result.get('pages', [])
                    }
                }), 200
            else:
                return jsonify({
                    'success': False,
                    'error': result.get('error', 'OCR processing failed'),
                    'code': 'OCR_FAILED'
                }), 500
                
        except Exception as e:
            current_app.logger.error(f"OCR processing error: {str(e)}", exc_info=True)
            return jsonify({
                'success': False,
                'error': str(e),
                'code': 'PROCESSING_ERROR'
            }), 500
        finally:
            # Clean up temp files
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
                if os.path.exists(temp_dir):
                    os.rmdir(temp_dir)
            except Exception:
                pass
        
    except Exception as e:
        current_app.logger.error(f"OCR route error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e),
            'code': 'INTERNAL_ERROR'
        }), 500



@app.route('/api/documents/ocr/search', methods=['POST', 'OPTIONS'])
@cross_origin()
@jwt_required
def ocr_search():
    """Search within OCR text"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        data = request.get_json()
        if not data:
            return jsonify({
                'success': False,
                'error': 'Missing request body',
                'code': 'MISSING_BODY'
            }), 400
        
        query = data.get('query', '').strip()
        text = data.get('text', '').strip()
        
        if not query:
            return jsonify({
                'success': False,
                'error': 'Search query is required',
                'code': 'MISSING_QUERY'
            }), 400
        
        if not text:
            return jsonify({
                'success': False,
                'error': 'Text to search is required',
                'code': 'MISSING_TEXT'
            }), 400
        
        query_lower = query.lower()
        text_lower = text.lower()
        
        matches = []
        start = 0
        while True:
            index = text_lower.find(query_lower, start)
            if index == -1:
                break
            
            # Get context around match
            context_start = max(0, index - 50)
            context_end = min(len(text), index + len(query) + 50)
            context = text[context_start:context_end]
            
            # Get line number
            line_number = text[:index].count('\n') + 1
            
            matches.append({
                'position': index,
                'context': context,
                'highlight': text[index:index + len(query)],
                'line': line_number,
                'start': index,
                'end': index + len(query)
            })
            
            start = index + len(query)
        
        return jsonify({
            'success': True,
            'matches': matches,
            'count': len(matches)
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"OCR search error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e),
            'code': 'INTERNAL_ERROR'
        }), 500

@app.route('/api/documents/ocr/status/<document_id>', methods=['GET', 'OPTIONS'])
@cross_origin()
@jwt_required
def get_ocr_status(document_id):
    """Get OCR status for a document"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import Document
        import uuid
        
        # Parse document ID - support both integer and UUID
        try:
            doc_id_int = int(document_id)
            id_filter = Document.id == doc_id_int
        except ValueError:
            try:
                doc_uuid = uuid.UUID(document_id)
                id_filter = Document.id == doc_uuid
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid document ID format',
                    'code': 'INVALID_ID'
                }), 400
        
        # Get document
        if is_super_admin:
            document = Document.query.filter(id_filter).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter(
                    id_filter,
                    Document.company_id == user_company_id
                ).first()
            else:
                document = Document.query.filter(
                    id_filter,
                    Document.user_id == current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # Check if document has OCR data
        has_ocr = hasattr(document, 'ocr_text') and document.ocr_text is not None
        
        return jsonify({
            'success': True,
            'has_ocr': has_ocr,
            'ocr_text': document.ocr_text if has_ocr else None,
            'ocr_confidence': document.ocr_confidence if has_ocr else None,
            'ocr_processed_at': document.ocr_processed_at.isoformat() if has_ocr and hasattr(document, 'ocr_processed_at') and document.ocr_processed_at else None,
            'document_id': document.id,
            'document_title': document.title
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"OCR status error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e),
            'code': 'INTERNAL_ERROR'
        }), 500

