@app.route('/api/documents/expiration/stats', methods=['GET', 'OPTIONS'])
@cross_origin()
@jwt_required
def get_expiration_stats():
    """Get expiration statistics"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import DocumentExpiration
        from datetime import timedelta
        
        now = datetime.utcnow()
        
        if is_super_admin:
            query = DocumentExpiration.query
        else:
            query = DocumentExpiration.query.join(Document).filter(
                Document.company_id == current_user.company_id
            )
        
        total = query.count()
        expired = query.filter(
            DocumentExpiration.expires_at < now,
            DocumentExpiration.status != 'completed'
        ).count()
        
        expiring_soon = query.filter(
            DocumentExpiration.expires_at > now,
            DocumentExpiration.expires_at <= now + timedelta(days=30),
            DocumentExpiration.status != 'completed'
        ).count()
        
        active = total - expired - expiring_soon
        
        return jsonify({
            'success': True,
            'stats': {
                'total': total,
                'active': active,
                'expiring_soon': expiring_soon,
                'expired': expired,
                'completed': query.filter_by(status='completed').count()
            }
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Get expiration stats error: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/documents/overdue', methods=['GET', 'OPTIONS'])
@cross_origin()
@jwt_required
def get_overdue_documents():
    """Get overdue and expiring soon documents"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import Document
        from datetime import timedelta
        
        now = datetime.utcnow()
        
        if is_super_admin:
            query = Document.query
        else:
            query = Document.query.filter_by(company_id=current_user.company_id)
        
        overdue = query.filter(
            Document.expires_at < now,
            Document.status != 'archived'
        ).all()
        
        expiring_soon = query.filter(
            Document.expires_at > now,
            Document.expires_at <= now + timedelta(days=30),
            Document.status != 'archived'
        ).all()
        
        overdue_list = []
        for doc in overdue:
            doc_dict = doc.to_dict()
            doc_dict['days_until_expiry'] = (doc.expires_at - now).days if doc.expires_at else None
            overdue_list.append(doc_dict)
        
        expiring_list = []
        for doc in expiring_soon:
            doc_dict = doc.to_dict()
            doc_dict['days_until_expiry'] = (doc.expires_at - now).days if doc.expires_at else None
            expiring_list.append(doc_dict)
        
        return jsonify({
            'success': True,
            'overdue': overdue_list,
            'expiring_soon': expiring_list,
            'overdue_count': len(overdue_list),
            'expiring_soon_count': len(expiring_list)
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Overdue documents error: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/documents/expiration/check', methods=['POST', 'OPTIONS'])
@cross_origin()
@jwt_required
def check_expiration_notifications():
    """Check and send expiration notifications (scheduled job)"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        if not is_super_admin:
            return jsonify({
                'success': False,
                'error': 'Only super admins can run this job'
            }), 403
        
        from models import DocumentExpiration, ExpirationNotificationLog
        from datetime import timedelta
        
        now = datetime.utcnow()
        notifications_sent = 0
        
        expirations = DocumentExpiration.query.filter(
            DocumentExpiration.status != 'completed'
        ).all()
        
        for expiration in expirations:
            if expiration.is_expired() and expiration.status != 'expired':
                expiration.status = 'expired'
                notifications_sent += 1
                
                log = ExpirationNotificationLog(
                    expiration_id=expiration.id,
                    notification_type='expired',
                    sent_to=expiration.assignee.name if expiration.assignee else 'Unknown',
                    sent_via='system',
                    subject=f'Document Expired: {expiration.document.title}',
                    content=f'The document "{expiration.document.title}" has expired on {expiration.expires_at.strftime("%Y-%m-%d")}.'
                )
                db.session.add(log)
                
            elif expiration.is_expiring_soon():
                days = expiration.get_days_until_expiry()
                
                if not expiration.last_notification_sent or \
                   (now - expiration.last_notification_sent).days > 7:
                    
                    notifications_sent += 1
                    expiration.last_notification_sent = now
                    
                    if not expiration.notifications_sent:
                        expiration.notifications_sent = []
                    expiration.notifications_sent.append({
                        'date': now.isoformat(),
                        'type': 'warning',
                        'days_remaining': days
                    })
                    
                    log = ExpirationNotificationLog(
                        expiration_id=expiration.id,
                        notification_type='warning',
                        sent_to=expiration.assignee.name if expiration.assignee else 'Unknown',
                        sent_via='system',
                        subject=f'Document Expiring Soon: {expiration.document.title}',
                        content=f'The document "{expiration.document.title}" will expire in {days} days.'
                    )
                    db.session.add(log)
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'notifications_sent': notifications_sent,
            'message': f'Processed {len(expirations)} expirations, sent {notifications_sent} notifications'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Check expiration error: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


