@app.route('/api/documents/compare', methods=['POST', 'OPTIONS'])
@cross_origin()
@jwt_required
def compare_documents():
    """Compare two documents"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        data = request.get_json()
        if not data:
            return jsonify({
                'success': False,
                'error': 'No data provided'
            }), 400
        
        doc1_id = data.get('document1_id')
        doc2_id = data.get('document2_id')
        
        if not doc1_id or not doc2_id:
            return jsonify({
                'success': False,
                'error': 'Both document IDs are required'
            }), 400
        
        from models import Document
        
        if is_super_admin:
            doc1 = Document.query.get(doc1_id)
            doc2 = Document.query.get(doc2_id)
        else:
            doc1 = Document.query.filter_by(
                id=doc1_id, 
                company_id=current_user.company_id
            ).first()
            doc2 = Document.query.filter_by(
                id=doc2_id, 
                company_id=current_user.company_id
            ).first()
        
        if not doc1 or not doc2:
            return jsonify({
                'success': False,
                'error': 'One or both documents not found'
            }), 404
        
        content1 = doc1.content or doc1.file_content or ''
        content2 = doc2.content or doc2.file_content or ''
        
        result = document_comparison.compare_documents(
            content1, 
            content2,
            {'title': doc1.title, 'version': doc1.version},
            {'title': doc2.title, 'version': doc2.version}
        )
        
        result['document1'] = {
            'id': doc1.id,
            'title': doc1.title,
            'version': doc1.version,
            'status': doc1.status,
            'updated_at': doc1.updated_at.isoformat() if doc1.updated_at else None
        }
        result['document2'] = {
            'id': doc2.id,
            'title': doc2.title,
            'version': doc2.version,
            'status': doc2.status,
            'updated_at': doc2.updated_at.isoformat() if doc2.updated_at else None
        }
        
        return jsonify(result), 200
        
    except Exception as e:
        current_app.logger.error(f"Document comparison error: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


