@app.route('/api/documents/audit', methods=['GET', 'OPTIONS'])
@cross_origin()
@jwt_required
def get_audit_logs():
    """Get audit logs"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import DocumentAuditLog, Document
        
        document_id = request.args.get('document_id')
        action = request.args.get('action')
        limit = request.args.get('limit', 100, type=int)
        offset = request.args.get('offset', 0, type=int)
        
        if is_super_admin:
            query = DocumentAuditLog.query
        else:
            # ✅ Get company documents first
            company_docs = Document.query.filter_by(company_id=current_user.company_id).all()
            doc_ids = [doc.id for doc in company_docs]
            if doc_ids:
                query = DocumentAuditLog.query.filter(DocumentAuditLog.document_id.in_(doc_ids))
            else:
                query = DocumentAuditLog.query.filter(False)  # No documents, return empty
        
        # ✅ Handle document_id filtering (supports both integer and UUID)
        if document_id and document_id != 'null' and document_id != '':
            try:
                # Try as integer first
                doc_int = int(document_id)
                query = query.filter(DocumentAuditLog.document_id == doc_int)
            except ValueError:
                try:
                    # Try as UUID string
                    doc_uuid = uuid.UUID(document_id)
                    # Convert UUID to integer ID if your documents use integer IDs
                    # If documents use UUID as string, you need to find the document
                    doc = Document.query.filter_by(id=doc_uuid).first()
                    if doc:
                        query = query.filter(DocumentAuditLog.document_id == doc.id)
                except ValueError:
                    pass
        
        if action and action != 'all':
            query = query.filter_by(action=action)
        
        # Order and pagination
        query = query.order_by(DocumentAuditLog.created_at.desc())
        total = query.count()
        logs = query.offset(offset).limit(limit).all()
        
        return jsonify({
            'success': True,
            'logs': [log.to_dict() for log in logs],
            'total': total,
            'limit': limit,
            'offset': offset,
            'has_more': offset + limit < total
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Audit logs error: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500



