@app.route('/api/documents/pending-approvals', methods=['GET'])
@cross_origin()
@jwt_required
def get_pending_approvals_chain():
    """Get pending approvals for current user"""
    try:
        current_user = request.user
        
        from models import DocumentApproval, ApprovalStepStatus
        
        # Get approvals where current user is assigned to a pending/in_progress step
        pending_approvals = []
        
        # Find all approvals with status pending or in_progress
        approvals = DocumentApproval.query.filter(
            DocumentApproval.status.in_(['pending', 'in_progress'])
        ).all()
        
        for approval in approvals:
            # Check if current user is assigned to the current step
            if approval.current_step is not None:
                # Get the current step status
                step_status = ApprovalStepStatus.query.filter_by(
                    approval_id=approval.id,
                    status='in_progress'
                ).first()
                
                if step_status and step_status.assigned_to == current_user.id:
                    pending_approvals.append(approval)
                elif not step_status:
                    # If no in_progress step, check pending steps
                    pending_step = ApprovalStepStatus.query.filter_by(
                        approval_id=approval.id,
                        status='pending'
                    ).order_by(ApprovalStepStatus.id).first()
                    
                    if pending_step and pending_step.assigned_to == current_user.id:
                        pending_approvals.append(approval)
        
        return jsonify({
            'success': True,
            'approvals': [a.to_dict() for a in pending_approvals],
            'total': len(pending_approvals)
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error getting pending approvals: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/documents/approval-chains', methods=['POST'])
@cross_origin()
@jwt_required
def create_approval_chain():
    """Create a new approval chain"""
    try:
        current_user = request.user
        data = request.get_json()
        
        from models import ApprovalChain, ApprovalStep
        
        if not data.get('name'):
            return jsonify({
                'success': False,
                'error': 'Chain name is required'
            }), 400
        
        chain = ApprovalChain(
            name=data.get('name'),
            description=data.get('description', ''),
            document_type=data.get('document_type'),
            module=data.get('module', 'general'),
            is_active=data.get('is_active', True),
            is_default=data.get('is_default', False),
            company_id=current_user.company_id if hasattr(current_user, 'company_id') else None,
            created_by=current_user.id
        )
        db.session.add(chain)
        db.session.flush()
        
        # ✅ Add steps with correct column names
        steps = data.get('steps', [])
        for i, step_data in enumerate(steps):
            step = ApprovalStep(
                chain_id=chain.id,
                step_number=i + 1,  # ✅ Use step_number (1-indexed for display)
                name=step_data.get('name', f'Step {i+1}'),
                description=step_data.get('description', ''),
                approval_type=step_data.get('approval_type', 'sequential'),
                assignee_type=step_data.get('assignee_type', 'role'),
                assignee_id=step_data.get('assignee_id'),
                assignee_name=step_data.get('assignee_name'),
                requires_comment=step_data.get('requires_comment', False),
                timeout_days=step_data.get('timeout_days', 7),
                escalation_days=step_data.get('escalation_days'),
                escalation_user_id=step_data.get('escalation_user_id'),
                is_mandatory=step_data.get('is_mandatory', True),
                condition_type=step_data.get('condition_type'),
                condition_value=step_data.get('condition_value')
                # can_skip is not in the model - remove it
            )
            db.session.add(step)
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'chain': chain.to_dict()
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error creating approval chain: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


