@app.route('/api/ai/html/preview/<document_id>', methods=['GET'])
@jwt_required
@cross_origin()
def preview_html_document_by_id(document_id: str):
    """Preview HTML document by ID - With dedicated HTML stylist"""
    try:
        # Get module reference for global variables
        import sys
        current_module = sys.modules[__name__]
        
        # SUPER ADMIN DETECTION
        is_super_admin = check_super_admin()
        current_app.logger.info(f"HTML preview by ID - User: {request.user.email if hasattr(request, 'user') else 'Unknown'}, Super admin: {is_super_admin}")
        
        # Get HTML template engine from module
        html_engine = getattr(current_module, 'html_template_engine', None)
        
        # SUPER ADMIN: BYPASS ALL CHECKS
        if is_super_admin:
            current_app.logger.info(f"🔓 SUPER ADMIN FULL ACCESS - Preview by ID for {document_id}")
            
            # Initialize engine if needed
            if not html_engine:
                init_result = initialize_html_template_engine()
                if not init_result:
                    return jsonify({
                        'success': False,
                        'error': 'HTML Template Engine initialization failed',
                        'code': 'ENGINE_INIT_FAILED',
                        'timestamp': datetime.now().isoformat()
                    }), 503
                # Refresh the reference after initialization
                html_engine = getattr(current_module, 'html_template_engine', None)
            
            # Try to get document from storage
            document_content = None
            metadata = None
            
            try:
                if hasattr(html_engine, 'storage_manager') and html_engine.storage_manager:
                    document_content = html_engine.storage_manager.get_export(
                        document_id=document_id,
                        format_type='html'
                    )
                    
                    # Try to get metadata if method exists
                    if hasattr(html_engine.storage_manager, 'get_metadata'):
                        metadata = html_engine.storage_manager.get_metadata(document_id)
            except Exception as e:
                logger.warning(f"Error accessing storage: {e}")
                document_content = None
                metadata = None
            
            if not document_content:
                # Return a default preview
                default_html = f"""
                <!DOCTYPE html>
                <html>
                <head>
                    <title>Document Preview - {document_id}</title>
                    <style>
                        body {{ font-family: Arial, sans-serif; margin: 40px; line-height: 1.6; }}
                        .info-box {{ background-color: #f0f8ff; border-left: 4px solid #1E3D58; padding: 20px; margin: 20px 0; }}
                        h1 {{ color: #1E3D58; }}
                        .metadata {{ background-color: #f5f5f5; padding: 15px; border-radius: 5px; overflow-x: auto; }}
                        pre {{ margin: 0; }}
                        .note {{ color: #666; font-style: italic; }}
                    </style>
                </head>
                <body>
                    <h1>Document Preview: {document_id}</h1>
                    <div class="info-box">
                        <p><strong>This is a super admin preview</strong></p>
                        <p>Document ID: <code>{document_id}</code></p>
                        <p>The document could not be found in storage, but super admin bypass is active.</p>
                    </div>
                    
                    <h2>Metadata:</h2>
                    <div class="metadata">
                        <pre>{json.dumps(metadata, indent=2, default=str) if metadata else 'No metadata available'}</pre>
                    </div>
                    
                    <h2>Access Information:</h2>
                    <div class="metadata">
                        <pre>{{
    "access_level": "super_admin_full_access",
    "is_super_admin": true,
    "bypassed_checks": ["document_exists_check", "ownership_check"]
}}</pre>
                    </div>
                    
                    <p class="note">Generated at: {datetime.now().isoformat()}</p>
                </body>
                </html>
                """
                
                return jsonify({
                    'success': True,
                    'preview': default_html,
                    'document_id': document_id,
                    'note': 'Document not found in storage - showing default preview',
                    'access_info': {
                        'access_level': 'super_admin_full_access',
                        'is_super_admin': True,
                        'bypassed_checks': ['document_exists_check', 'ownership_check']
                    },
                    'timestamp': datetime.now().isoformat()
                })
            
            # Return the actual document
            return jsonify({
                'success': True,
                'preview': document_content.decode('utf-8') if isinstance(document_content, bytes) else document_content,
                'document_id': document_id,
                'metadata': metadata,
                'access_info': {
                    'access_level': 'super_admin_full_access',
                    'is_super_admin': True,
                    'bypassed_checks': ['ownership_check', 'download_limit_check']
                },
                'timestamp': datetime.now().isoformat()
            })
        
        # ===== REGULAR USER FLOW =====
        # Initialize engine if needed
        if not html_engine:
            init_result = initialize_html_template_engine()
            if not init_result:
                return jsonify({
                    'success': False,
                    'error': 'HTML Template Engine initialization failed',
                    'code': 'ENGINE_INIT_FAILED',
                    'timestamp': datetime.now().isoformat()
                }), 503
            # Refresh the reference after initialization
            html_engine = getattr(current_module, 'html_template_engine', None)
        
        # Check if storage manager is available
        if not hasattr(html_engine, 'storage_manager') or not html_engine.storage_manager:
            return jsonify({
                'success': False,
                'error': 'Storage manager not available',
                'code': 'STORAGE_UNAVAILABLE',
                'timestamp': datetime.now().isoformat()
            }), 503
        
        # Get document from storage
        document_content = None
        metadata = None
        
        try:
            document_content = html_engine.storage_manager.get_export(
                document_id=document_id,
                format_type='html'
            )
            
            # Try to get metadata if method exists
            if hasattr(html_engine.storage_manager, 'get_metadata'):
                metadata = html_engine.storage_manager.get_metadata(document_id)
        except Exception as e:
            logger.error(f"Error retrieving document: {e}")
            return jsonify({
                'success': False,
                'error': f'Error retrieving document: {str(e)}',
                'code': 'RETRIEVAL_ERROR',
                'timestamp': datetime.now().isoformat()
            }), 500
        
        if not document_content:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND',
                'timestamp': datetime.now().isoformat()
            }), 404
        
        # Check ownership (if metadata has user_id)
        current_user_id = get_jwt_identity()
        if metadata and metadata.get('user_id') and metadata.get('user_id') != current_user_id:
            logger.warning(f"Access denied: User {current_user_id} attempted to access document {document_id} owned by {metadata.get('user_id')}")
            return jsonify({
                'success': False,
                'error': 'You do not have permission to view this document',
                'code': 'ACCESS_DENIED',
                'timestamp': datetime.now().isoformat()
            }), 403
        
        # Decode content if needed
        preview_content = document_content
        if isinstance(document_content, bytes):
            try:
                preview_content = document_content.decode('utf-8')
            except UnicodeDecodeError:
                # If it's not UTF-8 text, return as base64
                import base64
                preview_content = base64.b64encode(document_content).decode('utf-8')
                return jsonify({
                    'success': True,
                    'preview_base64': preview_content,
                    'document_id': document_id,
                    'metadata': metadata,
                    'content_type': 'base64',
                    'note': 'Content is binary and returned as base64',
                    'access_info': {
                        'access_level': 'regular_user',
                        'is_super_admin': False
                    },
                    'timestamp': datetime.now().isoformat()
                })
        
        return jsonify({
            'success': True,
            'preview': preview_content,
            'document_id': document_id,
            'metadata': metadata,
            'content_type': 'html',
            'access_info': {
                'access_level': 'regular_user',
                'is_super_admin': False
            },
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        logger.error(f"HTML preview by ID endpoint error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to get HTML preview: {str(e)}',
            'code': 'PREVIEW_FETCH_ERROR',
            'suggestion': 'Please check the document ID and try again',
            'timestamp': datetime.now().isoformat()
        }), 500


