def make_content_fillable(content):
    """Make content fillable by adding contenteditable attributes and placeholders"""
    import re
    
    # Add contenteditable="true" to all table cells
    content = re.sub(r'<td([^>]*)>', r'<td\1 contenteditable="true">', content)
    
    # Add contenteditable to empty list items
    content = re.sub(r'<li([^>]*)>', r'<li\1 contenteditable="true">', content)
    
    # Add placeholders for signature lines
    content = re.sub(r'_{10,}', r'<span contenteditable="true" style="min-width:150px; display:inline-block; border-bottom:2px solid #999; color:#999; padding:2px 4px;">Enter name</span>', content)
    
    # Add placeholders for dates
    content = re.sub(r'__/__/____', r'<span contenteditable="true" style="min-width:100px; display:inline-block; border-bottom:1px solid #999; color:#999; padding:2px 4px;">MM/DD/YYYY</span>', content)
    content = re.sub(r'____-__-__', r'<span contenteditable="true" style="min-width:100px; display:inline-block; border-bottom:1px solid #999; color:#999; padding:2px 4px;">YYYY-MM-DD</span>', content)
    
    # Add data-placeholder to empty table cells
    content = re.sub(r'<td([^>]*?)contenteditable="true"([^>]*)>\s*</td>', r'<td\1contenteditable="true"\2 data-placeholder="Click to add..."><span style="color:#999; font-style:italic;">Click to add...</span></td>', content)
    
    # Add template badge to section titles
    content = re.sub(r'<h2>', r'<h2><span style="background:#F39C12; color:white; padding:2px 12px; border-radius:12px; font-size:12px; font-weight:600; text-transform:uppercase; margin-right:10px;">📋 TEMPLATE</span> ', content)
    
    return content


