@app.route('/api/v1/ai/documents/pdf/download', methods=['POST'])
@jwt_required
@cross_origin()
def download_pdf_document():
    """
    Download PDF version of a previously generated HTML document
    
    FLEXIBLE ENDPOINT - Accepts various payload formats:
    - {"pdf_document_id": "5EBBC7E2F269"}
    - {"document_id": "5EBBC7E2F269"}
    - {"id": "5EBBC7E2F269"}
    - "5EBBC7E2F269" (raw string)
    """
    import json
    from datetime import datetime
    from bs4 import BeautifulSoup  # Add this import
    
    request_id = datetime.now().strftime('%Y%m%d%H%M%S%f')[:-3]
    
    print(f"\n{'='*80}")
    print(f"📄 PDF DOWNLOAD DEBUG [{request_id}]")
    print(f"{'='*80}")
    
    try:
        # SUPER ADMIN DETECTION
        is_super_admin = check_super_admin()
        current_app.logger.info(f"📄 PDF download request [{request_id}] - Super admin: {is_super_admin}")
        
        # Get request data
        data = request.get_json()
        
        print(f"\n📦 RAW REQUEST DATA [{request_id}]:")
        print(f"  Type: {type(data)}")
        print(f"  Content: {json.dumps(data, indent=2) if data else 'None'}")
        print(f"  Keys: {list(data.keys()) if isinstance(data, dict) else 'N/A'}")
        
        if not data:
            print(f"❌ [{request_id}] No JSON data provided")
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA_PROVIDED',
                'debug': {'request_id': request_id}
            }), 400
        
        # ========== FLEXIBLE ID DETECTION ==========
        document_id = None
        extraction_method = None
        
        # CASE 1: Direct string in payload
        if isinstance(data, str):
            document_id = data
            extraction_method = 'direct_string'
            print(f"✅ [{request_id}] Extracted ID from direct string: {document_id}")
        
        # CASE 2: Standard field names
        elif isinstance(data, dict):
            # Check common field names
            for field in ['pdf_document_id', 'document_id', 'id', 'doc_id', 'documentId', 'pdfId']:
                if field in data and data[field]:
                    document_id = data[field]
                    extraction_method = f'field_{field}'
                    print(f"✅ [{request_id}] Extracted ID from field '{field}': {document_id}")
                    break
            
            # CASE 3: Check if this is a generation response (has doc_type, industry, etc.)
            if not document_id and 'doc_type' in data and 'requirements' in data:
                print(f"🔍 [{request_id}] This appears to be a generation request, not a download request")
                print(f"    The frontend is sending a generation payload to the download endpoint!")
                print(f"    Please use the generation endpoint first to get a document ID.")
                return jsonify({
                    'success': False,
                    'error': 'Please generate the document first to get an ID',
                    'code': 'USE_GENERATION_ENDPOINT_FIRST',
                    'debug': {'request_id': request_id}
                }), 400
        
        # CASE 4: No ID found
        if not document_id:
            print(f"❌ [{request_id}] No document ID found in payload")
            print(f"    Attempted fields: pdf_document_id, document_id, id, doc_id, documentId, pdfId")
            return jsonify({
                'success': False,
                'error': 'Missing document ID',
                'code': 'MISSING_DOCUMENT_ID',
                'debug': {
                    'request_id': request_id,
                    'received_type': str(type(data)),
                    'received_keys': list(data.keys()) if isinstance(data, dict) else None,
                    'received_preview': str(data)[:200] + '...' if len(str(data)) > 200 else str(data)
                }
            }), 400
        
        # Get format and filename
        format_type = 'pdf'
        if isinstance(data, dict):
            format_type = data.get('format', 'pdf')
            custom_filename = data.get('filename', f"{document_id}.{format_type}")
        else:
            custom_filename = f"{document_id}.pdf"
        
        print(f"\n📋 PROCESSING [{request_id}]:")
        print(f"  Document ID: {document_id}")
        print(f"  Extraction Method: {extraction_method}")
        print(f"  Format: {format_type}")
        print(f"  Filename: {custom_filename}")
        
        # Get storage manager
        storage = app.config.get('STORAGE_MANAGER')
        if not storage:
            from classes import StorageManager
            storage = StorageManager()
            app.config['STORAGE_MANAGER'] = storage
            print(f"✅ [{request_id}] Storage manager initialized")
        
        # ========== SEARCH FOR HTML FILE ==========
        print(f"\n🔍 SEARCHING FOR HTML FILE [{request_id}]:")
        
        # Possible locations to search
        search_paths = []
        html_path = None
        
        # Try different filename patterns
        filename_patterns = [
            f"{document_id}.html",
            f"{document_id}.HTML",
            f"{document_id}.htm",
            f"{document_id}_export.html",
            f"export_{document_id}.html",
            f"document_{document_id}.html"
        ]
        
        # Try different directories
        search_dirs = []
        if hasattr(storage, 'base_path'):
            search_dirs.append(storage.base_path)
            search_dirs.append(os.path.join(storage.base_path, 'exports'))
            search_dirs.append(os.path.join(storage.base_path, 'html'))
            search_dirs.append(os.path.join(storage.base_path, 'documents'))
        
        # Also check common paths
        common_paths = [
            os.path.join('hse_documents', 'exports'),
            os.path.join('hse_documents'),
            os.path.join('exports'),
            '.'
        ]
        
        for path in common_paths:
            if os.path.exists(path):
                search_dirs.append(os.path.abspath(path))
        
        # Search all combinations
        for directory in set(search_dirs):  # Use set to remove duplicates
            print(f"  📁 Checking directory: {directory}")
            for pattern in filename_patterns:
                full_path = os.path.join(directory, pattern)
                if os.path.exists(full_path):
                    html_path = full_path
                    print(f"  ✅ FOUND: {full_path}")
                    break
                else:
                    print(f"     ✗ Not found: {pattern}")
            if html_path:
                break
        
        # If still not found, try wildcard search
        if not html_path:
            print(f"\n🔍 PERFORMING WILDCARD SEARCH [{request_id}]...")
            for directory in set(search_dirs):
                if os.path.exists(directory):
                    for file in os.listdir(directory):
                        if file.endswith('.html') and document_id in file:
                            html_path = os.path.join(directory, file)
                            print(f"  ✅ FOUND via wildcard: {html_path}")
                            break
                    if html_path:
                        break
        
        if not html_path:
            print(f"\n❌ [{request_id}] HTML document not found!")
            return jsonify({
                'success': False,
                'error': f'HTML document not found: {document_id}',
                'code': 'DOCUMENT_NOT_FOUND',
                'debug': {
                    'request_id': request_id,
                    'searched_patterns': filename_patterns,
                    'searched_directories': search_dirs,
                    'document_id': document_id
                }
            }), 404
        
        # Read HTML file
        print(f"\n📖 READING HTML FILE [{request_id}]:")
        with open(html_path, 'r', encoding='utf-8') as f:
            html_content = f.read()
        
        print(f"  ✅ File size: {len(html_content)} bytes")
        print(f"  File path: {html_path}")
        
        # ========== SMART TABLE DETECTION ==========
        print(f"\n📊 ANALYZING TABLE STRUCTURE [{request_id}]:")
        
        # Parse HTML to check for wide tables
        soup = BeautifulSoup(html_content, 'html.parser')
        
        # Find all tables and count columns
        max_columns = 0
        table_count = 0
        wide_tables = 0
        
        for table in soup.find_all('table'):
            table_count += 1
            # Find the maximum number of columns in any row
            for row in table.find_all('tr')[:3]:  # Check first 3 rows
                cols = len(row.find_all(['th', 'td']))
                if cols > max_columns:
                    max_columns = cols
            if max_columns > 6:
                wide_tables += 1
        
        print(f"  Tables found: {table_count}")
        print(f"  Maximum columns: {max_columns}")
        print(f"  Wide tables (>6 cols): {wide_tables}")
        
        # ========== SMART PDF OPTIONS ==========
        pdf_options = {
            'zoom': 0.95  # Default zoom
        }
        
        if max_columns > 8:
            # Very wide tables - use A3 landscape
            pdf_options.update({
                'page_size': 'A3',
                'orientation': 'landscape',
                'zoom': 0.85,
                'margin_left': '15mm',
                'margin_right': '15mm'
            })
            print(f"  📐 Using A3 Landscape for very wide tables ({max_columns} cols)")
        elif max_columns > 6:
            # Wide tables - use A4 landscape
            pdf_options.update({
                'page_size': 'A4',
                'orientation': 'landscape',
                'zoom': 0.9,
                'margin_left': '15mm',
                'margin_right': '15mm'
            })
            print(f"  📐 Using A4 Landscape for wide tables ({max_columns} cols)")
        elif max_columns > 4:
            # Medium tables - use A4 portrait with smaller margins
            pdf_options.update({
                'page_size': 'A4',
                'orientation': 'portrait',
                'zoom': 0.95,
                'margin_left': '12mm',
                'margin_right': '12mm'
            })
            print(f"  📐 Using A4 Portrait with adjusted margins ({max_columns} cols)")
        else:
            # Normal tables - standard A4 portrait
            pdf_options.update({
                'page_size': 'A4',
                'orientation': 'portrait',
                'zoom': 1.0,
                'margin_left': '20mm',
                'margin_right': '20mm'
            })
            print(f"  📐 Using standard A4 Portrait ({max_columns} cols)")
        
        # Get or create converter
        converter = app.config.get('DOCUMENT_CONVERTER')
        if not converter:
            converter = ComprehensiveDocumentConverter(storage_manager=storage)
            app.config['DOCUMENT_CONVERTER'] = converter
            print(f"✅ [{request_id}] Converter initialized")
        
        # Handle different formats
        if format_type == 'pdf':
            print(f"\n🔄 CONVERTING TO PDF [{request_id}] with options: {pdf_options}")
            
            # Check if PDF is available
            if not converter.pdf_available:
                print(f"⚠️ [{request_id}] PDF not available, falling back to HTML")
                from flask import send_file
                import io
                return send_file(
                    io.BytesIO(html_content.encode('utf-8')),
                    mimetype='text/html',
                    as_attachment=True,
                    download_name=f"{document_id}.html"
                )
            
            # Convert to PDF with smart options
            result = converter.convert_html_to_pdf(html_content, document_id, pdf_options)
            
            if not result.get('success'):
                print(f"❌ [{request_id}] PDF conversion failed: {result.get('error')}")
                # Fallback to HTML
                from flask import send_file
                import io
                return send_file(
                    io.BytesIO(html_content.encode('utf-8')),
                    mimetype='text/html',
                    as_attachment=True,
                    download_name=f"{document_id}.html"
                )
            
            print(f"✅ [{request_id}] PDF generated: {len(result['pdf_data'])} bytes")
            
            # Return PDF
            from flask import send_file
            import io
            return send_file(
                io.BytesIO(result['pdf_data']),
                mimetype='application/pdf',
                as_attachment=True,
                download_name=custom_filename
            )
            
        elif format_type == 'html':
            # Return HTML directly
            from flask import send_file
            import io
            return send_file(
                io.BytesIO(html_content.encode('utf-8')),
                mimetype='text/html',
                as_attachment=True,
                download_name=custom_filename
            )
            
        else:
            return jsonify({
                'success': False,
                'error': f'Unsupported format: {format_type}',
                'code': 'UNSUPPORTED_FORMAT',
                'supported_formats': ['pdf', 'html']
            }), 400
        
    except Exception as e:
        current_app.logger.error(f"PDF download error [{request_id}]: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': f'PDF download failed: {str(e)}',
            'code': 'PDF_DOWNLOAD_ERROR',
            'debug': {'request_id': request_id, 'exception': str(e)}
        }), 500
    finally:
        print(f"\n{'='*80}")
        print(f"📄 PDF DOWNLOAD COMPLETE [{request_id}]")
        print(f"{'='*80}\n")


