@app.route('/api/v1/ai/documents/pdf/download/<document_id>', methods=['GET'])
@jwt_required
@cross_origin()
def download_pdf_from_html(document_id):
    """
    Convert saved HTML document to PDF and download
    
    Args:
        document_id: The HTML document ID (e.g., "5EBBC7E2F269")
    
    Returns:
        PDF file as download
    """
    try:
        is_super_admin = check_super_admin()
        current_app.logger.info(f"📄 PDF download from HTML: {document_id} - Super admin: {is_super_admin}")
        
        # Initialize storage
        storage = app.config.get('STORAGE_MANAGER')
        if not storage:
            from classes import StorageManager
            storage = StorageManager()
            app.config['STORAGE_MANAGER'] = storage
        
        # Initialize converter
        converter = app.config.get('DOCUMENT_CONVERTER')
        if not converter:
            converter = ComprehensiveDocumentConverter(storage_manager=storage)
            app.config['DOCUMENT_CONVERTER'] = converter
        
        # Check if PDF export is available
        if not converter.pdf_available:
            return jsonify({
                'success': False,
                'error': 'PDF export not available',
                'code': 'PDF_NOT_AVAILABLE',
                'fallback_formats': ['html']
            }), 501
        
        # Look for HTML file
        html_filename = f"{document_id}.html"
        html_path = storage.get_document_path(html_filename)
        
        if not html_path or not os.path.exists(html_path):
            # Try exports folder
            exports_path = os.path.join(storage.base_path, 'exports', html_filename)
            if os.path.exists(exports_path):
                html_path = exports_path
            else:
                return jsonify({
                    'success': False,
                    'error': f'HTML document not found: {document_id}',
                    'code': 'DOCUMENT_NOT_FOUND',
                    'checked_paths': [html_path, exports_path]
                }), 404
        
        # Read HTML file
        with open(html_path, 'r', encoding='utf-8') as f:
            html_content = f.read()
        
        current_app.logger.info(f"✅ HTML loaded: {document_id}.html ({len(html_content)} bytes)")
        
        # ========== SMART TABLE DETECTION ==========
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(html_content, 'html.parser')
        
        # Find all tables and count columns
        max_columns = 0
        for table in soup.find_all('table'):
            for row in table.find_all('tr')[:3]:
                cols = len(row.find_all(['th', 'td']))
                if cols > max_columns:
                    max_columns = cols
        
        # Set PDF options based on table width
        pdf_options = {'zoom': 0.95}
        
        if max_columns > 8:
            pdf_options.update({
                'page_size': 'A3',
                'orientation': 'landscape',
                'zoom': 0.85
            })
            current_app.logger.info(f"📐 Using A3 Landscape for {max_columns} columns")
        elif max_columns > 6:
            pdf_options.update({
                'page_size': 'A4',
                'orientation': 'landscape',
                'zoom': 0.9
            })
            current_app.logger.info(f"📐 Using A4 Landscape for {max_columns} columns")
        elif max_columns > 4:
            pdf_options.update({
                'page_size': 'A4',
                'orientation': 'portrait',
                'margin_left': '12mm',
                'margin_right': '12mm'
            })
            current_app.logger.info(f"📐 Using A4 Portrait with adjusted margins for {max_columns} columns")
        
        # Convert to PDF with smart options
        result = converter.convert_html_to_pdf(html_content, document_id, pdf_options)
        
        if not result.get('success'):
            # Fallback to HTML
            from flask import send_file
            import io
            return send_file(
                io.BytesIO(html_content.encode('utf-8')),
                mimetype='text/html',
                as_attachment=True,
                download_name=f"{document_id}.html"
            )
        
        # Return PDF
        from flask import send_file
        import io
        return send_file(
            io.BytesIO(result['pdf_data']),
            mimetype='application/pdf',
            as_attachment=True,
            download_name=f"{document_id}.pdf"
        )
        
    except Exception as e:
        current_app.logger.error(f"PDF download error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': f'PDF download failed: {str(e)}',
            'code': 'PDF_DOWNLOAD_ERROR'
        }), 500
