@app.route('/api/v1/ai/documents/convert/<document_id>/<format_type>', methods=['GET'])
@jwt_required
@cross_origin()
def convert_document(document_id, format_type):
    """
    Convert saved HTML document to various formats
    
    Args:
        document_id: The HTML document ID
        format_type: 'pdf', 'docx', or 'txt'
    
    Returns:
        Converted file as download
    """
    try:
        is_super_admin = check_super_admin()
        
        # Validate format
        valid_formats = ['pdf', 'docx', 'txt', 'html']
        if format_type not in valid_formats:
            return jsonify({
                'success': False,
                'error': f'Invalid format: {format_type}',
                'valid_formats': valid_formats
            }), 400
        
        # Initialize storage
        storage = app.config.get('STORAGE_MANAGER')
        if not storage:
            from classes import StorageManager
            storage = StorageManager()
            app.config['STORAGE_MANAGER'] = storage
        
        # Initialize converter
        converter = app.config.get('DOCUMENT_CONVERTER')
        if not converter:
            converter = ComprehensiveDocumentConverter(storage_manager=storage)
            app.config['DOCUMENT_CONVERTER'] = converter
        
        # If format is html, just return the HTML file
        if format_type == 'html':
            html_path = storage.get_document_path(f"{document_id}.html")
            if not html_path or not os.path.exists(html_path):
                return jsonify({'success': False, 'error': 'HTML document not found'}), 404
            
            with open(html_path, 'r', encoding='utf-8') as f:
                html_content = f.read()
            
            from flask import send_file
            import io
            return send_file(
                io.BytesIO(html_content.encode('utf-8')),
                mimetype='text/html',
                as_attachment=True,
                download_name=f"{document_id}.html"
            )
        
        # Check if target format is available
        if format_type == 'pdf' and not converter.pdf_available:
            return jsonify({'success': False, 'error': 'PDF export not available'}), 501
        if format_type == 'docx' and not converter.docx_available:
            return jsonify({'success': False, 'error': 'DOCX export not available'}), 501
        
        # Get HTML content
        html_path = storage.get_document_path(f"{document_id}.html")
        if not html_path or not os.path.exists(html_path):
            return jsonify({'success': False, 'error': 'HTML document not found'}), 404
        
        with open(html_path, 'r', encoding='utf-8') as f:
            html_content = f.read()
        
        # Convert document
        result = converter.convert_document(document_id, format_type, html_content)
        
        if not result.get('success'):
            return jsonify({'success': False, 'error': result.get('error')}), 500
        
        # Determine mime type
        mime_types = {
            'pdf': 'application/pdf',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'txt': 'text/plain'
        }
        
        # Return converted file
        from flask import send_file
        import io
        
        data_key = f"{format_type}_data"
        return send_file(
            io.BytesIO(result[data_key]),
            mimetype=mime_types[format_type],
            as_attachment=True,
            download_name=f"{document_id}.{format_type}"
        )
        
    except Exception as e:
        current_app.logger.error(f"Document conversion error: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500

