@app.route('/api/ai/html/download/<document_id>/<format_type>', methods=['GET'])
@jwt_required
@cross_origin()
def download_html_document(document_id: str, format_type: str):
    """Download HTML document in specified format - Knowledge Based Version"""
    try:
        # SUPER ADMIN DETECTION
        is_super_admin = check_super_admin()
        
        # SUPER ADMIN: BYPASS ALL CHECKS
        if is_super_admin:
            current_app.logger.info(f"🔓 SUPER ADMIN HTML download: {document_id} for {request.user.email if hasattr(request, 'user') else 'Super Admin'}")
            
            
            
            # Get document from storage
            document_content = html_template_engine.storage_manager.get_export(
                document_id=document_id,
                format_type=format_type
            )
            
            if not document_content:
                # Try to find in any format
                for fmt in ['html', 'pdf', 'docx', 'txt']:
                    document_content = html_template_engine.storage_manager.get_export(
                        document_id=document_id,
                        format_type=fmt
                    )
                    if document_content:
                        format_type = fmt
                        break
            
            if not document_content:
                return jsonify({
                    'success': False,
                    'error': 'Document not found',
                    'code': 'DOCUMENT_NOT_FOUND',
                    'timestamp': datetime.now().isoformat()
                }), 404
            
            # Determine mime type
            mime_types = {
                'html': 'text/html',
                'pdf': 'application/pdf',
                'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                'txt': 'text/plain'
            }
            
            mime_type = mime_types.get(format_type, 'application/octet-stream')
            filename = f"{document_id}.{format_type}"
            
            # Return as base64
            file_base64 = base64.b64encode(document_content).decode('utf-8')
            
            return jsonify({
                'success': True,
                'download': {
                    'document_id': document_id,
                    'format': format_type,
                    'filename': filename,
                    'mime_type': mime_type,
                    'size_bytes': len(document_content),
                    'base64_data': file_base64,
                    'download_url': f'/api/download/{filename}'
                },
                'knowledge_base_info': {
                    'retrieved_from_kb': True,
                    'document_id': document_id
                },
                'access_info': {
                    'access_level': 'super_admin_full_access',
                    'is_super_admin': True,
                    'bypassed_checks': ['ownership_check', 'download_limit_check']
                },
                'timestamp': datetime.now().isoformat()
            })
        
        # ===== REGULAR USER FLOW =====
        
        
        # Get document from storage
        document_content = html_template_engine.storage_manager.get_export(
            document_id=document_id,
            format_type=format_type
        )
        
        if not document_content:
            # Try to find in any format
            for fmt in ['html', 'pdf', 'docx', 'txt']:
                document_content = html_template_engine.storage_manager.get_export(
                    document_id=document_id,
                    format_type=fmt
                )
                if document_content:
                    format_type = fmt
                    break
        
        if not document_content:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND',
                'timestamp': datetime.now().isoformat()
            }), 404
        
        # Check ownership
        metadata = html_template_engine.storage_manager.get_metadata(document_id)
        if metadata and metadata.get('user_id') and metadata.get('user_id') != get_jwt_identity():
            return jsonify({
                'success': False,
                'error': 'You do not have permission to download this document',
                'code': 'ACCESS_DENIED',
                'timestamp': datetime.now().isoformat()
            }), 403
        
        # Determine mime type
        mime_types = {
            'html': 'text/html',
            'pdf': 'application/pdf',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'txt': 'text/plain'
        }
        
        mime_type = mime_types.get(format_type, 'application/octet-stream')
        filename = f"{document_id}.{format_type}"
        
        # Return as base64
        file_base64 = base64.b64encode(document_content).decode('utf-8')
        
        return jsonify({
            'success': True,
            'download': {
                'document_id': document_id,
                'format': format_type,
                'filename': filename,
                'mime_type': mime_type,
                'size_bytes': len(document_content),
                'base64_data': file_base64,
                'download_url': f'/api/download/{filename}'
            },
            'knowledge_base_info': {
                'retrieved_from_kb': True,
                'document_id': document_id
            },
            'access_info': {
                'access_level': 'regular_user',
                'is_super_admin': False
            },
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        logger.error(f"HTML download endpoint error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Document download failed: {str(e)}',
            'code': 'DOWNLOAD_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500


