        days_old = data.get('days_old', 30)
        
        # SUPER ADMIN: BYPASS ALL CHECKS
        if is_super_admin:
            current_app.logger.info(f"🔓 SUPER ADMIN Storage cleanup for {request.user.email if hasattr(request, 'user') else 'Super Admin'}")
            
            
            
            # Perform cleanup
