def determine_credential_level(score: float) -> Dict[str, Any]:
    """Determine credential level based on score - CSP Level aligned"""
    credential_levels = {
        'csp_distinguished': {
            'min_score': 95,
            'name': 'CSP Distinguished Scholar Credential',
            'validity_months': 36,
            'ceus_awarded': 5.0,
            'color': '#B8860B'  # Dark gold
        },
        'platinum': {
            'min_score': 90,
            'name': 'Platinum Safety Professional Credential',
            'validity_months': 24,
            'ceus_awarded': 4.0,
            'color': '#E5E4E2'
        },
        'gold': {
            'min_score': 85,
            'name': 'Gold Safety Specialist Credential',
            'validity_months': 18,
            'ceus_awarded': 3.5,
            'color': '#FFD700'
        },
        'silver': {
            'min_score': 80,
            'name': 'Silver Safety Practitioner Credential',
            'validity_months': 12,
            'ceus_awarded': 3.0,
            'color': '#C0C0C0'
        },
        'bronze': {
            'min_score': 75,
            'name': 'Bronze Safety Technician Credential',
            'validity_months': 12,
            'ceus_awarded': 2.5,
            'color': '#CD7F32'
        },
        'competent': {
            'min_score': 70,
            'name': 'Competent Safety Operator Credential',
            'validity_months': 12,
            'ceus_awarded': 2.0,
            'color': '#1E3C72'
        }
    }
    
    for level, criteria in credential_levels.items():
        if score >= criteria['min_score']:
            return {
                'level': level,
                **criteria
            }
    
    # Below 70%
    return {
        'level': 'not_certified',
        'name': 'Not Certified',
        'validity_months': 0,
        'ceus_awarded': 0,
        'color': '#666666'
    }

