def generate_professional_certificate_knowledge(session: Dict[str, Any], 
                                               grading_result: Dict[str, Any]) -> Dict[str, Any]:
    """
    Generate professional certificate for passed exams with specific signatures
    """
    try:
        user_name = session.get('user_name', session.get('user_id', 'Professional'))
        course = session.get('course', 'CSP Professional Certification Preparation')
        score = grading_result.get('percentage', 0)
        
        # Get base URL
        base_url = request.host_url.rstrip('/') if request else 'http://localhost:5000'
        
        # Director signature - Dr. Adam Fusheini
        signature1_url = f"{base_url}/uploads/signatures/dr_adam_fusheini.png"
        
        # Chief Examiner signature - Mr. Isaac Andoh
        signature2_url = f"{base_url}/uploads/signatures/mr_isaac_andoh.png"
        
        # Check if signature files exist
        signature_folder = os.path.join(os.getcwd(), 'uploads', 'signatures')
        signature1_exists = os.path.exists(os.path.join(signature_folder, 'dr_adam_fusheini.png'))
        signature2_exists = os.path.exists(os.path.join(signature_folder, 'mr_isaac_andoh.png'))
        
        print(f"📝 Signature files:")
        print(f"  Dr. Adam Fusheini: {signature1_exists} - {signature1_url}")
        print(f"  Mr. Isaac Andoh: {signature2_exists} - {signature2_url}")
        
        # Determine credential level
        if score >= 90:
            credential_level = 'Platinum'
            credential_color = '#722ed1'
            ceus = 4.0
        elif score >= 85:
            credential_level = 'Gold'
            credential_color = '#fa8c16'
            ceus = 3.5
        elif score >= 80:
            credential_level = 'Silver'
            credential_color = '#8c8c8c'
            ceus = 3.0
        elif score >= 75:
            credential_level = 'Bronze'
            credential_color = '#d48806'
            ceus = 2.5
        elif score >= 70:
            credential_level = 'Competent'
            credential_color = '#389e0d'
            ceus = 2.0
        else:
            credential_level = 'Certified'
            credential_color = '#1890ff'
            ceus = 0
        
        # Generate credential ID
        credential_id = f"CSP-{credential_level[:3].upper()}-{uuid.uuid4().hex[:12].upper()}"
        
        certificate_data = {
            'credential_id': credential_id,
            'credential_name': f"{credential_level} Safety Professional Credential",
            'credential_level': credential_level,
            'credential_color': credential_color,
            'recipient_name': user_name,
            'course_name': course,
            'exam_domain': session.get('domain', 'Comprehensive Safety Practice'),
            'issue_date': datetime.now().strftime('%Y-%m-%d'),
            'exam_score': round(score, 2),
            'correct_count': grading_result.get('correct_answers', 0),
            'total_count': grading_result.get('total_questions', 0),
            'ceus_awarded': ceus,
            'accreditation_body': 'CSP Knowledge Examination System',
            'standard_compliance': 'ISO/IEC 17024:2012',
            'verification_url': f"{base_url}/verify/{credential_id}",
            'signature1_url': signature1_url if signature1_exists else '',
            'signature2_url': signature2_url if signature2_exists else '',
            'signature_names': {
                'director': 'Dr. Adam Fusheini',
                'examiner': 'Mr. Isaac Andoh'
            }
        }
        
        # Generate HTML certificate
        certificate_content = generate_professional_certificate_html(certificate_data)
        
        return {
            'success': True,
            'certificate': certificate_data,
            'content': certificate_content,
            'signature_used': True,
            'signature_files_exist': {
                'director': signature1_exists,
                'examiner': signature2_exists
            },
            'download_options': {
                'html': f"/api/credentials/{credential_id}/html",
                'verification': certificate_data['verification_url']
            }
        }
        
    except Exception as e:
        print(f"❌ Certificate generation error: {e}")
        import traceback
        traceback.print_exc()
        return {
            'success': False,
            'error': f'Certificate generation failed: {str(e)}'
        }

def grade_csp_exam_knowledge_with_answers(session: Dict[str, Any], user_answers: Dict[str, Any]) -> Dict[str, Any]:
    """
    Grade CSP exam with professional analysis using provided answers
    Supports advanced CSP question types (analysis, synthesis, evaluation, integrated, ethical_dilemma)
    """
    try:
        exam_data = session.get('exam_data', {})
        questions = exam_data.get('questions', [])
        
        correct_answers = 0
        total_questions = len(questions)
        detailed_results = []
        
        # Enhanced professional metrics - includes new CSP question types
        professional_metrics = {
            # Basic types
            'conceptual_questions': 0,
            'conceptual_correct': 0,
            'application_questions': 0,
            'application_correct': 0,
            'scenario_questions': 0,
            'scenario_correct': 0,
            'calculation_questions': 0,
            'calculation_correct': 0,
            'professional_judgment_questions': 0,
            'professional_judgment_correct': 0,
            # Advanced CSP types
            'analysis_questions': 0,
            'analysis_correct': 0,
            'synthesis_questions': 0,
            'synthesis_correct': 0,
            'evaluation_questions': 0,
            'evaluation_correct': 0,
            'ethical_dilemma_questions': 0,
            'ethical_dilemma_correct': 0,
            'integrated_questions': 0,
            'integrated_correct': 0,
            'regulatory_comparison_questions': 0,
            'regulatory_comparison_correct': 0,
            'root_cause_questions': 0,
            'root_cause_correct': 0,
            'risk_assessment_questions': 0,
            'risk_assessment_correct': 0,
            'hierarchy_design_questions': 0,
            'hierarchy_design_correct': 0
        }
        
        domain_correct = {}
        domain_total = {}
        
        # Track cognitive level performance
        cognitive_performance = {
            'recall': {'correct': 0, 'total': 0},
            'application': {'correct': 0, 'total': 0},
            'analysis': {'correct': 0, 'total': 0},
            'synthesis': {'correct': 0, 'total': 0},
            'evaluation': {'correct': 0, 'total': 0}
        }
        
        print(f"📊 Grading with provided answers: {user_answers}")
        
        for i, question in enumerate(questions):
            # Get user answer
            user_answer_raw = user_answers.get(str(i)) or user_answers.get(i)
            
            # Handle different answer formats
            if isinstance(user_answer_raw, dict):
                answer_value = user_answer_raw.get('answer') or user_answer_raw.get('letter') or user_answer_raw.get('index')
            else:
                answer_value = user_answer_raw
            
            # Convert to letter for comparison
            if isinstance(answer_value, int):
                user_answer = chr(65 + answer_value)
            elif isinstance(answer_value, str) and len(answer_value) == 1 and answer_value.isalpha():
                user_answer = answer_value.upper()
            else:
                user_answer = str(answer_value).strip().upper() if answer_value else ''
            
            correct_letter = question.get('correct_answer', '').strip().upper()
            points = question.get('points', 1)
            cognitive_level = question.get('cognitive_level', question.get('question_type', 'conceptual'))
            
            # Compare answers
            is_correct = user_answer == correct_letter
            
            if is_correct:
                correct_answers += 1
            
            # Track domain performance
            domain = question.get('domain_code', question.get('domain', 'Unknown'))
            if domain not in domain_total:
                domain_total[domain] = 0
                domain_correct[domain] = 0
            domain_total[domain] += 1
            if is_correct:
                domain_correct[domain] += 1
            
            # Track cognitive level performance
            if cognitive_level in cognitive_performance:
                cognitive_performance[cognitive_level]['total'] += 1
                if is_correct:
                    cognitive_performance[cognitive_level]['correct'] += 1
            
            # Track professional metrics
            question_type = question.get('question_type', 'conceptual')
            metric_key = f"{question_type}_questions"
            metric_correct = f"{question_type}_correct"
            
            if metric_key in professional_metrics:
                professional_metrics[metric_key] += 1
                if is_correct:
                    professional_metrics[metric_correct] += 1
            
            # Map to standard types for backward compatibility
            if question_type in ['analysis', 'synthesis', 'evaluation']:
                professional_metrics['professional_judgment_questions'] += 1
                if is_correct:
                    professional_metrics['professional_judgment_correct'] += 1
            elif question_type in ['ethical_dilemma', 'integrated', 'regulatory_comparison']:
                professional_metrics['scenario_questions'] += 1
                if is_correct:
                    professional_metrics['scenario_correct'] += 1
            
            detailed_results.append({
                'question_index': i,
                'question_number': question.get('question_number', i + 1),
                'question_text': question.get('question_text', '')[:120] + '...' if len(question.get('question_text', '')) > 120 else question.get('question_text', ''),
                'question_type': question_type,
                'cognitive_level': cognitive_level,
                'domain': domain,
                'user_answer': user_answer,
                'correct_answer': correct_letter,
                'correct_answer_text': question.get('correct_answer_text', ''),
                'is_correct': is_correct,
                'explanation': question.get('explanation', 'Professional safety knowledge application'),
                'points': points,
                'points_earned': points if is_correct else 0
            })
        
        percentage = (correct_answers / total_questions * 100) if total_questions > 0 else 0
        passing_score = exam_data.get('passing_score', 75)
        passed = percentage >= passing_score
        
        # Calculate domain scores
        domain_scores = {}
        for domain in domain_total:
            domain_scores[domain] = {
                'correct': domain_correct.get(domain, 0),
                'total': domain_total[domain],
                'percentage': round((domain_correct.get(domain, 0) / domain_total[domain]) * 100, 1) if domain_total[domain] > 0 else 0
            }
        
        # Calculate cognitive level scores
        cognitive_scores = {}
        for level, data in cognitive_performance.items():
            cognitive_scores[level] = {
                'correct': data['correct'],
                'total': data['total'],
                'percentage': round((data['correct'] / data['total'] * 100), 1) if data['total'] > 0 else 0
            }
        
        # Generate result ID
        hash_string = f"{session.get('session_id', '')}{datetime.now().isoformat()}"
        hash_digest = hashlib.sha256(hash_string.encode()).hexdigest()
        result_id = f"CSP-RESULT-{hash_digest[:12]}"
        
        # Determine credential level
        credential = determine_credential_level(percentage)
        
        # Calculate total points earned
        total_points_earned = sum(d['points_earned'] for d in detailed_results)
        total_points_possible = sum(d['points'] for d in detailed_results)
        
        grading_result = {
            'result_id': result_id,
            'session_id': session.get('session_id', ''),
            'exam_id': session.get('exam_id', ''),
            'exam_title': exam_data.get('exam_title', 'CSP Examination'),
            'total_questions': total_questions,
            'correct_answers': correct_answers,
            'percentage': round(percentage, 2),
            'passing_score': passing_score,
            'passed': passed,
            'certificate_eligible': passed,
            'total_points_earned': total_points_earned,
            'total_points_possible': total_points_possible,
            'credential': credential,
            'credential_level': credential['level'] if credential else 'Not Certified',
            'credential_name': credential['name'] if credential else 'No Credential',
            'ceus_awarded': credential['ceus_awarded'] if credential else 0,
            'domain_scores': domain_scores,
            'cognitive_scores': cognitive_scores,
            'professional_metrics': professional_metrics,
            'detailed_results': detailed_results,
            'graded_at': datetime.now().isoformat(),
            'exam_type': 'CSP Professional Examination - Advanced',
            'knowledge_base_verified': True,
            'csp_blueprint_aligned': exam_data.get('csp_blueprint_aligned', False)
        }
        
        # Enhanced professional analysis
        professional_analysis = {
            'credential_level': credential['level'] if credential else 'Not Certified',
            'credential_name': credential['name'] if credential else 'No Credential',
            'ceus_awarded': credential['ceus_awarded'] if credential else 0,
            'standards_compliance': 'ISO/IEC 17024, ANSI/IACET, ISO 9001, BCSP Blueprint',
            'strong_domains': [d for d, s in domain_scores.items() if s['percentage'] >= 80],
            'weak_domains': [d for d, s in domain_scores.items() if s['percentage'] < 70],
            'cognitive_analysis': {
                'recall': cognitive_scores.get('recall', {}).get('percentage', 0),
                'application': cognitive_scores.get('application', {}).get('percentage', 0),
                'analysis': cognitive_scores.get('analysis', {}).get('percentage', 0),
                'synthesis': cognitive_scores.get('synthesis', {}).get('percentage', 0),
                'evaluation': cognitive_scores.get('evaluation', {}).get('percentage', 0)
            },
            'scenario_performance': {
                'attempted': professional_metrics.get('scenario_questions', 0) + professional_metrics.get('integrated_questions', 0),
                'correct': professional_metrics.get('scenario_correct', 0) + professional_metrics.get('integrated_correct', 0),
                'percentage': round((professional_metrics.get('scenario_correct', 0) + professional_metrics.get('integrated_correct', 0)) / 
                                    max(1, professional_metrics.get('scenario_questions', 0) + professional_metrics.get('integrated_questions', 0)) * 100, 1)
            },
            'ethical_performance': {
                'attempted': professional_metrics.get('ethical_dilemma_questions', 0),
                'correct': professional_metrics.get('ethical_dilemma_correct', 0),
                'percentage': round((professional_metrics.get('ethical_dilemma_correct', 0) / 
                                    max(1, professional_metrics.get('ethical_dilemma_questions', 0))) * 100, 1)
            },
            'calculation_performance': {
                'attempted': professional_metrics.get('calculation_questions', 0),
                'correct': professional_metrics.get('calculation_correct', 0),
                'percentage': round((professional_metrics.get('calculation_correct', 0) / 
                                    max(1, professional_metrics.get('calculation_questions', 0))) * 100, 1)
            },
            'csp_readiness': 'Ready' if percentage >= 75 else 'Needs Improvement',
            'estimated_csp_score': estimate_csp_exam_score(percentage),
            'recommendations': _generate_recommendations(domain_scores, cognitive_scores, percentage)
        }
        
        grading_result['professional_analysis'] = professional_analysis
        
        print(f"✅ Grading complete: {correct_answers}/{total_questions} correct, {percentage}%")
        print(f"   Cognitive Level Performance:")
        for level, score in professional_analysis['cognitive_analysis'].items():
            print(f"     - {level.capitalize()}: {score}%")
        
        return {
            'success': True,
            'grading_result': grading_result,
            'certificate_eligible': passed,
            'credential': credential
        }
        
    except Exception as e:
        logger.error(f"CSP grading error: {e}")
        logger.error(traceback.format_exc())
        return {
            'success': False,
            'error': f'CSP grading failed: {str(e)}'
        }


def _generate_recommendations(domain_scores: Dict, cognitive_scores: Dict, overall_score: float) -> List[str]:
    """Generate personalized recommendations based on performance"""
    recommendations = []
    
    if overall_score >= 85:
        recommendations.append("Excellent performance! You're well-prepared for the actual CSP exam.")
    elif overall_score >= 75:
        recommendations.append("Good performance. Focus on weak domains to increase confidence.")
    else:
        recommendations.append("Additional preparation recommended. Focus on foundational knowledge and practice questions.")
    
    # Domain-specific recommendations
    weak_domains = [d for d, s in domain_scores.items() if s['percentage'] < 70]
    for domain in weak_domains[:3]:  # Top 3 weak domains
        recommendations.append(f"Review {domain} - additional study recommended.")
    
    # Cognitive level recommendations
    if cognitive_scores.get('analysis', {}).get('percentage', 0) < 70:
        recommendations.append("Strengthen analytical skills - practice breaking down complex safety scenarios.")
    if cognitive_scores.get('synthesis', {}).get('percentage', 0) < 70:
        recommendations.append("Develop synthesis skills - practice combining multiple safety concepts.")
    if cognitive_scores.get('evaluation', {}).get('percentage', 0) < 70:
        recommendations.append("Enhance evaluation skills - practice making professional judgments.")
    
    return recommendations


def grade_exam_manually_fallback(session: Dict[str, Any]) -> Dict[str, Any]:
    """Fallback manual grading function"""
    try:
        exam_data = session.get('exam_data', {})
        answers = session.get('answers', {})
        questions = exam_data.get('questions', [])
        
        correct_answers = 0
        for i, question in enumerate(questions):
            user_answer = answers.get(str(i), '')
            if isinstance(user_answer, dict):
                user_answer = user_answer.get('answer', '')
            
            correct_answer = question.get('correct_answer', '')
            if str(user_answer).strip().upper() == str(correct_answer).strip().upper():
                correct_answers += 1
        
        total_questions = len(questions)
        percentage = (correct_answers / total_questions * 100) if total_questions > 0 else 0
        passed = percentage >= 70
        
        grading_result = {
            'total_questions': total_questions,
            'correct_answers': correct_answers,
            'percentage': round(percentage, 2),
            'passed': passed,
            'certificate_eligible': passed,
            'graded_at': datetime.now().isoformat()
        }
        
        return {'success': True, 'grading_result': grading_result}
    except Exception as e:
        return {'success': False, 'error': str(e)}


def estimate_csp_exam_score(practice_score: float) -> str:
    """Estimate actual CSP exam score based on practice score"""
    if practice_score >= 85:
        return "72-88% (High Probability of Passing CSP)"
    elif practice_score >= 80:
        return "68-84% (Good Chance of Passing CSP)"
    elif practice_score >= 75:
        return "63-79% (Moderate Chance of Passing CSP)"
    elif practice_score >= 70:
        return "58-74% (Needs Significant Improvement)"
    else:
        return "Below 60% (Extensive Preparation Required)"

