class CSPKnowledgeSystem:
    """
    Complete CSP Exam Preparation System - Knowledge Based Version
    Integrates all components and provides interface matching original endpoints
    """
    
    def __init__(self):
        """Initialize the complete CSP Knowledge System"""
        logger.info("=" * 80)
        logger.info("CSP KNOWLEDGE EXAM SYSTEM - PROFESSIONAL EDITION")
        logger.info("=" * 80)
        logger.info("DISCLAIMER: This material is NOT endorsed by BCSP.")
        logger.info("BCSP does not review or approve preparation materials.")
        logger.info("All questions are original and do not replicate actual exam questions.")
        logger.info("CSP is a registered trademark of BCSP.")
        logger.info("=" * 80)
        
        # Initialize core components
        self.knowledge_base = CSPKnowledgeBase()
        self.question_generator = CSPKnowledgeQuestionGenerator(self.knowledge_base)
        self.exam_engine = CSPKnowledgeExamEngine(self.question_generator)
        
        # Session storage
        self.exam_sessions = {}
        
        logger.info("✅ CSP Knowledge System initialized successfully")
        logger.info(f"📚 Knowledge Base: {len(self.knowledge_base.regulations)} regulations")
        logger.info(f"📝 Question Templates: {sum(len(v) for v in self.question_generator.question_templates.values())} templates")
        logger.info(f"🎯 CSP Domains: 10 domains with BCSP blueprint weighting\n")
    
    def generate_csp_exam(self, domain: str = None, num_questions: int = 100,
                         user_id: str = None, time_limit: int = 240,
                         difficulty: str = 'advanced') -> Dict[str, Any]:
        """
        Generate CSP exam - matches EnhancedCSPExamSystem interface
        
        Args:
            domain: Specific domain or None for full exam
            num_questions: Number of questions
            user_id: User identifier
            time_limit: Time limit in minutes
            difficulty: Difficulty level
            
        Returns:
            Dictionary with exam data
        """
        return self.exam_engine.generate_csp_exam(
            domain=domain,
            num_questions=num_questions,
            user_id=user_id,
            time_limit=time_limit,
            difficulty=difficulty
        )
    
    def generate_exam(self, domain: str = None, num_questions: int = 10,
                     user_id: str = None, time_limit: int = 240,
                     difficulty: str = "ADVANCED", **kwargs) -> Dict[str, Any]:
        """
        Generate exam - matches EnhancedCSPExamSystem.generate_exam interface
        
        This is an alias for generate_csp_exam for backward compatibility
        """
        # Map difficulty string
        difficulty_map = {
            'BASIC': 'basic',
            'INTERMEDIATE': 'intermediate',
            'ADVANCED': 'advanced',
            'CSP_HARD': 'csp_hard'
        }
        mapped_difficulty = difficulty_map.get(difficulty.upper(), 'advanced')
        
        return self.generate_csp_exam(
            domain=domain,
            num_questions=num_questions,
            user_id=user_id,
            time_limit=time_limit,
            difficulty=mapped_difficulty
        )
    
    def get_system_status(self) -> Dict[str, Any]:
        """Get system status report"""
        return {
            'success': True,
            'system': 'CSP Knowledge Exam System',
            'knowledge_base': {
                'regulations': len(self.knowledge_base.regulations),
                'correct_answers': len(self.knowledge_base.get_all_key_requirements()),
                'authorities': list(set(r.authority for r in self.knowledge_base.regulations.values()))
            },
            'templates': {
                'question_types': list(self.question_generator.question_templates.keys()),
                'total_templates': sum(len(v) for v in self.question_generator.question_templates.values())
            },
            'exam_engine': {
                'domains': list(self.exam_engine.domain_weights.keys()),
                'domain_names': self.exam_engine.domain_names
            },
            'generated_exams': len(self.exam_engine.generated_exams),
            'active_sessions': len(self.exam_sessions),
            'system_ready': True,
            'timestamp': datetime.now().isoformat()
        }

