    def generate_csp_exam(self, domain=None, num_questions=100, user_id=None, time_limit=240, difficulty='advanced'):
        """Generate CSP exam with random question selection"""
        import uuid
        import random
        from datetime import datetime
        
        exam_id = f"CSP-EXAM-{uuid.uuid4().hex[:12].upper()}"
        
        # Filter questions by domain if specified
        available_questions = self.questions_db.copy()
        if domain and domain != 'Domain 2':
            available_questions = [q for q in available_questions if q.get('domain') == domain]
        
        # If not enough questions, use all questions
        if len(available_questions) < num_questions:
            print(f"⚠️ Only {len(available_questions)} questions available, using all {len(available_questions)}")
            num_questions = len(available_questions)
        
        # ✅ RANDOM SELECTION - different every time
        selected_questions = random.sample(available_questions, min(num_questions, len(available_questions)))
        
        # ✅ SHUFFLE question order for variety
        random.shuffle(selected_questions)
        
        formatted_questions = []
        for i, q in enumerate(selected_questions):
            # ✅ Randomize option order to prevent memorization
            options = q['options']
            correct_answer_text = q['correct_answer_text']
            
            # Randomize option order but track correct answer
            option_items = list(options.items())
            random.shuffle(option_items)
            
            shuffled_options = {}
            new_correct_letter = None
            
            for idx, (letter, text) in enumerate(option_items):
                new_letter = chr(65 + idx)
                shuffled_options[new_letter] = text
                if text == correct_answer_text:
                    new_correct_letter = new_letter
            
            formatted_questions.append({
                'id': q.get('id', f"CSP-Q-{i+1:04d}"),
                'question_text': q['question_text'],
                'question_type': q.get('question_type', 'application'),
                'domain': q.get('domain', domain or 'Domain 2'),
                'difficulty': difficulty,
                'points': q.get('points', 2),
                'cognitive_level': q.get('cognitive_level', 'application'),
                'options': shuffled_options,
                'correct_answer': new_correct_letter,
                'correct_answer_text': correct_answer_text,
                'explanation': q['explanation'],
                'authority': q.get('authority', 'OSHA'),
                'standard': q.get('standard', '')
            })
        
        return {
            'success': True,
            'exam': {
                'exam_id': exam_id,
                'total_questions': len(formatted_questions),
                'time_limit_minutes': time_limit,
                'passing_score': 75,
                'questions': formatted_questions,
                'generated_at': datetime.now().isoformat()
            }
        }
    
    def get_all_key_requirements(self):
        """Get all key requirements for verification"""
        all_requirements = []
        for reg in self.knowledge_base.values():
            all_requirements.extend(reg.get('key_requirements', []))
        return all_requirements
