CERTIFICATE_DIR = 'generated_certificates'
os.makedirs(CERTIFICATE_DIR, exist_ok=True)

def generate_pdf_from_html(html_content, certificate_id):
    """Generate PDF from HTML content and save to file"""
    try:
        # Create unique filename
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        filename = f"certificate_{certificate_id}_{timestamp}.pdf"
        filepath = os.path.join(CERTIFICATE_DIR, filename)
        
        # Generate PDF
        html = HTML(string=html_content)
        html.write_pdf(filepath)
        
        # Return relative path for database storage
        return f"/generated_certificates/{filename}"
        
    except Exception as e:
        print(f"❌ PDF generation error: {e}")
        return None


