@app.route('/api/debug/signatures', methods=['GET'])
@jwt_required
def debug_signatures():
    """Debug endpoint to check signature files"""
    try:
        signature_folder = os.path.join(os.getcwd(), 'uploads', 'signatures')
        base_url = request.host_url.rstrip('/')
        
        files = []
        if os.path.exists(signature_folder):
            for filename in os.listdir(signature_folder):
                file_path = os.path.join(signature_folder, filename)
                file_url = f"{base_url}/uploads/signatures/{filename.replace(' ', '%20')}"
                files.append({
                    'filename': filename,
                    'exists': os.path.exists(file_path),
                    'size': os.path.getsize(file_path) if os.path.exists(file_path) else 0,
                    'url': file_url,
                    'full_path': file_path
                })
        
        return jsonify({
            'success': True,
            'signature_folder': signature_folder,
            'folder_exists': os.path.exists(signature_folder),
            'files': files,
            'base_url': base_url
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

