@app.route('/api/ai/exam/flow/generate', methods=['POST'])
@jwt_required
@cross_origin()
def generate_exam_for_flow():
    """Generate full CSP exam (100 questions, 4 hours)"""
    try:
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA_PROVIDED',
                'timestamp': datetime.now().isoformat()
            }), 400
            
        session_id = data.get('session_id') or data.get('sessionId')
        
        if not session_id:
            return jsonify({
                'success': False,
                'error': 'Session ID is required',
                'code': 'MISSING_SESSION_ID',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        # Get session
        session = exam_sessions.get(session_id)
        
        if not session:
            return jsonify({
                'success': False,
                'error': f'Exam session not found: {session_id}',
                'code': 'SESSION_NOT_FOUND',
                'timestamp': datetime.now().isoformat()
            }), 404
        
        # Get exam parameters
        domain = session.get('domain', 'Domain 2')
        num_questions = session.get('num_questions', 100)
        user_id = session.get('user_id')
        
        print(f"🎯 GENERATING CSP FULL EXAM for session {session_id}")
        print(f"   - Domain: {domain}")
        print(f"   - Questions: {num_questions}")
        
        # Get advanced CSP system (csp_exam_system)
        system = get_csp_exam_system()
        
        if not system:
            return jsonify({
                'success': False,
                'error': 'CSP Exam System not available',
                'code': 'SYSTEM_UNAVAILABLE',
                'timestamp': datetime.now().isoformat()
            }), 500
        
        # ✅ FIX: Use generate_csp_exam, not generate_exam
        exam_result = system.generate_csp_exam(
            domain=domain,
            num_questions=num_questions,
            user_id=user_id,
            time_limit=session.get('time_limit_minutes', 240),
            difficulty='advanced'
        )
        
        if not exam_result.get('success'):
            return jsonify({
                'success': False,
                'error': 'Failed to generate exam',
                'code': 'EXAM_GENERATION_FAILED',
                'timestamp': datetime.now().isoformat()
            }), 500
        
        exam_data = exam_result.get('exam', {})
        exam_id = exam_data.get('exam_id', f"EXAM-{session_id[:8]}")
        
        # Process questions to ensure proper format
        questions = exam_data.get('questions', [])
        for i, q in enumerate(questions):
            if not q.get('id'):
                q['id'] = f"CSP-Q-{i+1:04d}"
            if not q.get('question_type'):
                q['question_type'] = 'application'
            if not q.get('points'):
                q['points'] = 2
            if not q.get('cognitive_level'):
                q['cognitive_level'] = q.get('question_type', 'application')
            
            # Ensure options are in frontend format
            if 'options' in q:
                if isinstance(q['options'], dict):
                    options_array = []
                    for letter in sorted(q['options'].keys()):
                        options_array.append({
                            'id': letter,
                            'text': q['options'][letter],
                            'letter': letter
                        })
                    q['options'] = options_array
                elif isinstance(q['options'], list) and q['options'] and isinstance(q['options'][0], str):
                    options_array = []
                    for j, opt_text in enumerate(q['options']):
                        letter = chr(65 + j)
                        options_array.append({
                            'id': letter,
                            'text': opt_text,
                            'letter': letter
                        })
                    q['options'] = options_array
        
        # Update session
        session['exam_id'] = exam_id
        session['exam_data'] = exam_data
        session['current_step'] = 'taking_exam'
        session['status'] = 'active'
        session['start_time'] = datetime.now().isoformat()
        session['progress']['total'] = len(questions)
        
        # Store session
        exam_sessions[session_id] = session
        app.exam_sessions = exam_sessions
        
        print(f"✅ CSP Full Exam generated: {exam_id} with {len(questions)} questions")
        
        return jsonify({
            'success': True,
            'session_id': session_id,
            'current_step': 'taking_exam',
            'exam_id': exam_id,
            'exam_data': {
                'exam_id': exam_id,
                'exam_type': 'CSP_FULL_EXAM',
                'questions': questions,
                'total_questions': len(questions),
                'total_points': sum(q.get('points', 1) for q in questions),
                'time_limit_minutes': session.get('time_limit_minutes', 240),
                'passing_score': session.get('passing_score', 75),
                'course': session.get('course'),
                'domain': domain,
                'difficulty': 'CSP Full Exam',
                'csp_blueprint_aligned': True,
                'generated_at': datetime.now().isoformat()
            },
            'time_details': {
                'start_time': session['start_time'],
                'time_limit_minutes': session.get('time_limit_minutes', 240),
                'current_time': datetime.now().isoformat()
            },
            'progress': {
                'answered': 0,
                'total': len(questions),
                'percentage': 0
            },
            'exam_instructions': {
                'difficulty_note': 'This is a full CSP-level exam (100 questions, 4 hours).',
                'cognitive_demand': 'Questions require analysis, synthesis, and evaluation.',
                'scenario_based': 'Complex scenarios requiring professional judgment.',
                'time_management': '4 hours (240 minutes) for 100 questions.',
                'passing_benefits': 'Passing scores qualify for professional credentials.'
            },
            'next_action': 'answer_questions',
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        print(f"❌ GENERATE ERROR: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': f'Failed to generate exam: {str(e)}',
            'code': 'EXAM_GENERATION_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500

@app.route('/api/ai/exam/flow/submit-answer', methods=['POST'])
@jwt_required
@cross_origin()
def submit_exam_answer():
    """Submit answer for exam question - KNOWLEDGE BASED CSP SYSTEM"""
    try:
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA_PROVIDED',
                'timestamp': datetime.now().isoformat()
            }), 400
            
        session_id = data.get('session_id')
        question_index = data.get('question_index')
        answer = data.get('answer')
        
        if not session_id or question_index is None:
            return jsonify({
                'success': False,
                'error': 'Session ID and question index are required',
                'code': 'MISSING_REQUIRED_FIELDS',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        # Get session
        session = exam_sessions.get(session_id)
        
        if not session:
            return jsonify({
                'success': False,
                'error': 'Session not found',
                'code': 'SESSION_NOT_FOUND',
                'timestamp': datetime.now().isoformat()
            }), 404
        
        if session.get('status') != 'active':
            return jsonify({
                'success': False,
                'error': 'Session not active',
                'code': 'SESSION_NOT_ACTIVE',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        # Update answers
        if 'answers' not in session:
            session['answers'] = {}
        
        answer_data = {
            'answer': answer,
            'timestamp': datetime.now().isoformat()
        }
        
        session['answers'][str(question_index)] = answer_data
        
        # Update progress
        total_questions = len(session.get('exam_data', {}).get('questions', []))
        answered = len(session['answers'])
        progress_percentage = (answered / total_questions) * 100 if total_questions > 0 else 0
        
        session['progress']['answered'] = answered
        session['progress']['percentage'] = progress_percentage
        
        # Calculate time for CSP exams
        if session.get('start_time'):
            try:
                start_time = datetime.fromisoformat(session['start_time'].replace('Z', '+00:00'))
                time_elapsed = (datetime.now() - start_time).total_seconds()
                time_limit_seconds = session.get('time_limit_minutes', 240) * 60
                time_remaining = max(0, time_limit_seconds - time_elapsed)
                session['time_remaining_minutes'] = int(time_remaining / 60)
            except:
                pass
        
        # Store session
        exam_sessions[session_id] = session
        app.exam_sessions = exam_sessions
        
        print(f"✅ KNOWLEDGE CSP ANSWER: Submitted answer for question {question_index}")
        
        response = {
            'success': True,
            'session_id': session_id,
            'question_index': question_index,
            'answer_submitted': True,
            'progress': {
                'answered': answered,
                'total': total_questions,
                'percentage': round(progress_percentage, 1)
            },
            'can_submit': answered >= total_questions,
            'timestamp': datetime.now().isoformat()
        }
        
        # Add time info
        if 'time_remaining_minutes' in session:
            response['time_remaining_minutes'] = session['time_remaining_minutes']
            response['time_warning'] = session['time_remaining_minutes'] < 30
        
        return jsonify(response)
        
    except Exception as e:
        print(f"❌ KNOWLEDGE CSP ANSWER: Error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to submit answer: {str(e)}',
            'code': 'ANSWER_SUBMIT_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500


