@app.route('/api/ai/exam/flow/reset', methods=['POST'])
@jwt_required
@cross_origin()
def reset_exam_session():
    """Reset an exam session to start over - KNOWLEDGE BASED CSP SYSTEM"""
    try:
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA_PROVIDED',
                'timestamp': datetime.now().isoformat()
            }), 400
            
        session_id = data.get('session_id')
        
        if not session_id:
            return jsonify({
                'success': False,
                'error': 'Session ID is required',
                'code': 'MISSING_SESSION_ID',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        # Get session
        session = exam_sessions.get(session_id)
        
        if not session:
            return jsonify({
                'success': False,
                'error': 'Exam session not found',
                'code': 'SESSION_NOT_FOUND',
                'timestamp': datetime.now().isoformat()
            }), 404
        
        # Keep exam mode and user info
        exam_mode = session.get('exam_mode', 'standard')
        user_id = session.get('user_id')
        user_name = session.get('user_name')
        user_email = session.get('user_email')
        course = session.get('course')
        domain = session.get('domain')
        topic = session.get('topic')
        
        # Reset session
        session.update({
            'current_step': 'setup',
            'status': 'setup',
            'exam_id': None,
            'exam_data': None,
            'answers': {},
            'grading_result': None,
            'certificate_generated': False,
            'certificate_data': None,
            'start_time': None,
            'end_time': None,
            'progress': {
                'answered': 0,
                'total': 0,
                'percentage': 0
            }
        })
        
        # Restore essential data
        session['exam_mode'] = exam_mode
        session['user_id'] = user_id
        session['user_name'] = user_name
        session['user_email'] = user_email
        session['course'] = course
        session['domain'] = domain
        session['topic'] = topic
        
        # Store session
        exam_sessions[session_id] = session
        app.exam_sessions = exam_sessions
        
        message = 'CSP Knowledge Based Exam session reset'
        
        return jsonify({
            'success': True,
            'session_id': session_id,
            'message': message,
            'current_step': 'setup',
            'exam_mode': exam_mode,
            'domain': domain,
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        print(f"❌ KNOWLEDGE CSP RESET: Error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to reset exam session: {str(e)}',
            'code': 'RESET_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500


