# ===== HELPER FUNCTIONS =====

def generate_fallback_exam_data(domain: str, num_questions: int, difficulty: str, session_id: str) -> Dict:
    """Generate fallback exam data if knowledge system fails"""
    exam_id = f"CSP-FALLBACK-{hashlib.md5(f'{domain}{datetime.now().isoformat()}'.encode()).hexdigest()[:8]}"
    
    questions = []
    for i in range(num_questions):
        question = {
            'id': f"Q-{i+1:03d}",
            'question_number': i+1,
            'question_text': f"Question {i+1}: According to OSHA standards, what is the primary requirement for {domain} safety management?",
            'question_type': 'conceptual',
            'domain': domain,
            'difficulty': difficulty,
            'options': {
                'A': 'Develop and implement written program with employee involvement',
                'B': 'Conduct annual training for all affected employees',
                'C': 'Maintain records for minimum of 5 years',
                'D': 'Perform quarterly safety inspections'
            },
            'correct_answer': 'A',
            'correct_answer_text': 'Develop and implement written program with employee involvement',
            'explanation': f'This is a fundamental requirement of {domain} safety management systems.',
            'points': 2,
            'authority': 'OSHA',
            'standard': 'General Industry'
        }
        questions.append(question)
    
    return {
        'exam_id': exam_id,
        'exam_type': 'CSP_FALLBACK',
        'exam_title': f'CSP {domain} Practice Examination',
        'domain': domain,
        'difficulty': difficulty,
        'total_questions': len(questions),
        'time_limit_minutes': 240,
        'passing_score': 70,
        'questions': questions,
        'generated_at': datetime.now().isoformat()
    }

