def allowed_signature_file(filename):
    """Check if file has an allowed extension for signatures"""
    if '.' not in filename:
        return False
    ext = filename.rsplit('.', 1)[1].lower()
    return ext in SIGNATURE_ALLOWED_EXTENSIONS


