def _map_industry(industry_str: str) -> Optional[str]:
    """Map frontend industry strings to HSE Knowledge Base industry names"""
    if not industry_str or industry_str.lower() == 'general':
        return None
    
    mapping = {
        'construction': 'Construction',
        'manufacturing': 'Manufacturing',
        'oil_gas': 'Oil & Gas',
        'oil and gas': 'Oil & Gas',
        'healthcare': 'Healthcare',
        'mining': 'Mining',
        'agriculture': 'Agriculture',
        'transportation': 'Transportation',
        'warehousing': 'Warehousing & Logistics',
        'chemical': 'Chemical Processing',
        'pharmaceutical': 'Pharmaceutical',
        'food': 'Food Processing',
        'maritime': 'Maritime',
        'aviation': 'Aviation',
        'utilities': 'Utilities',
        'office': 'Office & Administrative',
        'retail': 'Retail',
        'hospitality': 'Hospitality',
        'education': 'Education',
        'waste': 'Waste Management',
        'forestry': 'Forestry & Logging',
        'steel': 'Steel Production',
        'automotive': 'Automotive Manufacturing',
        'aerospace': 'Aerospace',
        'nuclear': 'Nuclear Power',
        'renewable': 'Renewable Energy',
        'telecom': 'Telecommunications',
        'water': 'Water Treatment',
        'rail': 'Rail Transportation',
        'defense': 'Defense & Aerospace',
        'biotech': 'Biotechnology',
        'semiconductor': 'Semiconductor Manufacturing',
        # Add any other industries your frontend might send
        'laboratory': 'Laboratory',  # 👈 ADD THIS IF NEEDED
        'lab': 'Laboratory',          # 👈 ADD THIS IF NEEDED
        'research': 'Research & Development'
    }
    
    key = industry_str.lower().strip()
    
    # Direct mapping check
    if key in mapping:
        return mapping[key]
    
    # Partial match check
    for k, v in mapping.items():
        if k in key or key in k:
            return v
    
    # Default to None for unmapped industries (which will use general knowledge base)
    return None  # 👈 CHANGE THIS - return None instead of industry_str.capitalize()

def _map_jurisdiction_to_country(jurisdiction: str) -> str:
    """Map jurisdiction to country code for regulatory information"""
    if not jurisdiction:
        return "USA"
    
    mapping = {
        'us': 'USA',
        'usa': 'USA',
        'osha': 'USA',
        'uk': 'UK',
        'gb': 'UK',
        'hse': 'UK',
        'eu': 'EU',
        'europe': 'EU',
        'canada': 'Canada',
        'ca': 'Canada',
        'ccohs': 'Canada',
        'australia': 'Australia',
        'au': 'Australia'
    }
    
    key = jurisdiction.lower().strip()
    return mapping.get(key, 'USA')

def _generate_session_id() -> str:
    """Generate a unique session ID"""
    return f"SES-{uuid.uuid4().hex[:12].upper()}"

def _calculate_relevance_score(query: str, result_text: str) -> float:
    """Calculate relevance score between query and result"""
    query_words = set(query.lower().split())
    result_words = set(result_text.lower().split())
    
    if not query_words or not result_words:
        return 0.5
    
    intersection = query_words.intersection(result_words)
    union = query_words.union(result_words)
    
    return len(intersection) / len(union) if union else 0.5

