@app.route('/api/safety/search', methods=['POST'])
@cross_origin()
def safety_search():
    """Main endpoint for safety search engine - powered by HSE Knowledge Base"""
    try:
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        query = data.get('query', '').strip()
        if not query:
            return jsonify({
                'success': False,
                'error': 'Query is required',
                'code': 'EMPTY_QUERY',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        industry = data.get('industry', 'general')
        jurisdiction = data.get('jurisdiction')
        session_id = data.get('session_id')
        user_plan = data.get('user_plan', 'free')
        
        # DEBUG: Log all incoming data
        print("\n" + "="*80)
        print("🔍 SAFETY SEARCH DEBUG - INCOMING DATA")
        print("="*80)
        print(f"Query: {query}")
        print(f"Industry: {industry}")
        print(f"Jurisdiction: {jurisdiction}")
        print(f"Session ID: {session_id}")
        print(f"User Plan: {user_plan}")
        print("="*80 + "\n")
        
        # Map to HSE system formats
        hse_industry = _map_industry(industry)
        hse_jurisdiction = _map_jurisdiction_to_country(jurisdiction) if jurisdiction else None
        
        print(f"📋 Mapped industry: '{hse_industry}'")
        
        # Generate session ID if not provided
        if not session_id:
            session_id = _generate_session_id()
            print(f"🆕 Generated session ID: {session_id}")
        
        # Get HSE Advisor system
        print("🔄 Getting HSE system...")
        hse_system = get_hse_system()
        print("✅ HSE system retrieved")
        
        # Prepare question with industry context
        enhanced_question = query
        if hse_industry and hse_industry != 'general':
            enhanced_question = f"For {hse_industry} industry: {query}"
        
        print(f"📝 Enhanced question: '{enhanced_question[:100]}...'")
        
        # DEBUG: Try-catch around the HSE system call
        print("🔄 Calling HSE system.ask()...")
        try:
            response = hse_system.ask(
                question=enhanced_question,
                user_id="api_user",
                session_id=session_id
            )
            print("✅ HSE system.ask() completed successfully")
            print(f"📊 Response type: {type(response)}")
            if isinstance(response, dict):
                print(f"📊 Response keys: {list(response.keys())}")
        except Exception as hse_error:
            print(f"❌ HSE system.ask() exception: {str(hse_error)}")
            import traceback
            traceback.print_exc()
            raise
        
        # Format response for API
        search_result = {
            'success': True,
            'query': query,
            'industry': industry,
            'jurisdiction': jurisdiction,
            'session_id': session_id,
            'total_results': 1,
            'total_search_time': 0,
            'sources_used': ['hse_knowledge_base'],
            'timestamp': datetime.now().isoformat()
        }
        
        # Extract answer and format as results
        results = []
        
        # Main answer as primary result
        main_result = {
            'title': f"HSE Advisory: {response.get('question_type', 'Safety Guidance').replace('_', ' ').title()}",
            'snippet': response['answer'][:300] + "..." if len(response['answer']) > 300 else response['answer'],
            'full_text': response['answer'],
            'source': 'HSE Knowledge Base',
            'relevance_score': 0.95,
            'category': response.get('question_type', 'general'),
            'industries': response.get('industries', []),
            'hazards': response.get('hazards', []),
            'confidence': response.get('confidence', {}),
            'references': response.get('references', [])
        }
        results.append(main_result)
        
        # Add follow-up suggestions as additional results
        for i, suggestion in enumerate(response.get('follow_up_suggestions', [])[:3]):
            results.append({
                'title': f"Follow-up: {suggestion[:50]}...",
                'snippet': suggestion,
                'full_text': suggestion,
                'source': 'Suggested Query',
                'relevance_score': 0.8 - (i * 0.1),
                'category': 'suggestion',
                'is_follow_up': True
            })
        
        search_result['results'] = results
        search_result['session_id'] = session_id
        
        # Store in session tracking
        if session_id not in chat_sessions:
            chat_sessions[session_id] = {
                'created': datetime.now().isoformat(),
                'last_active': datetime.now().isoformat(),
                'queries': []
            }
        
        chat_sessions[session_id]['last_active'] = datetime.now().isoformat()
        chat_sessions[session_id]['queries'].append({
            'query': query,
            'timestamp': datetime.now().isoformat(),
            'results_count': len(results)
        })
        
        # Log the search
        logger.info(f"Safety search: '{query[:50]}...' - Industry: {industry}, Session: {session_id}")
        
        return jsonify(search_result)
        
    except Exception as e:
        logger.error(f"Safety search error: {str(e)}")
        print("\n" + "="*80)
        print("❌ EXCEPTION DETAILS")
        print("="*80)
        import traceback
        traceback.print_exc()
        print("="*80 + "\n")
        return jsonify({
            'success': False,
            'error': f'Search failed: {str(e)}',
            'code': 'SEARCH_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500
