@app.route('/api/safety/search/batch', methods=['POST'])
@cross_origin()
def safety_search_batch():
    """Batch search endpoint for multiple queries - powered by HSE Knowledge Base"""
    try:
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        queries = data.get('queries', [])
        if not queries or not isinstance(queries, list):
            return jsonify({
                'success': False,
                'error': 'Queries must be a non-empty list',
                'code': 'INVALID_QUERIES',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        industry = data.get('industry', 'general')
        jurisdiction = data.get('jurisdiction')
        
        # Map to HSE system formats
        hse_industry = _map_industry(industry)
        hse_jurisdiction = _map_jurisdiction_to_country(jurisdiction) if jurisdiction else None
        
        # Get HSE system
        hse_system = get_hse_system()
        
        # Perform batch searches (limit to 10)
        results = []
        for i, query_item in enumerate(queries[:10]):
            try:
                # Extract query details
                if isinstance(query_item, dict):
                    q = query_item.get('query', '')
                    ind = _map_industry(query_item.get('industry', industry))
                    jur = _map_jurisdiction_to_country(query_item.get('jurisdiction', jurisdiction)) if query_item.get('jurisdiction') else hse_jurisdiction
                else:
                    q = str(query_item)
                    ind = hse_industry
                    jur = hse_jurisdiction
                
                if not q:
                    continue
                
                # Generate session ID for this batch query
                session_id = f"BATCH-{uuid.uuid4().hex[:8].upper()}-{i}"
                
                # Get advisory response
                response = hse_system.ask(
                    question=q,
                    user_id="batch_user",
                    session_id=session_id
                )
                
                search_result = {
                    'query': q,
                    'industry': query_item.get('industry', industry) if isinstance(query_item, dict) else industry,
                    'jurisdiction': query_item.get('jurisdiction', jurisdiction) if isinstance(query_item, dict) else jurisdiction,
                    'success': True,
                    'answer': response['answer'],
                    'industries': response.get('industries', []),
                    'hazards': response.get('hazards', []),
                    'question_type': response.get('question_type', 'general'),
                    'confidence': response.get('confidence', {}),
                    'references': response.get('references', []),
                    'suggestions': response.get('follow_up_suggestions', [])
                }
                
                # Add original query
                search_result['original_query'] = q
                
                results.append(search_result)
                
            except Exception as e:
                logger.error(f"Batch search item error: {str(e)}")
                results.append({
                    'query': q if 'q' in locals() else str(query_item),
                    'success': False,
                    'error': str(e)[:100]
                })
        
        return jsonify({
            'success': True,
            'results': results,
            'total_queries': len(queries),
            'processed_queries': len(results),
            'industry': industry,
            'jurisdiction': jurisdiction,
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        logger.error(f"Batch search error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Batch search failed: {str(e)}',
            'code': 'BATCH_SEARCH_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500


