@app.route('/api/safety/search/analyze', methods=['POST'])
@cross_origin()
def analyze_safety_query():
    """Analyze a safety query using HSE Advisor Engine"""
    try:
        data = request.get_json()
        
        if not data:
            return jsonify({
                'success': False,
                'error': 'No JSON data provided',
                'code': 'NO_DATA',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        query = data.get('query', '').strip()
        if not query:
            return jsonify({
                'success': False,
                'error': 'Query is required',
                'code': 'EMPTY_QUERY',
                'timestamp': datetime.now().isoformat()
            }), 400
        
        industry = data.get('industry', 'general')
        jurisdiction = data.get('jurisdiction')
        
        # Get HSE Advisor Engine directly for analysis
        advisor_engine = get_hse_advisor_engine()
        
        # Detect components
        industries = advisor_engine._detect_industries(query)
        hazards = advisor_engine._detect_hazards(query)
        question_type = advisor_engine._detect_question_type(query)
        urgency = advisor_engine._detect_urgency(query)
        
        # Map to frontend format
        industry_names = [i.value if hasattr(i, 'value') else str(i) for i in industries[:3]]
        hazard_names = [h.value if hasattr(h, 'value') else str(h) for h in hazards[:3]]
        
        # Determine complexity based on query length and detected items
        complexity = min(len(query) / 200, 1.0) * 0.5
        complexity += min(len(industries) * 0.1, 0.3)
        complexity += min(len(hazards) * 0.1, 0.3)
        complexity = min(complexity, 1.0)
        
        # Get risk assessment method recommendation
        knowledge_base = get_hse_knowledge_base()
        risk_methods = []
        if hazards:
            primary_hazard = hazards[0]
            recommendations = knowledge_base.risk_engine.recommend_method(
                industries[0] if industries else None,
                primary_hazard
            )
            risk_methods = [r['method'] for r in recommendations[:3]]
        
        # Build comprehensive analysis
        analysis = {
            'query_analysis': {
                'original_query': query,
                'normalized_query': query.lower(),
                'query_length': len(query),
                'word_count': len(query.split()),
                'has_question_mark': '?' in query,
                'complexity_score': round(complexity, 2),
                'complexity_level': 'high' if complexity > 0.7 else 'medium' if complexity > 0.4 else 'low'
            },
            'industry_detection': {
                'detected': industry_names,
                'primary': industry_names[0] if industry_names else industry,
                'confidence': len(industry_names) * 0.33 if industry_names else 0.5,
                'all_detections': industry_names
            },
            'hazard_detection': {
                'detected': hazard_names,
                'primary': hazard_names[0] if hazard_names else 'General Safety',
                'confidence': len(hazard_names) * 0.33 if hazard_names else 0.5,
                'all_detections': hazard_names
            },
            'question_classification': {
                'type': question_type,
                'formatted_type': question_type.replace('_', ' ').title(),
                'urgency': urgency,
                'requires_immediate_action': urgency == 'high'
            },
            'jurisdiction': jurisdiction or 'Not specified',
            'recommended_approach': {
                'risk_assessment_methods': risk_methods,
                'primary_method': risk_methods[0] if risk_methods else '5x5 Risk Matrix',
                'control_hierarchy_levels': [c.value[0] for c in ControlHierarchy],
                'regulatory_focus': _map_jurisdiction_to_country(jurisdiction) if jurisdiction else 'USA'
            },
            'search_strategy': {
                'priority_sources': ['osha', 'hse_knowledge_base', 'industry_guidelines'],
                'strategy': 'focused' if len(hazard_names) > 0 else 'exploratory',
                'estimated_results': 5 + (len(hazard_names) * 3)
            }
        }
        
        return jsonify({
            'success': True,
            'query': query,
            'analysis': analysis,
            'search_recommendations': {
                'priority_sources': ['osha', 'hse_knowledge_base'],
                'strategy': 'focused' if len(hazard_names) > 0 else 'balanced',
                'estimated_complexity': complexity,
                'recommended_industry': industry_names[0] if industry_names else industry,
                'recommended_topic': hazard_names[0] if hazard_names else 'general_safety'
            },
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        logger.error(f"Query analysis error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Query analysis failed: {str(e)}',
            'code': 'ANALYSIS_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500


