# ============================================================================
# ENDPOINT 5: /api/safety/search/cache/clear (POST)
# ============================================================================

@app.route('/api/safety/search/cache/clear', methods=['POST'])
@cross_origin()
def clear_search_cache():
    """Clear session caches and optionally search cache"""
    try:
        data = request.get_json() or {}
        
        # Clear chat sessions older than specified days
        days_old = data.get('days_old', 7)
        cutoff_time = datetime.now() - timedelta(days=days_old)
        
        deleted_sessions = 0
        sessions_to_remove = []
        
        for session_id, session_data in chat_sessions.items():
            created_time = datetime.fromisoformat(session_data.get('created', datetime.now().isoformat()))
            if created_time < cutoff_time:
                sessions_to_remove.append(session_id)
                deleted_sessions += 1
        
        for session_id in sessions_to_remove:
            del chat_sessions[session_id]
        
        # Clear file cache if directory exists
        cache_dir = Path(data.get('cache_dir', './search_cache'))
        deleted_files = 0
        
        if cache_dir.exists():
            for cache_file in cache_dir.glob('*.json'):
                try:
                    file_time = datetime.fromtimestamp(cache_file.stat().st_mtime)
                    if file_time < cutoff_time:
                        cache_file.unlink()
                        deleted_files += 1
                except Exception as e:
                    logger.warning(f"Failed to delete {cache_file}: {e}")
        
        return jsonify({
            'success': True,
            'message': f'Cleared {deleted_sessions} old sessions and {deleted_files} old cache files',
            'sessions_cleared': deleted_sessions,
            'cache_files_cleared': deleted_files,
            'days_old': days_old,
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        logger.error(f"Clear cache error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to clear cache: {str(e)}',
            'code': 'CACHE_CLEAR_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500


# ============================================================================
# ENDPOINT 6: /api/safety/search/stats (GET)
# ============================================================================

@app.route('/api/safety/search/stats', methods=['GET'])
@cross_origin()
def get_search_stats():
    """Get search engine statistics from HSE Knowledge Base"""
    try:
        knowledge_base = get_hse_knowledge_base()
        
        # Knowledge base statistics
        hazard_stats = {
            'total_hazards': len(knowledge_base.hazard_library),
            'by_category': {}
        }
        
        # Count hazards by category
        for hazard in knowledge_base.hazard_library.values():
            category = hazard.category.value
            if category not in hazard_stats['by_category']:
                hazard_stats['by_category'][category] = 0
            hazard_stats['by_category'][category] += 1
        
        # Control statistics
        control_stats = {
            'total_controls': len(knowledge_base.control_library),
            'by_hierarchy': {}
        }
        
        for control in knowledge_base.control_library.values():
            hierarchy = control.control_type.value[0]
            if hierarchy not in control_stats['by_hierarchy']:
                control_stats['by_hierarchy'][hierarchy] = 0
            control_stats['by_hierarchy'][hierarchy] += 1
        
        # Regulation statistics
        regulation_stats = {
            'total_regulations': len(knowledge_base.regulation_library),
            'by_jurisdiction': {}
        }
        
        for reg in knowledge_base.regulation_library.values():
            jurisdiction = reg.jurisdiction
            if jurisdiction not in regulation_stats['by_jurisdiction']:
                regulation_stats['by_jurisdiction'][jurisdiction] = 0
            regulation_stats['by_jurisdiction'][jurisdiction] += 1
        
        # Industry profile statistics
        industry_stats = {
            'total_industries': len(knowledge_base.industry_profiles),
            'industries': [i.industry.value for i in knowledge_base.industry_profiles.values()]
        }
        
        # Session statistics
        session_stats = {
            'active_sessions': len(chat_sessions),
            'total_queries': sum(len(s.get('queries', [])) for s in chat_sessions.values())
        }
        
        # Cache statistics
        cache_dir = Path('./search_cache')
        if cache_dir.exists():
            cache_files = list(cache_dir.glob('*.json'))
            cache_size = sum(f.stat().st_size for f in cache_files)
            cache_stats = {
                'files_count': len(cache_files),
                'total_size_bytes': cache_size,
                'total_size_mb': round(cache_size / (1024 * 1024), 2),
                'last_modified': max((f.stat().st_mtime for f in cache_files), default=0)
            }
        else:
            cache_stats = {
                'files_count': 0,
                'total_size_bytes': 0,
                'total_size_mb': 0,
                'last_modified': 0
            }
        
        return jsonify({
            'success': True,
            'stats': {
                'knowledge_base': {
                    'hazards': hazard_stats,
                    'controls': control_stats,
                    'regulations': regulation_stats,
                    'industries': industry_stats,
                    'risk_assessment_methods': len(knowledge_base.risk_engine.methods)
                },
                'sessions': session_stats,
                'cache': cache_stats,
                'config': {
                    'default_timeout': 15,
                    'max_results': 5,
                    'min_relevance': 0.4,
                    'industries_available': len(Industry),
                    'hazard_categories_available': len(HazardCategory)
                }
            },
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        logger.error(f"Stats error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to get stats: {str(e)}',
            'code': 'STATS_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500


# ============================================================================
# ENDPOINT 7: /api/safety/search/test (POST)
# ============================================================================

@app.route('/api/safety/search/test', methods=['POST'])
@cross_origin()
def test_safety_search():
    """Test the HSE Knowledge Base with a sample query"""
    try:
        data = request.get_json() or {}
        
        test_query = data.get('query', 'fall protection requirements construction')
        industry = data.get('industry', 'construction')
        jurisdiction = data.get('jurisdiction', 'us')
        
        # Get HSE system
        hse_system = get_hse_system()
        
        # Map industry
        hse_industry = _map_industry(industry)
        
        start_time = time.time()
        
        # Test search with HSE advisor
        session_id = f"TEST-{uuid.uuid4().hex[:8].upper()}"
        response = hse_system.ask(
            question=test_query,
            user_id="test_user",
            session_id=session_id
        )
        
        search_time = (time.time() - start_time) * 1000  # ms
        
        # Check if search was successful
        test_passed = bool(response.get('answer')) and len(response.get('answer', '')) > 100
        
        result = {
            'success': True,
            'test_passed': test_passed,
            'query': test_query,
            'industry': industry,
            'jurisdiction': jurisdiction,
            'results_count': 1,
            'answer_length': len(response.get('answer', '')),
            'sources_used': ['hse_knowledge_base'],
            'search_time_ms': round(search_time, 2),
            'industries_detected': response.get('industries', []),
            'hazards_detected': response.get('hazards', []),
            'question_type': response.get('question_type', 'general'),
            'confidence': response.get('confidence', {}),
            'timestamp': datetime.now().isoformat()
        }
        
        # Additional diagnostics
        if test_passed:
            result['diagnostics'] = {
                'answer_preview': response.get('answer', '')[:200] + '...',
                'follow_up_suggestions': response.get('follow_up_suggestions', [])[:3],
                'references_count': len(response.get('references', []))
            }
        
        return jsonify(result)
        
    except Exception as e:
        logger.error(f"Test search error: {str(e)}")
        return jsonify({
            'success': False,
            'test_passed': False,
            'error': f'Test failed: {str(e)}',
            'code': 'TEST_ERROR',
            'timestamp': datetime.now().isoformat()
        }), 500


# ============================================================================
# ENDPOINT 8: /api/ai/system/status (GET)
# ============================================================================

@app.route('/api/ai/system/status', methods=['GET'])
@cross_origin()
def get_ai_system_status():
    """Get comprehensive AI system status and health - including HSE Knowledge Base"""
    start_time = datetime.now()
    try:
        # Try to verify JWT if present, but don't require it
        try:
            from flask_jwt_extended import verify_jwt_in_request, get_jwt_identity
            verify_jwt_in_request(optional=True)
            current_user = get_jwt_identity()
        except:
            current_user = None
        
        # Get HSE system components
        hse_system = get_hse_system()
        knowledge_base = get_hse_knowledge_base()
        advisor_engine = get_hse_advisor_engine()
        chat_interface = get_hse_chat_interface()
        
        # System information
        status_data = {
            'system': 'HSE Advisor AI Platform',
            'version': '2.0.0',
            'environment': os.getenv('FLASK_ENV', 'development'),
            'timestamp': datetime.now().isoformat(),
            'uptime_seconds': int(time.time() - app_start_time) if 'app_start_time' in globals() else 0
        }
        
        # Core services status
        services_status = {
            'hse_knowledge_base': 'operational' if knowledge_base else 'failed',
            'hse_advisor_engine': 'operational' if advisor_engine else 'failed',
            'hse_chat_interface': 'operational' if chat_interface else 'failed',
            'risk_assessment_engine': 'operational' if hasattr(knowledge_base, 'risk_engine') else 'failed'
        }
        
        # Knowledge base statistics
        kb_stats = {
            'hazards': len(knowledge_base.hazard_library) if knowledge_base else 0,
            'controls': len(knowledge_base.control_library) if knowledge_base else 0,
            'regulations': len(knowledge_base.regulation_library) if knowledge_base else 0,
            'industries': len(knowledge_base.industry_profiles) if knowledge_base else 0,
            'risk_methods': len(knowledge_base.risk_engine.methods) if hasattr(knowledge_base, 'risk_engine') else 0
        }
        
        # External service availability
        external_services = {
            'hse_knowledge_base': 'available',
            'ai_advisory_engine': 'available',
            'weasyprint': 'available' if 'weasyprint' in globals() else 'not_installed',
            'python_docx': 'available' if 'docx' in globals() else 'not_installed'
        }
        
        # System metrics
        try:
            import psutil
            process = psutil.Process()
            memory_info = process.memory_info()
            
            system_metrics = {
                'memory_usage_mb': memory_info.rss / (1024 * 1024),
                'memory_percent': process.memory_percent(),
                'cpu_percent': process.cpu_percent(interval=0.1),
                'thread_count': process.num_threads(),
                'open_files': len(process.open_files()) if hasattr(process, 'open_files') else 0
            }
        except:
            system_metrics = {
                'memory_usage_mb': 0,
                'memory_percent': 0,
                'cpu_percent': 0,
                'thread_count': 0,
                'open_files': 0
            }
        
        # Session statistics
        active_sessions = {
            'chat_sessions': len(chat_sessions),
            'hse_advisor_sessions': len(chat_interface.sessions) if chat_interface else 0,
            'total_conversations': sum(len(s.get('question_history', [])) for s in chat_interface.sessions.values()) if chat_interface else 0
        }
        
        # Recent activity (last 5 minutes)
        recent_activity = {
            'searches_performed': 0,  # Would need tracking
            'documents_generated': 0,
            'exams_taken': 0,
            'advisor_queries': active_sessions.get('total_conversations', 0)
        }
        
        # Determine overall health
        operational_services = sum(1 for status in services_status.values() if status == 'operational')
        total_services = len(services_status)
        health_percentage = (operational_services / total_services) * 100 if total_services > 0 else 0
        
        if health_percentage >= 80:
            overall_status = 'healthy'
        elif health_percentage >= 50:
            overall_status = 'degraded'
        elif health_percentage >= 25:
            overall_status = 'critical'
        else:
            overall_status = 'failed'
        
        # Build response
        response = {
            'success': True,
            'status': overall_status,
            'health_percentage': round(health_percentage, 2),
            'system_info': status_data,
            'services': services_status,
            'knowledge_base_stats': kb_stats,
            'external_services': external_services,
            'metrics': system_metrics,
            'sessions': active_sessions,
            'activity': recent_activity,
            'checks': {
                'timestamp': datetime.now().isoformat(),
                'duration_ms': (datetime.now() - start_time).total_seconds() * 1000
            },
            'capabilities': {
                'risk_assessment': True,
                'hazard_identification': True,
                'control_measures': True,
                'regulatory_guidance': True,
                'training_requirements': True,
                'incident_investigation': True,
                'emergency_response': True,
                'industrial_hygiene': True,
                'process_safety': True,
                'environmental_compliance': True,
                'multi_industry_support': len(Industry) > 0,
                'multi_jurisdiction': len(set(r.jurisdiction for r in knowledge_base.regulation_library.values())) > 0 if knowledge_base else False
            },
            'recommendations': []
        }
        
        # Add recommendations if any issues
        if kb_stats['hazards'] == 0:
            response['recommendations'].append('Hazard library is empty - check knowledge base initialization')
        
        if kb_stats['controls'] == 0:
            response['recommendations'].append('Control library is empty - check knowledge base initialization')
        
        if external_services.get('weasyprint') == 'not_installed':
            response['recommendations'].append('Install weasyprint for PDF generation: pip install weasyprint')
        
        # Add cache statistics
        try:
            cache_dir = Path('./search_cache')
            if cache_dir.exists():
                cache_files = list(cache_dir.glob('*.json'))
                cache_size = sum(f.stat().st_size for f in cache_files)
                response['cache'] = {
                    'files': len(cache_files),
                    'size_mb': round(cache_size / (1024 * 1024), 2)
                }
        except:
            pass
        
        # Add user info
        response['user_info'] = {
            'authenticated': bool(current_user),
            'user_id': current_user if current_user else 'anonymous',
            'permissions': ['basic_access']
        }
        
        logger.info(f"System status checked: {overall_status} ({health_percentage}%) by user: {current_user or 'anonymous'}")
        
        return jsonify(response)
        
    except Exception as e:
        logger.error(f"System status endpoint error: {str(e)}")
        return jsonify({
            'success': False,
            'status': 'error',
            'error': f'Failed to get system status: {str(e)}',
            'timestamp': datetime.now().isoformat()
        }), 500


