@app.route('/api/hse/industries', methods=['GET'])
@cross_origin()
def list_hse_industries():
    """List all industries supported by HSE Knowledge Base"""
    try:
        knowledge_base = get_hse_knowledge_base()
        
        industries = []
        for industry_enum in Industry:
            profile = knowledge_base.get_industry_profile(industry_enum)
            industries.append({
                'id': industry_enum.name,
                'name': industry_enum.value,
                'hazard_count': len(knowledge_base.get_hazards_by_industry(industry_enum)) if profile else 0,
                'has_profile': profile is not None
            })
        
        return jsonify({
            'success': True,
            'industries': industries,
            'total': len(industries),
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        logger.error(f"List industries error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to list industries: {str(e)}',
            'timestamp': datetime.now().isoformat()
        }), 500


@app.route('/api/hse/hazards', methods=['GET'])
@cross_origin()
def list_hse_hazards():
    """List all hazards in HSE Knowledge Base"""
    try:
        knowledge_base = get_hse_knowledge_base()
        industry = request.args.get('industry')
        
        hazards = []
        
        if industry:
            # Get hazards for specific industry
            industry_enum = None
            for ind in Industry:
                if industry.lower() in ind.value.lower():
                    industry_enum = ind
                    break
            
            if industry_enum:
                industry_hazards = knowledge_base.get_hazards_by_industry(industry_enum)
                for hazard in industry_hazards[:20]:  # Limit to 20
                    hazards.append({
                        'id': hazard.id,
                        'name': hazard.name,
                        'category': hazard.category.value,
                        'description': hazard.description[:100] + '...',
                        'severity_potential': hazard.severity_potential
                    })
        else:
            # Get all hazards (limited)
            for hazard_id, hazard in list(knowledge_base.hazard_library.items())[:50]:
                hazards.append({
                    'id': hazard.id,
                    'name': hazard.name,
                    'category': hazard.category.value,
                    'description': hazard.description[:100] + '...',
                    'industries': [i.value for i in hazard.industries[:3]]
                })
        
        return jsonify({
            'success': True,
            'hazards': hazards,
            'total': len(hazards),
            'industry': industry if industry else 'all',
            'timestamp': datetime.now().isoformat()
        })
        
    except Exception as e:
        logger.error(f"List hazards error: {str(e)}")
        return jsonify({
            'success': False,
            'error': f'Failed to list hazards: {str(e)}',
            'timestamp': datetime.now().isoformat()
        }), 500


