@app.route('/api/incidents/stats', methods=['GET'], endpoint='get_notification_incident_stats')
@jwt_required
def get_notification_incident_stats():
    """Get incident statistics"""
    try:
        current_user = request.user
        time_range = request.args.get('timeRange', 'month')
        
        # Incident analytics require at least Pro plan
        if 'incident_analytics' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Incident analytics not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for incident statistics and analytics',
                'basic_reporting': '/api/incidents'
            }), 403
        
        # Validate time range
        allowed_ranges = ['day', 'week', 'month', 'quarter', 'year']
        if time_range not in allowed_ranges:
            return jsonify({
                'success': False,
                'error': f'Invalid time range. Allowed: {", ".join(allowed_ranges)}',
                'code': 'INVALID_TIME_RANGE',
                'suggestion': f'Choose from allowed time ranges'
            }), 400
        
        # Calculate date range
        end_date = datetime.utcnow()
        if time_range == 'day':
            start_date = end_date - timedelta(days=1)
        elif time_range == 'week':
            start_date = end_date - timedelta(weeks=1)
        elif time_range == 'month':
            start_date = end_date - timedelta(days=30)
        elif time_range == 'quarter':
            start_date = end_date - timedelta(days=90)
        else:  # year
            start_date = end_date - timedelta(days=365)
        
        # Build base query based on user role
        if current_user.user_type in ['admin', 'safety_officer', 'manager', 'safety_manager'] or request.is_system_team:
            base_query = Incident.query
            access_level = 'organization'
        else:
            base_query = Incident.query.filter_by(reported_by=current_user.id)
            access_level = 'personal'
        
        # Get statistics
        total_incidents = base_query.filter(
            Incident.date_reported >= start_date
        ).count()
        
        incidents_by_severity = db.session.query(
            Incident.severity,
            func.count(Incident.id)
        ).filter(
            Incident.date_reported >= start_date
        )
        if access_level == 'personal':
            incidents_by_severity = incidents_by_severity.filter(Incident.reported_by == current_user.id)
        incidents_by_severity = incidents_by_severity.group_by(Incident.severity).all()
        
        incidents_by_status = db.session.query(
            Incident.status,
            func.count(Incident.id)
        ).filter(
            Incident.date_reported >= start_date
        )
        if access_level == 'personal':
            incidents_by_status = incidents_by_status.filter(Incident.reported_by == current_user.id)
        incidents_by_status = incidents_by_status.group_by(Incident.status).all()
        
        incidents_by_type = db.session.query(
            Incident.incident_type,
            func.count(Incident.id)
        ).filter(
            Incident.date_reported >= start_date
        )
        if access_level == 'personal':
            incidents_by_type = incidents_by_type.filter(Incident.reported_by == current_user.id)
        incidents_by_type = incidents_by_type.group_by(Incident.incident_type).all()
        
        # Calculate average resolution time
        resolved_query = base_query.filter(
            Incident.status.in_(['resolved', 'closed']),
            Incident.date_reported >= start_date,
            Incident.resolution_date.isnot(None)
        )
        resolved_incidents = resolved_query.all()
        
        avg_resolution_hours = 0
        if resolved_incidents:
            total_hours = sum([
                (inc.resolution_date - inc.date_reported).total_seconds() / 3600
                for inc in resolved_incidents
            ])
            avg_resolution_hours = total_hours / len(resolved_incidents)
        
        # Additional metrics for Business/Enterprise plans
        advanced_metrics = {}
        if request.effective_plan in ['business', 'enterprise']:
            # Time to first response
            responded_incidents = IncidentTimeline.query.filter(
                IncidentTimeline.action == 'assignment',
                IncidentTimeline.timestamp >= start_date
            ).count()
            
            # Repeat incidents (same type within 30 days)
            if time_range in ['quarter', 'year'] and 'incident_trend_analysis' in request.plan_features:
                # Complex analysis for Business/Enterprise
                pass
            
            advanced_metrics = {
                'incidents_responded': responded_incidents,
                'response_rate': (responded_incidents / total_incidents * 100) if total_incidents > 0 else 0,
                'trend_analysis_available': 'incident_trend_analysis' in request.plan_features
            }
        
        stats = {
            'time_range': time_range,
            'period': {
                'start': start_date.isoformat(),
                'end': end_date.isoformat(),
                'days': (end_date - start_date).days
            },
            'total_incidents': total_incidents,
            'incidents_by_severity': dict(incidents_by_severity),
            'incidents_by_status': dict(incidents_by_status),
            'incidents_by_type': dict(incidents_by_type),
            'avg_resolution_hours': round(avg_resolution_hours, 2),
            'open_investigations': base_query.filter(
                Incident.status == 'investigating'
            ).count(),
            'access_level': access_level,
            **advanced_metrics
        }
        
        # Add recommendations for Pro+ plans
        if request.effective_plan in ['pro', 'business', 'enterprise']:
            recommendations = []
            
            if incidents_by_severity and 'critical' in dict(incidents_by_severity) and dict(incidents_by_severity)['critical'] > 0:
                recommendations.append('Critical incidents detected. Review safety protocols immediately.')
            
            if avg_resolution_hours > 72:  # More than 3 days
                recommendations.append('Average resolution time is high. Consider streamlining investigation process.')
            
            if stats['open_investigations'] > 5:
                recommendations.append('High number of open investigations. Assign additional resources.')
            
            stats['recommendations'] = recommendations
        
        return jsonify({
            'success': True,
            'statistics': stats,
            'analytics_capabilities': {
                'time_series_analysis': 'incident_time_series' in request.plan_features,
                'predictive_analytics': 'predictive_incident_analysis' in request.plan_features,
                'export_dashboard': 'incident_dashboard_export' in request.plan_features,
                'real_time_updates': request.effective_plan == 'enterprise'
            },
            'export_options': {
                'json': True,
                'csv': 'data_export' in request.plan_features,
                'pdf': 'report_export' in request.plan_features,
                'excel': request.effective_plan in ['business', 'enterprise']
            },
            'next_period_start': (end_date + timedelta(days=1)).isoformat() if time_range != 'day' else None
        }), 200
        
    except Exception as e:
        logger.error(f'Failed to fetch incident statistics: {str(e)}')
        return jsonify({
            'success': False,
            'error': 'Failed to fetch incident statistics',
            'code': 'STATS_FETCH_ERROR',
            'suggestion': 'Try a different time range or contact support',
            'timestamp': datetime.now().isoformat()
        }), 500
    
@app.route('/api/incidents/export', methods=['POST'], endpoint='export_notification_incidents')
@jwt_required
def export_notification_incidents():
    """Export incidents to CSV and other formats"""
    try:
        current_user = request.user
        data = request.get_json() or {}
        export_format = data.get('format', 'csv')
        
        # Check if export feature is available in plan
        if 'data_export' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Data export not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for data export capabilities',
                'view_only_endpoint': '/api/incidents',
                'timestamp': datetime.utcnow().isoformat()
            }), 403
        
        # Check if user has permission to export
        if not (current_user.user_type in ['admin', 'safety_officer', 'manager', 'safety_manager'] or request.is_system_team):
            return jsonify({
                'success': False,
                'error': 'Unauthorized to export incidents',
                'code': 'EXPORT_PERMISSION_DENIED',
                'suggestion': 'Only safety managers and administrators can export incident data',
                'timestamp': datetime.utcnow().isoformat()
            }), 403
        
        # Validate export format
        allowed_formats = {
            'free': ['csv'],
            'pro': ['csv', 'json'],
            'business': ['csv', 'json', 'excel'],
            'enterprise': ['csv', 'json', 'excel', 'pdf', 'html']
        }
        
        available_formats = allowed_formats.get(request.effective_plan, ['csv'])
        if export_format not in available_formats:
            return jsonify({
                'success': False,
                'error': f'Export format {export_format} not available in your plan',
                'code': 'EXPORT_FORMAT_NOT_AVAILABLE',
                'available_formats': available_formats,
                'suggestion': f'Choose from available formats or upgrade plan',
                'timestamp': datetime.utcnow().isoformat()
            }), 400
        
        # Check export frequency limits for non-enterprise plans
        if request.effective_plan != 'enterprise':
            max_daily_exports = request.plan_limits.get('max_daily_exports', 5)
            today = datetime.utcnow().date()
            exports_today = DataExportLog.query.filter(
                DataExportLog.user_id == current_user.id,
                db.func.date(DataExportLog.created_at) == today,
                DataExportLog.export_type == 'incidents'
            ).count()
            
            if exports_today >= max_daily_exports:
                return jsonify({
                    'success': False,
                    'error': f'Daily export limit reached ({max_daily_exports})',
                    'code': 'DAILY_EXPORT_LIMIT_REACHED',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited exports',
                    'current_usage': exports_today,
                    'reset_time': (datetime.utcnow() + timedelta(days=1)).replace(hour=0, minute=0, second=0).isoformat(),
                    'timestamp': datetime.utcnow().isoformat()
                }), 403
        
        # Check max rows based on plan
        max_rows = {
            'free': 100,
            'pro': 1000,
            'business': 5000,
            'enterprise': 100000
        }.get(request.effective_plan, 100)
        
        # Build query with filters
        query = Incident.query
        
        if data.get('status'):
            statuses = data['status'] if isinstance(data['status'], list) else [data['status']]
            query = query.filter(Incident.status.in_(statuses))
        
        if data.get('severity'):
            severities = data['severity'] if isinstance(data['severity'], list) else [data['severity']]
            query = query.filter(Incident.severity.in_(severities))
        
        if data.get('incident_type'):
            types = data['incident_type'] if isinstance(data['incident_type'], list) else [data['incident_type']]
            query = query.filter(Incident.incident_type.in_(types))
        
        if data.get('date_from'):
            try:
                date_from = datetime.fromisoformat(data['date_from'].replace('Z', '+00:00'))
                query = query.filter(Incident.date_occurred >= date_from)
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid date_from format',
                    'code': 'INVALID_DATE_FORMAT',
                    'suggestion': 'Use ISO 8601 format: YYYY-MM-DDTHH:MM:SSZ',
                    'timestamp': datetime.utcnow().isoformat()
                }), 400
        
        if data.get('date_to'):
            try:
                date_to = datetime.fromisoformat(data['date_to'].replace('Z', '+00:00'))
                query = query.filter(Incident.date_occurred <= date_to)
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid date_to format',
                    'code': 'INVALID_DATE_FORMAT',
                    'suggestion': 'Use ISO 8601 format: YYYY-MM-DDTHH:MM:SSZ',
                    'timestamp': datetime.utcnow().isoformat()
                }), 400
        
        # Apply row limit
        total_incidents = query.count()
        if total_incidents > max_rows:
            query = query.limit(max_rows)
        
        incidents = query.order_by(desc(Incident.created_at)).all()
        
        # Log the export
        export_log = DataExportLog(
            user_id=current_user.id,
            export_type='incidents',
            format=export_format,
            row_count=len(incidents),
            filter_criteria=str(data),
            plan=request.effective_plan
        )
        db.session.add(export_log)
        db.session.commit()
        
        # Update usage counter
        if request.effective_plan != 'enterprise':
            current_user.daily_exports = getattr(current_user, 'daily_exports', 0) + 1
            db.session.commit()
        
        # Generate export based on format
        if export_format == 'csv':
            return generate_csv_export(incidents, export_log.id)
        elif export_format == 'json':
            return generate_json_export(incidents, export_log.id)
        elif export_format == 'excel':
            if request.effective_plan in ['business', 'enterprise']:
                return generate_excel_export(incidents, export_log.id)
        elif export_format == 'pdf':
            if request.effective_plan == 'enterprise':
                return generate_pdf_export(incidents, export_log.id)
        elif export_format == 'html':
            if request.effective_plan == 'enterprise':
                return generate_html_export(incidents, export_log.id)
        
        # Default to CSV
        return generate_csv_export(incidents, export_log.id)
        
    except Exception as e:
        db.session.rollback()
        logger.error(f'Failed to export incidents: {str(e)}')
        return jsonify({
            'success': False,
            'error': 'Failed to export incidents',
            'code': 'EXPORT_GENERATION_ERROR',
            'suggestion': 'Try again with fewer records or different filters',
            'timestamp': datetime.utcnow().isoformat()
        }), 500

# Export generation helper functions
def generate_csv_export(incidents, export_log_id):
    """Generate CSV export"""
    output = io.StringIO()
    writer = csv.writer(output)
    
    # Enhanced header for premium plans
    headers = [
        'Incident Number', 'Title', 'Description', 'Type', 'Severity', 'Status',
        'Location', 'Department', 'Date Occurred', 'Date Reported',
        'Reported By', 'Reported By Email', 'Assigned To', 'Assigned To Email',
        'Resolution Date', 'Investigation Details', 'Corrective Actions',
        'Root Cause', 'Created At', 'Updated At'
    ]
    
    writer.writerow(headers)
    
    # Write data
    for incident in incidents:
        writer.writerow([
            incident.incident_number,
            incident.title,
            incident.description,
            incident.incident_type,
            incident.severity,
            incident.status,
            incident.location or '',
            incident.department or '',
            incident.date_occurred.isoformat() if incident.date_occurred else '',
            incident.date_reported.isoformat() if incident.date_reported else '',
            incident.reporter.name if incident.reporter else '',
            incident.reporter.email if incident.reporter else '',
            incident.assignee.name if incident.assignee else '',
            incident.assignee.email if incident.assignee else '',
            incident.resolution_date.isoformat() if incident.resolution_date else '',
            incident.investigation_details or '',
            incident.corrective_actions or '',
            incident.root_cause or '',
            incident.created_at.isoformat() if incident.created_at else '',
            incident.updated_at.isoformat() if incident.updated_at else ''
        ])
    
    output.seek(0)
    
    filename = f'incidents_export_{datetime.utcnow().strftime("%Y%m%d_%H%M%S")}_{export_log_id}.csv'
    
    return send_file(
        BytesIO(output.getvalue().encode()),
        mimetype='text/csv',
        as_attachment=True,
        download_name=filename
    )

def generate_json_export(incidents, export_log_id):
    """Generate JSON export"""
    incidents_data = []
    for incident in incidents:
        incidents_data.append({
            'incident_number': incident.incident_number,
            'title': incident.title,
            'description': incident.description,
            'type': incident.incident_type,
            'severity': incident.severity,
            'status': incident.status,
            'location': incident.location,
            'department': incident.department,
            'date_occurred': incident.date_occurred.isoformat() if incident.date_occurred else None,
            'date_reported': incident.date_reported.isoformat() if incident.date_reported else None,
            'reported_by': {
                'name': incident.reporter.name if incident.reporter else None,
                'email': incident.reporter.email if incident.reporter else None
            },
            'assigned_to': {
                'name': incident.assignee.name if incident.assignee else None,
                'email': incident.assignee.email if incident.assignee else None
            },
            'resolution_date': incident.resolution_date.isoformat() if incident.resolution_date else None,
            'investigation_details': incident.investigation_details,
            'corrective_actions': incident.corrective_actions,
            'root_cause': incident.root_cause,
            'timeline': get_incident_timeline(incident.id) if hasattr(incident, 'id') else []
        })
    
    export_data = {
        'export_id': export_log_id,
        'generated_at': datetime.utcnow().isoformat(),
        'total_incidents': len(incidents),
        'incidents': incidents_data,
        'metadata': {
            'export_format': 'json',
            'version': '1.0'
        }
    }
    
    filename = f'incidents_export_{datetime.utcnow().strftime("%Y%m%d_%H%M%S")}_{export_log_id}.json'
    
    return send_file(
        BytesIO(json.dumps(export_data, indent=2).encode()),
        mimetype='application/json',
        as_attachment=True,
        download_name=filename
    )

@app.route('/api/incidents/<int:incident_id>/upload', methods=['POST'], endpoint='upload_incident_evidence')
@jwt_required
def upload_incident_evidence(incident_id):
    """Upload evidence files for an incident"""
    try:
        current_user = request.user
        
        # Check if incident exists
        incident = Incident.query.get(incident_id)
        if not incident:
            return jsonify({
                'success': False,
                'error': 'Incident not found',
                'code': 'INCIDENT_NOT_FOUND'
            }), 404
        
        # Check permissions
        can_upload = False
        if current_user.user_type in ['admin', 'safety_officer', 'manager', 'safety_manager'] or request.is_system_team:
            can_upload = True
        elif incident.reported_by == current_user.id:
            can_upload = True
        elif incident.assigned_to == current_user.id:
            can_upload = True
        
        if not can_upload:
            return jsonify({
                'success': False,
                'error': 'Unauthorized to upload files',
                'code': 'UPLOAD_PERMISSION_DENIED'
            }), 403
        
        # Check if file was uploaded
        if 'file' not in request.files:
            return jsonify({
                'success': False,
                'error': 'No file provided',
                'code': 'NO_FILE'
            }), 400
        
        file = request.files['file']
        
        if file.filename == '':
            return jsonify({
                'success': False,
                'error': 'No file selected',
                'code': 'NO_FILE_SELECTED'
            }), 400
        
        # Validate file
        if not allowed_file(file.filename):
            return jsonify({
                'success': False,
                'error': f'File type not allowed. Allowed: {", ".join(ALLOWED_EXTENSIONS)}',
                'code': 'FILE_TYPE_NOT_ALLOWED'
            }), 400
        
        # Check file size
        file.seek(0, os.SEEK_END)
        file_size = file.tell()
        file.seek(0)
        
        if file_size > MAX_FILE_SIZE:
            return jsonify({
                'success': False,
                'error': f'File too large. Max size: {MAX_FILE_SIZE / (1024 * 1024)}MB',
                'code': 'FILE_TOO_LARGE'
            }), 400
        
        # Check number of files
        existing_files = IncidentAttachment.query.filter_by(incident_id=incident_id).count()
        if existing_files >= MAX_FILES_PER_INCIDENT:
            return jsonify({
                'success': False,
                'error': f'Maximum {MAX_FILES_PER_INCIDENT} files per incident',
                'code': 'MAX_FILES_REACHED'
            }), 400
        
        # Create upload directory if not exists
        incident_folder = os.path.join(UPLOAD_FOLDER, str(incident_id))
        os.makedirs(incident_folder, exist_ok=True)
        
        # Generate secure filename
        original_filename = secure_filename(file.filename)
        file_extension = original_filename.rsplit('.', 1)[1].lower() if '.' in original_filename else ''
        unique_filename = f"{uuid.uuid4().hex}.{file_extension}"
        file_path = os.path.join(incident_folder, unique_filename)
        
        # Save file
        file.save(file_path)
        
        # Create attachment record
        attachment = IncidentAttachment(
            incident_id=incident_id,
            filename=original_filename,
            stored_filename=unique_filename,
            file_path=file_path,
            file_size=file_size,
            file_type=file.content_type or 'application/octet-stream',
            uploaded_by=current_user.id,
            uploaded_at=datetime.utcnow(),
            metadata={
                'uploaded_by_name': current_user.name or current_user.email,
                'uploaded_by_role': current_user.user_type,
                'ip_address': request.remote_addr
            }
        )
        
        db.session.add(attachment)
        
        # Add to incident timeline
        timeline_entry = IncidentTimeline(
            incident_id=incident_id,
            action='file_uploaded',
            details=f'File uploaded: {original_filename}',
            user_id=current_user.id,
            timestamp=datetime.utcnow(),
            data={
                'filename': original_filename,
                'file_size': file_size,
                'file_type': file.content_type,
                'attachment_id': attachment.id
            }
        )
        db.session.add(timeline_entry)
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'File uploaded successfully',
            'attachment': {
                'id': attachment.id,
                'filename': attachment.filename,
                'file_size': attachment.file_size,
                'file_type': attachment.file_type,
                'uploaded_at': attachment.uploaded_at.isoformat(),
                'uploaded_by': attachment.uploaded_by,
                'uploaded_by_name': current_user.name or current_user.email
            },
            'timeline': timeline_entry.to_dict()
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f'Failed to upload file: {str(e)}')
        return jsonify({
            'success': False,
            'error': 'Failed to upload file',
            'code': 'UPLOAD_ERROR'
        }), 500


