@app.route('/api/notifications', methods=['GET'], endpoint='get_report_notifications')
@jwt_required
def get_report_notifications():
    """Get all notifications for current user"""
    try:
        user_id = request.user_id
        current_user = request.user
        
        # Check notification access based on plan
        if 'notification_history' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Notification history not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan to view notification history',
                'timestamp': datetime.utcnow().isoformat()
            }), 403
        
        # Pagination
        page = int(request.args.get('page', 1))
        per_page_limits = {
            'free': 10,
            'pro': 50,
            'business': 100,
            'enterprise': 200
        }
        max_per_page = per_page_limits.get(request.effective_plan, 10)
        per_page = min(int(request.args.get('per_page', 20)), max_per_page)
        
        unread_only = request.args.get('unread_only', 'false').lower() == 'true'
        notification_type = request.args.get('type')
        priority = request.args.get('priority')
        
        query = Notification.query.filter_by(user_id=user_id)
        
        if unread_only:
            query = query.filter_by(is_read=False)
        
        if notification_type:
            query = query.filter_by(notification_type=notification_type)
        
        if priority:
            query = query.filter_by(priority=priority)
        
        # Apply retention policy based on plan
        retention_days = {
            'free': 7,
            'pro': 30,
            'business': 90,
            'enterprise': 365
        }.get(request.effective_plan, 7)
        
        cutoff_date = datetime.utcnow() - timedelta(days=retention_days)
        query = query.filter(Notification.created_at >= cutoff_date)
        
        notifications = query.order_by(desc(Notification.created_at)).paginate(
            page=page, per_page=per_page, error_out=False
        )
        
        # Enhance notification data based on plan
        enhanced_notifications = []
        for notification in notifications.items:
            notification_data = notification.to_dict()
            
            # Add action suggestions for Business/Enterprise
            if request.effective_plan in ['business', 'enterprise']:
                if notification.notification_type == 'incident_assigned':
                    notification_data['suggested_actions'] = [
                        'Review incident details',
                        'Start investigation',
                        'Schedule follow-up meeting'
                    ]
                elif notification.notification_type == 'incident_status_change':
                    notification_data['suggested_actions'] = [
                        'Review updated status',
                        'Update documentation',
                        'Notify stakeholders'
                    ]
            
            enhanced_notifications.append(notification_data)
        
        return jsonify({
            'success': True,
            'notifications': enhanced_notifications,
            'total': notifications.total,
            'unread_count': Notification.query.filter_by(
                user_id=user_id, is_read=False
            ).filter(Notification.created_at >= cutoff_date).count(),
            'page': page,
            'per_page': per_page,
            'pages': notifications.pages,
            'retention_policy': {
                'days': retention_days,
                'older_notifications_archived': True
            },
            'plan_limits': {
                'max_per_page': max_per_page,
                'history_available': 'notification_history' in request.plan_features,
                'advanced_filtering': request.effective_plan in ['business', 'enterprise']
            },
            'summary': {
                'total_notifications': notifications.total,
                'unread_percentage': (notifications.total - Notification.query.filter_by(
                    user_id=user_id, is_read=True
                ).filter(Notification.created_at >= cutoff_date).count()) / notifications.total * 100 if notifications.total > 0 else 0
            }
        }), 200
        
    except Exception as e:
        logger.error(f'Failed to fetch notifications: {str(e)}')
        return jsonify({
            'success': False,
            'error': 'Failed to fetch notifications',
            'code': 'NOTIFICATIONS_FETCH_ERROR',
            'suggestion': 'Try again or contact support',
            'timestamp': datetime.utcnow().isoformat()
        }), 500

@app.route('/api/notifications/<int:notification_id>/read', methods=['POST'], endpoint='mark_report_notification_read')
@jwt_required
def mark_report_notification_read(notification_id):
    """Mark single notification as read"""
    try:
        user_id = request.user_id
        
        notification = Notification.query.filter_by(
            id=notification_id, user_id=user_id
        ).first()
        
        if not notification:
            return jsonify({
                'success': False,
                'error': 'Notification not found',
                'code': 'NOTIFICATION_NOT_FOUND',
                'suggestion': 'Check notification ID or access permissions',
                'timestamp': datetime.utcnow().isoformat()
            }), 404
        
        if notification.is_read:
            return jsonify({
                'success': True,
                'message': 'Notification already marked as read',
                'notification_id': notification_id,
                'timestamp': datetime.utcnow().isoformat()
            }), 200
        
        notification.is_read = True
        notification.read_at = datetime.utcnow()
        db.session.commit()
        
        # Log notification interaction for analytics
        if request.effective_plan in ['business', 'enterprise']:
            interaction_log = NotificationInteractionLog(
                notification_id=notification_id,
                user_id=user_id,
                action='marked_read',
                interaction_time=datetime.utcnow(),
                plan=request.effective_plan
            )
            db.session.add(interaction_log)
            db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Notification marked as read',
            'notification_id': notification_id,
            'read_at': notification.read_at.isoformat(),
            'remaining_unread': Notification.query.filter_by(
                user_id=user_id, is_read=False
            ).count(),
            'timestamp': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f'Failed to mark notification as read: {str(e)}')
        return jsonify({
            'success': False,
            'error': 'Failed to mark notification as read',
            'code': 'NOTIFICATION_MARK_READ_ERROR',
            'suggestion': 'Try again or contact support',
            'timestamp': datetime.utcnow().isoformat()
        }), 500

@app.route('/api/notifications/mark-read', methods=['POST'], endpoint='mark_all_report_notifications_read')
@jwt_required
def mark_all_report_notifications_read():
    """Mark all notifications as read for current user"""
    try:
        user_id = request.user_id
        
        # Check bulk operation limit for non-enterprise plans
        if request.effective_plan != 'enterprise':
            max_bulk_operations = request.plan_limits.get('max_bulk_notification_operations', 10)
            today = datetime.utcnow().date()
            bulk_ops_today = NotificationBulkOperation.query.filter(
                NotificationBulkOperation.user_id == user_id,
                db.func.date(NotificationBulkOperation.created_at) == today
            ).count()
            
            if bulk_ops_today >= max_bulk_operations:
                return jsonify({
                    'success': False,
                    'error': f'Daily bulk notification operation limit reached ({max_bulk_operations})',
                    'code': 'BULK_OPERATION_LIMIT_REACHED',
                    'suggestion': 'Mark notifications individually or upgrade to Enterprise plan',
                    'current_usage': bulk_ops_today,
                    'reset_time': (datetime.utcnow() + timedelta(days=1)).replace(hour=0, minute=0, second=0).isoformat(),
                    'timestamp': datetime.utcnow().isoformat()
                }), 403
        
        unread_count = Notification.query.filter_by(
            user_id=user_id, is_read=False
        ).count()
        
        if unread_count == 0:
            return jsonify({
                'success': True,
                'message': 'No unread notifications to mark',
                'unread_count': 0,
                'timestamp': datetime.utcnow().isoformat()
            }), 200
        
        # Update all unread notifications
        Notification.query.filter_by(
            user_id=user_id, is_read=False
        ).update({'is_read': True, 'read_at': datetime.utcnow()})
        
        # Log bulk operation
        bulk_op = NotificationBulkOperation(
            user_id=user_id,
            action='mark_all_read',
            affected_count=unread_count,
            plan=request.effective_plan
        )
        db.session.add(bulk_op)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Marked {unread_count} notifications as read',
            'unread_count': 0,
            'operation_id': bulk_op.id,
            'timestamp': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f'Failed to mark all notifications as read: {str(e)}')
        return jsonify({
            'success': False,
            'error': 'Failed to mark all notifications as read',
            'code': 'BULK_MARK_READ_ERROR',
            'suggestion': 'Try marking notifications individually or contact support',
            'timestamp': datetime.utcnow().isoformat()
        }), 500

