@app.route('/api/notifications/preferences/<int:user_id>', methods=['PUT'], endpoint='update_report_notification_preferences')
@jwt_required
def update_report_notification_preferences(user_id):
    """Update notification preferences"""
    try:
        current_user = request.user
        data = request.get_json()
        
        # Check if user is updating their own preferences or has permission
        if current_user.id != user_id and not (current_user.user_type in ['admin', 'safety_officer', 'manager', 'safety_manager'] or request.is_system_team):
            return jsonify({
                'success': False,
                'error': 'Unauthorized to update notification preferences',
                'code': 'PREFERENCES_UPDATE_DENIED',
                'suggestion': 'You can only update your own notification preferences',
                'timestamp': datetime.utcnow().isoformat()
            }), 403
        
        # Check if notification preferences feature is available
        if 'notification_preferences' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Notification preferences not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan to customize notification preferences',
                'timestamp': datetime.utcnow().isoformat()
            }), 403
        
        preferences = NotificationPreferences.query.filter_by(user_id=user_id).first()
        
        if not preferences:
            preferences = NotificationPreferences(
                user_id=user_id,
                **get_default_notification_preferences(request.effective_plan)
            )
            db.session.add(preferences)
        
        # Track changes
        changes = []
        
        # Update basic preferences
        basic_fields = [
            'email_enabled', 'push_enabled', 'sms_enabled', 'in_app_enabled',
            'incident_alerts', 'status_updates', 'assignment_notifications',
            'overdue_alerts', 'daily_digest', 'weekly_report'
        ]
        
        for field in basic_fields:
            if field in data:
                old_value = getattr(preferences, field)
                new_value = data[field]
                if old_value != new_value:
                    setattr(preferences, field, new_value)
                    changes.append({
                        'field': field,
                        'old_value': old_value,
                        'new_value': new_value
                    })
        
        # Update advanced preferences for Business/Enterprise
        if request.effective_plan in ['business', 'enterprise']:
            advanced_fields = [
                'quiet_hours_start', 'quiet_hours_end',
                'high_priority_only', 'urgent_notifications_only',
                'mobile_vibration', 'mobile_sound'
            ]
            
            for field in advanced_fields:
                if field in data:
                    old_value = getattr(preferences, field, None)
                    new_value = data[field]
                    if old_value != new_value:
                        setattr(preferences, field, new_value)
                        changes.append({
                            'field': field,
                            'old_value': old_value,
                            'new_value': new_value
                        })
        
        # Update Enterprise-specific preferences
        if request.effective_plan == 'enterprise':
            enterprise_fields = [
                'custom_notification_sounds', 'notification_routing_rules',
                'escalation_notifications', 'compliance_alerts'
            ]
            
            for field in enterprise_fields:
                if field in data:
                    setattr(preferences, field, data[field])
        
        preferences.updated_at = datetime.utcnow()
        db.session.commit()
        
        # Log preference changes for audit
        if changes and request.effective_plan in ['business', 'enterprise']:
            audit_log = PreferenceAuditLog(
                user_id=user_id,
                changed_by=current_user.id,
                changes=json.dumps(changes),
                ip_address=request.remote_addr,
                plan=request.effective_plan
            )
            db.session.add(audit_log)
            db.session.commit()
        
        return jsonify({
            'success': True,
            'preferences': preferences.to_dict(),
            'message': 'Notification preferences updated successfully',
            'changes_made': changes if changes else None,
            'audit_log_id': audit_log.id if 'audit_log' in locals() else None,
            'next_steps': [
                'Test notification delivery',
                'Review notification history',
                'Adjust settings as needed'
            ],
            'timestamp': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f'Failed to update notification preferences: {str(e)}')
        return jsonify({
            'success': False,
            'error': 'Failed to update notification preferences',
            'code': 'PREFERENCES_UPDATE_ERROR',
            'suggestion': 'Check your input values and try again',
            'timestamp': datetime.utcnow().isoformat()
        }), 500

@app.route('/api/notifications/clear-all', methods=['DELETE'], endpoint='clear_all_report_notifications')
@jwt_required
def clear_all_report_notifications():
    """Clear all notifications for current user"""
    try:
        user_id = request.user_id
        
        # Check if user can clear all notifications
        if 'notification_management' not in request.plan_features and request.effective_plan == 'free':
            return jsonify({
                'success': False,
                'error': 'Notification management not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan to manage notification history',
                'timestamp': datetime.utcnow().isoformat()
            }), 403
        
        # Check bulk operation limit for non-enterprise plans
        if request.effective_plan != 'enterprise':
            max_bulk_operations = request.plan_limits.get('max_bulk_notification_operations', 10)
            today = datetime.utcnow().date()
            bulk_ops_today = NotificationBulkOperation.query.filter(
                NotificationBulkOperation.user_id == user_id,
                db.func.date(NotificationBulkOperation.created_at) == today
            ).count()
            
            if bulk_ops_today >= max_bulk_operations:
                return jsonify({
                    'success': False,
                    'error': f'Daily bulk notification operation limit reached ({max_bulk_operations})',
                    'code': 'BULK_OPERATION_LIMIT_REACHED',
                    'suggestion': 'Upgrade to Enterprise plan for unlimited operations',
                    'current_usage': bulk_ops_today,
                    'reset_time': (datetime.utcnow() + timedelta(days=1)).replace(hour=0, minute=0, second=0).isoformat(),
                    'timestamp': datetime.utcnow().isoformat()
                }), 403
        
        total_notifications = Notification.query.filter_by(user_id=user_id).count()
        
        if total_notifications == 0:
            return jsonify({
                'success': True,
                'message': 'No notifications to clear',
                'timestamp': datetime.utcnow().isoformat()
            }), 200
        
        # Clear all notifications
        Notification.query.filter_by(user_id=user_id).delete()
        
        # Log bulk operation
        bulk_op = NotificationBulkOperation(
            user_id=user_id,
            action='clear_all',
            affected_count=total_notifications,
            plan=request.effective_plan
        )
        db.session.add(bulk_op)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Cleared {total_notifications} notifications',
            'operation_id': bulk_op.id,
            'timestamp': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f'Failed to clear notifications: {str(e)}')
        return jsonify({
            'success': False,
            'error': 'Failed to clear notifications',
            'code': 'CLEAR_NOTIFICATIONS_ERROR',
            'suggestion': 'Try clearing notifications in smaller batches',
            'timestamp': datetime.utcnow().isoformat()
        }), 500

# Helper functions
def get_default_notification_preferences(plan='free'):
    """Get default notification preferences based on plan"""
    base_preferences = {
        'email_enabled': True,
        'push_enabled': False,
        'sms_enabled': False,
        'in_app_enabled': True,
        'incident_alerts': True,
        'status_updates': True,
        'assignment_notifications': True,
        'overdue_alerts': True,
        'daily_digest': False,
        'weekly_report': False
    }
    
    if plan == 'pro':
        base_preferences.update({
            'push_enabled': True,
            'daily_digest': True,
            'weekly_report': True
        })
    
    elif plan in ['business', 'enterprise']:
        base_preferences.update({
            'push_enabled': True,
            'sms_enabled': True,
            'daily_digest': True,
            'weekly_report': True,
            'quiet_hours_start': '22:00',
            'quiet_hours_end': '06:00',
            'high_priority_only': False,
            'urgent_notifications_only': False,
            'mobile_vibration': True,
            'mobile_sound': True
        })
    
    if plan == 'enterprise':
        base_preferences.update({
            'custom_notification_sounds': False,
            'notification_routing_rules': [],
            'escalation_notifications': True,
            'compliance_alerts': True
        })
    
    return base_preferences

def get_available_channels(plan):
    """Get available notification channels based on plan"""
    channels = ['email', 'in_app']
    
    if plan in ['pro', 'business', 'enterprise']:
        channels.append('push')
    
    if plan in ['business', 'enterprise']:
        channels.append('sms')
    
    if plan == 'enterprise':
        channels.extend(['slack', 'teams', 'webhook'])
    
    return channels

def get_incident_timeline(incident_id):
    """Get incident timeline for export"""
    try:
        timeline = IncidentTimeline.query.filter_by(
            incident_id=incident_id
        ).order_by(IncidentTimeline.timestamp).all()
        
        return [{
            'timestamp': event.timestamp.isoformat(),
            'action': event.action,
            'details': event.details,
            'user': User.query.get(event.user_id).email if User.query.get(event.user_id) else None
        } for event in timeline]
    except:
        return []
