# Global storage for video analyses (use database in production)
video_analyses = {}

# Create temp directory for video uploads
if not os.path.exists('temp_videos'):
    os.makedirs('temp_videos')

def extract_frames_from_video(video_path, frame_interval=10):
    """Extract frames from video for analysis"""
    frames = []
    timestamps = []
    
    try:
        cap = cv2.VideoCapture(video_path)
        if not cap.isOpened():
            return frames, timestamps
        
        fps = cap.get(cv2.CAP_PROP_FPS)
        total_frames = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
        duration = total_frames / fps if fps > 0 else 0
        
        frame_count = 0
        while True:
            ret, frame = cap.read()
            if not ret:
                break
                
            # Extract frame at specified interval
            if frame_count % frame_interval == 0:
                frames.append(frame)
                timestamp_seconds = frame_count / fps
                timestamps.append(timestamp_seconds)
                
            frame_count += 1
            
        cap.release()
        
    except Exception as e:
        logger.error(f"Error extracting frames from video: {e}")
    
    return frames, timestamps, duration

def perform_video_analysis(video_path, analysis_config):
    """Perform AI analysis on video using YOLOv5"""
    try:
        analysis_type = analysis_config.get('analysis_type', 'safety_monitoring')
        industry = analysis_config.get('industry', 'construction')
        confidence_threshold = analysis_config.get('confidence_threshold', 0.6)
        custom_prompt = analysis_config.get('custom_prompt', '')
        
        # Extract frames from video
        frames, timestamps, duration = extract_frames_from_video(video_path)
        
        if not frames:
            return {
                'error': 'Could not extract frames from video',
                'risk_level': 'UNKNOWN',
                'risk_score': 0,
                'violations_detected': 0,
                'violations': []
            }
        
        # Analyze each frame using YOLOv5
        all_detections = []
        all_violations = []
        
        for i, frame in enumerate(frames):
            # Save frame temporarily for analysis
            temp_frame_path = f"temp_frame_{i}.jpg"
            cv2.imwrite(temp_frame_path, frame)
            
            try:
                # Use your existing YOLOv5 system for analysis
                analysis_result = cv_system.detect_safety_violations(
                    temp_frame_path, 
                    industry=industry,
                    context={'frame_timestamp': timestamps[i]}
                )
                
                # Process detections
                if 'detections' in analysis_result:
                    for detection in analysis_result['detections']:
                        detection['frame_number'] = i
                        detection['timestamp'] = timestamps[i]
                        all_detections.append(detection)
                
                # Process violations
                if 'violations' in analysis_result:
                    for violation in analysis_result['violations']:
                        violation['frame_number'] = i
                        violation['timestamp'] = timestamps[i]
                        violation['timestamp_formatted'] = format_timestamp(timestamps[i])
                        all_violations.append(violation)
                        
            except Exception as e:
                logger.error(f"Error analyzing frame {i}: {e}")
            finally:
                # Clean up temp frame
                if os.path.exists(temp_frame_path):
                    os.remove(temp_frame_path)
        
        # Calculate overall metrics
        risk_level = calculate_video_risk_level(all_violations, duration)
        risk_score = calculate_risk_score(all_violations, duration)
        compliance_score = calculate_compliance_score(all_violations, len(frames))
        
        # Generate insights based on analysis
        insights = generate_video_insights(all_violations, all_detections, duration, custom_prompt)
        
        return {
            'risk_level': risk_level,
            'risk_score': risk_score,
            'compliance_score': compliance_score,
            'violations_detected': len(all_violations),
            'violations': all_violations,
            'detections': all_detections,
            'frames_analyzed': len(frames),
            'total_frames': len(frames),
            'duration_seconds': duration,
            'analysis_type': analysis_type,
            'industry': industry,
            'insights': insights,
            'processing_time_ms': 0  # You can track actual processing time
        }
        
    except Exception as e:
        logger.error(f"Video analysis error: {e}")
        return {
            'error': str(e),
            'risk_level': 'UNKNOWN',
            'risk_score': 0,
            'violations_detected': 0,
            'violations': []
        }

def format_timestamp(seconds):
    """Convert seconds to HH:MM:SS format"""
    hours = int(seconds // 3600)
    minutes = int((seconds % 3600) // 60)
    seconds = int(seconds % 60)
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}"

def calculate_video_risk_level(violations, duration):
    """Calculate overall risk level for the video"""
    if not violations:
        return "LOW"
    
    # Calculate violations per minute
    violations_per_minute = len(violations) / (duration / 60) if duration > 0 else len(violations)
    
    # Calculate severity score
    severity_weights = {
        'critical': 4,
        'high': 3,
        'medium': 2,
        'low': 1
    }
    
    total_severity = sum(severity_weights.get(violation.get('severity', 'low'), 1) for violation in violations)
    avg_severity = total_severity / len(violations) if violations else 0
    
    # Determine risk level
    if violations_per_minute > 2 and avg_severity >= 3:
        return "CRITICAL"
    elif violations_per_minute > 1 and avg_severity >= 2:
        return "HIGH"
    elif violations_per_minute > 0.5:
        return "MEDIUM"
    else:
        return "LOW"

def calculate_risk_score(violations, duration):
    """Calculate numerical risk score (0-100)"""
    if not violations:
        return 0
    
    base_score = 0
    severity_weights = {
        'critical': 25,
        'high': 15,
        'medium': 10,
        'low': 5
    }
    
    for violation in violations:
        severity = violation.get('severity', 'low')
        confidence = violation.get('confidence', 0.5)
        base_score += severity_weights.get(severity, 5) * confidence
    
    # Normalize by duration (violations per minute)
    if duration > 0:
        violations_per_minute = len(violations) / (duration / 60)
        base_score *= min(2.0, 1 + violations_per_minute / 10)
    
    return min(100, base_score)

def calculate_compliance_score(violations, total_frames):
    """Calculate compliance score (0-100)"""
    if total_frames == 0:
        return 100
    
    # Start with perfect score
    base_score = 100
    
    # Deduct for violations
    violation_penalty = min(50, len(violations) * 5)
    
    # Additional penalty for high severity violations
    high_severity_count = sum(1 for v in violations if v.get('severity') in ['high', 'critical'])
    severity_penalty = high_severity_count * 10
    
    final_score = base_score - violation_penalty - severity_penalty
    return max(0, min(100, final_score))

def generate_video_insights(violations, detections, duration, custom_prompt):
    """Generate insights based on analysis results"""
    insights = []
    
    # Violation insights
    if violations:
        violation_types = {}
        for violation in violations:
            v_type = violation.get('type', 'unknown')
            violation_types[v_type] = violation_types.get(v_type, 0) + 1
        
        most_common_violation = max(violation_types.items(), key=lambda x: x[1]) if violation_types else None
        if most_common_violation:
            insights.append({
                'title': 'Most Common Safety Issue',
                'description': f"'{most_common_violation[0]}' detected {most_common_violation[1]} times",
                'recommendation': f'Focus on addressing {most_common_violation[0]} through training and supervision'
            })
    
    # Detection insights
    if detections:
        person_count = sum(1 for d in detections if d.get('class') == 'person')
        if person_count > 0:
            insights.append({
                'title': 'Workforce Monitoring',
                'description': f'Detected {person_count} person instances across the video',
                'recommendation': 'Ensure all personnel follow safety protocols'
            })
    
    # Custom prompt insights
    if custom_prompt:
        insights.append({
            'title': 'Custom Analysis',
            'description': f'Analysis performed based on your specific requirements',
            'recommendation': 'Review findings in context of your custom instructions'
        })
    
    # Duration-based insights
    if duration > 300:  # More than 5 minutes
        insights.append({
            'title': 'Extended Monitoring',
            'description': f'Video analyzed for {duration:.0f} seconds',
            'recommendation': 'Consider continuous monitoring for long-duration activities'
        })
    
    return insights

def perform_risk_analysis(video_file):
    """Perform quick risk assessment using YOLOv5"""
    try:
        # Save video temporarily
        temp_path = f"temp_risk_{datetime.utcnow().strftime('%Y%m%d_%H%M%S')}.mp4"
        video_file.save(temp_path)
        
        # Analyze using YOLOv5
        analysis_config = {
            'analysis_type': 'risk_assessment',
            'industry': 'construction',
            'confidence_threshold': 0.7
        }
        
        results = perform_video_analysis(temp_path, analysis_config)
        
        # Generate risk-specific recommendations
        recommendations = []
        if results.get('violations_detected', 0) > 0:
            recommendations.append(f"Address {results['violations_detected']} safety violations identified")
            recommendations.append("Review high-risk areas highlighted in detailed analysis")
        
        if results.get('risk_level') in ['HIGH', 'CRITICAL']:
            recommendations.append("Implement immediate corrective actions")
            recommendations.append("Consider temporary work stoppage for critical risks")
        
        # Clean up
        if os.path.exists(temp_path):
            os.remove(temp_path)
        
        return {
            'risk_level': results.get('risk_level', 'UNKNOWN'),
            'risk_score': results.get('risk_score', 0),
            'critical_risks': sum(1 for v in results.get('violations', []) if v.get('severity') == 'critical'),
            'high_risks': sum(1 for v in results.get('violations', []) if v.get('severity') == 'high'),
            'total_hazards': results.get('violations_detected', 0),
            'recommendations': recommendations,
            'analysis_details': {
                'frames_analyzed': results.get('frames_analyzed', 0),
                'duration_seconds': results.get('duration_seconds', 0)
            }
        }
        
    except Exception as e:
        logger.error(f"Risk analysis error: {e}")
        return {
            'risk_level': 'UNKNOWN',
            'risk_score': 0,
            'critical_risks': 0,
            'high_risks': 0,
            'total_hazards': 0,
            'recommendations': ['Analysis failed - please try again'],
            'error': str(e)
        }

def perform_ppe_analysis(video_file):
    """Perform quick PPE compliance check using YOLOv5"""
    try:
        # Save video temporarily
        temp_path = f"temp_ppe_{datetime.utcnow().strftime('%Y%m%d_%H%M%S')}.mp4"
        video_file.save(temp_path)
        
        # Analyze using YOLOv5 with PPE focus
        analysis_config = {
            'analysis_type': 'ppe_compliance',
            'industry': 'construction',
            'confidence_threshold': 0.6
        }
        
        results = perform_video_analysis(temp_path, analysis_config)
        
        # Calculate PPE-specific metrics
        ppe_violations = [v for v in results.get('violations', []) 
                         if any(ppe_item in v.get('type', '').lower() 
                               for ppe_item in ['helmet', 'vest', 'gloves', 'gown', 'mask'])]
        
        person_detections = [d for d in results.get('detections', []) 
                           if d.get('class') == 'person']
        
        compliance_rate = 0
        if person_detections:
            compliance_rate = max(0, 100 - (len(ppe_violations) / len(person_detections)) * 100)
        
        # Generate PPE-specific recommendations
        recommendations = []
        if ppe_violations:
            ppe_types = {}
            for violation in ppe_violations:
                v_type = violation.get('type', 'unknown')
                ppe_types[v_type] = ppe_types.get(v_type, 0) + 1
            
            for ppe_type, count in ppe_types.items():
                recommendations.append(f"Enforce {ppe_type.replace('no_', '').replace('_', ' ')} policy")
        
        if compliance_rate < 80:
            recommendations.append("Implement PPE training and awareness program")
            recommendations.append("Increase supervision in non-compliant areas")
        
        # Clean up
        if os.path.exists(temp_path):
            os.remove(temp_path)
        
        return {
            'compliance_rate': compliance_rate,
            'violations': len(ppe_violations),
            'ppe_items_checked': ['helmet', 'vest', 'gloves', 'boots', 'mask', 'gown'],
            'non_compliant_workers': len(set(v.get('frame_number', 0) for v in ppe_violations)),
            'recommendations': recommendations,
            'detailed_violations': ppe_violations[:5]  # Return first 5 violations
        }
        
    except Exception as e:
        logger.error(f"PPE analysis error: {e}")
        return {
            'compliance_rate': 0,
            'violations': 0,
            'ppe_items_checked': [],
            'non_compliant_workers': 0,
            'recommendations': ['Analysis failed - please try again'],
            'error': str(e)
        }

