@jwt_required
@limiter.limit("5 per minute")
def analyze_video_risks():
    """Quick analysis for risk assessment using YOLOv5"""
    try:
        # 🔥 SUPER ADMIN BYPASS - Add this check first
        if hasattr(request.user, 'role') and request.user.role == 'super_admin':
            # Super admin gets unlimited access - skip plan checks
            pass
        else:
            # Check if video analysis is available for user's plan
            if request.effective_plan == 'free':
                # For free plan, check monthly limits
                if hasattr(request.user, 'monthly_video_minutes_used'):
                    plan_limit = request.plan_limits.get('video_minutes', 0)
                    if request.user.monthly_video_minutes_used >= plan_limit:
                        return jsonify({
                            'success': False,
                            'error': 'Monthly video analysis limit reached',
                            'code': 'VIDEO_LIMIT_EXCEEDED',
                            'suggestion': 'Upgrade to Pro plan for more video analysis minutes',
                            'current_plan': request.effective_plan,
                            'current_usage': request.user.monthly_video_minutes_used,
                            'plan_limit': plan_limit
                        }), 403
        
        if 'video' not in request.files:
            return jsonify({
                'success': False,
                'error': 'No video file provided'
            }), 400
        
        video_file = request.files['video']
        
        # Validate file
        if video_file.filename == '':
            return jsonify({
                'success': False,
                'error': 'No video file selected'
            }), 400
        
        # Validate file type
        allowed_extensions = {'mp4', 'avi', 'mov', 'mkv', 'webm', 'mpeg', 'mpg'}
        if not ('.' in video_file.filename and 
                video_file.filename.rsplit('.', 1)[1].lower() in allowed_extensions):
            return jsonify({
                'success': False,
                'error': 'Invalid file type. Allowed: MP4, AVI, MOV, MKV, WebM, MPEG, MPG'
            }), 400
        
        # Perform risk-focused analysis
        risk_results = perform_risk_analysis(video_file)
        
        analysis_id = f"risk_analysis_{datetime.utcnow().strftime('%Y%m%d_%H%M%S')}_{request.user.id}"
        
        # Track usage for non-super-admins
        if not (hasattr(request.user, 'role') and request.user.role == 'super_admin'):
            if request.effective_plan == 'free':
                try:
                    video_duration = risk_results.get('duration_seconds', 0)
                    if video_duration > 0:
                        minutes_used = video_duration / 60
                        request.user.monthly_video_minutes_used += minutes_used
                        request.user.total_video_minutes_used += minutes_used
                        db.session.commit()
                except Exception as e:
                    logger.warning(f"Failed to track video usage: {str(e)}")
        
        return jsonify({
            'success': True,
            'analysis_id': analysis_id,
            'analysis_type': 'risk_assessment',
            'results': risk_results,
            'plan_info': {
                'current_plan': request.effective_plan,
                'is_trial': request.is_trial_active,
                'remaining_minutes': 'unlimited' if (hasattr(request.user, 'role') and request.user.role == 'super_admin') else (
                    request.plan_limits.get('video_minutes', 0) - request.user.monthly_video_minutes_used if request.effective_plan == 'free' else 'unlimited'
                ),
                'is_super_admin': hasattr(request.user, 'role') and request.user.role == 'super_admin'
            },
            'timestamp': datetime.utcnow().isoformat()
        }), 200
        
    except Exception as e:
        logger.error(f"Risk analysis error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to perform risk analysis'
        }), 500
    
