from sqlalchemy import text

@app.route('/api/hospital/<int:hospital_id>/patients', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_patients(hospital_id):
    """Get all patients - WITH HEALTHCARE HEADERS"""
    try:
        # Get healthcare context
        healthcare_context = get_healthcare_context()
        current_app.logger.info(f"Patients request for hospital {hospital_id} from facility: {healthcare_context['facility']}")
        
        # ✅ Use has_feature_access for plan check
        if not has_feature_access('hospital_patients'):
            return jsonify({
                'success': False,
                'error': 'Patient management not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'current_plan': request.effective_plan,
                'healthcare_context': healthcare_context
            }), 403
        
        is_super_admin = check_super_admin()
        user = request.user
        
        # ✅ Check if user can access this hospital
        # 1. Super admin has access to all
        # 2. System team has access to all
        # 3. User's hospital_id matches the requested hospital
        # 4. User's company owns the hospital (company.hospital_id or hospital.company_id)
        has_access = False
        
        if is_super_admin or request.is_system_team:
            has_access = True
        else:
            # Check if user's hospital_id matches
            if user.hospital_id == hospital_id:
                has_access = True
            else:
                # Check if user's company owns this hospital
                # Get user's company
                company = user.company if hasattr(user, 'company') else None
                if company:
                    # Check if company's primary hospital matches
                    if company.hospital_id == hospital_id:
                        has_access = True
                    else:
                        # Check if hospital belongs to the company
                        hospital = Hospital.query.get(hospital_id)
                        if hospital and hospital.company_id == company.id:
                            has_access = True
        
        if not has_access:
            return jsonify({
                'success': False,
                'error': 'Access denied to this hospital',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        # Build query
        query = Patient.query.filter_by(hospital_id=hospital_id)
        
        # Apply filters
        status_filter = request.args.get('status')
        if status_filter:
            query = query.filter_by(status=status_filter)
        
        department_filter = request.args.get('department')
        if department_filter:
            query = query.filter_by(department=department_filter)
        
        search = request.args.get('search')
        if search:
            query = query.filter(
                db.or_(
                    Patient.first_name.ilike(f'%{search}%'),
                    Patient.last_name.ilike(f'%{search}%'),
                    Patient.mrn.ilike(f'%{search}%')
                )
            )
        
        patients = query.order_by(Patient.created_at.desc()).all()
        
        patient_data = []
        for patient in patients:
            patient_data.append(patient.to_dict())
        
        return jsonify({
            'success': True,
            'data': patient_data,
            'total': len(patient_data),
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching patients: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500

@app.route('/api/companies/<int:company_id>/medical-staff', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_company_medical_staff(company_id):
    """Get all medical staff (doctors and nurses) for a company"""
    try:
        healthcare_context = get_healthcare_context()
        is_super_admin = check_super_admin()
        user = request.user
        
        # Get the company
        company = Company.query.get(company_id)
        if not company:
            return jsonify({
                'success': False,
                'error': 'Company not found',
                'code': 'COMPANY_NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        # Check permissions
        if not (is_super_admin or request.is_system_team or user.company_id == company_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        # Get company's hospital
        hospital_id = company.hospital_id
        if not hospital_id:
            return jsonify({
                'success': True,
                'data': [],
                'total': 0,
                'message': 'Company has no hospital assigned',
                'healthcare_context': healthcare_context
            }), 200
        
        # ✅ Get all medical staff from users table
        # Nurses: user_type == 'nurse'
        # Doctors: user_type == 'doctor' OR from doctors table
        medical_staff = User.query.filter(
            User.hospital_id == hospital_id,
            User.user_type.in_(['doctor', 'nurse', 'medical_staff'])
        ).all()
        
        # ✅ Also get doctors from doctors table
        doctors_from_table = Doctor.query.filter_by(hospital_id=hospital_id).all()
        
        # Combine and deduplicate
        staff_dict = {}
        
        # Add users
        for staff in medical_staff:
            staff_dict[staff.id] = {
                'id': staff.id,
                'name': staff.name,
                'email': staff.email,
                'phone': staff.phone,
                'user_type': staff.user_type,
                'role': staff.role or staff.user_type,
                'department': staff.department,
                'specialty': getattr(staff, 'specialty', None),
                'is_active': staff.is_active,
                'created_at': staff.created_at.isoformat() if staff.created_at else None,
                'source': 'user_table'
            }
        
        # Add doctors from doctors table
        for doctor in doctors_from_table:
            if doctor.id not in staff_dict:
                # Try to find if this doctor is also a user
                user_doctor = User.query.filter_by(email=doctor.email).first()
                if user_doctor and user_doctor.id in staff_dict:
                    # Update the existing user entry with doctor details
                    staff_dict[user_doctor.id]['specialty'] = doctor.specialty
                    staff_dict[user_doctor.id]['doctor_id'] = doctor.id
                else:
                    staff_dict[doctor.id] = {
                        'id': doctor.id,
                        'name': doctor.name,
                        'email': doctor.email,
                        'phone': doctor.phone,
                        'user_type': 'doctor',
                        'role': 'Doctor',
                        'department': doctor.department,
                        'specialty': doctor.specialty,
                        'is_active': doctor.is_active,
                        'created_at': doctor.created_at.isoformat() if doctor.created_at else None,
                        'source': 'doctor_table',
                        'doctor_id': doctor.id
                    }
        
        # Convert to list
        staff_list = list(staff_dict.values())
        
        # Separate doctors and nurses
        doctors_list = [s for s in staff_list if s['user_type'] in ['doctor', 'medical_staff'] or s['role'] == 'Doctor']
        nurses_list = [s for s in staff_list if s['user_type'] == 'nurse']
        
        current_app.logger.info(f"Medical staff fetched for company {company_id}: {len(staff_list)} staff (Doctors: {len(doctors_list)}, Nurses: {len(nurses_list)})")
        
        return jsonify({
            'success': True,
            'data': staff_list,
            'total': len(staff_list),
            'doctors': doctors_list,
            'nurses': nurses_list,
            'company': {
                'id': company.id,
                'name': company.name,
                'hospital_id': hospital_id
            },
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching company medical staff: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


