@app.route('/api/doctors', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_all_doctors():
    """Get all doctors (from users table and doctors table)"""
    try:
        healthcare_context = get_healthcare_context()
        is_super_admin = check_super_admin()
        user = request.user
        
        # ✅ Build query from users table
        query = User.query.filter(User.user_type == 'doctor')
        
        # Filter by hospital
        hospital_id = request.args.get('hospital_id')
        if hospital_id:
            query = query.filter_by(hospital_id=hospital_id)
        elif not is_super_admin and user.hospital_id:
            query = query.filter_by(hospital_id=user.hospital_id)
        
        # Filter by company
        company_id = request.args.get('company_id')
        if company_id:
            company = Company.query.get(company_id)
            if company and company.hospital_id:
                query = query.filter_by(hospital_id=company.hospital_id)
        
        # Filter by department
        department = request.args.get('department')
        if department:
            query = query.filter_by(department=department)
        
        # Search
        search = request.args.get('search')
        if search:
            query = query.filter(
                db.or_(
                    User.name.ilike(f'%{search}%'),
                    User.email.ilike(f'%{search}%')
                )
            )
        
        users = query.order_by(User.name).all()
        
        # ✅ Also get doctors from doctors table
        doctor_records = Doctor.query
        if hospital_id:
            doctor_records = doctor_records.filter_by(hospital_id=hospital_id)
        elif not is_super_admin and user.hospital_id:
            doctor_records = doctor_records.filter_by(hospital_id=user.hospital_id)
        
        doctor_records = doctor_records.all()
        
        # Combine and deduplicate
        doctor_dict = {}
        
        # Add users
        for doc in users:
            doctor_dict[doc.id] = {
                'id': doc.id,
                'name': doc.name,
                'email': doc.email,
                'phone': doc.phone,
                'user_type': doc.user_type,
                'role': doc.role or 'Doctor',
                'department': doc.department,
                'specialty': getattr(doc, 'specialty', None),
                'is_active': doc.is_active,
                'created_at': doc.created_at.isoformat() if doc.created_at else None,
                'source': 'user_table'
            }
        
        # Add doctor records
        for doc in doctor_records:
            if doc.id not in doctor_dict:
                doctor_dict[doc.id] = {
                    'id': doc.id,
                    'name': doc.name,
                    'email': doc.email,
                    'phone': doc.phone,
                    'user_type': 'doctor',
                    'role': 'Doctor',
                    'department': doc.department,
                    'specialty': doc.specialty,
                    'is_active': doc.is_active,
                    'created_at': doc.created_at.isoformat() if doc.created_at else None,
                    'source': 'doctor_table',
                    'doctor_id': doc.id
                }
        
        doctors_list = list(doctor_dict.values())
        
        return jsonify({
            'success': True,
            'data': doctors_list,
            'total': len(doctors_list),
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching doctors: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


