@app.route('/api/patients/<int:patient_id>/assign-doctor', methods=['PUT'])
@jwt_required
@validate_healthcare_headers
def assign_doctor_to_patient(patient_id):
    """Assign a doctor to a patient"""
    try:
        healthcare_context = get_healthcare_context()
        is_super_admin = check_super_admin()
        user = request.user
        
        patient = Patient.query.get(patient_id)
        if not patient:
            return jsonify({
                'success': False,
                'error': 'Patient not found',
                'code': 'PATIENT_NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        # Check access
        if not (is_super_admin or request.is_system_team or user.hospital_id == patient.hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        data = request.get_json()
        doctor_id = data.get('doctor_id')
        
        if not doctor_id:
            return jsonify({
                'success': False,
                'error': 'Doctor ID is required',
                'code': 'MISSING_DOCTOR_ID',
                'healthcare_context': healthcare_context
            }), 400
        
        # Verify doctor exists
        doctor = Doctor.query.get(doctor_id)
        if not doctor:
            return jsonify({
                'success': False,
                'error': 'Doctor not found',
                'code': 'DOCTOR_NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        # Verify doctor works in same hospital
        if doctor.hospital_id != patient.hospital_id:
            return jsonify({
                'success': False,
                'error': 'Doctor does not work in this hospital',
                'code': 'INVALID_DOCTOR',
                'healthcare_context': healthcare_context
            }), 400
        
        # Assign doctor
        patient.doctor_id = doctor_id
        patient.doctor = doctor.name
        patient.updated_at = datetime.utcnow()
        
        # Add to timeline
        timeline = PatientTimeline(
            patient_id=patient.id,
            event_type='Doctor Assigned',
            description=f"Doctor {doctor.name} assigned to patient",
            created_by=user.id
        )
        db.session.add(timeline)
        
        db.session.commit()
        
        current_app.logger.info(f"Doctor {doctor.name} assigned to patient {patient.id}")
        
        return jsonify({
            'success': True,
            'message': f'Doctor {doctor.name} assigned successfully',
            'data': {
                'patient_id': patient.id,
                'doctor_id': doctor.id,
                'doctor_name': doctor.name,
                'assigned_at': datetime.utcnow().isoformat()
            },
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error assigning doctor: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


