        if not has_feature_access('hospital_patients'):
            return jsonify({
                'success': False,
                'error': 'Patient management not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'current_plan': request.effective_plan,
                'healthcare_context': healthcare_context
            }), 403
        
        # Check permissions
