@app.route('/api/company/overview', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_company_overview():
    """Get company overview using real data"""
    try:
        healthcare_context = get_healthcare_context()
        user = request.user
        
        # Get user's company
        company = user.company if hasattr(user, 'company') else None
        
        if not company:
            return jsonify({
                'success': False,
                'error': 'No company associated with your account',
                'code': 'NO_COMPANY_ASSOCIATED',
                'healthcare_context': healthcare_context
            }), 404
        
        # Get company users
        company_users = User.query.filter_by(company_id=company.id).all()
        user_ids = [u.id for u in company_users]
        
        # Get safety incidents from AI requests or safety incidents
        safety_incidents = SafetyIncident.query.filter_by(company_id=company.id).all() if hasattr(SafetyIncident, 'company_id') else []
        
        # Get AI usage analytics for the company
        ai_usage = AIUsageAnalytics.query.filter(AIUsageAnalytics.user_id.in_(user_ids)).all() if user_ids else []
        
        # Get activity logs for the company
        activity_logs = ActivityLog.query.filter(ActivityLog.user_id.in_(user_ids)).order_by(ActivityLog.timestamp.desc()).limit(20).all() if user_ids else []
        
        # Calculate metrics
        active_incidents = len([i for i in safety_incidents if i.status == 'Active']) if safety_incidents else 0
        
        # Days since last incident
        last_incident = safety_incidents[0] if safety_incidents else None
        days_since_last_incident = 0
        if last_incident and hasattr(last_incident, 'created_at'):
            days_since_last_incident = (datetime.utcnow() - last_incident.created_at).days
        
        # Get safety protocols from AI requests or documents
        safety_protocols = []
        if user_ids:
            ai_docs = AIRequest.query.filter(AIRequest.user_id.in_(user_ids), AIRequest.request_type == 'safety_analysis').limit(5).all()
            for doc in ai_docs:
                safety_protocols.append({
                    'id': doc.id,
                    'title': doc.user_input[:50] if doc.user_input else 'Safety Protocol',
                    'status': doc.status,
                    'created_at': doc.created_at.isoformat() if doc.created_at else None
                })
        
        # Get environmental metrics from documents and AI usage
        environmental_metrics = []
        
        # Calculate document metrics
        documents = Document.query.filter(Document.user_id.in_(user_ids)).all() if user_ids else []
        total_docs = len(documents)
        
        # Calculate AI usage metrics
        ai_requests = AIRequest.query.filter(AIRequest.user_id.in_(user_ids)).all() if user_ids else []
        total_ai_requests = len(ai_requests)
        
        # Calculate upload metrics
        uploads = UploadFile.query.filter(UploadFile.user_id.in_(user_ids)).all() if user_ids else []
        total_uploads = len(uploads)
        
        # Calculate video analysis metrics
        videos = VideoAnalysis.query.filter(VideoAnalysis.user_id.in_(user_ids)).all() if user_ids else []
        total_videos = len(videos)
        
        environmental_metrics = [
            {
                'parameter': 'Documents Processed',
                'current': total_docs,
                'target': 100,
                'unit': 'documents',
                'status': 'success' if total_docs > 50 else 'warning'
            },
            {
                'parameter': 'AI Requests',
                'current': total_ai_requests,
                'target': 50,
                'unit': 'requests',
                'status': 'success' if total_ai_requests > 25 else 'warning'
            },
            {
                'parameter': 'Uploads',
                'current': total_uploads,
                'target': 50,
                'unit': 'files',
                'status': 'success' if total_uploads > 25 else 'warning'
            },
            {
                'parameter': 'Video Analyses',
                'current': total_videos,
                'target': 30,
                'unit': 'videos',
                'status': 'success' if total_videos > 15 else 'warning'
            }
        ]
        
        # Get departments count
        departments_count = Department.query.filter_by(company_id=company.id).count()
        
        return jsonify({
            'success': True,
            'data': {
                'environmentalMetrics': environmental_metrics,
                'safetyProtocols': safety_protocols,
                'activeIncidents': active_incidents,
                'daysSinceLastIncident': days_since_last_incident,
                'departments': departments_count
            },
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching company overview: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


