@app.route('/api/hospital/<int:hospital_id>/ai-services/enable', methods=['POST'])
@jwt_required
@validate_healthcare_headers
def enable_hospital_ai_service(hospital_id):
    """Enable AI service for a hospital - WITH HEALTHCARE HEADERS"""
    try:
        # Get healthcare context
        healthcare_context = get_healthcare_context()
        
        hospital = Hospital.query.get_or_404(hospital_id)
        
        # 🔥 SUPER ADMIN BYPASS - Check super admin role first
        is_super_admin = hasattr(request.user, 'role') and request.user.role == 'super_admin'
        
        # ✅ Use has_feature_access for plan check
        if not is_super_admin and not has_feature_access('hospital_ai_services'):
            return jsonify({
                'success': False,
                'error': 'AI services not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'current_plan': request.effective_plan,
                'healthcare_context': healthcare_context
            }), 403
        
        # Check if user can manage hospital AI services
        if not (is_super_admin or request.is_system_team or 
                request.user.user_type in ['admin', 'safety_manager'] or
                (request.user.hospital_id == hospital_id and request.user.user_type == 'doctor')):
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions to enable AI services',
                'code': 'PERMISSION_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        data = request.get_json()
        service_name = data.get('serviceName')
        
        if not service_name:
            return jsonify({
                'success': False,
                'error': 'Service name is required',
                'code': 'VALIDATION_ERROR',
                'healthcare_context': healthcare_context
            }), 400
        
        current_app.logger.info(f"Enabling AI service '{service_name}' for hospital '{hospital.name}' - Facility: {healthcare_context['facility']}")
        
        # Get available services
        ai_services_response = hospital_ai_services()
        if ai_services_response.status_code != 200:
            return ai_services_response
        
        services_data = ai_services_response.get_json()
        service_info = next((s for s in services_data['services'] if s['name'] == service_name), None)
        
        if not service_info:
            return jsonify({
                'success': False,
                'error': f'Service {service_name} not found',
                'code': 'SERVICE_NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        # Super admin can enable any service regardless of plan
        if not is_super_admin and not service_info['enabled']:
            return jsonify({
                'success': False,
                'error': f'Service {service_name} is not available in your plan',
                'code': 'SERVICE_NOT_AVAILABLE',
                'requiredPlan': service_info['planRequired'],
                'healthcare_context': healthcare_context
            }), 403
        
        current_app.logger.info(f"Enabled AI service '{service_name}' for hospital '{hospital.name}' by {request.user.email} - Facility: {healthcare_context['facility']}")
        
        return jsonify({
            'success': True,
            'message': f'AI service {service_name} enabled successfully',
            'hospitalId': hospital.id,
            'hospitalName': hospital.name,
            'serviceEnabled': service_name,
            'planInfo': {
                'currentPlan': 'super_admin' if is_super_admin else request.effective_plan,
                'is_super_admin': is_super_admin,
                'serviceAccuracy': service_info['accuracy']
            },
            'enabled_by': {
                'user_id': request.user.id,
                'user_email': request.user.email,
                'user_role': 'super_admin' if is_super_admin else request.user.user_type,
                'super_admin_override': is_super_admin and not service_info['enabled']
            },
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Enable AI service error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500




@app.route('/api/hospital/<int:hospital_id>/ai-services', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_hospital_ai_services(hospital_id):
    """Get AI services for a specific hospital"""
    try:
        healthcare_context = get_healthcare_context()
        current_app.logger.info(f"AI services request for hospital {hospital_id} from facility: {healthcare_context['facility']}")
        
        # ✅ Use has_feature_access for plan check
        if not has_feature_access('hospital_ai_services'):
            return jsonify({
                'success': False,
                'error': 'AI services not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'suggestion': f'Upgrade to {get_next_plan(request.effective_plan)} plan for AI services',
                'current_plan': request.effective_plan,
                'healthcare_context': healthcare_context
            }), 403
        
        # ✅ Check permissions - handle users without hospital_id
        is_super_admin = check_super_admin()
        user = request.user
        
        # ✅ If user has no hospital_id, they might be a global admin or need assignment
        if user.hospital_id is None:
            if is_super_admin or request.is_system_team or user.user_type in ['admin', 'employee', 'doctor', 'nurse' 'safety_manager']:
                # Allow access for admins/super admins even without hospital_id
                current_app.logger.info(f"Admin user {user.email} with no hospital_id accessing AI services for hospital {hospital_id}")
                # Check if the hospital exists
                hospital = Hospital.query.get(hospital_id)
                if not hospital:
                    return jsonify({
                        'success': False,
                        'error': f'Hospital {hospital_id} not found',
                        'code': 'HOSPITAL_NOT_FOUND',
                        'healthcare_context': healthcare_context
                    }), 404
            else:
                return jsonify({
                    'success': False,
                    'error': 'No hospital assigned. Please contact your administrator.',
                    'code': 'NO_HOSPITAL_ASSIGNED',
                    'suggestion': 'Contact your administrator to be assigned to a hospital',
                    'healthcare_context': healthcare_context
                }), 403
        elif user.hospital_id != hospital_id and not (is_super_admin or request.is_system_team):
            return jsonify({
                'success': False,
                'error': f'Access denied to hospital {hospital_id}. You are assigned to hospital {user.hospital_id}',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        # ✅ Get ALL 7 AI services based on loaded models
        all_ai_services = [
            {'name': 'AI Chat Assistant', 'status': 'active', 'description': 'Real-time medical Q&A', 'enabled': True},
            {'name': 'Symptom Analysis', 'status': 'active', 'description': 'Symptom assessment and triage', 'enabled': True},
            {'name': 'Medical Text Analysis', 'status': 'active', 'description': 'Medical document analysis', 'enabled': True},
            {'name': 'Disease Prediction', 'status': 'active', 'description': 'Risk assessment and prediction', 'enabled': True},
            {'name': 'Lab Analysis', 'status': 'active', 'description': 'Laboratory result interpretation', 'enabled': True},
            {'name': 'Safety Analysis', 'status': 'active', 'description': 'Safety protocol compliance analysis', 'enabled': True},
            {'name': 'Comprehensive AI', 'status': 'active', 'description': 'Full comprehensive medical analysis', 'enabled': True}
        ]
        
        # ✅ Plan-based availability
        user_plan = 'super_admin' if is_super_admin else request.effective_plan
        
        if user_plan == 'free':
            ai_services = all_ai_services[:1]  # Only chat for free
        elif user_plan == 'pro':
            ai_services = all_ai_services[:3]  # Chat, Symptoms, Text
        elif user_plan == 'business':
            ai_services = all_ai_services[:6]  # All except Comprehensive AI
        elif user_plan in ['enterprise', 'custom']:
            ai_services = all_ai_services  # All 7 services
        else:
            ai_services = all_ai_services  # Default to all for super_admin
        
        return jsonify({
            'success': True,
            'services': ai_services,
            'total': len(ai_services),
            'plan': user_plan,
            'healthcare_context': healthcare_context,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'is_super_admin': is_super_admin,
                'user_hospital_id': user.hospital_id,
                'requested_hospital_id': hospital_id,
                'hasHospitalAssignment': user.hospital_id is not None,
                'allServicesAvailable': len(all_ai_services),
                'servicesProvided': len(ai_services)
            }
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching AI services: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': healthcare_context if 'healthcare_context' in locals() else {}
        }), 500


@app.route('/api/hospital/<int:hospital_id>/safety-incidents', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_safety_incidents(hospital_id):
    """Get all safety incidents for a hospital"""
    try:
        healthcare_context = get_healthcare_context()
        is_super_admin = check_super_admin()
        user = request.user
        
        if not (is_super_admin or request.is_system_team or user.hospital_id == hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        query = SafetyIncident.query.filter_by(hospital_id=hospital_id)
        
        # Apply filters
        status = request.args.get('status')
        if status:
            query = query.filter_by(status=status)
        
        type_filter = request.args.get('type')
        if type_filter:
            query = query.filter_by(type=type_filter)
        
        severity = request.args.get('severity')
        if severity:
            query = query.filter_by(severity=severity)
        
        incidents = query.order_by(SafetyIncident.created_at.desc()).all()
        
        return jsonify({
            'success': True,
            'data': [incident.to_dict() for incident in incidents],
            'total': len(incidents),
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching safety incidents: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


@app.route('/api/hospital/<int:hospital_id>/safety-incidents', methods=['POST'])
@jwt_required
@validate_healthcare_headers
def create_safety_incident(hospital_id):
    """Create a new safety incident"""
    try:
        healthcare_context = get_healthcare_context()
        is_super_admin = check_super_admin()
        user = request.user
        
        if not (is_super_admin or request.is_system_team or user.hospital_id == hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        data = request.get_json()
        
        required = ['title', 'type', 'severity', 'department', 'location']
        for field in required:
            if not data.get(field):
                return jsonify({
                    'success': False,
                    'error': f'Missing required field: {field}',
                    'code': 'MISSING_FIELD',
                    'healthcare_context': healthcare_context
                }), 400
        
        # Generate incident number
        incident_number = f"INC-{datetime.utcnow().strftime('%Y%m%d')}-{random.randint(1000, 9999)}"
        
        # Parse date
        incident_date = datetime.utcnow()
        if data.get('date'):
            try:
                incident_date = datetime.fromisoformat(data['date'].replace('Z', '+00:00'))
            except:
                incident_date = datetime.utcnow()
        
        incident = SafetyIncident(
            incident_number=incident_number,
            hospital_id=hospital_id,
            title=data['title'],
            type=data['type'],
            severity=data.get('severity', 'Medium'),
            department=data['department'],
            location=data['location'],
            status=data.get('status', 'Reported'),
            date=incident_date,
            investigator=data.get('investigator'),
            description=data.get('description', ''),
            root_cause=data.get('rootCause', ''),
            corrective_actions=data.get('correctiveActions', ''),
            preventive_measures=data.get('preventiveMeasures', ''),
            created_by=user.id,
            updated_by=user.id
        )
        
        db.session.add(incident)
        db.session.commit()
        
        current_app.logger.info(f"Safety incident created: {incident.title} by {user.email}")
        
        return jsonify({
            'success': True,
            'message': 'Safety incident reported successfully',
            'data': incident.to_dict(),
            'healthcare_context': healthcare_context
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error creating safety incident: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


@app.route('/api/hospital/<int:hospital_id>/safety-incidents/<int:incident_id>', methods=['PUT'])
@jwt_required
@validate_healthcare_headers
def update_safety_incident(hospital_id, incident_id):
    """Update a safety incident"""
    try:
        healthcare_context = get_healthcare_context()
        is_super_admin = check_super_admin()
        user = request.user
        
        incident = SafetyIncident.query.get_or_404(incident_id)
        
        if incident.hospital_id != hospital_id:
            return jsonify({
                'success': False,
                'error': 'Incident not found in this hospital',
                'code': 'NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        if not (is_super_admin or request.is_system_team or user.hospital_id == hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        data = request.get_json()
        
        # Update fields
        updateable_fields = ['title', 'type', 'severity', 'department', 'location', 'status', 
                           'investigator', 'description', 'root_cause', 'corrective_actions', 
                           'preventive_measures']
        for field in updateable_fields:
            if field in data:
                setattr(incident, field, data[field])
        
        incident.updated_at = datetime.utcnow()
        incident.updated_by = user.id
        
        db.session.commit()
        
        current_app.logger.info(f"Safety incident updated: {incident.title} by {user.email}")
        
        return jsonify({
            'success': True,
            'message': 'Incident updated successfully',
            'data': incident.to_dict(),
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error updating safety incident: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


