@app.route('/api/hospital/<int:hospital_id>/safety-inspections', methods=['POST'])
@jwt_required
@validate_healthcare_headers
def create_safety_inspection(hospital_id):
    """Create a new safety inspection"""
    try:
        healthcare_context = get_healthcare_context()
        is_super_admin = check_super_admin()
        user = request.user
        
        if not (is_super_admin or request.is_system_team or user.hospital_id == hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        data = request.get_json()
        
        required = ['title', 'type', 'inspector', 'date']
        for field in required:
            if not data.get(field):
                return jsonify({
                    'success': False,
                    'error': f'Missing required field: {field}',
                    'code': 'MISSING_FIELD',
                    'healthcare_context': healthcare_context
                }), 400
        
        # Generate inspection number
        inspection_number = f"INS-{datetime.utcnow().strftime('%Y%m%d')}-{random.randint(1000, 9999)}"
        
        # Parse date
        inspection_date = datetime.utcnow()
        if data.get('date'):
            try:
                inspection_date = datetime.fromisoformat(data['date'].replace('Z', '+00:00'))
            except:
                inspection_date = datetime.utcnow()
        
        inspection = SafetyInspection(
            inspection_number=inspection_number,
            hospital_id=hospital_id,
            title=data['title'],
            type=data['type'],
            department=data.get('department'),
            conducted_by=user.id,  # Using conducted_by field
            inspector=data.get('inspector'),
            inspection_date=inspection_date,
            status=data.get('status', 'draft'),  # Your model uses draft/in_progress/completed/approved
            findings_summary=data.get('findings', ''),  # Your model uses findings_summary
            recommendations=data.get('recommendations', ''),
            created_by=user.id,
            updated_by=user.id
        )
        
        db.session.add(inspection)
        db.session.commit()
        
        current_app.logger.info(f"Safety inspection created: {inspection.title} by {user.email}")
        
        return jsonify({
            'success': True,
            'message': 'Inspection scheduled successfully',
            'data': inspection.to_dict(),
            'healthcare_context': healthcare_context
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error creating safety inspection: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


