def get_user_engagement(hospital_id: int, days: int = 30) -> Dict[str, Any]:
    """
    Calculate user engagement metrics for a hospital using new models
    
    Args:
        hospital_id: Hospital ID
        days: Number of days to analyze (default: 30)
    
    Returns:
        dict: User engagement metrics
    """
    try:
        end_date = datetime.utcnow()
        start_date = end_date - timedelta(days=days)
        
        # Get hospital users
        hospital_users = User.query.filter_by(hospital_id=hospital_id).all()
        total_users = len(hospital_users)
        
        if total_users == 0:
            return {
                'engagement_rate': 0,
                'active_users': 0,
                'total_users': 0,
                'avg_sessions': 0,
                'avg_duration': 0,
                'engagement_score': 0,
                'trend': 'stable',
                'period_days': days,
                'start_date': start_date.isoformat(),
                'end_date': end_date.isoformat()
            }
        
        # Count active users (users with activity in date range)
        active_users = 0
        total_sessions = 0
        total_duration = 0
        
        # Get engagement events in date range
        events = UserEngagementEvent.query.filter(
            UserEngagementEvent.hospital_id == hospital_id,
            UserEngagementEvent.created_at >= start_date,
            UserEngagementEvent.created_at <= end_date
        ).all()
        
        # Get unique active users from events
        active_user_ids = set([e.user_id for e in events])
        active_users = len(active_user_ids)
        
        # Get sessions count from UserSession
        sessions = UserSession.query.filter(
            UserSession.user_id.in_([u.id for u in hospital_users]),
            UserSession.login_time >= start_date,
            UserSession.login_time <= end_date,
            UserSession.is_active == True
        ).all()
        
        total_sessions = len(sessions)
        
        # Calculate total duration from engagement events
        total_duration = sum([e.duration_seconds for e in events if e.duration_seconds])
        
        # Calculate engagement metrics
        engagement_rate = round((active_users / total_users) * 100, 1) if total_users > 0 else 0
        avg_sessions = round(total_sessions / total_users, 1) if total_users > 0 else 0
        avg_duration = round(total_duration / total_users / 60, 1) if total_users > 0 else 0  # Convert to minutes
        
        # Get engagement scores from UserEngagementScore
        scores = UserEngagementScore.query.filter_by(hospital_id=hospital_id).all()
        avg_score = round(sum([s.engagement_score for s in scores]) / len(scores), 1) if scores else 0
        
        # Calculate engagement score (0-100) using weighted factors
        engagement_score = min(100, int(
            (engagement_rate * 0.4) +  # 40% weight
            (avg_sessions * 5) +        # 30% weight (max 10 sessions = 50 points)
            (avg_duration * 2)          # 30% weight (max 10 minutes = 20 points)
        ))
        
        # Determine trend using engagement events by day
        trend = 'stable'
        if len(events) > 0:
            # Get daily event counts
            daily_counts = {}
            for event in events:
                date_key = event.created_at.date().isoformat()
                daily_counts[date_key] = daily_counts.get(date_key, 0) + 1
            
            if len(daily_counts) >= 2:
                dates = sorted(daily_counts.keys())
                first_half = [daily_counts[d] for d in dates[:len(dates)//2]]
                second_half = [daily_counts[d] for d in dates[len(dates)//2:]]
                
                first_avg = sum(first_half) / len(first_half) if first_half else 0
                second_avg = sum(second_half) / len(second_half) if second_half else 0
                
                if second_avg > first_avg * 1.1:
                    trend = 'improving'
                elif second_avg < first_avg * 0.9:
                    trend = 'declining'
                else:
                    trend = 'stable'
        
        return {
            'engagement_rate': engagement_rate,
            'active_users': active_users,
            'total_users': total_users,
            'avg_sessions': avg_sessions,
            'avg_duration': avg_duration,
            'engagement_score': engagement_score,
            'avg_score': avg_score,
            'trend': trend,
            'period_days': days,
            'start_date': start_date.isoformat(),
            'end_date': end_date.isoformat(),
            'events_count': len(events)
        }
        
    except Exception as e:
        logger.error(f"Error calculating user engagement: {str(e)}")
        return {
            'engagement_rate': 0,
            'active_users': 0,
            'total_users': 0,
            'avg_sessions': 0,
            'avg_duration': 0,
            'engagement_score': 0,
            'trend': 'unknown',
            'error': str(e)
        }


def track_engagement_event(hospital_id: int, user_id: int, event_type: str, 
                          event_data: Optional[Dict] = None, duration_seconds: int = 0,
                          session_id: Optional[str] = None) -> Optional[UserEngagementEvent]:
    """
    Track a user engagement event in real-time using new models
    """
    try:
        # Get request context if available
        ip_address = request.remote_addr if hasattr(request, 'remote_addr') else None
        user_agent = request.headers.get('User-Agent') if hasattr(request, 'headers') else None
        
        event = UserEngagementEvent.track_event(
            hospital_id=hospital_id,
            user_id=user_id,
            event_type=event_type,
            event_data=event_data,  # Changed from 'metadata' to 'event_data'
            duration_seconds=duration_seconds,
            session_id=session_id or str(random.randint(100000, 999999)),
            ip_address=ip_address,
            user_agent=user_agent
        )
        
        # Update user engagement score
        UserEngagementScore.update_score(user_id, hospital_id)
        
        return event
        
    except Exception as e:
        logger.error(f"Error tracking engagement event: {e}")
        return None


def get_engagement_benchmarks(hospital_id: int) -> Dict[str, Any]:
    """
    Compare hospital engagement against industry benchmarks using new models
    
    Args:
        hospital_id: Hospital ID
    
    Returns:
        dict: Engagement benchmarks comparison
    """
    try:
        engagement = get_user_engagement(hospital_id)
        
        # Industry benchmarks (can be pulled from a config/database)
        benchmarks = {
            'good': {'engagement_rate': 70, 'avg_sessions': 5, 'avg_duration': 10, 'engagement_score': 75},
            'average': {'engagement_rate': 50, 'avg_sessions': 3, 'avg_duration': 6, 'engagement_score': 50},
            'poor': {'engagement_rate': 30, 'avg_sessions': 1, 'avg_duration': 2, 'engagement_score': 25}
        }
        
        # Determine benchmark category
        rate = engagement.get('engagement_rate', 0)
        if rate >= benchmarks['good']['engagement_rate']:
            category = 'good'
        elif rate >= benchmarks['average']['engagement_rate']:
            category = 'average'
        else:
            category = 'poor'
        
        # Get top users from engagement scores
        top_users = UserEngagementScore.query.filter_by(
            hospital_id=hospital_id
        ).order_by(UserEngagementScore.engagement_score.desc()).limit(5).all()
        
        return {
            'current': engagement,
            'benchmark_category': category,
            'benchmarks': benchmarks,
            'improvement_needed': {
                'engagement_rate': max(0, benchmarks['good']['engagement_rate'] - rate),
                'avg_sessions': max(0, benchmarks['good']['avg_sessions'] - engagement.get('avg_sessions', 0)),
                'avg_duration': max(0, benchmarks['good']['avg_duration'] - engagement.get('avg_duration', 0))
            },
            'top_users': [u.to_dict() for u in top_users],
            'total_users_with_scores': UserEngagementScore.query.filter_by(hospital_id=hospital_id).count()
        }
        
    except Exception as e:
        logger.error(f"Error getting engagement benchmarks: {e}")
        return {
            'current': get_user_engagement(hospital_id),
            'benchmark_category': 'unknown',
            'benchmarks': {}
        }


def get_user_engagement_score(user_id: int, hospital_id: int) -> Optional[Dict]:
    """
    Get individual user engagement score using new models
    
    Args:
        user_id: User ID
        hospital_id: Hospital ID
    
    Returns:
        dict: User engagement score details
    """
    try:
        user = User.query.get(user_id)
        if not user:
            return None
        
        # Get or create engagement score
        score_record = UserEngagementScore.query.filter_by(user_id=user_id).first()
        
        if not score_record:
            score_record = UserEngagementScore.update_score(user_id, hospital_id)
        
        if not score_record:
            return None
        
        # Get recent events
        recent_events = UserEngagementEvent.query.filter_by(
            user_id=user_id,
            hospital_id=hospital_id
        ).order_by(UserEngagementEvent.created_at.desc()).limit(10).all()
        
        return {
            'user_id': user_id,
            'name': user.name,
            'email': user.email,
            'engagement_score': score_record.engagement_score,
            'level': score_record.level,
            'sessions_count': score_record.sessions_count,
            'analyses_count': score_record.analyses_count,
            'chats_count': score_record.chats_count,
            'last_active_days': score_record.last_active_days,
            'updated_at': score_record.updated_at.isoformat() if score_record.updated_at else None,
            'recent_events': [e.to_dict() for e in recent_events]
        }
        
    except Exception as e:
        logger.error(f"Error getting user engagement score: {e}")
        return None


def get_engagement_trend(hospital_id: int, days: int = 30) -> List[Dict]:
    """
    Get engagement trend over time using new models
    
    Args:
        hospital_id: Hospital ID
        days: Number of days to analyze
    
    Returns:
        list: Daily engagement data
    """
    try:
        end_date = datetime.utcnow()
        start_date = end_date - timedelta(days=days)
        
        # Get daily engagement events
        daily_events = db.session.query(
            func.date(UserEngagementEvent.created_at).label('date'),
            func.count(UserEngagementEvent.id).label('event_count'),
            func.count(func.distinct(UserEngagementEvent.user_id)).label('unique_users')
        ).filter(
            UserEngagementEvent.hospital_id == hospital_id,
            UserEngagementEvent.created_at >= start_date,
            UserEngagementEvent.created_at <= end_date
        ).group_by('date').order_by('date').all()
        
        # Get daily user sessions
        daily_sessions = db.session.query(
            func.date(UserSession.login_time).label('date'),
            func.count(UserSession.id).label('session_count')
        ).join(User, UserSession.user_id == User.id).filter(
            User.hospital_id == hospital_id,
            UserSession.login_time >= start_date,
            UserSession.login_time <= end_date
        ).group_by('date').order_by('date').all()
        
        # Combine data
        result = []
        date_dict = {}
        
        for event in daily_events:
            date_key = str(event[0])
            date_dict[date_key] = {
                'date': date_key,
                'event_count': event[1] or 0,
                'unique_users': event[2] or 0,
                'session_count': 0
            }
        
        for session in daily_sessions:
            date_key = str(session[0])
            if date_key in date_dict:
                date_dict[date_key]['session_count'] = session[1] or 0
            else:
                date_dict[date_key] = {
                    'date': date_key,
                    'event_count': 0,
                    'unique_users': 0,
                    'session_count': session[1] or 0
                }
        
        # Sort by date
        result = [date_dict[d] for d in sorted(date_dict.keys())]
        
        return result
        
    except Exception as e:
        logger.error(f"Error getting engagement trend: {e}")
        return []


# ============================================
# COST SAVINGS CALCULATION
# ============================================

def calculate_cost_savings(analyses_count: int, avg_cost_per_analysis: int = 50) -> Dict[str, Any]:
    """
    Calculate estimated cost savings from AI analyses
    
    Args:
        analyses_count: Number of AI analyses performed
        avg_cost_per_analysis: Average cost saved per analysis (default: $50)
    
    Returns:
        dict: Cost savings breakdown
    """
    try:
        # Base savings
        total_savings = analyses_count * avg_cost_per_analysis
        
        # Additional savings factors
        labor_savings = analyses_count * 15  # 15 minutes saved per analysis
        error_reduction = analyses_count * 5  # 5% error reduction
        efficiency_gain = analyses_count * 3  # 3% efficiency gain
        
        # Calculate total savings with multipliers
        total_savings = (
            total_savings * 1.0 +           # Base
            labor_savings * 0.5 +           # Labor efficiency
            error_reduction * 2.0 +         # Error reduction
            efficiency_gain * 1.5           # Efficiency gain
        )
        
        # Calculate monthly and yearly projections
        monthly_savings = total_savings / 12 if analyses_count > 0 else 0
        yearly_savings = total_savings
        
        return {
            'total_savings': round(total_savings, 2),
            'monthly_savings': round(monthly_savings, 2),
            'yearly_savings': round(yearly_savings, 2),
            'per_analysis_savings': round(avg_cost_per_analysis + 10, 2),
            'total_analyses': analyses_count,
            'labor_hours_saved': round(analyses_count * 0.25, 1),  # 15 minutes per analysis
            'error_reduction': round(analyses_count * 0.05, 2),
            'efficiency_gain': round(analyses_count * 0.03, 2),
            'roi_percentage': round((total_savings / (analyses_count * 10)) * 100, 1) if analyses_count > 0 else 0,
            'break_even_analyses': 10
        }
        
    except Exception as e:
        logger.error(f"Error calculating cost savings: {str(e)}")
        return {
            'total_savings': 0,
            'monthly_savings': 0,
            'yearly_savings': 0,
            'per_analysis_savings': 0,
            'total_analyses': analyses_count,
            'error': str(e)
        }


def calculate_cost_savings_enhanced(hospital_id: int, analyses_count: int, avg_cost_per_analysis: int = 50) -> Dict[str, Any]:
    """
    Enhanced cost savings with hospital-specific factors
    
    Args:
        hospital_id: Hospital ID
        analyses_count: Number of AI analyses performed
        avg_cost_per_analysis: Average cost saved per analysis
    
    Returns:
        dict: Enhanced cost savings breakdown
    """
    try:
        hospital = Hospital.query.get(hospital_id)
        
        # Hospital-specific multipliers
        size_multiplier = {
            'small': 0.8,
            'medium': 1.0,
            'large': 1.2,
            'teaching': 1.3
        }.get(hospital.type if hospital else 'medium', 1.0)
        
        # Adjust cost per analysis based on location
        location_multiplier = {
            'US': 1.5,
            'Europe': 1.2,
            'Asia': 0.8,
            'Africa': 0.6,
            'default': 1.0
        }.get(hospital.country if hospital else 'default', 1.0)
        
        adjusted_cost = avg_cost_per_analysis * size_multiplier * location_multiplier
        
        base_savings = calculate_cost_savings(analyses_count, adjusted_cost)
        
        # Add hospital-specific insights
        if hospital:
            base_savings['hospital_name'] = hospital.name
            base_savings['hospital_type'] = hospital.type
            base_savings['hospital_country'] = hospital.country
        
        return base_savings
        
    except Exception as e:
        logger.error(f"Error in enhanced cost savings: {e}")
        return calculate_cost_savings(analyses_count, avg_cost_per_analysis)


# ============================================
# TIME SAVINGS CALCULATION
# ============================================

def calculate_time_savings(analyses_count: int) -> Dict[str, Any]:
    """
    Calculate estimated time savings in hours
    
    Args:
        analyses_count: Number of AI analyses performed
    
    Returns:
        dict: Time savings breakdown
    """
    try:
        # Time saved per analysis in hours (15 minutes = 0.25 hours)
        time_per_analysis = 0.25
        
        # Total hours saved
        total_hours = analyses_count * time_per_analysis
        
        # Calculate different perspectives
        hours_saved = round(total_hours, 1)
        days_saved = round(hours_saved / 8, 1)
        weeks_saved = round(days_saved / 5, 1)
        months_saved = round(weeks_saved / 4, 1)
        
        # Calculate productivity impact
        productivity_gain = min(100, round((hours_saved / (analyses_count * 0.5)) * 100, 1)) if analyses_count > 0 else 0
        
        return {
            'total_hours': hours_saved,
            'total_days': days_saved,
            'total_weeks': weeks_saved,
            'total_months': months_saved,
            'per_analysis_hours': round(time_per_analysis, 2),
            'per_analysis_minutes': 15,
            'total_analyses': analyses_count,
            'productivity_gain': round(productivity_gain, 1),
            'formatted_time': format_time_savings(hours_saved),
            'breakdown': {
                'diagnosis_time': round(hours_saved * 0.4, 1),  # 40% diagnostic time
                'review_time': round(hours_saved * 0.3, 1),     # 30% review time
                'documentation_time': round(hours_saved * 0.2, 1), # 20% documentation
                'communication_time': round(hours_saved * 0.1, 1)  # 10% communication
            }
        }
        
    except Exception as e:
        logger.error(f"Error calculating time savings: {str(e)}")
        return {
            'total_hours': 0,
            'total_days': 0,
            'total_weeks': 0,
            'total_months': 0,
            'error': str(e)
        }


def format_time_savings(hours: float) -> str:
    """Format time savings in human-readable format"""
    if hours < 1:
        return f"{round(hours * 60)} minutes"
    elif hours < 24:
        return f"{round(hours)} hours"
    elif hours < 168:
        return f"{round(hours / 8)} days"
    else:
        return f"{round(hours / 40)} weeks"


