def get_accuracy_trend(hospital_id: int, days: int = 30) -> Dict[str, Any]:
    """
    Get accuracy trend data for AI analyses
    
    Args:
        hospital_id: Hospital ID
        days: Number of days to analyze (default: 30)
    
    Returns:
        dict: Accuracy trend data
    """
    try:
        end_date = datetime.utcnow()
        start_date = end_date - timedelta(days=days)
        
        # Get hospital users
        hospital_user_ids = [u.id for u in User.query.filter_by(hospital_id=hospital_id).all()]
        
        if not hospital_user_ids:
            return {
                'current': 0,
                'trend': 'unknown',
                'change': 0,
                'data_points': [],
                'average': 0,
                'min': 0,
                'max': 0
            }
        
        # Query analyses for the hospital
        analyses = MedicalAnalysis.query.filter(
            MedicalAnalysis.user_id.in_(hospital_user_ids),
            MedicalAnalysis.created_at >= start_date,
            MedicalAnalysis.created_at <= end_date
        ).order_by(MedicalAnalysis.created_at.asc()).all()
        
        if not analyses:
            return {
                'current': 0,
                'trend': 'unknown',
                'change': 0,
                'data_points': [],
                'average': 0,
                'min': 0,
                'max': 0
            }
        
        # Group by day
        daily_accuracy = {}
        for analysis in analyses:
            date_key = analysis.created_at.date().isoformat()
            if date_key not in daily_accuracy:
                daily_accuracy[date_key] = []
            if analysis.confidence_score:
                daily_accuracy[date_key].append(analysis.confidence_score)
        
        # Calculate daily averages
        data_points = []
        for date, scores in sorted(daily_accuracy.items()):
            avg_score = sum(scores) / len(scores) if scores else 0
            data_points.append({
                'date': date,
                'accuracy': round(avg_score * 100, 1)
            })
        
        # Calculate overall statistics
        all_scores = [a.confidence_score for a in analyses if a.confidence_score]
        avg_accuracy = (sum(all_scores) / len(all_scores) * 100) if all_scores else 0
        
        # Calculate trend
        if len(data_points) >= 2:
            first_half = data_points[:len(data_points)//2]
            second_half = data_points[len(data_points)//2:]
            
            first_avg = sum(p['accuracy'] for p in first_half) / len(first_half)
            second_avg = sum(p['accuracy'] for p in second_half) / len(second_half)
            
            change = second_avg - first_avg
            
            if change > 2:
                trend = 'improving'
            elif change < -2:
                trend = 'declining'
            else:
                trend = 'stable'
        else:
            change = 0
            trend = 'stable'
        
        return {
            'current': round(avg_accuracy, 1),
            'trend': trend,
            'change': round(change, 1),
            'data_points': data_points,
            'average': round(avg_accuracy, 1),
            'min': round(min(all_scores) * 100, 1) if all_scores else 0,
            'max': round(max(all_scores) * 100, 1) if all_scores else 0,
            'total_analyses': len(analyses),
            'period_days': days,
            'start_date': start_date.isoformat(),
            'end_date': end_date.isoformat()
        }
        
    except Exception as e:
        logger.error(f"Error calculating accuracy trend: {str(e)}")
        return {
            'current': 0,
            'trend': 'unknown',
            'change': 0,
            'data_points': [],
            'average': 0,
            'error': str(e)
        }



# ============================================
# MEDICAL RESPONSE GENERATION
# ============================================

def generate_intelligent_medical_response(messages, medical_entities, context):
    """
    Generate intelligent medical response with enhanced features
    
    Args:
        messages: List of chat messages
        medical_entities: Extracted medical entities
        context: Chat context including user info, plan, etc.
    
    Returns:
        dict: Enhanced medical response
    """
    try:
        last_message = messages[-1]['content'] if messages else ""
        message_lower = last_message.lower()
        
        # Healthcare context
        healthcare_context = context.get('healthcare_context', {})
        user_type = context.get('user_type', 'unknown')
        plan = context.get('plan', 'free')
        
        # Base response structure
        response = {
            "response": "",
            "confidence": 0.85,
            "sources": [],
            "entities": medical_entities,
            "timestamp": datetime.utcnow().isoformat(),
            "suggestions": [],
            "disclaimer": "",
            "plan_level": plan,
            "user_type": user_type
        }
        
        # Analyze message type
        message_type = detect_message_type(last_message, medical_entities)
        
        # Generate response based on message type
        if message_type == 'emergency':
            response.update(generate_emergency_response(last_message))
            
        elif message_type == 'symptom_analysis' and medical_entities:
            response.update(generate_symptom_response(last_message, medical_entities))
            
        elif message_type == 'medication_query':
            response.update(generate_medication_response(last_message, medical_entities))
            
        elif message_type == 'disease_query':
            response.update(generate_disease_response(last_message, medical_entities))
            
        elif message_type == 'hospital_query':
            response.update(generate_hospital_response(last_message, context))
            
        elif message_type == 'lab_query':
            response.update(generate_lab_response(last_message, medical_entities))
            
        elif message_type == 'safety_query':
            response.update(generate_safety_response(last_message))
            
        elif message_type == 'greeting':
            response.update(generate_greeting_response(last_message))
            
        elif message_type == 'feedback':
            response.update(generate_feedback_response(last_message))
            
        else:
            response.update(generate_general_response(last_message))
        
        # Add disclaimer based on user type
        if user_type not in ['doctor', 'nurse', 'medical_staff']:
            response['disclaimer'] = "I am an AI assistant. This information is not medical advice. Always consult a healthcare professional."
        
        # Add plan-based limitations
        if plan == 'free':
            response['response'] = response['response'][:500] + "..."
            response['suggestions'] = response['suggestions'][:2]
            response['plan_limitations'] = "Free plan: Limited response length"
        
        return response
        
    except Exception as e:
        current_app.logger.error(f"Error generating medical response: {str(e)}")
        return {
            "response": "I'm here to help with your medical questions. Please provide more details so I can assist you better.",
            "confidence": 0.80,
            "sources": ['Medical Knowledge Base'],
            "timestamp": datetime.utcnow().isoformat(),
            "suggestions": [
                "What specific symptoms are you experiencing?",
                "When did your symptoms begin?",
                "Have you seen a doctor about this concern?"
            ],
            "error": str(e)
        }


# ============================================
# RESPONSE GENERATION HELPERS
# ============================================

def detect_message_type(message, entities):
    """Detect the type of medical message"""
    message_lower = message.lower()
    
    # Emergency detection
    emergency_keywords = ['emergency', 'urgent', 'severe', 'critical', 
                         'chest pain', 'difficulty breathing', 'bleeding',
                         'loss of consciousness', 'stroke']
    if any(kw in message_lower for kw in emergency_keywords):
        return 'emergency'
    
    # Symptom detection
    symptom_keywords = ['symptom', 'pain', 'ache', 'hurt', 'fever', 'headache',
                       'nausea', 'dizzy', 'weak', 'tired', 'fatigue']
    if any(kw in message_lower for kw in symptom_keywords):
        return 'symptom_analysis'
    
    # Medication detection
    medication_keywords = ['medication', 'drug', 'pill', 'prescription', 'dosage',
                          'pharmacy', 'medicine', 'tablet', 'capsule']
    if any(kw in message_lower for kw in medication_keywords):
        return 'medication_query'
    
    # Disease detection
    disease_keywords = ['disease', 'condition', 'illness', 'infection', 'disorder',
                        'diagnosis', 'treatment', 'cure']
    if any(kw in message_lower for kw in disease_keywords):
        return 'disease_query'
    
    # Hospital detection
    hospital_keywords = ['hospital', 'clinic', 'department', 'doctor', 'nurse',
                        'staff', 'ward', 'emergency room', 'er']
    if any(kw in message_lower for kw in hospital_keywords):
        return 'hospital_query'
    
    # Lab detection
    lab_keywords = ['lab', 'test', 'result', 'blood', 'urine', 'sample',
                   'analysis', 'diagnostic']
    if any(kw in message_lower for kw in lab_keywords):
        return 'lab_query'
    
    # Safety detection
    safety_keywords = ['safety', 'hazard', 'risk', 'danger', 'protective',
                      'precaution', 'compliance']
    if any(kw in message_lower for kw in safety_keywords):
        return 'safety_query'
    
    # Greeting detection
    greeting_keywords = ['hello', 'hi', 'hey', 'greetings', 'good morning',
                        'good afternoon', 'good evening']
    if any(kw in message_lower for kw in greeting_keywords):
        return 'greeting'
    
    # Feedback detection
    feedback_keywords = ['thanks', 'thank you', 'great', 'helpful', 'useful',
                        'appreciate', 'awesome']
    if any(kw in message_lower for kw in feedback_keywords):
        return 'feedback'
    
    return 'general'


