# ============================================
# SYMPTOM TO CONDITION MAPPING
# ============================================

def map_symptoms_to_conditions(symptoms):
    """Map symptoms to possible conditions"""
    condition_map = {
        'headache': ['Migraine', 'Tension Headache', 'Cluster Headache', 'Sinusitis'],
        'fever': ['Infection', 'Influenza', 'COVID-19', 'Strep Throat'],
        'cough': ['Common Cold', 'Bronchitis', 'Pneumonia', 'COVID-19'],
        'fatigue': ['Anemia', 'Thyroid Disorder', 'Depression', 'Sleep Apnea'],
        'nausea': ['Food Poisoning', 'Migraine', 'Pregnancy', 'Gastroenteritis'],
        'dizziness': ['Vertigo', 'Anemia', 'Low Blood Pressure', 'Inner Ear Disorder'],
        'chest pain': ['Heart Attack', 'Angina', 'Pneumonia', 'Costochondritis'],
        'shortness of breath': ['Asthma', 'COPD', 'Pneumonia', 'Heart Disease'],
        'sore throat': ['Strep Throat', 'Cold', 'Influenza', 'Tonsillitis'],
        'back pain': ['Muscle Strain', 'Herniated Disc', 'Arthritis', 'Kidney Stones'],
        'joint pain': ['Arthritis', 'Gout', 'Lupus', 'Lyme Disease'],
        'rash': ['Allergic Reaction', 'Eczema', 'Psoriasis', 'Shingles'],
        'abdominal pain': ['Appendicitis', 'Food Poisoning', 'Ulcer', 'IBS'],
        'vision changes': ['Migraine', 'Retinal Issues', 'Cataracts', 'Glaucoma'],
        'confusion': ['Stroke', 'Dementia', 'Sepsis', 'Drug Interaction']
    }
    
    conditions = []
    for symptom in symptoms:
        symptom_lower = symptom.lower()
        for key, mapped_conditions in condition_map.items():
            if key in symptom_lower or symptom_lower in key:
                conditions.extend(mapped_conditions[:2])
    
    # Remove duplicates and limit
    seen = set()
    unique_conditions = []
    for condition in conditions:
        if condition not in seen:
            seen.add(condition)
            unique_conditions.append(condition)
    
    return unique_conditions[:3]


