def get_hospital_plan_distribution(hospital_id):
    """Get plan distribution for hospital users"""
    try:
        users = User.query.filter_by(hospital_id=hospital_id).all()
        plan_counts = {}
        for user in users:
            plan = user.subscription_plan if hasattr(user, 'subscription_plan') else 'free'
            plan_counts[plan] = plan_counts.get(plan, 0) + 1
        return plan_counts
    except Exception as e:
        current_app.logger.error(f"Error getting plan distribution: {str(e)}")
        return {}


def get_hospital_ai_usage_stats(hospital_id):
    """Get AI usage statistics for hospital"""
    try:
        # Count AI analyses
        total_analyses = MedicalAnalysis.query.filter_by(hospital_id=hospital_id).count()
        
        # Count by type
        analysis_types = db.session.query(
            MedicalAnalysis.analysis_type,
            func.count(MedicalAnalysis.id)
        ).filter_by(hospital_id=hospital_id).group_by(MedicalAnalysis.analysis_type).all()
        
        return {
            'total_analyses': total_analyses,
            'analysis_types': {at: count for at, count in analysis_types}
        }
    except Exception as e:
        current_app.logger.error(f"Error getting AI usage stats: {str(e)}")
        return {}

