@app.route('/api/ai/medical/symptoms', methods=['POST'])
@jwt_required
def analyze_symptoms():
    """Analyze symptoms and suggest potential conditions"""
    try:
        is_super_admin = check_super_admin()
        user = request.user
        
        current_app.logger.info(f"Symptoms analysis - User: {user.email}, Super admin: {is_super_admin}")
        
        # SUPER ADMIN: BYPASS ALL CHECKS
        if is_super_admin:
            current_app.logger.info(f"🔓 SUPER ADMIN FULL ACCESS - Symptoms analysis for {user.email}")
            
            data = request.get_json()
            symptoms = data.get('symptoms', [])
            patient_info = data.get('patientInfo', {})
            
            if medical_ai and medical_ai.is_model_available('bio_clinical_bert'):
                symptom_text = " ".join(symptoms) if isinstance(symptoms, list) else str(symptoms)
                analysis_result = medical_ai.symptoms_analyzer(symptom_text, patient_info)
                
                formatted_result = {
                    'conditions': analysis_result.get('possible_conditions', []),
                    'symptoms_detected': analysis_result.get('symptoms_detected', []),
                    'severity': analysis_result.get('severity', 'UNKNOWN'),
                    'urgency': analysis_result.get('urgency', 'ROUTINE'),
                    'emergency_indicators': analysis_result.get('emergency_indicators', []),
                    'recommendations': analysis_result.get('recommendations', []),
                    'confidence': analysis_result.get('confidence', 0.85),
                    'processing_time': analysis_result.get('processing_time', 0),
                    'models_used': analysis_result.get('models_used', [])
                }
            else:
                formatted_result = {
                    'conditions': [],
                    'symptoms_detected': [{'text': s, 'confidence': 0.8} for s in symptoms],
                    'severity': 'UNKNOWN',
                    'urgency': 'ROUTINE',
                    'recommendations': ['Please consult a healthcare provider'],
                    'confidence': 0.7
                }
            
            analysis_record = MedicalAnalysis(
                user_id=user.id,
                hospital_id=user.hospital_id,
                analysis_type='symptom_analysis',
                input_data=json.dumps({"symptoms": symptoms, "patient_info": patient_info, "access_level": "super_admin_full_access"}),
                output_data=json.dumps(formatted_result),
                confidence_score=formatted_result.get('confidence', 0.85),
                created_at=datetime.utcnow(),
                is_super_admin_access=True
            )
            db.session.add(analysis_record)
            db.session.commit()
            
            return jsonify({
                'success': True,
                'analysis': formatted_result,
                'analysisId': analysis_record.id,
                'accessInfo': {
                    'access_level': 'super_admin_full_access',
                    'is_super_admin': True,
                    'bypassed_checks': ['plan_check', 'feature_check', 'limit_check', 'role_check'],
                    'data_type': 'real_analysis'
                },
                'message': 'Super admin full access mode - real symptom analysis performed'
            }), 200
        
        # ===== REGULAR USER FLOW =====
        # ✅ Use has_feature_access for plan check
        if not has_feature_access('symptom_analysis'):
            return jsonify({
                'success': False,
                'error': 'Symptom analysis not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'current_plan': request.effective_plan,
                'suggestion': f'Upgrade to {get_next_plan(request.effective_plan)} plan for this feature'
            }), 403
        
        # Check if user can access medical AI features
        user_has_medical_access = False
        if hasattr(user, 'user_type'):
            if user.user_type in ['doctor', 'nurse', 'medical_staff']:
                user_has_medical_access = True
            elif user.user_type == 'admin' and user.hospital_id:
                user_has_medical_access = True
            elif user.user_type in ['company_admin', 'hospital_admin', 'safety_manager']:
                user_has_medical_access = True
        
        if not user_has_medical_access:
            return jsonify({
                'success': False,
                'error': 'Medical AI features require medical professional or admin account',
                'code': 'MEDICAL_ACCESS_REQUIRED',
                'user_type': user.user_type
            }), 403
        
        # Check usage limits
        if request.effective_plan == 'free':
            if hasattr(user, 'monthly_ai_requests_used'):
                plan_limit = request.plan_limits.get('ai_requests', 10)
                if user.monthly_ai_requests_used >= plan_limit:
                    return jsonify({
                        'success': False,
                        'error': 'Monthly AI analysis limit reached',
                        'code': 'AI_LIMIT_EXCEEDED',
                        'current_usage': user.monthly_ai_requests_used,
                        'plan_limit': plan_limit,
                        'suggestion': f'Upgrade to {get_next_plan(request.effective_plan)} plan for more requests'
                    }), 403
        
        data = request.get_json()
        symptoms = data.get('symptoms', [])
        patient_info = data.get('patientInfo', {})
        
        current_app.logger.info(f"Symptom analysis request from {user.email} (Regular user)")
        
        if medical_ai and medical_ai.is_model_available('bio_clinical_bert'):
            symptom_text = " ".join(symptoms) if isinstance(symptoms, list) else str(symptoms)
            analysis_result = medical_ai.symptoms_analyzer(symptom_text, patient_info)
            
            if request.effective_plan == 'free':
                formatted_result = {
                    'conditions': analysis_result.get('possible_conditions', [])[:3],
                    'symptoms_detected': analysis_result.get('symptoms_detected', [])[:5],
                    'urgency': analysis_result.get('urgency', 'ROUTINE'),
                    'recommendations': analysis_result.get('recommendations', [])[:3],
                    'confidence': analysis_result.get('confidence', 0.85)
                }
            elif request.effective_plan == 'pro':
                formatted_result = {
                    'conditions': analysis_result.get('possible_conditions', [])[:5],
                    'symptoms_detected': analysis_result.get('symptoms_detected', []),
                    'severity': analysis_result.get('severity', 'UNKNOWN'),
                    'urgency': analysis_result.get('urgency', 'ROUTINE'),
                    'recommendations': analysis_result.get('recommendations', [])[:5],
                    'confidence': analysis_result.get('confidence', 0.85)
                }
            else:
                formatted_result = {
                    'conditions': analysis_result.get('possible_conditions', []),
                    'symptoms_detected': analysis_result.get('symptoms_detected', []),
                    'severity': analysis_result.get('severity', 'UNKNOWN'),
                    'urgency': analysis_result.get('urgency', 'ROUTINE'),
                    'emergency_indicators': analysis_result.get('emergency_indicators', []),
                    'recommendations': analysis_result.get('recommendations', []),
                    'confidence': analysis_result.get('confidence', 0.85),
                    'processing_time': analysis_result.get('processing_time', 0)
                }
        else:
            formatted_result = {
                'conditions': [],
                'symptoms_detected': [{'text': s, 'confidence': 0.8} for s in symptoms],
                'urgency': 'ROUTINE',
                'recommendations': ['Please consult a healthcare provider'],
                'confidence': 0.7
            }
        
        analysis_record = MedicalAnalysis(
            user_id=user.id,
            hospital_id=user.hospital_id,
            analysis_type='symptom_analysis',
            input_data=json.dumps({"symptoms": symptoms, "patient_info": patient_info}),
            output_data=json.dumps(formatted_result),
            confidence_score=formatted_result.get('confidence', 0.85),
            created_at=datetime.utcnow(),
            plan_used=request.effective_plan
        )
        db.session.add(analysis_record)
        
        if hasattr(user, 'monthly_ai_requests_used'):
            user.monthly_ai_requests_used += 1
            user.total_ai_requests_used = getattr(user, 'total_ai_requests_used', 0) + 1
            db.session.commit()
        
        return jsonify({
            'success': True,
            'analysis': formatted_result,
            'analysisId': analysis_record.id,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'aiRequestsRemaining': request.plan_limits.get('ai_requests', 0) - user.monthly_ai_requests_used if request.effective_plan == 'free' else 'unlimited'
            },
            'accessInfo': {
                'access_level': 'regular_user',
                'is_super_admin': False
            }
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Symptom analysis error: {str(e)}")
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Failed to analyze symptoms',
            'code': 'ANALYSIS_ERROR'
        }), 500


