@app.route('/api/hospital/<int:hospital_id>/quality-indicators', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_hospital_quality_indicators(hospital_id):
    """Get all quality indicators for a hospital"""
    try:
        healthcare_context = get_healthcare_context()
        current_app.logger.info(f"Quality indicators request for hospital {hospital_id}")
        
        if not has_feature_access('hospital_quality_indicators'):
            return jsonify({
                'success': False,
                'error': 'Quality indicators not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'current_plan': request.effective_plan
            }), 403
        
        is_super_admin = check_super_admin()
        user = request.user
        
        if not (is_super_admin or request.is_system_team or user.hospital_id == hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED'
            }), 403
        
        hospital = Hospital.query.get(hospital_id)
        if not hospital:
            return jsonify({
                'success': False,
                'error': f'Hospital {hospital_id} not found',
                'code': 'HOSPITAL_NOT_FOUND'
            }), 404
        
        indicators = QualityIndicator.query.filter_by(hospital_id=hospital_id).all()
        
        indicator_data = []
        for ind in indicators:
            # Calculate achievement percentage
            achievement = 0
            if ind.target and ind.target > 0:
                achievement = round((ind.current_value or 0) / ind.target * 100, 1)
            
            indicator_data.append({
                'id': ind.id,
                'hospital_id': ind.hospital_id,
                'indicator_code': ind.indicator_code,
                'name': ind.name,
                'category': ind.category,
                'target': ind.target,
                'current_value': ind.current_value,
                'benchmark': ind.benchmark,
                'achievement': achievement,
                'trend': ind.trend,
                'unit': ind.unit,
                'measurement_frequency': ind.measurement_frequency,
                'last_updated': ind.last_updated.isoformat() if ind.last_updated else None,
                'department': ind.department,
                'notes': ind.notes,
                'created_at': ind.created_at.isoformat() if ind.created_at else None,
                'updated_at': ind.updated_at.isoformat() if ind.updated_at else None
            })
        
        return jsonify({
            'success': True,
            'data': indicator_data,
            'total': len(indicator_data)
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching quality indicators: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/hospital/<int:hospital_id>/quality-indicators', methods=['POST'])
@jwt_required
@validate_healthcare_headers
def create_hospital_quality_indicator(hospital_id):
    """Create a new quality indicator for a hospital"""
    try:
        healthcare_context = get_healthcare_context()
        current_app.logger.info(f"Create quality indicator request for hospital {hospital_id}")
        
        if not has_feature_access('hospital_quality_indicators'):
            return jsonify({
                'success': False,
                'error': 'Quality indicators not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'current_plan': request.effective_plan
            }), 403
        
        is_super_admin = check_super_admin()
        user = request.user
        
        if not (is_super_admin or request.is_system_team or user.user_type in ['admin', 'safety_manager']):
            return jsonify({
                'success': False,
                'error': 'Insufficient permissions',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        hospital = Hospital.query.get(hospital_id)
        if not hospital:
            return jsonify({
                'success': False,
                'error': f'Hospital {hospital_id} not found',
                'code': 'HOSPITAL_NOT_FOUND'
            }), 404
        
        data = request.get_json()
        
        # ✅ Validate required fields
        if 'name' not in data:
            return jsonify({
                'success': False,
                'error': 'Missing required field: name',
                'code': 'VALIDATION_ERROR'
            }), 400
        
        # ✅ Generate indicator code
        import random
        import string
        indicator_code = f"QI-{datetime.utcnow().strftime('%Y%m')}-{''.join(random.choices(string.ascii_uppercase + string.digits, k=6))}"
        
        # ✅ Create quality indicator
        indicator = QualityIndicator(
            indicator_code=indicator_code,
            name=data['name'],
            category=data.get('category'),
            hospital_id=hospital_id,
            target=data.get('target'),
            current_value=data.get('current_value'),
            benchmark=data.get('benchmark'),
            trend=data.get('trend', 'stable'),
            unit=data.get('unit'),
            measurement_frequency=data.get('measurement_frequency'),
            last_updated=datetime.utcnow(),
            department=data.get('department'),
            notes=data.get('notes')
        )
        
        db.session.add(indicator)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Quality indicator created successfully',
            'data': {
                'id': indicator.id,
                'indicator_code': indicator.indicator_code,
                'name': indicator.name,
                'category': indicator.category,
                'target': indicator.target,
                'current_value': indicator.current_value,
                'benchmark': indicator.benchmark,
                'trend': indicator.trend,
                'unit': indicator.unit
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error creating quality indicator: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


