@app.route('/api/ai/medical/history', methods=['GET'])
@jwt_required
def get_analysis_medical_history():
    """Get analysis history - REAL IMPLEMENTATION"""
    try:
        is_super_admin = check_super_admin()
        user = request.user
        
        # ✅ Use has_feature_access for plan check
        if not is_super_admin and not has_feature_access('analysis_history'):
            return jsonify({
                'success': False,
                'error': 'Analysis history not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': f'Upgrade to {get_next_plan(request.effective_plan)} plan to access analysis history',
                'current_plan': request.effective_plan
            }), 403
        
        limit = request.args.get('limit', 50, type=int)
        analysis_type = request.args.get('type')
        
        # Apply plan-based limits for non-super-admins
        if is_super_admin:
            max_limit = 10000
        else:
            max_history_limit = {
                'free': 10,
                'pro': 100,
                'business': 500,
                'enterprise': 5000
            }
            max_limit = max_history_limit.get(request.effective_plan, 10)
        
        if limit > max_limit:
            limit = max_limit
        
        # Query database
        if is_super_admin:
            query = MedicalAnalysis.query
        else:
            query = MedicalAnalysis.query.filter_by(user_id=user.id)
        
        if analysis_type:
            query = query.filter_by(analysis_type=analysis_type)
        
        history = query.order_by(MedicalAnalysis.created_at.desc()).limit(limit).all()
        
        history_data = []
        for record in history:
            history_data.append({
                "id": record.id,
                "type": record.analysis_type,
                "confidence": record.confidence_score,
                "timestamp": record.created_at.isoformat(),
                "inputPreview": get_input_preview(record.input_data),
                "outputPreview": get_output_preview(record.output_data),
                "isTestData": record.is_super_admin_access if hasattr(record, 'is_super_admin_access') else False,
                "planUsed": json.loads(record.input_data).get('plan_used', 'unknown') if record.input_data else 'unknown'
            })
        
        return jsonify({
            'success': True,
            'history': history_data,
            'total': len(history_data),
            'planInfo': {
                'currentPlan': 'super_admin' if is_super_admin else request.effective_plan,
                'is_super_admin': is_super_admin,
                'maxHistory': max_limit,
                'retentionDays': get_retention_days(request.effective_plan),
                'dataScope': 'all_data' if is_super_admin else 'user_data'
            }
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Analysis history error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to get analysis history',
            'code': 'HISTORY_ERROR'
        }), 500


