def perform_ai_lab_analysis(lab_data, reference_ranges):
    """Analyze lab results using AI"""
    abnormalities = []
    interpretation = "Normal"
    urgency = "Low"
    
    # Analyze each lab value against reference ranges
    for test_name, test_value in lab_data.items():
        if isinstance(test_value, (int, float)) and test_name in reference_ranges:
            ref_range = reference_ranges[test_name]
            if isinstance(ref_range, dict):
                ref_min = ref_range.get('min')
                ref_max = ref_range.get('max')
            else:
                ref_min, ref_max = ref_range
            
            if test_value < ref_min:
                abnormalities.append(f"{test_name} is below normal range ({test_value} < {ref_min})")
            elif test_value > ref_max:
                abnormalities.append(f"{test_name} is above normal range ({test_value} > {ref_max})")
    
    # Determine urgency based on abnormalities
    if abnormalities:
        interpretation = "Abnormal results detected that require review"
        critical_abnormalities = [ab for ab in abnormalities if any(word in ab.lower() for word in ['critical', 'severe', 'dangerous'])]
        urgency = "High" if critical_abnormalities else "Medium"
    else:
        interpretation = "All laboratory results are within normal ranges"
    
    return {
        'abnormalities': abnormalities,
        'interpretation': interpretation,
        'urgency': urgency,
        'recommendations': [
            'Consult with healthcare provider for clinical interpretation',
            'Discuss results with your doctor',
            'Follow up as recommended based on results'
        ],
        'confidence': 0.90,
        'timestamp': datetime.utcnow().isoformat()
    }

