# Utility Functions
def calculate_medical_risk_score(patient_data):
    """Calculate medical risk score based on patient data"""
    base_score = 50
    
    # Adjust based on patient data factors
    if 'age' in patient_data:
        age = patient_data['age']
        if age > 60:
            base_score += 20
        elif age > 40:
            base_score += 10
    
    if 'existing_conditions' in patient_data:
        conditions = patient_data['existing_conditions']
        if isinstance(conditions, list):
            base_score += len(conditions) * 5
    
    return min(base_score, 100)

def generate_medical_recommendations(conditions, patient_info):
    """Generate medical recommendations based on conditions"""
    recommendations = [
        "Consult with healthcare provider for accurate diagnosis",
        "Follow medical advice and treatment plans",
        "Keep scheduled medical appointments"
    ]
    
    # Add condition-specific recommendations
    for condition in conditions[:2]:  # Top 2 conditions
        if 'infection' in condition['condition'].lower():
            recommendations.append("Complete prescribed antibiotic course if applicable")
        if 'chronic' in condition['condition'].lower():
            recommendations.append("Monitor condition regularly with healthcare provider")
    
    return recommendations

def check_emergency_indicators(symptoms):
    """Check for emergency indicators in symptoms"""
    emergency_indicators = []
    
    severe_symptoms = [
        'chest pain', 'difficulty breathing', 'severe bleeding', 
        'loss of consciousness', 'sudden weakness', 'severe headache'
    ]
    
    symptom_text = " ".join(symptoms) if isinstance(symptoms, list) else str(symptoms)
    
    for symptom in severe_symptoms:
        if symptom in symptom_text.lower():
            emergency_indicators.append(f"Seek immediate medical attention for {symptom}")
    
    return emergency_indicators if emergency_indicators else ["No immediate emergency signs detected"]

def extract_medical_categories(entities):
    """Extract medical categories from entities"""
    categories = set()
    for entity in entities:
        categories.add(entity.get('entity_group', 'general'))
    return list(categories)

def extract_key_points_from_medical_entities(entities):
    """Extract key points from medical entities"""
    return [entity['word'] for entity in entities[:5]] if entities else []

def extract_key_medical_points(text):
    """Extract key medical points from text"""
    sentences = text.split('.')
    return '. '.join([s.strip() for s in sentences[:3] if s.strip()]) + '.'


