@app.route('/api/doctor/profile', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_doctor_profile():
    """Get current doctor's profile"""
    try:
        healthcare_context = get_healthcare_context()
        user = request.user
        is_super_admin = check_super_admin()
        
        # SUPER ADMIN: Can view any doctor's profile
        if is_super_admin:
            doctor_id = request.args.get('doctor_id')
            if doctor_id:
                doctor = Doctor.query.get(doctor_id)
            else:
                doctor = Doctor.query.filter_by(email=user.email).first()
        else:
            # Regular user - must be a doctor
            if user.user_type != 'doctor':
                return jsonify({
                    'success': False,
                    'error': 'Access denied. Only doctors can access this endpoint.',
                    'code': 'ACCESS_DENIED',
                    'healthcare_context': healthcare_context
                }), 403
            
            doctor = Doctor.query.filter_by(email=user.email).first()
        
        if not doctor:
            return jsonify({
                'success': False,
                'error': 'Doctor not found',
                'code': 'NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        return jsonify({
            'success': True,
            'data': doctor.to_dict(),
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Get profile error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


@app.route('/api/doctor/profile', methods=['PUT'])
@jwt_required
@validate_healthcare_headers
def update_doctor_profile():
    """Update current doctor's profile"""
    try:
        healthcare_context = get_healthcare_context()
        user = request.user
        is_super_admin = check_super_admin()
        
        # Get doctor
        doctor = Doctor.query.filter_by(email=user.email).first()
        if not doctor:
            return jsonify({
                'success': False,
                'error': 'Doctor not found',
                'code': 'NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        data = request.get_json()
        
        # Update fields
        if data.get('name'):
            doctor.name = data['name']
        if data.get('specialty'):
            doctor.specialty = data['specialty']
        if data.get('department'):
            doctor.department = data['department']
        if data.get('phone'):
            doctor.phone = data['phone']
        if data.get('email'):
            existing = Doctor.query.filter(
                Doctor.email == data['email'],
                Doctor.id != doctor.id
            ).first()
            if existing:
                return jsonify({
                    'success': False,
                    'error': 'Email already in use',
                    'code': 'EMAIL_EXISTS',
                    'healthcare_context': healthcare_context
                }), 400
            doctor.email = data['email']
        
        # Update password if provided
        if data.get('new_password'):
            if len(data['new_password']) < 8:
                return jsonify({
                    'success': False,
                    'error': 'Password must be at least 8 characters',
                    'code': 'WEAK_PASSWORD',
                    'healthcare_context': healthcare_context
                }), 400
            doctor.set_password(data['new_password'])
            send_password_change_email(doctor)
        
        doctor.updated_at = datetime.utcnow()
        db.session.commit()
        
        current_app.logger.info(f"Doctor profile updated: {doctor.email}")
        
        return jsonify({
            'success': True,
            'message': 'Profile updated successfully',
            'data': doctor.to_dict(),
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Update profile error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


