@app.route('/api/alerts/critical', methods=['POST'])
@jwt_required
@validate_healthcare_headers
def send_critical_alert():
    """Send critical alert for a patient"""
    try:
        healthcare_context = get_healthcare_context()
        user = request.user
        is_super_admin = check_super_admin()
        
        data = request.get_json()
        
        patient_id = data.get('patient_id')
        patient_name = data.get('patient_name')
        status = data.get('status')
        reason = data.get('reason', '')
        severity = data.get('severity', 'high')
        
        if not patient_id:
            return jsonify({
                'success': False,
                'error': 'Patient ID is required',
                'code': 'MISSING_PATIENT_ID',
                'healthcare_context': healthcare_context
            }), 400
        
        # Get patient
        patient = Patient.query.get(patient_id)
        if not patient:
            return jsonify({
                'success': False,
                'error': 'Patient not found',
                'code': 'PATIENT_NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        # Get doctor
        if is_super_admin:
            doctor = Doctor.query.filter_by(email=user.email).first()
            if not doctor:
                doctor = Doctor.query.first()
        else:
            if user.user_type != 'doctor':
                return jsonify({
                    'success': False,
                    'error': 'Access denied. Only doctors can send critical alerts.',
                    'code': 'ACCESS_DENIED',
                    'healthcare_context': healthcare_context
                }), 403
            
            doctor = Doctor.query.filter_by(email=user.email).first()
        
        if not doctor:
            return jsonify({
                'success': False,
                'error': 'Doctor not found',
                'code': 'NOT_FOUND',
                'healthcare_context': healthcare_context
            }), 404
        
        # Check if doctor is assigned to this patient
        if patient.doctor_id != doctor.id and not is_super_admin:
            return jsonify({
                'success': False,
                'error': 'Access denied. You are not assigned to this patient.',
                'code': 'ACCESS_DENIED',
                'healthcare_context': healthcare_context
            }), 403
        
        # Add critical alert to timeline
        timeline = PatientTimeline(
            patient_id=patient.id,
            event_type='Emergency',
            description=f"🚨 CRITICAL ALERT - Patient {patient.first_name} {patient.last_name} ({status}) - {reason} | Doctor: {doctor.name}",
            created_by=doctor.id
        )
        db.session.add(timeline)
        db.session.commit()
        
        current_app.logger.warning(f"CRITICAL ALERT: Patient {patient.first_name} {patient.last_name} - {status} - {reason}")
        
        # Send critical alert emails
        send_critical_alert_emails(patient, status, reason, doctor)
        
        return jsonify({
            'success': True,
            'message': 'Critical alert sent successfully',
            'data': {
                'patient_id': patient_id,
                'patient_name': patient_name,
                'status': status,
                'severity': severity,
                'timestamp': datetime.utcnow().isoformat(),
                'doctor_id': doctor.id,
                'doctor_name': doctor.name
            },
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Send critical alert error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


