@app.route('/api/hospital/analytics', methods=['GET'])
@jwt_required
@validate_healthcare_headers
def get_hospital_analytics():
    """Get hospital analytics with JWT auth - WITH HEALTHCARE HEADERS"""
    try:
        # Get healthcare context
        healthcare_context = get_healthcare_context()
        current_app.logger.info(f"Hospital analytics request from facility: {healthcare_context['facility']}")
        
        # ✅ Use has_feature_access for plan check
        if not request.is_system_team and not has_feature_access('hospital_analytics'):
            return jsonify({
                'success': False,
                'error': 'Hospital analytics not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'suggestion': f'Upgrade to {get_next_plan(request.effective_plan)} plan for hospital analytics',
                'current_plan': request.effective_plan,
                'healthcare_context': healthcare_context
            }), 403
        
        # Get query parameters for filtering
        time_range = request.args.get('time_range', '30d')
        hospital_id = request.args.get('hospital_id', None)
        
        # Build base query based on user permissions
        if request.is_system_team:
            # System team sees all hospitals
            hospitals_query = Hospital.query
            if hospital_id:
                hospitals_query = hospitals_query.filter(Hospital.id == hospital_id)
            hospitals = hospitals_query.all()
        else:
            # Regular users see only their hospital
            if hospital_id and int(hospital_id) != request.user.hospital_id:
                return jsonify({
                    'success': False,
                    'error': 'Access denied to this hospital',
                    'code': 'ACCESS_DENIED',
                    'healthcare_context': healthcare_context
                }), 403
            
            hospitals = [Hospital.query.get(request.user.hospital_id)] if request.user.hospital_id else []
        
        if not hospitals:
            return jsonify({
                'success': True,
                'message': 'No hospitals found',
                'hospitalCapacity': [],
                'aiUsageStats': [],
                'departmentStats': [],
                'infectionRates': {'overall': 0, 'compliance': 0},
                'patientSatisfaction': 0,
                'is_system_team': request.is_system_team,
                'healthcare_context': healthcare_context
            }), 200
        
        # Calculate date range based on time_range
        end_date = datetime.utcnow()
        if time_range == '7d':
            start_date = end_date - timedelta(days=7)
        elif time_range == '30d':
            start_date = end_date - timedelta(days=30)
        elif time_range == '90d':
            start_date = end_date - timedelta(days=90)
        elif time_range == '12m':
            start_date = end_date - timedelta(days=365)
        else:
            start_date = end_date - timedelta(days=30)  # Default to 30 days
        
        # Initialize analytics containers
        hospital_capacity = []
        ai_usage_stats = []
        department_stats = []
        all_departments = []
        
        for hospital in hospitals:
            # Get departments for this hospital
            departments = Department.query.filter_by(hospital_id=hospital.id).all()
            all_departments.extend(departments)
            
            # Calculate bed occupancy
            total_beds = hospital.beds or 0
            
            # Get occupied beds from admissions or encounters in the date range
            occupied_beds = 0
            if hasattr(hospital, 'admissions'):
                occupied_beds = Admission.query.filter(
                    Admission.hospital_id == hospital.id,
                    Admission.admitted_at <= end_date,
                    (Admission.discharged_at >= start_date) | (Admission.discharged_at.is_(None))
                ).count()
            else:
                # Fallback to estimation if no admission model
                occupied_beds = int(total_beds * 0.75)
            
            # Calculate utilization rate
            utilization_rate = round((occupied_beds / total_beds * 100), 1) if total_beds > 0 else 0
            
            hospital_capacity.append({
                'hospitalId': hospital.id,
                'hospitalName': hospital.name,
                'totalBeds': total_beds,
                'occupiedBeds': occupied_beds,
                'availableBeds': total_beds - occupied_beds,
                'utilizationRate': utilization_rate,
                'departmentsCount': len(departments),
                'staffCount': len(hospital.employees) if hasattr(hospital, 'employees') else 0,
                'trend': calculate_occupancy_trend(hospital.id, start_date, end_date)
            })
            
            # AI Usage statistics
            ai_usage = calculate_ai_usage(hospital.id, start_date, end_date)
            ai_usage_stats.append({
                'hospitalId': hospital.id,
                'hospitalName': hospital.name,
                'totalServices': ai_usage.get('total_services', 7),
                'activeServices': ai_usage.get('active_services', 0),
                'usagePercentage': ai_usage.get('usage_percentage', 0),
                'totalQueries': ai_usage.get('total_queries', 0),
                'successRate': ai_usage.get('success_rate', 0),
                'popularServices': ai_usage.get('popular_services', [])
            })
        
        # Department statistics
        for dept in all_departments:
            dept_stats = {
                'department_id': dept.id,
                'department_name': dept.name,
                'hospital_name': next((h.name for h in hospitals if h.id == dept.hospital_id), 'Unknown'),
                'hospital_id': dept.hospital_id,
                'risk_level': dept.risk_level or 'low',
                'hazards_count': len(dept.hazards) if hasattr(dept, 'hazards') else 0,
                'equipment_count': len(dept.equipment) if hasattr(dept, 'equipment') else 0,
                'staff_count': len(dept.employees) if hasattr(dept, 'employees') else 0,
                'head_of_department': dept.head_of_department,
                'recent_incidents': get_recent_incidents(dept.id, start_date, end_date)
            }
            department_stats.append(dept_stats)
        
        # Infection rates
        infection_rates = calculate_infection_rates(hospitals, start_date, end_date)
        
        # Patient satisfaction
        patient_satisfaction = calculate_patient_satisfaction(hospitals, start_date, end_date)
        
        # Summary statistics
        total_hospitals = len(hospitals)
        active_hospitals = sum(1 for h in hospitals if getattr(h, 'status', 'active') == 'active')
        total_departments = len(all_departments)
        total_beds = sum(h.beds or 0 for h in hospitals)
        total_staff = sum(len(h.employees) if hasattr(h, 'employees') else 0 for h in hospitals)
        
        # Calculate average utilization
        avg_utilization = round(
            sum(c['utilizationRate'] for c in hospital_capacity) / len(hospital_capacity), 1
        ) if hospital_capacity else 0
        
        return jsonify({
            'success': True,
            'hospitalCapacity': hospital_capacity,
            'aiUsageStats': ai_usage_stats,
            'departmentStats': department_stats,
            'infectionRates': infection_rates,
            'patientSatisfaction': patient_satisfaction,
            'summary': {
                'totalHospitals': total_hospitals,
                'activeHospitals': active_hospitals,
                'totalDepartments': total_departments,
                'totalBeds': total_beds,
                'totalStaff': total_staff,
                'avgUtilization': avg_utilization,
                'avgPatientSatisfaction': patient_satisfaction.get('average', 0)
            },
            'filters': {
                'time_range': time_range,
                'hospital_id': hospital_id
            },
            'is_system_team': request.is_system_team,
            'timestamp': datetime.utcnow().isoformat(),
            'healthcare_context': healthcare_context
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error in hospital analytics: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Internal server error',
            'code': 'INTERNAL_ERROR',
            'healthcare_context': get_healthcare_context() if 'get_healthcare_context' in dir() else {}
        }), 500


# Helper functions
def calculate_occupancy_trend(hospital_id: int, start_date: datetime, end_date: datetime, healthcare_context: Optional[Dict] = None) -> Dict[str, Any]:
    """
    Calculate occupancy trend over time period with actual database queries
    
    Args:
        hospital_id: ID of the hospital
        start_date: Start date for trend calculation
        end_date: End date for trend calculation
        healthcare_context: Healthcare context with facility info
    
    Returns:
        Dict containing occupancy trend data
    """
    try:
        facility = healthcare_context.get('facility', 'Unknown') if healthcare_context else 'Unknown'
        logger.info(f"Calculating occupancy trend for hospital {hospital_id} - Facility: {facility}")
        
        # Get hospital details
        hospital = Hospital.query.get(hospital_id)
        if not hospital:
            logger.warning(f"Hospital {hospital_id} not found for occupancy trend")
            return {
                'direction': 'unknown',
                'percentage_change': 0,
                'data_points': [],
                'message': 'Hospital not found'
            }
        
        total_beds = hospital.beds or 0
        if total_beds == 0:
            return {
                'direction': 'insufficient_data',
                'percentage_change': 0,
                'data_points': [],
                'message': 'No bed data available for this hospital'
            }
        
        # Query occupancy data from admissions
        daily_rates = []
        current_date = start_date
        
        # Use raw SQL for better performance with date ranges
        while current_date <= end_date:
            try:
                # Count occupied beds on this date
                occupied = Admission.query.filter(
                    Admission.hospital_id == hospital_id,
                    Admission.admitted_at <= current_date,
                    or_(
                        Admission.discharged_at >= current_date,
                        Admission.discharged_at.is_(None)
                    )
                ).count()
                
                rate = round((occupied / total_beds * 100), 1) if total_beds > 0 else 0
                daily_rates.append({
                    'date': current_date.strftime('%Y-%m-%d'),
                    'rate': rate,
                    'occupied': occupied,
                    'total': total_beds
                })
                current_date += timedelta(days=1)
            except Exception as e:
                logger.warning(f"Error querying occupancy for date {current_date}: {e}")
                # Add placeholder data point
                daily_rates.append({
                    'date': current_date.strftime('%Y-%m-%d'),
                    'rate': 0,
                    'occupied': 0,
                    'total': total_beds
                })
                current_date += timedelta(days=1)
        
        # Calculate trend
        if len(daily_rates) >= 2:
            first_rate = daily_rates[0]['rate']
            last_rate = daily_rates[-1]['rate']
            percentage_change = round(((last_rate - first_rate) / first_rate * 100) if first_rate > 0 else 0, 1)
            
            if percentage_change > 5:
                direction = 'increasing'
            elif percentage_change < -5:
                direction = 'decreasing'
            else:
                direction = 'stable'
        else:
            direction = 'stable'
            percentage_change = 0
        
        avg_occupancy = round(sum(d['rate'] for d in daily_rates) / len(daily_rates), 1) if daily_rates else 0
        
        return {
            'direction': direction,
            'percentage_change': percentage_change,
            'data_points': daily_rates,
            'total_beds': total_beds,
            'average_occupancy': avg_occupancy,
            'hospital_name': hospital.name,
            'timestamp': datetime.utcnow().isoformat()
        }
        
    except Exception as e:
        logger.error(f"Error calculating occupancy trend: {e}")
        return {
            'direction': 'unknown',
            'percentage_change': 0,
            'data_points': [],
            'error': str(e)
        }


def calculate_ai_usage(hospital_id: int, start_date: datetime, end_date: datetime, healthcare_context: Optional[Dict] = None) -> Dict[str, Any]:
    """
    Calculate AI usage statistics for a hospital with actual database queries
    
    Args:
        hospital_id: ID of the hospital
        start_date: Start date for analysis
        end_date: End date for analysis
        healthcare_context: Healthcare context with facility info
    
    Returns:
        Dict containing AI usage statistics
    """
    try:
        facility = healthcare_context.get('facility', 'Unknown') if healthcare_context else 'Unknown'
        logger.info(f"Calculating AI usage for hospital {hospital_id} - Facility: {facility}")
        
        # Get hospital
        hospital = Hospital.query.get(hospital_id)
        if not hospital:
            return {
                'total_services': 0,
                'active_services': 0,
                'usage_percentage': 0,
                'total_queries': 0,
                'success_rate': 0,
                'popular_services': [],
                'message': 'Hospital not found'
            }
        
        # Query AI usage from MedicalAnalysis table
        ai_analyses = MedicalAnalysis.query.filter(
            MedicalAnalysis.hospital_id == hospital_id,
            MedicalAnalysis.created_at.between(start_date, end_date)
        ).all()
        
        # Query AI chat records
        ai_chats = MedicalChat.query.filter(
            MedicalChat.hospital_id == hospital_id,
            MedicalChat.created_at.between(start_date, end_date)
        ).all() if hasattr(MedicalChat, '__tablename__') else []
        
        # Calculate statistics
        total_queries = len(ai_analyses) + len(ai_chats)
        
        # Get unique analysis types
        analysis_types = {}
        for analysis in ai_analyses:
            analysis_type = analysis.analysis_type or 'unknown'
            analysis_types[analysis_type] = analysis_types.get(analysis_type, 0) + 1
        
        # Calculate success rate (assuming confidence > 0.7 is success)
        successful = sum(1 for a in ai_analyses if a.confidence_score and a.confidence_score > 0.7)
        success_rate = round((successful / len(ai_analyses) * 100) if ai_analyses else 0, 1)
        
        # Get popular services
        popular_services = sorted(analysis_types.items(), key=lambda x: x[1], reverse=True)[:5]
        popular_service_names = [s[0].replace('_', ' ').title() for s in popular_services]
        
        # Determine active services based on hospital type and plan
        active_services = len(analysis_types)
        
        # Get plan-based service count
        plan_services = {
            'free': 1,
            'pro': 3,
            'business': 6,
            'enterprise': 7,
            'super_admin': 8
        }
        
        hospital_plan = 'business'  # Default
        if hospital.type == 'general':
            hospital_plan = 'enterprise'
        elif hospital.type == 'specialty':
            hospital_plan = 'business'
        elif hospital.type == 'clinic':
            hospital_plan = 'pro'
        
        total_services = plan_services.get(hospital_plan, 7)
        
        return {
            'total_services': total_services,
            'active_services': active_services or 1,
            'usage_percentage': round((active_services / total_services * 100) if total_services > 0 else 0, 1),
            'total_queries': total_queries,
            'success_rate': success_rate,
            'popular_services': popular_service_names if popular_service_names else ['AI Chat Assistant'],
            'analysis_types': analysis_types,
            'hospital_name': hospital.name,
            'hospital_type': hospital.type or 'general',
            'plan_used': hospital_plan,
            'time_range': {
                'start': start_date.isoformat() if start_date else None,
                'end': end_date.isoformat() if end_date else None
            },
            'timestamp': datetime.utcnow().isoformat()
        }
        
    except Exception as e:
        logger.error(f"Error calculating AI usage: {e}")
        return {
            'total_services': 7,
            'active_services': 0,
            'usage_percentage': 0,
            'total_queries': 0,
            'success_rate': 0,
            'popular_services': [],
            'error': str(e)
        }


def calculate_infection_rates(hospitals: List[Hospital], start_date: datetime, end_date: datetime, healthcare_context: Optional[Dict] = None) -> Dict[str, Any]:
    """
    Calculate infection rates across hospitals with actual database queries
    
    Args:
        hospitals: List of hospitals to analyze
        start_date: Start date for analysis
        end_date: End date for analysis
        healthcare_context: Healthcare context with facility info
    
    Returns:
        Dict containing infection rate statistics
    """
    try:
        facility = healthcare_context.get('facility', 'Unknown') if healthcare_context else 'Unknown'
        logger.info(f"Calculating infection rates for {len(hospitals)} hospitals - Facility: {facility}")
        
        hospital_ids = [h.id for h in hospitals]
        
        if not hospital_ids:
            return {
                'overall': 0,
                'compliance': 0,
                'trend': 'unknown',
                'by_hospital': [],
                'by_department': [],
                'message': 'No hospitals provided'
            }
        
        # Try to get actual infection data if InfectionControl model exists
        try:
            # Check if InfectionControl model exists
            from models import InfectionControl
            
            # Get average infection rate
            avg_rate_result = db.session.query(
                func.avg(InfectionControl.infection_rate)
            ).filter(
                InfectionControl.hospital_id.in_(hospital_ids),
                InfectionControl.recorded_date.between(start_date, end_date)
            ).scalar()
            
            # Get compliance data
            compliance_result = db.session.query(
                func.avg(InfectionControl.compliance_score)
            ).filter(
                InfectionControl.hospital_id.in_(hospital_ids),
                InfectionControl.recorded_date.between(start_date, end_date)
            ).scalar()
            
            # Get rates by hospital
            hospital_rates = db.session.query(
                InfectionControl.hospital_id,
                func.avg(InfectionControl.infection_rate).label('avg_rate')
            ).filter(
                InfectionControl.hospital_id.in_(hospital_ids),
                InfectionControl.recorded_date.between(start_date, end_date)
            ).group_by(InfectionControl.hospital_id).all()
            
            # Get rates by department
            department_rates = db.session.query(
                InfectionControl.department,
                func.avg(InfectionControl.infection_rate).label('avg_rate')
            ).filter(
                InfectionControl.hospital_id.in_(hospital_ids),
                InfectionControl.recorded_date.between(start_date, end_date)
            ).group_by(InfectionControl.department).all()
            
            # Calculate trend
            trend = 'stable'
            if len(hospital_rates) > 1:
                rates = [r.avg_rate for r in hospital_rates if r.avg_rate is not None]
                if rates and len(rates) > 1:
                    first_rate = rates[0] if rates else 0
                    last_rate = rates[-1] if rates else 0
                    if last_rate > first_rate * 1.1:
                        trend = 'increasing'
                    elif last_rate < first_rate * 0.9:
                        trend = 'decreasing'
            
            return {
                'overall': round(avg_rate_result or 0, 2),
                'compliance': round(compliance_result or 0, 2),
                'trend': trend,
                'by_hospital': [
                    {
                        'hospital_id': r.hospital_id,
                        'hospital_name': next((h.name for h in hospitals if h.id == r.hospital_id), 'Unknown'),
                        'rate': round(r.avg_rate or 0, 2)
                    }
                    for r in hospital_rates if r.avg_rate is not None
                ],
                'by_department': [
                    {
                        'department': r.department,
                        'rate': round(r.avg_rate or 0, 2)
                    }
                    for r in department_rates if r.avg_rate is not None
                ],
                'timestamp': datetime.utcnow().isoformat()
            }
            
        except (ImportError, AttributeError):
            # Fallback to sample data if InfectionControl model doesn't exist
            logger.warning("InfectionControl model not found, using sample data")
            return _get_sample_infection_rates(hospitals)
            
    except Exception as e:
        logger.error(f"Error calculating infection rates: {e}")
        return _get_sample_infection_rates(hospitals)


def calculate_patient_satisfaction(hospitals: List[Hospital], start_date: datetime, end_date: datetime, healthcare_context: Optional[Dict] = None) -> Dict[str, Any]:
    """
    Calculate patient satisfaction scores with actual database queries
    
    Args:
        hospitals: List of hospitals to analyze
        start_date: Start date for analysis
        end_date: End date for analysis
        healthcare_context: Healthcare context with facility info
    
    Returns:
        Dict containing patient satisfaction statistics
    """
    try:
        facility = healthcare_context.get('facility', 'Unknown') if healthcare_context else 'Unknown'
        logger.info(f"Calculating patient satisfaction for {len(hospitals)} hospitals - Facility: {facility}")
        
        hospital_ids = [h.id for h in hospitals]
        
        if not hospital_ids:
            return {
                'average': 0,
                'trend': 'unknown',
                'by_hospital': [],
                'by_category': [],
                'message': 'No hospitals provided'
            }
        
        # Try to get actual satisfaction data if PatientSatisfaction model exists
        try:
            from models import PatientSatisfaction
            
            # Get average satisfaction
            avg_result = db.session.query(
                func.avg(PatientSatisfaction.score)
            ).filter(
                PatientSatisfaction.hospital_id.in_(hospital_ids),
                PatientSatisfaction.created_at.between(start_date, end_date)
            ).scalar()
            
            # Get scores by hospital
            hospital_scores = db.session.query(
                PatientSatisfaction.hospital_id,
                func.avg(PatientSatisfaction.score).label('avg_score')
            ).filter(
                PatientSatisfaction.hospital_id.in_(hospital_ids),
                PatientSatisfaction.created_at.between(start_date, end_date)
            ).group_by(PatientSatisfaction.hospital_id).all()
            
            # Get scores by category
            category_scores = db.session.query(
                PatientSatisfaction.category,
                func.avg(PatientSatisfaction.score).label('avg_score')
            ).filter(
                PatientSatisfaction.hospital_id.in_(hospital_ids),
                PatientSatisfaction.created_at.between(start_date, end_date)
            ).group_by(PatientSatisfaction.category).all()
            
            # Calculate trend
            trend = 'stable'
            if len(hospital_scores) > 1:
                scores = [s.avg_score for s in hospital_scores if s.avg_score is not None]
                if scores and len(scores) > 1:
                    first_score = scores[0] if scores else 0
                    last_score = scores[-1] if scores else 0
                    if last_score > first_score * 1.05:
                        trend = 'improving'
                    elif last_score < first_score * 0.95:
                        trend = 'declining'
            
            return {
                'average': round(avg_result or 0, 1),
                'trend': trend,
                'by_hospital': [
                    {
                        'hospital_id': r.hospital_id,
                        'hospital_name': next((h.name for h in hospitals if h.id == r.hospital_id), 'Unknown'),
                        'score': round(r.avg_score or 0, 1)
                    }
                    for r in hospital_scores if r.avg_score is not None
                ],
                'by_category': [
                    {
                        'category': r.category,
                        'score': round(r.avg_score or 0, 1)
                    }
                    for r in category_scores if r.avg_score is not None
                ],
                'timestamp': datetime.utcnow().isoformat()
            }
            
        except (ImportError, AttributeError):
            # Fallback to sample data if PatientSatisfaction model doesn't exist
            logger.warning("PatientSatisfaction model not found, using sample data")
            return _get_sample_patient_satisfaction(hospitals)
            
    except Exception as e:
        logger.error(f"Error calculating patient satisfaction: {e}")
        return _get_sample_patient_satisfaction(hospitals)


def get_recent_incidents(department_id: int, start_date: datetime, end_date: datetime, healthcare_context: Optional[Dict] = None) -> Dict[str, Any]:
    """
    Get recent incidents for a department with actual database queries
    
    Args:
        department_id: ID of the department
        start_date: Start date for incidents
        end_date: End date for incidents
        healthcare_context: Healthcare context with facility info
    
    Returns:
        Dict containing incident statistics
    """
    try:
        facility = healthcare_context.get('facility', 'Unknown') if healthcare_context else 'Unknown'
        logger.info(f"Getting incidents for department {department_id} - Facility: {facility}")
        
        # Get department
        department = Department.query.get(department_id)
        if not department:
            return {
                'total': 0,
                'resolved': 0,
                'pending': 0,
                'trend': 'stable',
                'message': 'Department not found'
            }
        
        # Try to get actual incident data if Incident model exists
        try:
            from models import Incident
            
            # Get all incidents in date range
            incidents = Incident.query.filter(
                Incident.department_id == department_id,
                Incident.created_at.between(start_date, end_date)
            ).all()
            
            # Count by status
            total = len(incidents)
            resolved = sum(1 for i in incidents if i.status in ['resolved', 'closed', 'completed'])
            pending = total - resolved
            
            # Calculate trend by comparing to previous period
            previous_start = start_date - (end_date - start_date)
            previous_incidents = Incident.query.filter(
                Incident.department_id == department_id,
                Incident.created_at.between(previous_start, start_date)
            ).count()
            
            trend = 'stable'
            if previous_incidents > 0:
                change = ((total - previous_incidents) / previous_incidents) * 100
                if change > 20:
                    trend = 'increasing'
                elif change < -20:
                    trend = 'decreasing'
            
            # Get recent incidents details
            recent_incidents = Incident.query.filter(
                Incident.department_id == department_id
            ).order_by(Incident.created_at.desc()).limit(5).all()
            
            return {
                'total': total,
                'resolved': resolved,
                'pending': pending,
                'trend': trend,
                'previous_period_count': previous_incidents,
                'recent_incidents': [
                    {
                        'id': i.id,
                        'title': i.title,
                        'status': i.status,
                        'severity': i.severity,
                        'created_at': i.created_at.isoformat() if i.created_at else None
                    }
                    for i in recent_incidents
                ],
                'department_name': department.name,
                'time_range': {
                    'start': start_date.isoformat() if start_date else None,
                    'end': end_date.isoformat() if end_date else None
                },
                'timestamp': datetime.utcnow().isoformat()
            }
            
        except (ImportError, AttributeError):
            # Fallback to sample data if Incident model doesn't exist
            logger.warning("Incident model not found, using sample data")
            return _get_sample_incidents(department)
            
    except Exception as e:
        logger.error(f"Error getting incidents: {e}")
        return _get_sample_incidents(department)


