@app.route('/api/hospital/<int:hospital_id>/adverse-events', methods=['GET', 'POST', 'OPTIONS'])
@cross_origin()
@jwt_required
def hospital_adverse_events(hospital_id):
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        
        # ✅ Use the proper access function
        if not has_hospital_access(current_user, hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED'
            }), 403
        
        from models import AdverseEvent
        import time
        
        if request.method == 'GET':
            events = AdverseEvent.query.filter_by(hospital_id=hospital_id).all()
            
            return jsonify({
                'success': True,
                'data': [{
                    'id': e.id,
                    'event_number': e.event_number,
                    'type': e.type,
                    'severity': e.severity,
                    'department_id': e.department_id,
                    'hospital_id': e.hospital_id,
                    'patient_id': e.patient_id,
                    'description': e.description,
                    'status': e.status,
                    'event_date': e.event_date.isoformat() if e.event_date else None,
                    'reported_by': e.reported_by,
                    'root_cause': e.root_cause,
                    'corrective_actions': e.corrective_actions,
                    'preventive_measures': e.preventive_measures,
                    'resolved_date': e.resolved_date.isoformat() if e.resolved_date else None,
                    'created_at': e.created_at.isoformat() if e.created_at else None,
                    'updated_at': e.updated_at.isoformat() if e.updated_at else None,
                    'reporter_name': e.reporter.name if e.reporter else None
                } for e in events],
                'total': len(events)
            }), 200
        
        elif request.method == 'POST':
            data = request.get_json()
            
            event_number = f"AE-{hospital_id}-{int(time.time())}"
            
            event = AdverseEvent(
                event_number=event_number,
                type=data.get('type', ''),
                severity=data.get('severity', 'medium'),
                department_id=data.get('department_id'),
                hospital_id=hospital_id,
                patient_id=data.get('patient_id'),
                description=data.get('description', ''),
                status=data.get('status', 'Under Investigation'),
                event_date=datetime.utcnow(),
                reported_by=current_user.id,
                root_cause=data.get('root_cause', ''),
                corrective_actions=data.get('corrective_actions', ''),
                preventive_measures=data.get('preventive_measures', ''),
                resolved_date=data.get('resolved_date'),
                created_at=datetime.utcnow(),
                updated_at=datetime.utcnow()
            )
            
            db.session.add(event)
            db.session.commit()
            
            return jsonify({
                'success': True,
                'message': 'Adverse event created successfully',
                'data': {
                    'id': event.id,
                    'event_number': event.event_number,
                    'type': event.type,
                    'severity': event.severity,
                    'status': event.status
                }
            }), 201
            
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Adverse events error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


