@app.route('/api/hospital/<int:hospital_id>/infection-control/<int:protocol_id>', methods=['GET', 'PUT', 'DELETE', 'OPTIONS'])
@cross_origin()
@jwt_required
def hospital_infection_control_detail(hospital_id, protocol_id):
    """Get, update, or delete an infection control protocol"""
    if request.method == 'OPTIONS':
        return '', 200
    
    try:
        current_user = request.user
        
        if not has_hospital_access(current_user, hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'ACCESS_DENIED'
            }), 403
        
        from models import InfectionControlProtocol
        
        protocol = InfectionControlProtocol.query.get(protocol_id)
        if not protocol:
            return jsonify({
                'success': False,
                'error': 'Protocol not found',
                'code': 'NOT_FOUND'
            }), 404
        
        if request.method == 'GET':
            return jsonify({
                'success': True,
                'data': {
                    'id': protocol.id,
                    'name': protocol.name,
                    'department_id': protocol.department_id,
                    'standard_precautions': protocol.standard_precautions,
                    'transmission_precautions': protocol.transmission_precautions,
                    'ppe_requirements': protocol.ppe_requirements,
                    'cleaning_procedures': protocol.cleaning_procedures,
                    'compliance_rate': protocol.compliance_rate,
                    'last_audit_date': protocol.last_audit_date.isoformat() if protocol.last_audit_date else None,
                    'user_id': protocol.user_id,
                    'created_at': protocol.created_at.isoformat() if protocol.created_at else None,
                    'updated_at': protocol.updated_at.isoformat() if protocol.updated_at else None
                }
            }), 200
        
        elif request.method == 'PUT':
            data = request.get_json()
            
            if 'name' in data:
                protocol.name = data['name']
            if 'standard_precautions' in data:
                protocol.standard_precautions = data['standard_precautions']
            if 'transmission_precautions' in data:
                protocol.transmission_precautions = data['transmission_precautions']
            if 'ppe_requirements' in data:
                protocol.ppe_requirements = data['ppe_requirements']
            if 'cleaning_procedures' in data:
                protocol.cleaning_procedures = data['cleaning_procedures']
            if 'compliance_rate' in data:
                protocol.compliance_rate = data['compliance_rate']
            if 'last_audit_date' in data:
                protocol.last_audit_date = data['last_audit_date']
            
            protocol.updated_at = datetime.utcnow()
            
            db.session.commit()
            
            return jsonify({
                'success': True,
                'message': 'Protocol updated successfully',
                'data': {
                    'id': protocol.id,
                    'name': protocol.name,
                    'compliance_rate': protocol.compliance_rate
                }
            }), 200
        
        elif request.method == 'DELETE':
            db.session.delete(protocol)
            db.session.commit()
            
            return jsonify({
                'success': True,
                'message': 'Protocol deleted successfully'
            }), 200
            
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Infection control detail error: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

