def identify_risk_factors(patient_data: Dict[str, Any], healthcare_context: Optional[Dict] = None) -> Dict[str, Any]:
    """
    Identify risk factors from patient data with healthcare context
    
    Args:
        patient_data: Dictionary containing patient information
        healthcare_context: Healthcare context with facility info
    
    Returns:
        Dict containing risk factors and additional analysis
    """
    try:
        facility = healthcare_context.get('facility', 'Unknown') if healthcare_context else 'Unknown'
        logger.info(f"Identifying risk factors for patient - Facility: {facility}")
        
        risk_factors = []
        risk_categories = {
            'high': [],
            'medium': [],
            'low': []
        }
        recommendations = []
        
        # Age-related risk factors
        age = patient_data.get('age', 0)
        if age > 0:
            if age > 65:
                risk_factors.append("Advanced age (65+)")
                risk_categories['high'].append("Advanced age")
                recommendations.append("Schedule comprehensive geriatric assessment")
            elif age > 50:
                risk_factors.append("Age-related risk factors (50+)")
                risk_categories['medium'].append("Middle age")
                recommendations.append("Consider age-appropriate screenings")
        
        # Smoking status
        smoking_status = patient_data.get('smoker', False)
        if smoking_status:
            risk_factors.append("Active smoking")
            risk_categories['high'].append("Smoking")
            recommendations.append("Refer to smoking cessation program")
        elif patient_data.get('former_smoker', False):
            risk_factors.append("Former smoker")
            risk_categories['medium'].append("Former smoking history")
            recommendations.append("Monitor for smoking-related conditions")
        
        # Family history
        family_history = patient_data.get('family_history', {})
        if family_history:
            if isinstance(family_history, dict):
                conditions = family_history.get('conditions', [])
                if conditions:
                    risk_factors.append(f"Family history of: {', '.join(conditions[:3])}")
                    risk_categories['high'].append("Family history")
                    recommendations.append("Genetic counseling recommended")
            elif isinstance(family_history, list):
                if family_history:
                    risk_factors.append(f"Family history of: {', '.join(family_history[:3])}")
                    risk_categories['high'].append("Family history")
                    recommendations.append("Genetic counseling recommended")
            else:
                risk_factors.append("Family history of conditions")
                risk_categories['medium'].append("Family history")
        
        # BMI
        bmi = patient_data.get('bmi', 0)
        if bmi > 0:
            if bmi > 30:
                risk_factors.append(f"Obesity (BMI: {bmi:.1f})")
                risk_categories['high'].append("Obesity")
                recommendations.append("Refer to nutrition and weight management program")
            elif bmi > 25:
                risk_factors.append(f"Overweight (BMI: {bmi:.1f})")
                risk_categories['medium'].append("Overweight")
                recommendations.append("Lifestyle modification counseling")
        
        # Blood pressure
        blood_pressure = patient_data.get('blood_pressure', {})
        if blood_pressure:
            systolic = blood_pressure.get('systolic', 0)
            diastolic = blood_pressure.get('diastolic', 0)
            
            if systolic > 140 or diastolic > 90:
                risk_factors.append(f"High blood pressure ({systolic}/{diastolic})")
                risk_categories['high'].append("Hypertension")
                recommendations.append("Monitor blood pressure regularly")
            elif systolic > 130 or diastolic > 80:
                risk_factors.append(f"Elevated blood pressure ({systolic}/{diastolic})")
                risk_categories['medium'].append("Pre-hypertension")
                recommendations.append("Lifestyle modifications recommended")
        
        # Cholesterol
        cholesterol = patient_data.get('cholesterol', {})
        if cholesterol:
            total = cholesterol.get('total', 0)
            ldl = cholesterol.get('ldl', 0)
            
            if total > 240 or ldl > 160:
                risk_factors.append(f"High cholesterol (Total: {total}, LDL: {ldl})")
                risk_categories['high'].append("Hyperlipidemia")
                recommendations.append("Lipid management program")
            elif total > 200 or ldl > 130:
                risk_factors.append(f"Elevated cholesterol (Total: {total}, LDL: {ldl})")
                risk_categories['medium'].append("Borderline high cholesterol")
                recommendations.append("Dietary modification recommended")
        
        # Diabetes risk
        blood_sugar = patient_data.get('blood_sugar', 0)
        if blood_sugar > 0:
            if blood_sugar > 200:
                risk_factors.append(f"High blood sugar ({blood_sugar} mg/dL)")
                risk_categories['high'].append("Diabetes risk")
                recommendations.append("Comprehensive diabetes evaluation")
            elif blood_sugar > 100:
                risk_factors.append(f"Elevated blood sugar ({blood_sugar} mg/dL)")
                risk_categories['medium'].append("Pre-diabetes")
                recommendations.append("Diabetes screening")
        
        # Physical activity
        if not patient_data.get('physically_active', True):
            risk_factors.append("Sedentary lifestyle")
            risk_categories['medium'].append("Physical inactivity")
            recommendations.append("Physical activity plan")
        
        # Alcohol consumption
        alcohol_consumption = patient_data.get('alcohol_consumption', 'none')
        if alcohol_consumption in ['heavy', 'excessive']:
            risk_factors.append(f"{alcohol_consumption.capitalize()} alcohol consumption")
            risk_categories['high'].append("Alcohol use disorder risk")
            recommendations.append("Alcohol counseling")
        elif alcohol_consumption in ['moderate', 'regular']:
            risk_factors.append("Regular alcohol consumption")
            risk_categories['low'].append("Moderate alcohol use")
        
        # Mental health
        mental_health = patient_data.get('mental_health', {})
        if mental_health:
            if mental_health.get('depression', False):
                risk_factors.append("Depression indicators")
                risk_categories['medium'].append("Depression")
                recommendations.append("Mental health evaluation")
            if mental_health.get('anxiety', False):
                risk_factors.append("Anxiety indicators")
                risk_categories['medium'].append("Anxiety")
                recommendations.append("Stress management program")
        
        # Medication adherence
        if not patient_data.get('medication_adherent', True):
            risk_factors.append("Medication non-adherence")
            risk_categories['high'].append("Medication non-adherence")
            recommendations.append("Medication management counseling")
        
        # Calculate risk score
        risk_score = calculate_risk_score(risk_categories)
        
        # Determine overall risk level
        overall_risk = 'low'
        if risk_categories['high']:
            overall_risk = 'high'
        elif risk_categories['medium']:
            overall_risk = 'medium'
        
        return {
            'risk_factors': risk_factors,
            'risk_categories': risk_categories,
            'overall_risk': overall_risk,
            'risk_score': risk_score,
            'recommendations': recommendations,
            'risk_factor_count': len(risk_factors),
            'high_risk_factors': len(risk_categories['high']),
            'medium_risk_factors': len(risk_categories['medium']),
            'low_risk_factors': len(risk_categories['low']),
            'timestamp': datetime.utcnow().isoformat(),
            'patient_info': {
                'age': age,
                'bmi': bmi,
                'smoking_status': smoking_status,
                'has_family_history': bool(family_history)
            }
        }
        
    except Exception as e:
        logger.error(f"Error identifying risk factors: {e}")
        return {
            'risk_factors': [],
            'error': str(e),
            'timestamp': datetime.utcnow().isoformat()
        }


def get_plan_hierarchy_index(plan: str) -> int:
    """
    Get index of plan in hierarchy
    
    Args:
        plan: Plan name (free, pro, business, enterprise, super_admin)
    
    Returns:
        Integer index in hierarchy (0-based)
    """
    hierarchy = ['free', 'pro', 'business', 'enterprise', 'super_admin']
    try:
        return hierarchy.index(plan.lower() if plan else 'free')
    except ValueError:
        return 0  # Default to free if unknown


def get_plan_distribution_for_users(users: List[User]) -> Dict[str, Any]:
    """
    Get plan distribution for a list of users
    
    Args:
        users: List of User objects
    
    Returns:
        Dict containing plan distribution statistics
    """
    try:
        plan_counts = {
            'free': 0,
            'pro': 0,
            'business': 0,
            'enterprise': 0,
            'super_admin': 0
        }
        
        for user in users:
            # Try multiple possible plan fields
            plan = getattr(user, 'subscription_plan', None)
            if not plan:
                plan = getattr(user, 'plan', None)
            if not plan:
                plan = getattr(user, 'user_type', None)
            if not plan:
                plan = 'free'
            
            # Normalize plan name
            plan = plan.lower()
            
            # Map any admin/owner roles to appropriate plans
            if plan in ['super_admin', 'platform_owner', 'system_team']:
                plan = 'super_admin'
            elif plan in ['enterprise', 'custom']:
                plan = 'enterprise'
            elif plan in ['business', 'business_pro']:
                plan = 'business'
            elif plan in ['pro', 'professional']:
                plan = 'pro'
            elif plan in ['free', 'basic', 'trial']:
                plan = 'free'
            
            if plan in plan_counts:
                plan_counts[plan] += 1
            else:
                plan_counts['free'] += 1
        
        total = sum(plan_counts.values())
        
        # Find most common plan
        most_common = 'free'
        max_count = 0
        for plan, count in plan_counts.items():
            if count > max_count:
                max_count = count
                most_common = plan
        
        return {
            'plan_counts': plan_counts,
            'total_users': total,
            'plan_percentages': {
                plan: round((count / total * 100) if total > 0 else 0, 1)
                for plan, count in plan_counts.items()
            },
            'most_common_plan': most_common if total > 0 else 'free',
            'has_premium_users': any(
                count > 0 for plan, count in plan_counts.items() 
                if plan in ['pro', 'business', 'enterprise', 'super_admin']
            ),
            'timestamp': datetime.utcnow().isoformat()
        }
        
    except Exception as e:
        logger.error(f"Error getting plan distribution: {e}")
        return {
            'plan_counts': {},
            'total_users': 0,
            'error': str(e)
        }


