def get_plan_upgrade_recommendations(hospital_id: int) -> Dict[str, Any]:
    """
    Get plan upgrade recommendations for a hospital
    
    Args:
        hospital_id: ID of the hospital
    
    Returns:
        Dict containing upgrade recommendations
    """
    try:
        users = User.query.filter_by(hospital_id=hospital_id).all()
        distribution = get_plan_distribution_for_users(users)
        
        recommendations = {
            'current_plan_distribution': distribution,
            'recommendations': [],
            'potential_savings': 0
        }
        
        # Check if many users are on free plan
        free_count = distribution['plan_counts'].get('free', 0)
        total = distribution['total_users']
        
        if free_count > 0 and total > 0:
            free_percentage = (free_count / total) * 100
            
            if free_percentage > 50:
                recommendations['recommendations'].append({
                    'type': 'upgrade',
                    'message': f'{free_percentage:.1f}% of users are on free plan. Consider upgrading to Pro for better features.',
                    'suggested_plan': 'pro',
                    'impact': 'high'
                })
        
        # Check if users are exceeding free limits
        pro_count = distribution['plan_counts'].get('pro', 0)
        business_count = distribution['plan_counts'].get('business', 0)
        
        if pro_count > 0 and business_count == 0:
            recommendations['recommendations'].append({
                'type': 'optimization',
                'message': 'Multiple Pro users detected. Consider Business plan for team collaboration.',
                'suggested_plan': 'business',
                'impact': 'medium'
            })
        
        # Calculate potential savings
        # Assuming $10/user/month savings with bulk pricing
        if total > 5:
            savings = total * 10 * 12  # Annual savings
            recommendations['potential_savings'] = savings
            recommendations['recommendations'].append({
                'type': 'bulk_savings',
                'message': f'With {total} users, you could save up to ${savings:,.0f} annually with Enterprise plan.',
                'suggested_plan': 'enterprise',
                'impact': 'high'
            })
        
        return recommendations
        
    except Exception as e:
        logger.error(f"Error getting upgrade recommendations: {e}")
        return {
            'error': str(e),
            'recommendations': []
        }



def get_hospital_ai_usage_stats(hospital_id: int, healthcare_context: Optional[Dict] = None) -> Dict[str, Any]:
    """
    Get AI usage statistics for a hospital
    
    Args:
        hospital_id: ID of the hospital
        healthcare_context: Healthcare context with facility info
    
    Returns:
        Dict containing AI usage statistics
    """
    try:
        facility = healthcare_context.get('facility', 'Unknown') if healthcare_context else 'Unknown'
        logger.info(f"Getting AI usage stats for hospital {hospital_id} - Facility: {facility}")
        
        # Get AI analysis records
        ai_analyses = MedicalAnalysis.query.filter_by(hospital_id=hospital_id).all()
        
        # Get AI chat records
        ai_chats = MedicalChat.query.filter_by(hospital_id=hospital_id).all() if hasattr(MedicalChat, '__tablename__') else []
        
        # Count by analysis type
        analysis_types = {}
        for analysis in ai_analyses:
            analysis_type = analysis.analysis_type or 'unknown'
            analysis_types[analysis_type] = analysis_types.get(analysis_type, 0) + 1
        
        # Calculate usage metrics
        total_analyses = len(ai_analyses)
        total_chats = len(ai_chats)
        
        # Calculate average confidence
        avg_confidence = 0
        if total_analyses > 0:
            confidences = [a.confidence_score for a in ai_analyses if a.confidence_score is not None]
            avg_confidence = round(sum(confidences) / len(confidences), 2) if confidences else 0
        
        return {
            'total_analyses': total_analyses,
            'total_chats': total_chats,
            'analysis_types': analysis_types,
            'avg_confidence': avg_confidence,
            'most_used_type': max(analysis_types, key=analysis_types.get) if analysis_types else 'none',
            'timestamp': datetime.utcnow().isoformat()
        }
        
    except Exception as e:
        logger.error(f"Error getting AI usage stats: {e}")
        return {
            'total_analyses': 0,
            'total_chats': 0,
            'error': str(e)
        }


def calculate_risk_score(risk_categories: Dict[str, List[str]]) -> int:
    """
    Calculate risk score based on risk categories
    
    Args:
        risk_categories: Dictionary with high, medium, low risk categories
    
    Returns:
        Integer risk score (0-100)
    """
    # Weighted scoring
    high_weight = 10
    medium_weight = 5
    low_weight = 2
    
    high_count = len(risk_categories.get('high', []))
    medium_count = len(risk_categories.get('medium', []))
    low_count = len(risk_categories.get('low', []))
    
    raw_score = (high_count * high_weight) + (medium_count * medium_weight) + (low_count * low_weight)
    
    # Normalize to 0-100 scale
    max_possible = 100
    min_possible = 0
    
    # Cap at 100
    return min(raw_score, 100)


def get_user_engagement(hospital_id: int, healthcare_context: Optional[Dict] = None) -> float:
    """
    Calculate user engagement percentage for a hospital
    
    Args:
        hospital_id: ID of the hospital
        healthcare_context: Healthcare context with facility info
    
    Returns:
        Float percentage (0-100)
    """
    try:
        # Get total users in hospital
        total_users = User.query.filter_by(hospital_id=hospital_id).count()
        
        if total_users == 0:
            return 0.0
        
        # Get users active in last 30 days
        thirty_days_ago = datetime.utcnow() - timedelta(days=30)
        active_users = User.query.filter(
            User.hospital_id == hospital_id,
            User.last_login >= thirty_days_ago
        ).count()
        
        return round((active_users / total_users) * 100, 1)
        
    except Exception as e:
        logger.error(f"Error calculating user engagement: {e}")
        return 85.5  # Default sample value


