def get_risk_score_for_hospital(hospital_id: int) -> int:
    """
    Calculate risk score for a hospital based on various metrics
    
    Args:
        hospital_id: ID of the hospital
    
    Returns:
        Integer risk score (0-100)
    """
    try:
        risk_categories = {
            'high': [],
            'medium': [],
            'low': []
        }
        
        # Get risk assessments
        assessments = RiskAssessment.query.filter_by(hospital_id=hospital_id).all()
        
        for assessment in assessments:
            # Check assessment overall risk level
            if assessment.overall_risk_level in ['critical', 'high']:
                risk_categories['high'].append(f"assessment_{assessment.id}")
            elif assessment.overall_risk_level == 'medium':
                risk_categories['medium'].append(f"assessment_{assessment.id}")
            elif assessment.overall_risk_level in ['low', 'negligible']:
                risk_categories['low'].append(f"assessment_{assessment.id}")
            
            # Get items for this assessment
            items = RiskAssessmentItem.query.filter_by(assessment_id=assessment.id).all()
            
            for item in items:
                if item.risk_level in ['critical', 'high', 'extreme']:
                    risk_categories['high'].append(f"item_{item.id}")
                elif item.risk_level == 'medium':
                    risk_categories['medium'].append(f"item_{item.id}")
                elif item.risk_level in ['low', 'negligible']:
                    risk_categories['low'].append(f"item_{item.id}")
        
        return calculate_risk_score(risk_categories)
        
    except Exception as e:
        logger.error(f"Error calculating risk score for hospital {hospital_id}: {e}")
        return 0


