def get_engagement_trend(hospital_id: int, days: int = 30) -> List[Dict]:
    """
    Get user engagement trend over time
    
    Args:
        hospital_id: ID of the hospital
        days: Number of days to analyze
    
    Returns:
        List of daily engagement data
    """
    try:
        trend_data = []
        end_date = datetime.utcnow()
        start_date = end_date - timedelta(days=days)
        
        for i in range(days):
            date = start_date + timedelta(days=i)
            next_date = date + timedelta(days=1)
            
            # Count users with sessions on this day using UserSession
            sessions = UserSession.query.filter(
                UserSession.user_id.in_(
                    db.session.query(User.id).filter(User.hospital_id == hospital_id)
                ),
                UserSession.login_time >= date,
                UserSession.login_time < next_date,
                UserSession.is_active == True
            ).count()
            
            # Also count users with last_login on this day
            logins = User.query.filter(
                User.hospital_id == hospital_id,
                User.last_login >= date,
                User.last_login < next_date
            ).count()
            
            active_count = max(sessions, logins)
            
            trend_data.append({
                'date': date.strftime('%Y-%m-%d'),
                'active_users': active_count
            })
        
        return trend_data
        
    except Exception as e:
        logger.error(f"Error getting engagement trend: {e}")
        return []


