def calculate_roi_analysis(hospital_id: int) -> Dict[str, float]:
    """
    Calculate ROI analysis for AI investments
    
    Args:
        hospital_id: ID of the hospital
    
    Returns:
        Dictionary with ROI metrics
    """
    try:
        # Get AI usage metrics from MedicalAnalysis via User join
        total_analyses = MedicalAnalysis.query.join(
            User, MedicalAnalysis.user_id == User.id
        ).filter(User.hospital_id == hospital_id).count()
        
        # Calculate estimated savings
        time_saved_hours = total_analyses * 0.25  # 15 minutes = 0.25 hours
        cost_saved_dollars = time_saved_hours * 50  # $50 per hour
        
        estimated_investment = 1000  # Base investment
        
        if estimated_investment > 0:
            roi_percentage = ((cost_saved_dollars - estimated_investment) / estimated_investment) * 100
        else:
            roi_percentage = 0
        
        total_users = User.query.filter_by(hospital_id=hospital_id).count()
        productivity_gain = (time_saved_hours / (total_users * 40)) * 100 if total_users > 0 else 0
        
        return {
            'roi_percentage': round(roi_percentage, 1),
            'time_saved_hours': round(time_saved_hours, 1),
            'cost_saved_dollars': round(cost_saved_dollars, 2),
            'productivity_gain': round(productivity_gain, 1),
            'total_analyses': total_analyses
        }
    except Exception as e:
        logger.error(f"Error calculating ROI: {e}")
        return {
            'roi_percentage': 0,
            'time_saved_hours': 0,
            'cost_saved_dollars': 0,
            'productivity_gain': 0,
            'total_analyses': 0
        }


# ============================================
# HELPERS
# ============================================

def format_size(bytes: int) -> str:
    """
    Format bytes to human readable string
    
    Args:
        bytes: Number of bytes
    
    Returns:
        Formatted string (e.g., "2.5 GB")
    """
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if bytes < 1024.0:
            return f"{bytes:.1f} {unit}"
        bytes /= 1024.0
    return f"{bytes:.1f} PB"


