def get_analytics_cache(key):
    """Get data from analytics cache"""
    try:
        with app.app_context():
            cache_entry = AnalyticsCache.query.filter_by(
                cache_key=key
            ).filter(AnalyticsCache.expires_at > datetime.utcnow()).first()
            
            if cache_entry:
                return cache_entry.data
    except Exception as e:
        logger.error(f"Error getting analytics cache: {e}")
    return None

def set_analytics_cache(key, data, ttl_minutes=5):
    """Set data in analytics cache"""
    try:
        with app.app_context():
            expires_at = datetime.utcnow() + timedelta(minutes=ttl_minutes)
            
            # Update or create cache entry
            cache_entry = AnalyticsCache.query.filter_by(cache_key=key).first()
            if cache_entry:
                cache_entry.data = data
                cache_entry.expires_at = expires_at
            else:
                cache_entry = AnalyticsCache(
                    cache_key=key,
                    data=data,
                    expires_at=expires_at
                )
                db.session.add(cache_entry)
            
            db.session.commit()
    except Exception as e:
        logger.error(f"Error setting analytics cache: {e}")

def clear_analytics_cache(key=None):
    """Clear analytics cache"""
    try:
        with app.app_context():
            if key:
                AnalyticsCache.query.filter_by(cache_key=key).delete()
            else:
                # Clear expired cache entries
                AnalyticsCache.query.filter(
                    AnalyticsCache.expires_at <= datetime.utcnow()
                ).delete()
            
            db.session.commit()
    except Exception as e:
        logger.error(f"Error clearing analytics cache: {e}")



def get_risk_analytics_data(user, config):
    """Get risk analytics data for export"""
    try:
        # Query risk data based on user's permissions
        time_range = config.get('time_range', '30days')
        days = int(time_range.replace('days', '')) if 'days' in time_range else 30
        cutoff_date = datetime.utcnow() - timedelta(days=days)
        
        data = []
        
        # Get risk assessments for user's hospital
        if user.hospital_id:
            risk_assessments = RiskAssessment.query.filter(
                RiskAssessment.hospital_id == user.hospital_id,
                RiskAssessment.assessed_at >= cutoff_date
            ).all()
            
            for ra in risk_assessments:
                data.append({
                    'Date': ra.assessed_at.strftime('%Y-%m-%d'),
                    'Department': ra.department,
                    'Risk_Score': ra.risk_score,
                    'Risk_Level': ra.risk_level,
                    'Category': ra.category,
                    'Assessed_By': User.query.get(ra.assessed_by).name if ra.assessed_by else '',
                    'Notes': ra.notes or ''
                })
        
        return data
        
    except Exception as e:
        logger.error(f"Error getting risk analytics data: {e}")
        return []

def get_dashboard_data(user, config):
    """Get comprehensive dashboard data"""
    cache_key = f"dashboard:{user.id}:{json.dumps(config, sort_keys=True)}"
    
    # Check cache
    cached = get_analytics_cache(cache_key)
    if cached:
        return cached
    
    # Build dashboard data
    dashboard_data = {
        'overview': get_overview_stats(user),
        'trends': get_trends_data(user, config.get('time_range', '30days')),
        'risk_distribution': get_risk_distribution(user),
        'compliance_scores': get_compliance_scores(user),
        'department_stats': get_department_stats(user),
        'recent_activity': get_recent_activity(user)
    }
    
    # Cache for 5 minutes
    set_analytics_cache(cache_key, dashboard_data, 5)
    
    return dashboard_data

def get_overview_stats(user):
    """Get overview statistics"""
    try:
        # Get data from existing models
        stats = {
            'total_incidents': 0,
            'resolved_incidents': 0,
            'compliance_rate': 0,
            'risk_score': 0,
            'active_alerts': 0,
            'training_completion': 0
        }
        
        # Query based on user's hospital
        if user.hospital_id:
            # Get incident stats
            incidents = PatientSafetyIncident.query.filter_by(
                hospital_id=user.hospital_id
            ).all()
            
            stats['total_incidents'] = len(incidents)
            stats['resolved_incidents'] = len([i for i in incidents if i.status == 'resolved'])
            
            # Get training completion
            training_records = TrainingRecord.query.filter_by(
                hospital_id=user.hospital_id
            ).all()
            
            if training_records:
                completed = len([t for t in training_records if t.status == 'completed'])
                stats['training_completion'] = round((completed / len(training_records)) * 100, 1)
        
        return stats
        
    except Exception as e:
        logger.error(f"Error getting overview stats: {e}")
        return {}
    

