@app.route('/api/analytics/exports/<int:export_id>/status', methods=['GET'])
@jwt_required
def get_export_analytics_status(export_id):
    """Get export status with JWT auth - Plan check bypassed for super admin"""
    try:
        export = AnalyticsExport.query.get(export_id)
        
        if not export:
            return jsonify({
                'success': False, 
                'error': 'Export not found',
                'code': 'EXPORT_NOT_FOUND'
            }), 404
        
        # Check if user can access this export
        if export.user_id != request.user.id and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Access denied to this export',
                'code': 'EXPORT_ACCESS_DENIED',
                'suggestion': 'You can only access your own exports'
            }), 403
        
        export_data = {
            'id': export.id,
            'user_id': export.user_id,
            'export_type': export.export_type,
            'filename': export.filename,
            'analytics_types': export.analytics_types,
            'date_range': export.date_range,
            'file_size': export.file_size,
            'status': export.status,
            'created_at': export.created_at.isoformat() if export.created_at else None,
            'completed_at': export.completed_at.isoformat() if export.completed_at else None,
            'downloaded_at': export.downloaded_at.isoformat() if export.downloaded_at else None,
            'download_url': f'/api/analytics/exports/{export.id}/download' if export.status == 'completed' else None,
            'plan_used': getattr(export, 'plan_used', 'enterprise' if request.is_system_team else request.effective_plan),
            'is_system_export': getattr(export, 'is_system_export', False)
        }
        
        # Add progress information for processing exports
        if export.status == 'processing':
            export_data['progress'] = get_export_progress(export.id)
            export_data['estimated_time'] = get_estimated_completion_time(export.id)
        
        return jsonify({
            'success': True,
            'export': export_data,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'exportAccess': 'owner' if export.user_id == request.user.id else 'system_team' if request.is_system_team else 'denied',
                'planCheckBypassed': request.is_system_team
            }
        })
        
    except Exception as e:
        logger.error(f"Error getting export status: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'EXPORT_STATUS_ERROR'
        }), 500

@app.route('/api/analytics/exports/<int:export_id>/download', methods=['GET'])
@jwt_required
def download_analytics1_export(export_id):
    """Download export file with JWT auth - Plan check bypassed for super admin"""
    try:
        # Bypass plan check only for super admin/system team
        if not request.is_system_team:
            # Apply plan check for regular users
            if 'data_export_download' not in request.plan_features:
                return jsonify({
                    'success': False,
                    'error': 'Export download not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE',
                    'required_plan': 'business',
                    'suggestion': 'Upgrade to Business or Enterprise plan for export downloads',
                    'current_plan': request.effective_plan
                }), 403
        
        export = AnalyticsExport.query.get(export_id)
        
        if not export:
            return jsonify({
                'success': False, 
                'error': 'Export not found',
                'code': 'EXPORT_NOT_FOUND'
            }), 404
        
        # Check export ownership or system team access
        if export.user_id != request.user.id and not request.is_system_team:
            return jsonify({
                'success': False,
                'error': 'Access denied to this export',
                'code': 'DOWNLOAD_ACCESS_DENIED',
                'suggestion': 'You can only download your own exports'
            }), 403
        
        if export.status != 'completed':
            return jsonify({
                'success': False,
                'error': 'Export not ready for download',
                'status': export.status,
                'code': 'EXPORT_NOT_READY',
                'suggestion': 'Check export status and try again later'
            }), 400
        
        if not export.file_path or not os.path.exists(export.file_path):
            return jsonify({
                'success': False, 
                'error': 'File not found',
                'code': 'FILE_NOT_FOUND',
                'suggestion': 'Export may have expired or been deleted'
            }), 404
        
        # Check file size limits (bypass for super admin)
        if os.path.exists(export.file_path) and not request.is_system_team:
            file_size = os.path.getsize(export.file_path)
            max_sizes = {
                'free': 1 * 1024 * 1024,  # 1MB
                'pro': 10 * 1024 * 1024,   # 10MB
                'business': 50 * 1024 * 1024,  # 50MB
                'enterprise': 100 * 1024 * 1024  # 100MB
            }
            
            max_allowed = max_sizes.get(request.effective_plan, 1 * 1024 * 1024)
            if file_size > max_allowed and request.effective_plan != 'enterprise':
                return jsonify({
                    'success': False,
                    'error': f'Export file too large for {request.effective_plan} plan',
                    'code': 'FILE_TOO_LARGE',
                    'file_size_mb': round(file_size / (1024 * 1024), 2),
                    'max_allowed_mb': round(max_allowed / (1024 * 1024), 2),
                    'suggestion': f'Upgrade to {get_next_plan(request.effective_plan)} plan for larger exports'
                }), 400
        
        # Update download tracking
        export.downloaded_at = datetime.utcnow()
        export.download_count = (export.download_count or 0) + 1
        
        # Track download by user
        if hasattr(export, 'downloaded_by'):
            downloaded_by = json.loads(export.downloaded_by) if export.downloaded_by else []
            downloaded_by.append({
                'user_id': request.user.id,
                'user_email': request.user.email,
                'downloaded_at': datetime.utcnow().isoformat(),
                'plan': request.effective_plan,
                'is_system_team': request.is_system_team
            })
            export.downloaded_by = json.dumps(downloaded_by)
        
        db.session.commit()
        
        # Log the download
        logger.info(f"Export downloaded by {request.user.email} (system_team: {request.is_system_team}): {export.filename}")
        
        return send_file(
            export.file_path,
            as_attachment=True,
            download_name=export.filename,
            mimetype=get_mime_type(export.export_type),
            max_age=0  # Disable caching for security
        )
        
    except Exception as e:
        logger.error(f"Error downloading export: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'DOWNLOAD_ERROR'
        }), 500


