@app.route('/api/analytics/compliance/trends', methods=['GET'])
@jwt_required
def get_compliance_analytics_trends():
    """Get compliance trends with JWT auth - Plan check bypassed for super admin"""
    try:
        # Bypass plan check only for super admin/system team
        if not request.is_system_team:
            # Apply plan check for regular users
            if 'compliance_trends' not in request.plan_features:
                return jsonify({
                    'success': False,
                    'error': 'Compliance trends not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE',
                    'required_plan': 'business',
                    'suggestion': 'Upgrade to Business or Enterprise plan for compliance trend analytics',
                    'current_plan': request.effective_plan
                }), 403
        
        department = request.args.get('department')
        months = request.args.get('months', 6, type=int)
        
        # Validate months parameter based on plan (super admin gets unlimited)
        if not request.is_system_team:
            max_months = {
                'free': 3,
                'pro': 12,
                'business': 24,
                'enterprise': 36
            }.get(request.effective_plan, 3)
            
            if months > max_months:
                months = max_months
        else:
            max_months = 'unlimited'  # Super admin has no limit
        
        # Generate trend data
        trends = {
            'department': department or 'All',
            'months': months,
            'data': [],
            'plan_limits': {
                'max_months': max_months,
                'trend_resolution': 'monthly' if request.is_system_team or request.effective_plan in ['business', 'enterprise'] else 'quarterly'
            }
        }
        
        # Generate data points based on plan
        for i in range(months, 0, -1):
            month_date = datetime.utcnow() - timedelta(days=30*i)
            
            data_point = {
                'month': month_date.strftime('%Y-%m'),
                'compliance_score': 75 + i * 3,
                'audits_completed': 2 + i,
                'issues_resolved': 5 + i * 2
            }
            
            # Add additional metrics for higher plans and super admin
            if request.is_system_team or request.effective_plan in ['business', 'enterprise']:
                data_point.update({
                    'regulatory_updates': i % 3,
                    'training_hours': 10 + i * 2,
                    'penalty_risk': max(0, 30 - i * 5)
                })
            
            trends['data'].append(data_point)
        
        # Add trend analysis for higher plans and super admin
        if request.is_system_team or request.effective_plan in ['business', 'enterprise']:
            trends['analysis'] = {
                'overall_trend': 'improving',
                'improvement_rate': '+3.2% per month',
                'predictive_outlook': 'positive',
                'key_drivers': ['training_completion', 'audit_frequency', 'issue_resolution']
            }
        
        return jsonify({
            'success': True,
            'data': trends,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'maxMonths': max_months,
                'trendMetrics': len(trends['data'][0]) if trends['data'] else 0,
                'analyticsDepth': 'basic' if request.effective_plan == 'free' and not request.is_system_team else 'standard' if request.effective_plan == 'pro' and not request.is_system_team else 'advanced',
                'planCheckBypassed': request.is_system_team
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching compliance trends: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'COMPLIANCE_TRENDS_ERROR'
        }), 500

