# Helper functions
def get_user_email(user_id):
    """Helper to get user email by ID"""
    try:
        user = User.query.get(user_id)
        if user:
            return user.email
        else:
            # Try to find by alternate ID
            user = User.query.filter_by(id=str(user_id)).first()
            if user:
                return user.email
            
            # Check if it's a legacy ID
            user = User.query.filter_by(legacy_id=str(user_id)).first() if hasattr(User, 'legacy_id') else None
            return user.email if user else "Unknown User"
    except Exception as e:
        logger.warning(f"Error getting user email for ID {user_id}: {str(e)}")
        return "Unknown User"

def get_hospital_plan_distribution(hospital_id):
    """Get plan distribution for hospital users"""
    try:
        users = User.query.filter_by(hospital_id=hospital_id).all()
        plan_dist = {}
        plan_hierarchy = ['free', 'basic', 'pro', 'enterprise', 'super_admin']
        
        for user in users:
            plan = user.get_effective_plan()
            plan_dist[plan] = plan_dist.get(plan, 0) + 1
        
        # Sort by plan hierarchy for better presentation
        sorted_dist = {}
        for plan_level in plan_hierarchy:
            if plan_level in plan_dist:
                sorted_dist[plan_level] = plan_dist[plan_level]
        
        # Add any other plans not in hierarchy
        for plan, count in plan_dist.items():
            if plan not in sorted_dist:
                sorted_dist[plan] = count
        
        return {
            'distribution': sorted_dist,
            'total_users': len(users),
            'premium_users': sum(count for plan, count in sorted_dist.items() if plan in ['basic', 'pro', 'enterprise']),
            'premium_percentage': round((sum(count for plan, count in sorted_dist.items() if plan in ['basic', 'pro', 'enterprise']) / len(users) * 100), 1) if users else 0
        }
    
    except Exception as e:
        logger.error(f"Error getting hospital plan distribution: {str(e)}")
        return {
            'distribution': {'free': 0},
            'total_users': 0,
            'premium_users': 0,
            'premium_percentage': 0
        }

def get_hospital_ai_usage_stats(hospital_id):
    """Get AI usage stats for hospital"""
    try:
        # Get AI requests for this hospital
        hospital_users = User.query.filter_by(hospital_id=hospital_id).all()
        user_ids = [user.id for user in hospital_users]
        
        # Get total AI requests
        total_requests = AIRequest.query.filter(AIRequest.user_id.in_(user_ids)).count() if user_ids else 0
        
        # Get most used service
        service_counts = {}
        ai_requests = AIRequest.query.filter(AIRequest.user_id.in_(user_ids)).all() if user_ids else []
        
        for request in ai_requests:
            service = request.request_type
            service_counts[service] = service_counts.get(service, 0) + 1
        
        most_used_service = max(service_counts.items(), key=lambda x: x[1])[0] if service_counts else "No AI Usage"
        
        # Calculate average processing time
        processing_times = [r.processing_time for r in ai_requests if r.processing_time]
        avg_processing_time = sum(processing_times) / len(processing_times) if processing_times else 0
        
        # Calculate success rate
        successful_requests = sum(1 for r in ai_requests if r.status == 'completed')
        success_rate = (successful_requests / len(ai_requests) * 100) if ai_requests else 0
        
        # Get recent activity
        seven_days_ago = datetime.utcnow() - timedelta(days=7)
        recent_requests = sum(1 for r in ai_requests if r.created_at >= seven_days_ago) if ai_requests else 0
        
        return {
            'total_ai_requests': total_requests,
            'most_used_service': most_used_service,
            'average_processing_time': round(avg_processing_time, 2),
            'success_rate': round(success_rate, 1),
            'recent_activity_7_days': recent_requests,
            'daily_average': round(recent_requests / 7, 1) if recent_requests > 0 else 0,
            'service_distribution': service_counts,
            'total_tokens_used': sum(r.tokens_used for r in ai_requests if r.tokens_used),
            'total_cost': sum(r.cost for r in ai_requests if r.cost)
        }
    
    except Exception as e:
        logger.error(f"Error getting hospital AI usage stats: {str(e)}")
        return {
            'total_ai_requests': 0,
            'most_used_service': 'AI Chat Assistant',
            'average_processing_time': 0,
            'success_rate': 0,
            'recent_activity_7_days': 0,
            'daily_average': 0,
            'service_distribution': {},
            'total_tokens_used': 0,
            'total_cost': 0
        }

def get_database_size():
    """Get database size"""
    try:
        # This is a simplified example. In production, you'd use database-specific queries.
        # For SQLite:
        if current_app.config.get('SQLALCHEMY_DATABASE_URI', '').startswith('sqlite'):
            import os
            db_path = current_app.config.get('SQLALCHEMY_DATABASE_URI').replace('sqlite:///', '')
            if os.path.exists(db_path):
                size_bytes = os.path.getsize(db_path)
                size_mb = size_bytes / (1024 * 1024)
                return f"{size_mb:.2f} MB"
        
        # For PostgreSQL (example)
        elif current_app.config.get('SQLALCHEMY_DATABASE_URI', '').startswith('postgresql'):
            # You would need proper PostgreSQL permissions for this query
            # result = db.session.execute("SELECT pg_database_size(current_database())").fetchone()
            # size_bytes = result[0] if result else 0
            size_mb = 245.6  # Placeholder
            return f"{size_mb:.1f} MB"
        
        # Default fallback
        return "Unknown"
    
    except Exception as e:
        logger.error(f"Error getting database size: {str(e)}")
        return "Unknown"

def get_active_users_count(hospital_id=None):
    """Get count of active users in last 7 days"""
    try:
        seven_days_ago = datetime.utcnow() - timedelta(days=7)
        
        # If hospital_id is provided, filter by hospital
        if hospital_id:
            hospital_users = User.query.filter_by(hospital_id=hospital_id).all()
            user_ids = [user.id for user in hospital_users]
            
            # Check for any activity from these users in the last 7 days
            active_users = set()
            
            # Check AI requests
            ai_activities = AIRequest.query.filter(
                AIRequest.user_id.in_(user_ids),
                AIRequest.created_at >= seven_days_ago
            ).all() if user_ids else []
            
            for activity in ai_activities:
                active_users.add(activity.user_id)
            
            # Check video analyses
            video_activities = VideoAnalysis.query.filter(
                VideoAnalysis.user_id.in_(user_ids),
                VideoAnalysis.analyzed_at >= seven_days_ago
            ).all() if user_ids else []
            
            for activity in video_activities:
                active_users.add(activity.user_id)
            
            # Check last_activity field
            active_from_last_activity = User.query.filter(
                User.id.in_(user_ids),
                User.last_activity >= seven_days_ago
            ).count() if user_ids else 0
            
            # Combine all methods
            total_active = max(len(active_users), active_from_last_activity)
            return total_active
        else:
            # Get all active users across system
            # Using last_activity field
            active_users = User.query.filter(
                User.last_activity >= seven_days_ago
            ).count()
            
            return active_users
    
    except Exception as e:
        logger.error(f"Error getting active users count: {str(e)}")
        return 0

def get_last_audit_date(hospital_id=None):
    """Get last audit date"""
    try:
        # Check if you have an AuditLog model
        if hasattr(db.Model, 'audit_logs'):
            from .models import AuditLog  # Adjust import as needed
            
            if hospital_id:
                # Get last audit for this hospital
                last_audit = AuditLog.query.filter_by(
                    hospital_id=hospital_id
                ).order_by(AuditLog.created_at.desc()).first()
            else:
                # Get last system audit
                last_audit = AuditLog.query.order_by(AuditLog.created_at.desc()).first()
            
            if last_audit and last_audit.created_at:
                return last_audit.created_at.isoformat()
        
        # Check in User activities
        if hospital_id:
            hospital_users = User.query.filter_by(hospital_id=hospital_id).all()
            user_ids = [user.id for user in hospital_users]
            
            # Get latest AI request
            latest_ai = AIRequest.query.filter(
                AIRequest.user_id.in_(user_ids)
            ).order_by(AIRequest.created_at.desc()).first() if user_ids else None
            
            if latest_ai:
                return latest_ai.created_at.isoformat()
        
        # Default to 3 days ago
        return (datetime.utcnow() - timedelta(days=3)).isoformat()
    
    except Exception as e:
        logger.error(f"Error getting last audit date: {str(e)}")
        return datetime.utcnow().isoformat()

def get_user_distribution_by_role(hospital_id=None):
    """Get user distribution by role"""
    try:
        if hospital_id:
            users = User.query.filter_by(hospital_id=hospital_id).all()
        else:
            users = User.query.all()
        
        role_dist = {}
        for user in users:
            # Use user_type field from your model
            role = user.user_type or 'unknown'
            if role == 'safetypro':
                role = 'safety_professional'  # Make it more readable
            role_dist[role] = role_dist.get(role, 0) + 1
        
        # Add percentage calculations
        total_users = len(users)
        role_dist_with_percent = {}
        for role, count in role_dist.items():
            percentage = (count / total_users * 100) if total_users > 0 else 0
            role_dist_with_percent[role] = {
                'count': count,
                'percentage': round(percentage, 1)
            }
        
        # Find most common role
        most_common_role = max(role_dist.items(), key=lambda x: x[1])[0] if role_dist else 'none'
        
        # Convert to readable format
        if most_common_role == 'safety_professional':
            most_common_role_display = 'Safety Professional'
        else:
            most_common_role_display = most_common_role.title()
        
        return {
            'distribution': role_dist_with_percent,
            'total_users': total_users,
            'most_common_role': most_common_role,
            'most_common_role_display': most_common_role_display
        }
    
    except Exception as e:
        logger.error(f"Error getting user distribution by role: {str(e)}")
        return {
            'distribution': {'unknown': {'count': 0, 'percentage': 0}},
            'total_users': 0,
            'most_common_role': 'unknown',
            'most_common_role_display': 'Unknown'
        }

def get_peak_usage_times(hospital_id=None):
    """Get peak usage times"""
    try:
        # Analyze AI request patterns
        if hospital_id:
            hospital_users = User.query.filter_by(hospital_id=hospital_id).all()
            user_ids = [user.id for user in hospital_users]
            ai_requests = AIRequest.query.filter(AIRequest.user_id.in_(user_ids)).all() if user_ids else []
        else:
            ai_requests = AIRequest.query.all()
        
        hour_counts = {}
        for request in ai_requests:
            if request.created_at:
                hour = request.created_at.hour
                hour_counts[hour] = hour_counts.get(hour, 0) + 1
        
        if not hour_counts:
            return {
                'morning_peak': '09:00-11:00',
                'afternoon_peak': '14:00-16:00',
                'evening_peak': '19:00-21:00',
                'data_points': 0
            }
        
        # Find peaks
        sorted_hours = sorted(hour_counts.items(), key=lambda x: x[1], reverse=True)
        
        # Group into time ranges
        morning = sum(count for hour, count in hour_counts.items() if 6 <= hour < 12)
        afternoon = sum(count for hour, count in hour_counts.items() if 12 <= hour < 18)
        evening = sum(count for hour, count in hour_counts.items() if 18 <= hour < 24)
        night = sum(count for hour, count in hour_counts.items() if 0 <= hour < 6)
        
        total_requests = sum(hour_counts.values())
        
        return {
            'morning_peak': '06:00-12:00' if morning > 0 else 'No data',
            'afternoon_peak': '12:00-18:00' if afternoon > 0 else 'No data',
            'evening_peak': '18:00-24:00' if evening > 0 else 'No data',
            'night_usage': '00:00-06:00' if night > 0 else 'No data',
            'peak_hour': f"{sorted_hours[0][0]:02d}:00" if sorted_hours else 'No data',
            'total_requests': total_requests,
            'hourly_distribution': hour_counts,
            'period_percentages': {
                'morning': round(morning / total_requests * 100, 1) if total_requests > 0 else 0,
                'afternoon': round(afternoon / total_requests * 100, 1) if total_requests > 0 else 0,
                'evening': round(evening / total_requests * 100, 1) if total_requests > 0 else 0,
                'night': round(night / total_requests * 100, 1) if total_requests > 0 else 0
            }
        }
    
    except Exception as e:
        logger.error(f"Error getting peak usage times: {str(e)}")
        return {
            'morning_peak': '09:00-11:00',
            'afternoon_peak': '14:00-16:00',
            'evening_peak': '19:00-21:00',
            'data_points': 0,
            'error': str(e)
        }

