def get_suspicious_activities(hospital_id=None):
    """Get suspicious activities in last 24 hours"""
    try:
        twenty_four_hours_ago = datetime.utcnow() - timedelta(hours=24)
        
        suspicious_count = 0
        suspicious_activities = []
        
        # Check for users with high activity rates
        if hospital_id:
            hospital_users = User.query.filter_by(hospital_id=hospital_id).all()
            
            for user in hospital_users:
                # Check if user has unusually high activity rate
                if user.activity_rate > 100:  # More than 100 activities per day
                    suspicious_count += 1
                    suspicious_activities.append({
                        'type': 'high_activity_rate',
                        'user_id': user.id,
                        'user_email': user.email,
                        'activity_rate': round(user.activity_rate, 1),
                        'threshold': 100,
                        'timeframe': '24h'
                    })
                
                # Check for high AI request usage
                ai_request_count = AIRequest.query.filter(
                    AIRequest.user_id == user.id,
                    AIRequest.created_at >= twenty_four_hours_ago
                ).count()
                
                if ai_request_count > 100:  # More than 100 AI requests in 24h
                    suspicious_count += 1
                    suspicious_activities.append({
                        'type': 'high_ai_usage',
                        'user_id': user.id,
                        'user_email': user.email,
                        'ai_requests': ai_request_count,
                        'threshold': 100,
                        'timeframe': '24h'
                    })
        
        return {
            'count': suspicious_count,
            'activities': suspicious_activities,
            'last_24_hours': True,
            'monitoring_active': True
        }
    
    except Exception as e:
        logger.error(f"Error getting suspicious activities: {str(e)}")
        return {
            'count': 0,
            'activities': [],
            'error': str(e)
        }

def calculate_roi_analysis(hospital_id):
    """Calculate ROI analysis for super admin"""
    try:
        # Get hospital data
        hospital = Hospital.query.get(hospital_id)
        if not hospital:
            return {
                'estimatedSavings': 0,
                'roiPercentage': 0,
                'paybackPeriod': 'N/A',
                'data_available': False
            }
        
        # Get hospital users
        users = User.query.filter_by(hospital_id=hospital_id).all()
        
        # Calculate costs based on subscription plans
        total_subscription_cost = 0
        plan_costs = {
            'free': 0,
            'basic': 49,
            'pro': 99,
            'enterprise': 299
        }
        
        for user in users:
            effective_plan = user.get_effective_plan()
            # Check if user is in trial
            if user.is_trial_active():
                cost = 0  # Trial is free
            else:
                cost = plan_costs.get(effective_plan, 0)
            
            # Adjust for billing cycle
            billing_multiplier = 1
            if hasattr(user, 'billing_cycle'):
                if user.billing_cycle == '6_month':
                    billing_multiplier = 0.9  # 10% discount for 6-month
                elif user.billing_cycle == '1_year':
                    billing_multiplier = 0.8  # 20% discount for 1-year
            
            total_subscription_cost += cost * billing_multiplier
        
        # Calculate AI usage costs
        ai_requests = AIRequest.query.filter(
            AIRequest.user_id.in_([u.id for u in users])
        ).all()
        total_ai_cost = sum(r.cost for r in ai_requests if r.cost)
        
        # Calculate estimated savings
        # Assume each AI request saves 15 minutes of staff time
        # at an average cost of $50/hour for medical staff
        time_saved_hours = len(ai_requests) * 0.25  # 15 minutes per request
        labor_cost_per_hour = 50
        estimated_savings = time_saved_hours * labor_cost_per_hour
        
        # Calculate ROI
        total_cost = total_subscription_cost + total_ai_cost
        roi_percentage = ((estimated_savings - total_cost) / total_cost * 100) if total_cost > 0 else 0
        
        # Calculate payback period (in months)
        monthly_cost = total_cost / 12 if total_cost > 0 else 0
        monthly_savings = estimated_savings / 12 if estimated_savings > 0 else 0
        
        if monthly_savings > monthly_cost:
            payback_months = monthly_cost / (monthly_savings - monthly_cost)
            payback_period = f"{payback_months:.1f} months"
        else:
            payback_period = "N/A (costs exceed savings)"
        
        # Additional metrics
        avg_daily_requests = len(ai_requests) / 30 if ai_requests else 0  # Assuming 30-day month
        cost_per_request = total_cost / len(ai_requests) if ai_requests else 0
        savings_per_request = estimated_savings / len(ai_requests) if ai_requests else 0
        
        # Calculate time saved based on user activity
        total_session_hours_saved = sum(
            user.total_session_duration / 3600 for user in users 
            if user.total_session_duration
        ) * 0.3  # Assume 30% efficiency improvement
        
        return {
            'estimatedSavings': round(estimated_savings, 2),
            'totalCost': round(total_cost, 2),
            'roiPercentage': round(roi_percentage, 1),
            'paybackPeriod': payback_period,
            'monthlyMetrics': {
                'estimatedSavings': round(estimated_savings / 12, 2),
                'totalCost': round(total_cost / 12, 2),
                'netSavings': round((estimated_savings - total_cost) / 12, 2)
            },
            'efficiencyMetrics': {
                'avgDailyRequests': round(avg_daily_requests, 1),
                'costPerRequest': round(cost_per_request, 2),
                'savingsPerRequest': round(savings_per_request, 2),
                'timeSavedHours': round(time_saved_hours, 1),
                'sessionHoursSaved': round(total_session_hours_saved, 1)
            },
            'breakdown': {
                'subscriptionCost': round(total_subscription_cost, 2),
                'aiUsageCost': round(total_ai_cost, 2),
                'laborSavings': round(estimated_savings, 2),
                'efficiencySavings': round(total_session_hours_saved * labor_cost_per_hour, 2)
            },
            'dataPoints': {
                'totalUsers': len(users),
                'premiumUsers': sum(1 for u in users if u.get_effective_plan() != 'free'),
                'totalAIRequests': len(ai_requests),
                'activeUsers': sum(1 for u in users if u.last_activity and 
                                 (datetime.utcnow() - u.last_activity).days < 7),
                'trialUsers': sum(1 for u in users if u.is_trial_active())
            },
            'timestamp': datetime.utcnow().isoformat()
        }
    
    except Exception as e:
        logger.error(f"Error calculating ROI analysis: {str(e)}")
        return {
            'estimatedSavings': 0,
            'roiPercentage': 0,
            'paybackPeriod': 'N/A',
            'error': str(e)
        }

