def get_accuracy_trend(hospital_id):
    """Get accuracy trend over time"""
    try:
        # Get AI requests for last 30 days, grouped by week
        thirty_days_ago = datetime.utcnow() - timedelta(days=30)
        
        hospital_users = User.query.filter_by(hospital_id=hospital_id).all()
        user_ids = [user.id for user in hospital_users]
        
        if not user_ids:
            return []
        
        # Get AI requests with confidence scores
        ai_requests = AIRequest.query.filter(
            AIRequest.user_id.in_(user_ids),
            AIRequest.created_at >= thirty_days_ago
        ).all()
        
        if not ai_requests:
            return []
        
        # Group by week and calculate average confidence
        weekly_data = {}
        for request in ai_requests:
            week_start = request.created_at - timedelta(days=request.created_at.weekday())
            week_key = week_start.strftime('%Y-%m-%d')
            
            if week_key not in weekly_data:
                weekly_data[week_key] = {'confidence_scores': [], 'count': 0}
            
            if request.confidence_score:
                weekly_data[week_key]['confidence_scores'].append(request.confidence_score)
                weekly_data[week_key]['count'] += 1
        
        # Calculate trend
        trend = []
        for week_start, data in sorted(weekly_data.items()):
            if data['confidence_scores']:
                avg_confidence = sum(data['confidence_scores']) / len(data['confidence_scores'])
                trend.append({
                    'week': week_start,
                    'accuracy': round(avg_confidence, 1),
                    'requests': data['count']
                })
        
        return trend
    
    except Exception as e:
        logger.error(f"Error getting accuracy trend: {str(e)}")
        return []

def calculate_violation_categories(analyses):
    """Calculate violation categories from analyses"""
    categories = {}
    for analysis in analyses:
        violations = analysis.get('violations', [])
        for violation in violations:
            category = violation.get('category', 'unknown')
            categories[category] = categories.get(category, 0) + 1
    return categories

def calculate_peak_times(analyses):
    """Calculate peak analysis times"""
    hour_counts = {}
    for analysis in analyses:
        try:
            analysis_date = datetime.fromisoformat(analysis.get('timestamp', '').replace('Z', '+00:00'))
            hour = analysis_date.hour
            hour_counts[hour] = hour_counts.get(hour, 0) + 1
        except:
            continue
    
    return dict(sorted(hour_counts.items()))

def calculate_efficiency_score(analyses):
    """Calculate efficiency score from analyses"""
    if not analyses:
        return 0
    
    total_score = 0
    for analysis in analyses:
        risk_score = analysis.get('risk_score', 0)
        compliance_score = analysis.get('compliance_score', 0)
        efficiency = (compliance_score + (100 - risk_score)) / 2
        total_score += efficiency
    
    return round(total_score / len(analyses), 1)

