@app.route('/api/risk-assessments/', methods=['GET'])
@jwt_required
def get_risk_assessments():
    """Get all risk assessments with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('risk_assessments'):
            return jsonify({
                'success': False,
                'error': 'Risk assessments not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro or higher plan for risk assessment features',
                'current_plan': request.effective_plan
            }), 403
        
        # Pagination with plan-based limits (bypass for super admin)
        page = request.args.get('page', 1, type=int)
        limit = request.args.get('limit', 20, type=int)
        
        # Apply plan-based limits (bypass for super admin)
        if not request.is_system_team:
            max_limit = {
                'free': 10,
                'pro': 50,
                'business': 100,
                'enterprise': 500
            }.get(request.effective_plan, 10)
            
            if limit > max_limit:
                limit = max_limit
        else:
            max_limit = 'unlimited'  # Super admin has no limit
        
        # Filters
        status = request.args.get('status')
        department_id = request.args.get('department_id', type=int)
        hospital_id = request.args.get('hospital_id', type=int)
        industry_id = request.args.get('industry_id', type=int)
        search = request.args.get('search')
        
        # Build query with scope restrictions
        query = RiskAssessment.query
        
        # Apply scope based on user role
        if request.is_system_team:
            # System team sees all
            pass
        elif request.user.user_type in ['admin', 'safety_manager']:
            # Admins see their hospital's assessments
            if request.user.hospital_id:
                query = query.filter(RiskAssessment.hospital_id == request.user.hospital_id)
            else:
                # No hospital assigned - see only own assessments
                query = query.filter(RiskAssessment.assessed_by == request.user.id)
        else:
            # Regular users see only their own assessments
            query = query.filter(RiskAssessment.assessed_by == request.user.id)
        
        # Apply filters
        if status:
            query = query.filter_by(status=status)
        if department_id:
            query = query.filter_by(department_id=department_id)
        if hospital_id:
            query = query.filter_by(hospital_id=hospital_id)
        if industry_id:
            query = query.filter_by(industry_id=industry_id)
        if search:
            query = query.filter(
                db.or_(
                    RiskAssessment.title.ilike(f'%{search}%'),
                    RiskAssessment.description.ilike(f'%{search}%'),
                    RiskAssessment.assessment_number.ilike(f'%{search}%')
                )
            )
        
        # Date range filtering (bypass restrictions for super admin)
        if request.args.get('start_date'):
            try:
                start_date = datetime.fromisoformat(request.args.get('start_date').replace('Z', '+00:00'))
                # Free plan limited to last 30 days (only for non-super-admin)
                if not request.is_system_team and request.effective_plan == 'free':
                    thirty_days_ago = datetime.utcnow() - timedelta(days=30)
                    if start_date < thirty_days_ago:
                        start_date = thirty_days_ago
                query = query.filter(RiskAssessment.assessment_date >= start_date)
            except:
                pass
        
        if request.args.get('end_date'):
            try:
                end_date = datetime.fromisoformat(request.args.get('end_date').replace('Z', '+00:00'))
                query = query.filter(RiskAssessment.assessment_date <= end_date)
            except:
                pass
        
        # Paginate
        assessments = query.order_by(RiskAssessment.assessment_date.desc()).paginate(
            page=page, per_page=limit, error_out=False
        )
        
        # Get assessments with plan-based data depth
        plan_to_use = 'enterprise' if request.is_system_team else request.effective_plan
        
        assessment_data = []
        for assessment in assessments.items:
            assessment_dict = assessment.to_dict()
            
            # Add additional data based on plan
            if plan_to_use in ['pro', 'business', 'enterprise']:
                assessment_dict['items_count'] = len(assessment.items) if hasattr(assessment, 'items') else 0
                assessment_dict['last_updated'] = assessment.updated_at.isoformat() if assessment.updated_at else None
            
            # Add advanced data for business/enterprise and super admin
            if plan_to_use in ['business', 'enterprise']:
                assessment_dict['risk_indicators'] = get_risk_indicators(assessment.id)
                assessment_dict['compliance_status'] = get_environmental_compliance_status(assessment.id)
            
            assessment_data.append(assessment_dict)
        
        # Add summary statistics for higher plans and super admin
        summary_stats = {}
        if plan_to_use in ['business', 'enterprise'] and assessment_data:
            summary_stats = {
                'total_assessments': assessments.total,
                'average_risk_level': calculate_average_risk_level(assessments.items),
                'completion_rate': calculate_completion_rate(assessments.items),
                'overdue_count': count_overdue_assessments(assessments.items),
                'system_assessments': len([a for a in assessments.items if a.hospital_id is None]) if request.is_system_team else 0
            }
        
        return jsonify({
            'success': True,
            'data': assessment_data,
            'total': assessments.total,
            'page': assessments.page,
            'pages': assessments.pages,
            'has_next': assessments.has_next,
            'has_prev': assessments.has_prev,
            'summary_stats': summary_stats,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'effectivePlanUsed': plan_to_use,
                'maxResults': max_limit,
                'dataScope': 'system' if request.is_system_team else 'hospital' if request.user.hospital_id else 'personal',
                'analyticsDepth': 'basic' if plan_to_use == 'free' else 'standard' if plan_to_use == 'pro' else 'advanced',
                'planCheckBypassed': request.is_system_team
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching risk assessments: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'RISK_ASSESSMENTS_ERROR'
        }), 500

@app.route('/api/risk-assessments/<int:assessment_id>/', methods=['GET'])
@jwt_required
def get_env_risk_assessment(assessment_id):
    """Get risk assessment by ID with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('risk_assessment_detail'):
            return jsonify({
                'success': False,
                'error': 'Risk assessment detail view not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for detailed risk assessment views',
                'current_plan': request.effective_plan
            }), 403
        
        assessment = RiskAssessment.query.get(assessment_id)
        if not assessment:
            return jsonify({
                'success': False, 
                'error': 'Assessment not found',
                'code': 'ASSESSMENT_NOT_FOUND'
            }), 404
        
        # Check access permissions (super admin has full access)
        if not request.is_system_team and not has_access_to_assessment(request.user, assessment):
            return jsonify({
                'success': False,
                'error': 'Access denied to this assessment',
                'code': 'ASSESSMENT_ACCESS_DENIED',
                'suggestion': 'You can only access assessments in your scope'
            }), 403
        
        # Get assessment data with plan-based detail level
        assessment_data = assessment.to_dict()
        plan_to_use = 'enterprise' if request.is_system_team else request.effective_plan
        
        # Add items with plan-based depth
        if hasattr(assessment, 'items'):
            if plan_to_use == 'free':
                # Free plan gets basic item info
                assessment_data['items'] = [{
                    'id': item.id,
                    'hazard_description': item.hazard_description[:100] + '...' if len(item.hazard_description) > 100 else item.hazard_description,
                    'risk_level': item.risk_level,
                    'status': item.status
                } for item in assessment.items[:10]]  # Limit to 10 items
                assessment_data['items_limited'] = True
                assessment_data['total_items'] = len(assessment.items)
            else:
                # Pro and above get full items
                assessment_data['items'] = [item.to_dict() for item in assessment.items]
                assessment_data['items_count'] = len(assessment.items)
        
        # Add related data based on plan
        if plan_to_use in ['pro', 'business', 'enterprise']:
            assessment_data['history'] = get_assessment_history(assessment_id, plan_to_use)
            assessment_data['attachments'] = get_assessment_attachments(assessment_id)
        
        # Add advanced analytics for business/enterprise and super admin
        if plan_to_use in ['business', 'enterprise']:
            assessment_data['risk_analysis'] = analyze_assessment_risk(assessment)
            assessment_data['compliance_metrics'] = calculate_compliance_metrics(assessment)
            assessment_data['predictive_insights'] = generate_predictive_insights(assessment)
        
        # Add system admin specific data
        if request.is_system_team:
            assessment_data['system_metadata'] = {
                'created_by_email': get_user_email(assessment.assessed_by),
                'hospital_name': get_hospital_name(assessment.hospital_id),
                'access_log': get_assessment_access_log(assessment_id)
            }
        
        return jsonify({
            'success': True,
            'data': assessment_data,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'effectivePlanUsed': plan_to_use,
                'detailLevel': 'basic' if plan_to_use == 'free' else 'standard' if plan_to_use == 'pro' else 'advanced',
                'accessLevel': 'system_admin' if request.is_system_team else get_access_level(request.user, assessment),
                'planCheckBypassed': request.is_system_team
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching risk assessment {assessment_id}: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'ASSESSMENT_FETCH_ERROR'
        }), 500

@app.route('/api/risk-assessments/', methods=['POST'])
@jwt_required
def create_risk_assessment():
    """Create a new risk assessment with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('create_assessments'):
            return jsonify({
                'success': False,
                'error': 'Risk assessment creation not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan to create risk assessments',
                'current_plan': request.effective_plan
            }), 403
        
        # Check assessment creation limits (bypass for super admin)
        if not request.is_system_team and request.effective_plan != 'enterprise':
            monthly_assessments = RiskAssessment.query.filter(
                RiskAssessment.assessed_by == request.user.id,
                RiskAssessment.created_at >= datetime.utcnow().replace(day=1)
            ).count()
            
            assessment_limits = {
                'free': 1,
                'pro': 10,
                'business': 50
            }
            
            limit = assessment_limits.get(request.effective_plan, 1)
            if monthly_assessments >= limit:
                return jsonify({
                    'success': False,
                    'error': f'Monthly assessment limit reached for {request.effective_plan} plan',
                    'code': 'ASSESSMENT_LIMIT_REACHED',
                    'currentAssessments': monthly_assessments,
                    'limit': limit,
                    'suggestion': f'Upgrade to {get_next_plan(request.effective_plan)} plan for more assessments'
                }), 403
        
        data = request.json
        
        # Validate required fields
        required_fields = ['title', 'assessment_date']
        for field in required_fields:
            if not data.get(field):
                return jsonify({
                    'success': False, 
                    'error': f'{field.replace("_", " ").title()} is required',
                    'code': 'VALIDATION_ERROR'
                }), 400
        
        # Generate assessment number
        assessment_number = f"RA-{datetime.utcnow().strftime('%Y%m%d')}-{uuid.uuid4().hex[:8].upper()}"
        
        # Validate hospital access if specified (super admin bypasses hospital restrictions)
        hospital_id = data.get('hospital_id')
        if hospital_id and not request.is_system_team and not has_hospital_access(request.user, hospital_id):
            return jsonify({
                'success': False,
                'error': 'Access denied to specified hospital',
                'code': 'HOSPITAL_ACCESS_DENIED',
                'suggestion': 'You can only create assessments for your assigned hospital'
            }), 403
        
        # Create assessment
        plan_to_use = 'enterprise' if request.is_system_team else request.effective_plan
        assessment = RiskAssessment(
            assessment_number=assessment_number,
            title=data['title'],
            description=data.get('description'),
            department_id=data.get('department_id'),
            hospital_id=hospital_id or request.user.hospital_id,
            industry_id=data.get('industry_id'),
            assessed_by=request.user.id,  # Use authenticated user
            assessment_date=datetime.fromisoformat(data['assessment_date'].replace('Z', '+00:00')),
            next_assessment_date=datetime.fromisoformat(data['next_assessment_date'].replace('Z', '+00:00')) if data.get('next_assessment_date') else None,
            overall_risk_level=data.get('overall_risk_level'),
            status=data.get('status', 'draft'),
            plan_used=plan_to_use,
            created_by_system=request.is_system_team
        )
        
        db.session.add(assessment)
        db.session.commit()
        
        # Add history entry
        history = RiskAssessmentHistory(
            assessment_id=assessment.id,
            action='created',
            new_value=json.dumps(assessment.to_dict()),
            changed_by=request.user.id,
            plan_used=plan_to_use,
            system_action=request.is_system_team
        )
        db.session.add(history)
        
        # Add items if provided (with plan-based limits)
        if 'items' in data:
            max_items = {
                'free': 5,
                'pro': 20,
                'business': 100,
                'enterprise': 500
            }.get(plan_to_use, 5)
            
            items_to_add = data['items'][:max_items] if len(data['items']) > max_items else data['items']
            
            for item_data in items_to_add:
                item = RiskAssessmentItem(
                    assessment_id=assessment.id,
                    hazard_description=item_data.get('hazard_description', ''),
                    existing_controls=item_data.get('existing_controls'),
                    likelihood=item_data.get('likelihood'),
                    severity=item_data.get('severity'),
                    risk_level=item_data.get('risk_level'),
                    recommended_actions=item_data.get('recommended_actions'),
                    responsible_person=item_data.get('responsible_person'),
                    due_date=datetime.fromisoformat(item_data['due_date'].replace('Z', '+00:00')) if item_data.get('due_date') else None,
                    status=item_data.get('status', 'open'),
                    plan_used=plan_to_use
                )
                db.session.add(item)
            
            if len(data['items']) > max_items and not request.is_system_team:
                logger.warning(f"User {request.user.email} exceeded item limit ({max_items}) on assessment {assessment.id}")
        
        db.session.commit()
        
        logger.info(f"Risk assessment created by {request.user.email} (system: {request.is_system_team}): {assessment_number}")
        
        # Calculate monthly assessments (different for super admin)
        if request.is_system_team:
            monthly_assessments_total = RiskAssessment.query.filter(
                RiskAssessment.created_at >= datetime.utcnow().replace(day=1)
            ).count()
        else:
            monthly_assessments_total = RiskAssessment.query.filter(
                RiskAssessment.assessed_by == request.user.id,
                RiskAssessment.created_at >= datetime.utcnow().replace(day=1)
            ).count()
        
        return jsonify({
            'success': True,
            'message': 'Risk assessment created successfully',
            'data': assessment.to_dict(),
            'assessment_id': assessment.id,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'effectivePlanUsed': plan_to_use,
                'monthlyAssessments': monthly_assessments_total,
                'assessmentLimit': 'unlimited' if request.is_system_team else assessment_limits.get(request.effective_plan, 1),
                'itemsAdded': len(items_to_add) if 'items' in data else 0,
                'planCheckBypassed': request.is_system_team,
                'createdBySystem': request.is_system_team
            }
        })
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error creating risk assessment: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'ASSESSMENT_CREATION_ERROR'
        }), 500

@app.route('/api/risk-assessments/<int:assessment_id>/', methods=['PUT'])
@jwt_required
def update_risk_assessment(assessment_id):
    """Update an existing risk assessment with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('update_assessments'):
            return jsonify({
                'success': False,
                'error': 'Risk assessment updates not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan to update risk assessments',
                'current_plan': request.effective_plan
            }), 403
        
        assessment = RiskAssessment.query.get(assessment_id)
        if not assessment:
            return jsonify({
                'success': False, 
                'error': 'Assessment not found',
                'code': 'ASSESSMENT_NOT_FOUND'
            }), 404
        
        # Check update permissions (super admin can update anything)
        if not request.is_system_team and not can_update_assessment(request.user, assessment):
            return jsonify({
                'success': False,
                'error': 'Permission denied to update this assessment',
                'code': 'UPDATE_PERMISSION_DENIED',
                'suggestion': 'You can only update your own assessments or assessments in your department'
            }), 403
        
        data = request.json
        
        # Track changes
        changes = {}
        allowed_fields = ['title', 'description', 'department_id', 'assessment_date', 
                         'next_assessment_date', 'overall_risk_level', 'status']
        
        # Super admin can change any field
        if request.is_system_team:
            allowed_fields.extend(['hospital_id', 'industry_id', 'assessed_by', 'plan_used'])
        elif request.user.user_type in ['admin', 'safety_manager']:
            allowed_fields.extend(['hospital_id', 'industry_id'])
        
        for field in allowed_fields:
            if field in data:
                old_value = getattr(assessment, field)
                new_value = data[field]
                
                if old_value != new_value:
                    changes[field] = {'old': old_value, 'new': new_value}
                    setattr(assessment, field, new_value)
        
        # Update items if provided (with plan-based restrictions)
        if 'items' in data:
            # Use has_feature_access for item updates
            if not has_feature_access('update_assessment_items'):
                return jsonify({
                    'success': False,
                    'error': 'Item updates not available in free plan',
                    'code': 'FEATURE_NOT_AVAILABLE',
                    'required_plan': 'pro',
                    'suggestion': 'Upgrade to Pro plan to update assessment items'
                }), 403
            
            # Clear existing items
            RiskAssessmentItem.query.filter_by(assessment_id=assessment_id).delete()
            
            # Add new items with plan limits
            plan_to_use = 'enterprise' if request.is_system_team else request.effective_plan
            max_items = {
                'pro': 20,
                'business': 100,
                'enterprise': 500
            }.get(plan_to_use, 20)
            
            items_to_add = data['items'][:max_items] if len(data['items']) > max_items else data['items']
            
            for item_data in items_to_add:
                item = RiskAssessmentItem(
                    assessment_id=assessment_id,
                    hazard_description=item_data.get('hazard_description', ''),
                    existing_controls=item_data.get('existing_controls'),
                    likelihood=item_data.get('likelihood'),
                    severity=item_data.get('severity'),
                    risk_level=item_data.get('risk_level'),
                    recommended_actions=item_data.get('recommended_actions'),
                    responsible_person=item_data.get('responsible_person'),
                    due_date=datetime.fromisoformat(item_data['due_date'].replace('Z', '+00:00')) if item_data.get('due_date') else None,
                    status=item_data.get('status', 'open'),
                    plan_used=plan_to_use
                )
                db.session.add(item)
            
            changes['items'] = {'count': len(items_to_add)}
        
        assessment.updated_at = datetime.utcnow()
        assessment.updated_by = request.user.id
        
        # Track if updated by system admin
        if request.is_system_team:
            assessment.updated_by_system = True
        
        db.session.commit()
        
        # Add history entry if changes were made
        if changes:
            history = RiskAssessmentHistory(
                assessment_id=assessment_id,
                action='updated',
                old_value=json.dumps(changes),
                changed_by=request.user.id,
                change_reason=data.get('change_reason'),
                plan_used='enterprise' if request.is_system_team else request.effective_plan,
                system_action=request.is_system_team
            )
            db.session.add(history)
            db.session.commit()
        
        logger.info(f"Risk assessment updated by {request.user.email} (system: {request.is_system_team}): {assessment.assessment_number}")
        
        return jsonify({
            'success': True,
            'message': 'Risk assessment updated successfully',
            'data': assessment.to_dict(),
            'changes_made': len(changes),
            'planInfo': {
                'currentPlan': request.effective_plan,
                'effectivePlanUsed': 'enterprise' if request.is_system_team else request.effective_plan,
                'updatedBy': request.user.email,
                'planCheckBypassed': request.is_system_team,
                'systemUpdate': request.is_system_team
            }
        })
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating risk assessment {assessment_id}: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'ASSESSMENT_UPDATE_ERROR'
        }), 500

@app.route('/api/risk-assessments/<int:assessment_id>/', methods=['DELETE'])
@jwt_required
def delete_risk_assessment(assessment_id):
    """Delete a risk assessment with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('delete_assessments'):
            return jsonify({
                'success': False,
                'error': 'Risk assessment deletion not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan to delete risk assessments',
                'current_plan': request.effective_plan
            }), 403
        
        assessment = RiskAssessment.query.get(assessment_id)
        if not assessment:
            return jsonify({
                'success': False, 
                'error': 'Assessment not found',
                'code': 'ASSESSMENT_NOT_FOUND'
            }), 404
        
        # Check delete permissions (super admin can delete anything)
        if not request.is_system_team and not can_delete_assessment(request.user, assessment):
            return jsonify({
                'success': False,
                'error': 'Permission denied to delete this assessment',
                'code': 'DELETE_PERMISSION_DENIED',
                'suggestion': 'Only assessment owners and system administrators can delete assessments'
            }), 403
        
        # Check if assessment can be deleted (super admin bypasses all restrictions)
        if not request.is_system_team:
            if assessment.status == 'approved' and request.effective_plan != 'enterprise':
                return jsonify({
                    'success': False,
                    'error': 'Approved assessments cannot be deleted',
                    'code': 'ASSESSMENT_APPROVED',
                    'suggestion': 'Only Enterprise plan users can delete approved assessments'
                }), 400
        
        # Add history before deletion
        history = RiskAssessmentHistory(
            assessment_id=assessment_id,
            action='deleted',
            old_value=json.dumps(assessment.to_dict()),
            changed_by=request.user.id,
            change_reason=request.args.get('reason'),
            plan_used='enterprise' if request.is_system_team else request.effective_plan,
            system_action=request.is_system_team
        )
        db.session.add(history)
        
        # Delete the assessment
        assessment_number = assessment.assessment_number
        db.session.delete(assessment)
        db.session.commit()
        
        logger.warning(f"Risk assessment deleted by {request.user.email} (system: {request.is_system_team}): {assessment_number}")
        
        return jsonify({
            'success': True,
            'message': 'Risk assessment deleted successfully',
            'deleted_assessment': assessment_number,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'effectivePlanUsed': 'enterprise' if request.is_system_team else request.effective_plan,
                'deletedBy': request.user.email,
                'planCheckBypassed': request.is_system_team,
                'systemDeletion': request.is_system_team
            }
        })
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error deleting risk assessment {assessment_id}: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'ASSESSMENT_DELETION_ERROR'
        }), 500


@app.route('/api/risk-assessments/<int:assessment_id>/download-pdf/', methods=['GET'])
@jwt_required
def download_risk_assessment_pdf(assessment_id):
    """Download assessment as PDF with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('pdf_export'):
            return jsonify({
                'success': False,
                'error': 'PDF export not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for PDF exports',
                'current_plan': request.effective_plan
            }), 403
        
        assessment = RiskAssessment.query.get(assessment_id)
        if not assessment:
            return jsonify({
                'success': False, 
                'error': 'Assessment not found',
                'code': 'ASSESSMENT_NOT_FOUND'
            }), 404
        
        # Check access permissions
        if not request.is_system_team and not has_access_to_assessment(request.user, assessment):
            return jsonify({
                'success': False,
                'error': 'Access denied to this assessment',
                'code': 'ASSESSMENT_ACCESS_DENIED'
            }), 403
        
        # Check PDF download limits (bypass for super admin)
        if not request.is_system_team and request.effective_plan == 'free':
            if hasattr(request.user, 'monthly_pdf_exports'):
                pdf_limit = request.plan_limits.get('pdf_exports', 3)
                if request.user.monthly_pdf_exports >= pdf_limit:
                    return jsonify({
                        'success': False,
                        'error': 'Monthly PDF export limit reached',
                        'code': 'PDF_LIMIT_REACHED',
                        'currentExports': request.user.monthly_pdf_exports,
                        'limit': pdf_limit,
                        'suggestion': 'Upgrade to Pro plan for unlimited PDF exports'
                    }), 403
        
        # Create PDF
        from io import BytesIO
        from reportlab.pdfgen import canvas
        from reportlab.lib.pagesizes import letter
        
        buffer = BytesIO()
        p = canvas.Canvas(buffer, pagesize=letter)
        
        # Add branding
        p.setFont("Helvetica-Bold", 16)
        p.drawString(100, 780, f"Risk Assessment Report")
        p.setFont("Helvetica", 10)
        p.drawString(100, 760, f"Plan: {'SYSTEM ADMIN' if request.is_system_team else request.effective_plan.upper()}")
        p.drawString(100, 745, f"Generated by: {request.user.email}")
        p.drawString(100, 730, f"Generated on: {datetime.utcnow().strftime('%Y-%m-%d %H:%M')}")
        
        # Add assessment info
        p.setFont("Helvetica-Bold", 12)
        p.drawString(100, 710, f"Assessment Number: {assessment.assessment_number}")
        p.setFont("Helvetica", 12)
        p.drawString(100, 690, f"Title: {assessment.title}")
        p.drawString(100, 670, f"Date: {assessment.assessment_date.strftime('%Y-%m-%d')}")
        p.drawString(100, 650, f"Risk Level: {assessment.overall_risk_level}")
        
        # Add system admin marker
        if request.is_system_team:
            p.setFont("Helvetica-Bold", 10)
            p.drawString(100, 630, "[SYSTEM ADMINISTRATOR REPORT]")
            y = 610
        else:
            y = 630
        
        # Add assessment items
        items_to_show = assessment.items
        plan_to_use = 'enterprise' if request.is_system_team else request.effective_plan
        
        if plan_to_use == 'free':
            items_to_show = assessment.items[:5]  # Limit for free plan
        
        for item in items_to_show:
            if y < 100:  # New page if running out of space
                p.showPage()
                y = 750
                p.setFont("Helvetica", 10)
            
            p.drawString(100, y, f"Hazard: {item.hazard_description[:80]}...")
            p.drawString(100, y-15, f"Risk Level: {item.risk_level}")
            y -= 30
        
        # Add item limit notice for free plan
        if plan_to_use == 'free' and len(assessment.items) > 5:
            p.drawString(100, y-30, f"[... {len(assessment.items) - 5} more items hidden in free plan]")
        
        p.save()
        buffer.seek(0)
        
        # Track PDF export (not for super admin)
        if not request.is_system_team and hasattr(request.user, 'monthly_pdf_exports'):
            request.user.monthly_pdf_exports += 1
            request.user.total_pdf_exports += 1
            db.session.commit()
        
        logger.info(f"PDF exported by {request.user.email} (system: {request.is_system_team}): {assessment.assessment_number}")
        
        return send_file(
            buffer,
            as_attachment=True,
            download_name=f'risk-assessment-{assessment.assessment_number}.pdf',
            mimetype='application/pdf'
        )
        
    except Exception as e:
        logger.error(f"Error generating PDF for assessment {assessment_id}: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'PDF_GENERATION_ERROR'
        }), 500

@app.route('/api/risk-assessments/<int:assessment_id>/download-excel/', methods=['GET'])
@jwt_required
def download_risk_assessment_excel(assessment_id):
    """Download assessment as Excel with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('excel_export'):
            return jsonify({
                'success': False,
                'error': 'Excel export not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'suggestion': 'Upgrade to Business plan for Excel exports',
                'current_plan': request.effective_plan
            }), 403
        
        assessment = RiskAssessment.query.get(assessment_id)
        if not assessment:
            return jsonify({
                'success': False, 
                'error': 'Assessment not found',
                'code': 'ASSESSMENT_NOT_FOUND'
            }), 404
        
        # Check access permissions
        if not request.is_system_team and not has_access_to_assessment(request.user, assessment):
            return jsonify({
                'success': False,
                'error': 'Access denied to this assessment',
                'code': 'ASSESSMENT_ACCESS_DENIED'
            }), 403
        
        import pandas as pd
        from io import BytesIO
        
        # Create DataFrame with assessment data
        data = {
            'Assessment Number': [assessment.assessment_number],
            'Title': [assessment.title],
            'Description': [assessment.description],
            'Assessment Date': [assessment.assessment_date.strftime('%Y-%m-%d')],
            'Risk Level': [assessment.overall_risk_level],
            'Status': [assessment.status],
            'Generated By': [request.user.email],
            'Plan Used': ['SYSTEM ADMIN' if request.is_system_team else request.effective_plan],
            'Generated On': [datetime.utcnow().strftime('%Y-%m-%d %H:%M')],
            'System Admin': ['Yes' if request.is_system_team else 'No']
        }
        
        df_main = pd.DataFrame(data)
        
        # Create DataFrame for items
        items_data = []
        for item in assessment.items:
            items_data.append({
                'Hazard Description': item.hazard_description,
                'Existing Controls': item.existing_controls,
                'Likelihood': item.likelihood,
                'Severity': item.severity,
                'Risk Level': item.risk_level,
                'Recommended Actions': item.recommended_actions,
                'Responsible Person': item.responsible_person,
                'Due Date': item.due_date.strftime('%Y-%m-%d') if item.due_date else '',
                'Status': item.status
            })
        
        df_items = pd.DataFrame(items_data)
        
        # Add sheets
        sheets = {
            'Assessment Summary': df_main,
            'Risk Items': df_items
        }
        
        plan_to_use = 'enterprise' if request.is_system_team else request.effective_plan
        
        # Add analytics sheet for business/enterprise and super admin
        if plan_to_use in ['business', 'enterprise']:
            # Add analytics sheet
            analytics_data = {
                'Metric': ['Total Items', 'High Risk Items', 'Medium Risk Items', 'Low Risk Items', 'Open Actions', 'Completed Actions'],
                'Value': [
                    len(assessment.items),
                    len([i for i in assessment.items if i.risk_level == 'high']),
                    len([i for i in assessment.items if i.risk_level == 'medium']),
                    len([i for i in assessment.items if i.risk_level == 'low']),
                    len([i for i in assessment.items if i.status == 'open']),
                    len([i for i in assessment.items if i.status == 'completed'])
                ]
            }
            df_analytics = pd.DataFrame(analytics_data)
            sheets['Analytics'] = df_analytics
        
        # Create Excel file in memory
        output = BytesIO()
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            for sheet_name, df in sheets.items():
                df.to_excel(writer, sheet_name=sheet_name, index=False)
        
        output.seek(0)
        
        # Track Excel export (not for super admin)
        if not request.is_system_team and hasattr(request.user, 'monthly_excel_exports'):
            request.user.monthly_excel_exports += 1
            request.user.total_excel_exports += 1
            db.session.commit()
        
        logger.info(f"Excel exported by {request.user.email} (system: {request.is_system_team}): {assessment.assessment_number}")
        
        return send_file(
            output,
            as_attachment=True,
            download_name=f'risk-assessment-{assessment.assessment_number}.xlsx',
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        )
        
    except Exception as e:
        logger.error(f"Error generating Excel for assessment {assessment_id}: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'EXCEL_GENERATION_ERROR'
        }), 500

@app.route('/api/risk-assessments/download-all-excel/', methods=['GET'])
@jwt_required
def download_all_risk_assessments_excel():
    """Download all assessments as Excel with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('bulk_export'):
            return jsonify({
                'success': False,
                'error': 'Bulk export not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'enterprise',
                'suggestion': 'Upgrade to Enterprise plan for bulk exports',
                'current_plan': request.effective_plan
            }), 403
        
        # Check bulk export permissions (super admin always has permission)
        if not request.is_system_team and not request.user.user_type in ['admin', 'safety_manager']:
            return jsonify({
                'success': False,
                'error': 'Bulk export requires administrator role',
                'code': 'ADMIN_REQUIRED',
                'suggestion': 'Only administrators can perform bulk exports'
            }), 403
        
        # Get filter parameters
        department_id = request.args.get('department_id', type=int)
        start_date = request.args.get('start_date')
        end_date = request.args.get('end_date')
        
        # Build query with scope restrictions
        query = RiskAssessment.query
        
        # Apply user scope (super admin sees all)
        if not request.is_system_team and request.user.hospital_id:
            query = query.filter(RiskAssessment.hospital_id == request.user.hospital_id)
        
        if department_id:
            query = query.filter_by(department_id=department_id)
        if start_date:
            query = query.filter(RiskAssessment.assessment_date >= datetime.fromisoformat(start_date))
        if end_date:
            query = query.filter(RiskAssessment.assessment_date <= datetime.fromisoformat(end_date))
        
        # Apply plan-based limits (super admin has no limit)
        if not request.is_system_team:
            max_assessments = {
                'business': 100,
                'enterprise': 1000
            }.get(request.effective_plan, 50)
            
            assessments = query.limit(max_assessments).all()
        else:
            assessments = query.all()
        
        if not assessments:
            return jsonify({
                'success': False, 
                'error': 'No assessments found',
                'code': 'NO_ASSESSMENTS_FOUND'
            }), 404
        
        import pandas as pd
        from io import BytesIO
        
        # Create DataFrame
        data = []
        for assessment in assessments:
            data.append({
                'Assessment Number': assessment.assessment_number,
                'Title': assessment.title,
                'Department': assessment.department.name if assessment.department else '',
                'Assessment Date': assessment.assessment_date.strftime('%Y-%m-%d'),
                'Next Assessment': assessment.next_assessment_date.strftime('%Y-%m-%d') if assessment.next_assessment_date else '',
                'Overall Risk Level': assessment.overall_risk_level,
                'Status': assessment.status,
                'Created At': assessment.created_at.strftime('%Y-%m-%d %H:%M'),
                'Items Count': len(assessment.items),
                'Plan Used': getattr(assessment, 'plan_used', 'system' if request.is_system_team else 'unknown'),
                'Hospital': get_hospital_name(assessment.hospital_id) if assessment.hospital_id else 'System',
                'Created By': get_user_email(assessment.assessed_by)
            })
        
        df = pd.DataFrame(data)
        
        # Create Excel file
        output = BytesIO()
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name='All Assessments', index=False)
            
            # Add summary sheet for enterprise and super admin
            plan_to_use = 'enterprise' if request.is_system_team else request.effective_plan
            if plan_to_use == 'enterprise':
                summary_data = {
                    'Metric': ['Total Assessments', 'Average Items per Assessment', 'High Risk Assessments', 
                              'Completed Assessments', 'Average Risk Score', 'System Assessments'],
                    'Value': [
                        len(assessments),
                        sum(len(a.items) for a in assessments) / len(assessments) if assessments else 0,
                        len([a for a in assessments if a.overall_risk_level == 'high']),
                        len([a for a in assessments if a.status == 'completed']),
                        calculate_average_risk_score(assessments),
                        len([a for a in assessments if not a.hospital_id]) if request.is_system_team else 0
                    ]
                }
                df_summary = pd.DataFrame(summary_data)
                df_summary.to_excel(writer, sheet_name='Summary', index=False)
        
        output.seek(0)
        
        filename = f'bulk-risk-assessments-{datetime.utcnow().strftime("%Y%m%d-%H%M%S")}.xlsx'
        
        # Track bulk export
        logger.warning(f"Bulk export by {request.user.email} (system: {request.is_system_team}): {len(assessments)} assessments")
        
        return send_file(
            output,
            as_attachment=True,
            download_name=filename,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        )
        
    except Exception as e:
        logger.error(f"Error downloading all assessments: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'BULK_EXPORT_ERROR'
        }), 500

@app.route('/api/risk-assessment-templates/', methods=['GET'])
@jwt_required
def get_risk_assessment_templates():
    """Get assessment templates with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('assessment_templates'):
            return jsonify({
                'success': False,
                'error': 'Assessment templates not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for assessment templates',
                'current_plan': request.effective_plan
            }), 403
        
        industry_id = request.args.get('industry_id', type=int)
        department_id = request.args.get('department_id', type=int)
        
        query = RiskAssessmentTemplate.query.filter_by(is_active=True)
        
        # Apply scope restrictions
        if not request.is_system_team:
            # Only show templates available for user's plan
            plan_templates = {
                'free': ['basic'],
                'pro': ['basic', 'standard'],
                'business': ['basic', 'standard', 'advanced'],
                'enterprise': ['basic', 'standard', 'advanced', 'enterprise']
            }
            allowed_levels = plan_templates.get(request.effective_plan, ['basic'])
            query = query.filter(RiskAssessmentTemplate.template_level.in_(allowed_levels))
        else:
            # Super admin sees all templates
            allowed_levels = ['all']
        
        if industry_id:
            query = query.filter_by(industry_id=industry_id)
        if department_id:
            query = query.filter_by(department_id=department_id)
        
        templates = query.all()
        
        return jsonify({
            'success': True,
            'data': [template.to_dict() for template in templates],
            'count': len(templates),
            'planInfo': {
                'currentPlan': request.effective_plan,
                'availableTemplateLevels': allowed_levels,
                'templateAccess': 'full' if request.is_system_team else 'plan-based',
                'planCheckBypassed': request.is_system_team
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching templates: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'TEMPLATES_ERROR'
        }), 500

@app.route('/api/risk-assessment-templates/<int:template_id>/', methods=['GET'])
@jwt_required
def get_risk_assessment_template(template_id):
    """Get template by ID with JWT auth - Plan check bypassed for super admin"""
    try:
        # Use has_feature_access for plan check
        if not has_feature_access('template_detail'):
            return jsonify({
                'success': False,
                'error': 'Template detail view not available in free plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'pro',
                'suggestion': 'Upgrade to Pro plan for template details',
                'current_plan': request.effective_plan
            }), 403
        
        template = RiskAssessmentTemplate.query.get(template_id)
        if not template:
            return jsonify({
                'success': False, 
                'error': 'Template not found',
                'code': 'TEMPLATE_NOT_FOUND'
            }), 404
        
        # Check if template is available for user's plan (super admin bypasses)
        if not request.is_system_team:
            plan_templates = {
                'free': ['basic'],
                'pro': ['basic', 'standard'],
                'business': ['basic', 'standard', 'advanced'],
                'enterprise': ['basic', 'standard', 'advanced', 'enterprise']
            }
            allowed_levels = plan_templates.get(request.effective_plan, ['basic'])
            
            if template.template_level not in allowed_levels:
                return jsonify({
                    'success': False,
                    'error': f'Template level "{template.template_level}" not available in {request.effective_plan} plan',
                    'code': 'TEMPLATE_LEVEL_NOT_AVAILABLE',
                    'required_plan': get_plan_for_template_level(template.template_level),
                    'suggestion': f'Upgrade to {get_plan_for_template_level(template.template_level)} plan for this template'
                }), 403
        
        template_data = template.to_dict()
        plan_to_use = 'enterprise' if request.is_system_team else request.effective_plan
        
        # Add additional data based on plan
        if plan_to_use in ['pro', 'business', 'enterprise']:
            template_data['items_count'] = len(template.items) if hasattr(template, 'items') else 0
            template_data['usage_count'] = get_template_usage_count(template_id)
        
        # Add advanced data for business/enterprise and super admin
        if plan_to_use in ['business', 'enterprise']:
            template_data['best_practices'] = get_template_best_practices(template_id)
            template_data['compliance_references'] = get_template_compliance_references(template_id)
        
        # Add system admin specific data
        if request.is_system_team:
            template_data['system_metadata'] = {
                'created_by': get_user_email(template.created_by) if hasattr(template, 'created_by') else None,
                'last_modified': template.updated_at.isoformat() if template.updated_at else None,
                'is_protected': getattr(template, 'is_protected', False)
            }
        
        return jsonify({
            'success': True,
            'data': template_data,
            'planInfo': {
                'currentPlan': request.effective_plan,
                'effectivePlanUsed': plan_to_use,
                'templateLevel': template.template_level,
                'detailAccess': 'full' if plan_to_use in ['pro', 'business', 'enterprise'] else 'limited',
                'planCheckBypassed': request.is_system_team
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching template {template_id}: {e}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'code': 'TEMPLATE_FETCH_ERROR'
        }), 500

# Helper functions for risk assessments
# ==================== HELPER FUNCTIONS FOR RISK ASSESSMENTS ====================

def has_access_to_assessment(user, assessment):
    """Check if user has access to assessment"""
    if not user or not assessment:
        return False
    
    # System team members have full access
    if user.is_system_team:
        return True
    
    # Assessment owner has access
    if hasattr(assessment, 'assessed_by') and assessment.assessed_by == user.id:
        return True
    
    # Safety professionals in the same hospital have access
    if user.user_type in ['safetypro', 'admin', 'system']:
        if hasattr(assessment, 'hospital_id') and assessment.hospital_id == user.hospital_id:
            return True
    
    # Department members have access to department assessments
    if hasattr(assessment, 'department_id') and assessment.department_id:
        if hasattr(user, 'department_id') and user.department_id == assessment.department_id:
            return True
    
    # Platform owners have access to all assessments
    if user.is_platform_owner:
        return True
    
    # Check custom enterprise features
    if hasattr(user, 'enterprise_features') and user.enterprise_features:
        if 'cross_department_access' in user.enterprise_features:
            # Enterprise users with cross-department access
            if hasattr(assessment, 'hospital_id') and assessment.hospital_id == user.hospital_id:
                return True
    
    return False

def can_update_assessment(user, assessment):
    """Check if user can update assessment"""
    if not user or not assessment:
        return False
    
    # System team members can update any assessment
    if user.is_system_team:
        return True
    
    # Assessment owner can update their own assessments
    if hasattr(assessment, 'assessed_by') and assessment.assessed_by == user.id:
        # Check if assessment is in editable state
        if hasattr(assessment, 'status'):
            editable_statuses = ['draft', 'in_progress', 'pending_review']
            return assessment.status in editable_statuses
        return True
    
    # Safety managers and admins can update assessments in their hospital
    if user.user_type in ['safetypro', 'admin']:
        if hasattr(assessment, 'hospital_id') and assessment.hospital_id == user.hospital_id:
            # Additional check for user role permissions
            if hasattr(user, 'platform_permissions') and user.platform_permissions:
                if 'edit_assessments' in user.platform_permissions:
                    # Check if assessment is in editable state
                    if hasattr(assessment, 'status'):
                        editable_statuses = ['draft', 'in_progress', 'pending_review']
                        return assessment.status in editable_statuses
                    return True
    
    # Platform owners can update any assessment
    if user.is_platform_owner:
        return True
    
    return False

def can_delete_assessment(user, assessment):
    """Check if user can delete assessment"""
    if not user or not assessment:
        return False
    
    # System team members can delete any assessment
    if user.is_system_team:
        return True
    
    # Assessment owner can delete their own assessments if not approved
    if hasattr(assessment, 'assessed_by') and assessment.assessed_by == user.id:
        if hasattr(assessment, 'status'):
            deletable_statuses = ['draft', 'in_progress']
            return assessment.status in deletable_statuses
        return True
    
    # Platform owners can delete any assessment
    if user.is_platform_owner:
        return True
    
    # Safety managers and admins with delete permission can delete
    if user.user_type in ['safetypro', 'admin']:
        if hasattr(user, 'platform_permissions') and user.platform_permissions:
            if 'delete_assessments' in user.platform_permissions:
                if hasattr(assessment, 'hospital_id') and assessment.hospital_id == user.hospital_id:
                    return True
    
    return False

# backend/utils/permissions.py

def has_hospital_access(user, hospital_id):
    """Check if user has access to hospital"""
    if not user:
        return False
    
    # ✅ Check if user has proper plan for hospital access
    effective_plan = user.get_effective_plan() if hasattr(user, 'get_effective_plan') else getattr(user, 'subscription_plan', 'free')
    
    # ✅ Enterprise and business plans have hospital access
    if effective_plan in ['enterprise', 'business', 'custom']:
        # User has hospital access through plan
        pass  # Continue to other checks
    elif effective_plan == 'pro':
        # Pro users can only access their own hospital
        pass
    else:
        # Free users don't have hospital access
        return False
    
    # System team members have access to all hospitals
    if hasattr(user, 'is_system_team') and user.is_system_team:
        return True
    
    # Platform owners have access to all hospitals
    if hasattr(user, 'is_platform_owner') and user.is_platform_owner:
        return True
    
    # ✅ Check if user's hospital_id matches
    user_hospital_id = getattr(user, 'hospital_id', None)
    if user_hospital_id and user_hospital_id == hospital_id:
        return True
    
    # ✅ Check if user's company_id matches (if using company-based hospital access)
    user_company_id = getattr(user, 'company_id', None)
    if user_company_id:
        # Check if hospital belongs to this company
        from models import Hospital
        hospital = Hospital.query.get(hospital_id)
        if hospital and hospital.company_id == user_company_id:
            return True
    
    # Check if user has cross-hospital access through enterprise features
    enterprise_features = getattr(user, 'enterprise_features', {})
    if enterprise_features and isinstance(enterprise_features, dict):
        if enterprise_features.get('multi_hospital_access', False):
            accessible_hospitals = getattr(user, 'accessible_hospitals', [])
            if accessible_hospitals and hospital_id in accessible_hospitals:
                return True
    
    return False


def get_access_level(user, assessment):
    """Get access level for assessment"""
    if not user or not assessment:
        return 'none'
    
    # System team members have system-level access
    if hasattr(user, 'is_system_team') and user.is_system_team:
        return 'system'
    
    # Platform owners have owner-level access
    if hasattr(user, 'is_platform_owner') and user.is_platform_owner:
        return 'owner'
    
    # Assessment owner
    assessed_by = getattr(assessment, 'assessed_by', None)
    if assessed_by and assessed_by == user.id:
        return 'owner'
    
    # ✅ Check user's plan for access
    effective_plan = user.get_effective_plan() if hasattr(user, 'get_effective_plan') else getattr(user, 'subscription_plan', 'free')
    
    # Hospital admin/safety manager
    user_type = getattr(user, 'user_type', '')
    if user_type in ['safetypro', 'admin', 'hospital_admin']:
        assessment_hospital_id = getattr(assessment, 'hospital_id', None)
        user_hospital_id = getattr(user, 'hospital_id', None)
        
        if assessment_hospital_id and user_hospital_id and assessment_hospital_id == user_hospital_id:
            # Check specific permissions
            platform_permissions = getattr(user, 'platform_permissions', {})
            if platform_permissions and isinstance(platform_permissions, dict):
                if platform_permissions.get('manage_assessments', False):
                    return 'hospital_admin'
                elif platform_permissions.get('view_all_assessments', False):
                    return 'viewer'
            # Default hospital admin access
            return 'hospital_admin'
    
    # Department member access
    assessment_department = getattr(assessment, 'department_id', None)
    user_department = getattr(user, 'department_id', None)
    if assessment_department and user_department and assessment_department == user_department:
        return 'department_member'
    
    # ✅ Viewer access based on subscription plan
    if effective_plan in ['pro', 'business', 'enterprise', 'custom']:
        assessment_hospital_id = getattr(assessment, 'hospital_id', None)
        user_hospital_id = getattr(user, 'hospital_id', None)
        if assessment_hospital_id and user_hospital_id and assessment_hospital_id == user_hospital_id:
            return 'viewer'
    
    # ✅ Check if user's company owns this assessment's hospital
    user_company_id = getattr(user, 'company_id', None)
    if user_company_id:
        from models import Hospital
        assessment_hospital_id = getattr(assessment, 'hospital_id', None)
        if assessment_hospital_id:
            hospital = Hospital.query.get(assessment_hospital_id)
            if hospital and hospital.company_id == user_company_id:
                return 'viewer'
    
    return 'none'


# ✅ Helper function to check if user has hospital module access
def can_access_hospital_module(user):
    """Check if user can access the hospital module"""
    if not user:
        return False
    
    # Super admin bypass
    if hasattr(user, 'is_super_admin') and user.is_super_admin:
        return True
    
    # System team bypass
    if hasattr(user, 'is_system_team') and user.is_system_team:
        return True
    
    # Platform owner bypass
    if hasattr(user, 'is_platform_owner') and user.is_platform_owner:
        return True
    
    # Check plan
    effective_plan = user.get_effective_plan() if hasattr(user, 'get_effective_plan') else getattr(user, 'subscription_plan', 'free')
    
    # Enterprise, business, and custom plans have hospital access
    if effective_plan in ['enterprise', 'business', 'custom']:
        return True
    
    # Pro users have limited hospital access
    if effective_plan == 'pro':
        # Pro users can access hospital if they have a hospital_id
        return bool(getattr(user, 'hospital_id', None))
    
    return False


# ✅ Decorator for hospital module access
def require_hospital_module(f):
    """Decorator to require hospital module access"""
    from functools import wraps
    from flask import request, jsonify
    
    @wraps(f)
    def decorated_function(*args, **kwargs):
        user = getattr(request, 'user', None)
        if not user:
            return jsonify({'error': 'Authentication required'}), 401
        
        if not can_access_hospital_module(user):
            return jsonify({
                'success': False,
                'error': 'Hospital management not available in your plan',
                'code': 'FEATURE_NOT_AVAILABLE',
                'required_plan': 'business',
                'current_plan': user.subscription_plan if hasattr(user, 'subscription_plan') else 'free',
                'suggestion': 'Upgrade to Business or Enterprise plan for hospital management features'
            }), 403
        
        return f(*args, **kwargs)
    return decorated_function

def calculate_average_risk_level(assessments):
    """Calculate average risk level from assessments"""
    if not assessments:
        return 0
    
    risk_scores = {
        'low': 1,
        'low-medium': 1.5,
        'medium': 2,
        'medium-high': 2.5,
        'high': 3,
        'critical': 4
    }
    
    total_score = 0
    valid_assessments = 0
    
    for assessment in assessments:
        if hasattr(assessment, 'overall_risk_level'):
            risk_level = assessment.overall_risk_level
            if risk_level:
                risk_level = risk_level.lower()
                total_score += risk_scores.get(risk_level, 0)
                valid_assessments += 1
    
    if valid_assessments == 0:
        return 0
    
    average_score = total_score / valid_assessments
    
    # Convert back to risk level categories
    if average_score < 1.25:
        return 'low'
    elif average_score < 1.75:
        return 'low-medium'
    elif average_score < 2.25:
        return 'medium'
    elif average_score < 2.75:
        return 'medium-high'
    elif average_score < 3.5:
        return 'high'
    else:
        return 'critical'

def calculate_completion_rate(assessments):
    """Calculate completion rate"""
    if not assessments:
        return 0
    
    completed = 0
    total = len(assessments)
    
    for assessment in assessments:
        if hasattr(assessment, 'status'):
            status = assessment.status.lower()
            if status in ['completed', 'approved', 'closed', 'verified']:
                completed += 1
        else:
            # If no status field, assume completed if has overall_risk_score
            if hasattr(assessment, 'overall_risk_score') and assessment.overall_risk_score:
                completed += 1
    
    return round((completed / total) * 100, 1) if total > 0 else 0

def count_overdue_assessments(assessments):
    """Count overdue assessments"""
    overdue = 0
    today = datetime.utcnow().date()
    
    for assessment in assessments:
        if hasattr(assessment, 'next_assessment_date') and assessment.next_assessment_date:
            if assessment.next_assessment_date < today:
                overdue += 1
        elif hasattr(assessment, 'due_date') and assessment.due_date:
            if assessment.due_date < today:
                overdue += 1
    
    return overdue

def get_assessment_history(assessment_id, plan):
    """Get assessment history with plan-based depth"""
    try:
        if not hasattr(db.Model, 'risk_assessment_history'):
            return []
        
        query = RiskAssessmentHistory.query.filter_by(assessment_id=assessment_id)
        
        # Apply plan-based limits
        if plan == 'free' or plan == 'basic':
            query = query.limit(10)  # Limited history for free/basic
        elif plan == 'pro':
            query = query.limit(50)  # Moderate history for pro
        elif plan == 'business':
            query = query.limit(100)  # More history for business
        elif plan == 'enterprise':
            query = query.limit(200)  # Full history for enterprise
        
        history = query.order_by(RiskAssessmentHistory.created_at.desc()).all()
        
        # Convert to dictionary format
        history_data = []
        for h in history:
            history_data.append({
                'id': h.id,
                'assessment_id': h.assessment_id,
                'action': h.action,
                'changes': h.changes if hasattr(h, 'changes') else {},
                'performed_by': h.performed_by,
                'performed_by_name': get_user_email(h.performed_by) if h.performed_by else 'System',
                'created_at': h.created_at.isoformat() if h.created_at else None,
                'version': getattr(h, 'version', 1)
            })
        
        return history_data
    
    except Exception as e:
        logger.error(f"Error getting assessment history for {assessment_id}: {str(e)}")
        return []

def get_assessment_attachments(assessment_id):
    """Get assessment attachments"""
    try:
        if not hasattr(db.Model, 'assessment_attachments'):
            return []
        
        attachments = AssessmentAttachment.query.filter_by(
            assessment_id=assessment_id
        ).order_by(AssessmentAttachment.created_at.desc()).all()
        
        attachments_data = []
        for attachment in attachments:
            attachments_data.append({
                'id': attachment.id,
                'filename': attachment.filename,
                'file_url': attachment.file_url,
                'file_type': attachment.file_type,
                'file_size': attachment.file_size,
                'uploaded_by': attachment.uploaded_by,
                'uploaded_by_name': get_user_email(attachment.uploaded_by) if attachment.uploaded_by else 'Unknown',
                'created_at': attachment.created_at.isoformat() if attachment.created_at else None,
                'description': getattr(attachment, 'description', '')
            })
        
        return attachments_data
    
    except Exception as e:
        logger.error(f"Error getting assessment attachments for {assessment_id}: {str(e)}")
        return []

def analyze_assessment_risk(assessment):
    """Analyze assessment risk"""
    try:
        if not assessment:
            return {
                'risk_score': 0,
                'risk_trend': 'unknown',
                'areas_of_concern': [],
                'confidence': 'low'
            }
        
        # Calculate risk score
        risk_score = calculate_risk_score(assessment)
        
        # Identify risk areas
        risk_areas = identify_risk_areas(assessment)
        
        # Determine risk trend based on history
        risk_trend = 'stable'
        if hasattr(assessment, 'id'):
            try:
                history = RiskAssessmentHistory.query.filter_by(
                    assessment_id=assessment.id
                ).order_by(RiskAssessmentHistory.created_at.desc()).limit(2).all()
                
                if len(history) >= 2:
                    # Compare current risk with previous
                    current_risk = risk_score
                    previous_data = history[1].changes if hasattr(history[1], 'changes') else {}
                    previous_risk = previous_data.get('overall_risk_score', current_risk)
                    
                    if current_risk > previous_risk + 10:
                        risk_trend = 'increasing'
                    elif current_risk < previous_risk - 10:
                        risk_trend = 'decreasing'
            except:
                pass
        
        # Calculate confidence level
        confidence = 'medium'
        if hasattr(assessment, 'confidence_score'):
            if assessment.confidence_score > 80:
                confidence = 'high'
            elif assessment.confidence_score > 60:
                confidence = 'medium'
            else:
                confidence = 'low'
        
        return {
            'risk_score': risk_score,
            'risk_level': get_risk_level_from_score(risk_score),
            'risk_trend': risk_trend,
            'areas_of_concern': risk_areas,
            'confidence': confidence,
            'analysis_date': datetime.utcnow().isoformat()
        }
    
    except Exception as e:
        logger.error(f"Error analyzing assessment risk: {str(e)}")
        return {
            'risk_score': 0,
            'risk_trend': 'unknown',
            'areas_of_concern': [],
            'confidence': 'low',
            'error': str(e)
        }

def calculate_compliance_metrics(assessment):
    """Calculate compliance metrics"""
    try:
        if not assessment:
            return {
                'compliance_score': 0,
                'regulatory_alignment': 0,
                'audit_readiness': 0,
                'overall_status': 'unknown'
            }
        
        # Calculate compliance score (0-100)
        compliance_score = 0
        
        if hasattr(assessment, 'compliance_score'):
            compliance_score = assessment.compliance_score
        else:
            # Calculate based on risk factors
            risk_score = calculate_risk_score(assessment)
            compliance_score = max(0, 100 - risk_score)
        
        # Calculate regulatory alignment
        regulatory_alignment = 0
        if hasattr(assessment, 'regulatory_references'):
            references = assessment.regulatory_references
            if isinstance(references, list):
                alignment_per_reference = 100 / len(references) if references else 0
                regulatory_alignment = min(100, len(references) * 20)  # 20% per reference
        
        # Calculate audit readiness
        audit_readiness = 0
        if hasattr(assessment, 'documentation_completeness'):
            doc_completeness = assessment.documentation_completeness or 0
            audit_readiness = doc_completeness * 0.7  # 70% weight
        
        if hasattr(assessment, 'evidence_attached'):
            evidence_count = len(assessment.evidence_attached) if hasattr(assessment, 'evidence_attached') else 0
            audit_readiness += min(30, evidence_count * 5)  # 5% per evidence, max 30%
        
        # Determine overall status
        overall_status = 'non_compliant'
        if compliance_score >= 90:
            overall_status = 'highly_compliant'
        elif compliance_score >= 80:
            overall_status = 'compliant'
        elif compliance_score >= 70:
            overall_status = 'partially_compliant'
        
        return {
            'compliance_score': round(compliance_score, 1),
            'regulatory_alignment': round(regulatory_alignment, 1),
            'audit_readiness': round(audit_readiness, 1),
            'overall_status': overall_status,
            'status_display': overall_status.replace('_', ' ').title(),
            'last_calculated': datetime.utcnow().isoformat()
        }
    
    except Exception as e:
        logger.error(f"Error calculating compliance metrics: {str(e)}")
        return {
            'compliance_score': 0,
            'regulatory_alignment': 0,
            'audit_readiness': 0,
            'overall_status': 'unknown',
            'error': str(e)
        }

def generate_predictive_insights(assessment):
    """Generate predictive insights"""
    try:
        if not assessment:
            return {
                'likely_issues': [],
                'preventive_actions': [],
                'risk_forecast': 'unknown',
                'confidence': 'low'
            }
        
        # Analyze risk areas to predict likely issues
        risk_areas = identify_risk_areas(assessment)
        likely_issues = []
        
        # Map risk areas to likely issues
        risk_issue_map = {
            'workplace_safety': ['slip_and_fall', 'ergonomic_issues', 'fire_hazards'],
            'data_security': ['data_breach', 'unauthorized_access', 'data_loss'],
            'equipment_safety': ['equipment_failure', 'maintenance_backlog', 'safety_checks_missed'],
            'employee_health': ['stress_burnout', 'workplace_injuries', 'illness_outbreaks'],
            'environmental': ['waste_management', 'chemical_exposure', 'air_quality']
        }
        
        for area in risk_areas:
            if area in risk_issue_map:
                likely_issues.extend(risk_issue_map[area])
        
        # Remove duplicates
        likely_issues = list(set(likely_issues))[:5]  # Limit to top 5
        
        # Generate preventive actions based on issues
        preventive_actions = []
        for issue in likely_issues:
            if issue == 'slip_and_fall':
                preventive_actions.append('Implement regular floor inspections')
                preventive_actions.append('Provide anti-slip footwear')
            elif issue == 'data_breach':
                preventive_actions.append('Enhance access controls')
                preventive_actions.append('Conduct security training')
            elif issue == 'equipment_failure':
                preventive_actions.append('Schedule preventive maintenance')
                preventive_actions.append('Implement equipment monitoring')
            elif issue == 'stress_burnout':
                preventive_actions.append('Implement wellness programs')
                preventive_actions.append('Monitor workload distribution')
        
        # Determine risk forecast
        risk_score = calculate_risk_score(assessment)
        if risk_score < 30:
            risk_forecast = 'improving'
        elif risk_score < 60:
            risk_forecast = 'stable'
        else:
            risk_forecast = 'worsening'
        
        # Calculate confidence based on data completeness
        confidence = 'medium'
        if hasattr(assessment, 'data_completeness'):
            if assessment.data_completeness > 80:
                confidence = 'high'
            elif assessment.data_completeness > 50:
                confidence = 'medium'
            else:
                confidence = 'low'
        
        return {
            'likely_issues': likely_issues,
            'preventive_actions': preventive_actions[:5],  # Limit to top 5
            'risk_forecast': risk_forecast,
            'confidence': confidence,
            'forecast_period': '30_days',
            'generated_at': datetime.utcnow().isoformat()
        }
    
    except Exception as e:
        logger.error(f"Error generating predictive insights: {str(e)}")
        return {
            'likely_issues': [],
            'preventive_actions': [],
            'risk_forecast': 'unknown',
            'confidence': 'low',
            'error': str(e)
        }

def get_risk_indicators(assessment_id):
    """Get risk indicators for assessment"""
    try:
        assessment = RiskAssessment.query.get(assessment_id)
        if not assessment:
            return {
                'trend': 'unknown',
                'severity': 'unknown',
                'volatility': 'unknown',
                'data_points': 0
            }
        
        # Get assessment history for trend analysis
        history = RiskAssessmentHistory.query.filter_by(
            assessment_id=assessment_id
        ).order_by(RiskAssessmentHistory.created_at).all()
        
        if len(history) < 2:
            return {
                'trend': 'stable',
                'severity': get_risk_level_from_score(calculate_risk_score(assessment)),
                'volatility': 'low',
                'data_points': 1,
                'confidence': 'low'
            }
        
        # Extract risk scores from history
        risk_scores = []
        for h in history:
            if hasattr(h, 'changes'):
                risk_score = h.changes.get('overall_risk_score')
                if risk_score:
                    risk_scores.append(risk_score)
        
        # Add current risk score
        current_score = calculate_risk_score(assessment)
        risk_scores.append(current_score)
        
        # Calculate trend
        if len(risk_scores) >= 3:
            recent_avg = sum(risk_scores[-3:]) / 3
            older_avg = sum(risk_scores[:3]) / 3
            
            if recent_avg > older_avg + 5:
                trend = 'increasing'
            elif recent_avg < older_avg - 5:
                trend = 'decreasing'
            else:
                trend = 'stable'
        else:
            trend = 'stable'
        
        # Calculate volatility (standard deviation)
        if len(risk_scores) >= 2:
            mean = sum(risk_scores) / len(risk_scores)
            variance = sum((x - mean) ** 2 for x in risk_scores) / len(risk_scores)
            std_dev = variance ** 0.5
            
            if std_dev > 15:
                volatility = 'high'
            elif std_dev > 5:
                volatility = 'medium'
            else:
                volatility = 'low'
        else:
            volatility = 'low'
        
        # Determine severity
        severity = get_risk_level_from_score(current_score)
        
        return {
            'trend': trend,
            'severity': severity,
            'volatility': volatility,
            'current_score': round(current_score, 1),
            'average_score': round(sum(risk_scores) / len(risk_scores), 1),
            'score_range': f"{min(risk_scores):.1f}-{max(risk_scores):.1f}",
            'data_points': len(risk_scores),
            'confidence': 'high' if len(risk_scores) >= 5 else 'medium'
        }
    
    except Exception as e:
        logger.error(f"Error getting risk indicators for {assessment_id}: {str(e)}")
        return {
            'trend': 'unknown',
            'severity': 'unknown',
            'volatility': 'unknown',
            'data_points': 0,
            'error': str(e)
        }

def get_compliance_status(assessment_id):
    """Get compliance status for assessment"""
    try:
        assessment = RiskAssessment.query.get(assessment_id)
        if not assessment:
            return {
                'status': 'unknown',
                'score': 0,
                'last_audit': None,
                'next_audit': None
            }
        
        # Calculate compliance metrics
        compliance_metrics = calculate_compliance_metrics(assessment)
        
        # Get last audit date
        last_audit = None
        if hasattr(assessment, 'last_audit_date'):
            last_audit = assessment.last_audit_date
        elif hasattr(assessment, 'audit_dates'):
            if assessment.audit_dates:
                last_audit = max(assessment.audit_dates)
        
        # Calculate next audit date
        next_audit = None
        if last_audit:
            if isinstance(last_audit, str):
                last_audit = datetime.fromisoformat(last_audit.replace('Z', '+00:00'))
            next_audit = last_audit + timedelta(days=365)  # Annual audit
            
            # Check if overdue
            days_until = (next_audit - datetime.utcnow()).days
            if days_until < 0:
                compliance_status = 'audit_overdue'
            elif days_until <= 30:
                compliance_status = 'audit_due_soon'
            else:
                compliance_status = compliance_metrics['overall_status']
        else:
            compliance_status = compliance_metrics['overall_status']
        
        return {
            'status': compliance_status,
            'score': compliance_metrics['compliance_score'],
            'last_audit': last_audit.isoformat() if last_audit else None,
            'next_audit': next_audit.isoformat() if next_audit else None,
            'days_until_next_audit': (next_audit - datetime.utcnow()).days if next_audit else None,
            'regulatory_alignment': compliance_metrics['regulatory_alignment'],
            'audit_readiness': compliance_metrics['audit_readiness']
        }
    
    except Exception as e:
        logger.error(f"Error getting compliance status for {assessment_id}: {str(e)}")
        return {
            'status': 'unknown',
            'score': 0,
            'last_audit': None,
            'next_audit': None,
            'error': str(e)
        }

def calculate_risk_score(assessment):
    """Calculate risk score for assessment (0-100)"""
    try:
        if not assessment:
            return 0
        
        # If risk score is already calculated, return it
        if hasattr(assessment, 'overall_risk_score') and assessment.overall_risk_score:
            return assessment.overall_risk_score
        
        # Calculate based on available attributes
        score = 50  # Default medium risk
        
        # Adjust based on risk level
        if hasattr(assessment, 'overall_risk_level'):
            risk_level = assessment.overall_risk_level
            if risk_level:
                risk_level = risk_level.lower()
                if risk_level == 'critical':
                    score = 85
                elif risk_level == 'high':
                    score = 70
                elif risk_level == 'medium':
                    score = 50
                elif risk_level == 'low':
                    score = 30
                elif risk_level == 'very_low':
                    score = 15
        
        # Adjust based on number of high-risk findings
        if hasattr(assessment, 'high_risk_findings'):
            score += min(20, assessment.high_risk_findings * 5)
        
        # Adjust based on overdue actions
        if hasattr(assessment, 'overdue_actions'):
            score += min(15, assessment.overdue_actions * 3)
        
        # Cap at 100
        return min(100, max(0, score))
    
    except Exception as e:
        logger.error(f"Error calculating risk score: {str(e)}")
        return 50  # Return medium risk on error

def identify_risk_areas(assessment):
    """Identify risk areas in assessment"""
    try:
        if not assessment:
            return []
        
        risk_areas = []
        
        # Check common risk area attributes
        area_checks = [
            ('has_workplace_safety_issues', 'workplace_safety'),
            ('has_data_security_issues', 'data_security'),
            ('has_equipment_safety_issues', 'equipment_safety'),
            ('has_employee_health_issues', 'employee_health'),
            ('has_environmental_issues', 'environmental'),
            ('has_fire_safety_issues', 'fire_safety'),
            ('has_chemical_safety_issues', 'chemical_safety'),
            ('has_biological_safety_issues', 'biological_safety'),
            ('has_ergonomic_issues', 'ergonomic'),
            ('has_electrical_safety_issues', 'electrical_safety')
        ]
        
        for attr_name, area_name in area_checks:
            if hasattr(assessment, attr_name):
                if getattr(assessment, attr_name):
                    risk_areas.append(area_name)
        
        # If no specific attributes, infer from assessment data
        if not risk_areas:
            if hasattr(assessment, 'assessment_data'):
                data = assessment.assessment_data
                if isinstance(data, dict):
                    # Check for keywords in assessment data
                    keywords = {
                        'workplace': 'workplace_safety',
                        'data': 'data_security',
                        'equipment': 'equipment_safety',
                        'health': 'employee_health',
                        'environment': 'environmental',
                        'fire': 'fire_safety',
                        'chemical': 'chemical_safety',
                        'bio': 'biological_safety',
                        'ergo': 'ergonomic',
                        'electrical': 'electrical_safety'
                    }
                    
                    import json
                    data_str = json.dumps(data).lower()
                    
                    for keyword, area in keywords.items():
                        if keyword in data_str:
                            risk_areas.append(area)
        
        # Remove duplicates
        risk_areas = list(set(risk_areas))
        
        return risk_areas[:5]  # Return top 5 risk areas
    
    except Exception as e:
        logger.error(f"Error identifying risk areas: {str(e)}")
        return []

