@app.route('/api/payment/manual/initialize', methods=['POST'])
@jwt_required
def initialize_manual_payment():
    """Initialize a manual payment (for MoMo and Bank transfers without API)"""
    try:
        data = request.get_json()
        user = request.user
        
        # Validate required fields
        required_fields = ['plan', 'duration', 'amount', 'payment_method_id']
        for field in required_fields:
            if field not in data:
                return jsonify({'error': f'Missing required field: {field}'}), 400
        
        # Validate amount
        try:
            amount = float(data['amount'])
            if amount <= 0:
                return jsonify({'error': 'Amount must be greater than 0'}), 400
        except ValueError:
            return jsonify({'error': 'Invalid amount format'}), 400
        
        # Generate unique reference
        reference = f"MANUAL-{user.id}-{int(time.time())}-{uuid.uuid4().hex[:8].upper()}"
        
        # Get payment method details from your manual list
        payment_method = get_manual_payment_method(data['payment_method_id'])
        if not payment_method:
            return jsonify({'error': 'Invalid payment method'}), 400
        
        # Prepare metadata with user info from JWT
        metadata = {
            'user_id': user.id,
            'user_email': user.email,
            'user_name': f"{user.first_name} {user.last_name}".strip() or user.email,
            'user_phone': data.get('phone', ''),
            'plan': data['plan'],
            'duration': data['duration'],
            'amount': amount,
            'currency': 'GHS',
            'payment_method_id': data['payment_method_id'],
            'payment_method_name': payment_method['name'],
            'payment_details': payment_method['details'],
            'current_plan': request.effective_plan,
            'timestamp': datetime.utcnow().isoformat(),
            'user_agent': request.headers.get('User-Agent', 'Unknown'),
            'ip_address': request.remote_addr
        }
        
        # Create transaction record
        transaction = PaymentTransaction(
            user_id=user.id,
            plan=data['plan'],
            duration=data['duration'],
            amount=amount,
            currency='GHS',
            payment_method=f"MANUAL_{data['payment_method_id']}",
            transaction_reference=reference,
            status='awaiting_payment',  # Waiting for user to send money
            metadata=json.dumps(metadata)
        )
        db.session.add(transaction)
        db.session.commit()
        
        # Log the payment initialization
        logger.info(f"Manual payment initialized: {reference} - User: {user.email} - Amount: GHS {amount}")
        
        return jsonify({
            'success': True,
            'reference': reference,
            'payment_method': {
                'id': payment_method['id'],
                'name': payment_method['name'],
                'details': payment_method['details'],
                'instructions': payment_method['instructions']
            },
            'amount': amount,
            'currency': 'GHS',
            'status': 'awaiting_payment',
            'message': f"Please send exactly GHS {amount:,.2f} using the instructions below",
            'expires_at': (datetime.utcnow() + timedelta(hours=48)).isoformat(),  # 48 hours to pay
            'user_email': user.email  # Include email for reference
        }), 201
        
    except Exception as e:
        logger.error(f"Manual payment initialization error: {e}")
        db.session.rollback()
        return jsonify({'error': str(e)}), 500




