def calculate_activation_estimate(transaction):
    """Calculate when plan will be activated"""
    if transaction.status == 'completed':
        return 'Already activated'
    elif transaction.status == 'pending_verification':
        return 'Within 24 hours after verification'
    elif transaction.status == 'awaiting_payment':
        if hasattr(transaction, 'confirmed_at') and transaction.confirmed_at:
            return 'Pending verification'
        else:
            return 'After payment is confirmed'
    else:
        return 'Pending'

@app.route('/api/payment/paypal/create', methods=['POST'])
@jwt_required
def create_paypal_payment():
    """Create PayPal payment for plan upgrade"""
    try:
        data = request.get_json()
        user = request.user
        
        # Validate required fields
        required_fields = ['plan', 'duration', 'amount', 'currency']
        for field in required_fields:
            if field not in data:
                return jsonify({'error': f'Missing required field: {field}'}), 400
        
        # Get user details
        user_id = user.id
        user_email = user.email
        user_name = user.name or user.email
        
        # Get plan and amount details
        plan = data['plan']
        duration = data['duration']
        amount = float(data['amount'])
        currency = data['currency'].upper()
        
        # Validate amount
        if amount <= 0:
            return jsonify({'error': 'Invalid amount'}), 400
        
        # PayPal supported currencies
        supported_currencies = ['USD', 'EUR', 'GBP', 'CAD', 'AUD', 'JPY', 'SGD', 'CHF', 'NZD', 
                               'BRL', 'CZK', 'DKK', 'HKD', 'HUF', 'ILS', 'MXN', 'MYR', 'NOK', 
                               'PHP', 'PLN', 'SEK', 'THB', 'TWD']
        
        # Handle currency conversion if needed
        original_currency = currency
        original_amount = amount
        
        if currency not in supported_currencies:
            if currency == 'GHS':
                try:
                    import requests
                    response = requests.get('https://api.exchangerate-api.com/v4/latest/USD')
                    exchange_data = response.json()
                    usd_to_ghs = exchange_data['rates'].get('GHS', 12.0)
                    paypal_amount = round(amount / usd_to_ghs, 2)
                    paypal_currency = 'USD'
                    logging.info(f"Converted {currency} {amount} to USD {paypal_amount} (rate: {usd_to_ghs})")
                except Exception as e:
                    logging.error(f"Exchange rate fetch failed: {e}")
                    usd_to_ghs = 12.0
                    paypal_amount = round(amount / usd_to_ghs, 2)
                    paypal_currency = 'USD'
            else:
                return jsonify({
                    'success': False,
                    'error': f'Currency {currency} is not supported by PayPal',
                    'supported_currencies': supported_currencies
                }), 400
        else:
            paypal_amount = amount
            paypal_currency = currency
        
        # Generate unique transaction ID
        transaction_id = f"PAYPAL-{user_id}-{int(time.time())}-{uuid.uuid4().hex[:8].upper()}"
        
        # Get frontend URL for redirects
        frontend_url = app.config.get('FRONTEND_URL', 'http://localhost:3000')
        
        # ✅ FIX: Shorten the custom data - keep it under 256 characters
        # Store only essential data in the custom field
        custom_data = {
            'u': user_id,  # user_id (shortened key)
            't': transaction_id,  # transaction_id (shortened key)
            'p': plan,  # plan
            'd': duration,  # duration
            'c': original_currency,  # original_currency (shortened key)
            'a': original_amount  # original_amount (shortened key)
        }
        custom_json = json.dumps(custom_data)
        
        # Ensure it's under 256 characters
        if len(custom_json) > 256:
            # If still too long, remove less critical data
            custom_data = {
                'u': user_id,
                't': transaction_id,
                'p': plan,
                'd': duration
            }
            custom_json = json.dumps(custom_data)
            logging.warning(f"Custom data shortened to {len(custom_json)} chars")
        
        logging.info(f"Custom data length: {len(custom_json)} characters")
        
        # Create PayPal payment
        payment = paypalrestsdk.Payment({
            "intent": "sale",
            "payer": {
                "payment_method": "paypal"
            },
            "redirect_urls": {
                "return_url": f"{request.host_url.rstrip('/')}/api/payment/paypal/execute",
                "cancel_url": f"{frontend_url}/payment-cancel"
            },
            "transactions": [{
                "item_list": {
                    "items": [{
                        "name": f"{plan.upper()} Plan - {duration.replace('_', ' ').title()[:20]}",  # Limit name length
                        "sku": f"{plan[:3]}_{duration[:5]}",  # Shorten SKU
                        "price": str(paypal_amount),
                        "currency": paypal_currency,
                        "quantity": 1
                    }]
                },
                "amount": {
                    "total": str(paypal_amount),
                    "currency": paypal_currency
                },
                "description": f"{plan.upper()} Plan - {duration.replace('_', ' ').title()}",  # Shorten description
                "custom": custom_json  # ✅ Use shortened custom data
            }]
        })
        
        # Create payment
        if payment.create():
            # Save full payment details in database
            db_payment = Payment(
                user_id=user_id,
                amount=original_amount,
                currency=original_currency,
                plan=plan,
                duration=duration,
                payment_method='paypal',
                status='pending',
                transaction_id=transaction_id,
                paystack_reference=None,
                payment_details=json.dumps({
                    'paypal_payment_id': payment.id,
                    'paypal_currency': paypal_currency,
                    'paypal_amount': paypal_amount,
                    'original_currency': original_currency,
                    'original_amount': original_amount,
                    'metadata': data.get('metadata', {})
                }),
                created_at=datetime.utcnow()
            )
            db.session.add(db_payment)
            db.session.commit()
            
            # Save to PaymentHistory
            payment_history = PaymentHistory(
                user_id=user_id,
                plan=plan,
                billing_cycle=duration,
                country=data.get('country', user.country or 'Ghana'),
                currency=original_currency,
                amount=original_amount,
                payment_method='paypal',
                payment_gateway='paypal',
                payment_id=transaction_id,
                status='pending',
                gateway_response={
                    'paypal_payment_id': payment.id,
                    'paypal_currency': paypal_currency,
                    'paypal_amount': paypal_amount
                },
                created_at=datetime.utcnow()
            )
            db.session.add(payment_history)
            db.session.commit()
            
            # Find approval URL
            approval_url = None
            for link in payment.links:
                if link.rel == "approval_url":
                    approval_url = link.href
                    break
            
            logging.info(f"✅ PayPal payment created: {payment.id}")
            logging.info(f"   User: {user_email}")
            logging.info(f"   Original: {original_currency} {original_amount}")
            logging.info(f"   PayPal: {paypal_currency} {paypal_amount}")
            
            return jsonify({
                'success': True,
                'payment_id': payment.id,
                'approval_url': approval_url,
                'transaction_id': transaction_id,
                'original_currency': original_currency,
                'original_amount': original_amount,
                'paypal_currency': paypal_currency,
                'paypal_amount': paypal_amount
            }), 200
        else:
            logging.error(f"❌ PayPal payment creation failed: {payment.error}")
            return jsonify({
                'success': False,
                'error': payment.error.get('message', 'Payment creation failed')
            }), 400
            
    except Exception as e:
        logging.error(f"❌ PayPal payment creation error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/payment/paypal/execute', methods=['GET'])
def execute_paypal_payment():
    """Execute PayPal payment after approval"""
    try:
        # Get payment ID and payer ID from query params
        payment_id = request.args.get('paymentId')
        payer_id = request.args.get('PayerID')
        
        frontend_url = app.config.get('FRONTEND_URL', 'http://localhost:3000')
        
        if not payment_id or not payer_id:
            return redirect(f"{frontend_url}/payment-failed?error=missing_params")
        
        # Execute the payment
        payment = paypalrestsdk.Payment.find(payment_id)
        
        if payment.execute({"payer_id": payer_id}):
            # Payment successful
            logging.info(f"✅ PayPal payment executed: {payment_id}")
            
            # Get custom data from payment (shortened format)
            custom_data = json.loads(payment.transactions[0].custom)
            
            # Extract data from shortened format
            transaction_id = custom_data.get('t') or custom_data.get('transaction_id')
            user_id = custom_data.get('u') or custom_data.get('user_id')
            plan = custom_data.get('p') or custom_data.get('plan')
            duration = custom_data.get('d') or custom_data.get('duration')
            original_currency = custom_data.get('c') or custom_data.get('original_currency')
            original_amount = custom_data.get('a') or custom_data.get('original_amount')
            
            # Update payment record
            db_payment = Payment.query.filter_by(transaction_id=transaction_id).first()
            if db_payment:
                db_payment.status = 'completed'
                db_payment.completed_at = datetime.utcnow()
                db_payment.payment_details = json.dumps({
                    **(json.loads(db_payment.payment_details) if db_payment.payment_details else {}),
                    'paypal_payment_id': payment_id,
                    'payer_id': payer_id,
                    'executed': True
                })
                db.session.commit()
                
                # Update payment history
                payment_history = PaymentHistory.query.filter_by(payment_id=transaction_id).first()
                if payment_history:
                    payment_history.status = 'completed'
                    payment_history.paid_at = datetime.utcnow()
                    payment_history.gateway_response = {'paypal_payment_id': payment_id}
                    db.session.commit()
                
                # Update user's subscription
                user = User.query.get(db_payment.user_id)
                if user:
                    user.subscription_plan = db_payment.plan
                    user.subscription_status = 'active'
                    user.billing_cycle = db_payment.duration
                    user.last_payment_date = datetime.utcnow()
                    
                    # Calculate expiry
                    if db_payment.duration == '1_month':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=30)
                    elif db_payment.duration == '6_month':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=180)
                    elif db_payment.duration == '1_year':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=365)
                    
                    db.session.commit()
                    
                    # Create or update subscription record
                    existing_sub = Subscription.query.filter_by(user_id=user.id).first()
                    if existing_sub:
                        existing_sub.plan = db_payment.plan
                        existing_sub.status = 'active'
                        existing_sub.end_date = user.subscription_ends_at
                        existing_sub.last_payment_date = datetime.utcnow()
                        existing_sub.next_payment_date = user.subscription_ends_at
                        existing_sub.payment_method = 'paypal'
                    else:
                        new_sub = Subscription(
                            user_id=user.id,
                            plan=db_payment.plan,
                            status='active',
                            start_date=datetime.utcnow(),
                            end_date=user.subscription_ends_at,
                            auto_renew=True,
                            payment_method='paypal',
                            last_payment_date=datetime.utcnow(),
                            next_payment_date=user.subscription_ends_at
                        )
                        db.session.add(new_sub)
                    db.session.commit()
                    
                    # Record subscription history
                    sub_history = SubscriptionHistory(
                        user_id=user.id,
                        old_plan='free',
                        new_plan=db_payment.plan,
                        billing_cycle=db_payment.duration,
                        country=user.country or 'default',
                        currency=db_payment.currency,
                        amount=db_payment.amount,
                        change_type='upgrade',
                        change_reason='Payment completed via PayPal',
                        effective_date=datetime.utcnow()
                    )
                    db.session.add(sub_history)
                    db.session.commit()
                    
                    logging.info(f"✅ User {user.email} upgraded to {db_payment.plan} via PayPal")
            
            return redirect(f"{frontend_url}/payment-success?reference={transaction_id}")
        else:
            # Payment execution failed
            logging.error(f"❌ PayPal payment execution failed: {payment.error}")
            return redirect(f"{frontend_url}/payment-failed?error=execution_failed")
            
    except Exception as e:
        logging.error(f"❌ PayPal execute error: {e}")
        import traceback
        traceback.print_exc()
        frontend_url = app.config.get('FRONTEND_URL', 'http://localhost:3000')
        return redirect(f"{frontend_url}/payment-failed?error=execute_error")

@app.route('/api/payment/paypal/webhook', methods=['POST'])
def paypal_webhook():
    """Handle PayPal webhook events"""
    try:
        # Get webhook event
        event = request.get_json()
        
        if not event:
            return jsonify({'error': 'Invalid payload'}), 400
        
        event_type = event.get('event_type')
        logging.info(f"📨 PayPal webhook received: {event_type}")
        
        if event_type == 'PAYMENT.SALE.COMPLETED':
            # Handle successful payment
            resource = event.get('resource', {})
            custom_data = json.loads(resource.get('custom', '{}'))
            transaction_id = custom_data.get('transaction_id')
            
            if transaction_id:
                # Update payment status
                payment = Payment.query.filter_by(transaction_id=transaction_id).first()
                if payment and payment.status != 'completed':
                    payment.status = 'completed'
                    payment.completed_at = datetime.utcnow()
                    payment.payment_details = json.dumps({
                        **(json.loads(payment.payment_details) if payment.payment_details else {}),
                        'webhook_event': event
                    })
                    db.session.commit()
                    
                    logging.info(f"✅ PayPal webhook: Payment completed for {transaction_id}")
        
        elif event_type == 'PAYMENT.SALE.DENIED':
            # Handle denied payment
            resource = event.get('resource', {})
            custom_data = json.loads(resource.get('custom', '{}'))
            transaction_id = custom_data.get('transaction_id')
            
            if transaction_id:
                payment = Payment.query.filter_by(transaction_id=transaction_id).first()
                if payment:
                    payment.status = 'failed'
                    payment.failure_reason = 'Payment denied'
                    db.session.commit()
                    
                    logging.warning(f"⚠️ PayPal webhook: Payment denied for {transaction_id}")
        
        elif event_type == 'PAYMENT.SALE.REFUNDED':
            # Handle refund
            resource = event.get('resource', {})
            custom_data = json.loads(resource.get('custom', '{}'))
            transaction_id = custom_data.get('transaction_id')
            
            if transaction_id:
                payment = Payment.query.filter_by(transaction_id=transaction_id).first()
                if payment:
                    payment.status = 'refunded'
                    db.session.commit()
                    
                    logging.info(f"💰 PayPal webhook: Payment refunded for {transaction_id}")
        
        return jsonify({'status': 'success'}), 200
        
    except Exception as e:
        logging.error(f"❌ PayPal webhook error: {e}")
        return jsonify({'error': str(e)}), 500


@app.route('/api/payment/paypal/status/<transaction_id>', methods=['GET'])
@jwt_required
def paypal_payment_status(transaction_id):
    """Check PayPal payment status"""
    try:
        user = request.user
        
        # Find payment
        payment = Payment.query.filter_by(transaction_id=transaction_id).first()
        
        if not payment:
            return jsonify({'error': 'Payment not found'}), 404
        
        # Check ownership
        if payment.user_id != user.id:
            return jsonify({'error': 'Unauthorized'}), 403
        
        return jsonify({
            'success': True,
            'status': payment.status,
            'payment': {
                'transaction_id': payment.transaction_id,
                'plan': payment.plan,
                'amount': payment.amount,
                'currency': payment.currency,
                'created_at': payment.created_at.isoformat() if payment.created_at else None,
                'completed_at': payment.completed_at.isoformat() if payment.completed_at else None
            }
        }), 200
        
    except Exception as e:
        logging.error(f"❌ PayPal status error: {e}")
        return jsonify({'error': str(e)}), 500

