@app.route('/api/payment/paypal/create/public', methods=['POST'])
def create_paypal_payment_public():
    """Create PayPal payment - PUBLIC endpoint for signup (no JWT required)"""
    try:
        data = request.get_json()
        
        # Validate required fields
        required_fields = ['plan', 'duration', 'amount', 'currency', 'email']
        for field in required_fields:
            if field not in data:
                return jsonify({'error': f'Missing required field: {field}'}), 400
        
        # Get user details from request (not from JWT)
        user_email = data['email']
        user_name = data.get('name', user_email)
        user_id = data.get('user_id')  # Optional, will be set during registration
        
        # Get plan and amount details
        plan = data['plan']
        duration = data['duration']
        amount = float(data['amount'])
        currency = data['currency'].upper()
        
        # Validate amount
        if amount <= 0:
            return jsonify({'error': 'Invalid amount'}), 400
        
        # PayPal supported currencies
        supported_currencies = ['USD', 'EUR', 'GBP', 'CAD', 'AUD', 'JPY', 'SGD', 'CHF', 'NZD', 
                               'BRL', 'CZK', 'DKK', 'HKD', 'HUF', 'ILS', 'MXN', 'MYR', 'NOK', 
                               'PHP', 'PLN', 'SEK', 'THB', 'TWD']
        
        # Handle currency conversion if needed
        original_currency = currency
        original_amount = amount
        
        if currency not in supported_currencies:
            if currency == 'GHS':
                try:
                    import requests
                    response = requests.get('https://api.exchangerate-api.com/v4/latest/USD')
                    exchange_data = response.json()
                    usd_to_ghs = exchange_data['rates'].get('GHS', 12.0)
                    paypal_amount = round(amount / usd_to_ghs, 2)
                    paypal_currency = 'USD'
                    logging.info(f"Converted {currency} {amount} to USD {paypal_amount} (rate: {usd_to_ghs})")
                except Exception as e:
                    logging.error(f"Exchange rate fetch failed: {e}")
                    usd_to_ghs = 12.0
                    paypal_amount = round(amount / usd_to_ghs, 2)
                    paypal_currency = 'USD'
            else:
                return jsonify({
                    'success': False,
                    'error': f'Currency {currency} is not supported by PayPal',
                    'supported_currencies': supported_currencies
                }), 400
        else:
            paypal_amount = amount
            paypal_currency = currency
        
        # Generate unique transaction ID - mark as signup
        transaction_id = f"PAYPAL-SIGNUP-{int(time.time())}-{uuid.uuid4().hex[:8].upper()}"
        
        # Get frontend URL for redirects
        frontend_url = app.config.get('FRONTEND_URL', 'http://localhost:3000')
        
        # Store data in shortened format for custom field
        custom_data = {
            'u': user_id or 0,  # user_id (0 for signup, will be updated later)
            't': transaction_id,
            'p': plan,
            'd': duration,
            'c': original_currency,
            'a': original_amount,
            'e': user_email[:30],  # email (shortened for space)
            's': 1  # signup flag
        }
        custom_json = json.dumps(custom_data)
        
        # Ensure it's under 256 characters
        if len(custom_json) > 256:
            custom_data = {
                't': transaction_id,
                'p': plan,
                'd': duration,
                'e': user_email[:20],
                's': 1
            }
            custom_json = json.dumps(custom_data)
        
        logging.info(f"PayPal signup custom data length: {len(custom_json)} chars")
        
        # Check if we should use mock mode
        use_mock = app.config.get('PAYPAL_MOCK_MODE', True)
        
        if use_mock:
            logging.warning("PayPal running in MOCK mode - no real charges will be processed")
            
            # Store payment in session for later association
            session['pending_payment'] = {
                'email': user_email,
                'reference': transaction_id,
                'amount': original_amount,
                'currency': original_currency,
                'plan': plan,
                'duration': duration,
                'payment_method': 'paypal_mock',
                'created_at': datetime.utcnow().isoformat(),
                'signup': True
            }
            
            return jsonify({
                'success': True,
                'payment_id': f'mock_{transaction_id}',
                'approval_url': f"{frontend_url}/mock-payment?reference={transaction_id}&email={user_email}&method=paypal",
                'transaction_id': transaction_id,
                'mock': True,
                'message': 'Mock PayPal payment initialized (Testing mode)',
                'signup_mode': True
            }), 200
        
        # ✅ LIVE MODE - Create PayPal payment
        if not app.config.get('PAYPAL_CLIENT_ID') or not app.config.get('PAYPAL_CLIENT_SECRET'):
            return jsonify({
                'success': False,
                'error': 'PayPal credentials not configured'
            }), 500
        
        # Create PayPal payment
        payment = paypalrestsdk.Payment({
            "intent": "sale",
            "payer": {
                "payment_method": "paypal"
            },
            "redirect_urls": {
                "return_url": f"{request.host_url.rstrip('/')}/api/payment/paypal/execute/public",
                "cancel_url": f"{frontend_url}/payment-cancel"
            },
            "transactions": [{
                "item_list": {
                    "items": [{
                        "name": f"{plan.upper()} Plan - {duration.replace('_', ' ').title()[:20]}",
                        "sku": f"signup_{plan[:3]}_{duration[:5]}",
                        "price": str(paypal_amount),
                        "currency": paypal_currency,
                        "quantity": 1
                    }]
                },
                "amount": {
                    "total": str(paypal_amount),
                    "currency": paypal_currency
                },
                "description": f"{plan.upper()} Plan - Signup",
                "custom": custom_json
            }]
        })
        
        # Create payment
        if payment.create():
            # Store payment in session for later association
            session['pending_payment'] = {
                'email': user_email,
                'reference': transaction_id,
                'amount': original_amount,
                'currency': original_currency,
                'plan': plan,
                'duration': duration,
                'payment_method': 'paypal',
                'paypal_payment_id': payment.id,
                'created_at': datetime.utcnow().isoformat(),
                'signup': True
            }
            
            # Find approval URL
            approval_url = None
            for link in payment.links:
                if link.rel == "approval_url":
                    approval_url = link.href
                    break
            
            logging.info(f"✅ PayPal signup payment created: {payment.id}")
            logging.info(f"   Email: {user_email}")
            logging.info(f"   Original: {original_currency} {original_amount}")
            logging.info(f"   PayPal: {paypal_currency} {paypal_amount}")
            
            return jsonify({
                'success': True,
                'payment_id': payment.id,
                'approval_url': approval_url,
                'transaction_id': transaction_id,
                'original_currency': original_currency,
                'original_amount': original_amount,
                'paypal_currency': paypal_currency,
                'paypal_amount': paypal_amount,
                'signup_mode': True
            }), 200
        else:
            logging.error(f"❌ PayPal signup payment creation failed: {payment.error}")
            return jsonify({
                'success': False,
                'error': payment.error.get('message', 'Payment creation failed')
            }), 400
            
    except Exception as e:
        logging.error(f"❌ PayPal signup payment creation error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/payment/paypal/execute/public', methods=['GET'])
def execute_paypal_payment_public():
    """Execute PayPal payment - PUBLIC endpoint for signup"""
    try:
        # Get payment ID and payer ID from query params
        payment_id = request.args.get('paymentId')
        payer_id = request.args.get('PayerID')
        
        frontend_url = app.config.get('FRONTEND_URL', 'http://localhost:3000')
        
        if not payment_id or not payer_id:
            return redirect(f"{frontend_url}/payment-failed?error=missing_params")
        
        # Get pending payment from session
        pending_payment = session.get('pending_payment', {})
        
        # Check if this is a signup payment
        is_signup = pending_payment.get('signup', False) or 'SIGNUP' in (pending_payment.get('reference', ''))
        
        # Execute the payment
        payment = paypalrestsdk.Payment.find(payment_id)
        
        if payment.execute({"payer_id": payer_id}):
            # Payment successful
            logging.info(f"✅ PayPal payment executed: {payment_id}")
            
            # Get custom data from payment
            custom_data = json.loads(payment.transactions[0].custom)
            transaction_id = custom_data.get('t') or custom_data.get('transaction_id')
            plan = custom_data.get('p') or custom_data.get('plan')
            duration = custom_data.get('d') or custom_data.get('duration')
            user_email = custom_data.get('e') or pending_payment.get('email')
            original_amount = custom_data.get('a') or pending_payment.get('amount')
            original_currency = custom_data.get('c') or pending_payment.get('currency')
            
            if is_signup:
                # ✅ Signup payment - store in session for later registration
                session['payment_completed'] = {
                    'email': user_email,
                    'reference': transaction_id,
                    'plan': plan,
                    'duration': duration,
                    'amount': original_amount,
                    'currency': original_currency,
                    'payment_method': 'paypal',
                    'status': 'completed',
                    'completed_at': datetime.utcnow().isoformat()
                }
                
                # Clear pending payment
                if 'pending_payment' in session:
                    del session['pending_payment']
                
                session.modified = True
                
                logging.info(f"✅ PayPal signup payment completed for {user_email}")
                
                return redirect(f"{frontend_url}/payment-success?reference={transaction_id}&signup=true&email={user_email}")
            else:
                # Regular authenticated user payment flow
                # ... (existing code for authenticated users)
                return redirect(f"{frontend_url}/payment-success?reference={transaction_id}")
        else:
            logging.error(f"❌ PayPal payment execution failed: {payment.error}")
            return redirect(f"{frontend_url}/payment-failed?error=execution_failed")
            
    except Exception as e:
        logging.error(f"❌ PayPal execute error: {e}")
        import traceback
        traceback.print_exc()
        frontend_url = app.config.get('FRONTEND_URL', 'http://localhost:3000')
        return redirect(f"{frontend_url}/payment-failed?error=execute_error")

@app.route('/api/payment/paystack/initialize', methods=['POST'])
@jwt_required
def initialize_paystack_payment():
    """Initialize Paystack payment for plan upgrade"""
    try:
        data = request.get_json()
        user = request.user
        
        # Validate required fields
        required_fields = ['plan', 'duration', 'amount', 'currency']
        for field in required_fields:
            if field not in data:
                return jsonify({'error': f'Missing required field: {field}'}), 400
        
        # Get user details
        user_id = user.id
        user_email = user.email
        user_name = user.name or user.email
        
        # Get plan and amount details
        plan = data['plan']
        duration = data['duration']
        amount = float(data['amount'])
        currency = data['currency']
        
        # Validate amount
        if amount <= 0:
            return jsonify({'error': 'Invalid amount'}), 400
        
        # Generate unique reference
        reference = f"PAYSTACK-{user_id}-{int(time.time())}-{uuid.uuid4().hex[:8].upper()}"
        
        # Prepare metadata
        metadata = {
            'user_id': user_id,
            'user_email': user_email,
            'user_name': user_name,
            'plan': plan,
            'duration': duration,
            'country': data.get('country', user.country or 'Ghana'),
            'current_plan': request.effective_plan,
            'payment_method': 'paystack',
            'callback_url': data.get('callback_url', f"{request.host_url.rstrip('/')}/api/payment/paystack/callback"),
            'custom_fields': [
                {
                    'display_name': "Plan",
                    'variable_name': "plan",
                    'value': plan.upper()
                },
                {
                    'display_name': "Duration",
                    'variable_name': "duration",
                    'value': duration.replace('_', ' ').title()
                },
                {
                    'display_name': "User ID",
                    'variable_name': "user_id",
                    'value': str(user_id)
                }
            ]
        }
        
        # Check if we should use live or mock mode
        use_mock = app.config.get('PAYSTACK_MOCK_MODE', True)
        
        if use_mock:
            # Mock mode - development
            logger.warning("Paystack running in MOCK mode - no real charges will be processed")
            
            # Create mock payment record
            payment = Payment(
                user_id=user_id,
                amount=amount,
                currency=currency,
                plan=plan,
                duration=duration,
                payment_method='paystack_mock',
                status='pending',
                transaction_id=reference,
                paystack_reference=reference,
                payment_details=json.dumps({
                    'metadata': metadata,
                    'mock': True
                }),
                created_at=datetime.utcnow()
            )
            db.session.add(payment)
            db.session.commit()
            
            return jsonify({
                'success': True,
                'authorization_url': f"{app.config.get('FRONTEND_URL', 'http://localhost:3000')}/mock-payment?reference={reference}",
                'reference': reference,
                'access_code': f"mock_access_{reference}",
                'mock': True,
                'message': 'Mock payment initialized (Testing mode)',
                'payment_id': payment.id
            }), 200
        
        # LIVE MODE - Process real payment with Paystack
        if not app.config.get('PAYSTACK_SECRET_KEY'):
            return jsonify({
                'success': False,
                'error': 'Paystack secret key not configured. Please set PAYSTACK_SECRET_KEY in environment variables.'
            }), 500
        
        # Check if Paystack SDK is available
        if not PAYSTACK_AVAILABLE or not paystack:
            return jsonify({
                'success': False,
                'error': 'Paystack SDK not available. Please install paystack python package.'
            }), 500
        
        try:
            # Convert amount to kobo/cents (Paystack uses smallest currency unit)
            amount_in_kobo = int(amount * 100)
            
            # Initialize transaction with Paystack
            response = paystack.transaction.initialize(
                email=user_email,
                amount=amount_in_kobo,
                currency=currency,
                reference=reference,
                callback_url=metadata['callback_url'],
                metadata=metadata,
                channels=['card', 'bank', 'ussd', 'qr', 'mobile_money', 'bank_transfer']
            )
            
            if response['status']:
                # Save payment record
                payment = Payment(
                    user_id=user_id,
                    amount=amount,
                    currency=currency,
                    plan=plan,
                    duration=duration,
                    payment_method='paystack',
                    status='pending',
                    transaction_id=reference,
                    paystack_reference=response['data']['reference'],
                    payment_details=json.dumps({
                        'metadata': metadata,
                        'gateway_response': response['data']
                    }),
                    created_at=datetime.utcnow()
                )
                db.session.add(payment)
                db.session.commit()
                
                # Save to PaymentHistory
                payment_history = PaymentHistory(
                    user_id=user_id,
                    plan=plan,
                    billing_cycle=duration,
                    country=data.get('country', user.country or 'Ghana'),
                    currency=currency,
                    amount=amount,
                    payment_method='paystack',
                    payment_gateway='paystack',
                    payment_id=reference,
                    status='pending',
                    gateway_response=response['data'],
                    created_at=datetime.utcnow()
                )
                db.session.add(payment_history)
                db.session.commit()
                
                logger.info(f"Paystack live payment initialized: {reference} - User: {user_email} - Amount: {currency} {amount}")
                
                return jsonify({
                    'success': True,
                    'authorization_url': response['data']['authorization_url'],
                    'reference': response['data']['reference'],
                    'access_code': response['data']['access_code'],
                    'payment_id': payment.id,
                    'message': 'Payment initialized successfully'
                }), 200
            else:
                logger.error(f"Paystack initialization failed: {response.get('message', 'Unknown error')}")
                return jsonify({
                    'success': False,
                    'error': response.get('message', 'Payment initialization failed'),
                    'code': 'PAYSTACK_ERROR'
                }), 400
                
        except Exception as paystack_error:
            logger.error(f"Paystack API error: {paystack_error}")
            return jsonify({
                'success': False,
                'error': 'Payment gateway error. Please try again.',
                'code': 'PAYMENT_GATEWAY_ERROR'
            }), 500
            
    except Exception as e:
        logger.error(f"Paystack initialization error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/payment/paystack/public-callback', methods=['GET'])
def paystack_public_callback():
    """Handle Paystack payment callback"""
    try:
        reference = request.args.get('reference')
        
        if not reference:
            return redirect(f"{app.config.get('FRONTEND_URL', 'http://localhost:3000')}/payment-failed?error=no_reference")
        
        # Find payment in your database
        payment = Payment.query.filter_by(transaction_id=reference).first()
        
        if not payment:
            # Try finding by paystack_reference
            payment = Payment.query.filter_by(paystack_reference=reference).first()
        
        if not payment:
            logger.error(f"Payment not found for reference: {reference}")
            return redirect(f"{app.config.get('FRONTEND_URL', 'http://localhost:3000')}/payment-failed?error=payment_not_found")
        
        # Verify transaction with Paystack
        if PAYSTACK_AVAILABLE and paystack:
            try:
                response = paystack.transaction.verify(reference=reference)
                
                if response['status'] and response['data']['status'] == 'success':
                    # Update payment record
                    if payment.status == 'pending':
                        payment.status = 'completed'
                        payment.completed_at = datetime.utcnow()
                        payment.payment_details = json.dumps({
                            **(json.loads(payment.payment_details) if payment.payment_details else {}),
                            'verification_response': response['data']
                        })
                        db.session.commit()
                        
                        # Update payment history
                        payment_history = PaymentHistory.query.filter_by(payment_id=reference).first()
                        if payment_history:
                            payment_history.status = 'completed'
                            payment_history.paid_at = datetime.utcnow()
                            payment_history.gateway_response = response['data']
                            db.session.commit()
                        
                        # Update user's plan
                        user = User.query.get(payment.user_id)
                        if user:
                            # Update user subscription
                            user.subscription_plan = payment.plan
                            user.subscription_status = 'active'
                            user.billing_cycle = payment.duration
                            user.last_payment_date = datetime.utcnow()
                            
                            # Calculate expiry date
                            if payment.duration == '1_month':
                                user.subscription_ends_at = datetime.utcnow() + timedelta(days=30)
                            elif payment.duration == '6_month':
                                user.subscription_ends_at = datetime.utcnow() + timedelta(days=180)
                            elif payment.duration == '1_year':
                                user.subscription_ends_at = datetime.utcnow() + timedelta(days=365)
                            
                            db.session.commit()
                            
                            # Create or update subscription record
                            existing_sub = Subscription.query.filter_by(user_id=user.id).first()
                            if existing_sub:
                                existing_sub.plan = payment.plan
                                existing_sub.status = 'active'
                                existing_sub.end_date = user.subscription_ends_at
                                existing_sub.last_payment_date = datetime.utcnow()
                                existing_sub.next_payment_date = user.subscription_ends_at
                                existing_sub.payment_method = 'paystack'
                            else:
                                new_sub = Subscription(
                                    user_id=user.id,
                                    plan=payment.plan,
                                    status='active',
                                    start_date=datetime.utcnow(),
                                    end_date=user.subscription_ends_at,
                                    auto_renew=True,
                                    payment_method='paystack',
                                    last_payment_date=datetime.utcnow(),
                                    next_payment_date=user.subscription_ends_at
                                )
                                db.session.add(new_sub)
                            
                            db.session.commit()
                            
                            # Record subscription history
                            sub_history = SubscriptionHistory(
                                user_id=user.id,
                                old_plan='free',  # You might want to get the actual old plan
                                new_plan=payment.plan,
                                billing_cycle=payment.duration,
                                country=user.country or 'default',
                                currency=payment.currency,
                                amount=payment.amount,
                                change_type='upgrade',
                                change_reason='Payment completed via Paystack',
                                effective_date=datetime.utcnow()
                            )
                            db.session.add(sub_history)
                            db.session.commit()
                            
                            logger.info(f"Paystack payment successful: {reference} - User: {user.email} - Plan: {payment.plan}")
                            
                            # Send confirmation email (if you have this function)
                            # send_payment_confirmation_email(user, payment)
                    
                    return redirect(f"{app.config.get('FRONTEND_URL', 'http://localhost:3000')}/payment-success?reference={reference}")
                else:
                    # Payment verification failed
                    payment.status = 'failed'
                    payment.failure_reason = response.get('message', 'Verification failed')
                    payment.payment_details = json.dumps({
                        **(json.loads(payment.payment_details) if payment.payment_details else {}),
                        'verification_failed': response
                    })
                    db.session.commit()
                    
                    # Update payment history
                    payment_history = PaymentHistory.query.filter_by(payment_id=reference).first()
                    if payment_history:
                        payment_history.status = 'failed'
                        payment_history.gateway_response = response
                        db.session.commit()
                    
                    logger.warning(f"Paystack verification failed: {reference} - {response.get('message')}")
                    return redirect(f"{app.config.get('FRONTEND_URL', 'http://localhost:3000')}/payment-failed?reference={reference}&error=verification_failed")
                    
            except Exception as e:
                logger.error(f"Paystack verification error: {e}")
                return redirect(f"{app.config.get('FRONTEND_URL', 'http://localhost:3000')}/payment-failed?reference={reference}&error=verification_error")
        else:
            # Mock verification for development
            if payment.status == 'pending':
                payment.status = 'completed'
                payment.completed_at = datetime.utcnow()
                payment.payment_details = json.dumps({
                    **(json.loads(payment.payment_details) if payment.payment_details else {}),
                    'mock_verification': True,
                    'status': 'success'
                })
                db.session.commit()
                
                # Update user's plan (mock)
                user = User.query.get(payment.user_id)
                if user:
                    user.subscription_plan = payment.plan
                    user.subscription_status = 'active'
                    user.billing_cycle = payment.duration
                    user.last_payment_date = datetime.utcnow()
                    
                    if payment.duration == '1_month':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=30)
                    elif payment.duration == '6_month':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=180)
                    elif payment.duration == '1_year':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=365)
                    
                    db.session.commit()
                    
                    logger.info(f"Mock payment completed for user {user.email}")
            
            return redirect(f"{app.config.get('FRONTEND_URL', 'http://localhost:3000')}/payment-success?reference={reference}&mock=true")
            
    except Exception as e:
        logger.error(f"Paystack callback error: {e}")
        import traceback
        traceback.print_exc()
        return redirect(f"{app.config.get('FRONTEND_URL', 'http://localhost:3000')}/payment-failed?error=callback_error")


@app.route('/api/payment/paystack/webhook', methods=['POST'])
def paystack_webhook():
    """Handle Paystack webhook events"""
    try:
        # Verify webhook signature
        signature = request.headers.get('x-paystack-signature')
        # If you have signature verification, implement it here
        if not verify_paystack_signature(request.data, signature):
            logger.warning("Invalid Paystack webhook signature")
            return jsonify({'error': 'Invalid signature'}), 401
        
        # Parse webhook payload
        event = request.get_json()
        
        if not event:
            return jsonify({'error': 'Invalid payload'}), 400
        
        logger.info(f"Paystack webhook received: {event.get('event')}")
        
        # Handle different event types
        if event['event'] == 'charge.success':
            data = event['data']
            reference = data['reference']
            
            # Find payment
            payment = Payment.query.filter_by(transaction_id=reference).first()
            if not payment:
                payment = Payment.query.filter_by(paystack_reference=reference).first()
            
            if payment and payment.status == 'pending':
                # Update payment
                payment.status = 'completed'
                payment.completed_at = datetime.utcnow()
                payment.payment_details = json.dumps({
                    **(json.loads(payment.payment_details) if payment.payment_details else {}),
                    'webhook_response': data
                })
                db.session.commit()
                
                # Update payment history
                payment_history = PaymentHistory.query.filter_by(payment_id=reference).first()
                if payment_history:
                    payment_history.status = 'completed'
                    payment_history.paid_at = datetime.utcnow()
                    payment_history.gateway_response = data
                    db.session.commit()
                
                # Update user plan
                user = User.query.get(payment.user_id)
                if user:
                    user.subscription_plan = payment.plan
                    user.subscription_status = 'active'
                    user.billing_cycle = payment.duration
                    user.last_payment_date = datetime.utcnow()
                    
                    if payment.duration == '1_month':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=30)
                    elif payment.duration == '6_month':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=180)
                    elif payment.duration == '1_year':
                        user.subscription_ends_at = datetime.utcnow() + timedelta(days=365)
                    
                    db.session.commit()
                    
                    # Create subscription record
                    existing_sub = Subscription.query.filter_by(user_id=user.id).first()
                    if not existing_sub:
                        new_sub = Subscription(
                            user_id=user.id,
                            plan=payment.plan,
                            status='active',
                            start_date=datetime.utcnow(),
                            end_date=user.subscription_ends_at,
                            auto_renew=True,
                            payment_method='paystack',
                            last_payment_date=datetime.utcnow(),
                            next_payment_date=user.subscription_ends_at
                        )
                        db.session.add(new_sub)
                        db.session.commit()
                    
                    logger.info(f"Paystack webhook: Payment completed for user {user.email}")
            
        elif event['event'] == 'charge.failed':
            data = event['data']
            reference = data['reference']
            
            payment = Payment.query.filter_by(transaction_id=reference).first()
            if not payment:
                payment = Payment.query.filter_by(paystack_reference=reference).first()
            
            if payment:
                payment.status = 'failed'
                payment.failure_reason = data.get('gateway_response', 'Payment failed')
                payment.payment_details = json.dumps({
                    **(json.loads(payment.payment_details) if payment.payment_details else {}),
                    'webhook_failure': data
                })
                db.session.commit()
                
                logger.info(f"Paystack webhook: Payment failed for reference {reference}")
        
        elif event['event'] == 'charge.refund':
            data = event['data']
            reference = data['reference']
            
            payment = Payment.query.filter_by(transaction_id=reference).first()
            if payment:
                payment.status = 'refunded'
                payment.payment_details = json.dumps({
                    **(json.loads(payment.payment_details) if payment.payment_details else {}),
                    'refund_data': data
                })
                db.session.commit()
                
                logger.info(f"Paystack webhook: Payment refunded for reference {reference}")
        
        return jsonify({'status': 'success'}), 200
        
    except Exception as e:
        logger.error(f"Paystack webhook error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500


@app.route('/api/payment/paystack/verify/<reference>', methods=['GET'])
@jwt_required
def verify_paystack_payment(reference):
    """Verify Paystack payment status"""
    try:
        user = request.user
        
        # Find payment
        payment = Payment.query.filter_by(transaction_id=reference).first()
        if not payment:
            payment = Payment.query.filter_by(paystack_reference=reference).first()
        
        if not payment:
            return jsonify({'error': 'Payment not found'}), 404
        
        # Check ownership
        if payment.user_id != user.id:
            return jsonify({'error': 'Unauthorized'}), 403
        
        # If already completed, return success
        if payment.status == 'completed':
            return jsonify({
                'success': True,
                'status': 'completed',
                'payment': {
                    'reference': payment.transaction_id,
                    'plan': payment.plan,
                    'amount': payment.amount,
                    'currency': payment.currency,
                    'completed_at': payment.completed_at.isoformat() if payment.completed_at else None
                }
            }), 200
        
        # Verify with Paystack if not completed
        if PAYSTACK_AVAILABLE and paystack and payment.payment_method != 'paystack_mock':
            try:
                response = paystack.transaction.verify(reference=reference)
                
                if response['status']:
                    paystack_status = response['data']['status']
                    
                    if paystack_status == 'success' and payment.status == 'pending':
                        payment.status = 'completed'
                        payment.completed_at = datetime.utcnow()
                        payment.payment_details = json.dumps({
                            **(json.loads(payment.payment_details) if payment.payment_details else {}),
                            'verification_response': response['data']
                        })
                        db.session.commit()
                        
                        # Update user plan
                        user_to_update = User.query.get(payment.user_id)
                        if user_to_update:
                            user_to_update.subscription_plan = payment.plan
                            user_to_update.subscription_status = 'active'
                            user_to_update.billing_cycle = payment.duration
                            user_to_update.last_payment_date = datetime.utcnow()
                            
                            if payment.duration == '1_month':
                                user_to_update.subscription_ends_at = datetime.utcnow() + timedelta(days=30)
                            elif payment.duration == '6_month':
                                user_to_update.subscription_ends_at = datetime.utcnow() + timedelta(days=180)
                            elif payment.duration == '1_year':
                                user_to_update.subscription_ends_at = datetime.utcnow() + timedelta(days=365)
                            
                            db.session.commit()
                    
                    return jsonify({
                        'success': True,
                        'status': payment.status,
                        'paystack_status': paystack_status,
                        'payment': {
                            'reference': payment.transaction_id,
                            'plan': payment.plan,
                            'amount': payment.amount,
                            'currency': payment.currency
                        }
                    }), 200
                    
            except Exception as e:
                logger.error(f"Paystack verification error: {e}")
        
        # Return current status
        return jsonify({
            'success': True,
            'status': payment.status,
            'payment': {
                'reference': payment.transaction_id,
                'plan': payment.plan,
                'amount': payment.amount,
                'currency': payment.currency,
                'created_at': payment.created_at.isoformat() if payment.created_at else None
            }
        }), 200
        
    except Exception as e:
        logger.error(f"Payment verification error: {e}")
        return jsonify({'error': str(e)}), 500

import json

@app.route('/api/payment/paystack/initialize/public', methods=['POST'])
def initialize_paystack_payment_public():
    """Initialize Paystack payment for public (signup) users"""
    try:
        data = request.get_json()
        
        plan = data.get('plan', 'basic')
        duration = data.get('duration', '1_month')
        amount = data.get('amount')
        currency = data.get('currency', 'GHS')
        email = data.get('email')
        name = data.get('name', email.split('@')[0])
        
        print(f"📝 Payment initialization: {plan}, {duration}, {amount}, {currency}, {email}")
        
        # Check if user exists
        user = User.query.filter_by(email=email).first()
        
        if not user:
            # Create temporary user for payment
            user = User(
                name=name,
                email=email,
                password_hash='',  # Will be set during registration
                user_type='user',
                subscription_plan=plan,
                subscription_status='pending',
                is_active=False,
                verified=False,
                created_at=datetime.utcnow()
            )
            db.session.add(user)
            db.session.flush()
            print(f"✅ Created temporary user: {user.id} - {user.email}")
        
        # Generate unique transaction ID
        transaction_id = f"PAYSTACK-SIGNUP-{int(datetime.utcnow().timestamp())}-{uuid.uuid4().hex[:8].upper()}"
        
        # ✅ Convert payment_details to JSON string
        payment_details_dict = {
            'is_signup': True,
            'user_email': email,
            'user_name': user.name,
            'plan': plan,
            'duration': duration,
            'country': data.get('country', 'default'),
            'reference': transaction_id,
            'is_system_team': False
        }
        
        # Create payment record
        payment = Payment(
            user_id=user.id,
            amount=float(amount),
            currency=currency,
            plan=plan,
            duration=duration,
            payment_method='paystack',
            status='pending',
            transaction_id=transaction_id,
            paystack_reference=transaction_id,
            payment_details=json.dumps(payment_details_dict),  # ✅ Convert to JSON string
            created_at=datetime.utcnow()
        )
        
        db.session.add(payment)
        db.session.commit()
        print(f"✅ Created payment record: {payment.id}")
        
        # Store user ID in session
        session['pending_user_id'] = user.id
        session['pending_plan'] = plan
        session['pending_duration'] = duration
        
        # Initialize Paystack payment
        paystack_secret = current_app.config.get('PAYSTACK_SECRET_KEY')
        if not paystack_secret:
            return jsonify({
                'success': False,
                'error': 'Payment gateway not configured'
            }), 500
        
        paystack_url = "https://api.paystack.co/transaction/initialize"
        headers = {
            "Authorization": f"Bearer {paystack_secret}",
            "Content-Type": "application/json"
        }
        
        callback_url = f"{current_app.config.get('FRONTEND_URL', 'http://localhost:3000')}/payment/callback"
        
        payload = {
            "email": email,
            "amount": int(float(amount) * 100),
            "currency": currency,
            "reference": transaction_id,
            "callback_url": callback_url,
            "metadata": {
                "user_id": user.id,
                "plan": plan,
                "duration": duration,
                "is_signup": True,
                "email": email,
                "name": user.name
            }
        }
        
        print(f"📤 Sending to Paystack: {payload}")
        
        response = requests.post(paystack_url, json=payload, headers=headers)
        
        if response.status_code == 200:
            result = response.json()
            
            if result.get('status'):
                # Update payment with authorization URL
                payment_details_dict['authorization_url'] = result['data']['authorization_url']
                payment_details_dict['access_code'] = result['data']['access_code']
                payment.payment_details = json.dumps(payment_details_dict)  # Update JSON
                db.session.commit()
                
                print(f"✅ Paystack payment initialized: {result['data']['authorization_url']}")
                
                return jsonify({
                    'success': True,
                    'authorization_url': result['data']['authorization_url'],
                    'reference': transaction_id,
                    'user_id': user.id
                }), 200
            else:
                print(f"❌ Paystack error: {result}")
                return jsonify({
                    'success': False,
                    'error': result.get('message', 'Payment initialization failed')
                }), 400
        else:
            print(f"❌ Paystack API error: {response.text}")
            return jsonify({
                'success': False,
                'error': f"Paystack API error"
            }), 500
            
    except Exception as e:
        db.session.rollback()
        print(f"❌ Paystack API error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': 'Payment gateway error. Please try again.',
            'code': 'PAYMENT_GATEWAY_ERROR'
        }), 500

def get_payment_details(payment):
    """Parse payment details JSON"""
    try:
        if payment.payment_details:
            return json.loads(payment.payment_details)
        return {}
    except:
        return {}

