def validate_pagination(limit, offset):
    """Validate and sanitize pagination parameters"""
    if limit > 100:
        limit = 100
    if limit < 1:
        limit = 10
    if offset < 0:
        offset = 0
    return limit, offset

def generate_document_id(template_key=None, industry=None, standard=None):
    """
    Generate a unique document ID.
    
    Args:
        template_key: The template key used for generation
        industry: The industry type (e.g., 'construction', 'healthcare')
        standard: The standard/regulation (e.g., 'osha', 'iso_45001')
    
    Returns:
        str: Unique document ID (12 characters if using MD5, or UUID as fallback)
    """
    # If all 3 arguments are provided, create a deterministic ID
    if template_key and industry and standard:
        raw = f"{template_key}|{industry}|{standard}|{datetime.now().isoformat()}"
        return hashlib.md5(raw.encode()).hexdigest()[:12].upper()
    
    # Fallback: use UUID
    return str(uuid.uuid4())

def calculate_content_hash(content):
    """Generate SHA-256 hash of content"""
    if not content:
        return None
    return hashlib.sha256(content.encode()).hexdigest()

def get_file_extension(filename):
    """Get file extension from filename"""
    if not filename:
        return ''
    return os.path.splitext(filename)[1].lower()

def is_allowed_file(filename):
    """Check if file type is allowed"""
    allowed_extensions = {'.pdf', '.doc', '.docx', '.xls', '.xlsx', '.jpg', '.jpeg', '.png', '.txt'}
    ext = get_file_extension(filename)
    return ext in allowed_extensions


def create_audit_log(document_id, user_id, action, details=None):
    """Create an audit log entry with integer ID"""
    try:
        from models import DocumentAuditLog
        
        # ✅ Generate integer ID instead of UUID
        audit_id = int(time.time() * 1000000) + random.randint(1000, 9999)
        
        # ✅ Ensure document_id and user_id are integers
        if isinstance(document_id, str) and document_id.isdigit():
            document_id = int(document_id)
        if isinstance(user_id, str) and user_id.isdigit():
            user_id = int(user_id)
        
        # ✅ Handle details safely
        details_json = None
        if details:
            if isinstance(details, dict):
                details_json = json.dumps(details)
            elif isinstance(details, str):
                # If it's already a JSON string, keep it
                try:
                    json.loads(details)
                    details_json = details
                except json.JSONDecodeError:
                    details_json = json.dumps({'message': details})
            else:
                details_json = json.dumps({'data': str(details)})
        
        # ✅ Get IP and User Agent safely
        ip_address = None
        user_agent = ''
        try:
            # Try to get from Flask request context
            from flask import request
            ip_address = request.remote_addr if hasattr(request, 'remote_addr') else None
            user_agent = request.headers.get('User-Agent', '') if hasattr(request, 'headers') else ''
        except (RuntimeError, AttributeError):
            # Not in request context
            pass
        
        audit_log = DocumentAuditLog(
            id=audit_id,  # ✅ INTEGER ID
            document_id=document_id,  # ✅ INTEGER
            user_id=user_id,  # ✅ INTEGER
            action=action,
            details=details_json,
            ip_address=ip_address,
            user_agent=user_agent,
            created_at=datetime.utcnow()
        )
        
        db.session.add(audit_log)
        db.session.commit()
        return True
        
    except Exception as e:
        db.session.rollback()
        # Don't use current_app if not available in this context
        try:
            from flask import current_app
            current_app.logger.warning(f"Audit log creation failed: {e}")
        except RuntimeError:
            print(f"Audit log creation failed: {e}")
        return False
# ============================================================================
# DOCUMENT ACCESS CONTROL HELPERS
# ============================================================================

def can_access_document(user, document, is_super_admin=False):
    """Check if user can access a specific document"""
    if is_super_admin:
        return True
    
    if not user or not document:
        return False
    
    # User owns the document
    if hasattr(document, 'user_id') and document.user_id == user.id:
        return True
    
    # User belongs to same company as document
    if hasattr(document, 'company_id') and document.company_id:
        user_company_id = getattr(user, 'company_id', None)
        if user_company_id and document.company_id == user_company_id:
            return True
    
    # Document is public
    if hasattr(document, 'is_public') and document.is_public:
        return True
    
    return False

def can_edit_document(user, document, is_super_admin=False):
    """Check if user can edit a document"""
    if is_super_admin:
        return True
    
    if not user or not document:
        return False
    
    # User owns the document
    if hasattr(document, 'user_id') and document.user_id == user.id:
        return True
    
    return False

def can_delete_document(user, document, is_super_admin=False):
    """Check if user can delete a document"""
    if is_super_admin:
        return True
    
    if not user or not document:
        return False
    
    # Only document owner can delete
    if hasattr(document, 'user_id') and document.user_id == user.id:
        return True
    
    return False

def get_document_scope(user, is_super_admin=False):
    """Get document scope for user"""
    if is_super_admin:
        return 'all', None
    
    user_company_id = getattr(user, 'company_id', None)
    if user_company_id:
        return 'company', user_company_id
    else:
        return 'user', user.id

def has_document_feature_access(user, feature_name):
    """Check if user has access to document features"""
    if not user:
        return False
    
    if getattr(user, 'is_super_admin', False):
        return True
    
    effective_plan = getattr(user, 'subscription_plan', 'free')
    plan_features = {
        'free': ['view', 'upload', 'download'],
        'basic': ['view', 'upload', 'download', 'create'],
        'pro': ['view', 'upload', 'download', 'create', 'edit', 'share', 'versioning'],
        'business': ['view', 'upload', 'download', 'create', 'edit', 'share', 'versioning', 'approval'],
        'enterprise': ['view', 'upload', 'download', 'create', 'edit', 'share', 'versioning', 'approval', 'archive']
    }
    
    available_features = plan_features.get(effective_plan, ['view'])
    return feature_name in available_features


