@app.route('/api/documents/<document_id>', methods=['GET'])
@cross_origin()
@jwt_required
def get_document_by_id(document_id):
    """Get a single document by ID (supports both UUID and integer)"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user has document access
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'view'):
                return jsonify({
                    'success': False,
                    'error': 'Document access not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE',
                    'required_plan': 'free',
                    'current_plan': getattr(current_user, 'subscription_plan', 'free')
                }), 403
        
        from models import Document
        import uuid
        
        # ============================================================
        # PARSE ID - SUPPORT BOTH UUID AND INTEGER
        # ============================================================
        doc_uuid = None
        doc_id = None
        
        # Try to parse as UUID
        try:
            doc_uuid = uuid.UUID(document_id)
            # Use UUID for query
            id_filter = Document.id == doc_uuid
        except ValueError:
            # Not a valid UUID, try as integer
            try:
                doc_id = int(document_id)
                id_filter = Document.id == doc_id
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid document ID format. Must be UUID or integer.',
                    'code': 'INVALID_ID'
                }), 400
        
        # ============================================================
        # BUILD QUERY WITH SCOPE
        # ============================================================
        if is_super_admin:
            document = Document.query.filter(id_filter).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter(
                    id_filter,
                    Document.company_id == user_company_id
                ).first()
            else:
                document = Document.query.filter(
                    id_filter,
                    Document.user_id == current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # ============================================================
        # ✅ FIX: Parse tags from JSON string to array
        # ============================================================
        tags = document.tags or '[]'
        if isinstance(tags, str):
            try:
                tags = json.loads(tags) if tags else []
            except json.JSONDecodeError:
                # If it's a comma-separated string, split it
                tags = [t.strip() for t in tags.split(',') if t.strip()]
        elif not isinstance(tags, list):
            tags = []
        
        # ============================================================
        # AUDIT LOG
        # ============================================================
        create_audit_log(
            document_id=document.id,
            user_id=current_user.id,
            action='view',
            details={'viewed_at': datetime.utcnow().isoformat()}
        )
        
        # ============================================================
        # PREPARE RESPONSE
        # ============================================================
        doc_dict = {
            'id': str(document.id) if isinstance(document.id, uuid.UUID) else document.id,
            'title': document.title,
            'description': document.description,
            'document_type': document.document_type,
            'category': document.category,
            'module': document.module,
            'priority': document.priority,
            'status': document.status,
            'version': document.version,
            'file_url': document.file_url,
            'file_name': document.file_name,
            'file_size': document.file_size,
            'mime_type': document.mime_type,
            'tags': tags,  # ✅ Now properly parsed as an array
            'is_confidential': document.is_confidential,
            'requires_approval': document.requires_approval,
            'approval_workflow': document.approval_workflow,
            'review_status': document.review_status,
            'review_frequency': document.review_frequency,
            'next_review_date': document.next_review_date.isoformat() if document.next_review_date else None,
            'last_reviewed_at': document.last_reviewed_at.isoformat() if document.last_reviewed_at else None,
            'expires_at': document.expires_at.isoformat() if document.expires_at else None,
            'content': document.content,
            'content_hash': document.content_hash,
            'created_at': document.created_at.isoformat() if document.created_at else None,
            'updated_at': document.updated_at.isoformat() if document.updated_at else None,
            'reviewed_at': document.reviewed_at.isoformat() if document.reviewed_at else None,
            'approved_at': document.approved_at.isoformat() if document.approved_at else None,
            'published_at': document.published_at.isoformat() if document.published_at else None,
            'archived_at': document.archived_at.isoformat() if document.archived_at else None,
            'created_by': str(document.created_by) if document.created_by else None,
            'updated_by': str(document.updated_by) if document.updated_by else None,
            'created_by_name': document.creator.name if document.creator else None,
            'updated_by_name': document.updater.name if document.updater else None,
            'company_id': str(document.company_id) if document.company_id else None,
            'user_id': str(document.user_id) if hasattr(document, 'user_id') and document.user_id else None,
            'permissions': {
                'can_edit': can_edit_document(current_user, document, is_super_admin),
                'can_delete': can_delete_document(current_user, document, is_super_admin),
                'can_download': can_access_document(current_user, document, is_super_admin),
                'can_view': True
            }
        }
        
        return jsonify({
            'success': True,
            'document': doc_dict,
            'access_level': 'super_admin' if is_super_admin else 'user'
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching document: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to fetch document',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


