@jwt_required
def update_sds_document(sds_id):
    """Update an SDS document"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        data = request.get_json() or {}
        
        from models import SDSDocument
        
        # Parse ID
        try:
            sds_id_int = int(sds_id)
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid SDS ID format',
                'code': 'INVALID_ID'
            }), 400
        
        sds = SDSDocument.query.get(sds_id_int)
        if not sds:
            return jsonify({
                'success': False,
                'error': 'SDS document not found',
                'code': 'SDS_NOT_FOUND'
            }), 404
        
        # Check permission
        if not is_super_admin and sds.company_id != current_user.company_id:
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # Update fields
        if 'chemical_name' in data:
            sds.chemical_name = data['chemical_name']
        if 'cas_number' in data:
            # Check for duplicate CAS
            existing = SDSDocument.query.filter_by(cas_number=data['cas_number']).first()
            if existing and existing.id != sds_id_int:
                return jsonify({
                    'success': False,
                    'error': f'SDS document with CAS number {data["cas_number"]} already exists',
                    'code': 'DUPLICATE_CAS'
                }), 400
            sds.cas_number = data['cas_number']
        if 'manufacturer' in data:
            sds.manufacturer = data['manufacturer']
        if 'classification' in data:
            sds.classification = data['classification']
        if 'hazard_codes' in data:
            sds.hazard_codes = data['hazard_codes']
        if 'status' in data:
            sds.status = data['status']
        
        sds.updated_at = datetime.utcnow()
        sds.updated_by = current_user.id
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'SDS document updated successfully',
            'sds': sds.to_dict() if hasattr(sds, 'to_dict') else {'id': sds.id}
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error updating SDS document: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


