@app.route('/api/documents/sds/search', methods=['GET'])
@cross_origin()
@jwt_required
def search_sds():
    """Search SDS documents by chemical name or CAS number"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import SDSDocument
        
        query = request.args.get('q', '').strip()
        if not query or len(query) < 2:
            return jsonify({
                'success': True,
                'results': []
            }), 200
        
        if is_super_admin:
            sds_query = SDSDocument.query
        else:
            sds_query = SDSDocument.query.filter_by(company_id=current_user.company_id)
        
        results = sds_query.filter(
            (SDSDocument.chemical_name.ilike(f'%{query}%')) |
            (SDSDocument.cas_number.ilike(f'%{query}%'))
        ).limit(20).all()
        
        return jsonify({
            'success': True,
            'results': [sds.to_dict() for sds in results] if results else []
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error searching SDS: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

