@app.route('/api/documents/ptw', methods=['GET'])
@cross_origin()
@jwt_required
def get_ptw_documents():
    """Get all PTW documents"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import PTWDocument
        
        if is_super_admin:
            query = PTWDocument.query
        else:
            query = PTWDocument.query.filter_by(company_id=current_user.company_id)
        
        # Apply filters
        status = request.args.get('status')
        permit_type = request.args.get('permit_type')
        location = request.args.get('location')
        
        if status and status != 'all':
            query = query.filter_by(status=status)
        if permit_type and permit_type != 'all':
            query = query.filter_by(permit_type=permit_type)
        if location:
            query = query.filter(PTWDocument.location.ilike(f'%{location}%'))
        
        ptw_documents = query.order_by(PTWDocument.created_at.desc()).all()
        
        return jsonify({
            'success': True,
            'ptw_documents': [doc.to_dict() for doc in ptw_documents],
            'total': len(ptw_documents)
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error getting PTW documents: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/documents/ptw', methods=['POST'])
@cross_origin()
@jwt_required
def create_ptw_document():
    """Create a new PTW document"""
    try:
        current_user = request.user
        
        # ✅ DEBUG: Log all form data
        print("=" * 60)
        print("📋 PTW CREATE - REQUEST DATA:")
        print(f"  - Form keys: {list(request.form.keys())}")
        print(f"  - Form data: {dict(request.form)}")
        print(f"  - Files: {request.files.keys()}")
        print("=" * 60)
        
        from models import PTWDocument
        import time
        import random
        
        # ✅ Try to get title from multiple possible field names
        title = request.form.get('title', '')
        if not title:
            title = request.form.get('PTW Title', '')
        if not title:
            title = request.form.get('ptw_title', '')
        if not title:
            # Check if data is in JSON format
            data = request.get_json(silent=True)
            if data:
                title = data.get('title', '')
        
        if not title:
            return jsonify({
                'success': False,
                'error': f'Title is required. Received fields: {list(request.form.keys())}',
                'code': 'MISSING_TITLE'
            }), 400
        
        # ✅ Get ptw_type (frontend sends 'ptw_type')
        permit_type = request.form.get('ptw_type', 'excavation')
        if not permit_type or permit_type == 'undefined':
            permit_type = request.form.get('permit_type', 'excavation')
        
        # ✅ Get location
        location = request.form.get('location', '').strip()
        
        # ✅ Get description
        description = request.form.get('description', '').strip()
        
        # ✅ Get dates
        start_date_str = request.form.get('start_date', '')
        end_date_str = request.form.get('end_date', '')
        
        # ✅ Get priority
        priority = request.form.get('priority', 'medium')
        
        # ✅ Get assigned_to
        assigned_to = request.form.get('assigned_to', '')
        
        # ✅ Get department
        department = request.form.get('department', '')
        
        # ✅ Get risk_assessment
        risk_assessment = request.form.get('risk_assessment', '')
        
        # ✅ Get isolation_requirements
        isolation_requirements = request.form.get('isolation_requirements', '')
        
        # ✅ Get ppe_requirements
        ppe_requirements = request.form.get('ppe_requirements', '')
        
        # ✅ Get notes
        notes = request.form.get('notes', '')
        
        # Get status
        status = request.form.get('status', 'draft')
        
        # Parse dates
        start_date = None
        end_date = None
        
        if start_date_str:
            try:
                start_date = datetime.fromisoformat(start_date_str.replace('Z', '+00:00'))
            except:
                try:
                    from dateutil import parser
                    start_date = parser.parse(start_date_str)
                except:
                    pass
        
        if end_date_str:
            try:
                end_date = datetime.fromisoformat(end_date_str.replace('Z', '+00:00'))
            except:
                try:
                    from dateutil import parser
                    end_date = parser.parse(end_date_str)
                except:
                    pass
        
        # Get file
        file = request.files.get('file')
        
        # Generate ID
        ptw_id = int(time.time() * 1000000) + random.randint(1, 999)
        
        # Save file if provided
        file_url = None
        file_name = None
        if file and file.filename:
            filename = secure_filename(file.filename)
            safe_filename = f"ptw_{ptw_id}_{filename}"
            
            upload_dir = os.path.join(current_app.config.get('UPLOAD_FOLDER', 'uploads'), 'ptw')
            os.makedirs(upload_dir, exist_ok=True)
            
            file_path = os.path.join(upload_dir, safe_filename)
            file.save(file_path)
            
            file_url = f"/uploads/ptw/{safe_filename}"
            file_name = filename
        
        # Get company_id
        company_id = getattr(current_user, 'company_id', None)
        
        # ✅ Create PTW document with all fields
        ptw = PTWDocument(
            id=ptw_id,
            title=title,
            permit_type=permit_type,
            location=location,
            description=description,
            start_date=start_date,
            end_date=end_date,
            status=status,
            priority=priority,
            file_url=file_url,
            file_name=file_name,
            company_id=company_id,
            created_by=current_user.id,
            created_at=datetime.utcnow(),
            updated_at=datetime.utcnow()
        )
        
        # ✅ Add additional fields if the model supports them
        if assigned_to and hasattr(ptw, 'assigned_to'):
            ptw.assigned_to = assigned_to
        if department and hasattr(ptw, 'department'):
            ptw.department = department
        if risk_assessment and hasattr(ptw, 'risk_assessment'):
            ptw.risk_assessment = risk_assessment
        if isolation_requirements and hasattr(ptw, 'isolation_requirements'):
            ptw.isolation_requirements = isolation_requirements
        if ppe_requirements and hasattr(ptw, 'ppe_requirements'):
            ptw.ppe_requirements = ppe_requirements
        if notes and hasattr(ptw, 'notes'):
            ptw.notes = notes
        
        db.session.add(ptw)
        db.session.commit()
        
        # Create audit log
        create_audit_log(
            document_id=ptw_id,
            user_id=current_user.id,
            action='create_ptw',
            details={'title': title, 'permit_type': permit_type}
        )
        
        return jsonify({
            'success': True,
            'message': 'PTW document created successfully',
            'ptw_id': ptw_id,
            'ptw': ptw.to_dict() if hasattr(ptw, 'to_dict') else {
                'id': ptw.id,
                'title': ptw.title,
                'permit_type': ptw.permit_type,
                'status': ptw.status
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error creating PTW document: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e),
            'code': 'INTERNAL_ERROR'
        }), 500


