@app.route('/api/documents/ptw/<ptw_id>/status', methods=['PUT'])
@cross_origin()
@jwt_required
def update_ptw_status(ptw_id):
    """Update PTW document status"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        data = request.get_json() or {}
        
        from models import PTWDocument
        
        # Parse ID
        try:
            ptw_id_int = int(ptw_id)
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid PTW ID format',
                'code': 'INVALID_ID'
            }), 400
        
        ptw = PTWDocument.query.get(ptw_id_int)
        if not ptw:
            return jsonify({
                'success': False,
                'error': 'PTW document not found',
                'code': 'PTW_NOT_FOUND'
            }), 404
        
        # Check permission
        if not is_super_admin and ptw.company_id != current_user.company_id:
            return jsonify({
                'success': False,
                'error': 'Access denied',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        status = data.get('status')
        if not status:
            return jsonify({
                'success': False,
                'error': 'Status is required',
                'code': 'MISSING_STATUS'
            }), 400
        
        valid_statuses = ['draft', 'pending', 'approved', 'rejected', 'expired', 'cancelled']
        if status not in valid_statuses:
            return jsonify({
                'success': False,
                'error': f'Invalid status. Must be one of: {", ".join(valid_statuses)}',
                'code': 'INVALID_STATUS'
            }), 400
        
        ptw.status = status
        ptw.updated_at = datetime.utcnow()
        ptw.updated_by = current_user.id
        
        if status == 'approved':
            ptw.approved_at = datetime.utcnow()
            ptw.approved_by = current_user.id
        elif status == 'rejected':
            ptw.rejected_at = datetime.utcnow()
            ptw.rejected_by = current_user.id
        
        db.session.commit()
        
        # Create audit log
        create_audit_log(
            document_id=ptw_id_int,
            user_id=current_user.id,
            action='update_ptw_status',
            details={'status': status}
        )
        
        return jsonify({
            'success': True,
            'message': f'PTW status updated to {status}',
            'ptw': ptw.to_dict() if hasattr(ptw, 'to_dict') else {'id': ptw.id, 'status': ptw.status}
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error updating PTW status: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


