@app.route('/api/documents/signatures', methods=['POST'])
@cross_origin()
@jwt_required
def create_signature():
    """Create a new signature for a document"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        data = request.get_json()
        
        from models import Document, DocumentSignature, SignatureVerification
        import time
        import random
        
        # Validate required fields
        document_id = data.get('document_id')
        if not document_id:
            return jsonify({
                'success': False,
                'error': 'Document ID is required',
                'code': 'MISSING_DOCUMENT_ID'
            }), 400
        
        # Parse document ID
        try:
            doc_id_int = int(document_id)
            id_filter = Document.id == doc_id_int
        except ValueError:
            try:
                doc_uuid = uuid.UUID(document_id)
                id_filter = Document.id == doc_uuid
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid document ID format',
                    'code': 'INVALID_ID'
                }), 400
        
        # Get document
        if is_super_admin:
            document = Document.query.filter(id_filter).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter(
                    id_filter,
                    Document.company_id == user_company_id
                ).first()
            else:
                document = Document.query.filter(
                    id_filter,
                    Document.user_id == current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # Validate signature data
        signature_data = data.get('signature_data')
        if not signature_data:
            return jsonify({
                'success': False,
                'error': 'Signature data is required',
                'code': 'MISSING_SIGNATURE_DATA'
            }), 400
        
        # Get signature type
        signature_type = signature_data.get('type', 'draw')
        
        # Generate signature ID
        sig_id = int(time.time() * 1000000) + random.randint(1, 999)
        
        # Get user info
        signer_name = current_user.name or current_user.email or 'Unknown'
        signer_email = current_user.email
        
        # Create signature - ✅ using your model fields
        signature = DocumentSignature(
            id=sig_id,
            document_id=document.id,
            signed_by=current_user.id,  # ✅ Your model uses signed_by
            signer_name=signer_name,
            signer_email=signer_email,
            signer_ip=request.remote_addr,
            purpose=data.get('purpose', 'approval'),
            signature_type=signature_type,
            signature_data=signature_data,
            comment=data.get('comment', ''),
            status='signed',  # ✅ pending, signed, rejected, expired, revoked
            signed_at=datetime.utcnow(),
            created_at=datetime.utcnow()
        )
        
        db.session.add(signature)
        db.session.commit()
        
        # ✅ Create verification record
        verification = SignatureVerification(
            signature_id=sig_id,
            verified_by=current_user.id,
            verification_type='manual',
            status='valid',
            details={'ip': request.remote_addr, 'user_agent': request.headers.get('User-Agent')}
        )
        db.session.add(verification)
        db.session.commit()
        
        # Update document status
        if document.status == 'draft':
            document.status = 'review'
            document.updated_at = datetime.utcnow()
            db.session.commit()
        
        # Create audit log
        create_audit_log(
            document_id=document.id,
            user_id=current_user.id,
            action='sign',
            details={'signature_id': sig_id, 'purpose': data.get('purpose')}
        )
        
        return jsonify({
            'success': True,
            'message': 'Document signed successfully',
            'signature_id': sig_id,
            'signature': signature.to_dict() if hasattr(signature, 'to_dict') else {
                'id': signature.id,
                'document_id': signature.document_id,
                'status': signature.status,
                'signed_at': signature.signed_at.isoformat() if signature.signed_at else None
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error creating signature: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/documents/signatures/<signature_id>/verify', methods=['GET'])
@cross_origin()
@jwt_required
def verify_signature(signature_id):
    """Verify a signature"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import DocumentSignature, SignatureVerification
        
        # Parse signature ID
        try:
            sig_id_int = int(signature_id)
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid signature ID format',
                'code': 'INVALID_ID'
            }), 400
        
        signature = DocumentSignature.query.get(sig_id_int)
        if not signature:
            return jsonify({
                'success': False,
                'error': 'Signature not found',
                'code': 'SIGNATURE_NOT_FOUND'
            }), 404
        
        # Check permission
        if not is_super_admin:
            from models import Document
            document = Document.query.get(signature.document_id)
            if document and document.company_id != current_user.company_id:
                return jsonify({
                    'success': False,
                    'error': 'Access denied',
                    'code': 'PERMISSION_DENIED'
                }), 403
        
        # ✅ Create verification record
        verification = SignatureVerification(
            signature_id=sig_id_int,
            verified_by=current_user.id,
            verification_type='api',
            status='valid' if signature.status == 'signed' else 'invalid',
            details={'verified_at': datetime.utcnow().isoformat()}
        )
        db.session.add(verification)
        db.session.commit()
        
        # Update signature verification fields
        signature.verified_at = datetime.utcnow()
        signature.verified_by = current_user.id
        db.session.commit()
        
        return jsonify({
            'success': True,
            'valid': signature.status == 'signed',
            'signature': {
                'id': signature.id,
                'document_id': signature.document_id,
                'signer_name': signature.signer_name,
                'signer_email': signature.signer_email,
                'purpose': signature.purpose,
                'status': signature.status,
                'signed_at': signature.signed_at.isoformat() if signature.signed_at else None,
                'verified_at': datetime.utcnow().isoformat(),
                'verified_by': current_user.id
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error verifying signature: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/documents/signatures/<signature_id>/revoke', methods=['POST'])
@cross_origin()
@jwt_required
def revoke_signature(signature_id):
    """Revoke a signature"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        data = request.get_json() or {}
        
        from models import DocumentSignature, SignatureVerification
        
        # Parse signature ID
        try:
            sig_id_int = int(signature_id)
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid signature ID format',
                'code': 'INVALID_ID'
            }), 400
        
        signature = DocumentSignature.query.get(sig_id_int)
        if not signature:
            return jsonify({
                'success': False,
                'error': 'Signature not found',
                'code': 'SIGNATURE_NOT_FOUND'
            }), 404
        
        # Check permission
        if not is_super_admin and signature.signed_by != current_user.id:
            return jsonify({
                'success': False,
                'error': 'You do not have permission to revoke this signature',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # Update signature status
        signature.status = 'revoked'
        signature.revoked_at = datetime.utcnow()
        signature.revoked_by = current_user.id
        signature.revocation_reason = data.get('reason', '')
        
        db.session.commit()
        
        # ✅ Create verification record for revocation
        verification = SignatureVerification(
            signature_id=sig_id_int,
            verified_by=current_user.id,
            verification_type='api',
            status='revoked',
            details={'reason': data.get('reason', ''), 'revoked_at': datetime.utcnow().isoformat()}
        )
        db.session.add(verification)
        db.session.commit()
        
        # Create audit log
        create_audit_log(
            document_id=signature.document_id,
            user_id=current_user.id,
            action='revoke_signature',
            details={'signature_id': sig_id_int, 'reason': data.get('reason')}
        )
        
        return jsonify({
            'success': True,
            'message': 'Signature revoked successfully'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error revoking signature: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


