# 6. DELETE DOCUMENT (Soft Delete)
# ============================================================

@app.route('/api/documents/<document_id>', methods=['DELETE'])
@cross_origin()
@jwt_required
def delete_document_control(document_id):
    """Delete a document (soft delete by default)"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user can delete documents
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'delete'):
                return jsonify({
                    'success': False,
                    'error': 'Document deletion not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE',
                    'required_plan': 'pro',
                    'current_plan': getattr(current_user, 'subscription_plan', 'free')
                }), 403
        
        from models import Document
        
        try:
            doc_uuid = uuid.UUID(document_id)
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid document ID format',
                'code': 'INVALID_ID'
            }), 400
        
        # Get document with scope
        if is_super_admin:
            document = Document.query.filter_by(id=doc_uuid).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter_by(
                    id=doc_uuid, 
                    company_id=user_company_id
                ).first()
            else:
                document = Document.query.filter_by(
                    id=doc_uuid, 
                    user_id=current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # ✅ Check permission
        if not is_super_admin and not can_delete_document(current_user, document, is_super_admin):
            return jsonify({
                'success': False,
                'error': 'You do not have permission to delete this document',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # Soft delete - set status to archived
        document.status = 'archived'
        document.archived_at = datetime.utcnow()
        document.updated_at = datetime.utcnow()
        document.updated_by = current_user.id
        
        db.session.commit()
        
        # Create audit log
        create_audit_log(
            document_id=doc_uuid,
            user_id=current_user.id,
            action='archive',
            details={'soft_delete': True}
        )
        
        return jsonify({
            'success': True,
            'message': 'Document archived successfully'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error deleting document: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to delete document',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


