@app.route('/api/documents/stats/modules', methods=['GET'])
@cross_origin()
@jwt_required
def get_document_module_stats():
    """Get document statistics by module"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import Document
        from sqlalchemy import func
        
        # ✅ Build query with scope
        if is_super_admin:
            query = Document.query
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                query = Document.query.filter_by(company_id=user_company_id)
            else:
                query = Document.query.filter_by(user_id=current_user.id)
        
        # Group by module
        results = query.with_entities(
            Document.module,
            func.count(Document.id).label('count')
        ).group_by(Document.module).all()
        
        data = []
        for module, count in results:
            data.append({
                'key': module or 'general',
                'name': module.capitalize() if module else 'General',
                'value': count
            })
        
        return jsonify({
            'success': True,
            'data': data,
            'scope': 'all' if is_super_admin else ('company' if getattr(current_user, 'company_id', None) else 'user')
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Get module stats error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to get module stats',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


