@app.route('/api/documents/expiring', methods=['GET'])
@cross_origin()
@jwt_required
def get_expiring_documents():
    """Get expiring documents"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user has document access
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'view'):
                return jsonify({
                    'success': False,
                    'error': 'Document access not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE'
                }), 403
        
        days = request.args.get('days', 30, type=int)
        
        from models import Document
        from datetime import datetime, timedelta
        
        if not days or days <= 0:
            days = 30
        
        expiry_date = datetime.utcnow() + timedelta(days=days)
        
        # ✅ Build query with scope
        if is_super_admin:
            query = Document.query.filter(
                Document.expires_at.isnot(None),
                Document.expires_at <= expiry_date,
                Document.expires_at >= datetime.utcnow()
            )
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                query = Document.query.filter(
                    Document.company_id == user_company_id,
                    Document.expires_at.isnot(None),
                    Document.expires_at <= expiry_date,
                    Document.expires_at >= datetime.utcnow()
                )
            else:
                query = Document.query.filter(
                    Document.user_id == current_user.id,
                    Document.expires_at.isnot(None),
                    Document.expires_at <= expiry_date,
                    Document.expires_at >= datetime.utcnow()
                )
        
        documents = query.order_by(Document.expires_at.asc()).all()
        
        documents_data = []
        for doc in documents:
            documents_data.append({
                'id': str(doc.id),
                'title': doc.title,
                'status': doc.status,
                'expires_at': doc.expires_at.isoformat() if doc.expires_at else None,
                'module': doc.module,
                'file_name': doc.file_name,
            })
        
        return jsonify({
            'success': True,
            'documents': documents_data,
            'count': len(documents_data),
            'scope': 'all' if is_super_admin else ('company' if getattr(current_user, 'company_id', None) else 'user')
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Get expiring documents error: {str(e)}")
        return jsonify({
            'success': False,
            'error': 'Failed to get expiring documents',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


