# 13. CREATE NEW VERSION
# ============================================================

@app.route('/api/documents/<document_id>/version', methods=['POST'])
@cross_origin()
@jwt_required
def create_document_version(document_id):
    """Create a new version of a document"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user can edit documents
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'edit'):
                return jsonify({
                    'success': False,
                    'error': 'Document editing not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE',
                    'required_plan': 'pro',
                    'current_plan': getattr(current_user, 'subscription_plan', 'free')
                }), 403
        
        from models import Document, DocumentVersion
        
        try:
            doc_uuid = uuid.UUID(document_id)
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid document ID format',
                'code': 'INVALID_ID'
            }), 400
        
        # Get document with scope
        if is_super_admin:
            document = Document.query.filter_by(id=doc_uuid).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter_by(
                    id=doc_uuid, 
                    company_id=user_company_id
                ).first()
            else:
                document = Document.query.filter_by(
                    id=doc_uuid, 
                    user_id=current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # ✅ Check permission
        if not is_super_admin and not can_edit_document(current_user, document, is_super_admin):
            return jsonify({
                'success': False,
                'error': 'You do not have permission to create a new version',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # Get file
        file = request.files.get('file')
        if not file:
            return jsonify({
                'success': False,
                'error': 'File is required',
                'code': 'MISSING_FILE'
            }), 400
        
        changes = request.form.get('changes', '').strip()
        
        # Validate file
        if not is_allowed_file(file.filename):
            return jsonify({
                'success': False,
                'error': 'Unsupported file type',
                'code': 'INVALID_FILE_TYPE'
            }), 400
        
        # Get file size
        file.seek(0, os.SEEK_END)
        file_size = file.tell()
        file.seek(0)
        
        # Save current version
        current_version = DocumentVersion(
            id=str(uuid.uuid4()),
            document_id=doc_uuid,
            version=document.version,
            file_name=document.file_name,
            file_size=document.file_size,
            file_url=document.file_url,
            file_hash=document.file_hash,
            is_current=False,
            created_by=current_user.id
        )
        db.session.add(current_version)
        
        # Save new file
        filename = secure_filename(file.filename)
        file_ext = get_file_extension(filename)
        safe_filename = f"{doc_uuid}_v{document.version + 1}{file_ext}"
        
        upload_dir = os.path.join(current_app.config.get('UPLOAD_FOLDER', 'uploads'), 'documents')
        os.makedirs(upload_dir, exist_ok=True)
        
        file_path = os.path.join(upload_dir, safe_filename)
        file.save(file_path)
        
        with open(file_path, 'rb') as f:
            file_hash = hashlib.sha256(f.read()).hexdigest()
        
        # Update document
        document.version = document.version + 1
        document.file_name = filename
        document.file_size = file_size
        document.file_url = f"/uploads/documents/{safe_filename}"
        document.file_hash = file_hash
        document.updated_at = datetime.utcnow()
        document.updated_by = current_user.id
        
        db.session.commit()
        
        # Create audit log
        create_audit_log(
            document_id=doc_uuid,
            user_id=current_user.id,
            action='new_version',
            details={'version': document.version, 'changes': changes}
        )
        
        return jsonify({
            'success': True,
            'message': 'New version created',
            'version': document.version
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error creating version: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to create version',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


