@app.route('/api/documents/<document_id>/rollback', methods=['POST'])
@cross_origin()
@jwt_required
def rollback_document_version(document_id):
    """Rollback to a specific version"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user can edit documents
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'edit'):
                return jsonify({
                    'success': False,
                    'error': 'Document editing not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE'
                }), 403
        
        from models import Document, DocumentVersion
        
        try:
            doc_uuid = uuid.UUID(document_id)
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid document ID format',
                'code': 'INVALID_ID'
            }), 400
        
        data = request.get_json()
        if not data or 'version' not in data:
            return jsonify({
                'success': False,
                'error': 'Version number is required',
                'code': 'MISSING_VERSION'
            }), 400
        
        # Get document with scope
        if is_super_admin:
            document = Document.query.filter_by(id=doc_uuid).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter_by(
                    id=doc_uuid, 
                    company_id=user_company_id
                ).first()
            else:
                document = Document.query.filter_by(
                    id=doc_uuid, 
                    user_id=current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # ✅ Check permission
        if not is_super_admin and not can_edit_document(current_user, document, is_super_admin):
            return jsonify({
                'success': False,
                'error': 'You do not have permission to rollback this document',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        version_number = data['version']
        target_version = DocumentVersion.query.filter_by(
            document_id=doc_uuid,
            version=version_number
        ).first()
        
        if not target_version:
            return jsonify({
                'success': False,
                'error': f'Version {version_number} not found',
                'code': 'VERSION_NOT_FOUND'
            }), 404
        
        # Create new version from target
        new_version = DocumentVersion(
            id=str(uuid.uuid4()),
            document_id=doc_uuid,
            version=document.version + 1,
            file_name=target_version.file_name,
            file_size=target_version.file_size,
            file_url=target_version.file_url,
            file_hash=target_version.file_hash,
            changes=f"Rollback to version {version_number}",
            is_current=False,
            created_by=current_user.id
        )
        db.session.add(new_version)
        
        # Update document
        document.version = document.version + 1
        document.file_name = target_version.file_name
        document.file_size = target_version.file_size
        document.file_url = target_version.file_url
        document.file_hash = target_version.file_hash
        document.updated_at = datetime.utcnow()
        document.updated_by = current_user.id
        
        db.session.commit()
        
        # Create audit log
        create_audit_log(
            document_id=doc_uuid,
            user_id=current_user.id,
            action='rollback',
            details={'from_version': version_number, 'new_version': document.version}
        )
        
        return jsonify({
            'success': True,
            'message': f'Rolled back to version {version_number}',
            'new_version': document.version
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error rolling back: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to rollback',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


