# 15. SUBMIT FOR REVIEW
# ============================================================

@app.route('/api/documents/<document_id>/submit', methods=['POST'])
@cross_origin()
@jwt_required
def submit_document_for_review(document_id):
    """Submit a document for review"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user can edit documents
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'edit'):
                return jsonify({
                    'success': False,
                    'error': 'Document editing not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE'
                }), 403
        
        from models import Document
        import uuid
        
        # ✅ Parse ID - support both integer and UUID
        doc_id_value = None
        try:
            # Try as integer first
            doc_id_value = int(document_id)
            id_filter = Document.id == doc_id_value
        except ValueError:
            try:
                # Try as UUID
                doc_uuid = uuid.UUID(document_id)
                id_filter = Document.id == doc_uuid
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid document ID format. Must be UUID or integer.',
                    'code': 'INVALID_ID'
                }), 400
        
        # Get document with scope
        if is_super_admin:
            document = Document.query.filter(id_filter).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter(
                    id_filter,
                    Document.company_id == user_company_id
                ).first()
            else:
                document = Document.query.filter(
                    id_filter,
                    Document.user_id == current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # ✅ Check permission
        if not is_super_admin and not can_edit_document(current_user, document, is_super_admin):
            return jsonify({
                'success': False,
                'error': 'You do not have permission to submit this document',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        if document.status not in ['draft', 'rejected']:
            return jsonify({
                'success': False,
                'error': 'Document cannot be submitted for review',
                'code': 'INVALID_STATUS'
            }), 400
        
        document.status = 'review'
        document.updated_at = datetime.utcnow()
        document.updated_by = current_user.id
        
        # Get reviewer ID if provided
        data = request.get_json() or {}
        reviewer_id = data.get('reviewer_id')
        if reviewer_id:
            try:
                # Try as integer
                document.reviewed_by = int(reviewer_id)
            except ValueError:
                try:
                    # Try as UUID
                    document.reviewed_by = uuid.UUID(reviewer_id)
                except ValueError:
                    pass
        
        db.session.commit()
        
        # Create audit log
        create_audit_log(
            document_id=document.id,
            user_id=current_user.id,
            action='submit',
            details={'reviewer_id': reviewer_id}
        )
        
        return jsonify({
            'success': True,
            'message': 'Document submitted for review'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error submitting document: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to submit document',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


