@app.route('/api/documents/<document_id>/comments', methods=['GET'])
@cross_origin()
@jwt_required
def get_document_comments(document_id):
    """Get document comments"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user has document access
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'view'):
                return jsonify({
                    'success': False,
                    'error': 'Document access not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE'
                }), 403
        
        from models import Document, DocumentComment
        import uuid
        
        # ✅✅✅ FIX: Parse ID - support both integer and UUID
        try:
            doc_id_int = int(document_id)
            id_filter = Document.id == doc_id_int
        except ValueError:
            try:
                doc_uuid = uuid.UUID(document_id)
                id_filter = Document.id == doc_uuid
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid document ID format. Must be UUID or integer.',
                    'code': 'INVALID_ID'
                }), 400
        
        # Get document with scope
        if is_super_admin:
            document = Document.query.filter(id_filter).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter(
                    id_filter,
                    Document.company_id == user_company_id
                ).first()
            else:
                document = Document.query.filter(
                    id_filter,
                    Document.user_id == current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # ✅ Check if user can access document
        if not is_super_admin and not can_access_document(current_user, document, is_super_admin):
            return jsonify({
                'success': False,
                'error': 'You do not have permission to view comments on this document',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # Get comments
        comments = DocumentComment.query.filter_by(
            document_id=document.id
        ).order_by(DocumentComment.created_at.asc()).all()
        
        comments_data = []
        for comment in comments:
            comments_data.append({
                'id': str(comment.id),
                'content': comment.content,
                'created_at': comment.created_at.isoformat() if comment.created_at else None,
                'user_id': str(comment.user_id) if comment.user_id else None,
                'user_name': comment.user.name if comment.user else None
            })
        
        return jsonify({
            'success': True,
            'comments': comments_data,
            'scope': 'all' if is_super_admin else ('company' if getattr(current_user, 'company_id', None) else 'user')
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error fetching comments: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to fetch comments',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500

