@app.route('/api/documents/<document_id>/comments', methods=['POST'])
@cross_origin()
@jwt_required
def add_document_comment(document_id):
    """Add a comment to a document"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import Document, DocumentComment
        import uuid
        
        # ✅✅✅ FIX: Parse ID - support both integer and UUID
        try:
            doc_id_int = int(document_id)
            id_filter = Document.id == doc_id_int
        except ValueError:
            try:
                doc_uuid = uuid.UUID(document_id)
                id_filter = Document.id == doc_uuid
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid document ID format',
                    'code': 'INVALID_ID'
                }), 400
        
        # Get document with scope
        if is_super_admin:
            document = Document.query.filter(id_filter).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter(
                    id_filter,
                    Document.company_id == user_company_id
                ).first()
            else:
                document = Document.query.filter(
                    id_filter,
                    Document.user_id == current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # Check permission
        if not is_super_admin and not can_access_document(current_user, document, is_super_admin):
            return jsonify({
                'success': False,
                'error': 'You do not have permission to comment on this document',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        data = request.get_json()
        if not data or not data.get('content'):
            return jsonify({
                'success': False,
                'error': 'Comment content is required',
                'code': 'MISSING_CONTENT'
            }), 400
        
        content = data['content'].strip()
        if len(content) < 3:
            return jsonify({
                'success': False,
                'error': 'Comment must be at least 3 characters',
                'code': 'INVALID_COMMENT'
            }), 400
        
        if len(content) > 2000:
            return jsonify({
                'success': False,
                'error': 'Comment must be less than 2000 characters',
                'code': 'COMMENT_TOO_LONG'
            }), 400
        
        # ✅ Use integer ID for comment
        import time
        import random
        comment_id = int(time.time() * 1000000) + random.randint(1, 999)
        
        comment = DocumentComment(
            id=comment_id,
            document_id=document.id,
            user_id=current_user.id,
            content=content,
            parent_id=data.get('parent_id')
        )
        
        db.session.add(comment)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Comment added successfully',
            'comment': {
                'id': str(comment.id),
                'content': comment.content,
                'created_at': comment.created_at.isoformat() if comment.created_at else None
            }
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error adding comment: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to add comment',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500


# ============================================================
