@app.route('/api/documents/comments/<comment_id>', methods=['PUT'])
@cross_origin()
@jwt_required
def update_document_comment(comment_id):
    """Update a comment"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import DocumentComment
        
        try:
            comment_uuid = uuid.UUID(comment_id)
        except ValueError:
            return jsonify({
                'success': False,
                'error': 'Invalid comment ID format',
                'code': 'INVALID_ID'
            }), 400
        
        comment = DocumentComment.query.filter_by(id=comment_uuid).first()
        
        if not comment:
            return jsonify({
                'success': False,
                'error': 'Comment not found',
                'code': 'COMMENT_NOT_FOUND'
            }), 404
        
        # Check permission (only author can update)
        if comment.user_id != current_user.id and not is_super_admin:
            return jsonify({
                'success': False,
                'error': 'You do not have permission to update this comment',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        data = request.get_json()
        if not data or not data.get('content'):
            return jsonify({
                'success': False,
                'error': 'Comment content is required',
                'code': 'MISSING_CONTENT'
            }), 400
        
        content = data['content'].strip()
        if len(content) < 3:
            return jsonify({
                'success': False,
                'error': 'Comment must be at least 3 characters',
                'code': 'INVALID_COMMENT'
            }), 400
        
        if len(content) > 2000:
            return jsonify({
                'success': False,
                'error': 'Comment must be less than 2000 characters',
                'code': 'COMMENT_TOO_LONG'
            }), 400
        
        comment.content = content
        comment.updated_at = datetime.utcnow()
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Comment updated successfully'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error updating comment: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to update comment',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500

@app.route('/api/documents/<document_id>/review-detail', methods=['GET'])
@cross_origin()
@jwt_required
def get_document_review_detail(document_id):
    """Get detailed review information for a document"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        from models import Document, DocumentComment, DocumentAuditLog
        import uuid
        
        # ✅ Parse ID - support both integer and UUID
        try:
            doc_id_int = int(document_id)
            id_filter = Document.id == doc_id_int
        except ValueError:
            try:
                doc_uuid = uuid.UUID(document_id)
                id_filter = Document.id == doc_uuid
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Invalid document ID format. Must be UUID or integer.',
                    'code': 'INVALID_ID'
                }), 400
        
        # Get document
        if is_super_admin:
            document = Document.query.filter(id_filter).first()
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                document = Document.query.filter(
                    id_filter,
                    Document.company_id == user_company_id
                ).first()
            else:
                document = Document.query.filter(
                    id_filter,
                    Document.user_id == current_user.id
                ).first()
        
        if not document:
            return jsonify({
                'success': False,
                'error': 'Document not found',
                'code': 'DOCUMENT_NOT_FOUND'
            }), 404
        
        # ✅ Check if user can access document
        if not is_super_admin and not can_access_document(current_user, document, is_super_admin):
            return jsonify({
                'success': False,
                'error': 'You do not have permission to view this document',
                'code': 'PERMISSION_DENIED'
            }), 403
        
        # ✅ Get review comments
        review_comments = DocumentComment.query.filter_by(
            document_id=document.id
        ).order_by(DocumentComment.created_at.desc()).limit(50).all()
        
        # ✅ Get review history (audit logs with review actions)
        review_actions = ['submit', 'review', 'approve', 'reject', 'publish']
        audit_logs = DocumentAuditLog.query.filter(
            DocumentAuditLog.document_id == document.id,
            DocumentAuditLog.action.in_(review_actions)
        ).order_by(DocumentAuditLog.created_at.desc()).limit(50).all()
        
        # ✅ Build response
        return jsonify({
            'success': True,
            'document': {
                'id': document.id,
                'title': document.title,
                'status': document.status,
                'document_type': document.document_type
            },
            'review_comments': [
                {
                    'id': comment.id,
                    'content': comment.content,
                    'created_at': comment.created_at.isoformat() if comment.created_at else None,
                    'user_name': comment.user.name if comment.user else None
                }
                for comment in review_comments
            ],
            'review_history': [
                {
                    'action': log.action,
                    'details': log.details,
                    'created_at': log.created_at.isoformat() if log.created_at else None,
                    'user_name': log.user.name if log.user else None
                }
                for log in audit_logs
            ],
            'review_status': {
                'current_status': document.status,
                'reviewed_at': document.reviewed_at.isoformat() if document.reviewed_at else None,
                'reviewed_by': document.reviewed_by,
                'approved_at': document.approved_at.isoformat() if document.approved_at else None,
                'approved_by': document.approved_by,
                'published_at': document.published_at.isoformat() if document.published_at else None
            }
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error getting review detail: {str(e)}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'Failed to get review details',
            'details': str(e) if current_app.debug else 'Please try again',
            'code': 'INTERNAL_ERROR'
        }), 500

