@app.route('/api/documents/templates', methods=['GET'])
@cross_origin()
@jwt_required
def get_templates():
    """Get document templates with filters"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user has document access
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'view'):
                return jsonify({
                    'success': False,
                    'error': 'Document access not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE'
                }), 403
        
        search = request.args.get('search', '')
        category = request.args.get('category')
        document_type = request.args.get('document_type')
        module = request.args.get('module')
        limit = request.args.get('limit', 20, type=int)
        offset = request.args.get('offset', 0, type=int)
        
        from models import DocumentTemplate
        
        # ✅ Build query with scope
        if is_super_admin:
            query = DocumentTemplate.query
        else:
            user_company_id = getattr(current_user, 'company_id', None)
            if user_company_id:
                query = DocumentTemplate.query.filter(
                    or_(
                        DocumentTemplate.company_id == user_company_id,
                        DocumentTemplate.is_public == True
                    )
                )
            else:
                query = DocumentTemplate.query.filter(
                    DocumentTemplate.is_public == True
                )
        
        # Apply filters
        if search:
            search_term = f"%{search}%"
            query = query.filter(
                or_(
                    DocumentTemplate.name.ilike(search_term),
                    DocumentTemplate.description.ilike(search_term)
                )
            )
        
        if category:
            query = query.filter_by(category=category)
        if document_type:
            query = query.filter_by(document_type=document_type)
        if module:
            query = query.filter_by(module=module)
        
        # Only show active templates
        query = query.filter_by(is_active=True)
        
        total = query.count()
        templates = query.limit(limit).offset(offset).all()
        
        return jsonify({
            'success': True,
            'templates': [t.to_dict() for t in templates],
            'total': total,
            'limit': limit,
            'offset': offset,
            'scope': 'all' if is_super_admin else ('company' if getattr(current_user, 'company_id', None) else 'user')
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error getting templates: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/documents/templates', methods=['POST'])
@cross_origin()
@jwt_required
def create_template():
    """Create a new document template"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # ✅ Check if user can create documents
        if not is_super_admin:
            if not has_document_feature_access(current_user, 'create'):
                return jsonify({
                    'success': False,
                    'error': 'Document creation not available in your plan',
                    'code': 'FEATURE_NOT_AVAILABLE'
                }), 403
        
        data = request.get_json()
        if not data:
            return jsonify({
                'success': False,
                'error': 'No data provided'
            }), 400
        
        # Validate required fields
        required = ['name', 'document_type']
        for field in required:
            if not data.get(field):
                return jsonify({
                    'success': False,
                    'error': f'Missing required field: {field}'
                }), 400
        
        from models import DocumentTemplate
        
        user_company_id = getattr(current_user, 'company_id', None)
        
        template = DocumentTemplate(
            company_id=user_company_id,
            user_id=current_user.id,
            name=data['name'],
            description=data.get('description', ''),
            category=data.get('category'),
            document_type=data['document_type'],
            module=data.get('module', 'general'),
            template_content=data.get('template_content', ''),
            template_variables=data.get('template_variables', {}),
            preview_image=data.get('preview_image'),
            is_public=data.get('is_public', False),
            is_system=False,
            created_by=current_user.id
        )
        
        db.session.add(template)
        db.session.commit()
        
        return jsonify({
            'success': True,
            'template': template.to_dict(),
            'message': 'Template created successfully',
            'scope': 'company' if user_company_id else 'user'
        }), 201
        
    except Exception as e:
        db.session.rollback()
        current_app.logger.error(f"Error creating template: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


