# ============================================================
# DOCUMENT PERMISSIONS ENDPOINT
# ============================================================

@app.route('/api/documents/permissions', methods=['GET'])
@jwt_required
def get_document_permissions():
    """Get document permissions for current user based on role and plan"""
    try:
        current_user = request.user
        is_super_admin = check_super_admin()
        
        # Get user's plan
        user_plan = getattr(current_user, 'subscription_plan', 'free')
        user_type = getattr(current_user, 'user_type', 'user')
        user_role = getattr(current_user, 'role', 'user')
        
        # ✅ Get company_id
        company_id = getattr(current_user, 'company_id', None)
        is_system_team = getattr(current_user, 'is_system_team', False)
        is_platform_owner = getattr(current_user, 'is_platform_owner', False)
        
        # ============================================================
        # DETERMINE USER ROLE LEVEL
        # ============================================================
        is_admin = False
        is_company_admin = False
        
        # ✅ Check admin status from various sources
        if is_super_admin:
            is_admin = True
            is_company_admin = True
        elif is_system_team:
            is_admin = True
            is_company_admin = True
        elif is_platform_owner:
            is_admin = True
            is_company_admin = True
        elif user_type in ['admin', 'company_admin', 'hospital_admin', 'safety_manager']:
            is_admin = True
            is_company_admin = True
        elif user_role in ['admin', 'company_admin', 'hospital_admin', 'safety_manager']:
            is_admin = True
            is_company_admin = True
        elif getattr(current_user, 'is_admin', False):
            is_admin = True
            is_company_admin = True
        
        # Check if user is a document admin/manager
        is_document_admin = False
        if hasattr(current_user, 'permissions'):
            perms = current_user.permissions
            if isinstance(perms, dict):
                is_document_admin = perms.get('document_admin', False) or perms.get('document_manager', False)
        
        # ============================================================
        # BASE PERMISSIONS (Everyone gets these)
        # ============================================================
        permissions = {
            # View permissions
            'can_view': True,
            'can_view_all': is_admin or is_super_admin or is_system_team,
            'can_view_company': True if company_id else False,
            'can_view_own': True,
            
            # Create permissions
            'can_create': True,  # All users can create documents
            'can_create_company': is_admin or is_super_admin or is_system_team,
            'can_upload': True,  # All users can upload
            'can_upload_company': is_admin or is_super_admin or is_system_team,
            
            # Edit permissions
            'can_edit': False,
            'can_edit_own': True,  # Users can edit their own documents
            'can_edit_company': False,  # Company admin can edit company docs
            'can_edit_all': False,  # Super admin can edit all
            
            # Delete permissions
            'can_delete': False,
            'can_delete_own': True,  # Users can delete their own documents
            'can_delete_company': False,  # Company admin can delete company docs
            'can_delete_all': False,  # Super admin can delete all
            
            # Share permissions
            'can_share': False,
            'can_share_own': True,
            'can_share_company': False,
            'can_share_all': False,
            
            # Version control
            'can_version': False,
            'can_version_own': True,
            'can_version_company': False,
            'can_version_all': False,
            
            # Approval permissions
            'can_approve': False,
            'can_approve_company': False,
            'can_approve_all': False,
            
            # Archive permissions
            'can_archive': False,
            'can_archive_own': True,
            'can_archive_company': False,
            'can_archive_all': False,
            
            # Admin permissions
            'can_manage_users': False,
            'can_manage_roles': False,
            'can_manage_templates': False,
            'can_manage_categories': False,
            'can_manage_workflows': False,
            'can_manage_compliance': False,
            
            # Additional info
            'is_admin': is_admin,
            'is_super_admin': is_super_admin,
            'is_company_admin': is_company_admin,
            'user_type': user_type,
            'user_role': user_role,
            'plan': user_plan,
            'company_id': company_id,
            'access_level': 'super_admin' if is_super_admin else ('admin' if is_admin else 'user')
        }
        
        # ============================================================
        # ASSIGN PERMISSIONS BASED ON ROLE
        # ============================================================
        
        # ✅ SUPER ADMIN - Full access to everything
        if is_super_admin:
            permissions = {k: True for k in permissions.keys()}
            permissions['is_admin'] = True
            permissions['is_super_admin'] = True
            permissions['is_company_admin'] = True
            permissions['access_level'] = 'super_admin'
            
        # ✅ SYSTEM TEAM - Full access
        elif is_system_team:
            permissions = {k: True for k in permissions.keys()}
            permissions['is_admin'] = True
            permissions['is_super_admin'] = False
            permissions['is_company_admin'] = True
            permissions['access_level'] = 'system_team'
            
        # ✅ PLATFORM OWNER - Full access
        elif is_platform_owner:
            permissions = {k: True for k in permissions.keys()}
            permissions['is_admin'] = True
            permissions['is_super_admin'] = False
            permissions['is_company_admin'] = True
            permissions['access_level'] = 'platform_owner'
            
        # ✅ COMPANY ADMIN / HOSPITAL ADMIN / SAFETY MANAGER
        elif is_company_admin or is_document_admin:
            # Can do everything within their company
            permissions['can_edit'] = True
            permissions['can_edit_company'] = True
            permissions['can_delete'] = True
            permissions['can_delete_company'] = True
            permissions['can_share'] = True
            permissions['can_share_company'] = True
            permissions['can_version'] = True
            permissions['can_version_company'] = True
            permissions['can_approve'] = True
            permissions['can_approve_company'] = True
            permissions['can_archive'] = True
            permissions['can_archive_company'] = True
            permissions['can_view_all'] = True
            permissions['can_view_company'] = True
            permissions['can_upload_company'] = True
            permissions['can_create_company'] = True
            
            # Admin capabilities
            permissions['can_manage_users'] = True
            permissions['can_manage_roles'] = True
            permissions['can_manage_templates'] = True
            permissions['can_manage_categories'] = True
            permissions['can_manage_workflows'] = True
            permissions['can_manage_compliance'] = True
            
            permissions['is_admin'] = True
            permissions['is_company_admin'] = True
            permissions['access_level'] = 'admin'
            
        # ✅ PRO, BUSINESS, ENTERPRISE PLANS (Regular users with more features)
        elif user_plan in ['pro', 'business', 'enterprise']:
            # Users can edit their own documents
            permissions['can_edit_own'] = True
            permissions['can_delete_own'] = True
            permissions['can_share_own'] = True
            permissions['can_version_own'] = True
            permissions['can_archive_own'] = True
            
            # ✅ BUSINESS and ENTERPRISE can approve
            if user_plan in ['business', 'enterprise']:
                permissions['can_approve'] = True
                permissions['can_approve_company'] = True
                permissions['can_manage_compliance'] = True
            
            # ✅ ENTERPRISE gets all company-level features
            if user_plan == 'enterprise':
                permissions['can_edit_company'] = True
                permissions['can_delete_company'] = True
                permissions['can_share_company'] = True
                permissions['can_version_company'] = True
                permissions['can_archive_company'] = True
                permissions['can_view_all'] = True
                permissions['can_view_company'] = True
            
            # ✅ Company admins from any plan get admin features
            if is_company_admin:
                permissions['can_manage_users'] = True
                permissions['can_manage_roles'] = True
                permissions['can_manage_templates'] = True
                permissions['can_manage_categories'] = True
                permissions['can_manage_workflows'] = True
                
            permissions['access_level'] = 'user'
            
        # ✅ BASIC PLAN (Regular users)
        elif user_plan == 'basic':
            # Users can edit their own documents
            permissions['can_edit_own'] = True
            permissions['can_delete_own'] = True
            permissions['can_share_own'] = True
            permissions['can_version_own'] = True
            permissions['can_archive_own'] = True
            
            # Company admins from basic plan get admin features
            if is_company_admin:
                permissions['can_manage_users'] = True
                permissions['can_manage_roles'] = True
                permissions['can_manage_templates'] = True
                
            permissions['access_level'] = 'user'
            
        # ✅ FREE PLAN (Regular users)
        else:  # free plan
            # Users can only edit/delete their own documents
            permissions['can_edit_own'] = True
            permissions['can_delete_own'] = True
            
            # Company admins from free plan still get some admin features
            if is_company_admin:
                permissions['can_manage_users'] = True
                permissions['can_manage_templates'] = True
            
            permissions['access_level'] = 'user'
        
        # ============================================================
        # ADD USER INFO FOR DEBUGGING
        # ============================================================
        user_info = {
            'id': current_user.id,
            'email': current_user.email,
            'user_type': user_type,
            'role': user_role,
            'plan': user_plan,
            'company_id': company_id,
            'is_super_admin': is_super_admin,
            'is_system_team': is_system_team,
            'is_platform_owner': is_platform_owner,
            'is_company_admin': is_company_admin,
            'is_document_admin': is_document_admin
        }
        
        return jsonify({
            'success': True,
            'permissions': permissions,
            'user_info': user_info,
            'plan': user_plan,
            'access_level': permissions['access_level']
        }), 200
        
    except Exception as e:
        current_app.logger.error(f"Error getting document permissions: {str(e)}")
        import traceback
        traceback.print_exc()
        
        # Return safe defaults on error
        return jsonify({
            'success': False,
            'error': str(e),
            'permissions': {
                'can_view': True,
                'can_create': True,
                'can_upload': True,
                'can_edit': False,
                'can_delete': False,
                'can_share': False,
                'can_version': False,
                'can_approve': False,
                'can_archive': False,
                'is_admin': False,
                'is_super_admin': False,
                'is_company_admin': False,
                'access_level': 'user'
            }
        }), 200

# -- ERROR HANDLERS --

@app.errorhandler(404)
def not_found(error):
    return jsonify({'error': 'Endpoint not found', 'path': request.path}), 404

@app.errorhandler(405)
def method_not_allowed(error):
    return jsonify({'error': 'Method not allowed'}), 405

@app.errorhandler(500)
def internal_error(error):
    current_app.logger.error(f'Server Error: {error}')
    return jsonify({'error': 'Internal server error'}), 500

@app.errorhandler(413)
def too_large(error):
    return jsonify({'error': 'File too large. Maximum size is 50MB.'}), 413

@app.errorhandler(429)
def ratelimit_handler(e):
    return jsonify({'error': 'Rate limit exceeded', 'message': str(e.description)}), 429


@app.before_request
def apply_sqlalchemy_patch():
    """Apply SQLAlchemy 2.0 patch automatically"""
    # This will fix db.session.execute() calls
    if not hasattr(db.session, '_patched_for_sqlalchemy_2'):
        original_execute = db.session.execute
        
        def patched_execute(statement, *args, **kwargs):
            if isinstance(statement, str):
                statement = text(statement)
            return original_execute(statement, *args, **kwargs)
        
        db.session.execute = patched_execute
        db.session._patched_for_sqlalchemy_2 = True

