@app.errorhandler(Exception)
def handle_all_exceptions(e):
    """Catch ALL exceptions with full traceback"""
    print("\n" + "🔥"*80)
    print("🔥 UNHANDLED EXCEPTION - FULL TRACEBACK")
    print("🔥"*80)
    print(f"📅 Time: {datetime.utcnow().isoformat()}")
    print(f"🔗 Path: {request.path}")
    print(f"📋 Method: {request.method}")
    print(f"📍 Remote Addr: {request.remote_addr}")
    
    # Full traceback
    import traceback
    tb = traceback.format_exc()
    print(f"\n📜 FULL TRACEBACK:")
    print(tb)
    
    # Request details
    print(f"\n📨 REQUEST DETAILS:")
    print(f"  Headers: {dict(request.headers)}")
    print(f"  Args: {dict(request.args)}")
    if request.is_json:
        print(f"  JSON Body: {request.get_json(silent=True)}")
    
    # Check if it's a decorator issue
    if "'fn'" in str(e):
        print("\n🔍 SPECIAL DEBUG: 'fn' PARAMETER ERROR DETECTED")
        print("This usually means a decorator is not wrapping functions correctly.")
        print("Check decorator order and @wraps usage.")
    
    print("🔥"*80 + "\n")
    
    return jsonify({
        'success': False,
        'error': 'Internal server error',
        'message': str(e),
        'traceback': tb if app.debug else None
    }), 500

