@app.route('/api/debug/force-notification-templates', methods=['POST'])
def force_create_notification_templates():
    """Force create notification_templates table and data"""
    try:
        with app.app_context():
            from sqlalchemy import inspect
            inspector = inspect(db.engine)
            
            # Check if table exists before
            tables_before = inspector.get_table_names()
            notification_table_exists_before = 'notification_templates' in tables_before
            
            # Create the table using raw SQL if it doesn't exist
            if not notification_table_exists_before:
                create_sql = """
                CREATE TABLE IF NOT EXISTS notification_templates (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name VARCHAR(100) UNIQUE NOT NULL,
                    type VARCHAR(50) NOT NULL,
                    category VARCHAR(50) NOT NULL,
                    title_template VARCHAR(200) NOT NULL,
                    message_template TEXT NOT NULL,
                    default_priority VARCHAR(20) DEFAULT 'medium',
                    is_active BOOLEAN DEFAULT TRUE,
                    variables TEXT,
                    created_by VARCHAR(100),
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
                );
                """
                
                with db.engine.connect() as connection:
                    connection.execute(text(create_sql))
                    connection.commit()
                logger.info("✅ notification_templates table force created")
            
            # Now create the templates
            templates_created = create_initial_notification_templates()
            
            # Check after creation
            tables_after = inspector.get_table_names()
            notification_table_exists_after = 'notification_templates' in tables_after
            
            return jsonify({
                'success': True,
                'message': 'Notification templates force created',
                'details': {
                    'table_created': not notification_table_exists_before and notification_table_exists_after,
                    'table_exists': notification_table_exists_after,
                    'templates_created': templates_created,
                    'all_tables': tables_after
                }
            }), 200
            
    except Exception as e:
        logger.error(f"Error force creating notification templates: {str(e)}")
        return jsonify({
            'success': False, 
            'error': str(e),
            'details': 'Failed to create notification_templates table'
        }), 500

def create_initial_notification_templates():
    """Create initial notification templates with error handling"""
    try:
        templates = [
            {
                'name': 'new_incident_report',
                'type': 'incident_report',
                'category': 'safety',
                'title_template': '🚨 New Safety Incident Reported',
                'message_template': 'New {incident_type} incident reported in {industry_name} with {severity} severity',
                'default_priority': 'high',
                'variables': ['incident_type', 'industry_name', 'severity', 'location']
            },
            {
                'name': 'incident_status_update',
                'type': 'status_update',
                'category': 'safety',
                'title_template': '📋 Incident Status Updated',
                'message_template': 'Incident #{incident_number} status changed to {new_status}',
                'default_priority': 'medium',
                'variables': ['incident_number', 'new_status', 'notes']
            },
            {
                'name': 'investigator_assignment',
                'type': 'assignment',
                'category': 'safety',
                'title_template': '🔍 Investigation Assigned',
                'message_template': 'You have been assigned to investigate Incident #{incident_number}',
                'default_priority': 'high',
                'variables': ['incident_number', 'incident_title']
            }
        ]
        
        # Check if table exists first
        from sqlalchemy import inspect
        inspector = inspect(db.engine)
        if 'notification_templates' not in inspector.get_table_names():
            logger.warning("notification_templates table doesn't exist, creating templates later")
            return False
        
        created_count = 0
        for template_data in templates:
            if not NotificationTemplate.query.filter_by(name=template_data['name']).first():
                template = NotificationTemplate(**template_data)
                db.session.add(template)
                created_count += 1
        
        db.session.commit()
        logger.info(f"Created {created_count} notification templates")
        return True
        
    except Exception as e:
        logger.error(f"Error creating notification templates: {e}")
        return False

