def create_system_logs_table():
    """Create system_logs table using SQLAlchemy model or raw SQL"""
    try:
        # Try using SQLAlchemy first
        from sqlalchemy import inspect
        inspector = inspect(db.engine)
        
        if 'system_logs' not in inspector.get_table_names():
            # Create using raw SQL if model doesn't exist
            create_sql = """
            CREATE TABLE IF NOT EXISTS system_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                level VARCHAR(20) NOT NULL,
                module VARCHAR(100) NOT NULL,
                user_id VARCHAR(50),
                action VARCHAR(100) NOT NULL,
                resource_type VARCHAR(50),
                resource_id VARCHAR(50),
                description TEXT,
                ip_address VARCHAR(45),
                user_agent TEXT,
                request_method VARCHAR(10),
                request_path VARCHAR(500),
                status_code INTEGER,
                response_time FLOAT,
                error_message TEXT,
                stack_trace TEXT,
                additional_data TEXT
            );
            """
            
            with db.engine.connect() as connection:
                connection.execute(text(create_sql))
                connection.commit()
            
            logger.info("✅ system_logs table created successfully")
            return True
        else:
            logger.info("✅ system_logs table already exists")
            return True
            
    except Exception as e:
        logger.error(f"Error creating system_logs table: {e}")
        return False

