                    "CREATE INDEX IF NOT EXISTS idx_ai_pdf_batch_documents_generated_document_id ON ai_pdf_batch_documents(generated_document_id);",
                    
                    # PDF exports indexes
                    "CREATE INDEX IF NOT EXISTS idx_ai_pdf_exports_user_id ON ai_pdf_exports(user_id);",
