                    "CREATE INDEX IF NOT EXISTS idx_ai_pdf_exports_completed_at ON ai_pdf_exports(completed_at);",
                    
                    # PDF versions indexes
                    "CREATE INDEX IF NOT EXISTS idx_ai_pdf_versions_pdf_document_id ON ai_pdf_versions(pdf_document_id);",
