# ==================== HELPER FUNCTIONS ====================

def get_user_from_request():
    """Get current user from request context (set by jwt_required)"""
    user = getattr(request, 'user', None)
    if not user:
        return None, jsonify({
            'success': False,
            'error': 'User authentication failed',
            'code': 'AUTHENTICATION_ERROR'
        }), 401
    return user, None, None

def log_admin_action(user_id, action, resource_type=None, resource_id=None):
    """Log admin actions for audit trail using your existing AdminAuditLog model"""
    try:
        log = AdminAuditLog(
            user_id=user_id,
            action=action,
            resource_type=resource_type,
            resource_id=resource_id,
            ip_address=request.remote_addr,
            user_agent=request.headers.get('User-Agent'),
            timestamp=datetime.utcnow()
        )
        db.session.add(log)
        db.session.commit()
    except Exception as e:
        print(f"Failed to log admin action: {e}")
        db.session.rollback()


def add_pdf_tracking_columns():
    """Add PDF tracking columns to users table"""
    try:
        from sqlalchemy import inspect, text
        inspector = inspect(db.engine)
        
        # Check if users table exists
        if 'users' not in inspector.get_table_names():
            logger.warning("Users table doesn't exist")
            return False
        
        # Get existing columns
        columns = [col['name'] for col in inspector.get_columns('users')]
        
        changes_made = False
        
        # PDF tracking columns to add
        pdf_columns = [
            ('daily_pdf_generations', 'INTEGER DEFAULT 0'),
            ('monthly_pdf_generations', 'INTEGER DEFAULT 0'),
            ('total_pdf_documents', 'INTEGER DEFAULT 0'),
            ('last_pdf_generation_at', 'DATETIME'),
            ('pdf_templates_created', 'INTEGER DEFAULT 0'),
            ('max_pdf_templates', 'INTEGER DEFAULT 10')
        ]
        
        with db.engine.connect() as conn:
            for column_name, column_type in pdf_columns:
                if column_name not in columns:
                    try:
                        conn.execute(text(f"ALTER TABLE users ADD COLUMN {column_name} {column_type}"))
                        logger.info(f"✅ Added column: {column_name} to users table")
                        changes_made = True
                    except Exception as col_error:
                        logger.warning(f"Could not add column {column_name}: {col_error}")
            
            if changes_made:
                conn.commit()
        
        return changes_made
        
    except Exception as e:
        logger.error(f"❌ Error adding PDF tracking columns: {str(e)}")
        return False


def migrate_existing_pdf_data():
    """Migrate existing PDF data from old tables to new PDF tables"""
    try:
        with app.app_context():
            from sqlalchemy import text
            
            # Check if we need to migrate
            with db.engine.connect() as conn:
                # Check if old PDF data exists in ai_document_generations
                result = conn.execute(text("""
                    SELECT COUNT(*) as count 
                    FROM ai_document_generations 
                    WHERE output_format IN ('pdf', 'html') 
                    AND created_at > DATE('now', '-30 days')
                """)).fetchone()
                
                old_pdf_count = result[0] if result else 0
                
                if old_pdf_count == 0:
                    logger.info("No existing PDF data to migrate")
                    return {'success': True, 'migrated': 0, 'message': 'No data to migrate'}
                
                logger.info(f"Found {old_pdf_count} PDF/HTML documents to migrate")
                
                # Migrate PDF documents
                migration_sql = """
                    INSERT INTO ai_pdf_documents (
                        user_id, document_type, industry, quality_level,
                        generation_id, plan, system_team_bypass, created_at, updated_at
                    )
                    SELECT 
                        user_id, document_type, industry, quality_level,
                        id as generation_id, plan, system_team_bypass, created_at, created_at as updated_at
                    FROM ai_document_generations 
                    WHERE output_format IN ('pdf', 'html')
                    AND NOT EXISTS (
                        SELECT 1 FROM ai_pdf_documents 
                        WHERE ai_pdf_documents.generation_id = ai_document_generations.id
                    )
                """
                
                result = conn.execute(text(migration_sql))
                migrated_count = result.rowcount
                conn.commit()
                
                # Migrate corresponding generations
                if migrated_count > 0:
                    generation_migration_sql = """
                        INSERT INTO ai_pdf_generations (
                            user_id, pdf_document_id, document_type, industry,
                            plan, system_team_bypass, created_at
                        )
                        SELECT 
                            pd.user_id, pd.id as pdf_document_id, pd.document_type, pd.industry,
                            pd.plan, pd.system_team_bypass, pd.created_at
                        FROM ai_pdf_documents pd
                        WHERE pd.generation_id IN (
                            SELECT id FROM ai_document_generations 
                            WHERE output_format IN ('pdf', 'html')
                        )
                        AND NOT EXISTS (
                            SELECT 1 FROM ai_pdf_generations pg
                            WHERE pg.pdf_document_id = pd.id
                        )
                    """
                    
                    conn.execute(text(generation_migration_sql))
                    conn.commit()
                
                logger.info(f"✅ Migrated {migrated_count} PDF documents to new tables")
                
                return {
                    'success': True,
                    'migrated': migrated_count,
                    'message': f'Migrated {migrated_count} PDF documents'
                }
                
    except Exception as e:
        logger.error(f"❌ PDF migration error: {str(e)}")
        return {
            'success': False,
            'error': str(e),
            'message': 'Migration failed'
        }


def initialize_ai_database():
    """Initialize all AI database components"""
    try:
        logger.info("Initializing AI database...")
        
        # Ensure all tables exist
        tables_result = ensure_ai_tables_exist()
        
        if not tables_result['success']:
            logger.error(f"Failed to create AI tables: {tables_result.get('error')}")
            return tables_result
        
        # Migrate existing data
        migration_result = migrate_existing_pdf_data()
        
        logger.info("✅ AI database initialization completed")
        
        return {
            'success': True,
            'tables_created': tables_result.get('created_tables', []),
            'tables_migrated': migration_result.get('migrated', 0),
            'total_ai_tables': tables_result.get('total_ai_tables', 0)
        }
        
    except Exception as e:
        logger.error(f"❌ AI database initialization failed: {str(e)}")
        return {
            'success': False,
            'error': str(e)
        }


def cleanup_old_ai_data(days_old=90):
    """Clean up old AI data to save storage space"""
    try:
        with app.app_context():
            from sqlalchemy import text
            import datetime
            
            cutoff_date = datetime.datetime.utcnow() - datetime.timedelta(days=days_old)
            cutoff_str = cutoff_date.strftime('%Y-%m-%d %H:%M:%S')
            
            cleanup_tables = [
                'ai_html_previews',
                'ai_smart_query_logs',
                'ai_query_logs',
                'ai_chat_messages',
                'ai_pdf_analyses',
                'ai_pdf_downloads',
                'ai_pdf_generation_errors'
            ]
            
            deleted_counts = {}
            
            with db.engine.connect() as conn:
                for table in cleanup_tables:
                    try:
                        # Check if table exists
                        result = conn.execute(text(f"SELECT name FROM sqlite_master WHERE type='table' AND name='{table}'")).fetchone()
                        if not result:
                            continue
                        
                        # Delete old records
                        delete_sql = f"DELETE FROM {table} WHERE created_at < '{cutoff_str}'"
                        result = conn.execute(text(delete_sql))
                        deleted_counts[table] = result.rowcount
                        
                    except Exception as table_error:
                        logger.warning(f"Could not clean up {table}: {table_error}")
                
                conn.commit()
            
            # Vacuum database to reclaim space
            try:
                with db.engine.connect() as conn:
                    conn.execute(text("VACUUM"))
                    conn.commit()
            except:
                pass  # VACUUM might not work in some configurations
            
            logger.info(f"✅ Cleaned up old AI data (older than {days_old} days)")
            
            return {
                'success': True,
                'cutoff_date': cutoff_str,
                'deleted_counts': deleted_counts,
                'total_deleted': sum(deleted_counts.values())
            }
            
    except Exception as e:
        logger.error(f"❌ AI data cleanup failed: {str(e)}")
        return {
            'success': False,
            'error': str(e)
        }
    
