def add_document_fields_to_users():
    """Add document-related fields to the users table if they don't exist"""
    try:
        from sqlalchemy import text, inspect
        
        inspector = inspect(db.engine)
        
        # Check if users table exists first
        if 'users' not in inspector.get_table_names():
            logger.warning("Users table doesn't exist yet")
            return False
        
        # Get existing columns
        columns = [col['name'] for col in inspector.get_columns('users')]
        
        changes_made = False
        
        # Add documents_uploaded column if it doesn't exist
        if 'documents_uploaded' not in columns:
            try:
                db.session.execute(text('ALTER TABLE users ADD COLUMN documents_uploaded BOOLEAN DEFAULT FALSE'))
                logger.info("✅ Added documents_uploaded column to users table")
                changes_made = True
            except Exception as col_error:
                logger.warning(f"Could not add documents_uploaded column: {col_error}")
        
        # Add documents_verified column if it doesn't exist
        if 'documents_verified' not in columns:
            try:
                db.session.execute(text('ALTER TABLE users ADD COLUMN documents_verified BOOLEAN DEFAULT FALSE'))
                logger.info("✅ Added documents_verified column to users table")
                changes_made = True
            except Exception as col_error:
                logger.warning(f"Could not add documents_verified column: {col_error}")
        
        # Add documents_uploaded_at column if it doesn't exist
        if 'documents_uploaded_at' not in columns:
            try:
                db.session.execute(text('ALTER TABLE users ADD COLUMN documents_uploaded_at DATETIME'))
                logger.info("✅ Added documents_uploaded_at column to users table")
                changes_made = True
            except Exception as col_error:
                logger.warning(f"Could not add documents_uploaded_at column: {col_error}")
        
        if changes_made:
            db.session.commit()
            
            # Update existing users to have default values
            users = User.query.all()
            updated_count = 0
            
            for user in users:
                if hasattr(user, 'documents_uploaded') and user.documents_uploaded is None:
                    user.documents_uploaded = False
                    updated_count += 1
                
                if hasattr(user, 'documents_verified') and user.documents_verified is None:
                    user.documents_verified = False
                    updated_count += 1
            
            if updated_count > 0:
                db.session.commit()
                logger.info(f"✅ Updated {updated_count} users with default document values")
        
        return True
        
    except Exception as e:
        logger.error(f"❌ Error adding document fields: {str(e)}")
        db.session.rollback()
        return False

