def initialize_required_documents():
    """Create default required document types"""
    try:
        default_documents = [
            {
                'document_type': 'business_license',
                'display_name': 'Business License',
                'description': 'Official business license or registration',
                'required_for_types': ['admin', 'enterprise'],
                'required_for_plans': ['pro', 'custom'],
                'is_verification_required': True
            },
            {
                'document_type': 'id_card',
                'display_name': 'Government ID',
                'description': 'Government-issued identification (Passport, Driver\'s License)',
                'required_for_types': ['all'],
                'required_for_plans': ['all'],
                'is_verification_required': True
            },
            {
                'document_type': 'proof_of_address',
                'display_name': 'Proof of Address',
                'description': 'Utility bill or bank statement showing business address',
                'required_for_types': ['admin', 'enterprise'],
                'required_for_plans': ['pro', 'custom'],
                'is_verification_required': True
            },
            {
                'document_type': 'tax_certificate',
                'display_name': 'Tax Registration Certificate',
                'description': 'Tax identification or registration certificate',
                'required_for_types': ['enterprise'],
                'required_for_plans': ['custom'],
                'is_verification_required': True
            }
        ]
        
        for doc_data in default_documents:
            existing = RequiredDocument.query.filter_by(document_type=doc_data['document_type']).first()
            if not existing:
                doc = RequiredDocument(
                    document_type=doc_data['document_type'],
                    display_name=doc_data['display_name'],
                    description=doc_data['description'],
                    required_for_types=doc_data['required_for_types'],
                    required_for_plans=doc_data['required_for_plans'],
                    is_verification_required=doc_data['is_verification_required']
                )
                db.session.add(doc)
        
        db.session.commit()
        logger.info("Required documents initialized")
        
    except Exception as e:
        logger.error(f"Error initializing required documents: {str(e)}")
        db.session.rollback()

