def register_all_generators(hub):
    """Register all generators with the hub"""
    # ============ REGISTER PERMIT GENERATORS ============
    permit_count = 0
    for generator in [
        EnhancedConstructionPermitGenerator(),
        EnhancedOilGasPermitGenerator(),
        EnhancedHealthcarePermitGenerator(),
        EnhancedManufacturingPermitGenerator(),
        EnhancedMiningPermitGenerator(),
        EnhancedAviationPermitGenerator(),
        EnhancedMaritimePermitGenerator(),
        EnhancedChemicalPermitGenerator(),
        EnhancedEnergyPermitGenerator(),
        EnhancedTransportationPermitGenerator(),
        EnhancedPharmaceuticalPermitGenerator(),
        EnhancedFoodBeveragePermitGenerator(),
        EnhancedEducationPermitGenerator(),
        EnhancedHospitalityPermitGenerator(),
        EnhancedRetailPermitGenerator(),
        EnhancedTelecomPermitGenerator(),
        EnhancedGeneralPermitGenerator()
    ]:
        hub.register_instance(generator)
        permit_count += 1
    
    # ============ REGISTER RISK ASSESSMENTS ============
    risk_count = 0
    for assessment in [
        AviationRiskAssessment(),
        ChemicalRiskAssessment(),
        ConstructionRiskAssessment(),
        EnergyRiskAssessment(),
        HealthcareRiskAssessment(),
        ManufacturingRiskAssessment(),
        MaritimeRiskAssessment(),
        MiningRiskAssessment(),
        OilGasRiskAssessment()
    ]:
        hub.register_instance(assessment)
        risk_count += 1
    
    # ============ REGISTER SPECIALIZED TEMPLATES ============
    template_count = 0
    for template in [
        ConstructionSpecializedTemplates(),
        HealthcareSpecializedTemplates(),
        ManufacturingSpecializedTemplates(),
        AviationSpecializedTemplates(),
        EmergencyResponseTemplates(),
        IncidentManagementTemplates(),
        InspectionMonitoringTemplates(),
        OperationalSafetyTemplates(),
        SafetyManagementTemplates(),
        ContractorManagementTemplates(),
        EnvironmentalTemplates(),
        HealthHygieneTemplates(),
        EquipmentSafetyTemplates()
    ]:
        hub.register_instance(template)
        template_count += 1
    
    logger.info(f"Registered {permit_count} permit generators, {risk_count} risk assessments, {template_count} specialized templates")
    return permit_count, risk_count, template_count



def initialize_hse_document_system():
    """Initialize the HSE Document System"""
    global _hse_document_hub, html_template_engine, PDF_AVAILABLE, DOCX_AVAILABLE, _hse_stylist
    
    logger.info("🚀 Initializing HSE Document System...")
    
    try:
        # Create hub WITHOUT auto-discovery
        _hse_document_hub = HSEDocumentGeneratorHub()
        
        print("\n📦 Manually registering all generators...")
        permit_count, risk_count, template_count = register_all_generators(_hse_document_hub)
        
        # Initialize compatibility engine
        html_template_engine = HTMLTemplateEngineCompatibility(_hse_document_hub)
        
        # ✅ FIXED: Initialize the HSE HTML Stylist WITH the hub
        stylist_ready = False
        try:
            print("\n🔧 Creating HSEHTMLStylist instance with hub...")
            # PASS THE HUB HERE!
            _hse_stylist = HSEHTMLStylist(hub=_hse_document_hub)
            
            # Attach to html_template_engine for backward compatibility
            html_template_engine.stylist = _hse_stylist
            
            print(f"✅ HSEHTMLStylist created: {type(_hse_stylist).__name__}")
            print(f"   Hub attached: {_hse_stylist.hub is not None}")
            logger.info("✅ HSEHTMLStylist initialized successfully")
            stylist_ready = True
            
            # Verify stylist has required methods
            if hasattr(_hse_stylist, 'format_html_document'):
                print("✅ stylist.format_html_document method exists")
            else:
                print("❌ stylist.format_html_document method MISSING")
                stylist_ready = False
                
        except Exception as e:
            print(f"❌ HSEHTMLStylist initialization error: {e}")
            import traceback
            traceback.print_exc()
            logger.error(f"❌ Failed to initialize HSEHTMLStylist: {e}")
            _hse_stylist = None
            stylist_ready = False
        
        # Check for PDF libraries
        try:
            import weasyprint
            PDF_AVAILABLE = True
            logger.info("✅ PDF export available (weasyprint)")
        except ImportError:
            PDF_AVAILABLE = False
            logger.warning("⚠️ PDF export not available (install weasyprint)")
        
        try:
            import docx
            DOCX_AVAILABLE = True
            logger.info("✅ DOCX export available (python-docx)")
        except ImportError:
            DOCX_AVAILABLE = False
            logger.warning("⚠️ DOCX export not available (install python-docx)")
        
        # Final status
        templates_count = len(_hse_document_hub.templates) if hasattr(_hse_document_hub, 'templates') else 0
        logger.info(f"✅ HSE Document System ready: {templates_count} templates")
        
        return {
            'success': True,
            'templates': templates_count,
            'industries': len(_hse_document_hub.industry_map) if hasattr(_hse_document_hub, 'industry_map') else 0,
            'permits': permit_count,
            'risk_assessments': risk_count,
            'specialized': template_count,
            'pdf_available': PDF_AVAILABLE,
            'docx_available': DOCX_AVAILABLE,
            'stylist_ready': stylist_ready,
            'stylist_type': str(type(_hse_stylist)) if _hse_stylist else None
        }
        
    except Exception as e:
        logger.error(f"❌ HSE Document System initialization failed: {e}")
        import traceback
        traceback.print_exc()
        return {'success': False, 'error': str(e), 'traceback': traceback.format_exc()}

def get_hse_stylist():
    """Get the HSE HTML Stylist instance"""
    global _hse_stylist, html_template_engine, _hse_document_hub
    
    print("\n🔍 get_hse_stylist() called")
    
    # Return cached stylist if available
    if _hse_stylist is not None:
        # If stylist exists but hub is missing, try to update it
        if _hse_stylist.hub is None and _hse_document_hub is not None:
            print("🔄 Updating existing stylist with hub")
            _hse_stylist.hub = _hse_document_hub
        print(f"✅ Returning cached stylist: {type(_hse_stylist).__name__}, hub: {_hse_stylist.hub is not None}")
        return _hse_stylist
    
    # Try to get from html_template_engine
    if html_template_engine and hasattr(html_template_engine, 'stylist'):
        _hse_stylist = html_template_engine.stylist
        if _hse_stylist:
            print(f"✅ Got stylist from html_template_engine: {type(_hse_stylist).__name__}")
            return _hse_stylist
    
    # Initialize if needed
    if _hse_stylist is None:
        print("🔄 Creating new HSEHTMLStylist instance...")
        try:
            # ✅ FIXED: Pass hub when creating new stylist
            _hse_stylist = HSEHTMLStylist(hub=_hse_document_hub)
            if html_template_engine:
                html_template_engine.stylist = _hse_stylist
            print(f"✅ Created new stylist with hub: {_hse_stylist.hub is not None}")
            return _hse_stylist
        except Exception as e:
            print(f"❌ Failed to create stylist: {e}")
            return None
    
    print("❌ No stylist available")
    return None



# Make sure your HTMLTemplateEngineCompatibility class has stylist attribute
class HTMLTemplateEngineCompatibility:
    def __init__(self, hub):
        self.hub = hub
        self.stylist = None  # Will be set by initialize_hse_document_system
        self.storage_manager = StorageManager()  # Or whatever storage you use
    
    def get_template_list(self):
        """Get list of available templates"""
        if self.hub:
            return [
                {'id': tid, 'name': tid.replace('_', ' ').title()}
                for tid in self.hub.templates.keys()
            ]
        return []


def initialize_system():
    """Initialize the complete system with proper separation"""
    # =========================================================================
    # INITIALIZATION HEADER
    # =========================================================================
    _log_initialization_header()
    
    try:
        # =========================================================================
        # PHASE 0: PRE-INITIALIZATION CHECKS
        # =========================================================================
        _log_phase_header("PHASE 0: PRE-INITIALIZATION MODEL REGISTRY CHECK")
        _perform_pre_initialization_checks()
        
        # =========================================================================
        # PHASE 1: BACKGROUND SERVICES
        # =========================================================================
        _log_phase_header("PHASE 1: STARTING BACKGROUND SERVICES")
        _start_background_services()
        
        # =========================================================================
        # PHASE 2: DATABASE INITIALIZATION
        # =========================================================================
        _log_phase_header("PHASE 2: DATABASE INITIALIZATION")
        
        with app.app_context():
            # Track initialization results
            init_results = {
                'ai_database': False,
                'powerbi_tables': False,
                'construction_db': False,
                'admin_created': False,
                'hse_document_system': False,
                'thermal_monitoring_tables': 0
            }
            
            # 2.1-2.3 Core database setup
            init_results.update(_initialize_core_database())
            
            # 2.4 AI Database
            init_results['ai_database'] = _initialize_ai_database_section()
            
            # 2.5 Power BI Tables
            init_results['powerbi_tables'] = _initialize_powerbi_tables()
            
            # 2.6 Construction Database
            init_results['construction_db'] = _initialize_construction_database_section()
            
            # 2.7 Notification Templates
            _initialize_notification_templates()
            
            # 2.8 Admin Accounts
            init_results['admin_created'] = _initialize_admin_accounts()
            
            # 2.9 Database Migrations
            _run_database_migrations()
            
            # 2.10 Company Structure
            _initialize_company_structure()
            
            # 2.11 Document Tracking
            _initialize_document_tracking()
            
            # 2.12 HSE Document System
            init_results['hse_document_system'] = _initialize_hse_document_system_section()
            
            # 2.13 Thermal Monitoring
            init_results['thermal_monitoring_tables'] = _initialize_thermal_monitoring()
            
            # =========================================================================
            # FINAL VERIFICATION
            # =========================================================================
            _log_phase_header("FINAL CHECK: MODEL REGISTRY AFTER INITIALIZATION")
            thermal_table_count = _perform_final_verification()
            init_results['thermal_monitoring_tables'] = thermal_table_count
            init_results['thermal_monitoring_ready'] = thermal_table_count == 9
        
        # =========================================================================
        # INITIALIZATION COMPLETE
        # =========================================================================
        return _log_initialization_complete(init_results)
        
    except Exception as e:
        return _log_initialization_error(e)


