def _create_industries_table_manually():
    """Manually create industries table and insert default data"""
    from sqlalchemy import text
    
    try:
        with db.engine.connect() as conn:
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS industries (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name VARCHAR(100) NOT NULL UNIQUE,
                    code VARCHAR(50) NOT NULL UNIQUE,
                    description TEXT,
                    risk_level VARCHAR(20) NOT NULL,
                    color_code VARCHAR(7),
                    icon_name VARCHAR(50),
                    is_active BOOLEAN DEFAULT 1,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
                )
            """))
            conn.commit()
        logger.info("      ✅ industries table created manually")
        
        # Insert default industries
        default_industries = [
            ('Construction', 'construction', 'Construction industry', 'HIGH', '#FF6B6B'),
            ('Manufacturing', 'manufacturing', 'Manufacturing industry', 'MEDIUM', '#4ECDC4'),
            ('Oil & Gas', 'oil_gas', 'Oil and gas industry', 'VERY_HIGH', '#FF9F1C'),
            ('Healthcare', 'healthcare', 'Healthcare industry', 'MEDIUM', '#A8E6CF'),
            ('Mining', 'mining', 'Mining industry', 'HIGH', '#FFD93D'),
            ('General', 'general', 'General industry', 'LOW', '#6BCB77')
        ]
        
        for ind in default_industries:
            with db.engine.connect() as conn:
                conn.execute(
                    text("INSERT OR IGNORE INTO industries (name, code, description, risk_level, color_code) VALUES (?, ?, ?, ?, ?)"),
                    ind
                )
                conn.commit()
        logger.info("      ✅ Default industries inserted")
        
    except Exception as manual_err:
        logger.error(f"      ❌ Manual creation failed: {manual_err}")


