def _fix_admin_audit_logs():
    """2.9.1 Fix admin_audit_logs details column"""
    from sqlalchemy import inspect, text
    
    logger.info("\n   🔧 2.9.1 Checking admin_audit_logs table...")
    try:
        inspector = inspect(db.engine)
        
        if 'admin_audit_logs' in inspector.get_table_names():
            columns = [col['name'] for col in inspector.get_columns('admin_audit_logs')]
            
            if 'details' not in columns:
                logger.info("      📝 Adding 'details' column to admin_audit_logs table...")
                with db.engine.connect() as conn:
                    conn.execute(text("ALTER TABLE admin_audit_logs ADD COLUMN details TEXT"))
                    conn.commit()
                logger.info("      ✅ Column 'details' added successfully to admin_audit_logs")
            else:
                logger.info("      ✅ 'details' column already exists in admin_audit_logs")
        else:
            logger.info("      ⚠️ admin_audit_logs table doesn't exist yet - will be created on first use")
    except Exception as e:
        logger.error(f"      ❌ Failed to update admin_audit_logs: {e}")


