def _perform_final_verification():
    """Perform final verification of all models"""
    from sqlalchemy.orm import class_mapper
    from sqlalchemy import inspect
    
    try:
        # Get all mappers again
        mappers_after = list(db.Model.registry.mappers)
        logger.info(f"📊 Total mappers registered: {len(mappers_after)}")
        mapper_names = [mapper.class_.__name__ for mapper in mappers_after]
        logger.info(f"   Registered models: {', '.join(sorted(mapper_names))}")
        
        # Check Industry
        _verify_industry_model()
        
        # Check Incident
        _verify_incident_model()
        
        # Check User and platform owner
        _verify_user_and_platform_owner()
        
        # Check Thermal Monitoring models
        _verify_thermal_models()
        
        # Count thermal tables for return value
        inspector = inspect(db.engine)
        thermal_tables = [
            'thermal_comfort_logs', 'thermal_analysis_results', 'urban_heat_island_records',
            'cooling_requirements', 'heating_requirements', 'thermal_anomalies',
            'thermal_recommendations', 'building_thermal_profiles', 'thermal_sensor_readings'
        ]
        existing_tables = inspector.get_table_names()
        return sum(1 for t in thermal_tables if t in existing_tables)
        
    except Exception as final_error:
        logger.error(f"   ❌ Final check error: {final_error}")
        import traceback
        logger.error(traceback.format_exc())
        return 0


